-- Drop table

-- DROP TABLE con_p_mklmt_projek;

CREATE TABLE con_p_mklmt_projek (
	p_mklmt_projek_id numeric(19) NOT NULL, -- primary key bagi con_p_mklmt_projek
	created_by varchar(80) NOT NULL, -- dicipta oleh
	created_date timestamp NOT NULL, -- tarikh cipta
	last_modified_by varchar(80) NOT NULL, -- nama pengemaskini maklumat
	last_modified_date timestamp NOT NULL, -- tarikh akhir kemaskini maklumat
	"version" numeric(19) NOT NULL, -- versi data dikemaskini
	nama_pemaju varchar(1000) NOT NULL, -- paparan nama pemaju
	nama_projek varchar(1000) NOT NULL, -- paparan nama projek
	nama_pemilik_tnh varchar(500) NULL, -- paparan nama pemilik tanah
	no_rujukan_srt varchar(100) NOT NULL, -- no rujukan surat
	trkh_srt timestamp NULL, -- tarikh surat
	trkh_kelulusan timestamp NULL, -- tarikh kelulusan
	sumber varchar(20) NULL,
	CONSTRAINT pk_cpmp_p_mklmt_projek_id PRIMARY KEY (p_mklmt_projek_id)
);

-- Column comments

COMMENT ON COLUMN et_main_uat.con_p_mklmt_projek.p_mklmt_projek_id IS 'primary key bagi con_p_mklmt_projek';
COMMENT ON COLUMN et_main_uat.con_p_mklmt_projek.created_by IS 'dicipta oleh';
COMMENT ON COLUMN et_main_uat.con_p_mklmt_projek.created_date IS 'tarikh cipta';
COMMENT ON COLUMN et_main_uat.con_p_mklmt_projek.last_modified_by IS 'nama pengemaskini maklumat';
COMMENT ON COLUMN et_main_uat.con_p_mklmt_projek.last_modified_date IS 'tarikh akhir kemaskini maklumat';
COMMENT ON COLUMN et_main_uat.con_p_mklmt_projek."version" IS 'versi data dikemaskini';
COMMENT ON COLUMN et_main_uat.con_p_mklmt_projek.nama_pemaju IS 'paparan nama pemaju';
COMMENT ON COLUMN et_main_uat.con_p_mklmt_projek.nama_projek IS 'paparan nama projek';
COMMENT ON COLUMN et_main_uat.con_p_mklmt_projek.nama_pemilik_tnh IS 'paparan nama pemilik tanah';
COMMENT ON COLUMN et_main_uat.con_p_mklmt_projek.no_rujukan_srt IS 'no rujukan surat';
COMMENT ON COLUMN et_main_uat.con_p_mklmt_projek.trkh_srt IS 'tarikh surat';
COMMENT ON COLUMN et_main_uat.con_p_mklmt_projek.trkh_kelulusan IS 'tarikh kelulusan';


