-- et_main_uat.md_triggers definition

-- Drop table

-- DROP TABLE md_triggers;

CREATE TABLE md_triggers (
	id numeric NOT NULL, -- primary key
	table_or_view_id_fk numeric NOT NULL, -- table on which this trigger fires
	trigger_on_flag bpchar(1) NOT NULL, -- flag to show iif the trigger is on a table or a view.  if it is a table this should be 't'. if it is on a view this should be 'v'
	trigger_name varchar(4000) NULL, -- name of the trigger //objectname
	trigger_timing varchar(4000) NULL, -- before, after ,etc.
	trigger_operation varchar(4000) NULL, -- insert, delete, etc.
	trigger_event varchar(4000) NULL, -- the actual trigger that gets fired 
	native_sql sys."clob" NULL, -- the full definition 
	native_key varchar(4000) NULL, -- uinique identifer for this object at source
	"language" varchar(40) NOT NULL, -- //public
	"comments" varchar(4000) NULL,
	linecount numeric NULL,
	security_group_id numeric DEFAULT 0 NOT NULL,
	created_on timestamp DEFAULT sysdate NOT NULL,
	created_by varchar(255) NULL,
	last_updated_on timestamp NULL,
	last_updated_by varchar(255) NULL,
	CONSTRAINT md_triggers_pk PRIMARY KEY (id)
);
COMMENT ON TABLE et_main_uat.md_triggers IS 'for storing information about triggers.';

-- Column comments

COMMENT ON COLUMN et_main_uat.md_triggers.id IS 'primary key';
COMMENT ON COLUMN et_main_uat.md_triggers.table_or_view_id_fk IS 'table on which this trigger fires';
COMMENT ON COLUMN et_main_uat.md_triggers.trigger_on_flag IS 'flag to show iif the trigger is on a table or a view.  if it is a table this should be ''t''. if it is on a view this should be ''v''';
COMMENT ON COLUMN et_main_uat.md_triggers.trigger_name IS 'name of the trigger //objectname';
COMMENT ON COLUMN et_main_uat.md_triggers.trigger_timing IS 'before, after ,etc.';
COMMENT ON COLUMN et_main_uat.md_triggers.trigger_operation IS 'insert, delete, etc.';
COMMENT ON COLUMN et_main_uat.md_triggers.trigger_event IS 'the actual trigger that gets fired ';
COMMENT ON COLUMN et_main_uat.md_triggers.native_sql IS 'the full definition ';
COMMENT ON COLUMN et_main_uat.md_triggers.native_key IS 'uinique identifer for this object at source';
COMMENT ON COLUMN et_main_uat.md_triggers."language" IS '//public';


