-- et_main_uat.md_applications definition

-- Drop table

-- DROP TABLE md_applications;

CREATE TABLE md_applications (
	id numeric NOT NULL, -- primary key
	"name" varchar(4000) NULL, -- name of the application suite  //objectname
	description varchar(4000) NULL, -- overview of what the application does.
	base_dir varchar(4000) NULL, -- this is the base src directory for the application.  it could be an svn checkout, a clearcase view or something similar
	output_dir varchar(4000) NULL, -- this is the output directory where the scanner will present the converted files, if there are converted or modified.
	backup_dir varchar(4000) NULL, -- this is the directory in which the application files are backed up if a backp is chosen
	inplace numeric NULL, -- designates whether the changes have been made inplace, in the source directory or not
	project_id_fk numeric NOT NULL, -- project of the database(s) this application relates to
	security_group_id numeric DEFAULT 0 NOT NULL,
	created_on timestamp DEFAULT sysdate NOT NULL,
	created_by varchar(255) NULL,
	last_updated_on timestamp NULL,
	last_updated_by varchar(255) NULL,
	CONSTRAINT md_applications_pk PRIMARY KEY (id),
	CONSTRAINT md_app_proj_fk FOREIGN KEY (project_id_fk) REFERENCES md_projects(id) ON DELETE CASCADE
);
COMMENT ON TABLE et_main_uat.md_applications IS 'this is the base table for application projects.  it holds the base information for applications associated with a database';

-- Column comments

COMMENT ON COLUMN et_main_uat.md_applications.id IS 'primary key';
COMMENT ON COLUMN et_main_uat.md_applications."name" IS 'name of the application suite  //objectname';
COMMENT ON COLUMN et_main_uat.md_applications.description IS 'overview of what the application does.';
COMMENT ON COLUMN et_main_uat.md_applications.base_dir IS 'this is the base src directory for the application.  it could be an svn checkout, a clearcase view or something similar';
COMMENT ON COLUMN et_main_uat.md_applications.output_dir IS 'this is the output directory where the scanner will present the converted files, if there are converted or modified.';
COMMENT ON COLUMN et_main_uat.md_applications.backup_dir IS 'this is the directory in which the application files are backed up if a backp is chosen';
COMMENT ON COLUMN et_main_uat.md_applications.inplace IS 'designates whether the changes have been made inplace, in the source directory or not';
COMMENT ON COLUMN et_main_uat.md_applications.project_id_fk IS 'project of the database(s) this application relates to';


-- et_main_uat.md_connections definition

-- Drop table

-- DROP TABLE md_connections;

CREATE TABLE md_connections (
	id numeric NOT NULL, -- primary key
	project_id_fk numeric NOT NULL, -- the project to which this connection belongs //parentfield
	"type" varchar(4000) NULL, -- the type of the connection - for example it could be used to store oracle or mysql
	host varchar(4000) NULL, -- the host to which this connection connects.
	port numeric NULL, -- the port to which this connection connects
	username varchar(4000) NULL, -- the username used to make the connection
	"password" varchar(4000) NULL, -- the password used to make this connection
	dburl varchar(4000) NULL, -- the database url used to make this connection
	"name" varchar(255) NULL, -- //objectname
	native_sql sys."clob" NULL, -- the native sql used to create this connection
	status varchar(30) NULL, -- status of migration, = captured,converted,generated,datamoved
	num_catalogs numeric NULL,
	num_columns numeric NULL,
	num_constraints numeric NULL,
	num_groups numeric NULL,
	num_roles numeric NULL,
	num_indexes numeric NULL,
	num_other_objects numeric NULL,
	num_packages numeric NULL,
	num_privileges numeric NULL,
	num_schemas numeric NULL,
	num_sequences numeric NULL,
	num_stored_programs numeric NULL,
	num_synonyms numeric NULL,
	num_tables numeric NULL,
	num_tablespaces numeric NULL,
	num_triggers numeric NULL,
	num_user_defined_data_types numeric NULL,
	num_users numeric NULL,
	num_views numeric NULL,
	"comments" varchar(4000) NULL,
	security_group_id numeric DEFAULT 0 NOT NULL,
	created_on timestamp DEFAULT sysdate NOT NULL,
	created_by varchar(255) NULL,
	last_updated_on timestamp NULL,
	last_updated_by varchar(255) NULL,
	CONSTRAINT md_connections_pk PRIMARY KEY (id),
	CONSTRAINT md_connections_md_project_fk1 FOREIGN KEY (project_id_fk) REFERENCES md_projects(id) ON DELETE CASCADE
);
COMMENT ON TABLE et_main_uat.md_connections IS 'this table is used to store connection information.  for example, in migrations, we could be carrying out a consolidation which occurs across many connections.';

-- Column comments

COMMENT ON COLUMN et_main_uat.md_connections.id IS 'primary key';
COMMENT ON COLUMN et_main_uat.md_connections.project_id_fk IS 'the project to which this connection belongs //parentfield';
COMMENT ON COLUMN et_main_uat.md_connections."type" IS 'the type of the connection - for example it could be used to store oracle or mysql';
COMMENT ON COLUMN et_main_uat.md_connections.host IS 'the host to which this connection connects.';
COMMENT ON COLUMN et_main_uat.md_connections.port IS 'the port to which this connection connects';
COMMENT ON COLUMN et_main_uat.md_connections.username IS 'the username used to make the connection';
COMMENT ON COLUMN et_main_uat.md_connections."password" IS 'the password used to make this connection';
COMMENT ON COLUMN et_main_uat.md_connections.dburl IS 'the database url used to make this connection';
COMMENT ON COLUMN et_main_uat.md_connections."name" IS '//objectname';
COMMENT ON COLUMN et_main_uat.md_connections.native_sql IS 'the native sql used to create this connection';
COMMENT ON COLUMN et_main_uat.md_connections.status IS 'status of migration, = captured,converted,generated,datamoved';


-- et_main_uat.md_derivatives definition

-- Drop table

-- DROP TABLE md_derivatives;

CREATE TABLE md_derivatives (
	id numeric NOT NULL,
	src_id numeric NOT NULL,
	src_type varchar(4000) NULL,
	derived_id numeric NOT NULL,
	derived_type varchar(4000) NULL,
	derived_connection_id_fk numeric NOT NULL,
	transformed bpchar(1) NULL, -- set this field to 'y' if we carry out any sort of transformation on teh derived object.
	original_identifier varchar(4000) NULL,
	new_identifier varchar(4000) NULL,
	derived_object_namespace varchar(40) NULL,
	derivative_reason varchar(10) NULL,
	security_group_id numeric DEFAULT 0 NOT NULL,
	created_on timestamp DEFAULT sysdate NOT NULL,
	created_by varchar(255) NULL,
	last_updated_on timestamp NULL,
	last_updated_by varchar(255) NULL,
	enabled bpchar(1) DEFAULT 'y'::bpchar NULL,
	CONSTRAINT migrder_chk CHECK (((enabled = 'y'::bpchar) OR (enabled = 'y'::bpchar) OR (enabled = 'n'::bpchar) OR (enabled = 'n'::bpchar))),
	CONSTRAINT migrdreivatives_pk PRIMARY KEY (id),
	CONSTRAINT md_derivatives_md_connect_fk1 FOREIGN KEY (derived_connection_id_fk) REFERENCES md_connections(id) ON DELETE CASCADE
);
CREATE INDEX md_derivatives_perf_idx ON et_main_uat.md_derivatives USING btree (src_id, derived_connection_id_fk);
CREATE INDEX md_derivatives_perf_idx1 ON et_main_uat.md_derivatives USING btree (src_type, derivative_reason);
CREATE INDEX md_derivatives_perf_idx2 ON et_main_uat.md_derivatives USING btree (new_identifier);
CREATE INDEX md_derivatives_perf_idx3 ON et_main_uat.md_derivatives USING btree (original_identifier);
CREATE INDEX md_derivatives_perf_idx4 ON et_main_uat.md_derivatives USING btree (derived_id, derived_type, derived_connection_id_fk);
COMMENT ON TABLE et_main_uat.md_derivatives IS 'this table is used to store objects that are derived from each other.  for example in a migration an auto-increment column in a source model could be mapped to a primary key, and a sequence, and a trigger.  the md_derivatives table would store the fact that these 3 objects are derived from the auto-increment column.';

-- Column comments

COMMENT ON COLUMN et_main_uat.md_derivatives.transformed IS 'set this field to ''y'' if we carry out any sort of transformation on teh derived object.';


