CREATE TABLE md_migr_parameter (
	id numeric NOT NULL,
	connection_id_fk numeric NOT NULL, -- the connection in which this belongs //parentfield
	object_id numeric NOT NULL,
	object_type varchar(4000) NOT NULL,
	param_existing numeric NOT NULL, -- 1 represents a new parameter for pl/sql that was not present in the origional. 0 represents a n existing parameter that was present in the origional
