	"scale" numeric NULL,
	"nullable" bpchar(1) NOT NULL,
	default_value varchar(4000) NULL,
	security_group_id numeric DEFAULT 0 NOT NULL,
	created_on timestamp DEFAULT sysdate NOT NULL,
	created_by varchar(255) NULL,
	last_updated_on timestamp NULL,
	last_updated_by varchar(255) NULL,
	CONSTRAINT migr_parameter_pk PRIMARY KEY (id),
	CONSTRAINT migr_parameter_fk FOREIGN KEY (connection_id_fk) REFERENCES md_connections(id) ON DELETE CASCADE
);

