-- et_main_uat.md_additional_properties definition

-- Drop table

-- DROP TABLE md_additional_properties;

CREATE TABLE md_additional_properties (
	id numeric NOT NULL, -- primary key
	connection_id_fk numeric NOT NULL, -- connection to which this belongs //parentfield
	ref_id_fk numeric NOT NULL, -- the object to which this property blongs
	ref_type varchar(4000) NOT NULL, -- type of object that this property belongs to
	property_order numeric NULL, -- this is to handle a situation where multiple properties have a relevant order, or multiple properties have multiple values
	prop_key varchar(4000) NOT NULL, -- the keyname for this property
	value varchar(4000) NULL, -- the value for this property
	security_group_id numeric DEFAULT 0 NOT NULL,
	created_on timestamp DEFAULT sysdate NOT NULL,
	created_by varchar(255) NULL,
	last_updated_on timestamp NULL,
	last_updated_by varchar(255) NULL,
	CONSTRAINT md_additional_properties_pk PRIMARY KEY (id),
	CONSTRAINT md_additional_properties__fk1 FOREIGN KEY (connection_id_fk) REFERENCES md_connections(id) ON DELETE CASCADE
);
CREATE INDEX md_additional_properties_idx ON et_main_uat.md_additional_properties USING btree (prop_key);
CREATE INDEX md_additional_properties_idx2 ON et_main_uat.md_additional_properties USING btree (ref_id_fk);
COMMENT ON TABLE et_main_uat.md_additional_properties IS 'this table is used to store additional properties in key-value pairs.  it is designed to store "other information" that is not supported in the main database object table.';

-- Column comments

COMMENT ON COLUMN et_main_uat.md_additional_properties.id IS 'primary key';
COMMENT ON COLUMN et_main_uat.md_additional_properties.connection_id_fk IS 'connection to which this belongs //parentfield';
COMMENT ON COLUMN et_main_uat.md_additional_properties.ref_id_fk IS 'the object to which this property blongs';
COMMENT ON COLUMN et_main_uat.md_additional_properties.ref_type IS 'type of object that this property belongs to';
COMMENT ON COLUMN et_main_uat.md_additional_properties.property_order IS 'this is to handle a situation where multiple properties have a relevant order, or multiple properties have multiple values';
COMMENT ON COLUMN et_main_uat.md_additional_properties.prop_key IS 'the keyname for this property';
COMMENT ON COLUMN et_main_uat.md_additional_properties.value IS 'the value for this property';


-- et_main_uat.md_applicationfiles definition

-- Drop table

-- DROP TABLE md_applicationfiles;

CREATE TABLE md_applicationfiles (
	id numeric NOT NULL,
	applications_id_fk numeric NOT NULL,
	"name" varchar(200) NOT NULL, -- file name  //objectname
	uri varchar(4000) NOT NULL, -- the uri is the part of the file url after the base dir has been removed.  see md_application for base dir
	"type" varchar(100) NOT NULL, -- this will denote the type of file we have, including dir, file (text), binary, ignore (where we choose to ignore files)
	state varchar(100) NOT NULL, -- state will be how this file is operated on.  for example. it will be open, new, fixed, ignored, reviewed, complete
	"language" varchar(100) NULL, -- language of the file that has been processed.
	loc numeric NULL,
	security_group_id numeric DEFAULT 0 NOT NULL, -- apex
	created_on timestamp DEFAULT sysdate NOT NULL, -- apex
	created_by varchar(4000) NULL, -- apex
	updated_on timestamp NULL, -- apex
	updated_by varchar(4000) NULL, -- apex
	CONSTRAINT md_applicationfiles_pk PRIMARY KEY (id),
	CONSTRAINT md_file_app_fk FOREIGN KEY (applications_id_fk) REFERENCES md_applications(id) ON DELETE CASCADE
);
CREATE INDEX md_app_file_type_idx ON et_main_uat.md_applicationfiles USING btree (type, id);
CREATE INDEX md_state_type__id ON et_main_uat.md_applicationfiles USING btree (state, type, id);
COMMENT ON TABLE et_main_uat.md_applicationfiles IS 'holds a tuple for each file that is being processed whether it is changed or not.';

-- Column comments

COMMENT ON COLUMN et_main_uat.md_applicationfiles."name" IS 'file name  //objectname';
COMMENT ON COLUMN et_main_uat.md_applicationfiles.uri IS 'the uri is the part of the file url after the base dir has been removed.  see md_application for base dir';
COMMENT ON COLUMN et_main_uat.md_applicationfiles."type" IS 'this will denote the type of file we have, including dir, file (text), binary, ignore (where we choose to ignore files)';
COMMENT ON COLUMN et_main_uat.md_applicationfiles.state IS 'state will be how this file is operated on.  for example. it will be open, new, fixed, ignored, reviewed, complete';
COMMENT ON COLUMN et_main_uat.md_applicationfiles."language" IS 'language of the file that has been processed.';
COMMENT ON COLUMN et_main_uat.md_applicationfiles.security_group_id IS 'apex';
COMMENT ON COLUMN et_main_uat.md_applicationfiles.created_on IS 'apex';
COMMENT ON COLUMN et_main_uat.md_applicationfiles.created_by IS 'apex';
COMMENT ON COLUMN et_main_uat.md_applicationfiles.updated_on IS 'apex';
COMMENT ON COLUMN et_main_uat.md_applicationfiles.updated_by IS 'apex';


-- et_main_uat.md_catalogs definition

-- Drop table

-- DROP TABLE md_catalogs;

CREATE TABLE md_catalogs (
	id numeric NOT NULL,
	connection_id_fk numeric NOT NULL, -- foreign key into the connections table - shows what connection this catalog belongs to //parentfield
	catalog_name varchar(4000) NULL, -- name of the catalog //objectname
	dummy_flag bpchar(1) DEFAULT 'n'::bpchar NULL, -- flag to show if this catalog is a dummy catalog which is used as a placeholder for those platforms that do not support catalogs.  'n' signifies that this is not a dummy catalog, while 'y' signifies that it is.
	native_sql sys."clob" NULL, -- the sql used to create this catalog
	native_key varchar(4000) NULL, -- a unique identifier used to identify the catalog at source.
	"comments" varchar(4000) NULL,
	security_group_id numeric DEFAULT 0 NOT NULL,
	created_on timestamp DEFAULT sysdate NOT NULL,
	created_by varchar(255) NULL,
	last_updated_on timestamp NULL,
	last_updated_by varchar(255) NULL,
	CONSTRAINT md_catalogs_pk PRIMARY KEY (id),
	CONSTRAINT md_catalogs_md_connection_fk1 FOREIGN KEY (connection_id_fk) REFERENCES md_connections(id) ON DELETE CASCADE
);
COMMENT ON TABLE et_main_uat.md_catalogs IS 'store catalogs in this table.';

-- Column comments

COMMENT ON COLUMN et_main_uat.md_catalogs.connection_id_fk IS 'foreign key into the connections table - shows what connection this catalog belongs to //parentfield';
COMMENT ON COLUMN et_main_uat.md_catalogs.catalog_name IS 'name of the catalog //objectname';
COMMENT ON COLUMN et_main_uat.md_catalogs.dummy_flag IS 'flag to show if this catalog is a dummy catalog which is used as a placeholder for those platforms that do not support catalogs.  ''n'' signifies that this is not a dummy catalog, while ''y'' signifies that it is.';
COMMENT ON COLUMN et_main_uat.md_catalogs.native_sql IS 'the sql used to create this catalog';
COMMENT ON COLUMN et_main_uat.md_catalogs.native_key IS 'a unique identifier used to identify the catalog at source.';


-- et_main_uat.md_file_artifacts definition

-- Drop table

-- DROP TABLE md_file_artifacts;

CREATE TABLE md_file_artifacts (
	id numeric NOT NULL,
	applicationfiles_id numeric NOT NULL,
	pattern varchar(4000) NULL, -- pattern used to search source file for interesting artifiacts
	string_found varchar(4000) NULL, -- string found in source from the pattern supplied
	string_replaced varchar(4000) NULL, -- this is the string which replace the string found if it was replaced.
	"type" varchar(200) NULL, -- this is the type of the replacement.  it could be a straight replace from a replacement pattern, or we could have passed the string to a translator which would change the string depending on the database.
	status varchar(4000) NULL, -- pattern used to search source file for interesting artifiacts
	line numeric NULL,
	pattern_start numeric NULL,
	pattern_end numeric NULL,
	due_date timestamp NULL, -- due date is used by the todo mechanism to manage the validation and work to complete this change
	db_type varchar(100) NULL, -- source database calls type
	code_type varchar(1000) NULL, -- source code db api, like dblib, jdbc
	description varchar(4000) NULL, -- this is a description of the artifact which will have a default generated by the scanner and then can be modified by the user to be more appropriate for their use
	priority numeric(38) NULL, -- the priority is set for the todos so they can be managed by the user
	security_group_id varchar(20) DEFAULT '0'::character varying NOT NULL,
	created_on timestamp DEFAULT sysdate NOT NULL,
	created_by varchar(4000) NULL,
	last_updated timestamp NULL,
	last_updated_by varchar(4000) NULL,
	CONSTRAINT md_file_artifacts_pk PRIMARY KEY (id),
	CONSTRAINT md_artifact_file_fk FOREIGN KEY (applicationfiles_id) REFERENCES md_applicationfiles(id) ON DELETE CASCADE
);
COMMENT ON TABLE et_main_uat.md_file_artifacts IS 'holds a tuple for each interesting thing the scanner finds in a file';

-- Column comments

COMMENT ON COLUMN et_main_uat.md_file_artifacts.pattern IS 'pattern used to search source file for interesting artifiacts';
COMMENT ON COLUMN et_main_uat.md_file_artifacts.string_found IS 'string found in source from the pattern supplied';
COMMENT ON COLUMN et_main_uat.md_file_artifacts.string_replaced IS 'this is the string which replace the string found if it was replaced.';
COMMENT ON COLUMN et_main_uat.md_file_artifacts."type" IS 'this is the type of the replacement.  it could be a straight replace from a replacement pattern, or we could have passed the string to a translator which would change the string depending on the database.';
COMMENT ON COLUMN et_main_uat.md_file_artifacts.status IS 'pattern used to search source file for interesting artifiacts';
COMMENT ON COLUMN et_main_uat.md_file_artifacts.due_date IS 'due date is used by the todo mechanism to manage the validation and work to complete this change';
COMMENT ON COLUMN et_main_uat.md_file_artifacts.db_type IS 'source database calls type';
COMMENT ON COLUMN et_main_uat.md_file_artifacts.code_type IS 'source code db api, like dblib, jdbc';
COMMENT ON COLUMN et_main_uat.md_file_artifacts.description IS 'this is a description of the artifact which will have a default generated by the scanner and then can be modified by the user to be more appropriate for their use';
COMMENT ON COLUMN et_main_uat.md_file_artifacts.priority IS 'the priority is set for the todos so they can be managed by the user';


