-- et_main_uat.md_columns definition

-- Drop table

-- DROP TABLE md_columns;

CREATE TABLE md_columns (
	id numeric NOT NULL, -- primary key
	table_id_fk numeric NOT NULL, -- the table that this column is part of //parentfield
	column_name varchar(4000) NOT NULL, -- the name of the column //objectname
	column_order numeric NOT NULL, -- the order this appears in the table
	column_type varchar(4000) NULL, -- the type of the column
	"precision" numeric NULL, -- the precision on the column
	"scale" numeric NULL, -- the scale of the column
	"nullable" bpchar(1) NOT NULL, -- yes or no.  null signifies no
	default_value varchar(4000) NULL, -- default value on the column
	native_sql sys."clob" NULL, -- the sql used to create this column at source
	native_key varchar(4000) NULL, -- unique identifier for this object at source
	datatype_transformed_flag bpchar(1) NULL, -- this is set to 'y' to show if the data type was transformed.  this is useful so we don't apply more than 1 datatype transformation to a column
	"comments" varchar(4000) NULL,
	security_group_id numeric DEFAULT 0 NOT NULL,
	created_by varchar(255) NULL,
	created_on timestamp DEFAULT sysdate NOT NULL,
	last_updated_by varchar(255) NULL,
	last_updated_on timestamp NULL,
	CONSTRAINT md_columns_nullable_y_n CHECK ((upper((nullable)::text) = ANY (ARRAY['y'::text, 'n'::text]))),
	CONSTRAINT md_columns_pk PRIMARY KEY (id),
	CONSTRAINT md_columns_md_tables_fk1 FOREIGN KEY (table_id_fk) REFERENCES md_tables(id) ON DELETE CASCADE
);
CREATE INDEX md_columns_perf_idx ON et_main_uat.md_columns USING btree (table_id_fk, upper(TRIM(BOTH FROM column_name)), id);
COMMENT ON TABLE et_main_uat.md_columns IS 'column information is stored in this table.';

-- Column comments

