COMMENT ON COLUMN et_main_uat.md_columns.column_type IS 'the type of the column';
COMMENT ON COLUMN et_main_uat.md_columns."precision" IS 'the precision on the column';
COMMENT ON COLUMN et_main_uat.md_columns."scale" IS 'the scale of the column';
COMMENT ON COLUMN et_main_uat.md_columns."nullable" IS 'yes or no.  null signifies no';
COMMENT ON COLUMN et_main_uat.md_columns.default_value IS 'default value on the column';
COMMENT ON COLUMN et_main_uat.md_columns.native_sql IS 'the sql used to create this column at source';
COMMENT ON COLUMN et_main_uat.md_columns.native_key IS 'unique identifier for this object at source';
