	"language" varchar(40) NOT NULL, -- //public
	"comments" varchar(4000) NULL,
	security_group_id numeric DEFAULT 0 NOT NULL,
	created_on timestamp DEFAULT sysdate NOT NULL,
	created_by varchar(255) NULL,
	last_updated_on timestamp NULL,
	last_updated_by varchar(255) NULL,
	CONSTRAINT md_constraints_pk PRIMARY KEY (id),
	CONSTRAINT md_constraints_md_tables_fk1 FOREIGN KEY (table_id_fk) REFERENCES md_tables(id) ON DELETE CASCADE
);
COMMENT ON TABLE et_main_uat.md_constraints IS 'table for storing information about a constraint';

-- Column comments

COMMENT ON COLUMN et_main_uat.md_constraints.id IS 'primary key';
COMMENT ON COLUMN et_main_uat.md_constraints.delete_clause IS 'delete option , can be either cascade, restrict or null';
COMMENT ON COLUMN et_main_uat.md_constraints."name" IS 'name of the constraint //objectname';
