-- et_main_uat.md_privileges definition

-- Drop table

-- DROP TABLE md_privileges;

CREATE TABLE md_privileges (
	id numeric NOT NULL, -- primary key
	schema_id_fk numeric NOT NULL, -- the schema to which this object belongs //parentfield
	privilege_name varchar(4000) NOT NULL, -- the name of the privilege //objectname
	privelege_object_id numeric NULL, -- this references the table, view, etc on which the privelege exists.  this can be null for things like system wide privileges
	privelegeobjecttype varchar(4000) NOT NULL, -- the type the privelege is on (e.g. index)
	privelege_type varchar(4000) NOT NULL, -- e.g.select
	admin_option bpchar(1) NULL, -- flag to show if this was granted with admin option.  'y' means it was granted with admin option 'n' means it was not granted with admin option.  null means not applicable (e.g. not known, not supported by source platform, etc.)
	native_sql sys."clob" NOT NULL, -- the sql used to create this privilege at source
	native_key varchar(4000) NULL, -- an identifier for this object at source.
	"comments" varchar(4000) NULL,
	security_group_id numeric DEFAULT 0 NOT NULL,
	created_on timestamp DEFAULT sysdate NOT NULL,
	created_by varchar(255) NULL,
	last_updated_on timestamp NULL,
	last_updated_by varchar(255) NULL,
	CONSTRAINT md_privileges_pk PRIMARY KEY (id),
	CONSTRAINT md_privileges_md_schemas_fk1 FOREIGN KEY (schema_id_fk) REFERENCES md_schemas(id) ON DELETE CASCADE
);
COMMENT ON TABLE et_main_uat.md_privileges IS 'this table stores privilege information';

-- Column comments

COMMENT ON COLUMN et_main_uat.md_privileges.id IS 'primary key';
COMMENT ON COLUMN et_main_uat.md_privileges.schema_id_fk IS 'the schema to which this object belongs //parentfield';
COMMENT ON COLUMN et_main_uat.md_privileges.privilege_name IS 'the name of the privilege //objectname';
COMMENT ON COLUMN et_main_uat.md_privileges.privelege_object_id IS 'this references the table, view, etc on which the privelege exists.  this can be null for things like system wide privileges';
COMMENT ON COLUMN et_main_uat.md_privileges.privelegeobjecttype IS 'the type the privelege is on (e.g. index)';
COMMENT ON COLUMN et_main_uat.md_privileges.privelege_type IS 'e.g.select';
COMMENT ON COLUMN et_main_uat.md_privileges.admin_option IS 'flag to show if this was granted with admin option.  ''y'' means it was granted with admin option ''n'' means it was not granted with admin option.  null means not applicable (e.g. not known, not supported by source platform, etc.)';
COMMENT ON COLUMN et_main_uat.md_privileges.native_sql IS 'the sql used to create this privilege at source';
COMMENT ON COLUMN et_main_uat.md_privileges.native_key IS 'an identifier for this object at source.';


-- et_main_uat.md_stored_programs definition

-- Drop table

-- DROP TABLE md_stored_programs;

CREATE TABLE md_stored_programs (
	id numeric NOT NULL, -- primary key
	schema_id_fk numeric NOT NULL, -- schema to which this object belongs.  note that the package_id_fk (if present also leads us to the relevant schema), however a stored program may or may not belong in a package.  if it is in a package, then the schema_id_fk and the scheme_id_fk in the parent package should match //parentfield
	programtype varchar(20) NULL, -- java/tsql/plsql, etc.
	"name" varchar(4000) NULL, -- name of the stored program //objectname
	package_id_fk numeric NULL, -- the package to which this object belongs
	native_sql sys."clob" NULL, -- the sql used to create this object at source
	native_key varchar(4000) NULL, -- a unique indetifier for this object at source
	"language" varchar(40) NOT NULL, -- //public
	"comments" varchar(4000) NULL,
	linecount numeric NULL,
	security_group_id numeric DEFAULT 0 NOT NULL,
	created_on timestamp DEFAULT sysdate NOT NULL,
	created_by varchar(255) NULL,
	last_updated_on timestamp NULL,
	last_updated_by varchar(255) NULL,
	CONSTRAINT md_stored_programs_pk PRIMARY KEY (id),
	CONSTRAINT md_stored_programs_md_pac_fk1 FOREIGN KEY (package_id_fk) REFERENCES md_packages(id) ON DELETE CASCADE,
	CONSTRAINT md_stored_programs_md_sch_fk1 FOREIGN KEY (schema_id_fk) REFERENCES md_schemas(id) ON DELETE CASCADE
);
CREATE INDEX md_stored_progras_idx2 ON et_main_uat.md_stored_programs USING btree (schema_id_fk, upper((name)::text));
COMMENT ON TABLE et_main_uat.md_stored_programs IS 'container for stored programs.';

-- Column comments

COMMENT ON COLUMN et_main_uat.md_stored_programs.id IS 'primary key';
COMMENT ON COLUMN et_main_uat.md_stored_programs.schema_id_fk IS 'schema to which this object belongs.  note that the package_id_fk (if present also leads us to the relevant schema), however a stored program may or may not belong in a package.  if it is in a package, then the schema_id_fk and the scheme_id_fk in the parent package should match //parentfield';
COMMENT ON COLUMN et_main_uat.md_stored_programs.programtype IS 'java/tsql/plsql, etc.';
COMMENT ON COLUMN et_main_uat.md_stored_programs."name" IS 'name of the stored program //objectname';
COMMENT ON COLUMN et_main_uat.md_stored_programs.package_id_fk IS 'the package to which this object belongs';
COMMENT ON COLUMN et_main_uat.md_stored_programs.native_sql IS 'the sql used to create this object at source';
COMMENT ON COLUMN et_main_uat.md_stored_programs.native_key IS 'a unique indetifier for this object at source';
COMMENT ON COLUMN et_main_uat.md_stored_programs."language" IS '//public';


