-- et_main_uat.md_constraint_details definition

-- Drop table

-- DROP TABLE md_constraint_details;

CREATE TABLE md_constraint_details (
	id numeric NOT NULL, -- primary key
	ref_flag bpchar(1) DEFAULT 'n'::bpchar NULL, -- n or null signify that this column is the colum that is used in the constraint.  a flag of y signifies that the colum is a referenced column (i.e. part of a foreign key constraint)
	constraint_id_fk numeric NOT NULL, -- constraint that this detail belongs to //parentfield
	column_id_fk numeric NULL,
	column_portion numeric NULL, -- the portion of a column this detail belongs (e.g. for constrints on substrings)
	constraint_text sys."clob" NULL, -- the text of the constraint
	detail_order numeric NOT NULL,
	security_group_id numeric DEFAULT 0 NOT NULL,
	created_on timestamp DEFAULT sysdate NOT NULL,
	created_by varchar(255) NULL,
	last_updated_on timestamp NULL,
	last_updated_by varchar(255) NULL,
	CONSTRAINT md_constraint_details_pk PRIMARY KEY (id),
	CONSTRAINT md_constraint_details_md__fk1 FOREIGN KEY (constraint_id_fk) REFERENCES md_constraints(id) ON DELETE CASCADE,
	CONSTRAINT md_constraint_details_md__fk2 FOREIGN KEY (column_id_fk) REFERENCES md_columns(id) ON DELETE CASCADE
);
COMMENT ON TABLE et_main_uat.md_constraint_details IS 'constraint details show what columns are involved in a constraint.';

-- Column comments

COMMENT ON COLUMN et_main_uat.md_constraint_details.id IS 'primary key';
COMMENT ON COLUMN et_main_uat.md_constraint_details.ref_flag IS 'n or null signify that this column is the colum that is used in the constraint.  a flag of y signifies that the colum is a referenced column (i.e. part of a foreign key constraint)';
COMMENT ON COLUMN et_main_uat.md_constraint_details.constraint_id_fk IS 'constraint that this detail belongs to //parentfield';
COMMENT ON COLUMN et_main_uat.md_constraint_details.column_portion IS 'the portion of a column this detail belongs (e.g. for constrints on substrings)';
COMMENT ON COLUMN et_main_uat.md_constraint_details.constraint_text IS 'the text of the constraint';


