	keputusan_dasar varchar(1) NULL,
	keputusan_permohonan varchar(50) NULL,
	trkh_kelulusan timestamp NULL,
	ulasan varchar(500) NULL,
	terima_syarat varchar(1) NULL,
	tempoh_pendudukan numeric(5) NULL,
	unit_tempoh_pendudukan_id numeric(19) NULL,
	trkh_memasuki_tnh timestamp NULL,
	trkh_serahan_balik_tnh timestamp NULL,
	tujuan_projek_eng varchar(1000) NULL,
	tujuan_permohonan varchar(4000) NULL, -- tujuan permohonan
