	trkh_mula_lanjutan timestamp(6) NULL, -- Tarikh Mula Lanjutan
	trkh_tamat_lanjutan timestamp(6) NULL, -- Tarikh Tamat Lanjutan
	CONSTRAINT pk_aap_a_pengambilan_id PRIMARY KEY (a_pengambilan_id),
	CONSTRAINT uk_aap_aplikasi_id UNIQUE (aplikasi_id)
);
