	a_borang_id numeric(19) NOT NULL, -- sebagai primary key bagi dft_a_borang
	created_by varchar(80) NOT NULL, -- dicipta oleh
	created_date timestamp NOT NULL, -- tarikh cipta
	last_modified_by varchar(80) NOT NULL, -- nama pengemaskini maklumat
	last_modified_date timestamp NOT NULL, -- tarikh akhir kemaskini maklumat
	"version" numeric(19) NOT NULL, -- versi data dikemaskini
	aplikasi_id numeric(19) NULL, -- foreign key untuk umm_aplikasi
	hari numeric(10) NULL, -- tempoh hari
	bulan numeric(10) NULL, -- tempoh bulan
	tahun numeric(10) NULL, -- tempoh tahun
	flag_kptgn bpchar(1) DEFAULT 'N'::bpchar NOT NULL, -- adalah syer atau kepentingan(ya/tidak)
	nama_mahkamah varchar(150) NULL, -- nama mahkamah untuk pengisian borang
	trkh_mahkamah timestamp NULL, -- tarikh mahkamah untuk pengisian borang
	no_akta varchar(30) NULL, -- nombor akta bagi pendaftaran yang terlibat untuk pengisian borang
	no_bankrapsi varchar(30) NULL, -- nombor bankrapsi bagi pendaftaran yang terlibat untuk pengisian borang
	no_prnth varchar(200) NULL, -- nombor perintah bagi pendaftaran yang terlibat untuk pengisian borang
	no_petisyen varchar(200) NULL, -- nombor petisyen bagi pendaftaran yang terlibat untuk pengisian borang
	no_rujukan_mahkamah varchar(100) NULL, -- nombor rujukan mahkamah bagi pendaftaran yang terlibat untuk pengisian borang
	no_saman varchar(30) NULL, -- nombor saman bagi pendaftaran yang terlibat untuk pengisian borang
	no_seksyen varchar(30) NULL, -- nombor seksyen bagi pendaftaran yang terlibat untuk pengisian borang
	prnth_oleh varchar(50) NULL, -- pengisian borang atas perintah oleh
	alasan varchar(4000) NULL, -- alasan yang dinyatakan
	sebab_prnth varchar(1000) NULL, -- dinyatakan sebab perintah.data daripada kolum b_sebab dan jadual sptb.borang.
	catatan varchar(2000) NULL, -- maklumat tambahan
	trkh_kuatkuasa timestamp NULL, -- tarikh kuatkuasa borang 
	trkh_luput timestamp NULL, -- tarikh luput borang
	kod_tempoh bpchar(1) NULL,
	kodjms_id numeric(19) NULL,
	CONSTRAINT pk_dabrg_a_borang_id PRIMARY KEY (a_borang_id)
);
CREATE INDEX idx_dabrg_aplikasi_id ON et_main_uat.dft_a_borang USING btree (aplikasi_id);
CREATE INDEX idx_dabrg_kodjms_id ON et_main_uat.dft_a_borang USING btree (kodjms_id);
COMMENT ON TABLE et_main_uat.dft_a_borang IS 'pendaftaran-maklumat urusan transaksi perinci aplikasi bagi borang pendaftaran urusan';

