-- et_main_uat.hsl_cara_bayaran definition

-- Drop table

-- DROP TABLE hsl_cara_bayaran;

CREATE TABLE hsl_cara_bayaran (
	cara_bayaran_id numeric(19) NOT NULL, -- sebagai primary key bagi hsl_cara_byran
	created_by varchar(80) NOT NULL, -- dicipta oleh
	created_date timestamp NOT NULL, -- tarikh cipta
	last_modified_by varchar(80) NOT NULL, -- nama pengemaskini maklumat
	last_modified_date timestamp NOT NULL, -- tarikh akhir kemaskini maklumat
	"version" numeric(19) NOT NULL, -- versi data dikemaskini
	kod_bank_id numeric(19) NULL, -- bank yang digunakan untuk pembayaran.rujukan kepada sak dengan kod sk nama_bank
	kod_cara_bayaran_id numeric(19) NOT NULL, -- cara pembayaran dibuat.rujukan kepada sak dengan kod sk cara_byr
	mod_kemaskini_id numeric(19) NULL, -- foreign key mod kemaskini yang berkaitan dengan transaksi.rujukan kepada sak dengan kod sk mod_kmskni
	status_bayaran_id numeric(19) NULL, -- foreign key status bayaran yang berkaitan dengan transaksi.rujukan kepada sak dengan kod sk stat_byrn_akhir
	no_rujukan varchar(30) NULL, -- nombor rujukan daripada setiap resit cukai
	trkh_rujukan timestamp NULL, -- tarikh semasa bayaran dibuat
	nama_pemegang varchar(150) NULL, -- nama yang tertera di kad yang digunakan semasa pembayaran.
	catatan varchar(100) NULL, -- jika perlu dan sebagai rujukan bukti bagi mana-mana pihak
	cawangan_bank varchar(100) NULL, -- cawangan bank yang dibuat bayaran
	cawangan_luaran varchar(6) NULL, -- cawangan luar bank yang dibuat bayaran
	komisyen numeric(10, 4) NULL, -- keuntungan yang diperoleh daripada setiap pembayar yang membuat pembayaran cukai
	jumlah numeric(12, 2) NOT NULL, -- jumlah pembayaran yang dibuat
	kod_trace varchar(6) NULL, -- rujukan kod yang blh digunakan untuk semakan ataupun carian urusan
	no_mesin_luaran varchar(30) NULL, -- rujukan nombor mesin luar yang digunakan sebagai bukti pembayaran
	operator_luaran varchar(150) NULL, -- wakil pihak luar yang menguruskan penerimaan pembayaran cukai daripada pembayar cukai
	trkh_kemaskini_cek timestamp NULL, -- tarikh dan masa bayar yang disemak semula
	tempat varchar(30) NULL, -- tempat
	pegawai_kemaskini_cek_id numeric(19) NULL, -- pegawai kemaskini
	dm_id_cara_bayar varchar(15) NULL,
	no_akaun varchar(20) NULL, -- Nombor akaun
	CONSTRAINT pk_hcb_cara_byran_id PRIMARY KEY (cara_bayaran_id)
);
CREATE INDEX idx_hcb_kod_bank_id ON et_main_uat.hsl_cara_bayaran USING btree (kod_bank_id);
CREATE INDEX idx_hcb_kod_cara_byr_id ON et_main_uat.hsl_cara_bayaran USING btree (kod_cara_bayaran_id);
CREATE INDEX idx_hcb_last_modified_date ON et_main_uat.hsl_cara_bayaran USING btree (last_modified_date);
CREATE INDEX idx_hcb_mod_kemaskini_id ON et_main_uat.hsl_cara_bayaran USING btree (mod_kemaskini_id);
CREATE INDEX idx_hcb_no_rujukan ON et_main_uat.hsl_cara_bayaran USING btree (no_rujukan);
CREATE INDEX idx_hcb_pegawai_kemaskini_cek_id ON et_main_uat.hsl_cara_bayaran USING btree (pegawai_kemaskini_cek_id);
CREATE INDEX idx_hcb_status_byrn_id ON et_main_uat.hsl_cara_bayaran USING btree (status_bayaran_id);
