-- et_main_uat.ind_hkmlk definition

-- Drop table

-- DROP TABLE ind_hkmlk;

CREATE TABLE ind_hkmlk (
	hkmlk_id numeric(19) NOT NULL, -- primary key bagi ind_hkmlk
	created_by varchar(80) NOT NULL, -- dicipta oleh
	created_date timestamp NOT NULL, -- tarikh cipta
	last_modified_by varchar(80) NOT NULL, -- nama pengemaskini maklumat
	last_modified_date timestamp NOT NULL, -- tarikh akhir kemaskini maklumat
	"version" numeric(19) NOT NULL, -- versi data dikemaskini
	id_hkmlk varchar(70) NOT NULL, -- id hakmilik hakmilik
	no_hkmlk varchar(8) NULL, -- nombor hakmilik hakmilik
	no_bangunan varchar(20) NULL, -- nombor bangunan hakmilik
	no_tingkat varchar(20) NULL, -- nombor tingkat hakmilik
	no_ptk varchar(10) NULL, -- nombor petak hakmilik
	bandar_pekan_mukim_id numeric(19) NOT NULL, -- foreign key untuk ind_bandar_pekan_mukim
	strata_induk_id numeric(19) NULL, -- foreign key untuk ind_hkmlk
	jns_hkmlk_id numeric(19) NULL, -- foreign key untuk rjk_jenis_hkmlk
	upi varchar(35) NULL, -- pengecaman unit tanah hakmilik
	flag_tukarganti bpchar(1) DEFAULT 'N'::bpchar NOT NULL, -- tukar ganti(ya/tidak)
	checkdigit varchar(2) NULL, -- check digit
	hkmlk_pelbagai_id numeric(19) NULL, -- foreign key untuk ind_hkmlk_pelbagai
	flag_hkmlk_bertindih bpchar(1) DEFAULT 'N'::bpchar NULL, -- Hakmilik bertindih (Ya/Tidak)
	CONSTRAINT pk_ih_hkmlk_id PRIMARY KEY (hkmlk_id),
	CONSTRAINT uk_ih_id_hakmilik UNIQUE (id_hkmlk)
);
CREATE INDEX idx_hkmlk_lpad_nohkmlk ON et_main_uat.ind_hkmlk USING btree (lpad((no_hkmlk)::text, 8, '0'::text));
CREATE INDEX idx_hkmlk_upper_id ON et_main_uat.ind_hkmlk USING btree (upper((id_hkmlk)::text));
