CREATE TABLE pks_a_tangkapan (
	a_tangkapan_id numeric(19) NOT NULL, -- sebagai primary key bagi pks_a_tangkapan
	created_by varchar(255) NOT NULL, -- dicipta oleh
	created_date timestamp NOT NULL, -- tarikh cipta
	last_modified_by varchar(255) NOT NULL, -- nama pengemaskini maklumat
	last_modified_date timestamp NOT NULL, -- tarikh akhir kemaskini maklumat
	"version" numeric(19) NOT NULL, -- versi
	a_aduan_id numeric(19) NOT NULL, -- foreign key untuk pks_a_aduan
	trkh_tangkapan timestamp NULL, -- tarikh tangkapan
	no_laporan_polis varchar(3000) NULL, -- nombor laporan polis
	tujuan_laporan varchar(3000) NULL, -- tujuan laporan
	flag_berjaya bpchar(1) DEFAULT 'N'::bpchar NOT NULL, -- berjaya(ya/tidak)
	ulasan varchar(3000) NULL, -- ulasan
	barang_rampasan varchar(4000) NULL, -- BARANG RAMPASAN
	trkh_terima_kunci timestamp NULL, -- tarikh OKT menerima kunci lori
	no_enjin varchar(50) NULL, -- no. enjin
	no_chasis varchar(50) NULL, -- no. chasis
	no_kenderaan varchar(50) NULL, -- no. kenderaan yang ditahan
	jenis_kenderaan varchar(50) NULL, -- jenis kenderaan
	warna_kenderaan varchar(50) NULL, -- warna kenderaan
	no_siri varchar(50) NULL, -- no. siri lori/jentera rampasan
	tempat_barang_rampasan varchar(3000) NULL, -- tempat lori/jentera rampasan disimpan
	jumlah_jaminan numeric(19, 2) NULL, -- jumlah jaminan (rampasan)
	nama_penjamin_1 varchar(255) NULL, -- nama penjamin pertama
	no_pengenalan_penjamin_1 varchar(50) NULL, -- no. pengenalan penjamin pertama
	alamat_penjamin_1 varchar(500) NULL, -- alamat penjamin pertama
	nama_penjamin_2 varchar(255) NULL, -- nama penjamin kedua
	no_pengenalan_penjamin_2 varchar(50) NULL, -- no. pengenalan penjamin kedua
	alamat_penjamin_2 varchar(500) NULL, -- alamat penjamin kedua
	jenis_kamera varchar(50) NULL, -- jenis kamera untuk dokumen perakuan seksyen 90A (2)
	model_kamera varchar(50) NULL, -- model_kamera untuk dokumen perakuan seksyen 90A (2)
	tarikh_menyerah timestamp NULL, -- tarikh dan masa menyerah barang kes
	no_lpop varchar(50) NULL, -- no. LPOP untuk borang bongkar
	no_waran_bongkar varchar(50) NULL, -- no. waran bongkar
	nama_pemilik_bongkar varchar(255) NULL, -- nama pemilik/pemandu yang hadir bongkaran
	nama_pegawai_bongkar varchar(255) NULL, -- nama pegawai/polis yang hadir bongkaran
	no_kad_kuasa varchar(50) NULL, -- no. kad kuasa
	tarikh_bongkaran timestamp NULL, -- tarikh dan masa bongkaran
	tempat_bongkaran varchar(500) NULL, -- tempat bongkaran
	penerima_notis_sita varchar(500) NULL, -- penerima notis sita
	no_siri_notis_sita varchar(50) NULL, -- no. siri notis sita
	tarikh_sita timestamp NULL, -- tarikh sita
	jenis_kesalahan varchar(500) NULL, -- jenis kesalahan untuk notis kesalahan 426AKTN
	tempat_tangkapan varchar(3000) NULL, -- tempat tangkapan
	mukim_tangkapan varchar(50) NULL, -- mukim tangkapan
	peralatan_digunakan varchar(3000) NULL, -- peralatan/kenderaan yang digunakan
	pemandu_kenderaan varchar(255) NULL, -- pemandu kenderaan
	pemilik_kenderaan varchar(255) NULL, -- pemilik kenderaan
	jenis_bahan_batuan varchar(255) NULL, -- jenis bahan batuan
	tempat_diambil varchar(500) NULL, -- tempat bahan batuan diambil
	tempat_dihantar varchar(500) NULL, -- tempat bahan batuan dihantar
	pemegang_permit varchar(255) NULL, -- nama dan alamat pemegang permit
	lain_lain varchar(3000) NULL, -- lain-lain maklumat pemegang permit
	pnrm_brg_kerja_luar varchar(255) NULL, -- penerima borang kerja luar
	masa_keluar varchar(5) NULL, -- masa keluar
	dijangka_balik timestamp NULL, -- tarikh dan masa dijangka balik
	CONSTRAINT pks_a_tangkapan_pkey PRIMARY KEY (a_tangkapan_id)
);
CREATE INDEX idx_pat_a_aduan_id ON et_main_uat.pks_a_tangkapan USING btree (a_aduan_id);
