	alamat_emel_sln varchar(255) NULL, -- alamat emel salinan bagi dokumen keluaran
	a_perisytiharan_jualan_id numeric(19) NULL, -- foreign key untuk llg_a_perisytiharan_jualan
	flag_kutipan bpchar(1) DEFAULT 'N'::bpchar NOT NULL, -- kutipan(ya/tidak)
