	status_penyampaian_notis_id numeric(19) NULL, -- foreign key untuk umm_status_penyampaian_notis
	a_kertas_siasatan_id numeric(19) NULL, -- foreign key untuk pks_a_kertas_siasatan
	a_notis_pemberitahuan_id numeric(19) NULL, -- foreign key untuk pks_a_notis_pemberitahuan
	status_rahsia_id numeric(19) NULL, -- Status Rahsia (Peringkat Keselamatan Dokumen Rahsia Rasmi)
	CONSTRAINT pk_uadokklrn_a_dok_keluaran_id PRIMARY KEY (a_dok_keluaran_id)
);
