	no_permit varchar(50) NULL, -- nombor permit.keterangan terperinci dan tujuan pada jadual untuk permohonan gantian sijil dan permit bahagian strata
	no_sijil varchar(50) NULL, -- nombor sijil.keterangan terperinci dan tujuan pada jadual untuk permohonan gantian sijil dan permit bahagian strata
