CREATE TABLE umm_a_hkmlk_lain (
	a_hkmlk_lain_id numeric(19) NOT NULL, -- primary key bagi umm_a_hakmilik_lain
	created_by varchar(80) NOT NULL, -- dicipta oleh
	created_date timestamp NOT NULL, -- tarikh cipta
	last_modified_by varchar(80) NOT NULL, -- nama pengemaskini maklumat
	last_modified_date timestamp NOT NULL, -- tarikh akhir kemaskini maklumat
	"version" numeric(19) NOT NULL, -- versi data dikemaskini
	a_pihak_bkptg_id numeric(19) NULL, -- foreign key untuk umm_a_pihak_bkptg
	cara_pemilikan_id numeric(19) NULL, -- rujukan kepada sak dengan kod sk plp_beli_beri_krj
	jns_hkmlk_id numeric(19) NULL, -- rujukan kepada sak dengan kod sk plp_jns_hkmlk
	kegunaan_tnh_id numeric(19) NULL, -- rujukan kepada sak dengan kod sk "plp_btr_kls_tanah"
	flag_dalam_borang bpchar(1) DEFAULT 'N'::bpchar NOT NULL, -- dalam borang(ya/tidak)
	daerah varchar(50) NULL, -- daerah bagi hakmilik lain
	bandar varchar(50) NULL, -- bandar bagi hakmilik lain
	negeri_id numeric(19) NULL, -- rujukan kepada sak dengan kod sk negeri
	no_geran varchar(50) NULL, -- nombor geran bagi hakmilik lain
	no_hkmlk varchar(50) NULL, -- nombor hakmilik bagi hakmilik lain
	no_lot varchar(30) NULL, -- nombor lot bagi hakmilik lain
	unit_luas_id numeric(19) NULL, -- rujukan kepada sak dengan kod sk unit_luas
	keluasan numeric(19, 4) NULL, -- keluasan bagi hakmilik lain
	trkh_memiliki timestamp NULL, -- tarikh memiliki bagi hakmilik lain
	trkh_kelulusan_dan_bayaran timestamp NULL, -- tarikh kelulusan dan bayaran
	id_hakmilik varchar(100) NULL, -- id hakmilik
	kegunaan_tnh_str varchar(1000) NULL, -- kegunaan tanah
	mklmt_tmbhn sys."clob" NULL, -- maklumat tambahan
	CONSTRAINT pk_uahmlkln_a_hakmilik_lain_id PRIMARY KEY (a_hkmlk_lain_id)
);
CREATE INDEX idx_uahmlkln_a_pihak_bkptg_id ON et_main_uat.umm_a_hkmlk_lain USING btree (a_pihak_bkptg_id);
