CREATE INDEX idx_uahmlkln_negeri_id ON et_main_uat.umm_a_hkmlk_lain USING btree (negeri_id);
CREATE INDEX idx_uahmlkln_unit_luas_id ON et_main_uat.umm_a_hkmlk_lain USING btree (unit_luas_id);
