	p_daftar_organisasi_id numeric(19) NOT NULL, -- primary key bagi umm_p_daftar_organisasi 
	created_by varchar(80) NOT NULL, -- dicipta oleh
	created_date timestamp NOT NULL, -- tarikh cipta 
	last_modified_by varchar(80) NOT NULL, -- nama pengemaskini maklumat 
	last_modified_date timestamp NOT NULL, -- tarikh akhir kemaskini maklumat 
	"version" numeric(19) NOT NULL, -- versi data dikemaskini
	p_aplikasi_id numeric(19) NULL, -- foreign key untuk umm_p_pihak_bkptg
	jns_akaun_id numeric(19) NULL, -- rujukan kepada sak dengan kod sk akaun_pengguna
	pengguna_wkl_id numeric(19) NULL, -- foreign key untuk umm_p_daftar_organisasi
	pengesahan_biometrik_id numeric(19) NULL, -- foreign key untuk pcp_pengesahan_biometrik
	status_id numeric(19) NULL, -- rujukan kepada sak dengan kod sk stat_stemduti
	nama varchar(150) NULL, -- nama bagi daftar organisasi
	nama_pengguna varchar(50) NULL, -- nama pengguna bagi daftar organisasi
	jns_no_id numeric(19) NULL, -- rujukan kepada sak dengan kod sk jenis_nop
	no_kp varchar(50) NULL, -- nombor kad pengenalan bagi daftar organisasi
	alamat varchar(80) NULL, -- alamat surat menyurat bagi daftar organisasi
	alamat2 varchar(80) NULL, -- alamat2 surat menyurat bagi daftar organisasi
	alamat3 varchar(80) NULL, -- alamat3 surat menyurat bagi daftar organisasi
	alamat4 varchar(80) NULL, -- alamat4 surat menyurat bagi daftar organisasi
	poskod varchar(10) NULL, -- poskod surat menyurat bagi daftar organisasi
	bandar_id numeric(19) NULL, -- rujukan kepada sak dengan kod sk bandar
	bandar_lain varchar(50) NULL, -- selain bandar lain daripada senarai sak
	negeri_id numeric(19) NULL, -- rujukan kepada sak dengan kod sk negeri
	alamat_daftar1 varchar(80) NULL, -- alamat daftar1 bagi daftar organisasi
	alamat_daftar2 varchar(80) NULL, -- alamat daftar2 bagi daftar organisasi
	alamat_daftar3 varchar(80) NULL, -- alamat daftar3 bagi daftar organisasi
	alamat_daftar4 varchar(80) NULL, -- alamat daftar4 bagi daftar organisasi
	poskod_daftar varchar(10) NULL, -- poskod daftar bagi daftar organisasi
	bandar_daftar_id numeric(19) NULL, -- rujukan kepada sak dengan kod sk bandar
	bandar_daftar_lain varchar(50) NULL, -- selain bandar daftar lain daripada senarai sak
	negeri_daftar_id numeric(19) NULL, -- rujukan kepada sak dengan kod sk negeri
	negara_berdaftar_id numeric(19) NULL, -- foreign key untuk umm_p_pihak_bkptg
	negara_srt_menyurat_id numeric(19) NULL, -- rujukan kepada sak dengan kod sk negara
	emel varchar(50) NULL, -- emel bagi daftar organisasi
	no_tel varchar(15) NULL, -- nombor telefon bagi daftar organisasi
	no_tel2 varchar(15) NULL, -- nombor telefon2 bagi daftar organisasi
	no_tel_bimbit varchar(15) NULL, -- nombor telefon bimbit bagi daftar organisasi
	no_tel_faks varchar(15) NULL, -- nombor telefaks bagi daftar organisasi
	no_tel_pejabat varchar(15) NULL, -- nombor telefon pejabat bagi daftar organisasi
	warganegara_id numeric(19) NULL, -- rujukan kepada sak dengan kod sk warganegara
	no_lesen varchar(30) NULL, -- nombor lesen bagi daftar organisasi
	sambungan varchar(10) NULL, -- nombor sambungan nombor telefon bagi daftar organisasi
	ulasan varchar(500) NULL, -- ulasan bagi daftar organisasi
	soalan_keselamatan_1_id numeric(19) NULL, -- rujukan kepada sak dengan kod sk soalan_keselamatan_pengguna
	soalan_keselamatan_2_id numeric(19) NULL, -- rujukan kepada sak dengan kod sk soalan_keselamatan_pengguna
	jawapan_soalan_keselamatan_1 varchar(255) NULL, -- jawapan soalan keselamatan 1 bagi daftar organisasi
	jawapan_soalan_keselamatan_2 varchar(255) NULL, -- jawapan soalan keselamatan 2 bagi daftar organisasi
	cawangan varchar(50) NULL, -- cawangan bagi daftar organisasi
	emel_notifikasi varchar(50) NULL, -- emel notifikasi
	flag_aktif bpchar(1) DEFAULT 'Y'::bpchar NOT NULL, -- aktif (ya/tidak)
	modul_id numeric(19) NULL, -- foreign key untuk ind_modul
	pejabat_id numeric(19) NULL, -- foreign key untuk ind_pejabat
	trkh_tamat_lesen timestamp NULL,
	flag_jmb_dan_mc bpchar(1) DEFAULT 'n'::bpchar NULL, -- Adalah JMB dan MC (Ya/Tidak)
	CONSTRAINT pk_updo_p_daftar_organisasi_id PRIMARY KEY (p_daftar_organisasi_id),
	CONSTRAINT uk_updo_p_aplikasi_id UNIQUE (p_aplikasi_id)
);
