CREATE TABLE umm_p_hkmlk (
	p_hkmlk_id numeric(19) NOT NULL, -- primary key bagi umm_p_hkmlk 
	created_by varchar(80) NOT NULL, -- dicipta oleh
	created_date timestamp NOT NULL, -- tarikh cipta 
	last_modified_by varchar(80) NOT NULL, -- nama pengemaskini maklumat
	last_modified_date timestamp NOT NULL, -- tarikh akhir kemaskini maklumat 
	"version" numeric(19) NOT NULL, -- versi data dikemaskini
	p_aplikasi_id numeric(19) NULL, -- foreign key untuk spc_p_aplikasi
	versi_dhd_id numeric(19) NULL, -- foreign key untuk ind_versi_dhd.dokumen disimpan oleh ptg
	hkmlk_id numeric(19) NULL, -- foreign key untuk ind_hkmlk
	seksyen_id numeric(19) NULL, -- foreign key untuk ind_seksyen
	bandar_dipohon_id numeric(19) NULL, -- foreign key untuk ind_bandar_pekan_mukim
	kat_id numeric(19) NULL, -- rujukan kepada sak dengan kod sk kat_tanah
	status_tnh_id numeric(19) NULL, -- rujukan kepada sak dengan kod sk str_kat_tanah
	jns_rujukan_lokasi_id numeric(19) NULL, -- rujukan kepada sak dengan kod sk plp_jns_rjk_lokasi
	no_rujukan_lokasi varchar(30) NULL, -- nombor rujukan lokasi bagi hakmilik
	lokasi varchar(255) NULL, -- lokasi bagi hakmilik
	flag_hkmlk_strata_pukal bpchar(1) DEFAULT 'N'::bpchar NULL, -- hakmilik strata pukal(ya/tidak)
	bil_sln numeric(2) NULL, -- bilangan salinan bagi hakmilik
	harga_jualan numeric(19, 2) NULL, -- harga jualan bagi hakmilik
	unit_lot_id numeric(19) NULL, -- rujukan kepada sak dengan kod sk unitlt
	unit_luas_id numeric(19) NULL, -- rujukan kepada sak dengan kod sk unit_luas
	unit_luas_terlibat_id numeric(19) NULL, -- rujukan kepada sak dengan kod sk unit_luas
	luas numeric(16, 4) NULL, -- luas bagi hakmilik
	luas_terlibat numeric(16, 4) NULL, -- luas terlibat bagi hakmilik
	no_lot varchar(30) NULL, -- nombor lot bagi hakmilik
	no_pelan varchar(50) NULL, -- nombor pelan bagi hakmilik
	no_ptk varchar(10) NULL, -- nombor petak bagi hakmilik
	trkh_instrumen_disetem timestamp NULL, -- tarikh instrumen disetem bagi hakmilik
	trkh_perjanjian_jual_beli timestamp NULL, -- tarikh perjanjian jual beli bagi hakmilik
	tempoh_pajakan numeric(10) NULL, -- tempoh pajakan bagi hakmilik
	jarak_bandar varchar(100) NULL, -- jarak bandar bagi hakmilik
	jarak_jalan_keretapi varchar(100) NULL, -- jarak jalan keretapi bagi hakmilik
	jarak_jalan_raya varchar(100) NULL, -- jarak jalan raya bagi hakmilik
	jarak_sungai varchar(100) NULL, -- jarak sungai bagi hakmilik
	keterangan_lain varchar(255) NULL, -- keterangan lain bagi hakmilik
	kat_permohonan_id numeric(19) NULL, -- rujukan kepada sak dengan kod sk str_jns_mohon_ganti.keterangan terperinci dan tujuan pada jadual untuk permohonan gantian sijil dan permit bahagian strata
	no_permit varchar(50) NULL, -- nombor permit.keterangan terperinci dan tujuan pada jadual untuk permohonan gantian sijil dan permit bahagian strata
	no_sijil varchar(50) NULL, -- nombor sijil.keterangan terperinci dan tujuan pada jadual untuk permohonan gantian sijil dan permit bahagian strata
	alamat varchar(80) NULL, -- alamat
	alamat2 varchar(80) NULL, -- alamat 2
	alamat3 varchar(80) NULL, -- alamat 3
	alamat4 varchar(80) NULL, -- alamat 4
	poskod varchar(10) NULL, -- poskod
	bandar_id numeric(19) NULL, -- rujukan kepada sak dengan kod sk bandar
	bandar_lain varchar(50) NULL, -- bandar lain
	negeri_id numeric(19) NULL, -- rujukan kepada sak dengan kod sk negeri
	trkh_warta timestamp NULL, -- tarikh warta
	keterangan_tapak varchar(150) NULL, -- keterangan tapak bagi hakmilik
	tujuan_berimilik_lain varchar(100) NULL, -- tujuan bermilik lain
	tujuan_berimilik_id numeric(19) NULL, -- rujukan kepada sak dengan kod sk "-"
	mklmt_tmbhn varchar(4000) NULL, -- maklumat tambahan
	pengambilan_segera varchar(1) NULL, -- pengalaman segera
	bahagian_pengambilan_id numeric(19) NULL, -- rujukan kepada sak dengan kod sk plp_bhg_tlbt
	nama_rancangan varchar(50) NULL, -- nama rancangan
	no_siri varchar(15) NULL, -- nombor siri
	agensi_id numeric(19) NULL, -- foreign key untuk rjk_agensi
	no_warta varchar(50) NULL, -- nombor warta
	kawasan_rizab varchar(50) NULL, -- kawasan rizab
	jns_tarik_balik_id numeric(19) NULL, -- rujukan kepada sak dengan kod sk amb_jtb
	luas_permohonan_asal numeric(16, 4) NULL, -- luas permohonan asal
	unit_luas_permohonan_asal_id numeric(19) NULL, -- rujukan kepada sak dengan kod sk unit_luas
	baki_kepada_plot varchar(10) NULL,
	flag_plot_ambil bpchar(1) DEFAULT 'N'::bpchar NOT NULL,
	tanah_rizab_melayu varchar(1) NULL,
	luas_diperlukan numeric(16, 4) NULL,
	unit_luas_diperlukan_id numeric(19) NULL,
	flag_tanah_haram bpchar(1) DEFAULT 'N'::bpchar NULL, -- Flag hakmilik adalah tanah haram
	CONSTRAINT pk_uphkmlk_p_hkmlk_id PRIMARY KEY (p_hkmlk_id)
);
