);
CREATE INDEX idx_uun_hantaran_notis_id ON et_main_uat.umm_ulasan_notis USING btree (hantaran_notis_id);
CREATE INDEX idx_uun_oleh_id ON et_main_uat.umm_ulasan_notis USING btree (oleh_id);
