COMMENT ON COLUMN et_main_uat.umm_ulasan_notis.oleh_id IS 'foreign key untuk pcp_pengguna';
COMMENT ON COLUMN et_main_uat.umm_ulasan_notis.perihal IS 'perihal bagi ulasan notis';
