-- et_main_uat.gis_hm source

CREATE OR REPLACE VIEW gis_hm
AS SELECT ( SELECT a_1.nama
           FROM rjk_senarai_ahli_kumpulan a_1,
            rjk_senarai_kumpulan b_1
          WHERE a_1.senarai_kumpulan_id = b_1.senarai_kumpulan_id AND b_1.kod::text = 'STAT_HMILIK'::text AND a_1.senarai_ahli_kumpulan_id = c.status_hkmlk_id) AS status_hakmilik,
    c.status_hkmlk_id,
    c.trkh_daftar,
    a.jns_hkmlk_id,
    ( SELECT rjk_jns_hkmlk.kod
           FROM rjk_jns_hkmlk
          WHERE a.jns_hkmlk_id = rjk_jns_hkmlk.jns_hkmlk_id) AS jenis_hakmilik,
    a.id_hkmlk,
    a.no_hkmlk,
    substr(a.id_hkmlk::text, 1::numeric, 2::numeric) AS neg,
    substr(a.id_hkmlk::text, 3::numeric, 2::numeric) AS dae,
    substr(a.id_hkmlk::text, 5::numeric, 2::numeric) AS muk,
    ( SELECT a_1.nama
           FROM rjk_senarai_ahli_kumpulan a_1,
            rjk_senarai_kumpulan b_1
          WHERE a_1.senarai_kumpulan_id = b_1.senarai_kumpulan_id AND b_1.kod::text = 'UNITLT'::text AND a_1.senarai_ahli_kumpulan_id = c.unit_lot_id) AS unit_lot,
    c.unit_lot_id,
    c.no_lot,
    ( SELECT rjk_senarai_ahli_kumpulan.nama
           FROM rjk_senarai_ahli_kumpulan
          WHERE rjk_senarai_ahli_kumpulan.senarai_ahli_kumpulan_id = c.unit_luas_id) AS uluas,
    c.luas,
    c.no_helaian,
    d.no_pelan,
    c.kat_id,
    ( SELECT rjk_senarai_ahli_kumpulan.nama
           FROM rjk_senarai_ahli_kumpulan
          WHERE rjk_senarai_ahli_kumpulan.senarai_ahli_kumpulan_id = c.kat_id) AS katagori_tanah,
    ( SELECT rjk_senarai_ahli_kumpulan.nama
           FROM rjk_senarai_ahli_kumpulan
          WHERE rjk_senarai_ahli_kumpulan.senarai_ahli_kumpulan_id = f.status_tnh_id) AS status_tanah_rizab,
    f.flag_kuota_bumi,
    c.syrt_nyata_id,
    e.kod,
    e.perihal
   FROM ind_hkmlk a,
    ind_versi_dhd b,
    ind_mklmt_hkmlk c,
    ind_pelan d,
    ind_syrt_nyata e,
    ind_hkmlk_pelbagai f
  WHERE a.hkmlk_id = b.hkmlk_id AND b.mklmt_hkmlk_id = c.mklmt_hkmlk_id AND a.hkmlk_id = d.hkmlk_id AND c.syrt_nyata_id = e.syrt_nyata_id AND a.hkmlk_pelbagai_id = f.hkmlk_pelbagai_id;


