    ind_syrt_nyata e,
    ind_hkmlk_pelbagai f
  WHERE a.hkmlk_id = b.hkmlk_id AND b.mklmt_hkmlk_id = c.mklmt_hkmlk_id AND a.hkmlk_id = d.hkmlk_id AND c.syrt_nyata_id = e.syrt_nyata_id AND a.hkmlk_pelbagai_id = f.hkmlk_pelbagai_id;


-- et_main_uat.md_regex_catalog_mview source

CREATE MATERIALIZED VIEW md_regex_catalog_mview
TABLESPACE pg_default
AS SELECT project_id,
    connection_id,
    connection_name,
    catalog_id,
    catalog_name,
    item,
    sum(value) AS value
   FROM md_regex_schema_mview
  GROUP BY project_id, connection_id, connection_name, catalog_id, catalog_name, item
WITH DATA;

COMMENT ON MATERIALIZED VIEW et_main_uat.md_regex_catalog_mview IS 'snapshot table for snapshot et_main_mig.md_regex_catalog_mview';


-- et_main_uat.md_regex_mview source

CREATE MATERIALIZED VIEW md_regex_mview
TABLESPACE pg_default
AS SELECT pr.project_name,
    pr.id AS project_id,
    c.id AS connection_id,
    c.name AS connection_name,
    mc.id AS catalog_id,
    mc.catalog_name,
    s.id AS schema_id,
    s.name AS schema_name,
    p.id AS program_id,
    p.name AS program_name,
    rg.description AS item,
    regexp_count(p.native_sql::text, rg.regex::text, 1::numeric, 'ix'::text) AS value
   FROM md_stored_programs p,
    md_projects pr,
    md_connections c,
    md_schemas s,
    md_catalogs mc,
    md_code_regex rg
  WHERE c.type IS NULL AND mc.connection_id_fk = c.id AND mc.id = s.catalog_id_fk AND pr.project_name::text ~~ 'ss%'::text AND pr.id = c.project_id_fk AND p.schema_id_fk = s.id AND regexp_count(p.native_sql::text, rg.regex::text, 1::numeric, 'ix'::text) > 0
WITH DATA;

COMMENT ON MATERIALIZED VIEW et_main_uat.md_regex_mview IS 'snapshot table for snapshot et_main_mig.md_regex_mview';


-- et_main_uat.md_regex_schema_mview source

CREATE MATERIALIZED VIEW md_regex_schema_mview
TABLESPACE pg_default
AS SELECT project_id,
    connection_id,
    connection_name,
    catalog_id,
    catalog_name,
    schema_id,
    schema_name,
    item,
    sum(value) AS value
   FROM md_regex_mview
  GROUP BY project_name, project_id, connection_id, connection_name, catalog_id, catalog_name, schema_id, schema_name, item
WITH DATA;

COMMENT ON MATERIALIZED VIEW et_main_uat.md_regex_schema_mview IS 'snapshot table for snapshot et_main_mig.md_regex_schema_mview';


-- et_main_uat.mgv_all_captured_sql source

CREATE OR REPLACE VIEW mgv_all_captured_sql
AS SELECT d.objtype,
    d.objname,
    d.objid,
    d.mainobjtype,
    d.mainobjname,
    d.mainobjid,
    d.schemaname,
    d.schemaid,
    d.catalogname,
    d.catalogid,
    d.connname,
    d.connid,
    d.projectname,
    d.projectid,
    d.capturedorconverted,
    d.qualifiedname,
    p.native_sql,
    p.linecount
   FROM md_stored_programs p,
    mgv_all_programs_details d
  WHERE p.id = d.objid AND d.capturedorconverted::text = 'captured'::text
UNION ALL
 SELECT d.objtype,
    d.objname,
    d.objid,
    d.mainobjtype,
    d.mainobjname,
    d.mainobjid,
    d.schemaname,
    d.schemaid,
    d.catalogname,
    d.catalogid,
    d.connname,
    d.connid,
    d.projectname,
    d.projectid,
    d.capturedorconverted,
    d.qualifiedname,
    v.native_sql,
    v.linecount
   FROM md_views v,
    mgv_all_view_details d
  WHERE v.id = d.objid AND d.capturedorconverted::text = 'captured'::text
UNION ALL
 SELECT d.objtype,
    d.objname,
    d.objid,
    d.mainobjtype,
    d.mainobjname,
    d.mainobjid,
    d.schemaname,
    d.schemaid,
    d.catalogname,
    d.catalogid,
    d.connname,
    d.connid,
    d.projectname,
    d.projectid,
    d.capturedorconverted,
    d.qualifiedname,
    t.native_sql,
    t.linecount
   FROM md_triggers t,
    mgv_all_trigger_details d
  WHERE t.id = d.objid AND d.capturedorconverted::text = 'captured'::text;


-- et_main_uat.mgv_all_catalog_details source

CREATE OR REPLACE VIEW mgv_all_catalog_details
AS SELECT 'md_catalogs'::text AS objtype,
    cat.catalog_name AS objname,
    cat.id AS objid,
    'md_catalogs'::text AS mainobjtype,
    cat.catalog_name AS mainobjname,
    cat.id AS mainobjid,
    NULL::text AS schemaname,
    NULL::text AS schemaid,
    cat.catalog_name AS catalogname,
    cat.id AS catalogid,
    conn.name AS connname,
    conn.id AS connid,
    proj.project_name AS projectname,
    proj.id AS projectid,
    nvl(conn.type, 'captured'::character varying) AS capturedorconverted,
        CASE
            WHEN conn.type IS NULL THEN cat.catalog_name
            ELSE NULL::character varying
        END AS qualifiedname
   FROM md_catalogs cat,
    md_connections conn,
    md_projects proj
  WHERE cat.connection_id_fk = conn.id AND conn.project_id_fk = proj.id;


