CREATE OR REPLACE VIEW mgv_all_column_details
AS SELECT 'md_columns'::text AS objtype,
    c.column_name AS objname,
    c.id AS objid,
    'md_tables'::text AS mainobjtype,
    t.table_name AS mainobjname,
    t.id AS mainobjid,
    s.name AS schemaname,
    s.id AS schemaid,
    cat.catalog_name AS catalogname,
    cat.id AS catalogid,
    conn.name AS connname,
    conn.id AS connid,
    proj.project_name AS projectname,
    proj.id AS projectid,
    nvl(conn.type, 'captured'::character varying) AS capturedorconverted,
    ((((
        CASE
            WHEN conn.type IS NULL THEN cat.catalog_name::text || '.'::text
            ELSE ''::text
        END || s.name::text) || '.'::text) || t.table_name::text) || '.'::text) || c.column_name::text AS qualifiedname
   FROM md_columns c,
    md_tables t,
    md_schemas s,
    md_catalogs cat,
    md_connections conn,
    md_projects proj
  WHERE c.table_id_fk = t.id AND t.schema_id_fk = s.id AND s.catalog_id_fk = cat.id AND cat.connection_id_fk = conn.id AND conn.project_id_fk = proj.id;


-- et_main_uat.mgv_all_columndt_details source

CREATE OR REPLACE VIEW mgv_all_columndt_details
AS SELECT 'md_columns'::text AS objtype,
    c.column_name AS objname,
    c.id AS objid,
    'md_tables'::text AS mainobjtype,
    t.table_name AS mainobjname,
    t.id AS mainobjid,
    s.name AS schemaname,
    s.id AS schemaid,
    cat.catalog_name AS catalogname,
    cat.id AS catalogid,
    conn.name AS connname,
    conn.id AS connid,
    proj.project_name AS projectname,
    proj.id AS projectid,
    nvl(conn.type, 'captured'::character varying) AS capturedorconverted,
    ((((
        CASE
            WHEN conn.type IS NULL THEN cat.catalog_name::text || '.'::text
            ELSE ''::text
        END || s.name::text) || '.'::text) || t.table_name::text) || '.'::text) || c.column_name::text AS qualifiedname,
    c.column_type AS datatype,
        CASE
            WHEN p.prop_key::text = 'seedvalue'::text THEN 'y'::text
            ELSE 'n'::text
        END AS isidentity
   FROM md_columns c
     LEFT JOIN md_additional_properties p ON c.id = p.ref_id_fk,
    md_tables t,
    md_schemas s,
    md_catalogs cat,
    md_connections conn,
    md_projects proj
  WHERE c.table_id_fk = t.id AND t.schema_id_fk = s.id AND s.catalog_id_fk = cat.id AND cat.connection_id_fk = conn.id AND conn.project_id_fk = proj.id;


