    nvl(conn.type, 'captured'::character varying) AS capturedorconverted,
    ((
        CASE
            WHEN conn.type IS NULL THEN cat.catalog_name::text || '.'::text
            ELSE ''::text
        END || s.name::text) || '.'::text) || trig.trigger_name::text AS qualifiedname
   FROM md_triggers trig,
    md_tables t,
    md_schemas s,
    md_catalogs cat,
    md_connections conn,
