UNION ALL
 SELECT 'md_triggers'::text AS objtype,
    trig.trigger_name AS objname,
    trig.id AS objid,
    'md_views'::text AS mainobjtype,
    v.view_name AS mainobjname,
    v.id AS mainobjid,
    s.name AS schemaname,
    s.id AS schemaid,
    cat.catalog_name AS catalogname,
    cat.id AS catalogid,
    conn.name AS connname,
    conn.id AS connid,
    proj.project_name AS projectname,
    proj.id AS projectid,
    nvl(conn.type, 'captured'::character varying) AS capturedorconverted,
    ((
        CASE
            WHEN conn.type IS NULL THEN cat.catalog_name::text || '.'::text
            ELSE ''::text
        END || s.name::text) || '.'::text) || trig.trigger_name::text AS qualifiedname
   FROM md_triggers trig,
    md_views v,
    md_schemas s,
    md_catalogs cat,
    md_connections conn,
    md_projects proj
  WHERE trig.table_or_view_id_fk = v.id AND v.schema_id_fk = s.id AND s.catalog_id_fk = cat.id AND cat.connection_id_fk = conn.id AND conn.project_id_fk = proj.id
  ORDER BY 3;


