-- et_main_uat.mv_akaun_cukai_dtl_1 source

CREATE MATERIALIZED VIEW mv_akaun_cukai_dtl_1
TABLESPACE pg_default
AS SELECT ac.no_akaun,
    ct.tahun AS tahun_bil,
    sh.kod AS sh_kod,
    mh.trkh_batal AS mh_trkh_batal,
    pj.kod AS pj_hm,
    dd.kod AS dd_hm,
    dd.nama AS nama_dd,
    hm.strata_induk_id,
    pj.pejabat_id,
    st.kod AS status_byrn_bil,
    ac.mklmt_tmbhn,
    ac.akaun_cukai_id,
    hm.id_hkmlk,
    ac.nama_pembayar,
    jh.kod AS jns_hm,
        CASE
            WHEN COALESCE(ct.tempoh_tunggakan, 0::numeric) = 0::numeric THEN 1
            WHEN COALESCE(ct.tempoh_tunggakan, 0::numeric) = 1::numeric THEN 2
            WHEN COALESCE(ct.tempoh_tunggakan, 0::numeric) >= 2::numeric AND COALESCE(ct.tempoh_tunggakan, 0::numeric) <= 3::numeric THEN 3
            WHEN COALESCE(ct.tempoh_tunggakan, 0::numeric) >= 4::numeric AND COALESCE(ct.tempoh_tunggakan, 0::numeric) <= 6::numeric THEN 4
            WHEN COALESCE(ct.tempoh_tunggakan, 0::numeric) >= 7::numeric AND COALESCE(ct.tempoh_tunggakan, 0::numeric) <= 10::numeric THEN 5
            WHEN COALESCE(ct.tempoh_tunggakan, 0::numeric) > 10::numeric THEN 6
            ELSE NULL::integer
        END AS kod_tt,
    COALESCE(ct.tunggakan_cukai_remitan, 0::numeric) + COALESCE(ct.tunggakan_cukai_tali_air_remitan, 0::numeric) + COALESCE(ct.tunggakan_denda_remitan, 0::numeric) AS remitan_tunggakan
   FROM hsl_akaun_cukai ac
     JOIN ind_hkmlk hm ON hm.hkmlk_id = ac.hkmlk_id
     JOIN ind_bandar_pekan_mukim mk ON mk.bandar_pekan_mukim_id = hm.bandar_pekan_mukim_id
     JOIN ind_daerah dd ON dd.daerah_id = mk.daerah_id
     JOIN ind_pejabat pj ON pj.pejabat_id = mk.pejabat_id
     JOIN hsl_bil_cukai_tahunan ct ON ct.akaun_cukai_id = ac.akaun_cukai_id
     JOIN rjk_senarai_ahli_kumpulan st ON ct.status_bayaran_bil_id = st.senarai_ahli_kumpulan_id
     JOIN ind_versi_dhd vd ON vd.hkmlk_id = hm.hkmlk_id
     JOIN ind_mklmt_hkmlk mh ON mh.mklmt_hkmlk_id = vd.mklmt_hkmlk_id
     JOIN rjk_senarai_ahli_kumpulan sh ON mh.status_hkmlk_id = sh.senarai_ahli_kumpulan_id
     LEFT JOIN rjk_jns_hkmlk jh ON jh.jns_hkmlk_id = hm.jns_hkmlk_id AND jh.flag_aktif = 'Y'::bpchar
  WHERE vd.flag_aktif::text = 'Y'::text AND COALESCE(ct.tempoh_tunggakan, 0::numeric) >= 0::numeric AND hm.strata_induk_id IS NULL
WITH DATA;

-- View indexes:
CREATE INDEX idx_macd1_kod_tt ON et_main_uat.mv_akaun_cukai_dtl_1 USING btree (kod_tt);
CREATE INDEX idx_macd1_no_akaun ON et_main_uat.mv_akaun_cukai_dtl_1 USING btree (no_akaun);
CREATE INDEX idx_macd1_tahun ON et_main_uat.mv_akaun_cukai_dtl_1 USING btree (tahun_bil);


-- et_main_uat.mv_akaun_cukai_dtl_2 source

