    ac.mklmt_tmbhn,
    ac.akaun_cukai_id,
    hm.id_hkmlk,
    ac.nama_pembayar,
    jh.kod AS jns_hm,
        CASE
            WHEN COALESCE(ct.tempoh_tunggakan, 0::numeric) = 0::numeric THEN 1
            WHEN COALESCE(ct.tempoh_tunggakan, 0::numeric) = 1::numeric THEN 2
            WHEN COALESCE(ct.tempoh_tunggakan, 0::numeric) >= 2::numeric AND COALESCE(ct.tempoh_tunggakan, 0::numeric) <= 3::numeric THEN 3
            WHEN COALESCE(ct.tempoh_tunggakan, 0::numeric) >= 4::numeric AND COALESCE(ct.tempoh_tunggakan, 0::numeric) <= 6::numeric THEN 4
            WHEN COALESCE(ct.tempoh_tunggakan, 0::numeric) >= 7::numeric AND COALESCE(ct.tempoh_tunggakan, 0::numeric) <= 10::numeric THEN 5
            WHEN COALESCE(ct.tempoh_tunggakan, 0::numeric) > 10::numeric THEN 6
            ELSE NULL::integer
        END AS kod_tt,
    COALESCE(ct.tunggakan_cukai_remitan, 0::numeric) + COALESCE(ct.tunggakan_cukai_tali_air_remitan, 0::numeric) + COALESCE(ct.tunggakan_denda_remitan, 0::numeric) AS remitan_tunggakan
   FROM hsl_akaun_cukai ac
     JOIN ind_hkmlk hm ON hm.hkmlk_id = ac.hkmlk_id
     JOIN ind_bandar_pekan_mukim mk ON mk.bandar_pekan_mukim_id = hm.bandar_pekan_mukim_id
     JOIN ind_daerah dd ON dd.daerah_id = mk.daerah_id
     JOIN ind_pejabat pj ON pj.pejabat_id = mk.pejabat_id
     JOIN hsl_bil_cukai_tahunan ct ON ct.akaun_cukai_id = ac.akaun_cukai_id
     JOIN rjk_senarai_ahli_kumpulan st ON ct.status_bayaran_bil_id = st.senarai_ahli_kumpulan_id
     JOIN ind_versi_dhd vd ON vd.hkmlk_id = hm.hkmlk_id
     JOIN ind_mklmt_hkmlk mh ON mh.mklmt_hkmlk_id = vd.mklmt_hkmlk_id
     JOIN rjk_senarai_ahli_kumpulan sh ON mh.status_hkmlk_id = sh.senarai_ahli_kumpulan_id
     LEFT JOIN rjk_jns_hkmlk jh ON jh.jns_hkmlk_id = hm.jns_hkmlk_id AND jh.flag_aktif = 'Y'::bpchar
  WHERE vd.flag_aktif::text = 'Y'::text AND COALESCE(ct.tempoh_tunggakan, 0::numeric) >= 0::numeric AND hm.strata_induk_id IS NOT NULL
WITH DATA;

-- View indexes:
CREATE INDEX idx_macd2_kod_tt ON et_main_uat.mv_akaun_cukai_dtl_2 USING btree (kod_tt);
CREATE INDEX idx_macd2_no_akaun ON et_main_uat.mv_akaun_cukai_dtl_2 USING btree (no_akaun);
CREATE INDEX idx_macd2_tahun ON et_main_uat.mv_akaun_cukai_dtl_2 USING btree (tahun_bil);


-- et_main_uat.mv_cara_bayaran_sum source

CREATE MATERIALIZED VIEW mv_cara_bayaran_sum
TABLESPACE pg_default
AS SELECT cb.kod_cara_bayaran_id,
    sum(cb.jumlah) AS total_jumlah,
    max(b.trkh_resit) AS trkh_resit,
    max(b.hasil_pejabat::text) AS hasil_pejabat
   FROM hsl_cara_bayaran cb
     JOIN hsl_btrn_bayaran bb ON bb.cara_bayaran_id = cb.cara_bayaran_id
     JOIN hsl_bayaran b ON bb.bayaran_id = b.bayaran_id
  WHERE b.trkh_resit >= date_trunc('year'::text, current_date::timestamp with time zone) AND b.trkh_resit < (date_trunc('year'::text, current_date::timestamp with time zone) + '1 year'::interval)
  GROUP BY cb.kod_cara_bayaran_id
WITH DATA;

-- View indexes:
CREATE INDEX idx_mvcbs_kod_cara_bayaran_id ON et_main_uat.mv_cara_bayaran_sum USING btree (kod_cara_bayaran_id);


-- et_main_uat.mv_penyata_akaun_summary source

CREATE MATERIALIZED VIEW mv_penyata_akaun_summary
TABLESPACE pg_default
AS SELECT no_akaun,
    tahun AS tahun_pa,
    trunc(tarikh) AS tarikh,
    sum(
        CASE
            WHEN (jenis_dokumen::text = ANY (ARRAY['BIL'::character varying, 'Notis'::character varying]::text[])) AND (kod_ispeks::text = ANY (ARRAY['H0161101'::character varying, 'H0176199'::character varying]::text[])) OR catatan::text = 'cukaiNotis'::text AND kod_ispeks::text = 'H0176104'::text THEN debit - kredit
            ELSE 0::numeric
        END) AS bil_s_tnh,
    sum(
        CASE
            WHEN (jenis_dokumen::text = ANY (ARRAY['NOTA_DEBIT'::character varying, 'NOTA_KREDIT'::character varying]::text[])) AND catatan::text = 'Pelarasan Cukai'::text AND (kod_ispeks::text = ANY (ARRAY['H0161101'::character varying, 'H0176199'::character varying]::text[])) THEN debit - kredit
            ELSE 0::numeric
        END) AS pelarasan_s_tnh,
    sum(
        CASE
            WHEN jenis_dokumen::text = 'RESIT'::text AND (kod_ispeks::text = ANY (ARRAY['H0161101'::character varying, 'H0176199'::character varying]::text[])) OR catatan::text = 'cukaiNotis'::text AND kod_ispeks::text = 'H0176104'::text THEN kredit - debit
            ELSE 0::numeric
        END) AS resit_s_tnh,
    sum(
        CASE
            WHEN jenis_dokumen::text = 'BIL'::text AND kod_ispeks::text = 'H0161198'::text THEN debit - kredit
            ELSE 0::numeric
        END) AS bil_t_tnh,
    sum(
        CASE
            WHEN (jenis_dokumen::text = ANY (ARRAY['NOTA_DEBIT'::character varying, 'NOTA_KREDIT'::character varying]::text[])) AND catatan::text = 'Pelarasan Tunggakan Cukai'::text AND kod_ispeks::text = 'H0161198'::text THEN debit - kredit
            ELSE 0::numeric
        END) AS pelarasan_t_tnh,
    sum(
        CASE
            WHEN jenis_dokumen::text = 'RESIT'::text AND kod_ispeks::text = 'H0161198'::text THEN kredit - debit
            ELSE 0::numeric
        END) AS resit_t_tnh,
    sum(
        CASE
            WHEN jenis_dokumen::text = 'BIL'::text AND sumber::text = 'Proses Denda'::text AND kod_ispeks::text = 'H0176104'::text THEN debit - kredit
            ELSE 0::numeric
        END) AS bil_ft_tnh,
    sum(
        CASE
            WHEN (jenis_dokumen::text = ANY (ARRAY['NOTA_DEBIT'::character varying, 'NOTA_KREDIT'::character varying]::text[])) AND catatan::text = 'Pelarasan Denda'::text AND kod_ispeks::text = 'H0176104'::text THEN debit - kredit
            ELSE 0::numeric
        END) AS pelarasan_ft_tnh,
    sum(
        CASE
            WHEN jenis_dokumen::text = 'RESIT'::text AND kod_ispeks::text = 'H0176104'::text AND catatan::text = 'denda'::text THEN kredit - debit
            ELSE 0::numeric
        END) AS resit_ft_tnh,
    sum(
        CASE
            WHEN jenis_dokumen::text = 'BIL'::text AND (sumber::text = ANY (ARRAY['BIL AWAL TAHUN'::character varying, 'Proses Akhir Tahun'::character varying]::text[])) AND kod_ispeks::text = 'H0176104'::text THEN debit - kredit
            ELSE 0::numeric
        END) AS bil_td_tnh,
    sum(
        CASE
            WHEN (jenis_dokumen::text = ANY (ARRAY['NOTA_DEBIT'::character varying, 'NOTA_KREDIT'::character varying]::text[])) AND catatan::text = 'Pelarasan Tunggakan Denda'::text AND kod_ispeks::text = 'H0176104'::text THEN debit - kredit
            ELSE 0::numeric
        END) AS pelarasan_td_tnh,
    sum(
        CASE
            WHEN jenis_dokumen::text = 'RESIT'::text AND kod_ispeks::text = 'H0176104'::text AND catatan::text = 'tunggakanDenda'::text THEN kredit - debit
            ELSE 0::numeric
        END) AS resit_td_tnh,
    sum(
        CASE
            WHEN jenis_dokumen::text = 'BIL'::text AND kod_ispeks::text = 'H0161301'::text THEN debit - kredit
            ELSE 0::numeric
        END) AS bil_ta_tnh,
    sum(
        CASE
            WHEN (jenis_dokumen::text = ANY (ARRAY['NOTA_DEBIT'::character varying, 'NOTA_KREDIT'::character varying]::text[])) AND catatan::text = 'Pelarasan Cukai Parit Dan Tali Air'::text AND kod_ispeks::text = 'H0161301'::text THEN debit - kredit
            ELSE 0::numeric
        END) AS pelarasan_ta_tnh,
    sum(
        CASE
            WHEN jenis_dokumen::text = 'RESIT'::text AND kod_ispeks::text = 'H0161301'::text THEN kredit - debit
            ELSE 0::numeric
        END) AS resit_ta_tnh,
    sum(
        CASE
            WHEN jenis_dokumen::text = 'BIL'::text AND kod_ispeks::text = 'H0161302'::text THEN debit - kredit
            ELSE 0::numeric
        END) AS bil_tta_tnh,
    sum(
        CASE
            WHEN (jenis_dokumen::text = ANY (ARRAY['NOTA_DEBIT'::character varying, 'NOTA_KREDIT'::character varying]::text[])) AND catatan::text = 'Pelarasan Tunggakan Cukai Parit Dan Tali Air'::text AND kod_ispeks::text = 'H0161302'::text THEN debit - kredit
            ELSE 0::numeric
        END) AS pelarasan_tta_tnh,
    sum(
        CASE
            WHEN jenis_dokumen::text = 'RESIT'::text AND kod_ispeks::text = 'H0161302'::text THEN kredit - debit
            ELSE 0::numeric
        END) AS resit_tta_tnh,
    sum(
        CASE
            WHEN (jenis_dokumen::text = ANY (ARRAY['BIL'::character varying, 'Notis'::character varying]::text[])) AND (kod_ispeks::text = ANY (ARRAY['H0176104'::character varying, 'H0161115'::character varying, 'H0176199'::character varying]::text[])) OR catatan::text = 'cukaiNotis'::text AND kod_ispeks::text = 'H0176104'::text THEN debit - kredit
            ELSE 0::numeric
        END) AS bil_s_ptk,
    sum(
        CASE
            WHEN (jenis_dokumen::text = ANY (ARRAY['NOTA_DEBIT'::character varying, 'NOTA_KREDIT'::character varying]::text[])) AND (kod_ispeks::text = ANY (ARRAY['H0176104'::character varying, 'H0161115'::character varying, 'H0176199'::character varying]::text[])) THEN debit - kredit
            ELSE 0::numeric
        END) AS pelarasan_s_ptk,
    sum(
        CASE
            WHEN jenis_dokumen::text = 'RESIT'::text AND (kod_ispeks::text = ANY (ARRAY['H0176104'::character varying, 'H0161115'::character varying, 'H0176199'::character varying]::text[])) THEN kredit - debit
            ELSE 0::numeric
        END) AS resit_s_ptk,
    sum(
        CASE
            WHEN jenis_dokumen::text = 'BIL'::text AND kod_ispeks::text = 'H0161116'::text THEN debit - kredit
            ELSE 0::numeric
        END) AS bil_t_ptk,
    sum(
        CASE
            WHEN (jenis_dokumen::text = ANY (ARRAY['NOTA_DEBIT'::character varying, 'NOTA_KREDIT'::character varying]::text[])) AND kod_ispeks::text = 'H0161116'::text THEN debit - kredit
            ELSE 0::numeric
        END) AS pelarasan_t_ptk,
    sum(
        CASE
            WHEN jenis_dokumen::text = 'RESIT'::text AND kod_ispeks::text = 'H0161116'::text THEN kredit - debit
            ELSE 0::numeric
        END) AS resit_t_ptk,
    sum(
        CASE
            WHEN jenis_dokumen::text = 'BIL'::text AND sumber::text = 'Proses Denda'::text AND kod_ispeks::text = 'H0176104'::text THEN debit - kredit
            ELSE 0::numeric
        END) AS bil_ft_ptk,
    sum(
        CASE
            WHEN (jenis_dokumen::text = ANY (ARRAY['NOTA_DEBIT'::character varying, 'NOTA_KREDIT'::character varying]::text[])) AND catatan::text = 'Pelarasan Denda'::text AND kod_ispeks::text = 'H0176104'::text THEN debit - kredit
            ELSE 0::numeric
        END) AS pelarasan_ft_ptk,
    sum(
        CASE
            WHEN jenis_dokumen::text = 'RESIT'::text AND kod_ispeks::text = 'H0176104'::text AND catatan::text = 'denda'::text THEN kredit - debit
            ELSE 0::numeric
        END) AS resit_ft_ptk,
    sum(
        CASE
            WHEN jenis_dokumen::text = 'BIL'::text AND (sumber::text = ANY (ARRAY['BIL AWAL TAHUN'::character varying, 'Proses Akhir Tahun'::character varying]::text[])) AND kod_ispeks::text = 'H0176104'::text THEN debit - kredit
            ELSE 0::numeric
        END) AS bil_td_ptk,
    sum(
        CASE
            WHEN (jenis_dokumen::text = ANY (ARRAY['NOTA_DEBIT'::character varying, 'NOTA_KREDIT'::character varying]::text[])) AND catatan::text = 'Pelarasan Tunggakan Denda'::text AND kod_ispeks::text = 'H0176104'::text THEN debit - kredit
            ELSE 0::numeric
        END) AS pelarasan_td_ptk,
    sum(
        CASE
            WHEN jenis_dokumen::text = 'RESIT'::text AND kod_ispeks::text = 'H0176104'::text AND catatan::text = 'tunggakanDenda'::text THEN kredit - debit
            ELSE 0::numeric
        END) AS resit_td_ptk
   FROM hsl_penyata_akaun pa
  WHERE (kod_ispeks::text = ANY (ARRAY['H0176104'::character varying, 'H0161301'::character varying, 'H0161101'::character varying, 'H0161198'::character varying, 'H0161302'::character varying, 'H0176103'::character varying, 'H0161116'::character varying, 'H0161115'::character varying, 'H0176199'::character varying]::text[])) AND (jenis_dokumen::text = ANY (ARRAY['NOTA_DEBIT'::character varying, 'NOTA_KREDIT'::character varying, 'BIL'::character varying, 'RESIT'::character varying, 'Notis'::character varying]::text[]))
  GROUP BY no_akaun, tahun, (trunc(tarikh))
WITH DATA;


-- et_main_uat.mv_penyata_akaun_summary_1 source

CREATE MATERIALIZED VIEW mv_penyata_akaun_summary_1
TABLESPACE pg_default
AS SELECT no_akaun,
    tahun_pa,
    tarikh,
    bil_s_tnh + pelarasan_s_tnh AS ct,
    bil_t_tnh + pelarasan_t_tnh AS tct,
    bil_ft_tnh + pelarasan_ft_tnh AS dd,
    bil_td_tnh + pelarasan_td_tnh AS td,
    bil_ta_tnh + pelarasan_ta_tnh AS ta,
    bil_tta_tnh + pelarasan_tta_tnh AS tta,
    bil_s_tnh + pelarasan_s_tnh - resit_s_tnh + (bil_t_tnh + pelarasan_t_tnh - resit_t_tnh) + (bil_ft_tnh + pelarasan_ft_tnh - resit_ft_tnh) + (bil_td_tnh + pelarasan_td_tnh - resit_td_tnh) + (bil_ta_tnh + pelarasan_ta_tnh - resit_ta_tnh) + (bil_tta_tnh + pelarasan_tta_tnh - resit_tta_tnh) AS jumlah
   FROM mv_penyata_akaun_summary pa
WITH DATA;

-- View indexes:
CREATE INDEX idx_mpas1_no_akaun ON et_main_uat.mv_penyata_akaun_summary_1 USING btree (no_akaun);
CREATE INDEX idx_mpas1_tahun_pa ON et_main_uat.mv_penyata_akaun_summary_1 USING btree (tahun_pa);


-- et_main_uat.mv_penyata_akaun_summary_2 source

CREATE MATERIALIZED VIEW mv_penyata_akaun_summary_2
TABLESPACE pg_default
AS SELECT no_akaun,
    tahun_pa,
    tarikh,
    bil_s_ptk + pelarasan_s_ptk AS ct,
    bil_t_ptk + pelarasan_t_ptk AS tct,
    bil_ft_ptk + pelarasan_ft_ptk AS dd,
    bil_td_ptk + pelarasan_td_ptk AS td,
    0 AS ta,
    0 AS tta,
    bil_s_ptk + pelarasan_s_ptk - resit_s_ptk + (bil_t_ptk + pelarasan_t_ptk - resit_t_ptk) + (bil_ft_ptk + pelarasan_ft_ptk - resit_ft_ptk) + (bil_td_ptk + pelarasan_td_ptk - resit_td_ptk) AS jumlah
   FROM mv_penyata_akaun_summary pa
WITH DATA;

-- View indexes:
CREATE INDEX idx_mpas2_no_akaun ON et_main_uat.mv_penyata_akaun_summary_2 USING btree (no_akaun);
CREATE INDEX idx_mpas2_tahun_pa ON et_main_uat.mv_penyata_akaun_summary_2 USING btree (tahun_pa);


-- et_main_uat.mv_sak_dtl source

CREATE MATERIALIZED VIEW mv_sak_dtl
TABLESPACE pg_default
AS SELECT tt.seq,
    tt.kod_usia,
    tt.perihal,
    jt.seq_jt,
    jt.kod_jt,
    jt.nama_jt
   FROM ( SELECT sak.turutan AS seq,
            sak.kod AS kod_usia,
            sak.nama AS perihal
           FROM rjk_senarai_kumpulan sk
             JOIN rjk_senarai_ahli_kumpulan sak ON sak.senarai_kumpulan_id = sk.senarai_kumpulan_id
          WHERE sk.kod::text = 'RPT_USIA_ABT'::text AND sk.flag_aktif = 'Y'::bpchar) tt,
    ( SELECT rjk_senarai_ahli_kumpulan.turutan AS seq_jt,
            rjk_senarai_ahli_kumpulan.kod AS kod_jt,
            rjk_senarai_ahli_kumpulan.nama AS nama_jt
           FROM rjk_senarai_ahli_kumpulan
          WHERE rjk_senarai_ahli_kumpulan.senarai_kumpulan_id = (( SELECT rjk_senarai_kumpulan.senarai_kumpulan_id
                   FROM rjk_senarai_kumpulan
                  WHERE rjk_senarai_kumpulan.kod::text = 'RPT_JNS_CUKAI2'::text))) jt
WITH DATA;


-- et_main_uat.mv_status_kutipan_cukai source

CREATE MATERIALIZED VIEW mv_status_kutipan_cukai
TABLESPACE pg_default
AS SELECT bct.tahun,
    bpm.pejabat_id,
        CASE
            WHEN hk.strata_induk_id IS NULL THEN 'tanah'::text
            ELSE 'petak'::text
        END AS jenis,
    sum(
        DECODE(  sign(bct.cukai_baki)
            , 1::numeric
            , bct.cukai_baki
            , 0::numeric
        )) AS cukai_perlu_dikutip,
    sum(
        DECODE(  sign(bct.cukai_baki)
            , 1::numeric
            , 0::numeric
            , bct.cukai_awal
        )) AS cukai_telah_dikutip,
    sum(
        DECODE(  sign(bct.tunggakan_cukai_baki)
            , 1::numeric
            , bct.tunggakan_cukai_baki
            , 0::numeric
        )) AS tunggakan_cukai_perlu_dikutip,
    sum(
        DECODE(  sign(bct.tunggakan_cukai_baki)
            , 1::numeric
            , 0::numeric
            , bct.tunggakan_cukai_awal
        )) AS tunggakan_cukai_telah_dikutip,
    sysdate AS trkh_kemaskini
   FROM hsl_akaun_cukai ac
     JOIN hsl_bil_cukai_tahunan bct ON ac.akaun_cukai_id = bct.akaun_cukai_id
     JOIN ind_hkmlk hk ON ac.hkmlk_id = hk.hkmlk_id
     JOIN ind_bandar_pekan_mukim bpm ON hk.bandar_pekan_mukim_id = bpm.bandar_pekan_mukim_id
  WHERE bct.tahun > (to_char(sysdate, 'yyyy'::character varying)::numeric - 3::numeric)
  GROUP BY bct.tahun, bpm.pejabat_id, (
        CASE
            WHEN hk.strata_induk_id IS NULL THEN 'tanah'::text
            ELSE 'petak'::text
        END)
WITH DATA;

COMMENT ON MATERIALIZED VIEW et_main_uat.mv_status_kutipan_cukai IS 'snapshot table for snapshot et_main_mig.mv_status_kutipan_cukai';


-- et_main_uat.tkr_tmp_v_borang2 source

CREATE OR REPLACE VIEW tkr_tmp_v_borang2
AS SELECT id_hkmlk,
    hkmlk_id,
    no_siri,
    luas_master,
    nvl(luaspetak, 0::numeric) AS luas_petak,
    nvl(luaspetakaksesori, 0::numeric) AS luas_petak_aksesori,
    nvl(luaspetak, 0::numeric) + nvl(luaspetakaksesori, 0::numeric) AS sum_of_luas,
        CASE
            WHEN nvl(luaspetak, 0::numeric) = 0::numeric AND nvl(luaspetakaksesori, 0::numeric) = 0::numeric THEN 0::numeric
            ELSE luas_master / (nvl(luaspetak, 0::numeric) + nvl(luaspetakaksesori, 0::numeric))
        END AS factor_original,
        CASE
            WHEN nvl(luaspetak, 0::numeric) = 0::numeric AND nvl(luaspetakaksesori, 0::numeric) = 0::numeric THEN 0::numeric
            WHEN (luas_master / (nvl(luaspetak, 0::numeric) + nvl(luaspetakaksesori, 0::numeric))) < 1::numeric THEN 1::numeric
            ELSE luas_master / (nvl(luaspetak, 0::numeric) + nvl(luaspetakaksesori, 0::numeric))
        END AS factor
   FROM ( SELECT a.id_hkmlk,
            a.hkmlk_id,
            ( SELECT string_agg(bh.no_siri::text, ','::text) AS string_agg
                   FROM tkr_buku_hakmilik bh,
                    tkr_hakmilik_tukarganti ht
                  WHERE ht.hkmlk_id = a.hkmlk_id AND ht.buku_hakmilik_id = bh.buku_hakmilik_id) AS no_siri,
            ( SELECT mx.luas
                   FROM ind_hkmlk hx,
                    ind_versi_dhd dx,
                    ind_mklmt_hkmlk mx
                  WHERE hx.hkmlk_id = dx.hkmlk_id AND mx.mklmt_hkmlk_id = dx.mklmt_hkmlk_id AND hx.hkmlk_id = a.hkmlk_id) AS luas_master,
            ( SELECT sum(d.luas) AS sum
                   FROM ind_hkmlk b_1
                     JOIN ind_versi_dhd c ON c.hkmlk_id = b_1.hkmlk_id
                     JOIN ind_mklmt_hkmlk d ON d.mklmt_hkmlk_id = c.mklmt_hkmlk_id
                     JOIN rjk_senarai_ahli_kumpulan e ON e.senarai_ahli_kumpulan_id = d.status_hkmlk_id
                  WHERE b_1.strata_induk_id = a.hkmlk_id AND c.flag_aktif::text = 'y'::text AND e.kod::text <> 'stahmbt'::text) AS luaspetak,
            ( SELECT sum(f.luas) AS sum
                   FROM ind_hkmlk b_1
                     JOIN ind_versi_dhd c ON c.hkmlk_id = b_1.hkmlk_id
                     JOIN ind_mklmt_hkmlk d ON d.mklmt_hkmlk_id = c.mklmt_hkmlk_id
                     JOIN rjk_senarai_ahli_kumpulan e ON e.senarai_ahli_kumpulan_id = d.status_hkmlk_id
                     JOIN ind_strata_ptk_aksesori f ON f.versi_akhir_id = c.versi_dhd_id
                  WHERE b_1.strata_induk_id = a.hkmlk_id AND c.flag_aktif::text = 'y'::text AND e.kod::text <> 'stahmbt'::text) AS luaspetakaksesori
           FROM ind_hkmlk a
          WHERE (a.hkmlk_id IN ( SELECT DISTINCT ind_hkmlk.strata_induk_id
                   FROM ind_hkmlk
                  WHERE ind_hkmlk.strata_induk_id IS NOT NULL))) b;


-- et_main_uat.v_b2_btrn source

CREATE OR REPLACE VIEW v_b2_btrn
AS SELECT ms.id_hkmlk AS id_hkmlk_master,
    hm.id_hkmlk,
    hm.hkmlk_id,
    nvl(bx.luas, 0::numeric) AS luas_petak,
    nvl(( SELECT sum(x.luas) AS sum
           FROM ind_strata_idx_ptk_aksesori x
          WHERE bx.btrn_strata_idx_id = x.btrn_strata_idx_id), 0::numeric) AS luas_petak_aksesori,
    nvl(bx.luas, 0::numeric) + nvl(( SELECT sum(x.luas) AS sum
           FROM ind_strata_idx_ptk_aksesori x
          WHERE bx.btrn_strata_idx_id = x.btrn_strata_idx_id), 0::numeric) AS total_luas,
    bx.btrn_strata_idx_id
   FROM ind_btrn_strata_idx bx
     CROSS JOIN ind_hkmlk hm
     CROSS JOIN ind_hkmlk ms
  WHERE bx.hkmlk_id = hm.hkmlk_id AND ms.hkmlk_id = hm.strata_induk_id AND bx.btrn_strata_idx_id <> 118337::numeric;


-- et_main_uat.v_butiran_honorarium source

CREATE OR REPLACE VIEW v_butiran_honorarium
AS SELECT ht.hakmilik_tukarganti_id,
    hm.id_hkmlk,
        DECODE(  tt.kod_tugasan
            , 'cbh2'::text::character varying
            , 'cbh'::text::character varying
            , 'cbh1'::text::character varying
            , 'cbh'::text::character varying
            , tt.kod_tugasan
        ) AS kod_tugasan,
    tt.nama_pengguna AS pegawai,
    tt.trkh_tamat AS tarikh_selesai
   FROM tkr_tugasan_tukarganti tt
     LEFT JOIN tkr_hakmilik_tukarganti ht ON tt.hakmilik_tukarganti_id = ht.hakmilik_tukarganti_id
     LEFT JOIN tkr_buku_hakmilik bh ON bh.buku_hakmilik_id = ht.buku_hakmilik_id
     LEFT JOIN ind_hkmlk hm ON hm.hkmlk_id = ht.hkmlk_id
  WHERE ht.status::text = 'strk'::text AND (tt.kod_tugasan::text = ANY (ARRAY['cbh2'::character varying::text, 'vm'::character varying::text, 'sp'::character varying::text])) AND (tt.tugasan_tukarganti_id IN ( SELECT max(tkr_tugasan_tukarganti.tugasan_tukarganti_id) AS max
           FROM tkr_tugasan_tukarganti
          GROUP BY tkr_tugasan_tukarganti.hakmilik_tukarganti_id, tkr_tugasan_tukarganti.kod_tugasan)) AND (EXISTS ( SELECT 'x'::text AS text
           FROM tkr_tugasan_tukarganti tt1
          WHERE tt1.hakmilik_tukarganti_id = ht.hakmilik_tukarganti_id AND tt1.kod_tugasan::text = 'sp'::text
          GROUP BY tt1.hakmilik_tukarganti_id
         HAVING max(tt1.trkh_tamat) < trunc(sysdate)));


-- et_main_uat.v_hakmilik_tukarganti source

CREATE OR REPLACE VIEW v_hakmilik_tukarganti
AS SELECT ht.hkmlk_id,
    hm.id_hkmlk,
    bh.no_siri,
    bh.jenis_fail
   FROM tkr_hakmilik_tukarganti ht
     CROSS JOIN tkr_buku_hakmilik bh
     LEFT JOIN ind_hkmlk hm ON hm.hkmlk_id = ht.hkmlk_id
  WHERE ht.buku_hakmilik_id = bh.buku_hakmilik_id;


-- et_main_uat.v_hsl_ac_qt_has_ft source

CREATE OR REPLACE VIEW v_hsl_ac_qt_has_ft
AS SELECT a.id_hkmlk,
    a.no_akaun,
    ((a.mklmt_tmbhn::json ->> 'noAkaunBaru'::text) || '|'::text) || ((( SELECT hsl_akaun_cukai.id_hkmlk
           FROM hsl_akaun_cukai
          WHERE hsl_akaun_cukai.no_akaun::text = (a.mklmt_tmbhn::json ->> 'noAkaunBaru'::text)))::text) AS hakmilik_baru
   FROM hsl_akaun_cukai a
     LEFT JOIN rjk_senarai_ahli_kumpulan b ON a.status_akaun_id = b.senarai_ahli_kumpulan_id
  WHERE json_extract_path_text(a.mklmt_tmbhn::json, VARIADIC ARRAY['noAkaunBaru'::text]) IS NOT NULL AND b.kod::text = 'SA_XAKTIF'::text AND (a.akaun_cukai_id IN ( SELECT a2.akaun_cukai_id
           FROM hsl_akaun_cukai a2
             JOIN hsl_bil_cukai_tahunan b2 ON a2.akaun_cukai_id = b2.akaun_cukai_id
          WHERE a2.no_akaun::text = (a.mklmt_tmbhn::json ->> 'noAkaunBaru'::text) AND b2.tahun = EXTRACT(year FROM sysdate)));


-- et_main_uat.v_hsl_ac_with_notis source

CREATE OR REPLACE VIEW v_hsl_ac_with_notis
AS SELECT id_hkmlk
   FROM hsl_akaun_cukai
  WHERE mklmt_tmbhn::text ~~ '%NOTIS":%'::text;


