-- et_main_uat.v_kadar_cukai_strata source

CREATE OR REPLACE VIEW v_kadar_cukai_strata
AS SELECT kpc.kadar_premium_cukai_id,
    kpc.jns_tnh_id,
    jt.nama AS jns_tnh,
    jt.kod AS jns_tnh_kod,
    kpc.kegunaan_tnh_id,
    kg.nama AS kegunaan_tnh,
    kg.kod AS kegunaan_tnh_kod,
    kcb.kadar_cukai_bpm_id,
    kcb.bandar_pekan_mukim_id,
    bp.nama AS bpm_nama,
    bp.kod AS bpm_kod,
    kcb.kadar_cukai,
    kcb.kadar_cukai_maxima,
    kcb.kadar_cukai_minima
   FROM ind_kadar_premium_cukai kpc,
    ind_kadar_cukai_bpm kcb,
    rjk_senarai_ahli_kumpulan jt,
    rjk_senarai_ahli_kumpulan kg,
    ind_bandar_pekan_mukim bp
  WHERE bp.bandar_pekan_mukim_id = kcb.bandar_pekan_mukim_id AND kpc.kadar_premium_cukai_id = kcb.kadar_premium_cukai_id AND kpc.jns_tnh_id = jt.senarai_ahli_kumpulan_id AND kpc.kegunaan_tnh_id = kg.senarai_ahli_kumpulan_id AND kpc.warta_id = 3::numeric;


-- et_main_uat.v_kod_hasil source

CREATE OR REPLACE VIEW v_kod_hasil
AS SELECT DISTINCT seq,
    kodfi,
    perihal,
    jenis_hasil
   FROM ( SELECT 1 AS seq,
            rjkkf.kod AS kodfi,
            'cukai tanah berulang'::text AS perihal,
            'rpt_kb_ct'::text AS jenis_hasil
           FROM rjk_senarai_ahli_kumpulan rjkkf
          WHERE rjkkf.kod::text = 'h0161101'::text
        UNION ALL
         SELECT 2 AS sort,
            rjkkf.kod AS kodfi,
            'tunggakan cukai tanah'::text AS perihal,
            'rpt_kb_tct'::text AS jenis_hasil
           FROM rjk_senarai_ahli_kumpulan rjkkf
          WHERE rjkkf.kod::text = 'h0161198'::text
        UNION ALL
         SELECT 3 AS sort,
            rjkkf.kod AS kodfi,
            'bahan batu'::text AS perihal,
            'rpt_kb_bb'::text AS jenis_hasil
           FROM rjk_senarai_ahli_kumpulan rjkkf
          WHERE rjkkf.kod::text = ANY (ARRAY['h0171230'::character varying::text, 'h0171290'::character varying::text])
        UNION ALL
         SELECT 4 AS sort,
            rjkkf.kod AS kodfi,
            'bahan mineral'::text AS perihal,
            'rpt_kb_bm'::text AS jenis_hasil
           FROM rjk_senarai_ahli_kumpulan rjkkf
          WHERE rjkkf.kod::text = ANY (ARRAY['h0161808'::character varying::text, 'h0161809'::character varying::text, 'h0161899'::character varying::text])
        UNION ALL
         SELECT 5 AS sort,
            rjkkf.kod AS kodfi,
            'premium'::text AS perihal,
            'rpt_kb_pre'::text AS jenis_hasil
           FROM rjk_senarai_ahli_kumpulan rjkkf
          WHERE rjkkf.kod::text = 'h0173602'::text
        UNION ALL
         SELECT 6 AS sort,
            rjkkf.kod AS kodfi,
            'hasil - hasil lain'::text AS perihal,
            'rpt_kb_hl'::text AS jenis_hasil
           FROM rjk_senarai_ahli_kumpulan rjkkf,
            rjk_senarai_kumpulan rj
          WHERE rjkkf.senarai_kumpulan_id = rj.senarai_kumpulan_id AND rj.kod::text = 'kod_bdhr'::text AND (rjkkf.kod::text = ANY (ARRAY['h0161303'::character varying::text, 'h0161302'::character varying::text, 'h0161301'::character varying::text, 'h0161302'::character varying::text, 'h0176103'::character varying::text, 'h0272447'::character varying::text, 'h0161102'::character varying::text, 'h0161105'::character varying::text, 'h0171243'::character varying::text, 'h0171261'::character varying::text, 'h0162703'::character varying::text, 'h0171204'::character varying::text, 'h0171277'::character varying::text, 'h0274199'::character varying::text, 'h0272104'::character varying::text, 'h0272110'::character varying::text, 'h0272499'::character varying::text, 'h0272102'::character varying::text, 'h0273210'::character varying::text, 'h0272499'::character varying::text, 'h0272471'::character varying::text, 'h0273111'::character varying::text, 'h0273199'::character varying::text, 'h0171281'::character varying::text, 'h0171264'::character varying::text, 'h0272448'::character varying::text, 'h0173606'::character varying::text, 'h0173601'::character varying::text, 'h0173605'::character varying::text, 'h0173604'::character varying::text, 'h0274101'::character varying::text, 'h0274102'::character varying::text, 'h0274103'::character varying::text, 'h0173601'::character varying::text, 'h0274101'::character varying::text, 'h0274101'::character varying::text, 'h0176199'::character varying::text, 'h0274101'::character varying::text, 'h0274101'::character varying::text, 'h0176199'::character varying::text, 'h0171204'::character varying::text, 'h0176110'::character varying::text, 'h0176110'::character varying::text, 'h0273999'::character varying::text, 'h0161199'::character varying::text, 'h0182328'::character varying::text, 'h0176125'::character varying::text])) AND rjkkf.flag_aktif = 'y'::bpchar) m1
  ORDER BY seq;


-- et_main_uat.v_kod_ispek source

CREATE OR REPLACE VIEW v_kod_ispek
AS SELECT rt.seq_kelas,
    rt.kelas,
    rt.seq_kat,
    rt.kategori,
    rt.seq_kump,
    rt.kumpulan,
    rt.seq_jns,
    rt.jns,
    kh.kod_kb,
    kh.perihal,
    kh.turutan,
    kh.hsl69
   FROM ( SELECT kl.seq_kelas,
            kl.kelas,
            kt.seq_kat,
            kt.kategori,
            kp.seq_kump,
            kp.kumpulan,
            jh.seq_jns,
            jh.jns
           FROM ( SELECT 1 AS seq_kelas,
                    'hasil daripada urusniaga bukan pertukaran'::text AS kelas
                   FROM dual
                UNION ALL
                 SELECT 2 AS seq_kelas,
                    'hasil daripada urusniaga pertukaran'::text AS kelas
                   FROM dual) kl,
            ( SELECT 1 AS seq_kat,
                    'hasil cukai'::text AS kategori,
                    1 AS seq_kelas
                   FROM dual
                UNION ALL
                 SELECT 2 AS seq_kat,
                    'hasil bukan cukai'::text AS kategori,
                    1 AS seq_kelas
                   FROM dual
                UNION ALL
                 SELECT 3 AS seq_kat,
                    'pelbagai terimaan dan pindahan'::text AS kategori,
                    1 AS seq_kelas
                   FROM dual
                UNION ALL
                 SELECT 1 AS seq_kat,
                    'hasil bukan cukai'::text AS kategori,
                    2 AS seq_kelas
                   FROM dual) kt,
            ( SELECT 1 AS seq_kump,
                    'cukai langsung'::text AS kumpulan,
                    1 AS seq_kat,
                    1 AS seq_kelas
                   FROM dual
                UNION ALL
                 SELECT 2 AS seq_kump,
                    'cukai tidak langsung'::text AS kumpulan,
                    1 AS seq_kat,
                    1 AS seq_kelas
                   FROM dual
                UNION ALL
                 SELECT 1 AS seq_kump,
                    'lesen, bayaran pendaftaran dan permit'::text AS kumpulan,
                    2 AS seq_kat,
                    1 AS seq_kelas
                   FROM dual
                UNION ALL
                 SELECT 2 AS seq_kump,
                    'pelbagai bayaran'::text AS kumpulan,
                    2 AS seq_kat,
                    1 AS seq_kelas
                   FROM dual
                UNION ALL
                 SELECT 3 AS seq_kump,
                    'perolehan dari jualan barang-barang'::text AS kumpulan,
                    2 AS seq_kat,
                    1 AS seq_kelas
                   FROM dual
                UNION ALL
                 SELECT 4 AS seq_kump,
                    'denda dan hukuman'::text AS kumpulan,
                    2 AS seq_kat,
                    1 AS seq_kelas
                   FROM dual
                UNION ALL
                 SELECT 5 AS seq_kump,
                    'pelbagai sumbangan'::text AS kumpulan,
                    2 AS seq_kat,
                    1 AS seq_kelas
                   FROM dual
                UNION ALL
                 SELECT 1 AS seq_kump,
                    'pulang balik perbelanjaan'::text AS kumpulan,
                    3 AS seq_kat,
                    1 AS seq_kelas
                   FROM dual
                UNION ALL
                 SELECT 1 AS seq_kump,
                    'perkhidmatan dan bayaran perkhidmatan'::text AS kumpulan,
                    1 AS seq_kat,
                    2 AS seq_kelas
                   FROM dual
                UNION ALL
                 SELECT 2 AS seq_kump,
                    'perolehan jualan barang-barang'::text AS kumpulan,
                    1 AS seq_kat,
                    2 AS seq_kelas
                   FROM dual
                UNION ALL
                 SELECT 3 AS seq_kump,
                    'sewaan'::text AS kumpulan,
                    1 AS seq_kat,
                    2 AS seq_kelas
                   FROM dual) kp,
            ( SELECT 1 AS seq_jns,
                    'cukai tanah'::text AS jns,
                    1 AS seq_kump,
                    1 AS seq_kat,
                    1 AS seq_kelas
                   FROM dual
                UNION ALL
                 SELECT 2 AS seq_jns,
                    'cukai parit dan tali air'::text AS jns,
                    1 AS seq_kump,
                    1 AS seq_kat,
                    1 AS seq_kelas
                   FROM dual
                UNION ALL
                 SELECT 3 AS seq_jns,
                    'royalti'::text AS jns,
                    1 AS seq_kump,
                    1 AS seq_kat,
                    1 AS seq_kelas
                   FROM dual
                UNION ALL
                 SELECT 4 AS seq_jns,
                    'levi'::text AS jns,
                    2 AS seq_kump,
                    1 AS seq_kat,
                    1 AS seq_kelas
                   FROM dual
                UNION ALL
                 SELECT 5 AS seq_jns,
                    'bayaran untuk berniaga'::text AS jns,
                    1 AS seq_kump,
                    2 AS seq_kat,
                    1 AS seq_kelas
                   FROM dual
                UNION ALL
                 SELECT 6 AS seq_jns,
                    'pelbagai bayaran'::text AS jns,
                    2 AS seq_kump,
                    2 AS seq_kat,
                    1 AS seq_kelas
                   FROM dual
                UNION ALL
                 SELECT 7 AS seq_jns,
                    'premium tanah'::text AS jns,
                    3 AS seq_kump,
                    2 AS seq_kat,
                    1 AS seq_kelas
                   FROM dual
                UNION ALL
                 SELECT 8 AS seq_jns,
                    'denda dan hukuman'::text AS jns,
                    4 AS seq_kump,
                    2 AS seq_kat,
                    1 AS seq_kelas
                   FROM dual
                UNION ALL
                 SELECT 9 AS seq_jns,
                    'pelbagai sumbangan'::text AS jns,
                    5 AS seq_kump,
                    2 AS seq_kat,
                    1 AS seq_kelas
                   FROM dual
                UNION ALL
                 SELECT 10 AS seq_jns,
                    'pulang balik perbelanjaan am'::text AS jns,
                    1 AS seq_kump,
                    3 AS seq_kat,
                    1 AS seq_kelas
                   FROM dual
                UNION ALL
                 SELECT 11 AS seq_jns,
                    'bayaran ikhtisas'::text AS jns,
                    1 AS seq_kump,
                    1 AS seq_kat,
                    2 AS seq_kelas
                   FROM dual
                UNION ALL
                 SELECT 12 AS seq_jns,
                    'bayaran perkhidmatan'::text AS jns,
                    1 AS seq_kump,
                    1 AS seq_kat,
                    2 AS seq_kelas
                   FROM dual
                UNION ALL
                 SELECT 13 AS seq_jns,
                    'jualan barang-barang cetak'::text AS jns,
                    2 AS seq_kump,
                    1 AS seq_kat,
                    2 AS seq_kelas
                   FROM dual
                UNION ALL
                 SELECT 14 AS seq_jns,
                    'jualan harta benda tidak dipermodalkan'::text AS jns,
                    2 AS seq_kump,
                    1 AS seq_kat,
                    2 AS seq_kelas
                   FROM dual
                UNION ALL
                 SELECT 15 AS seq_jns,
                    'sewa pelbagai'::text AS jns,
                    3 AS seq_kump,
                    1 AS seq_kat,
                    2 AS seq_kelas
                   FROM dual) jh
          WHERE kt.seq_kelas = kl.seq_kelas AND kp.seq_kat = kt.seq_kat AND kp.seq_kelas = kt.seq_kelas AND jh.seq_kump = kp.seq_kump AND jh.seq_kat = kp.seq_kat AND jh.seq_kelas = kp.seq_kelas) rt
     JOIN ( SELECT 1 AS seq_jns,
            kb.kod AS kod_kb,
            kb.nama AS perihal,
            kb.turutan,
                CASE
                    WHEN kb.kod::text = ANY (ARRAY['h0161101'::character varying::text, 'h0161102'::character varying::text, 'h0161115'::character varying::text, 'h0161116'::character varying::text, 'h0161117'::character varying::text, 'h0161198'::character varying::text]) THEN 'y'::text
                    ELSE 'n'::text
                END AS hsl69
           FROM ( SELECT rjk_senarai_ahli_kumpulan.turutan,
                    rjk_senarai_ahli_kumpulan.kod,
                    rjk_senarai_ahli_kumpulan.nama,
                    rjk_senarai_ahli_kumpulan.perihal
                   FROM rjk_senarai_ahli_kumpulan
                  WHERE rjk_senarai_ahli_kumpulan.senarai_kumpulan_id = (( SELECT rjk_senarai_kumpulan.senarai_kumpulan_id
                           FROM rjk_senarai_kumpulan
                          WHERE rjk_senarai_kumpulan.kod::text = 'kod_bdhr'::text)) AND rjk_senarai_ahli_kumpulan.flag_aktif = 'y'::bpchar) kb
          WHERE kb.kod::text >= 'h0161101'::text AND kb.kod::text <= 'h0161199'::text
        UNION ALL
         SELECT 2 AS seq_jns,
            kb.kod AS kod_kb,
            kb.nama AS perihal,
            kb.turutan,
                CASE
                    WHEN kb.kod::text = ANY (ARRAY['h0161301'::character varying::text, 'h0161302'::character varying::text]) THEN 'y'::text
                    ELSE 'n'::text
                END AS hsl69
           FROM ( SELECT rjk_senarai_ahli_kumpulan.turutan,
                    rjk_senarai_ahli_kumpulan.kod,
                    rjk_senarai_ahli_kumpulan.nama,
                    rjk_senarai_ahli_kumpulan.perihal
                   FROM rjk_senarai_ahli_kumpulan
                  WHERE rjk_senarai_ahli_kumpulan.senarai_kumpulan_id = (( SELECT rjk_senarai_kumpulan.senarai_kumpulan_id
                           FROM rjk_senarai_kumpulan
                          WHERE rjk_senarai_kumpulan.kod::text = 'kod_bdhr'::text)) AND rjk_senarai_ahli_kumpulan.flag_aktif = 'y'::bpchar) kb
          WHERE kb.kod::text >= 'h0161301'::text AND kb.kod::text <= 'h0161399'::text
        UNION ALL
         SELECT 3 AS seq_jns,
            kb.kod AS kod_kb,
            kb.nama AS perihal,
            kb.turutan,
                CASE
                    WHEN kb.kod::text = ANY (ARRAY['h0161808'::character varying::text, 'h0161809'::character varying::text, 'h0161899'::character varying::text]) THEN 'y'::text
                    ELSE 'n'::text
                END AS hsl69
           FROM ( SELECT rjk_senarai_ahli_kumpulan.turutan,
                    rjk_senarai_ahli_kumpulan.kod,
                    rjk_senarai_ahli_kumpulan.nama,
                    rjk_senarai_ahli_kumpulan.perihal
                   FROM rjk_senarai_ahli_kumpulan
                  WHERE rjk_senarai_ahli_kumpulan.senarai_kumpulan_id = (( SELECT rjk_senarai_kumpulan.senarai_kumpulan_id
                           FROM rjk_senarai_kumpulan
                          WHERE rjk_senarai_kumpulan.kod::text = 'kod_bdhr'::text)) AND rjk_senarai_ahli_kumpulan.flag_aktif = 'y'::bpchar) kb
          WHERE kb.kod::text >= 'h0161808'::text AND kb.kod::text <= 'h0161899'::text
        UNION ALL
         SELECT 4 AS seq_jns,
            rjk_senarai_ahli_kumpulan.kod AS kod_kb,
            rjk_senarai_ahli_kumpulan.nama AS perihal,
            rjk_senarai_ahli_kumpulan.turutan,
            'y'::text AS hsl69
           FROM rjk_senarai_ahli_kumpulan
          WHERE rjk_senarai_ahli_kumpulan.senarai_kumpulan_id = (( SELECT rjk_senarai_kumpulan.senarai_kumpulan_id
                   FROM rjk_senarai_kumpulan
                  WHERE rjk_senarai_kumpulan.kod::text = 'kod_bdhr'::text)) AND rjk_senarai_ahli_kumpulan.kod::text = 'h0162799'::text
        UNION ALL
         SELECT 5 AS seq_jns,
            kb.kod AS kod_kb,
            kb.nama AS perihal,
            kb.turutan,
                CASE
                    WHEN kb.kod::text = ANY (ARRAY['h0171214'::character varying::text, 'h0171219'::character varying::text, 'h0171230'::character varying::text, 'h0171253'::character varying::text, 'h0171264'::character varying::text, 'h0171274'::character varying::text, 'h0171290'::character varying::text, 'h0171299'::character varying::text]) THEN 'y'::text
                    ELSE 'n'::text
                END AS hsl69
           FROM ( SELECT rjk_senarai_ahli_kumpulan.turutan,
                    rjk_senarai_ahli_kumpulan.kod,
                    rjk_senarai_ahli_kumpulan.nama,
                    rjk_senarai_ahli_kumpulan.perihal
                   FROM rjk_senarai_ahli_kumpulan
                  WHERE rjk_senarai_ahli_kumpulan.senarai_kumpulan_id = (( SELECT rjk_senarai_kumpulan.senarai_kumpulan_id
                           FROM rjk_senarai_kumpulan
                          WHERE rjk_senarai_kumpulan.kod::text = 'kod_bdhr'::text)) AND rjk_senarai_ahli_kumpulan.flag_aktif = 'y'::bpchar) kb
          WHERE kb.kod::text >= 'h0171201'::text AND kb.kod::text <= 'h0171299'::text
        UNION ALL
         SELECT 6 AS seq_jns,
            rjk_senarai_ahli_kumpulan.kod AS kod_kb,
            rjk_senarai_ahli_kumpulan.nama AS perihal,
            rjk_senarai_ahli_kumpulan.turutan,
            'y'::text AS hsl69
           FROM rjk_senarai_ahli_kumpulan
