-- et_main_uat.v_rekod_ursn source

CREATE OR REPLACE VIEW v_rekod_ursn
AS SELECT ru.rekod_ursn_id,
    ru.flag_kuatkuasa,
    ru.aplikasi_id,
    ap.id_pengenalan,
    ur.kod AS ursn_kod,
    ru.versi_mula,
    ru.versi_akhir_id,
    ru.kandungan_baru,
    ru.tdkn_diambil,
    hm.hkmlk_id,
    hm.id_hkmlk,
    ru.created_date,
    ru.last_modified_date
   FROM ind_rekod_ursn ru
     LEFT JOIN ind_versi_dhd dh ON dh.versi_dhd_id = ru.versi_akhir_id
     LEFT JOIN ind_hkmlk hm ON hm.hkmlk_id = dh.hkmlk_id
     LEFT JOIN umm_aplikasi ap ON ap.aplikasi_id = ru.aplikasi_id
     LEFT JOIN ind_ursn ur ON ur.ursn_id = ap.ursn_id
  WHERE dh.flag_aktif::text = 'y'::text;


-- et_main_uat.v_rpt_jns_hasil source

CREATE OR REPLACE VIEW v_rpt_jns_hasil
AS SELECT
        DECODE(  rjk_senarai_ahli_kumpulan.kod
            , 'h0161101'::text::character varying
            , 1
            , 'h0161198'::text::character varying
            , 2
            , 'h0173602'::text::character varying
            , 5
            , NULL::integer
        ) AS seq,
    rjk_senarai_ahli_kumpulan.kod,
        CASE
            WHEN rjk_senarai_ahli_kumpulan.kod::text = 'h0173602'::text THEN 'premium'::character varying
            ELSE rjk_senarai_ahli_kumpulan.nama
        END AS perihal,
        DECODE(  rjk_senarai_ahli_kumpulan.kod
            , 'h0161101'::text::character varying
            , 'rpt_kb_ct'::text::character varying
            , 'h0161198'::text::character varying
            , 'rpt_kb_tct'::text::character varying
            , 'h0173602'::text::character varying
            , 'rpt_kb_pre'::text::character varying
            , NULL::character varying
        ) AS kod_hasil
   FROM rjk_senarai_ahli_kumpulan
  WHERE rjk_senarai_ahli_kumpulan.kod::text = ANY (ARRAY['h0161101'::character varying::text, 'h0161198'::character varying::text, 'h0173602'::character varying::text])
UNION ALL
 SELECT 3 AS seq,
    rjk_senarai_ahli_kumpulan.kod,
    'bahan batu'::character varying AS perihal,
    'rpt_kb_bb'::character varying AS kod_hasil
   FROM rjk_senarai_ahli_kumpulan
  WHERE rjk_senarai_ahli_kumpulan.kod::text = ANY (ARRAY['h0171230'::character varying::text, 'h0171290'::character varying::text])
UNION ALL
 SELECT 4 AS seq,
    rjk_senarai_ahli_kumpulan.kod,
    'bahan mineral'::character varying AS perihal,
    'rpt_kb_bm'::character varying AS kod_hasil
   FROM rjk_senarai_ahli_kumpulan
  WHERE rjk_senarai_ahli_kumpulan.kod::text = ANY (ARRAY['h0161808'::character varying::text, 'h0161809'::character varying::text])
UNION ALL
 SELECT 6 AS seq,
    sak.kod,
    'hasil - hasil lain'::character varying AS perihal,
    'rpt_kb_hl'::character varying AS kod_hasil
   FROM rjk_senarai_ahli_kumpulan sak,
    rjk_senarai_kumpulan sk
  WHERE sk.senarai_kumpulan_id = sak.senarai_kumpulan_id AND sk.kod::text = 'kod_bdhr'::text AND (sak.kod::text <> ALL (ARRAY['h0161101'::character varying::text, 'h0161198'::character varying::text, 'h0171230'::character varying::text, 'h0171290'::character varying::text, 'h0161808'::character varying::text, 'h0161809'::character varying::text, 'h0173602'::character varying::text])) AND sak.flag_aktif = 'y'::bpchar
  ORDER BY 1, 2;


-- et_main_uat.v_script_dc source

CREATE OR REPLACE VIEW v_script_dc
AS SELECT dc.id_hkmlk,
    dc.perihal,
    (('update ind_hkmlk_pelbagai set maklumat_tambahan=''{"pembetulanlist":[{catatan:"'::text || dc.perihal::text) || '",status:n}]}'' where hkmlk_pelbagai_id =  '::text) || hp.hkmlk_pelbagai_id::text AS update_script
   FROM tkr_tmp_dc dc,
    ind_hkmlk hm,
    ind_hkmlk_pelbagai hp
  WHERE dc.id_hkmlk::text = hm.id_hkmlk::text AND hm.hkmlk_pelbagai_id = hp.hkmlk_pelbagai_id AND dc.perihal IS NOT NULL;


-- et_main_uat.v_str_mukim_44 source

CREATE OR REPLACE VIEW v_str_mukim_44
AS SELECT substr(b.catatan::text, 1::numeric, (instr(b.catatan, '/'::character varying, 1::numeric) - 1)::numeric) AS hm_landed,
    b.catatan AS hm_str
   FROM ind_hkmlk a,
    ind_hkmlk_pelbagai b
  WHERE a.hkmlk_pelbagai_id = b.hkmlk_pelbagai_id AND b.catatan IS NOT NULL AND b.last_modified_by::text = 'migrator_s_upd_idhm_44_41'::text;


