-- et_main_uat.v_tukarganti source

CREATE OR REPLACE VIEW v_tukarganti
AS SELECT ht.hakmilik_tukarganti_id,
    ht.status,
    hm.hkmlk_id,
    hm.id_hkmlk,
    bh.buku_hakmilik_id,
    bh.no_siri,
    bh.jenis_fail,
    ht.pendaftar,
    bh.pendaftar AS pendaftar_buku
   FROM tkr_hakmilik_tukarganti ht,
    ind_hkmlk hm,
