-- et_main_uat.v_tukarganti_pengguna source

CREATE OR REPLACE VIEW v_tukarganti_pengguna
AS SELECT pengguna_id,
    created_by,
    created_date,
    last_modified_by,
    last_modified_date,
    version,
    nama_pengguna,
    nama,
    adalah_aktif,
        DECODE(  peranan_kod
            , 'PH'::text::character varying
            , 'PRN_PGN_PYMKDF'::text::character varying
            , 'PT'::text::character varying
            , 'PRN_PGN_PYMKPT'::text::character varying
            , 'PYM_PSTB'::text::character varying
            , 'PRN_PGN_PYMK'::text::character varying
            , 'PB_PTSB'::text::character varying
            , 'PRN_PGN_PB'::text::character varying
            , 'PB'::text::character varying
            , 'PRN_PGN_PBPTG'::text::character varying
            , 'PD_PTSB'::text::character varying
            , 'PRN_PGN_PD'::text::character varying
            , 'PYLIA_PTSB'::text::character varying
            , 'PRN_PGN_PYLIA'::text::character varying
            , peranan_kod
        ) AS peranan_kod
   FROM ( SELECT a.pengguna_id,
            a.created_by,
            a.created_date,
            a.last_modified_by,
            a.last_modified_date,
            a.version,
            a.nama_pengguna,
            b.nama,
            a.flag_aktif AS adalah_aktif,
            ( SELECT sak.kod
                   FROM pcp_capaian_pengguna c,
                    pcp_peranan_modul e,
                    rjk_senarai_ahli_kumpulan sak
                  WHERE e.peranan_modul_id = c.peranan_modul_id AND e.peranan_id = sak.senarai_ahli_kumpulan_id AND (sak.kod::text = ANY (ARRAY['PB_PTSB'::character varying::text, 'PB'::character varying::text, 'PYM_PSTB'::character varying::text, 'PD_PTSB'::character varying::text, 'PYLIA_PTSB'::character varying::text, 'PT'::character varying::text, 'PH'::character varying::text, 'PYM_QA'::character varying::text])) AND a.pengguna_id = c.pengguna_id AND (rownum) = 1) AS peranan_kod
           FROM pcp_pengguna a,
            rjk_individu b
          WHERE a.individu_id = b.individu_id) __unnamed_subquery_0
  WHERE peranan_kod IS NOT NULL;


-- et_main_uat.view_perserahan_hakmilik source

CREATE OR REPLACE VIEW view_perserahan_hakmilik
AS SELECT ap.created_by AS ap_created_by,
    ap.last_modified_by AS ap_last_modified_by,
    ah.id_hkmlk,
