-- DROP FUNCTION et_main_uat.calculate_business_days(timestamp, timestamp);

CREATE OR REPLACE FUNCTION et_main_uat.calculate_business_days(p_start_date timestamp without time zone, p_end_date timestamp without time zone)
 RETURNS numeric
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_holidays integer;
    v_start_date date := trunc(p_start_date);
    v_end_date date := trunc(p_end_date);

	v_total_days integer;

BEGIN
    IF v_end_date >= v_start_date THEN

        SELECT count(1)
        INTO v_holidays
        FROM (
            SELECT DISTINCT
                b.trkh + generate_series(0, extract(day from (b.trkh_hingga - b.trkh))) AS day
            FROM rjk_hari_kelepasan_am b
        ) AS holidays
        WHERE day BETWEEN v_start_date AND v_end_date
          AND EXTRACT(DOW FROM day) NOT IN (0, 6);
            

        SELECT count(1)
        INTO v_total_days
        FROM (
            SELECT 
                v_start_date + generate_series(0, extract(day from (v_end_date - v_start_date))) AS day
            FROM dual
        ) AS holidays
        WHERE EXTRACT(DOW FROM day) NOT IN (0, 6);

        RETURN v_total_days - v_holidays;
	ELSE
        RETURN NULL;
    END IF;
END;
$function$
;

-- DROP FUNCTION et_main_uat.calculate_business_hours_day(timestamp, timestamp, varchar);

CREATE OR REPLACE FUNCTION et_main_uat.calculate_business_hours_day(p_start_date timestamp without time zone, p_end_date timestamp without time zone, p_daftar character varying)
 RETURNS numeric
 LANGUAGE edbspl
 SECURITY DEFINER
AS $function$
        V_HOURS        NUMBER;
        V_DAY          NUMBER;

        BEGIN
        IF P_END_DATE >= P_START_DATE
        THEN

        V_HOURS := 24 * calculate_business_days(to_date ( to_char ( P_START_DATE , 'DD-MM-YYYY hh24:mi:ss' ) , 'DD-MM-YYYY hh24:mi:ss' )
        ,to_date ( to_char (P_END_DATE, 'DD-MM-YYYY hh24:mi:ss'), 'DD-MM-YYYY hh24:mi:ss' ));

        IF P_DAFTAR = 'ISIHAN' AND V_HOURS <= 96
        THEN V_DAY := 1;
        ELSIF P_DAFTAR = 'ISIHAN' AND V_HOURS BETWEEN 97 AND 192
        THEN V_DAY:=2;
        ELSIF P_DAFTAR = 'ISIHAN' AND V_HOURS BETWEEN 193 AND 288
        THEN V_DAY:=3;
        ELSIF P_DAFTAR = 'ISIHAN' AND V_HOURS BETWEEN 289 AND 384
        THEN V_DAY:=4;
        ELSIF P_DAFTAR = 'ISIHAN' AND V_HOURS BETWEEN 385 AND 1344
        THEN V_DAY:=5;
        ELSIF P_DAFTAR = 'ISIHAN' AND V_HOURS BETWEEN 1345 AND 2880
        THEN V_DAY:=15;
        ELSIF P_DAFTAR = 'ISIHAN' AND V_HOURS > 2880
        THEN V_DAY:=31;
        END IF;

        IF P_DAFTAR = 'DAFTAR' AND V_HOURS <= 48
        THEN V_DAY := 1;
        ELSIF P_DAFTAR = 'DAFTAR' AND V_HOURS BETWEEN 49 AND 96
        THEN V_DAY:=2;
        ELSIF P_DAFTAR = 'DAFTAR' AND V_HOURS BETWEEN 97 AND 144
        THEN V_DAY:=3;
        ELSIF P_DAFTAR = 'DAFTAR' AND V_HOURS BETWEEN 145 AND 192
        THEN V_DAY:=4;
        ELSIF P_DAFTAR = 'DAFTAR' AND V_HOURS BETWEEN 193 AND 672
        THEN V_DAY:=5;
        ELSIF P_DAFTAR = 'DAFTAR' AND V_HOURS BETWEEN 673 AND 1440
        THEN V_DAY:=15;
        ELSIF P_DAFTAR = 'DAFTAR' AND V_HOURS > 1440
        THEN V_DAY:=31;
        END IF;

        RETURN V_DAY;
        ELSE
          RETURN NULL;
        END IF;

END CALCULATE_BUSINESS_HOURS_DAY$function$
;

-- DROP FUNCTION et_main_uat.calculate_day_daftar(timestamp, timestamp);

CREATE OR REPLACE FUNCTION et_main_uat.calculate_day_daftar(p_start_date timestamp without time zone, p_end_date timestamp without time zone)
 RETURNS numeric
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_holidays integer;
	v_total_days integer;

BEGIN
    IF p_end_date >= p_start_date THEN

        SELECT count(1)
        INTO v_holidays
        FROM (
            SELECT DISTINCT
                b.trkh + generate_series(0, extract(day from (b.trkh_hingga - b.trkh))) AS day
            FROM rjk_hari_kelepasan_am b
        ) AS holidays
        WHERE day BETWEEN p_start_date AND p_end_date
          AND EXTRACT(DOW FROM day) NOT IN (0, 6);
            

        SELECT count(1)
        INTO v_total_days
        FROM (
            SELECT 
                p_start_date + generate_series(0, extract(day from (p_end_date - p_start_date))) AS day
            FROM dual
        ) AS holidays
        WHERE EXTRACT(DOW FROM day) NOT IN (0, 6);

        RETURN v_total_days - v_holidays;
	ELSE
        RETURN NULL;
    END IF;
END;
$function$
;

-- DROP FUNCTION et_main_uat.calculate_fi_tunggakan(varchar, varchar);

CREATE OR REPLACE FUNCTION et_main_uat.calculate_fi_tunggakan(p_no_akaun character varying, p_tahun character varying)
 RETURNS numeric
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_fi_tunggakan numeric :=0;
    v_bil_cukai_tahunan_id numeric;
    v_jumlah_awal numeric;
    v_jumlah_bayaran numeric;
    v_jumlah_pelarasan numeric;
    v_jumlah_diskaun numeric;
    v_jumlah_remitan numeric;
    v_tunggakan numeric;
    v_baki_akhir numeric;
    v_denda numeric;
    v_denda_diskaun numeric;
    v_denda_remitan numeric;
    v_denda_pelarasan numeric;
    v_denda_baki numeric;
    v_lebih_bayar numeric;

BEGIN

    SELECT bil_cukai_tahunan_id, baki_akhir, denda_awal,  nvl ( ct.denda_remitan, 0 ) , NVL(tunggakan_terlebih_bayar_awal, 0),
    ( nvl ( ct.cukai_remitan, 0 ) + nvl ( ct.tunggakan_cukai_remitan, 0 )  
    + nvl ( ct.denda_remitan, 0 ) 
    + nvl ( ct.tunggakan_denda_remitan, 0 )) as remisyen,
    nvl ( ct.cukai_awal, 0 ) +  nvl ( ct.tunggakan_cukai_awal, 0 ) +  nvl ( ct.tunggakan_denda_awal, 0 ) + nvl(tunggakan_cukai_atas_petak_awal,0)
    INTO v_bil_cukai_tahunan_id, v_baki_akhir, v_denda, v_denda_remitan, v_lebih_bayar, v_jumlah_remitan, v_jumlah_awal
    FROM hsl_bil_cukai_tahunan ct
    WHERE  tahun =p_tahun AND akaun_cukai_id = (SELECT akaun_cukai_id FROM hsl_akaun_cukai WHERE no_akaun =p_no_akaun);  
    RAISE NOTICE 'v_jumlah_awal = %', v_jumlah_awal;
    RAISE NOTICE 'v_jumlah_remitan = %', v_jumlah_remitan;
    
    IF v_baki_akhir > 0 THEN 

            SELECT SUM(jumlah)  INTO v_jumlah_bayaran
                FROM hsl_bayaran A
            WHERE flag_batal = 'N' 
            AND bil_cukai_tahunan_id =v_bil_cukai_tahunan_id; 
            RAISE NOTICE 'v_jumlah_bayaran = %' , v_jumlah_bayaran;

            SELECT SUM(
                      NVL ( TO_NUMBER ( JSON_VALUE ( dis.diskaun, '$.cukaiTanah' )),0 ) +
               NVL ( TO_NUMBER ( JSON_VALUE ( dis.diskaun, '$.tunggakanDenda' )),0 ) +
               NVL ( TO_NUMBER ( JSON_VALUE ( dis.diskaun, '$.denda' )),0 ) +
               NVL ( TO_NUMBER ( JSON_VALUE ( dis.diskaun, '$.tunggakanCukaiTanahAtasPetak' )),0 ) + 
               NVL ( TO_NUMBER ( JSON_VALUE ( dis.diskaun, '$.tunggakanCukaiTanah' )),0)) ,
               SUM(NVL ( TO_NUMBER ( JSON_VALUE ( dis.diskaun, '$.denda' ) ),0))
               INTO v_jumlah_diskaun, v_denda_diskaun
            FROM hsl_pemberian_diskaun_cukai dis
            WHERE cukai_tahunan_id = v_bil_cukai_tahunan_id 
            AND flag_diskaun_segera='Y';
            RAISE NOTICE 'v_jumlah_diskaun = %' , v_jumlah_diskaun;
          
            SELECT SUM(debit) - SUM(kredit),
            SUM(DECODE(catatan,'Pelarasan Fi Tunggakan Semasa',  debit, 0)) - SUM(DECODE(catatan,'Pelarasan Fi Tunggakan Semasa',  kredit, 0) )
            INTO  v_jumlah_pelarasan, v_denda_pelarasan
            FROM hsl_penyata_akaun
            WHERE catatan IN ('Pelarasan Tunggakan Cukai',  'Pelarasan Cukai',
            'Pelarasan Fi Tunggakan', 'Pelarasan Tunggakan Cukai Tanah Atas Petak', 'Pelarasan Fi Tunggakan Semasa') 
            AND  sumber IN ( 'PELARASAN', 'PFT' )  
            AND no_akaun = p_no_akaun
            AND tahun= p_tahun;
            RAISE NOTICE 'v_jumlah_pelarasan = %' , v_jumlah_pelarasan;

            v_tunggakan := v_jumlah_awal - v_lebih_bayar  + nvl(v_jumlah_pelarasan,0) - nvl(v_jumlah_diskaun,0) - nvl(v_jumlah_remitan,0) - nvl(v_jumlah_bayaran,0);
            RAISE NOTICE 'v_tunggakan = %' , v_tunggakan;

            v_denda_baki := nvl(v_denda,0) + nvl(v_denda_pelarasan,0) - nvl(v_denda_diskaun,0) - nvl(v_denda_remitan,0);
            RAISE NOTICE 'v_denda_baki = %' , v_denda_baki;

            IF v_tunggakan > v_denda_baki   THEN
                IF v_denda_baki > 0 THEN
                    v_fi_tunggakan := v_denda_baki;
                ELSE   
                    IF (v_tunggakan <= 10) THEN 
                        v_fi_tunggakan :=1.00; 
                    ELSIF (v_tunggakan BETWEEN 10.01 AND 50.00) THEN
                        v_fi_tunggakan :=2.00; 
                    ELSIF (v_tunggakan BETWEEN 50.01 AND 100.00) THEN
                        v_fi_tunggakan  :=5.00;
                    ELSIF (v_tunggakan > 100) THEN 
                        v_fi_tunggakan := (floor(((v_tunggakan) ) *(0.07)) + ceil(MOD(((v_tunggakan)) * 0.07,1) *10)/10);
                    END IF;
                END IF;
            ELSE
                IF v_tunggakan <= 0 THEN
                    if v_denda_baki > 0 THEN
                        v_fi_tunggakan := v_denda_baki;
                    ELSE
                        v_fi_tunggakan :=0;
                    END IF;
                ELSE 
                    v_fi_tunggakan := v_tunggakan;
                END IF;
            END IF;

    END IF;

   	RAISE NOTICE 'v_fi_tunggakan = %' , v_fi_tunggakan;
    RETURN v_fi_tunggakan;


END;
$function$
;

-- DROP FUNCTION et_main_uat.convertnumber(int4);

CREATE OR REPLACE FUNCTION et_main_uat.convertnumber(in_nombor integer)
 RETURNS character varying
 LANGUAGE plpgsql
AS $function$
DECLARE
NOMBOR  integer := ABS ( IN_NOMBOR );
SEN1      VARCHAR2(1);
SEN2      VARCHAR2(1);
SA        VARCHAR2(1);
PULUH     VARCHAR2(1);
RATUS     VARCHAR2(1);
RIBU      VARCHAR2(1);
PRIBU     VARCHAR2(1);
RRIBU     VARCHAR2(1);
JUTA      VARCHAR2(1);
PJUTA     VARCHAR2(1);
RJUTA     VARCHAR2(1);
BILION    VARCHAR2(1);
XSEN1     VARCHAR2(20);
XSEN2     VARCHAR2(20);
XSA       VARCHAR2(20);
XPULUH    VARCHAR2(20);
XRATUS    VARCHAR2(20);
XRIBU     VARCHAR2(20);
XPRIBU    VARCHAR2(20);
XRRIBU    VARCHAR2(20);
XJUTA     VARCHAR2(20);
XPJUTA    VARCHAR2(20);
XRJUTA    VARCHAR2(20);
XBILION   VARCHAR2(20);
SEN       VARCHAR2(500);
SATU      VARCHAR2(500);
DUA       VARCHAR2(500);
TIGA      VARCHAR2(500);
EMPAT     VARCHAR2(500);
LIMA      VARCHAR2(500);
ENAM      VARCHAR2(500);
TUJUH     VARCHAR2(500);

BEGIN
SELECT  SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -1, 1 ), SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -2, 1 ),
        SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -4, 1 ), SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -5, 1 ),
        SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -6, 1 ), SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -7, 1 ),
        SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -8, 1 ), SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -9, 1 ),
        SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -10, 1 ), SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -11, 1 ),
        SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -12, 1 ), SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -13, 1 )
INTO    SEN1, SEN2, SA, PULUH, RATUS, RIBU, PRIBU, RRIBU, JUTA, PJUTA, RJUTA, BILION
FROM    DUAL;

--Bilion
IF BILION = '1' THEN
    XBILION := 'Satu Bilion ';
ELSIF BILION = '2' THEN
    XBILION := 'Dua Bilion ';
ELSIF BILION = '3' THEN
    XBILION := 'Tiga Bilion ';
ELSIF BILION = '4' THEN
    XBILION := 'Empat Bilion ';
ELSIF BILION = '5' THEN
    XBILION := 'Lima Bilion ';
ELSIF BILION = '6' THEN
    XBILION := 'Enam Bilion ';
ELSIF BILION = '7' THEN
    XBILION := 'Tujuh Bilion ';
ELSIF BILION = '8' THEN
    XBILION := 'Lapan Bilion ';
ELSIF BILION = '9' THEN
    XBILION := 'Sembilan Bilion ';
ELSE
    XBILION := NULL;
END IF;

--Ratus Juta
IF RJUTA = '1' THEN
    XRJUTA := 'Satu Ratus ';
ELSIF RJUTA = '2' THEN
    XRJUTA := 'Dua Ratus ';
ELSIF RJUTA = '3' THEN
    XRJUTA := 'Tiga Ratus ';
ELSIF RJUTA = '4' THEN
    XRJUTA := 'Empat Ratus ';
ELSIF RJUTA = '5' THEN
    XRJUTA := 'Lima Ratus ';
ELSIF RJUTA = '6' THEN
    XRJUTA := 'Enam Ratus ';
ELSIF RJUTA = '7' THEN
    XRJUTA := 'Tujuh Ratus ';
ELSIF RJUTA = '8' THEN
    XRJUTA := 'Lapan Ratus ';
ELSIF RJUTA = '9' THEN
    XRJUTA := 'Sembilan Ratus ';
ELSE
    XRJUTA := NULL;
END IF;

--Puluh Juta
IF PJUTA = '1' THEN
    IF JUTA = '0' THEN
        XPJUTA := 'Sepuluh ';
    ELSIF JUTA = '1' THEN
        XPJUTA := 'Sebelas ';
    ELSIF JUTA = '2' THEN
        XPJUTA := 'Dua Belas ';
    ELSIF JUTA = '3' THEN
        XPJUTA := 'Tiga Belas ';
    ELSIF JUTA = '4' THEN
        XPJUTA := 'Empat Belas ';
    ELSIF JUTA = '5' THEN
        XPJUTA := 'Lima Belas ';
    ELSIF JUTA = '6' THEN
        XPJUTA := 'Enam Belas ';
    ELSIF JUTA = '7' THEN
        XPJUTA := 'Tujuh Belas ';
    ELSIF JUTA = '8' THEN
        XPJUTA := 'Lapan Belas ';
    ELSIF JUTA = '9' THEN
        XPJUTA := 'Sembilan Belas ';
    END IF;
ELSIF PJUTA = '2' THEN
    XPJUTA := 'Dua Puluh ';
ELSIF PJUTA = '3' THEN
    XPJUTA := 'Tiga Puluh ';
ELSIF PJUTA = '4' THEN
    XPJUTA := 'Empat Puluh ';
ELSIF PJUTA = '5' THEN
    XPJUTA := 'Lima Puluh ';
ELSIF PJUTA = '6' THEN
    XPJUTA := 'Enam Puluh ';
ELSIF PJUTA = '7' THEN
    XPJUTA := 'Tujuh Puluh ';
ELSIF PJUTA = '8' THEN
    XPJUTA := 'Lapan Puluh ';
ELSIF PJUTA = '9' THEN
    XPJUTA := 'Sembilan Puluh ';
ELSE
    XPJUTA := NULL;
END IF;

--Juta
IF JUTA = '1' THEN
    XJUTA := 'Satu Juta ';
ELSIF JUTA = '2' THEN
    XJUTA := 'Dua Juta ';
ELSIF JUTA = '3' THEN
    XJUTA := 'Tiga Juta ';
ELSIF JUTA = '4' THEN
    XJUTA := 'Empat Juta ';
ELSIF JUTA = '5' THEN
    XJUTA := 'Lima Juta ';
ELSIF JUTA = '6' THEN
    XJUTA := 'Enam Juta ';
ELSIF JUTA = '7' THEN
    XJUTA := 'Tujuh Juta ';
ELSIF JUTA = '8' THEN
    XJUTA := 'Lapan Juta ';
ELSIF JUTA = '9' THEN
    XJUTA := 'Sembilan Juta ';
ELSE
    XJUTA := NULL;
END IF;

--Ratus Ribu
IF RRIBU = '1' THEN
    XRRIBU := 'Satu Ratus ';
ELSIF RRIBU = '2' THEN
    XRRIBU := 'Dua Ratus ';
ELSIF RRIBU = '3' THEN
    XRRIBU := 'Tiga Ratus ';
ELSIF RRIBU = '4' THEN
    XRRIBU := 'Empat Ratus ';
ELSIF RRIBU = '5' THEN
    XRRIBU := 'Lima Ratus ';
ELSIF RRIBU = '6' THEN
    XRRIBU := 'Enam Ratus ';
ELSIF RRIBU = '7' THEN
    XRRIBU := 'Tujuh Ratus ';
ELSIF RRIBU = '8' THEN
    XRRIBU := 'Lapan Ratus ';
ELSIF RRIBU = '9' THEN
    XRRIBU := 'Sembilan Ratus ';
ELSE
    XRRIBU := NULL;
END IF;

--Puluh Ribu
IF PRIBU = '1' THEN
    XPRIBU := 'Sepuluh ';
ELSIF PRIBU = '2' THEN
    XPRIBU := 'Dua Puluh ';
ELSIF PRIBU = '3' THEN
    XPRIBU := 'Tiga Puluh ';
ELSIF PRIBU = '4' THEN
    XPRIBU := 'Empat Puluh ';
ELSIF PRIBU = '5' THEN
    XPRIBU := 'Lima Puluh ';
ELSIF PRIBU = '6' THEN
    XPRIBU := 'Enam Puluh ';
ELSIF PRIBU = '7' THEN
    XPRIBU := 'Tujuh Puluh ';
ELSIF PRIBU = '8' THEN
    XPRIBU := 'Lapan Puluh ';
ELSIF PRIBU = '9' THEN
    XPRIBU := 'Sembilan Puluh ';
ELSE
    XPRIBU := NULL;
END IF;

--Ribu
IF RIBU = '1' THEN
    XRIBU := 'Satu Ribu ';
ELSIF RIBU = '2' THEN
    XRIBU := 'Dua Ribu ';
ELSIF RIBU = '3' THEN
    XRIBU := 'Tiga Ribu ';
ELSIF RIBU = '4' THEN
    XRIBU := 'Empat Ribu ';
ELSIF RIBU = '5' THEN
    XRIBU := 'Lima Ribu ';
ELSIF RIBU = '6' THEN
    XRIBU := 'Enam Ribu ';
ELSIF RIBU = '7' THEN
    XRIBU := 'Tujuh Ribu ';
ELSIF RIBU = '8' THEN
    XRIBU := 'Lapan Ribu ';
ELSIF RIBU = '9' THEN
    XRIBU := 'Sembilan Ribu ';
ELSE
    XRIBU := NULL;
END IF;

--Ratus
IF RATUS = '1' THEN
    XRATUS := 'Satu Ratus ';
ELSIF RATUS = '2' THEN
    XRATUS := 'Dua Ratus ';
ELSIF RATUS = '3' THEN
    XRATUS := 'Tiga Ratus ';
ELSIF RATUS = '4' THEN
    XRATUS := 'Empat Ratus ';
ELSIF RATUS = '5' THEN
    XRATUS := 'Lima Ratus ';
ELSIF RATUS = '6' THEN
    XRATUS := 'Enam Ratus ';
ELSIF RATUS = '7' THEN
    XRATUS := 'Tujuh Ratus ';
ELSIF RATUS = '8' THEN
    XRATUS := 'Lapan Ratus ';
ELSIF RATUS = '9' THEN
    XRATUS := 'Sembilan Ratus ';
END IF;

--Puluh
IF PULUH = '1' THEN
    IF SA = '0' THEN
        XPULUH := 'Sepuluh ';
    ELSIF SA = '1' THEN
        XPULUH := 'Sebelas ';
    ELSIF SA = '2' THEN
        XPULUH := 'Dua Belas ';
    ELSIF SA = '3' THEN
        XPULUH := 'Tiga Belas ';
    ELSIF SA = '4' THEN
        XPULUH := 'Empat Belas ';
    ELSIF SA = '5' THEN
        XPULUH := 'Lima Belas ';
    ELSIF SA = '6' THEN
        XPULUH := 'Enam Belas ';
    ELSIF SA = '7' THEN
        XPULUH := 'Tujuh Belas ';
    ELSIF SA = '8' THEN
        XPULUH := 'Lapan Belas ';
    ELSIF SA = '9' THEN
        XPULUH := 'Sembilan Belas ';
    END IF;
ELSIF PULUH = '2' THEN
    XPULUH := 'Dua Puluh ';
ELSIF PULUH = '3' THEN
    XPULUH := 'Tiga Puluh ';
ELSIF PULUH = '4' THEN
    XPULUH := 'Empat Puluh ';
ELSIF PULUH = '5' THEN
    XPULUH := 'Lima Puluh ';
ELSIF PULUH = '6' THEN
    XPULUH := 'Enam Puluh ';
ELSIF PULUH = '7' THEN
    XPULUH := 'Tujuh Puluh ';
ELSIF PULUH = '8' THEN
    XPULUH := 'Lapan Puluh ';
ELSIF PULUH = '9' THEN
    XPULUH := 'Sembilan Puluh ';
END IF;

--Sa
IF SA = '1' THEN
    XSA := 'Satu ';
ELSIF SA = '2' THEN
    XSA := 'Dua ';
ELSIF SA = '3' THEN
    XSA := 'Tiga ';
ELSIF SA = '4' THEN
    XSA := 'Empat ';
ELSIF SA = '5' THEN
    XSA := 'Lima ';
ELSIF SA = '6' THEN
    XSA := 'Enam ';
ELSIF SA = '7' THEN
    XSA := 'Tujuh ';
ELSIF SA = '8' THEN
    XSA := 'Lapan ';
ELSIF SA = '9' THEN
    XSA := 'Sembilan ';
END IF;

--Sen Decimal ke 2
IF SEN1 = '0' THEN
    XSEN1 := '';
ELSIF SEN1 =  '1' THEN
    XSEN1 := 'Satu ';
ELSIF SEN1 = '2' THEN
    XSEN1 := 'Dua ';
ELSIF SEN1 = '3' THEN
    XSEN1 := 'Tiga ';
ELSIF SEN1 = '4' THEN
    XSEN1 := 'Empat ';
ELSIF SEN1 = '5' THEN
    XSEN1 := 'Lima ';
ELSIF SEN1 = '6' THEN
    XSEN1 := 'Enam ';
ELSIF SEN1 = '7' THEN
    XSEN1 := 'Tujuh ';
ELSIF SEN1 = '8' THEN
    XSEN1 := 'Lapan ';
ELSIF SEN1 = '9' THEN
    XSEN1 := 'Sembilan ';
END IF;

--Sen Decimal pertama
IF SEN2 = '1' THEN
    IF SEN1 = '0' THEN
        XSEN2 := 'Sepuluh ';
    ELSIF SEN1 = '1' THEN
        XSEN2 := 'Sebelas ';
    ELSIF SEN1 = '2' THEN
        XSEN2 := 'Dua Belas ';
    ELSIF SEN1 = '3' THEN
        XSEN2 := 'Tiga Belas ';
    ELSIF SEN1 = '4' THEN
        XSEN2 := 'Empat Belas ';
    ELSIF SEN1 = '5' THEN
        XSEN2 := 'Lima Belas ';
    ELSIF SEN1 = '6' THEN
        XSEN2 := 'Enam Belas ';
    ELSIF SEN1 = '7' THEN
        XSEN2 := 'Tujuh Belas ';
    ELSIF SEN1 = '8' THEN
        XSEN2 := 'Lapan Belas ';
    ELSIF SEN1 = '9' THEN
        XSEN2 := 'Sembilan Belas ';
    END IF;
ELSIF SEN2 = '2' THEN
    XSEN2 := 'Dua Puluh ';
ELSIF SEN2 = '3' THEN
    XSEN2 := 'Tiga Puluh ';
ELSIF SEN2 = '4' THEN
    XSEN2 := 'Empat Puluh ';
ELSIF SEN2 = '5' THEN
    XSEN2 := 'Lima Puluh ';
ELSIF SEN2 = '6' THEN
    XSEN2 := 'Enam Puluh ';
ELSIF SEN2 = '7' THEN
    XSEN2 := 'Tujuh Puluh ';
ELSIF SEN2 = '8' THEN
    XSEN2 := 'Lapan Puluh ';
ELSIF SEN2 = '9' THEN
    XSEN2 := 'Sembilan Puluh ';
END IF;

IF SEN2 = '0' THEN
    IF SEN1 = '0' THEN
       SEN := NULL;
    ELSE
       SEN := XSEN1;
    END IF;
ELSIF SEN2 = '1' THEN
    SEN := XSEN2;
ELSE
    SEN := XSEN2 || XSEN1;
END IF;

-- Condition Puluh
IF PULUH = '0' OR PULUH IS NULL THEN
    IF XSA IS NOT NULL THEN
        SATU := XSA;
    ELSE
        SATU := NULL;
    END IF;
ELSIF PULUH = '1' THEN
    SATU := XPULUH;
ELSE
    SATU := XPULUH || XSA;
END IF;

-- Condition Ratus
IF RATUS IS NULL OR RATUS = '0' THEN
    DUA := NULL;
ELSE
    DUA := XRATUS;
END IF;

-- Condition Puluh Ribu and Ribu
IF PRIBU IS NULL OR PRIBU = '0' THEN
    IF RIBU IS NOT NULL THEN
        TIGA := XRIBU;
    ELSE
        TIGA := NULL;
    END IF;

ELSIF PRIBU = '1' THEN
    IF RIBU = '0' THEN
        TIGA := 'Sepuluh Ribu ';
    ELSIF RIBU = '1' THEN
        TIGA := 'Sebelas Ribu ';
    ELSIF RIBU = '2' THEN
        TIGA := 'Dua Belas Ribu ';
    ELSIF RIBU = '3' THEN
        TIGA := 'Tiga Belas Ribu ';
    ELSIF RIBU = '4' THEN
        TIGA := 'Empat Belas Ribu ';
    ELSIF RIBU = '5' THEN
        TIGA := 'Lima Belas Ribu ';
    ELSIF RIBU = '6' THEN
        TIGA := 'Enam Belas Ribu ';
    ELSIF RIBU = '7' THEN
        TIGA := 'Tujuh Belas Ribu ';
    ELSIF RIBU = '8' THEN
        TIGA := 'Lapan Belas Ribu ';
    ELSIF RIBU = '9' THEN
        TIGA := 'Sembilan Belas Ribu ';
    END IF;

ELSE
    IF RIBU = '0' THEN
        TIGA := XPRIBU || 'Ribu ';
    ELSE
        TIGA := XPRIBU || XRIBU;
    END IF;
    
END IF;

-- Condition to gabung number from Puluh Ribu until Sa
IF TIGA IS NOT NULL AND DUA IS NOT NULL AND SATU IS NOT NULL THEN 
	EMPAT := TIGA || DUA || SATU;
ELSIF TIGA IS NOT NULL AND DUA IS NOT NULL AND SATU IS NULL THEN 
	EMPAT := TIGA || DUA;
ELSIF TIGA IS NOT NULL AND DUA IS NULL AND SATU IS NOT NULL THEN 
	EMPAT := TIGA || SATU;
ELSIF TIGA IS NULL AND DUA IS NOT NULL AND SATU IS NOT NULL THEN 
	EMPAT := DUA || SATU;
ELSIF TIGA IS NOT NULL AND DUA IS NULL AND SATU IS NULL THEN 
	EMPAT := TIGA;
ELSIF TIGA IS NULL AND DUA IS NOT NULL AND SATU IS NULL THEN 
	EMPAT := DUA;
ELSIF TIGA IS NULL AND DUA IS NULL AND SATU IS NOT NULL THEN 
	EMPAT := SATU;
END IF;

-- Gabung Puluh Ribu until Sa with Sen
IF SEN IS NOT NULL AND EMPAT IS NOT NULL THEN
    LIMA := EMPAT || 'dan ' || SEN || 'Sen ';
ELSIF SEN IS NULL AND EMPAT IS NOT NULL THEN
    LIMA := EMPAT;
ELSIF SEN IS NOT NULL AND EMPAT IS NULL THEN
    IF XRRIBU IS NULL AND XJUTA IS NULL THEN
        LIMA := SEN || 'Sen ';
    ELSE
        LIMA := SEN || 'Sen ';
    END IF;
END IF;

-- Condition Ratus Ribu and Juta
IF XRRIBU IS NULL AND XJUTA IS NULL THEN
    ENAM := LIMA;

ELSIF XRRIBU IS NOT NULL AND XJUTA IS NULL THEN
    IF XPRIBU IS NULL AND XRIBU IS NULL THEN
        ENAM := XRRIBU || 'Ribu ' || LIMA;
    ELSE
        ENAM := XRRIBU || LIMA;
    END IF;

ELSIF XRRIBU IS NULL AND XJUTA IS NOT NULL THEN
    IF XPRIBU IS NULL AND XRIBU IS NULL THEN
        ENAM := XJUTA || LIMA;
    ELSIF PRIBU != '0' AND RIBU != '0' THEN      
        ENAM := XJUTA || LIMA;
    ELSE
        ENAM := XJUTA || XRRIBU || LIMA;
    END IF;

ELSIF XRRIBU IS NOT NULL AND XJUTA IS NOT NULL THEN
    IF PJUTA = '1' THEN
        IF XPRIBU IS NULL AND XRIBU IS NULL THEN
            ENAM := XRRIBU || 'Ribu ' || LIMA;
        ELSE
            ENAM := XRRIBU || LIMA;
        END IF;
    ELSE
        ENAM := XJUTA || XRRIBU || LIMA;
    END IF;
    
END IF;

-- Condition for Puluh Juta and Juta and Ratus Ribu
IF XPJUTA IS NULL AND XRJUTA IS NULL THEN
    TUJUH := ENAM;
    
ELSIF XPJUTA IS NOT NULL AND XRJUTA IS NULL THEN
    IF XRRIBU IS NULL AND XJUTA IS NULL THEN
        IF PJUTA = '1' THEN
            TUJUH := XPJUTA || 'Juta ' || ENAM;
        ELSE
            TUJUH := XPJUTA || 'Juta ' || ENAM;
        END IF;
    ELSIF XJUTA IS NOT NULL THEN
        IF PJUTA = '1' THEN
            TUJUH := XPJUTA || 'Juta ' || ENAM;
        ELSE
            TUJUH := XPJUTA || ENAM;
        END IF;
    END IF;
        
ELSIF XPJUTA IS NULL AND XRJUTA IS NOT NULL THEN
    IF XRRIBU IS NULL AND XJUTA IS NULL THEN
        TUJUH := XRJUTA || 'Juta ' || ENAM;
    ELSIF XRRIBU != '0' AND XJUTA != '0' THEN
        TUJUH := XRJUTA || XJUTA || 'Juta ' || ENAM;
    END IF;
    
ELSIF XPJUTA IS NOT NULL AND XRJUTA IS NOT NULL THEN
    IF XRRIBU IS NULL AND XJUTA IS NULL THEN  
        TUJUH := XRJUTA || XPJUTA || 'Juta ' || ENAM;            
    ELSE
        TUJUH := XRJUTA || XPJUTA || ENAM;
    END IF;
    
END IF;

-- Condition Bilion and Ratus Juta
IF TUJUH IS NULL AND XBILION IS NULL THEN
    RETURN ( 'Tiada' );
ELSIF TUJUH IS NOT NULL AND XBILION IS NULL THEN
    RETURN ( TUJUH || 'Sahaja' );
ELSIF TUJUH IS NULL AND XBILION IS NOT NULL THEN
    RETURN ( XBILION || 'Sahaja' );
ELSE
    RETURN ( XBILION || TUJUH || 'Sahaja' );
END IF;

END;
$function$
;

-- DROP FUNCTION et_main_uat.convertnumber(numeric);

CREATE OR REPLACE FUNCTION et_main_uat.convertnumber(in_nombor numeric)
 RETURNS character varying
 LANGUAGE plpgsql
AS $function$
DECLARE
NOMBOR  numeric := ABS ( IN_NOMBOR );
SEN1      VARCHAR2(1);
SEN2      VARCHAR2(1);
SA        VARCHAR2(1);
PULUH     VARCHAR2(1);
RATUS     VARCHAR2(1);
RIBU      VARCHAR2(1);
PRIBU     VARCHAR2(1);
RRIBU     VARCHAR2(1);
JUTA      VARCHAR2(1);
PJUTA     VARCHAR2(1);
RJUTA     VARCHAR2(1);
BILION    VARCHAR2(1);
XSEN1     VARCHAR2(20);
XSEN2     VARCHAR2(20);
XSA       VARCHAR2(20);
XPULUH    VARCHAR2(20);
XRATUS    VARCHAR2(20);
XRIBU     VARCHAR2(20);
XPRIBU    VARCHAR2(20);
XRRIBU    VARCHAR2(20);
XJUTA     VARCHAR2(20);
XPJUTA    VARCHAR2(20);
XRJUTA    VARCHAR2(20);
XBILION   VARCHAR2(20);
SEN       VARCHAR2(500);
SATU      VARCHAR2(500);
DUA       VARCHAR2(500);
TIGA      VARCHAR2(500);
EMPAT     VARCHAR2(500);
LIMA      VARCHAR2(500);
ENAM      VARCHAR2(500);
TUJUH     VARCHAR2(500);

BEGIN
SELECT  SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -1, 1 ), SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -2, 1 ),
        SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -4, 1 ), SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -5, 1 ),
        SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -6, 1 ), SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -7, 1 ),
        SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -8, 1 ), SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -9, 1 ),
        SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -10, 1 ), SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -11, 1 ),
        SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -12, 1 ), SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -13, 1 )
INTO    SEN1, SEN2, SA, PULUH, RATUS, RIBU, PRIBU, RRIBU, JUTA, PJUTA, RJUTA, BILION
FROM    DUAL;

--Bilion
IF BILION = '1' THEN
    XBILION := 'Satu Bilion ';
ELSIF BILION = '2' THEN
    XBILION := 'Dua Bilion ';
ELSIF BILION = '3' THEN
    XBILION := 'Tiga Bilion ';
ELSIF BILION = '4' THEN
    XBILION := 'Empat Bilion ';
ELSIF BILION = '5' THEN
    XBILION := 'Lima Bilion ';
ELSIF BILION = '6' THEN
    XBILION := 'Enam Bilion ';
ELSIF BILION = '7' THEN
    XBILION := 'Tujuh Bilion ';
ELSIF BILION = '8' THEN
    XBILION := 'Lapan Bilion ';
ELSIF BILION = '9' THEN
    XBILION := 'Sembilan Bilion ';
ELSE
    XBILION := NULL;
END IF;

--Ratus Juta
IF RJUTA = '1' THEN
    XRJUTA := 'Satu Ratus ';
ELSIF RJUTA = '2' THEN
    XRJUTA := 'Dua Ratus ';
ELSIF RJUTA = '3' THEN
    XRJUTA := 'Tiga Ratus ';
ELSIF RJUTA = '4' THEN
    XRJUTA := 'Empat Ratus ';
ELSIF RJUTA = '5' THEN
    XRJUTA := 'Lima Ratus ';
ELSIF RJUTA = '6' THEN
    XRJUTA := 'Enam Ratus ';
ELSIF RJUTA = '7' THEN
    XRJUTA := 'Tujuh Ratus ';
ELSIF RJUTA = '8' THEN
    XRJUTA := 'Lapan Ratus ';
ELSIF RJUTA = '9' THEN
    XRJUTA := 'Sembilan Ratus ';
ELSE
    XRJUTA := NULL;
END IF;

--Puluh Juta
IF PJUTA = '1' THEN
    IF JUTA = '0' THEN
        XPJUTA := 'Sepuluh ';
    ELSIF JUTA = '1' THEN
        XPJUTA := 'Sebelas ';
    ELSIF JUTA = '2' THEN
        XPJUTA := 'Dua Belas ';
    ELSIF JUTA = '3' THEN
        XPJUTA := 'Tiga Belas ';
    ELSIF JUTA = '4' THEN
        XPJUTA := 'Empat Belas ';
    ELSIF JUTA = '5' THEN
        XPJUTA := 'Lima Belas ';
    ELSIF JUTA = '6' THEN
        XPJUTA := 'Enam Belas ';
    ELSIF JUTA = '7' THEN
        XPJUTA := 'Tujuh Belas ';
    ELSIF JUTA = '8' THEN
        XPJUTA := 'Lapan Belas ';
    ELSIF JUTA = '9' THEN
        XPJUTA := 'Sembilan Belas ';
    END IF;
ELSIF PJUTA = '2' THEN
    XPJUTA := 'Dua Puluh ';
ELSIF PJUTA = '3' THEN
    XPJUTA := 'Tiga Puluh ';
ELSIF PJUTA = '4' THEN
    XPJUTA := 'Empat Puluh ';
ELSIF PJUTA = '5' THEN
    XPJUTA := 'Lima Puluh ';
ELSIF PJUTA = '6' THEN
    XPJUTA := 'Enam Puluh ';
ELSIF PJUTA = '7' THEN
    XPJUTA := 'Tujuh Puluh ';
ELSIF PJUTA = '8' THEN
    XPJUTA := 'Lapan Puluh ';
ELSIF PJUTA = '9' THEN
    XPJUTA := 'Sembilan Puluh ';
ELSE
    XPJUTA := NULL;
END IF;

--Juta
IF JUTA = '1' THEN
    XJUTA := 'Satu Juta ';
ELSIF JUTA = '2' THEN
    XJUTA := 'Dua Juta ';
ELSIF JUTA = '3' THEN
    XJUTA := 'Tiga Juta ';
ELSIF JUTA = '4' THEN
    XJUTA := 'Empat Juta ';
ELSIF JUTA = '5' THEN
    XJUTA := 'Lima Juta ';
ELSIF JUTA = '6' THEN
    XJUTA := 'Enam Juta ';
ELSIF JUTA = '7' THEN
    XJUTA := 'Tujuh Juta ';
ELSIF JUTA = '8' THEN
    XJUTA := 'Lapan Juta ';
ELSIF JUTA = '9' THEN
    XJUTA := 'Sembilan Juta ';
ELSE
    XJUTA := NULL;
END IF;

--Ratus Ribu
IF RRIBU = '1' THEN
    XRRIBU := 'Satu Ratus ';
ELSIF RRIBU = '2' THEN
    XRRIBU := 'Dua Ratus ';
ELSIF RRIBU = '3' THEN
    XRRIBU := 'Tiga Ratus ';
ELSIF RRIBU = '4' THEN
    XRRIBU := 'Empat Ratus ';
ELSIF RRIBU = '5' THEN
    XRRIBU := 'Lima Ratus ';
ELSIF RRIBU = '6' THEN
    XRRIBU := 'Enam Ratus ';
ELSIF RRIBU = '7' THEN
    XRRIBU := 'Tujuh Ratus ';
ELSIF RRIBU = '8' THEN
    XRRIBU := 'Lapan Ratus ';
ELSIF RRIBU = '9' THEN
    XRRIBU := 'Sembilan Ratus ';
ELSE
    XRRIBU := NULL;
END IF;

--Puluh Ribu
IF PRIBU = '1' THEN
    XPRIBU := 'Sepuluh ';
ELSIF PRIBU = '2' THEN
    XPRIBU := 'Dua Puluh ';
ELSIF PRIBU = '3' THEN
    XPRIBU := 'Tiga Puluh ';
ELSIF PRIBU = '4' THEN
    XPRIBU := 'Empat Puluh ';
ELSIF PRIBU = '5' THEN
    XPRIBU := 'Lima Puluh ';
ELSIF PRIBU = '6' THEN
    XPRIBU := 'Enam Puluh ';
ELSIF PRIBU = '7' THEN
    XPRIBU := 'Tujuh Puluh ';
ELSIF PRIBU = '8' THEN
    XPRIBU := 'Lapan Puluh ';
ELSIF PRIBU = '9' THEN
    XPRIBU := 'Sembilan Puluh ';
ELSE
    XPRIBU := NULL;
END IF;

--Ribu
IF RIBU = '1' THEN
    XRIBU := 'Satu Ribu ';
ELSIF RIBU = '2' THEN
    XRIBU := 'Dua Ribu ';
ELSIF RIBU = '3' THEN
    XRIBU := 'Tiga Ribu ';
ELSIF RIBU = '4' THEN
    XRIBU := 'Empat Ribu ';
ELSIF RIBU = '5' THEN
    XRIBU := 'Lima Ribu ';
ELSIF RIBU = '6' THEN
    XRIBU := 'Enam Ribu ';
ELSIF RIBU = '7' THEN
    XRIBU := 'Tujuh Ribu ';
ELSIF RIBU = '8' THEN
    XRIBU := 'Lapan Ribu ';
ELSIF RIBU = '9' THEN
    XRIBU := 'Sembilan Ribu ';
ELSE
    XRIBU := NULL;
END IF;

--Ratus
IF RATUS = '1' THEN
    XRATUS := 'Satu Ratus ';
ELSIF RATUS = '2' THEN
    XRATUS := 'Dua Ratus ';
ELSIF RATUS = '3' THEN
    XRATUS := 'Tiga Ratus ';
ELSIF RATUS = '4' THEN
    XRATUS := 'Empat Ratus ';
ELSIF RATUS = '5' THEN
    XRATUS := 'Lima Ratus ';
ELSIF RATUS = '6' THEN
    XRATUS := 'Enam Ratus ';
ELSIF RATUS = '7' THEN
    XRATUS := 'Tujuh Ratus ';
ELSIF RATUS = '8' THEN
    XRATUS := 'Lapan Ratus ';
ELSIF RATUS = '9' THEN
    XRATUS := 'Sembilan Ratus ';
END IF;

--Puluh
IF PULUH = '1' THEN
    IF SA = '0' THEN
        XPULUH := 'Sepuluh ';
    ELSIF SA = '1' THEN
        XPULUH := 'Sebelas ';
    ELSIF SA = '2' THEN
        XPULUH := 'Dua Belas ';
    ELSIF SA = '3' THEN
        XPULUH := 'Tiga Belas ';
    ELSIF SA = '4' THEN
        XPULUH := 'Empat Belas ';
    ELSIF SA = '5' THEN
        XPULUH := 'Lima Belas ';
    ELSIF SA = '6' THEN
        XPULUH := 'Enam Belas ';
    ELSIF SA = '7' THEN
        XPULUH := 'Tujuh Belas ';
    ELSIF SA = '8' THEN
        XPULUH := 'Lapan Belas ';
    ELSIF SA = '9' THEN
        XPULUH := 'Sembilan Belas ';
    END IF;
ELSIF PULUH = '2' THEN
    XPULUH := 'Dua Puluh ';
ELSIF PULUH = '3' THEN
    XPULUH := 'Tiga Puluh ';
ELSIF PULUH = '4' THEN
    XPULUH := 'Empat Puluh ';
ELSIF PULUH = '5' THEN
    XPULUH := 'Lima Puluh ';
ELSIF PULUH = '6' THEN
    XPULUH := 'Enam Puluh ';
ELSIF PULUH = '7' THEN
    XPULUH := 'Tujuh Puluh ';
ELSIF PULUH = '8' THEN
    XPULUH := 'Lapan Puluh ';
ELSIF PULUH = '9' THEN
    XPULUH := 'Sembilan Puluh ';
END IF;

--Sa
IF SA = '1' THEN
    XSA := 'Satu ';
ELSIF SA = '2' THEN
    XSA := 'Dua ';
ELSIF SA = '3' THEN
    XSA := 'Tiga ';
ELSIF SA = '4' THEN
    XSA := 'Empat ';
ELSIF SA = '5' THEN
    XSA := 'Lima ';
ELSIF SA = '6' THEN
    XSA := 'Enam ';
ELSIF SA = '7' THEN
    XSA := 'Tujuh ';
ELSIF SA = '8' THEN
    XSA := 'Lapan ';
ELSIF SA = '9' THEN
    XSA := 'Sembilan ';
END IF;

--Sen Decimal ke 2
IF SEN1 = '0' THEN
    XSEN1 := '';
ELSIF SEN1 =  '1' THEN
    XSEN1 := 'Satu ';
ELSIF SEN1 = '2' THEN
    XSEN1 := 'Dua ';
ELSIF SEN1 = '3' THEN
    XSEN1 := 'Tiga ';
ELSIF SEN1 = '4' THEN
    XSEN1 := 'Empat ';
ELSIF SEN1 = '5' THEN
    XSEN1 := 'Lima ';
ELSIF SEN1 = '6' THEN
    XSEN1 := 'Enam ';
ELSIF SEN1 = '7' THEN
    XSEN1 := 'Tujuh ';
ELSIF SEN1 = '8' THEN
    XSEN1 := 'Lapan ';
ELSIF SEN1 = '9' THEN
    XSEN1 := 'Sembilan ';
END IF;

--Sen Decimal pertama
IF SEN2 = '1' THEN
    IF SEN1 = '0' THEN
        XSEN2 := 'Sepuluh ';
    ELSIF SEN1 = '1' THEN
        XSEN2 := 'Sebelas ';
    ELSIF SEN1 = '2' THEN
        XSEN2 := 'Dua Belas ';
    ELSIF SEN1 = '3' THEN
        XSEN2 := 'Tiga Belas ';
    ELSIF SEN1 = '4' THEN
        XSEN2 := 'Empat Belas ';
    ELSIF SEN1 = '5' THEN
        XSEN2 := 'Lima Belas ';
    ELSIF SEN1 = '6' THEN
        XSEN2 := 'Enam Belas ';
    ELSIF SEN1 = '7' THEN
        XSEN2 := 'Tujuh Belas ';
    ELSIF SEN1 = '8' THEN
        XSEN2 := 'Lapan Belas ';
    ELSIF SEN1 = '9' THEN
        XSEN2 := 'Sembilan Belas ';
    END IF;
ELSIF SEN2 = '2' THEN
    XSEN2 := 'Dua Puluh ';
ELSIF SEN2 = '3' THEN
    XSEN2 := 'Tiga Puluh ';
ELSIF SEN2 = '4' THEN
    XSEN2 := 'Empat Puluh ';
ELSIF SEN2 = '5' THEN
    XSEN2 := 'Lima Puluh ';
ELSIF SEN2 = '6' THEN
    XSEN2 := 'Enam Puluh ';
ELSIF SEN2 = '7' THEN
    XSEN2 := 'Tujuh Puluh ';
ELSIF SEN2 = '8' THEN
    XSEN2 := 'Lapan Puluh ';
ELSIF SEN2 = '9' THEN
    XSEN2 := 'Sembilan Puluh ';
END IF;

IF SEN2 = '0' THEN
    IF SEN1 = '0' THEN
       SEN := NULL;
    ELSE
       SEN := XSEN1;
    END IF;
ELSIF SEN2 = '1' THEN
    SEN := XSEN2;
ELSE
    SEN := XSEN2 || XSEN1;
END IF;

-- Condition Puluh
IF PULUH = '0' OR PULUH IS NULL THEN
    IF XSA IS NOT NULL THEN
        SATU := XSA;
    ELSE
        SATU := NULL;
    END IF;
ELSIF PULUH = '1' THEN
    SATU := XPULUH;
ELSE
    SATU := XPULUH || XSA;
END IF;

-- Condition Ratus
IF RATUS IS NULL OR RATUS = '0' THEN
    DUA := NULL;
ELSE
    DUA := XRATUS;
END IF;

-- Condition Puluh Ribu and Ribu
IF PRIBU IS NULL OR PRIBU = '0' THEN
    IF RIBU IS NOT NULL THEN
        TIGA := XRIBU;
    ELSE
        TIGA := NULL;
    END IF;

ELSIF PRIBU = '1' THEN
    IF RIBU = '0' THEN
        TIGA := 'Sepuluh Ribu ';
    ELSIF RIBU = '1' THEN
        TIGA := 'Sebelas Ribu ';
    ELSIF RIBU = '2' THEN
        TIGA := 'Dua Belas Ribu ';
    ELSIF RIBU = '3' THEN
        TIGA := 'Tiga Belas Ribu ';
    ELSIF RIBU = '4' THEN
        TIGA := 'Empat Belas Ribu ';
    ELSIF RIBU = '5' THEN
        TIGA := 'Lima Belas Ribu ';
    ELSIF RIBU = '6' THEN
        TIGA := 'Enam Belas Ribu ';
    ELSIF RIBU = '7' THEN
        TIGA := 'Tujuh Belas Ribu ';
    ELSIF RIBU = '8' THEN
        TIGA := 'Lapan Belas Ribu ';
    ELSIF RIBU = '9' THEN
        TIGA := 'Sembilan Belas Ribu ';
    END IF;

ELSE
    IF RIBU = '0' THEN
        TIGA := XPRIBU || 'Ribu ';
    ELSE
        TIGA := XPRIBU || XRIBU;
    END IF;
    
END IF;

-- Condition to gabung number from Puluh Ribu until Sa
IF TIGA IS NOT NULL AND DUA IS NOT NULL AND SATU IS NOT NULL THEN 
	EMPAT := TIGA || DUA || SATU;
ELSIF TIGA IS NOT NULL AND DUA IS NOT NULL AND SATU IS NULL THEN 
	EMPAT := TIGA || DUA;
ELSIF TIGA IS NOT NULL AND DUA IS NULL AND SATU IS NOT NULL THEN 
	EMPAT := TIGA || SATU;
ELSIF TIGA IS NULL AND DUA IS NOT NULL AND SATU IS NOT NULL THEN 
	EMPAT := DUA || SATU;
ELSIF TIGA IS NOT NULL AND DUA IS NULL AND SATU IS NULL THEN 
	EMPAT := TIGA;
ELSIF TIGA IS NULL AND DUA IS NOT NULL AND SATU IS NULL THEN 
	EMPAT := DUA;
ELSIF TIGA IS NULL AND DUA IS NULL AND SATU IS NOT NULL THEN 
	EMPAT := SATU;
END IF;

-- Gabung Puluh Ribu until Sa with Sen
IF SEN IS NOT NULL AND EMPAT IS NOT NULL THEN
    LIMA := EMPAT || 'dan ' || SEN || 'Sen ';
ELSIF SEN IS NULL AND EMPAT IS NOT NULL THEN
    LIMA := EMPAT;
ELSIF SEN IS NOT NULL AND EMPAT IS NULL THEN
    IF XRRIBU IS NULL AND XJUTA IS NULL THEN
        LIMA := SEN || 'Sen ';
    ELSE
        LIMA := SEN || 'Sen ';
    END IF;
END IF;

-- Condition Ratus Ribu and Juta
IF XRRIBU IS NULL AND XJUTA IS NULL THEN
    ENAM := LIMA;

ELSIF XRRIBU IS NOT NULL AND XJUTA IS NULL THEN
    IF XPRIBU IS NULL AND XRIBU IS NULL THEN
        ENAM := XRRIBU || 'Ribu ' || LIMA;
    ELSE
        ENAM := XRRIBU || LIMA;
    END IF;

ELSIF XRRIBU IS NULL AND XJUTA IS NOT NULL THEN
    IF XPRIBU IS NULL AND XRIBU IS NULL THEN
        ENAM := XJUTA || LIMA;
    ELSIF PRIBU != '0' AND RIBU != '0' THEN      
        ENAM := XJUTA || LIMA;
    ELSE
        ENAM := XJUTA || XRRIBU || LIMA;
    END IF;

ELSIF XRRIBU IS NOT NULL AND XJUTA IS NOT NULL THEN
    IF PJUTA = '1' THEN
        IF XPRIBU IS NULL AND XRIBU IS NULL THEN
            ENAM := XRRIBU || 'Ribu ' || LIMA;
        ELSE
            ENAM := XRRIBU || LIMA;
        END IF;
    ELSE
        ENAM := XJUTA || XRRIBU || LIMA;
    END IF;
    
END IF;

-- Condition for Puluh Juta and Juta and Ratus Ribu
IF XPJUTA IS NULL AND XRJUTA IS NULL THEN
    TUJUH := ENAM;
    
ELSIF XPJUTA IS NOT NULL AND XRJUTA IS NULL THEN
    IF XRRIBU IS NULL AND XJUTA IS NULL THEN
        IF PJUTA = '1' THEN
            TUJUH := XPJUTA || 'Juta ' || ENAM;
        ELSE
            TUJUH := XPJUTA || 'Juta ' || ENAM;
        END IF;
    ELSIF XJUTA IS NOT NULL THEN
        IF PJUTA = '1' THEN
            TUJUH := XPJUTA || 'Juta ' || ENAM;
        ELSE
            TUJUH := XPJUTA || ENAM;
        END IF;
    END IF;
        
ELSIF XPJUTA IS NULL AND XRJUTA IS NOT NULL THEN
    IF XRRIBU IS NULL AND XJUTA IS NULL THEN
        TUJUH := XRJUTA || 'Juta ' || ENAM;
    ELSIF XRRIBU != '0' AND XJUTA != '0' THEN
        TUJUH := XRJUTA || XJUTA || 'Juta ' || ENAM;
    END IF;
    
ELSIF XPJUTA IS NOT NULL AND XRJUTA IS NOT NULL THEN
    IF XRRIBU IS NULL AND XJUTA IS NULL THEN  
        TUJUH := XRJUTA || XPJUTA || 'Juta ' || ENAM;            
    ELSE
        TUJUH := XRJUTA || XPJUTA || ENAM;
    END IF;
    
END IF;

-- Condition Bilion and Ratus Juta
IF TUJUH IS NULL AND XBILION IS NULL THEN
    RETURN ( 'Tiada' );
ELSIF TUJUH IS NOT NULL AND XBILION IS NULL THEN
    RETURN ( TUJUH || 'Sahaja' );
ELSIF TUJUH IS NULL AND XBILION IS NOT NULL THEN
    RETURN ( XBILION || 'Sahaja' );
ELSE
    RETURN ( XBILION || TUJUH || 'Sahaja' );
END IF;

END;
$function$
;

-- DROP FUNCTION et_main_uat.convertnumber_eng(numeric);

CREATE OR REPLACE FUNCTION et_main_uat.convertnumber_eng(in_nombor numeric)
 RETURNS character varying
 LANGUAGE plpgsql
AS $function$
DECLARE
NOMBOR  numeric := ABS ( IN_NOMBOR );
SEN1      VARCHAR2(1);
SEN2      VARCHAR2(1);
SA        VARCHAR2(1);
PULUH     VARCHAR2(1);
RATUS     VARCHAR2(1);
RIBU      VARCHAR2(1);
PRIBU     VARCHAR2(1);
RRIBU     VARCHAR2(1);
JUTA      VARCHAR2(1);
PJUTA     VARCHAR2(1);
RJUTA     VARCHAR2(1);
BILION    VARCHAR2(1);
XSEN1     VARCHAR2(20);
XSEN2     VARCHAR2(20);
XSA       VARCHAR2(20);
XPULUH    VARCHAR2(20);
XRATUS    VARCHAR2(20);
XRIBU     VARCHAR2(20);
XPRIBU    VARCHAR2(20);
XRRIBU    VARCHAR2(20);
XJUTA     VARCHAR2(20);
XPJUTA    VARCHAR2(20);
XRJUTA    VARCHAR2(20);
XBILION   VARCHAR2(20);
SEN       VARCHAR2(500);
SATU      VARCHAR2(500);
DUA       VARCHAR2(500);
TIGA      VARCHAR2(500);
EMPAT     VARCHAR2(500);
LIMA      VARCHAR2(500);
ENAM      VARCHAR2(500);
TUJUH     VARCHAR2(500);

BEGIN
SELECT  SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -1, 1 ), SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -2, 1 ),
        SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -4, 1 ), SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -5, 1 ),
        SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -6, 1 ), SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -7, 1 ),
        SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -8, 1 ), SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -9, 1 ),
        SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -10, 1 ), SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -11, 1 ),
        SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -12, 1 ), SUBSTR ( TO_CHAR ( NOMBOR, '9999999990.00' ), -13, 1 )
INTO    SEN1, SEN2, SA, PULUH, RATUS, RIBU, PRIBU, RRIBU, JUTA, PJUTA, RJUTA, BILION
FROM    DUAL;

--Bilion
IF BILION = '1' THEN
    XBILION := 'One Billion ';
ELSIF BILION = '2' THEN
    XBILION := 'Two Billion ';
ELSIF BILION = '3' THEN
    XBILION := 'Three Billion ';
ELSIF BILION = '4' THEN
    XBILION := 'Four Billion ';
ELSIF BILION = '5' THEN
    XBILION := 'Five Billion ';
ELSIF BILION = '6' THEN
    XBILION := 'Six Billion ';
ELSIF BILION = '7' THEN
    XBILION := 'Seven Billion ';
ELSIF BILION = '8' THEN
    XBILION := 'Eight Billion ';
ELSIF BILION = '9' THEN
    XBILION := 'Nine Billion ';
ELSE
    XBILION := NULL;
END IF;

--Ratus Juta
IF RJUTA = '1' THEN
    XRJUTA := 'One Hundred ';
ELSIF RJUTA = '2' THEN
    XRJUTA := 'Two Hundred ';
ELSIF RJUTA = '3' THEN
    XRJUTA := 'Three Hundred ';
ELSIF RJUTA = '4' THEN
    XRJUTA := 'Four Hundred ';
ELSIF RJUTA = '5' THEN
    XRJUTA := 'Five Hundred ';
ELSIF RJUTA = '6' THEN
    XRJUTA := 'Six Hundred ';
ELSIF RJUTA = '7' THEN
    XRJUTA := 'Seven Hundred ';
ELSIF RJUTA = '8' THEN
    XRJUTA := 'Eight Hundred ';
ELSIF RJUTA = '9' THEN
    XRJUTA := 'Nine Hundred ';
ELSE
    XRJUTA := NULL;
END IF;

--Puluh Juta
IF PJUTA = '1' THEN
    IF JUTA = '0' THEN
        XPJUTA := 'Ten ';
    ELSIF JUTA = '1' THEN
        XPJUTA := 'Eleven ';
    ELSIF JUTA = '2' THEN
        XPJUTA := 'Twelve ';
    ELSIF JUTA = '3' THEN
        XPJUTA := 'Thirteen ';
    ELSIF JUTA = '4' THEN
        XPJUTA := 'Fourteen ';
    ELSIF JUTA = '5' THEN
        XPJUTA := 'Fifteen ';
    ELSIF JUTA = '6' THEN
        XPJUTA := 'Sixteen ';
    ELSIF JUTA = '7' THEN
        XPJUTA := 'Seventeen ';
    ELSIF JUTA = '8' THEN
        XPJUTA := 'Eighteen ';
    ELSIF JUTA = '9' THEN
        XPJUTA := 'Nineteen ';
    END IF;
ELSIF PJUTA = '2' THEN
    XPJUTA := 'Twenty ';
ELSIF PJUTA = '3' THEN
    XPJUTA := 'Thirty ';
ELSIF PJUTA = '4' THEN
    XPJUTA := 'Forty ';
ELSIF PJUTA = '5' THEN
    XPJUTA := 'Fifty ';
ELSIF PJUTA = '6' THEN
    XPJUTA := 'Sixty ';
ELSIF PJUTA = '7' THEN
    XPJUTA := 'Seventy ';
ELSIF PJUTA = '8' THEN
    XPJUTA := 'Eighty ';
ELSIF PJUTA = '9' THEN
    XPJUTA := 'Ninety ';
ELSE
    XPJUTA := NULL;
END IF;

--Juta
IF JUTA = '1' THEN
    XJUTA := 'One Million ';
ELSIF JUTA = '2' THEN
    XJUTA := 'Two Million ';
ELSIF JUTA = '3' THEN
    XJUTA := 'Three Million ';
ELSIF JUTA = '4' THEN
    XJUTA := 'Four Million ';
ELSIF JUTA = '5' THEN
    XJUTA := 'Five Million ';
ELSIF JUTA = '6' THEN
    XJUTA := 'Six Million ';
ELSIF JUTA = '7' THEN
    XJUTA := 'Seven Million ';
ELSIF JUTA = '8' THEN
    XJUTA := 'Eight Million ';
ELSIF JUTA = '9' THEN
    XJUTA := 'Nine Million ';
ELSE
    XJUTA := NULL;
END IF;

--Ratus Ribu
IF RRIBU = '1' THEN
    XRRIBU := 'One Hundred ';
ELSIF RRIBU = '2' THEN
    XRRIBU := 'Two Hundred ';
ELSIF RRIBU = '3' THEN
    XRRIBU := 'Three Hundred ';
ELSIF RRIBU = '4' THEN
    XRRIBU := 'Four Hundred ';
ELSIF RRIBU = '5' THEN
    XRRIBU := 'Five Hundred ';
ELSIF RRIBU = '6' THEN
    XRRIBU := 'Six Hundred ';
ELSIF RRIBU = '7' THEN
    XRRIBU := 'Seven Hundred ';
ELSIF RRIBU = '8' THEN
    XRRIBU := 'Eight Hundred ';
ELSIF RRIBU = '9' THEN
    XRRIBU := 'Nine Hundred ';
ELSE
    XRRIBU := NULL;
END IF;

--Puluh Ribu
IF PRIBU = '1' THEN
    XPRIBU := 'Ten ';
ELSIF PRIBU = '2' THEN
    XPRIBU := 'Twenty ';
ELSIF PRIBU = '3' THEN
    XPRIBU := 'Thirty ';
ELSIF PRIBU = '4' THEN
    XPRIBU := 'Forty ';
ELSIF PRIBU = '5' THEN
    XPRIBU := 'Fifty ';
ELSIF PRIBU = '6' THEN
    XPRIBU := 'Sixty ';
ELSIF PRIBU = '7' THEN
    XPRIBU := 'Seventy ';
ELSIF PRIBU = '8' THEN
    XPRIBU := 'Eighty ';
ELSIF PRIBU = '9' THEN
    XPRIBU := 'Ninety ';
ELSE
    XPRIBU := NULL;
END IF;

--Ribu
IF RIBU = '1' THEN
    XRIBU := 'One Thousand ';
ELSIF RIBU = '2' THEN
    XRIBU := 'Two Thousand ';
ELSIF RIBU = '3' THEN
    XRIBU := 'Three Thousand ';
ELSIF RIBU = '4' THEN
    XRIBU := 'Four Thousand ';
ELSIF RIBU = '5' THEN
    XRIBU := 'Five Thousand ';
ELSIF RIBU = '6' THEN
    XRIBU := 'Six Thousand ';
ELSIF RIBU = '7' THEN
    XRIBU := 'Seven Thousand ';
ELSIF RIBU = '8' THEN
    XRIBU := 'Eight Thousand ';
ELSIF RIBU = '9' THEN
    XRIBU := 'Nine Thousand ';
ELSE
    XRIBU := NULL;
END IF;

--Ratus
IF RATUS = '1' THEN
    XRATUS := 'One Hundred ';
ELSIF RATUS = '2' THEN
    XRATUS := 'Two Hundred ';
ELSIF RATUS = '3' THEN
    XRATUS := 'Three Hundred ';
ELSIF RATUS = '4' THEN
    XRATUS := 'Four Hundred ';
ELSIF RATUS = '5' THEN
    XRATUS := 'Five Hundred ';
ELSIF RATUS = '6' THEN
    XRATUS := 'Six Hundred ';
ELSIF RATUS = '7' THEN
    XRATUS := 'Seven Hundred ';
ELSIF RATUS = '8' THEN
    XRATUS := 'Eight Hundred ';
ELSIF RATUS = '9' THEN
    XRATUS := 'Nine Hundred ';
END IF;

--Puluh
IF PULUH = '1' THEN
    IF SA = '0' THEN
        XPULUH := 'Ten ';
    ELSIF SA = '1' THEN
        XPULUH := 'Eleven ';
    ELSIF SA = '2' THEN
        XPULUH := 'Twelve ';
    ELSIF SA = '3' THEN
        XPULUH := 'Thirteen ';
    ELSIF SA = '4' THEN
        XPULUH := 'Fourteen ';
    ELSIF SA = '5' THEN
        XPULUH := 'Fifteen ';
    ELSIF SA = '6' THEN
        XPULUH := 'Sixteen ';
    ELSIF SA = '7' THEN
        XPULUH := 'Seventeen ';
    ELSIF SA = '8' THEN
        XPULUH := 'Eighteen ';
    ELSIF SA = '9' THEN
        XPULUH := 'Nineteen ';
    END IF;
ELSIF PULUH = '2' THEN
    XPULUH := 'Twenty ';
ELSIF PULUH = '3' THEN
    XPULUH := 'Thirty ';
ELSIF PULUH = '4' THEN
    XPULUH := 'Forty ';
ELSIF PULUH = '5' THEN
    XPULUH := 'Fifty ';
ELSIF PULUH = '6' THEN
    XPULUH := 'Sixty ';
ELSIF PULUH = '7' THEN
    XPULUH := 'Seventy ';
ELSIF PULUH = '8' THEN
    XPULUH := 'Eighty ';
ELSIF PULUH = '9' THEN
    XPULUH := 'Ninety ';
END IF;

--Sa
IF SA = '1' THEN
    XSA := 'One ';
ELSIF SA = '2' THEN
    XSA := 'Two ';
ELSIF SA = '3' THEN
    XSA := 'Three ';
ELSIF SA = '4' THEN
    XSA := 'Four ';
ELSIF SA = '5' THEN
    XSA := 'Five ';
ELSIF SA = '6' THEN
    XSA := 'Six ';
ELSIF SA = '7' THEN
    XSA := 'Seven ';
ELSIF SA = '8' THEN
    XSA := 'Eight ';
ELSIF SA = '9' THEN
    XSA := 'Nine ';
END IF;

--Sen Decimal ke 2
IF SEN1 = '0' THEN
    XSEN1 := '';
ELSIF SEN1 =  '1' THEN
    XSEN1 := 'One ';
ELSIF SEN1 = '2' THEN
    XSEN1 := 'Two ';
ELSIF SEN1 = '3' THEN
    XSEN1 := 'Three ';
ELSIF SEN1 = '4' THEN
    XSEN1 := 'Four ';
ELSIF SEN1 = '5' THEN
    XSEN1 := 'Five ';
ELSIF SEN1 = '6' THEN
    XSEN1 := 'Six ';
ELSIF SEN1 = '7' THEN
    XSEN1 := 'Seven ';
ELSIF SEN1 = '8' THEN
    XSEN1 := 'Eight ';
ELSIF SEN1 = '9' THEN
    XSEN1 := 'Nine ';
END IF;

--Sen Decimal pertama
IF SEN2 = '1' THEN
    IF SEN1 = '0' THEN
        XSEN2 := 'Ten ';
    ELSIF SEN1 = '1' THEN
        XSEN2 := 'Eleven ';
    ELSIF SEN1 = '2' THEN
        XSEN2 := 'Twelve ';
    ELSIF SEN1 = '3' THEN
        XSEN2 := 'Thirteen ';
    ELSIF SEN1 = '4' THEN
        XSEN2 := 'Fourteen ';
    ELSIF SEN1 = '5' THEN
        XSEN2 := 'Fifteen ';
    ELSIF SEN1 = '6' THEN
        XSEN2 := 'Sixteen ';
    ELSIF SEN1 = '7' THEN
        XSEN2 := 'Seventeen ';
    ELSIF SEN1 = '8' THEN
        XSEN2 := 'Eighteen ';
    ELSIF SEN1 = '9' THEN
        XSEN2 := 'Nineteen ';
    END IF;
ELSIF SEN2 = '2' THEN
    XSEN2 := 'Twenty ';
ELSIF SEN2 = '3' THEN
    XSEN2 := 'Thirty ';
ELSIF SEN2 = '4' THEN
    XSEN2 := 'Forty ';
ELSIF SEN2 = '5' THEN
    XSEN2 := 'Fifty ';
ELSIF SEN2 = '6' THEN
    XSEN2 := 'Sixty ';
ELSIF SEN2 = '7' THEN
    XSEN2 := 'Seventy ';
ELSIF SEN2 = '8' THEN
    XSEN2 := 'Eighty ';
ELSIF SEN2 = '9' THEN
    XSEN2 := 'Ninety ';
END IF;

IF SEN2 = '0' THEN
    IF SEN1 = '0' THEN
       SEN := NULL;
    ELSE
       SEN := XSEN1;
    END IF;
ELSIF SEN2 = '1' THEN
    SEN := XSEN2;
ELSE
    SEN := XSEN2 || XSEN1;
END IF;

-- Condition Puluh
IF PULUH = '0' OR PULUH IS NULL THEN
    IF XSA IS NOT NULL THEN
        SATU := XSA;
    ELSE
        SATU := NULL;
    END IF;
ELSIF PULUH = '1' THEN
    SATU := XPULUH;
ELSE
    SATU := XPULUH || XSA;
END IF;

-- Condition Ratus
IF RATUS IS NULL OR RATUS = '0' THEN
    DUA := NULL;
ELSE
    DUA := XRATUS;
END IF;

-- Condition Puluh Ribu and Ribu
IF PRIBU IS NULL OR PRIBU = '0' THEN
    IF RIBU IS NOT NULL THEN
        TIGA := XRIBU;
    ELSE
        TIGA := NULL;
    END IF;

ELSIF PRIBU = '1' THEN
    IF RIBU = '0' THEN
        TIGA := 'Ten Thousand ';
    ELSIF RIBU = '1' THEN
        TIGA := 'Eleven Thousand ';
    ELSIF RIBU = '2' THEN
        TIGA := 'Twelve Thousand ';
    ELSIF RIBU = '3' THEN
        TIGA := 'Thirteen Thousand ';
    ELSIF RIBU = '4' THEN
        TIGA := 'Fourteen Thousand ';
    ELSIF RIBU = '5' THEN
        TIGA := 'Fifteen Thousand ';
    ELSIF RIBU = '6' THEN
        TIGA := 'Sixteen Thousand ';
    ELSIF RIBU = '7' THEN
        TIGA := 'Seventeen Thousand ';
    ELSIF RIBU = '8' THEN
        TIGA := 'Eighteen Thousand ';
    ELSIF RIBU = '9' THEN
        TIGA := 'Nineteen Thousand ';
    END IF;

ELSE
    IF RIBU = '0' THEN
        TIGA := XPRIBU || 'Thousand ';
    ELSE
        TIGA := XPRIBU || XRIBU;
    END IF;
    
END IF;

-- Condition to gabung number from Puluh Ribu until Sa
IF TIGA IS NOT NULL AND DUA IS NOT NULL AND SATU IS NOT NULL THEN 
	EMPAT := TIGA || DUA || SATU;
ELSIF TIGA IS NOT NULL AND DUA IS NOT NULL AND SATU IS NULL THEN 
	EMPAT := TIGA || DUA;
ELSIF TIGA IS NOT NULL AND DUA IS NULL AND SATU IS NOT NULL THEN 
	EMPAT := TIGA || SATU;
ELSIF TIGA IS NULL AND DUA IS NOT NULL AND SATU IS NOT NULL THEN 
	EMPAT := DUA || SATU;
ELSIF TIGA IS NOT NULL AND DUA IS NULL AND SATU IS NULL THEN 
	EMPAT := TIGA;
ELSIF TIGA IS NULL AND DUA IS NOT NULL AND SATU IS NULL THEN 
	EMPAT := DUA;
ELSIF TIGA IS NULL AND DUA IS NULL AND SATU IS NOT NULL THEN 
	EMPAT := SATU;
END IF;

-- Gabung Puluh Ribu until Sa with Sen
IF SEN IS NOT NULL AND EMPAT IS NOT NULL THEN
    LIMA := EMPAT || 'and ' || SEN || 'Cents ';
ELSIF SEN IS NULL AND EMPAT IS NOT NULL THEN
    LIMA := EMPAT;
ELSIF SEN IS NOT NULL AND EMPAT IS NULL THEN
    IF XRRIBU IS NULL AND XJUTA IS NULL THEN
        LIMA := SEN || 'Cents ';
    ELSE
        LIMA := SEN || 'Cents ';
    END IF;
END IF;

-- Condition Ratus Ribu and Juta
IF XRRIBU IS NULL AND XJUTA IS NULL THEN
    ENAM := LIMA;

ELSIF XRRIBU IS NOT NULL AND XJUTA IS NULL THEN
    IF XPRIBU IS NULL AND XRIBU IS NULL THEN
        ENAM := XRRIBU || 'Thousand ' || LIMA;
    ELSE
        ENAM := XRRIBU || LIMA;
    END IF;

ELSIF XRRIBU IS NULL AND XJUTA IS NOT NULL THEN
    IF XPRIBU IS NULL AND XRIBU IS NULL THEN
        ENAM := XJUTA || LIMA;
    ELSIF PRIBU != '0' AND RIBU != '0' THEN      
        ENAM := XJUTA || LIMA;
    ELSE
        ENAM := XJUTA || XRRIBU || LIMA;
    END IF;

ELSIF XRRIBU IS NOT NULL AND XJUTA IS NOT NULL THEN
    IF PJUTA = '1' THEN
        IF XPRIBU IS NULL AND XRIBU IS NULL THEN
            ENAM := XRRIBU || 'Thousand ' || LIMA;
        ELSE
            ENAM := XRRIBU || LIMA;
        END IF;
    ELSE
        ENAM := XJUTA || XRRIBU || LIMA;
    END IF;
    
END IF;

-- Condition for Puluh Juta and Juta and Ratus Ribu
IF XPJUTA IS NULL AND XRJUTA IS NULL THEN
    TUJUH := ENAM;
    
ELSIF XPJUTA IS NOT NULL AND XRJUTA IS NULL THEN
    IF XRRIBU IS NULL AND XJUTA IS NULL THEN
        IF PJUTA = '1' THEN
            TUJUH := XPJUTA || 'Million ' || ENAM;
        ELSE
            TUJUH := XPJUTA || 'Million ' || ENAM;
        END IF;
    ELSIF XJUTA IS NOT NULL THEN
        IF PJUTA = '1' THEN
            TUJUH := XPJUTA || 'Million ' || ENAM;
        ELSE
            TUJUH := XPJUTA || ENAM;
        END IF;
    END IF;
        
ELSIF XPJUTA IS NULL AND XRJUTA IS NOT NULL THEN
    IF XRRIBU IS NULL AND XJUTA IS NULL THEN
        TUJUH := XRJUTA || 'Million ' || ENAM;
    ELSIF XRRIBU != '0' AND XJUTA != '0' THEN
        TUJUH := XRJUTA || XJUTA || 'Million ' || ENAM;
    END IF;
    
ELSIF XPJUTA IS NOT NULL AND XRJUTA IS NOT NULL THEN
    IF XRRIBU IS NULL AND XJUTA IS NULL THEN  
        TUJUH := XRJUTA || XPJUTA || 'Million ' || ENAM;            
    ELSE
        TUJUH := XRJUTA || XPJUTA || ENAM;
    END IF;
    
END IF;

-- Condition Bilion and Ratus Juta
IF TUJUH IS NULL AND XBILION IS NULL THEN
    RETURN ( 'Nil' );
ELSIF TUJUH IS NOT NULL AND XBILION IS NULL THEN
    RETURN ( TUJUH || 'Only' );
ELSIF TUJUH IS NULL AND XBILION IS NOT NULL THEN
    RETURN ( XBILION || 'Only' );
ELSE
    RETURN ( XBILION || TUJUH || 'Only' );
END IF;

END;
$function$
;

-- DROP FUNCTION et_main_uat.del_md_triggers_t_func();

CREATE OR REPLACE FUNCTION et_main_uat.del_md_triggers_t_func()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    DELETE FROM md_triggers
    WHERE table_or_view_id_fk = OLD.id AND trigger_on_flag = 't';
    RETURN OLD;
END;
$function$
;

-- DROP FUNCTION et_main_uat.del_md_triggers_v_func();

CREATE OR REPLACE FUNCTION et_main_uat.del_md_triggers_v_func()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    DELETE FROM md_triggers
    WHERE table_or_view_id_fk = OLD.id AND trigger_on_flag = 'v';
    RETURN OLD;
END;
$function$
;

-- DROP FUNCTION et_main_uat.fn_get_dhd_path(varchar);

CREATE OR REPLACE FUNCTION et_main_uat.fn_get_dhd_path(idhakmilik3 character varying)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_path text;
  idhakmilik character varying;
BEGIN

  IF idhakmilik3 LIKE '%/%' THEN

  	select 
  	coalesce(p.id_hkmlk_sebenar,h.id_hkmlk) into idhakmilik

	  from ind_hkmlk h, ind_hkmlk_pelbagai p 
	  where h.hkmlk_pelbagai_id = p.hkmlk_pelbagai_id
	  and h.id_hkmlk = idhakmilik3;
	if idhakmilik LIKE '%/%' then
  
	    SELECT CASE
	             WHEN d.nama_fizikal LIKE '/geran%' THEN
	               '/home/app/etanah/files/dms/MIGRATION/WORM' ||
	               replace(d.nama_fizikal, '/geran/04','')
	             ELSE
	               '/home/app/etanah/files/dms/MIGRATION/DMS/' || d.nama_fizikal
	           END
	      INTO v_path
	    FROM fatmk.dokumen d
	    JOIN fatmk.mohon_hakmilik h
	      ON d.id_dokumen IN (h.id_dokumen1, h.id_dokumen2, h.id_dokumen3, h.id_dokumen4)
	    JOIN fatmk.mohon m
	      ON m.id_mohon = h.id_mohon
	    JOIN et_migrator.h_s_delta e
	      ON h.id_hakmilik = e.id_hakmilik
	    WHERE e.id_hkmlk = idhakmilik  --  format etanah v2 vs etanah v1
	      AND d.kod_dokumen = 'DHDK'
	    ORDER BY d.trh_masuk DESC
	    LIMIT 1;
	else

	    SELECT CASE
	             WHEN d.nama_fizikal LIKE '/geran%' THEN
	               '/home/app/etanah/files/dms/MIGRATION/WORM' ||
	               replace(d.nama_fizikal, '/geran/04','')
	             ELSE
	               '/home/app/etanah/files/dms/MIGRATION/DMS/' || d.nama_fizikal
	           END
	      INTO v_path
	    FROM fatmk.dokumen d
	    JOIN fatmk.mohon_hakmilik h
	      ON d.id_dokumen IN (h.id_dokumen1, h.id_dokumen2, h.id_dokumen3, h.id_dokumen4, h.id_dokumen5)
	    JOIN fatmk.mohon m
	      ON m.id_mohon = h.id_mohon
	 
	    WHERE h.id_hakmilik = idhakmilik  --  format etanah v2 vs etanah v1
	      AND d.kod_dokumen = 'DHDK'
	    ORDER BY d.trh_masuk DESC
	    LIMIT 1;
	end if;

  ELSE

  	select 
  	coalesce(p.id_hkmlk_sebenar,h.id_hkmlk) into idhakmilik

	  from ind_hkmlk h, ind_hkmlk_pelbagai p 
	  where h.hkmlk_pelbagai_id = p.hkmlk_pelbagai_id
	  and h.id_hkmlk = idhakmilik3;
  
    SELECT CASE
             WHEN nama_fizikal LIKE '/geran%' THEN
               '/home/app/etanah/files/dms/MIGRATION/WORM' ||
               replace(nama_fizikal, '/geran/04','')
             ELSE
               '/home/app/etanah/files/dms/MIGRATION/DMS/' || nama_fizikal
           END
      INTO v_path
    FROM fatmk.dokumen
    WHERE kod_dokumen IN ('DHDE','4KDHD','4AKDH')
      AND (d_nilai1 = idhakmilik OR id_hakmilik = idhakmilik)
    ORDER BY trh_masuk DESC
    LIMIT 1;
  END IF;

  RETURN v_path;  -- returns NULL if nothing matched
END;
$function$
;

-- DROP FUNCTION et_main_uat.fn_sak_kod_by_sptb_code(varchar, varchar);

CREATE OR REPLACE FUNCTION et_main_uat.fn_sak_kod_by_sptb_code(kodsaksptb character varying, kodsk character varying)
 RETURNS character varying
 LANGUAGE plpgsql
AS $function$
DECLARE
    kodsak VARCHAR2(100);
BEGIN
    SELECT kod INTO kodsak 
    FROM et_main_mig.rjk_senarai_ahli_kumpulan 
    WHERE sptb_kod = kodsaksptb 
        AND senarai_kumpulan_id = (
            SELECT senarai_kumpulan_id 
            FROM et_main_mig.rjk_senarai_kumpulan 
            WHERE kod = kodsk
        );

    RETURN kodsak;
EXCEPTION
    WHEN OTHERS THEN 
        RETURN NULL;
END;
$function$
;

-- DROP FUNCTION et_main_uat.fn_tkr_bilangan_strk_semasa(varchar);

CREATE OR REPLACE FUNCTION et_main_uat.fn_tkr_bilangan_strk_semasa(v_pengguna character varying)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
    n_cnt INTEGER;
BEGIN
    SELECT COUNT(*) INTO n_cnt
    FROM et_main_mig.tkr_hakmilik_tukarganti
    WHERE checker = v_pengguna
       OR quality_analyst = v_pengguna
       OR pembantu_tadbir = v_pengguna
       OR pendaftar = v_pengguna;

    RETURN n_cnt;
EXCEPTION
    WHEN OTHERS THEN 
        RETURN 0;
END;
$function$
;

-- DROP FUNCTION et_main_uat.gcd(int4, int4);

CREATE OR REPLACE FUNCTION et_main_uat.gcd(x integer, y integer)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
   ans INTEGER;
BEGIN
   IF (y <= x) AND (x % y = 0) THEN
      ans := y;
   ELSIF x < y THEN
      ans := et_main_mig.gcd(y, x);  -- recursive call
   ELSE
      ans := et_main_mig.gcd(y, x % y);  -- recursive call
   END IF;
   RETURN ans;
END;
$function$
;

-- DROP FUNCTION et_main_uat.gencolumnkeytrig_function();

CREATE OR REPLACE FUNCTION et_main_uat.gencolumnkeytrig_function()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.colid_gen IS NULL THEN
    NEW.colid_gen := md_meta.get_next_id();
  END IF;
  RETURN NEW;
END;
$function$
;

-- DROP FUNCTION et_main_uat.get_alamat(numeric, text);

CREATE OR REPLACE FUNCTION et_main_uat.get_alamat(alamat_id numeric, report_name text)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
    FULL_ADDRESS TEXT;
BEGIN
	IF REPORT_NAME = 'LaporanBilCukai' THEN
	    SELECT 
			-- NAMA_PEMBAYAR on first line
			--CASE 
			--    WHEN NAMA_PEMBAYAR IS NULL OR TRIM(NAMA_PEMBAYAR) = '' THEN '' 
			--    ELSE UPPER(TRIM(NAMA_PEMBAYAR)) || '<br>' 
			--END ||
			
			-- Combine ALAMAT and ALAMAT2 on one line
			CASE 
			    WHEN (ALAMAT IS NULL OR TRIM(ALAMAT) = '') AND (ALAMAT2 IS NULL OR TRIM(ALAMAT2) = '') THEN '' 
			    ELSE 
			        COALESCE(TRIM(ALAMAT), '') || 
			        CASE 
			            WHEN (TRIM(ALAMAT) IS NOT NULL AND TRIM(ALAMAT2) IS NOT NULL
						AND TRIM(ALAMAT) <> '' AND TRIM(ALAMAT2) <> '') THEN ' ' 
			            ELSE '' 
			        END || 
			        COALESCE(TRIM(ALAMAT2), '') || '<br>'
			END ||
			
			-- Combine ALAMAT3 and ALAMAT4 on one line
			CASE 
			    WHEN (ALAMAT3 IS NULL OR TRIM(ALAMAT3) = '') AND (ALAMAT4 IS NULL OR TRIM(ALAMAT4) = '') THEN '' 
			    ELSE 
			        COALESCE(TRIM(ALAMAT3), '') || 
			        CASE 
			            WHEN (TRIM(ALAMAT3) IS NOT NULL AND TRIM(ALAMAT4) IS NOT NULL 
						AND TRIM(ALAMAT3) <> '' AND TRIM(ALAMAT4) <> '') THEN ' ' 
			            ELSE '' 
			        END || 
			        COALESCE(TRIM(ALAMAT4), '') || '<br>'
			END ||
			
			-- Combine POSKOD and BANDAR on one line
			CASE 
			    WHEN (POSKOD IS NULL OR TRIM(POSKOD) = '') AND (BD_AL.NAMA IS NULL OR TRIM(BD_AL.NAMA) = '') THEN '' 
			    ELSE 
			        COALESCE(TRIM(POSKOD), '') || 
			        CASE 
			            WHEN (TRIM(POSKOD) IS NOT NULL AND TRIM(BD_AL.NAMA) IS NOT NULL 
						AND TRIM(POSKOD) <> '' AND TRIM(BD_AL.NAMA) <> '') THEN ' ' 
			            ELSE '' 
			        END || 
			        COALESCE(TRIM(BD_AL.NAMA), '') || '<br>'
			END ||
			
			-- NEGERI on last line
			CASE 
			    WHEN NG_AL.NAMA IS NULL OR TRIM(NG_AL.NAMA) = '' THEN '' 
			    ELSE TRIM(NG_AL.NAMA)
			END 
	    INTO FULL_ADDRESS
	    FROM HSL_ALAMAT_CUKAI AL
	    LEFT JOIN RJK_SENARAI_AHLI_KUMPULAN BD_AL ON AL.BANDAR_ID = BD_AL.SENARAI_AHLI_KUMPULAN_ID
	    LEFT JOIN RJK_SENARAI_AHLI_KUMPULAN NG_AL ON AL.NEGERI_ID = NG_AL.SENARAI_AHLI_KUMPULAN_ID
	    WHERE AL.ALAMAT_CUKAI_ID = ALAMAT_ID;
	
	-- ADD THIS IF WANT TO USE FOR OTHER REPORT
	--ELSIF report_name = 'report_b' THEN

	END IF;

    -- IF NO ADDRESS FOUND
    IF FULL_ADDRESS IS NULL THEN
        RETURN '';
    END IF;

    RETURN FULL_ADDRESS;
END;
$function$
;

-- DROP FUNCTION et_main_uat.get_count_dashboard_by_pengguna(_text, text, numeric, text, text, text, text, text, text);

CREATE OR REPLACE FUNCTION et_main_uat.get_count_dashboard_by_pengguna(var_urusan_kod_list text[], var_nama_pengguna text DEFAULT NULL::text, var_pejabat_id numeric DEFAULT NULL::numeric, var_modul_kod text DEFAULT NULL::text, var_urusan_mdl_kod text DEFAULT NULL::text, var_status_tugasan text DEFAULT NULL::text, var_kod_negri text DEFAULT NULL::text, var_filter_colum text DEFAULT NULL::text, var_filter_val text DEFAULT NULL::text)
 RETURNS TABLE(total bigint)
 LANGUAGE plpgsql
AS $function$
BEGIN
  RETURN QUERY
WITH VAR_URUSAN_KOD_LIST AS (
    SELECT UNNEST(var_urusan_kod_list) AS KOD
  ),
VAR_PERANAN_KOD_PENGGUNA AS (
  SELECT DISTINCT PP.NAMA_PENGGUNA, RM.KOD AS PERANAN_KOD
  FROM PCP_CAPAIAN_PENGGUNA CP
  JOIN PCP_PENGGUNA PP ON CP.PENGGUNA_ID = PP.PENGGUNA_ID
  JOIN PCP_PERANAN_MODUL PM ON CP.PERANAN_MODUL_ID = PM.PERANAN_MODUL_ID
  JOIN RJK_SENARAI_AHLI_KUMPULAN RM ON PM.PERANAN_ID = RM.SENARAI_AHLI_KUMPULAN_ID
  WHERE PP.NAMA_PENGGUNA IN (var_nama_pengguna)
),
VAR_DAERAH_PENGGUNA AS (
    SELECT DISTINCT DAERAH_ID
    FROM IND_PEJABAT AS IP
    WHERE PEJABAT_ID IN (var_pejabat_id) 
),
VAR_PEJABAT_TERKAIT AS (
    SELECT DISTINCT PEJABAT_ID
    FROM IND_PEJABAT AS IP
    WHERE DAERAH_ID IN (SELECT DAERAH_ID FROM VAR_DAERAH_PENGGUNA)
),
VAR_FILTER_TUGASAN_KOD_SET AS (
	SELECT UNNEST(ARRAY[ 'PPBKRPJPM', 'PPBKRKPJPM', 'PTB', 'SJR',
    'PJR', 'CTK_JR', 'PMMP6PTB2', 'PPBBPTB2',
    'PPHSYBPTB2', 'PKJR', 'PKJRPP']) as stgsn_kod
),

VAR_PELUPUSAN_TUGASAN_FILTERED AS (
  SELECT ID_TGSN AS ID_TGSN_PELUPUSAN_PENGGUNA_FILTER
  FROM (
    SELECT A.ID_TGSN,
        ROW_NUMBER() OVER (
            PARTITION BY COALESCE(C.kod, E.kod), A.ID_TGSN
            ORDER BY A.ID_TGSN
    ) AS RN
    FROM UMM_TGSN_SEMASA A
    LEFT JOIN UMM_APLIKASI B ON B.APLIKASI_ID = A.APLIKASI_ID
    LEFT JOIN IND_URSN C ON C.URSN_ID = B.URSN_ID
    LEFT JOIN UMM_P_APLIKASI D ON D.APLIKASI_ID = A.APLIKASI_ID
    LEFT JOIN IND_URSN E ON E.URSN_ID = D.URSN_ID
    WHERE A.MODUL = 'PLP'
      AND A.KOD_TGSN = 'FPIKM'
      AND UPPER(A.FLAG_TGSN_SISTEM) = 'N'
  ) A
  WHERE RN = 1
),
VAR_PEJABAT_PERANAN_MAP AS (
  SELECT * FROM (VALUES
    ('TRG', ARRAY['PTG', 'TPTG', 'KPP']),
    ('PRK', ARRAY['PTG', 'KPP']),
    ('SEL', ARRAY['PTG', 'TPTG'])
  ) AS T (KOD_PEJABAT, PERANANS)
),
VAR_PLP_TUGASAN_KOD_SET AS (
    SELECT unnest(ARRAY['PDKM', 'SDKM', 'SDKM2', 'SDKM3', 'PPKM', 'CKM', 'CKMPPLN'])
),
VAR_ALSAN_TUKARGANTI_KOD_SET AS (
    SELECT unnest(ARRAY['KMPP', 'HMSC', 'HMSTP', 'PRBB', 'OPRBB', 'HDHD', 'HMPV', 'HMV', 'HMVB',
            'SSHM', 'SSSC', 'SW', 'SA', 'CRHMB', 'CSHMB', 'BETUL', 'PACT', 'PKH', 'PMKMH', 'PFT', 'REM', 'REMITAN'])
),
VAR_GROUP_BY_NO_FAIL_TUGASAN_KOD_SET AS (
    SELECT unnest(ARRAY['PPBKRPDPJPM', 'PPBKRSDPJPM', 'PPBKRCDPJPM'])
),

VAR_ALSAN_TUKARGANTI_KOD_SET_BATAL AS (
    SELECT unnest(ARRAY['HDHK', 'HPLN','PMKMH','HSSTB','HKSSS'])
),
VAR_NO_HAK_MILIK_BARU AS (
    SELECT 
        mohon.APLIKASI_ID,
        STRING_AGG(mohon.id_hkmlk, '<br>') AS NO_HAKMILIK_BARU
    FROM dft_A_MOHON_HKMLK mohon
    JOIN UMM_APLIKASI appl ON appl.APLIKASI_ID = mohon.APLIKASI_ID
    JOIN IND_URSN urusan ON appl.URSN_ID = urusan.URSN_ID
    JOIN rjk_jns_ursn jenis ON jenis.jns_ursn_id = urusan.jns_ursn_id
    WHERE mohon.id_hkmlk IS NOT NULL
      AND jenis.KOD = 'MH'
    GROUP BY mohon.APLIKASI_ID
),
MAIN_QUERY AS (
	SELECT 
  	DHAS_1.TGSN_SEMASA_ID,
	DHAS_1.TRKH_PNRMAN,
	MDL_1.KOD as MODUL,
	DHAS_1.ID_HKMLK,
	DHAS_1.NO_RESIT,
	DHAS_1.LOCKED_BY,
	DHAS_1.LOCKED_DATE,
	DHAS_1.PERANAN,
	DHAS_1.KOD_TGSN,
	DHAS_1.ID_TGSN,
	DHAS_1.TGSN_PERIHAL,
	DHAS_1.NAMA_PENGGUNA,
	APP_TGSN_1.TRKH_TETAP,
	APP_1.TRKH_PIAGAM,
	APP_1.APLIKASI_ID,
	APP_1.APLIKASI_ID as APP_ID,
	APP_1.RANGKAIAN_ID,
	APP_1.ID_PENGENALAN,
	APP_1.FLAG_INTEGRASI,
	APP_1.STATUS_KEPUTUSAN,
	COALESCE(APP_1.STATUS_PROSES, SNR_1.NAMA) AS STATUS_PROSES,
    COALESCE(URSN_1.KOD, URSN_2.KOD) AS URUSAN_KOD,
    COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI) AS NO_RUJUKAN,
	IPJ_1.NAMA_PENDEK,
	IPJ_1.KOD AS PEJABAT_KOD,
	HNTR_1.ID_PENGHANTARAN,
	DHAS_1.a_tgsn_id as APP_A_TGSN_ID,
	IPJ_1.NAMA_PENDEK as NAMA_PEJABAT_PENDEK,
	TO_CHAR(MLS.TRKH_SIASATAN, 'DD/MM/YYYY') AS TARIKH_SIASATAN_STRING,
	APP_1.ID_RUJUKAN_SMARTBOX,
	DHAS_1.TRKH_KPI AS DHAS_1_TRKH_KPI,
	ITG_1.MINIT_KPI,
	CASE 
      WHEN URSN_1.KOD = 'PSBS' AND DHAS_1.TGSN_PERIHAL = 'Penyediaan Fail Induk Kertas Mesyuarat' THEN FALSE
      ELSE TRUE 
    END AS SHOW_ID_HAKMILIK,
	(
      SELECT STRING_AGG(mohon.id_hkmlk, '<br>')
      FROM dft_A_MOHON_HKMLK mohon
      JOIN UMM_APLIKASI appl ON appl.APLIKASI_ID = mohon.APLIKASI_ID
      JOIN IND_URSN urusan ON appl.URSN_ID = urusan.URSN_ID
      JOIN rjk_jns_ursn jenis ON jenis.jns_ursn_id = urusan.jns_ursn_id
      WHERE mohon.APLIKASI_ID = DHAS_1.APLIKASI_ID
        AND mohon.id_hkmlk IS NOT NULL
        AND jenis.KOD = CAST('MH' AS VARCHAR)
    ) AS NO_HAKMILIK_BARU,
	
	CASE 
		WHEN DHAS_1.TRKH_KPI IS NULL 
		     AND ITG_1.MINIT_KPI IS NOT NULL 
		     AND DHAS_1.TRKH_PNRMAN IS NOT NULL
		THEN DHAS_1.TRKH_PNRMAN + (ITG_1.MINIT_KPI || ' minutes')::INTERVAL
		ELSE DHAS_1.TRKH_KPI
	END AS TRKH_KPI,
	CASE 
		WHEN APP_TGSN_1.STATUS_TUGASAN IS NULL 
			OR DHAS_1.TGSN_PERIHAL = 'Pengagihan Tugasan Baru' 
		THEN 'Baru'
		ELSE APP_TGSN_1.STATUS_TUGASAN
	END AS STATUS_TUGASAN,

	CASE 
		WHEN ITG_1.MINIT_KPI IS NOT NULL THEN TRUE
		ELSE FALSE
	END AS SHOW_KPI,
	CASE 
    WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
         AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
              OR DHAS_1.KOD_TGSN LIKE '%PTB%')
    THEN '-' 
    ELSE TO_CHAR(DHAS_1.TRKH_PNRMAN, 'DD/MM/YYYY')
	END AS TARIKH_PENERIMAAN_STRING,

	CASE 
	
		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
			AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
				OR DHAS_1.KOD_TGSN LIKE '%PTB%')
		THEN '-' 

		ELSE TO_CHAR(
			CASE
			WHEN ITG_1.MINIT_KPI IS NOT NULL 
				AND DHAS_1.TRKH_PNRMAN IS NOT NULL 
				AND DHAS_1.TRKH_KPI IS NULL
			THEN DHAS_1.TRKH_PNRMAN + (ITG_1.MINIT_KPI || ' minutes')::INTERVAL
			ELSE DHAS_1.TRKH_KPI
			END,
			'DD/MM/YYYY'
		)
	END AS TARIKH_DAN_MASA_LUPUT_STRING,
CASE
  WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL
       AND (
         DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
         OR DHAS_1.KOD_TGSN LIKE '%PTB%'
       )
  THEN NULL
  ELSE
    CASE
      WHEN ITG_1.MINIT_KPI IS NOT NULL
           AND DHAS_1.TRKH_PNRMAN IS NOT NULL
           AND DHAS_1.TRKH_KPI IS NULL
      THEN DHAS_1.TRKH_PNRMAN + (ITG_1.MINIT_KPI || ' minutes')::INTERVAL
      ELSE DHAS_1.TRKH_KPI
    END
END AS TARIKH_DAN_MASA_LUPUT,

	CASE 
		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
			AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
				OR DHAS_1.KOD_TGSN LIKE '%PTB%')
		THEN '-' 
		ELSE TO_CHAR(APP_1.TRKH_PIAGAM, 'DD/MM/YYYY')
	END AS TARIKH_PIAGAM_STRING,
	CASE 
		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
			AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
				OR DHAS_1.KOD_TGSN LIKE '%PTB%')
		THEN '-' 
		ELSE TO_CHAR(APP_TGSN_1.TRKH_TETAP, 'DD/MM/YYYY')
	END AS TARIKH_MULA_STRING,
	CASE 
		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
			AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
				OR DHAS_1.KOD_TGSN LIKE '%PTB%')
		THEN TRUE 
		ELSE FALSE 
	END AS IS_FILTER_TUGASAN,
	CASE
		WHEN ITG_1.MINIT_KPI IS NOT NULL 
			AND DHAS_1.TRKH_PNRMAN IS NOT NULL 
			AND DHAS_1.TRKH_KPI IS NULL
		THEN DHAS_1.TRKH_PNRMAN + (ITG_1.MINIT_KPI || ' minutes')::INTERVAL
		ELSE DHAS_1.TRKH_KPI
	END AS TARIKH_KPI,
	

	CASE 
	  WHEN NOT (
	    TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
	    AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
	         OR DHAS_1.KOD_TGSN LIKE '%PTB%')
	  )
	  THEN 
	    CASE 
	      WHEN COALESCE(NULLIF(TRIM(DHAS_1.ID_HKMLK), ''), '-') = '-' THEN '-'
	      ELSE (
	        SELECT 
	          CASE 
	            WHEN COUNT(*) > 10 
	            THEN (
	              SELECT string_agg(val, ', ') || '...'
	              FROM (
	                SELECT DISTINCT val
	                FROM unnest(string_to_array(DHAS_1.ID_HKMLK, ',')) AS val
	                ORDER BY val
	                LIMIT 10
	              ) sub
	            )
	            ELSE (
	              SELECT string_agg(DISTINCT val, ', ' ORDER BY val)
	              FROM unnest(string_to_array(DHAS_1.ID_HKMLK, ',')) AS val
	            )
	          END
	      )
	    END
	  ELSE COALESCE(NULLIF(TRIM(DHAS_1.ID_HKMLK), ''), '-') 
	END AS NO_HAKMILIK_DASHBOARD,
	CASE 
	  WHEN NOT (
	    TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
	    AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
	         OR DHAS_1.KOD_TGSN LIKE '%PTB%')
	  )
	  THEN COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
	  ELSE NULL
	END AS APLIKASI_NO_PERMOHONAN,
	
	
	CASE 
	  WHEN NOT (
	    TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
	    AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
	         OR DHAS_1.KOD_TGSN LIKE '%PTB%')
	  )
		  THEN 
		    CASE 
		      WHEN COALESCE(NULLIF(TRIM(DHAS_1.NO_RESIT), ''), '-') = '-' THEN '-'
		      ELSE (
		        SELECT 
		          CASE 
		            WHEN COUNT(*) > 10 
		            THEN (
		              SELECT string_agg(val, ', ') || '...'
		              FROM (
		                SELECT DISTINCT val
		                FROM unnest(string_to_array(DHAS_1.NO_RESIT, ',')) AS val
		                ORDER BY val
		                LIMIT 10
		              ) sub
		            )
		            ELSE (
		              SELECT string_agg(DISTINCT val, ', ' ORDER BY val)
		              FROM unnest(string_to_array(DHAS_1.NO_RESIT, ',')) AS val
		            )
		          END
		      )
		    END
		  ELSE COALESCE(NULLIF(TRIM(DHAS_1.NO_RESIT), ''), '-') 
		END AS NO_RESIT_DASHBOARD,
		
		
		CASE
		  WHEN NOT (
		    TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
		    AND (
		      DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
		      OR DHAS_1.KOD_TGSN LIKE '%PTB%'
		    )
		  )
		  THEN
		    CASE 
		      WHEN HNTR_1.ID_PENGHANTARAN IS NOT NULL AND HNTR_1.ID_PENGHANTARAN LIKE 'PNL/%'
		        THEN 'UPNL'
		      ELSE COALESCE(URSN_1.KOD, URSN_2.KOD)
		    END
		  ELSE
		    COALESCE(URSN_1.KOD, URSN_2.KOD)
		END AS URUSAN_KOD_DASHBOARD,

		CASE
		  WHEN UPPER(APP_1.FLAG_INTEGRASI) ='Y' THEN
		    CASE
		      WHEN COALESCE(COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI), '') LIKE '%MF%' 
		           AND COALESCE(COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI), '') LIKE '%(%' THEN
		        SPLIT_PART(COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI), '(', 1)
		        
		      WHEN COALESCE(APP_1.URSN_ID, URSN_2.URSN_ID) IS NOT NULL 
		           AND COALESCE(URSN_1.KOD, URSN_2.KOD) = 'KVSP' THEN
		        (
		          SELECT hubungan2.ID_PENGENALAN || ' / ' || COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
		          FROM UMM_APLIKASI hubungan1
		          JOIN UMM_APLIKASI hubungan2 ON hubungan1.ID_PENGENALAN = hubungan2.APLIKASI_ID
		          WHERE hubungan1.APLIKASI_ID = APP_1.APLIKASI_ID
		          LIMIT 1
		        )
		        
		      ELSE
		        (
		          SELECT hubungan.no_rujukan_fail || ' / ' || COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
		          FROM UMM_APLIKASI hubungan
		          WHERE hubungan.APLIKASI_ID = APP_1.APLIKASI_ID
		          LIMIT 1
		        )
		    END
		  WHEN DHAS_1.KOD_TGSN  = 'STRSPRAP' THEN
		    APP_A_1.ID_TRANSAKSI

		   WHEN COALESCE(URSN_1.KOD, URSN_2.KOD) IN ('HDHK', 'HDHD', 'KVSPM')
    AND NOT (
      DHAS_1.MODUL = 'PNT'
      AND HNTR_1.ID_PENGHANTARAN LIKE 'PNL/%'
      AND APP_1.MKLMT_TMBHN IS NOT NULL
      AND APP_1.MKLMT_TMBHN::jsonb ->> 'idPengenalanInduk' IS NOT NULL
    )
  THEN
    COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI) || 
    ' ' || (
      SELECT ID_PENGENALAN 
      FROM UMM_APLIKASI 
      WHERE NO_RUJUKAN_FAIL = COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
      LIMIT 1
    )

  WHEN DHAS_1.MODUL = 'PNT'
    AND HNTR_1.ID_PENGHANTARAN LIKE 'PNL/%'
    AND APP_1.MKLMT_TMBHN IS NOT NULL
    AND APP_1.MKLMT_TMBHN::jsonb ->> 'idPengenalanInduk' IS NOT NULL
  THEN
    APP_1.MKLMT_TMBHN::jsonb ->> 'idPengenalanInduk'

		  ELSE
		    COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
		END AS ID_PERMOHONAN_DASHBOARD,
	
		  CASE
		    WHEN DHAS_1.kod_tgsn IN ('PPF', 'PPJUB', 'PPPK', 'PPSYT') THEN org_nama.nama
		    WHEN URSN_1.kod = 'PPLBL' THEN pelelong_nama.nama_pemohon
		    ELSE bkptg_nama.nama
		  END AS NAMA_PEMOHON,
		  COALESCE(KS.NO_KERTAS_SIASATAN, APP_1.NO_RUJUKAN_FAIL, '') as NO_FAIL_PEMOHON
		    
		


FROM UMM_TGSN_SEMASA DHAS_1

LEFT JOIN UMM_APLIKASI APP_1 ON DHAS_1.APLIKASI_ID = APP_1.APLIKASI_ID
LEFT JOIN UMM_APLIKASI APP_2 ON DHAS_1.APLIKASI_ID = APP_2.APLIKASI_ID
LEFT JOIN IND_URSN URSN_1 ON APP_2.URSN_ID = URSN_1.URSN_ID

LEFT JOIN IND_MODUL MDL_1 ON URSN_1.MODUL_ID = MDL_1.MODUL_ID

LEFT JOIN UMM_APLIKASI APP_3 ON DHAS_1.APLIKASI_ID = APP_3.APLIKASI_ID
LEFT JOIN UMM_APLIKASI APP_4 ON APP_3.HUBUNGAN_APLIKASI_ID = APP_4.APLIKASI_ID

LEFT JOIN UMM_P_APLIKASI APP_A_1 ON DHAS_1.P_APLIKASI_ID = APP_A_1.P_APLIKASI_ID
LEFT JOIN UMM_P_APLIKASI APP_A_2 ON DHAS_1.P_APLIKASI_ID = APP_A_2.P_APLIKASI_ID
LEFT JOIN IND_URSN URSN_2 ON APP_A_2.URSN_ID = URSN_2.URSN_ID
LEFT JOIN UMM_P_APLIKASI APP_A_3 ON DHAS_1.P_APLIKASI_ID = APP_A_3.P_APLIKASI_ID

LEFT JOIN RJK_JNS_URSN RJU_1  on URSN_1.JNS_URSN_ID = RJU_1.JNS_URSN_ID
LEFT JOIN RJK_SENARAI_AHLI_KUMPULAN SNR_1 ON APP_A_3.STATUS_ID = SNR_1.SENARAI_AHLI_KUMPULAN_ID

LEFT JOIN UMM_A_TGSN APP_TGSN_1 ON DHAS_1.A_TGSN_ID = APP_TGSN_1.A_TGSN_ID
LEFT JOIN UMM_A_TGSN APP_TGSN_2 ON DHAS_1.A_TGSN_ID = APP_TGSN_2.A_TGSN_ID
LEFT JOIN IND_TGSN ITG_1 ON APP_TGSN_2.TGSN_ID = ITG_1.TGSN_ID

LEFT JOIN UMM_A_TGSN APP_A_4 ON DHAS_1.A_TGSN_ID = APP_A_4.A_TGSN_ID
LEFT JOIN PCP_PENGGUNA PGN_1 ON APP_A_4.PENGGUNA_SEMASA_ID = PGN_1.PENGGUNA_ID

LEFT JOIN UMM_MKLMT_LAPORAN_SIASATAN MLS ON DHAS_1.MKLMT_LAPORAN_SIASATAN_ID = MLS.MKLMT_LAPORAN_SIASATAN_ID

LEFT JOIN IND_PEJABAT IPJ_1 ON DHAS_1.PEJABAT_ID = IPJ_1.PEJABAT_ID
LEFT JOIN UMM_HANTARAN_NOTIS HNTR_1 ON DHAS_1.HANTARAN_NOTIS_ID = HNTR_1.HANTARAN_NOTIS_ID
LEFT JOIN PKS_A_KERTAS_SIASATAN KS ON DHAS_1.A_KERTAS_SIASATAN_ID = KS.A_KERTAS_SIASATAN_ID




LEFT JOIN LATERAL (
	  SELECT o.nama
	  FROM umm_p_daftar_organisasi o
	  WHERE o.p_daftar_organisasi_id IN (
	    SELECT MIN(o2.p_daftar_organisasi_id)
	    FROM umm_p_daftar_organisasi o2
	    WHERE APP_A_1.id_transaksi = APP_1.id_pengenalan
	  )
	  LIMIT 1
	) AS org_nama ON DHAS_1.kod_tgsn IN ('PPF', 'PPJUB', 'PPPK', 'PPSYT')
	
	-- Join nama pelelong jika kod urusan 'PPLBL'
	LEFT JOIN LATERAL (
	  SELECT p.nama_pemohon
	  FROM llg_a_daftar_pelelong p
	  WHERE p.aplikasi_id = DHAS_1.aplikasi_id
	  ORDER BY p.a_daftar_pelelong_id ASC
	  LIMIT 1
	) AS pelelong_nama ON URSN_1.kod = 'PPLBL'
	
	-- Join nama pihak berkepentingan
	LEFT JOIN LATERAL (
	  SELECT r.nama
	  FROM umm_a_pihak_bkptg r
	  WHERE r.aplikasi_id = DHAS_1.aplikasi_id
	    AND UPPER(r.flag_pemohon) = 'Y'
	  ORDER BY r.a_pihak_bkptg_id ASC
	  LIMIT 1
	) AS bkptg_nama ON TRUE
  	
	WHERE UPPER(DHAS_1.FLAG_TGSN_SISTEM) = 'N'
	AND (DHAS_1.NAMA_PENGGUNA = var_nama_pengguna OR DHAS_1.NAMA_PENGGUNA IS NULL)
	AND (EXISTS (
        SELECT 1 FROM VAR_PERANAN_KOD_PENGGUNA PKP
        WHERE PKP.NAMA_PENGGUNA = DHAS_1.NAMA_PENGGUNA AND PKP.peranan_kod = 'PTG'
    	) OR DHAS_1.PEJABAT_ID IN (SELECT PEJABAT_ID FROM VAR_PEJABAT_TERKAIT) OR DHAS_1.PEJABAT_ID IS NULL
	)

	AND (
		URSN_1.KOD IN (SELECT KOD FROM VAR_URUSAN_KOD_LIST)
		OR URSN_2.KOD IN (SELECT KOD FROM VAR_URUSAN_KOD_LIST)
	)

	AND EXISTS ( 
		SELECT 1
		FROM VAR_PERANAN_KOD_PENGGUNA PKP
		WHERE DHAS_1.PERANAN LIKE '%-' || PKP.PERANAN_KOD || '-%'
	)
	AND (APP_TGSN_1.A_TGSN_ID is null or APP_TGSN_1.A_TGSN_ID is not null )
	--IF 
		AND (
		    var_modul_kod IS NULL 
		    OR DHAS_1.modul = var_modul_kod
			AND (var_modul_kod = 'DFT' AND RJU_1.KOD = var_urusan_mdl_kod)

			or  (var_modul_kod != 'DFT' AND COALESCE(URSN_1.KOD, URSN_2.KOD) = var_urusan_mdl_kod)
		)
	-- END 
	),

VAR_GROUPED_TUGAS AS (
    SELECT
        mq.*,
        ROW_NUMBER() OVER (PARTITION BY ua.no_fail, mq.kod_tgsn ORDER BY mq.tgsn_semasa_id) AS rn
    FROM MAIN_QUERY mq
    LEFT JOIN umm_aplikasi ua ON mq.aplikasi_id = ua.aplikasi_id
    WHERE mq.kod_tgsn IN ('PPBKRPDPJPM', 'PPBKRSDPJPM', 'PPBKRCDPJPM') 
),
VAR_MODUL_PENGGUNA AS (
  SELECT DISTINCT p.nama_pengguna, m.kod AS modul_kod
  FROM pcp_capaian_pengguna cp
  JOIN pcp_pengguna p ON cp.pengguna_id = p.pengguna_id
  JOIN pcp_peranan_modul pm ON cp.peranan_modul_id = pm.peranan_modul_id
  JOIN ind_modul m ON pm.modul_id = m.modul_id
  WHERE p.nama_pengguna IN (var_nama_pengguna) 
    AND m.kod IN ('PNT', 'UAM')
),

VAR_BELUM_TUKAR_GANTI AS (
 SELECT unnest(ARRAY['HMSC', 'HMSTP', 'PRBB', 'OPRBB', 'HDHD', 'HMPV', 'HMV','HMVB','SSHM','SSSC','SW','SA','CRHMB','CSHMB','BETUL','PACT','PKH','PMKMH','PFT','REM','REMITAN'])
),
FINAL_QUERY_V1 AS (
	SELECT * FROM MAIN_QUERY AS DEFAULT_MAIN_PNT
	WHERE EXISTS (
	    SELECT 1
	    FROM VAR_MODUL_PENGGUNA mp
	    WHERE mp.nama_pengguna = DEFAULT_MAIN_PNT.nama_pengguna
	      OR DEFAULT_MAIN_PNT.modul IN ('PNT', 'UAM')
	  )
	AND DEFAULT_MAIN_PNT.kod_tgsn NOT IN ('KD', 'STRKD')
		AND NOT (
		  DEFAULT_MAIN_PNT.modul = 'CON'
		  AND DEFAULT_MAIN_PNT.kod_tgsn IN ('CSK', 'JSK')
		)
	UNION ALL
	SELECT * FROM MAIN_QUERY AS DEFAULT_MAIN
	WHERE DEFAULT_MAIN.KOD_TGSN NOT IN ('KD', 'STRKD')
	AND NOT (
	    DEFAULT_MAIN.MODUL = 'CON' AND 
	    (DEFAULT_MAIN.KOD_TGSN = 'CSK' OR DEFAULT_MAIN.KOD_TGSN = 'JSK')
	)
	AND DEFAULT_MAIN.MODUL NOT IN ('PNT', 'UAM')
	AND NOT (
	    DEFAULT_MAIN.kod_tgsn IN ('KD', 'STRKD')
	    OR (DEFAULT_MAIN.NAMA_PENGGUNA IS NOT NULL AND DEFAULT_MAIN.NAMA_PENGGUNA <> var_nama_pengguna)
	)
	AND NOT (
	    DEFAULT_MAIN.KOD_TGSN = 'PTBUT'
	    AND DEFAULT_MAIN.URUSAN_KOD IN ('PMQFT', 'PMQTFT')
	)

),

FIANL_QUERY_MERGE as (
	select * FROM FINAL_QUERY_V1 as FN_Q1
	WHERE NOT EXISTS (
		SELECT 1
   		FROM VAR_FILTER_TUGASAN_KOD_SET 
		 WHERE
	      (
	        stgsn_kod = 'PTB'
	        AND FN_Q1.KOD_TGSN LIKE '%' || stgsn_kod || '%'
	      )
			OR (
		    stgsn_kod <> 'PTB'
			  AND FN_Q1.KOD_TGSN = stgsn_kod
			)
	)

 	UNION ALL
	SELECT * from (

		SELECT DISTINCT ON (FN_Q1_v2.KOD_TGSN) FN_Q1_v2.*
		FROM FINAL_QUERY_V1 as FN_Q1_v2
		WHERE EXISTS (
			 SELECT 1
      		FROM VAR_FILTER_TUGASAN_KOD_SET
			where (
					UPPER(FN_Q1_v2.STATUS_PROSES) <> 'GANTUNG'

					AND (
			          (stgsn_kod = 'PTB' AND FN_Q1_v2.KOD_TGSN LIKE '%' || stgsn_kod || '%')
			          OR (stgsn_kod = 'SJR' AND FN_Q1_v2.KOD_TGSN LIKE '%' || stgsn_kod || '%')
			          OR (stgsn_kod = 'CTK_JR' AND FN_Q1_v2.KOD_TGSN LIKE '%' || stgsn_kod || '%')
			          OR (stgsn_kod = 'PJR' AND FN_Q1_v2.KOD_TGSN LIKE '%' || stgsn_kod || '%')
			          OR (
			            stgsn_kod NOT IN ('PTB', 'SJR', 'CTK_JR', 'PJR')
			            AND FN_Q1_v2.KOD_TGSN = stgsn_kod
			          )
			        )
			) order by FN_Q1_v2.KOD_TGSN, FN_Q1_v2.tgsn_semasa_id desc
		) limit 1 
	)

),
VAR_USER_PERANAN AS (
  SELECT LOWER(mdl.kod) AS modul, LOWER(sak.kod) AS peranan
  FROM pcp_capaian_pengguna cp
  JOIN pcp_pengguna pg ON cp.pengguna_id = pg.pengguna_id
  JOIN pcp_peranan_modul pm ON cp.peranan_modul_id = pm.peranan_modul_id
  JOIN ind_modul mdl ON pm.modul_id = mdl.modul_id
  JOIN rjk_senarai_ahli_kumpulan sak ON pm.peranan_id = sak.senarai_ahli_kumpulan_id
  WHERE pg.nama_pengguna = var_nama_pengguna
),
FINAL_QUERY AS (
  SELECT * 
  FROM FIANL_QUERY_MERGE AS DEFAULT_MAIN
  WHERE 1=1

	AND 
    (
      var_status_tugasan IS NULL
      OR UPPER(var_status_tugasan) NOT IN ('BARU', 'SEMASA')
      OR (
        UPPER(var_status_tugasan) = 'BARU' AND UPPER(DEFAULT_MAIN.STATUS_TUGASAN) = 'BARU'
      )
      OR (
        UPPER(var_status_tugasan) = 'SEMASA' AND UPPER(DEFAULT_MAIN.STATUS_TUGASAN) = 'DALAM TINDAKAN'
      )
    )
 AND (
    -- Ambil jika bukan PTB dan nama_pengguna tidak kosong
    (
      DEFAULT_MAIN.kod_tgsn NOT ILIKE '%PTB%'
      AND COALESCE(TRIM(DEFAULT_MAIN.nama_pengguna), '') <> ''
    )
    -- Atau: jika PTB / nama kosong, validasi modul dan peranan terhadap VAR_USER_PERANAN
    OR EXISTS (
      SELECT 1
      FROM VAR_USER_PERANAN u
      WHERE LOWER(u.modul) = LOWER(DEFAULT_MAIN.modul)
        AND EXISTS (
          SELECT 1
          FROM unnest(string_to_array(LOWER(DEFAULT_MAIN.peranan), '-')) AS p(peranan)
          WHERE p.peranan = u.peranan
        )
        AND (
          DEFAULT_MAIN.kod_tgsn ILIKE '%PTB%'
          OR COALESCE(TRIM(DEFAULT_MAIN.nama_pengguna), '') = ''
        )
    )
  
    )
    AND NOT (
      DEFAULT_MAIN.id_rujukan_smartbox IS NOT NULL
      AND DEFAULT_MAIN.id_rujukan_smartbox <> ''
      AND DEFAULT_MAIN.kod_tgsn IN ('ISHSB', 'KDSB')
    )
),

URUSAN_MODUL_PARENT_CTE AS (
  SELECT 
    A.APLIKASI_ID as APP_ID_CTE,
    M.KOD AS URUSAN_MODUL_PARENT
  FROM UMM_APLIKASI A
  LEFT JOIN IND_URSN U ON A.URSN_ID = U.URSN_ID
  LEFT JOIN IND_MODUL M ON U.MODUL_ID = M.MODUL_ID
),

VAR_CONSENT_KOD AS (
    SELECT unnest(ARRAY['PFMMK', 'PPPTG', 'SFMMK', 'SPTPTG', 'KPTG','KTPTG','KCADO','KDO','PDO','STSKP','KPTG2', 'KMB'])
),
CONSENT_FILTER AS (
	SELECT *
	FROM FINAL_QUERY f
	WHERE f.MODUL = 'CON'
	  AND NOT (
	    f.urusan_kod_dashboard = 'KPMP'
	    AND var_kod_negri = '08' -- 11= param
	  )
	  AND f.KOD_TGSN IN (SELECT * FROM VAR_CONSENT_KOD) 
),


CONSENT_FILTER_ONE as (
	SELECT *
	FROM CONSENT_FILTER CON
--	ORDER BY CON.tgsn_semasa_id
--	LIMIT 1
),

FINAL_FILTER_CON as (
SELECT *
	FROM FINAL_QUERY a
--	WHERE a.modul <> 'CON'

	UNION ALL

	SELECT * FROM CONSENT_FILTER_ONE
),

FINAL_FILTER_ALL  AS (
	SELECT * FROM FINAL_FILTER_CON AS FQ
	
	WHERE 1=1
	AND NOT (
		FQ.MODUL = 'PFIKM'   
		OR FQ.ID_TGSN IN (SELECT ID_TGSN_PELUPUSAN_PENGGUNA_FILTER FROM VAR_PELUPUSAN_TUGASAN_FILTERED)	
  	)
	AND NOT (FQ.modul = 'UAM' AND FQ.URUSAN_KOD = 'BIO')

    AND NOT (
      COALESCE(TRIM(FQ.locked_by), '') <> ''
      AND LOWER(FQ.locked_by) <> LOWER(var_nama_pengguna)
      AND FQ.locked_date IS NOT NULL
      AND FQ.locked_date > NOW() - INTERVAL '30 minutes'
    )
-- NEW 
OR FQ.modul IS NULL
	 
),

FINAL_FILTER_ALL_V2 as (
	SELECT * FROM FINAL_FILTER_ALL
),


FINAL_RESULT AS (
	SELECT * ,
	CASE 
	  WHEN EXISTS (
	    SELECT 1
	    FROM UMM_PERTANYAAN p
	    JOIN RJK_SENARAI_AHLI_KUMPULAN k ON p.STATUS_ID = k.SENARAI_AHLI_KUMPULAN_ID
	    JOIN UMM_APLIKASI a ON p.APLIKASI_ID = a.APLIKASI_ID
	    JOIN IND_URSN u ON a.URSN_ID = u.URSN_ID
	    WHERE p.A_TGSN_ID = FQ.APP_A_TGSN_ID
	      AND k.KOD != 'SELESAI'
	      AND u.TEMPOH_KUIRI ~ '^[0-9]+$'
	      AND DATE_PART('day', CURRENT_DATE - p.CREATED_DATE) > u.TEMPOH_KUIRI::INT
	  )
	  THEN ' (Pertanyaan) - Telah Melebihi Tempoh Kuiri'
	
	  WHEN EXISTS (
	    SELECT 1
	    FROM UMM_PERTANYAAN p
	    JOIN RJK_SENARAI_AHLI_KUMPULAN k ON p.STATUS_ID = k.SENARAI_AHLI_KUMPULAN_ID
	    WHERE p.A_TGSN_ID = FQ.APP_A_TGSN_ID
	      AND k.KOD != 'SELESAI'
	  )
	  THEN ' (Pertanyaan)'
	
	  ELSE NULL
	END AS pertanyaan_keterangan,


	--	color and flag
	CASE 
	    WHEN (
	        CASE
	            WHEN FQ.MINIT_KPI IS NOT NULL 
	                 AND FQ.TRKH_PNRMAN IS NOT NULL 
	                 AND FQ.DHAS_1_TRKH_KPI IS NULL
	            THEN FQ.TRKH_PNRMAN + (FQ.MINIT_KPI || ' minutes')::INTERVAL
	            ELSE FQ.DHAS_1_TRKH_KPI
	        END
	    ) IS NOT NULL 
	    AND (
	        CASE
	            WHEN FQ.MINIT_KPI IS NOT NULL 
	                 AND FQ.TRKH_PNRMAN IS NOT NULL 
	                 AND FQ.DHAS_1_TRKH_KPI IS NULL
	            THEN FQ.TRKH_PNRMAN + (FQ.MINIT_KPI || ' minutes')::INTERVAL
	            ELSE FQ.DHAS_1_TRKH_KPI
	        END
	    ) < CURRENT_DATE
	THEN 'TUNGGAK'
	ELSE NULL
	END AS STATUS,
	CASE 
	    WHEN (
	        CASE
	            WHEN FQ.MINIT_KPI IS NOT NULL 
	                 AND FQ.TRKH_PNRMAN IS NOT NULL 
	                 AND FQ.TRKH_KPI IS NULL
	            THEN FQ.TRKH_PNRMAN + (FQ.MINIT_KPI || ' minutes')::INTERVAL
	            ELSE FQ.DHAS_1_TRKH_KPI
	        END
	    ) IS NOT NULL 
	    AND (
	        CASE
	            WHEN FQ.MINIT_KPI IS NOT NULL 
	                 AND FQ.TRKH_PNRMAN IS NOT NULL 
	                 AND FQ.TRKH_KPI IS NULL
	            THEN FQ.TRKH_PNRMAN + (FQ.MINIT_KPI || ' minutes')::INTERVAL
	            ELSE FQ.DHAS_1_TRKH_KPI
	        END
	    ) < CURRENT_DATE
	THEN 'red' -- warna merah sebagai contoh
	ELSE NULL
	END AS COLOR,


	CASE
	    WHEN NOT FQ.SHOW_KPI THEN 'Hijau'
	    WHEN FQ.TARIKH_DAN_MASA_LUPUT_STRING IS NULL OR FQ.TARIKH_DAN_MASA_LUPUT_STRING = '-' THEN 'Hijau'
	    WHEN FQ.TRKH_TETAP IS NULL THEN
	        CASE
	            WHEN TO_DATE(FQ.TARIKH_DAN_MASA_LUPUT_STRING, 'DD/MM/YYYY') >= CURRENT_DATE THEN 'Hijau'
	            ELSE 'Merah'
	        END
	    WHEN TO_DATE(FQ.TARIKH_DAN_MASA_LUPUT_STRING, 'DD/MM/YYYY') <= FQ.TRKH_TETAP::DATE THEN 'Hijau'
	    ELSE 'Merah'
	END AS FLAG_STATUS,

	--end color and flag

CASE
  WHEN FQ.KOD_TGSN = 'ISH' THEN TRUE
  WHEN FQ.MODUL = 'KKS' THEN TRUE
  WHEN FQ.MODUL = 'PNT' AND URUSAN_MODUL_PARENT = 'KKS' THEN TRUE
  WHEN EXISTS (
    SELECT 1
    FROM UNNEST(STRING_TO_ARRAY(FQ.URUSAN_KOD_DASHBOARD, '<BR />')) AS URSN
    WHERE URSN IN (SELECT * FROM VAR_BELUM_TUKAR_GANTI)
  ) THEN TRUE
  WHEN EXISTS (
    SELECT 1
    FROM UNNEST(STRING_TO_ARRAY(FQ.URUSAN_KOD_DASHBOARD, '<BR />')) AS URSN
    WHERE URSN IS NOT NULL
      AND (
        URSN NOT IN (SELECT * FROM VAR_BELUM_TUKAR_GANTI)
        OR URSN IN (SELECT * FROM VAR_ALSAN_TUKARGANTI_KOD_SET_BATAL)
      )
or (
    (
      SELECT COUNT(*) FROM DFT_A_MOHON_HKMLK HM
      JOIN IND_MKLMT_HKMLK MH ON MH.mklmt_hkmlk_id = HM.ID_HKMLK
      JOIN rjk_senarai_ahli_kumpulan o ON o.senarai_ahli_kumpulan_id = MH.status_hkmlk_id
      WHERE HM.APLIKASI_ID = FQ.APLIKASI_ID AND o.kod = 'STAHMBT'
    ) = (
      SELECT COUNT(*) FROM DFT_A_MOHON_HKMLK HM
      WHERE HM.APLIKASI_ID = FQ.APLIKASI_ID
    )
    or NOT EXISTS (
      SELECT 1
      FROM DFT_A_MOHON_HKMLK HM
      JOIN IND_MKLMT_HKMLK MH ON MH.mklmt_hkmlk_id = HM.ID_HKMLK
      JOIN RJK_SENARAI_AHLI_KUMPULAN o ON o.senarai_ahli_kumpulan_id = MH.status_hkmlk_id
      WHERE HM.APLIKASI_ID = FQ.APLIKASI_ID
      AND o.kod = 'STAHDFT'
      AND EXISTS (
        SELECT 1 FROM IND_VERSI_DHD TG WHERE TG.hkmlk_id = HM.ID_HKMLK
      )
    )
  )
  )
  
  THEN TRUE
  ELSE FALSE
END AS IS_HAKMILIK_BELUM_TUKARGANTI,



CASE 
  WHEN FQ.TARIKH_DAN_MASA_LUPUT IS NULL THEN '-' 

  WHEN FQ.TARIKH_DAN_MASA_LUPUT <= NOW() THEN '0 Hari'

  WHEN DATE_PART('month', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 THEN
    TRIM(BOTH FROM CONCAT_WS(' ',
      CASE 
        WHEN DATE_PART('month', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('month', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Bulan' 
      END,
      CASE 
        WHEN DATE_PART('day', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('day', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Hari' 
      END,
      CASE 
        WHEN DATE_PART('hour', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('hour', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Jam' 
      END,
      CASE 
        WHEN DATE_PART('minute', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('minute', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Minit' 
      END
    ))

  ELSE
    TRIM(BOTH FROM CONCAT_WS(' ',
      CASE 
        WHEN DATE_PART('day', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('day', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Hari' 
      END,
      CASE 
        WHEN DATE_PART('hour', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('hour', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Jam' 
      END,
      CASE 
        WHEN DATE_PART('minute', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('minute', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Minit' 
      END
    ))
END AS BAKI_MASA





	
FROM FINAL_FILTER_ALL_V2 AS FQ 
LEFT JOIN URUSAN_MODUL_PARENT_CTE UMP ON UMP.APP_ID_CTE = FQ.APP_ID
	where UPPER(FQ.STATUS_TUGASAN) <> 'SELESAI'
--	AND NOT (
--		FQ.MODUL = 'PFIKM'   
--		OR FQ.ID_TGSN IN (SELECT ID_TGSN_PELUPUSAN_PENGGUNA_FILTER FROM VAR_PELUPUSAN_TUGASAN_FILTERED)	
--  	)
--AND NOT (FQ.modul = 'UAM' AND FQ.URUSAN_KOD = 'BIO')
 


),



 RANGKAIAN_MERGERED AS (
    SELECT 
    MAX(fd.TGSN_SEMASA_ID)::BIGINT AS ID,
    MAX(fd.TRKH_PNRMAN) AS TRKH_PEN,
    MAX(fd.TARIKH_PENERIMAAN_STRING) AS TARIKH_PENERIMAAN_STRING,
    MAX(fd.TARIKH_DAN_MASA_LUPUT_STRING) AS TARIKH_DAN_MASA_LUPUT_STRING,
    STRING_AGG(fd.ID_HKMLK, '<br />') AS no_hakmilik,
    ra.RANGKAIAN_ID::TEXT AS rangkaian_id_merged,
    fd.kod_tgsn::TEXT,
    STRING_AGG(fd.ID_PERMOHONAN_DASHBOARD ::TEXT, '<br />') AS id_permohonan,
    STRING_AGG(fd.URUSAN_KOD_DASHBOARD ::TEXT, '<br />') AS urusan,
    MAX(fd.NO_FAIL_PEMOHON) AS NO_FAIL_PEMOHON,
    STRING_AGG(fd.NO_RESIT_DASHBOARD :: TEXT, '<br />') AS no_resit,
	MAX(fd.TGSN_PERIHAL) as tugas,
    MAX(fd.NAMA_PEMOHON) AS NAMA_PEMOHON,
    MAX(fd.NAMA_PEJABAT_PENDEK) AS PEJABAT,
    MAX(fd.ID_PENGHANTARAN) AS ID_PENYAMPAIAN,
	MAX(fd.APP_A_TGSN_ID ) as id_APP_A_TGSN,
	MAX(fd.APLIKASI_ID),
	MAX(fd.pertanyaan_keterangan) AS pertanyaan_keterangan,
	MAX(fd.TARIKH_SIASATAN_STRING) as TARIKH_SIASATAN_STRING,
	MAX(fd.STATUS) as ROW_STATUS,
	MAX(fd.COLOR) as ROW_COLOR,
	MAX(fd.FLAG_STATUS) as FLAG_STATUS,
	(MAX(CASE WHEN fd.IS_HAKMILIK_BELUM_TUKARGANTI THEN 1 ELSE 0 END) = 1),
	MAX(fd.BAKI_MASA) as BAKI_MASA,
	MAX(fd.NO_HAKMILIK_BARU) as NO_HAKMILIK_BARU,
MAX(fd.MODUL) as MODUL

    FROM FINAL_RESULT fd
    JOIN UMM_APLIKASI ra ON fd.APLIKASI_ID = ra.APLIKASI_ID
    WHERE ra.RANGKAIAN_ID IS NOT NULL AND fd.kod_tgsn <> 'IMH'
    GROUP BY ra.RANGKAIAN_ID, fd.kod_tgsn
  ),

  REMAINING_ROW AS (
    SELECT 
    fd.TGSN_SEMASA_ID::BIGINT AS ID,
    fd.TRKH_PNRMAN AS TRKH_PEN,
    fd.TARIKH_PENERIMAAN_STRING,
    fd.TARIKH_DAN_MASA_LUPUT_STRING,
    fd.ID_HKMLK AS no_hakmilik,
      NULL::TEXT AS rangkaian_id_merged,
    fd.kod_tgsn::TEXT,
    fd.ID_PERMOHONAN_DASHBOARD AS id_permohonan,
    fd.URUSAN_KOD_DASHBOARD AS urusan,
    fd.NO_FAIL_PEMOHON AS NO_FAIL_PEMOHON,
    fd.NO_RESIT_DASHBOARD AS no_resit,
	fd.TGSN_PERIHAL as tugas,
    fd.NAMA_PEMOHON AS NAMA_PEMOHON,
    fd.NAMA_PEJABAT_PENDEK AS PEJABAT,
    fd.ID_PENGHANTARAN AS ID_PENYAMPAIAN,
	fd.APP_A_TGSN_ID as id_APP_A_TGSN,
	fd.APLIKASI_ID,
	fd.pertanyaan_keterangan,
	fd.TARIKH_SIASATAN_STRING as TARIKH_SIASATAN_STRING,
	fd.STATUS as ROW_STATUS,
	fd.COLOR as ROW_COLOR,
	fd.FLAG_STATUS as FLAG_STATUS, 
	fd.IS_HAKMILIK_BELUM_TUKARGANTI,
	fd.BAKI_MASA as BAKI_MASA, 
	fd.NO_HAKMILIK_BARU as NO_HAKMILIK_BARU,
fd.MODUL as MODUL
    FROM FINAL_RESULT fd
    LEFT JOIN UMM_APLIKASI ra ON fd.APLIKASI_ID = ra.APLIKASI_ID
--    testing
--	WHERE ra.RANGKAIAN_ID IS NULL OR fd.kod_tgsn = 'IMH'
  ),

--   FINAL_V2 AS (
--     SELECT * FROM RANGKAIAN_MERGERED
--     UNION ALL
--     SELECT * FROM REMAINING_ROW
--   ),
 


FINAL_V2 AS (
    SELECT DISTINCT ON (merged.id) merged.*
    FROM (
        SELECT * FROM RANGKAIAN_MERGERED
        UNION ALL
        SELECT * FROM REMAINING_ROW
    ) merged

    WHERE (
        var_modul_kod IS NULL
        OR (
            merged.modul = var_modul_kod
            AND (
                var_modul_kod <> 'DFT'
                OR (
                    var_modul_kod = 'DFT'
                    AND merged.id IN (
                        SELECT 
                            d.tgsn_semasa_id
                        FROM UMM_TGSN_SEMASA d
                        INNER JOIN UMM_APLIKASI a ON d.aplikasi_id = a.APLIKASI_ID
                        INNER JOIN IND_URSN u ON a.URSN_ID = u.URSN_ID
                        INNER JOIN RJK_JNS_URSN j ON u.JNS_URSN_ID = j.JNS_URSN_ID
                        INNER JOIN IND_MODUL m ON u.MODUL_ID = m.MODUL_ID
                        WHERE 
                            m.kod = var_modul_kod
                            AND d.nama_pengguna = var_nama_pengguna
                            AND d.FLAG_TGSN_SISTEM = 'N'
                            AND d.pejabat_id = var_pejabat_id
                            AND d.TGSN_PERIHAL NOT IN ('Kutipan Dokumen', 'Imbasan Dokumen Hakmilik Batal')
                            AND a.status_keputusan <> 'Batal'
                            AND j.kod = var_urusan_mdl_kod
                    )
                )
            )
        )
    )

    ORDER BY merged.id, merged.trkh_pen DESC
),

   params AS (
    SELECT trim(c.col) AS fcol, trim(v.val) AS fval
    FROM unnest(string_to_array(var_filter_colum, ',')) WITH ORDINALITY AS c(col, idx)
    JOIN unnest(string_to_array(var_filter_val, '||')) WITH ORDINALITY AS v(val, idx2)
      ON c.idx = v.idx2
)


  SELECT count(*)
  FROM FINAL_V2 V2

WHERE
    -- Jika tidak ada filter sama sekali, kembalikan semua
    NOT EXISTS (SELECT 1 FROM params)
    
   OR (
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TARIKH_PENERIMAAN_STRING')
         OR v2.TARIKH_PENERIMAAN_STRING ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TARIKH_PENERIMAAN_STRING')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TARIKH_DAN_MASA_LUPUT_STRING')
         OR v2.TARIKH_DAN_MASA_LUPUT_STRING ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TARIKH_DAN_MASA_LUPUT_STRING')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TARIKH_SIASATAN_STRING')
         OR v2.TARIKH_SIASATAN_STRING ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TARIKH_SIASATAN_STRING')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'NO_HAKMILIK')
         OR v2.NO_HAKMILIK ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'NO_HAKMILIK')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'ID_PERMOHONAN')
         OR v2.ID_PERMOHONAN ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'ID_PERMOHONAN')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'NO_FAIL_PEMOHON')
         OR v2.NO_FAIL_PEMOHON ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'NO_FAIL_PEMOHON')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'NO_RESIT')
         OR v2.NO_RESIT ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'NO_RESIT')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'URUSAN')
         OR v2.URUSAN ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'URUSAN')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'NAMA_PEMOHON')
         OR v2.NAMA_PEMOHON ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'NAMA_PEMOHON')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'PERTANYAAN_KETERANGAN')
         OR v2.PERTANYAAN_KETERANGAN ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'PERTANYAAN_KETERANGAN')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TUGAS')
         OR v2.TUGAS ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TUGAS')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'PEJABAT')
         OR v2.PEJABAT ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'PEJABAT')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'ID_PENYAMPAIAN')
         OR v2.ID_PENYAMPAIAN ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'ID_PENYAMPAIAN')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TUGASAN')
         OR v2.TUGAS ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TUGASAN')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'FLAG_STATUS')
         OR v2.FLAG_STATUS ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'FLAG_STATUS')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'BAKI_MASA')
         OR v2.BAKI_MASA ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'BAKI_MASA')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TUGAS_AND_PERTANYAAN')
         OR (v2.TUGAS ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TUGAS_AND_PERTANYAAN'))
             OR v2.PERTANYAAN_KETERANGAN ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TUGAS_AND_PERTANYAAN'))))
    )

;


END;
$function$
;

-- DROP FUNCTION et_main_uat.get_count_dashboard_by_pengguna_v2(_text, text, numeric, text, text, text, text, text, text);

CREATE OR REPLACE FUNCTION et_main_uat.get_count_dashboard_by_pengguna_v2(var_urusan_kod_list text[], var_nama_pengguna text DEFAULT NULL::text, var_pejabat_id numeric DEFAULT NULL::numeric, var_modul_kod text DEFAULT NULL::text, var_urusan_mdl_kod text DEFAULT NULL::text, var_status_tugasan text DEFAULT NULL::text, var_id_pengenalan text DEFAULT NULL::text, var_filter_colum text DEFAULT NULL::text, var_filter_val text DEFAULT NULL::text)
 RETURNS TABLE(total bigint)
 LANGUAGE plpgsql
AS $function$
BEGIN
  RETURN QUERY
WITH VAR_URUSAN_KOD_LIST AS (
    SELECT UNNEST(var_urusan_kod_list) AS KOD
  ),
VAR_PERANAN_KOD_PENGGUNA AS (
  SELECT DISTINCT PP.NAMA_PENGGUNA, RM.KOD AS PERANAN_KOD
  FROM PCP_CAPAIAN_PENGGUNA CP
  JOIN PCP_PENGGUNA PP ON CP.PENGGUNA_ID = PP.PENGGUNA_ID
  JOIN PCP_PERANAN_MODUL PM ON CP.PERANAN_MODUL_ID = PM.PERANAN_MODUL_ID
  JOIN RJK_SENARAI_AHLI_KUMPULAN RM ON PM.PERANAN_ID = RM.SENARAI_AHLI_KUMPULAN_ID
  WHERE PP.NAMA_PENGGUNA IN (var_nama_pengguna)
),
VAR_DAERAH_PENGGUNA AS (
    SELECT DISTINCT DAERAH_ID
    FROM IND_PEJABAT AS IP
    WHERE PEJABAT_ID IN (var_pejabat_id) 
),
VAR_PEJABAT_TERKAIT AS (
    SELECT DISTINCT PEJABAT_ID
    FROM IND_PEJABAT AS IP
    WHERE DAERAH_ID IN (SELECT DAERAH_ID FROM VAR_DAERAH_PENGGUNA)
),
VAR_FILTER_TUGASAN_KOD_SET AS (
	SELECT UNNEST(ARRAY[ 'PPBKRPJPM', 'PPBKRKPJPM', 'PTB', 'SJR',
    'PJR', 'CTK_JR', 'PMMP6PTB2', 'PPBBPTB2',
    'PPHSYBPTB2', 'PKJR', 'PKJRPP']) as stgsn_kod
),

VAR_PELUPUSAN_TUGASAN_FILTERED AS (
  SELECT ID_TGSN AS ID_TGSN_PELUPUSAN_PENGGUNA_FILTER
  FROM (
    SELECT A.ID_TGSN,
        ROW_NUMBER() OVER (
            PARTITION BY COALESCE(C.kod, E.kod), A.ID_TGSN
            ORDER BY A.ID_TGSN
    ) AS RN
    FROM UMM_TGSN_SEMASA A
    LEFT JOIN UMM_APLIKASI B ON B.APLIKASI_ID = A.APLIKASI_ID
    LEFT JOIN IND_URSN C ON C.URSN_ID = B.URSN_ID
    LEFT JOIN UMM_P_APLIKASI D ON D.APLIKASI_ID = A.APLIKASI_ID
    LEFT JOIN IND_URSN E ON E.URSN_ID = D.URSN_ID
    WHERE A.MODUL = 'PLP'
      AND A.KOD_TGSN = 'FPIKM'
      AND UPPER(A.FLAG_TGSN_SISTEM) = 'N'
  ) A
  WHERE RN = 1
),
VAR_PEJABAT_PERANAN_MAP AS (
  SELECT * FROM (VALUES
    ('TRG', ARRAY['PTG', 'TPTG', 'KPP']),
    ('PRK', ARRAY['PTG', 'KPP']),
    ('SEL', ARRAY['PTG', 'TPTG'])
  ) AS T (KOD_PEJABAT, PERANANS)
),
VAR_PLP_TUGASAN_KOD_SET AS (
    SELECT unnest(ARRAY['PDKM', 'SDKM', 'SDKM2', 'SDKM3', 'PPKM', 'CKM', 'CKMPPLN'])
),
VAR_ALSAN_TUKARGANTI_KOD_SET AS (
    SELECT unnest(ARRAY['KMPP', 'HMSC', 'HMSTP', 'PRBB', 'OPRBB', 'HDHD', 'HMPV', 'HMV', 'HMVB',
            'SSHM', 'SSSC', 'SW', 'SA', 'CRHMB', 'CSHMB', 'BETUL', 'PACT', 'PKH', 'PMKMH', 'PFT', 'REM', 'REMITAN'])
),
VAR_GROUP_BY_NO_FAIL_TUGASAN_KOD_SET AS (
    SELECT unnest(ARRAY['PPBKRPDPJPM', 'PPBKRSDPJPM', 'PPBKRCDPJPM'])
),

VAR_ALSAN_TUKARGANTI_KOD_SET_BATAL AS (
    SELECT unnest(ARRAY['HDHK', 'HPLN','PMKMH','HSSTB','HKSSS'])
),
VAR_NO_HAK_MILIK_BARU AS (
    SELECT 
        mohon.APLIKASI_ID,
        STRING_AGG(mohon.id_hkmlk, '<br>') AS NO_HAKMILIK_BARU
    FROM dft_A_MOHON_HKMLK mohon
    JOIN UMM_APLIKASI appl ON appl.APLIKASI_ID = mohon.APLIKASI_ID
    JOIN IND_URSN urusan ON appl.URSN_ID = urusan.URSN_ID
    JOIN rjk_jns_ursn jenis ON jenis.jns_ursn_id = urusan.jns_ursn_id
    WHERE mohon.id_hkmlk IS NOT NULL
      AND jenis.KOD = 'MH'
    GROUP BY mohon.APLIKASI_ID
),
MAIN_QUERY AS (
	SELECT 
  	DHAS_1.TGSN_SEMASA_ID,
	DHAS_1.TRKH_PNRMAN,
	DHAS_1.MODUL,
	DHAS_1.ID_HKMLK,
	DHAS_1.NO_RESIT,
	DHAS_1.LOCKED_BY,
	DHAS_1.LOCKED_DATE,
	DHAS_1.PERANAN,
	DHAS_1.KOD_TGSN,
	DHAS_1.ID_TGSN,
	DHAS_1.TGSN_PERIHAL,
	DHAS_1.NAMA_PENGGUNA,
	APP_TGSN_1.TRKH_TETAP,
	APP_1.TRKH_PIAGAM,
	APP_1.APLIKASI_ID,
	APP_1.APLIKASI_ID as APP_ID,
	APP_1.RANGKAIAN_ID,
	APP_1.ID_PENGENALAN,
	APP_1.FLAG_INTEGRASI,
	APP_1.STATUS_KEPUTUSAN,
	COALESCE(APP_1.STATUS_PROSES, SNR_1.NAMA) AS STATUS_PROSES,
    COALESCE(URSN_1.KOD, URSN_2.KOD) AS URUSAN_KOD,
    COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI) AS NO_RUJUKAN,
	IPJ_1.NAMA_PENDEK,
	IPJ_1.KOD AS PEJABAT_KOD,
	HNTR_1.ID_PENGHANTARAN,
	DHAS_1.a_tgsn_id as APP_A_TGSN_ID,
	IPJ_1.NAMA_PENDEK as NAMA_PEJABAT_PENDEK,
	TO_CHAR(MLS.TRKH_SIASATAN, 'DD/MM/YYYY') AS TARIKH_SIASATAN_STRING,
	APP_1.ID_RUJUKAN_SMARTBOX,
	DHAS_1.TRKH_KPI AS DHAS_1_TRKH_KPI,
	ITG_1.MINIT_KPI,
	CASE 
      WHEN URSN_1.KOD = 'PSBS' AND DHAS_1.TGSN_PERIHAL = 'Penyediaan Fail Induk Kertas Mesyuarat' THEN FALSE
      ELSE TRUE 
    END AS SHOW_ID_HAKMILIK,
	(
      SELECT STRING_AGG(mohon.id_hkmlk, '<br>')
      FROM dft_A_MOHON_HKMLK mohon
      JOIN UMM_APLIKASI appl ON appl.APLIKASI_ID = mohon.APLIKASI_ID
      JOIN IND_URSN urusan ON appl.URSN_ID = urusan.URSN_ID
      JOIN rjk_jns_ursn jenis ON jenis.jns_ursn_id = urusan.jns_ursn_id
      WHERE mohon.APLIKASI_ID = DHAS_1.APLIKASI_ID
        AND mohon.id_hkmlk IS NOT NULL
        AND jenis.KOD = CAST('MH' AS VARCHAR)
    ) AS NO_HAKMILIK_BARU,
	
	CASE 
		WHEN DHAS_1.TRKH_KPI IS NULL 
		     AND ITG_1.MINIT_KPI IS NOT NULL 
		     AND DHAS_1.TRKH_PNRMAN IS NOT NULL
		THEN DHAS_1.TRKH_PNRMAN + (ITG_1.MINIT_KPI || ' minutes')::INTERVAL
		ELSE DHAS_1.TRKH_KPI
	END AS TRKH_KPI,
	CASE 
		WHEN APP_TGSN_1.STATUS_TUGASAN IS NULL 
			OR DHAS_1.TGSN_PERIHAL = 'Pengagihan Tugasan Baru' 
		THEN 'Baru'
		ELSE APP_TGSN_1.STATUS_TUGASAN
	END AS STATUS_TUGASAN,

	CASE 
		WHEN ITG_1.MINIT_KPI IS NOT NULL THEN TRUE
		ELSE FALSE
	END AS SHOW_KPI,
	CASE 
    WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
         AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
              OR DHAS_1.KOD_TGSN LIKE '%PTB%')
    THEN '-' 
    ELSE TO_CHAR(DHAS_1.TRKH_PNRMAN, 'DD/MM/YYYY')
	END AS TARIKH_PENERIMAAN_STRING,

	CASE 
	
		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
			AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
				OR DHAS_1.KOD_TGSN LIKE '%PTB%')
		THEN '-' 

		ELSE TO_CHAR(
			CASE
			WHEN ITG_1.MINIT_KPI IS NOT NULL 
				AND DHAS_1.TRKH_PNRMAN IS NOT NULL 
				AND DHAS_1.TRKH_KPI IS NULL
			THEN DHAS_1.TRKH_PNRMAN + (ITG_1.MINIT_KPI || ' minutes')::INTERVAL
			ELSE DHAS_1.TRKH_KPI
			END,
			'DD/MM/YYYY'
		)
	END AS TARIKH_DAN_MASA_LUPUT_STRING,
CASE
  WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL
       AND (
         DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
         OR DHAS_1.KOD_TGSN LIKE '%PTB%'
       )
  THEN NULL
  ELSE
    CASE
      WHEN ITG_1.MINIT_KPI IS NOT NULL
           AND DHAS_1.TRKH_PNRMAN IS NOT NULL
           AND DHAS_1.TRKH_KPI IS NULL
      THEN DHAS_1.TRKH_PNRMAN + (ITG_1.MINIT_KPI || ' minutes')::INTERVAL
      ELSE DHAS_1.TRKH_KPI
    END
END AS TARIKH_DAN_MASA_LUPUT,

	CASE 
		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
			AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
				OR DHAS_1.KOD_TGSN LIKE '%PTB%')
		THEN '-' 
		ELSE TO_CHAR(APP_1.TRKH_PIAGAM, 'DD/MM/YYYY')
	END AS TARIKH_PIAGAM_STRING,
	CASE 
		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
			AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
				OR DHAS_1.KOD_TGSN LIKE '%PTB%')
		THEN '-' 
		ELSE TO_CHAR(APP_TGSN_1.TRKH_TETAP, 'DD/MM/YYYY')
	END AS TARIKH_MULA_STRING,
	CASE 
		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
			AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
				OR DHAS_1.KOD_TGSN LIKE '%PTB%')
		THEN TRUE 
		ELSE FALSE 
	END AS IS_FILTER_TUGASAN,
	CASE
		WHEN ITG_1.MINIT_KPI IS NOT NULL 
			AND DHAS_1.TRKH_PNRMAN IS NOT NULL 
			AND DHAS_1.TRKH_KPI IS NULL
		THEN DHAS_1.TRKH_PNRMAN + (ITG_1.MINIT_KPI || ' minutes')::INTERVAL
		ELSE DHAS_1.TRKH_KPI
	END AS TARIKH_KPI,
	

	CASE 
	  WHEN NOT (
	    TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
	    AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
	         OR DHAS_1.KOD_TGSN LIKE '%PTB%')
	  )
	  THEN 
	    CASE 
	      WHEN COALESCE(NULLIF(TRIM(DHAS_1.ID_HKMLK), ''), '-') = '-' THEN '-'
	      ELSE (
	        SELECT 
	          CASE 
	            WHEN COUNT(*) > 10 
	            THEN (
	              SELECT string_agg(val, ', ') || '...'
	              FROM (
	                SELECT DISTINCT val
	                FROM unnest(string_to_array(DHAS_1.ID_HKMLK, ',')) AS val
	                ORDER BY val
	                LIMIT 10
	              ) sub
	            )
	            ELSE (
	              SELECT string_agg(DISTINCT val, ', ' ORDER BY val)
	              FROM unnest(string_to_array(DHAS_1.ID_HKMLK, ',')) AS val
	            )
	          END
	      )
	    END
	  ELSE COALESCE(NULLIF(TRIM(DHAS_1.ID_HKMLK), ''), '-') 
	END AS NO_HAKMILIK_DASHBOARD,
	CASE 
	  WHEN NOT (
	    TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
	    AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
	         OR DHAS_1.KOD_TGSN LIKE '%PTB%')
	  )
	  THEN COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
	  ELSE NULL
	END AS APLIKASI_NO_PERMOHONAN,
	
	
	CASE 
	  WHEN NOT (
	    TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
	    AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
	         OR DHAS_1.KOD_TGSN LIKE '%PTB%')
	  )
		  THEN 
		    CASE 
		      WHEN COALESCE(NULLIF(TRIM(DHAS_1.NO_RESIT), ''), '-') = '-' THEN '-'
		      ELSE (
		        SELECT 
		          CASE 
		            WHEN COUNT(*) > 10 
		            THEN (
		              SELECT string_agg(val, ', ') || '...'
		              FROM (
		                SELECT DISTINCT val
		                FROM unnest(string_to_array(DHAS_1.NO_RESIT, ',')) AS val
		                ORDER BY val
		                LIMIT 10
		              ) sub
		            )
		            ELSE (
		              SELECT string_agg(DISTINCT val, ', ' ORDER BY val)
		              FROM unnest(string_to_array(DHAS_1.NO_RESIT, ',')) AS val
		            )
		          END
		      )
		    END
		  ELSE COALESCE(NULLIF(TRIM(DHAS_1.NO_RESIT), ''), '-') 
		END AS NO_RESIT_DASHBOARD,
		
		
		CASE
		  WHEN NOT (
		    TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
		    AND (
		      DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
		      OR DHAS_1.KOD_TGSN LIKE '%PTB%'
		    )
		  )
		  THEN
		    CASE 
		      WHEN HNTR_1.ID_PENGHANTARAN IS NOT NULL AND HNTR_1.ID_PENGHANTARAN LIKE 'PNL/%'
		        THEN 'UPNL'
		      ELSE COALESCE(URSN_1.KOD, URSN_2.KOD)
		    END
		  ELSE
		    COALESCE(URSN_1.KOD, URSN_2.KOD)
		END AS URUSAN_KOD_DASHBOARD,

		CASE
		  WHEN UPPER(APP_1.FLAG_INTEGRASI) ='Y' THEN
		    CASE
		      WHEN COALESCE(COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI), '') LIKE '%MF%' 
		           AND COALESCE(COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI), '') LIKE '%(%' THEN
		        SPLIT_PART(COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI), '(', 1)
		        
		      WHEN COALESCE(APP_1.URSN_ID, URSN_2.URSN_ID) IS NOT NULL 
		           AND COALESCE(URSN_1.KOD, URSN_2.KOD) = 'KVSP' THEN
		        (
		          SELECT hubungan2.ID_PENGENALAN || ' / ' || COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
		          FROM UMM_APLIKASI hubungan1
		          JOIN UMM_APLIKASI hubungan2 ON hubungan1.ID_PENGENALAN = hubungan2.APLIKASI_ID
		          WHERE hubungan1.APLIKASI_ID = APP_1.APLIKASI_ID
		          LIMIT 1
		        )
		        
		      ELSE
		        (
		          SELECT hubungan.no_rujukan_fail || ' / ' || COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
		          FROM UMM_APLIKASI hubungan
		          WHERE hubungan.APLIKASI_ID = APP_1.APLIKASI_ID
		          LIMIT 1
		        )
		    END
		  WHEN DHAS_1.KOD_TGSN  = 'STRSPRAP' THEN
		    APP_A_1.ID_TRANSAKSI

		   WHEN COALESCE(URSN_1.KOD, URSN_2.KOD) IN ('HDHK', 'HDHD', 'KVSPM')
    AND NOT (
      DHAS_1.MODUL = 'PNT'
      AND HNTR_1.ID_PENGHANTARAN LIKE 'PNL/%'
      AND APP_1.MKLMT_TMBHN IS NOT NULL
      AND APP_1.MKLMT_TMBHN::jsonb ->> 'idPengenalanInduk' IS NOT NULL
    )
  THEN
    COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI) || 
    ' ' || (
      SELECT ID_PENGENALAN 
      FROM UMM_APLIKASI 
      WHERE NO_RUJUKAN_FAIL = COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
      LIMIT 1
    )

  WHEN DHAS_1.MODUL = 'PNT'
    AND HNTR_1.ID_PENGHANTARAN LIKE 'PNL/%'
    AND APP_1.MKLMT_TMBHN IS NOT NULL
    AND APP_1.MKLMT_TMBHN::jsonb ->> 'idPengenalanInduk' IS NOT NULL
  THEN
    APP_1.MKLMT_TMBHN::jsonb ->> 'idPengenalanInduk'

		  ELSE
		    COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
		END AS ID_PERMOHONAN_DASHBOARD,
	
		  CASE
		    WHEN DHAS_1.kod_tgsn IN ('PPF', 'PPJUB', 'PPPK', 'PPSYT') THEN org_nama.nama
		    WHEN URSN_1.kod = 'PPLBL' THEN pelelong_nama.nama_pemohon
		    ELSE bkptg_nama.nama
		  END AS NAMA_PEMOHON,
		  COALESCE(KS.NO_KERTAS_SIASATAN, APP_1.NO_RUJUKAN_FAIL, '') as NO_FAIL_PEMOHON,
		    
			
		CASE 
		  WHEN COALESCE(var_id_pengenalan, '') = '' THEN (
		    SELECT MIN(p.pertanyaan_id)
		    FROM umm_pertanyaan p
		    JOIN rjk_senarai_ahli_kumpulan k ON p.status_id = k.senarai_ahli_kumpulan_id
		    WHERE p.a_tgsn_id = app_tgsn_1.a_tgsn_id
		      AND k.kod != 'SELESAI'
		  )
		  ELSE NULL
		END AS app_tugasan_idpertanyaan_id_map
	



FROM UMM_TGSN_SEMASA DHAS_1

LEFT JOIN UMM_APLIKASI APP_1 ON DHAS_1.APLIKASI_ID = APP_1.APLIKASI_ID
LEFT JOIN UMM_APLIKASI APP_2 ON DHAS_1.APLIKASI_ID = APP_2.APLIKASI_ID
LEFT JOIN IND_URSN URSN_1 ON APP_2.URSN_ID = URSN_1.URSN_ID

LEFT JOIN UMM_APLIKASI APP_3 ON DHAS_1.APLIKASI_ID = APP_3.APLIKASI_ID
LEFT JOIN UMM_APLIKASI APP_4 ON APP_3.HUBUNGAN_APLIKASI_ID = APP_4.APLIKASI_ID

LEFT JOIN UMM_P_APLIKASI APP_A_1 ON DHAS_1.P_APLIKASI_ID = APP_A_1.P_APLIKASI_ID
LEFT JOIN UMM_P_APLIKASI APP_A_2 ON DHAS_1.P_APLIKASI_ID = APP_A_2.P_APLIKASI_ID
LEFT JOIN IND_URSN URSN_2 ON APP_A_2.URSN_ID = URSN_2.URSN_ID
LEFT JOIN UMM_P_APLIKASI APP_A_3 ON DHAS_1.P_APLIKASI_ID = APP_A_3.P_APLIKASI_ID

LEFT JOIN RJK_SENARAI_AHLI_KUMPULAN SNR_1 ON APP_A_3.STATUS_ID = SNR_1.SENARAI_AHLI_KUMPULAN_ID

LEFT JOIN UMM_A_TGSN APP_TGSN_1 ON DHAS_1.A_TGSN_ID = APP_TGSN_1.A_TGSN_ID
LEFT JOIN UMM_A_TGSN APP_TGSN_2 ON DHAS_1.A_TGSN_ID = APP_TGSN_2.A_TGSN_ID
LEFT JOIN IND_TGSN ITG_1 ON APP_TGSN_2.TGSN_ID = ITG_1.TGSN_ID

LEFT JOIN UMM_A_TGSN APP_A_4 ON DHAS_1.A_TGSN_ID = APP_A_4.A_TGSN_ID
LEFT JOIN PCP_PENGGUNA PGN_1 ON APP_A_4.PENGGUNA_SEMASA_ID = PGN_1.PENGGUNA_ID

LEFT JOIN UMM_MKLMT_LAPORAN_SIASATAN MLS ON DHAS_1.MKLMT_LAPORAN_SIASATAN_ID = MLS.MKLMT_LAPORAN_SIASATAN_ID

LEFT JOIN IND_PEJABAT IPJ_1 ON DHAS_1.PEJABAT_ID = IPJ_1.PEJABAT_ID
LEFT JOIN UMM_HANTARAN_NOTIS HNTR_1 ON DHAS_1.HANTARAN_NOTIS_ID = HNTR_1.HANTARAN_NOTIS_ID
LEFT JOIN PKS_A_KERTAS_SIASATAN KS ON DHAS_1.A_KERTAS_SIASATAN_ID = KS.A_KERTAS_SIASATAN_ID




LEFT JOIN LATERAL (
	  SELECT o.nama
	  FROM umm_p_daftar_organisasi o
	  WHERE o.p_daftar_organisasi_id IN (
	    SELECT MIN(o2.p_daftar_organisasi_id)
	    FROM umm_p_daftar_organisasi o2
	    WHERE APP_A_1.id_transaksi = APP_1.id_pengenalan
	  )
	  LIMIT 1
	) AS org_nama ON DHAS_1.kod_tgsn IN ('PPF', 'PPJUB', 'PPPK', 'PPSYT')
	
	-- Join nama pelelong jika kod urusan 'PPLBL'
	LEFT JOIN LATERAL (
	  SELECT p.nama_pemohon
	  FROM llg_a_daftar_pelelong p
	  WHERE p.aplikasi_id = DHAS_1.aplikasi_id
	  ORDER BY p.a_daftar_pelelong_id ASC
	  LIMIT 1
	) AS pelelong_nama ON URSN_1.kod = 'PPLBL'
	
	-- Join nama pihak berkepentingan
	LEFT JOIN LATERAL (
	  SELECT r.nama
	  FROM umm_a_pihak_bkptg r
	  WHERE r.aplikasi_id = DHAS_1.aplikasi_id
	    AND UPPER(r.flag_pemohon) = 'Y'
	  ORDER BY r.a_pihak_bkptg_id ASC
	  LIMIT 1
	) AS bkptg_nama ON TRUE
  	
	WHERE UPPER(DHAS_1.FLAG_TGSN_SISTEM) = 'N'
	AND (DHAS_1.NAMA_PENGGUNA = var_nama_pengguna OR DHAS_1.NAMA_PENGGUNA IS NULL)
	AND (EXISTS (
        SELECT 1 FROM VAR_PERANAN_KOD_PENGGUNA PKP
        WHERE PKP.NAMA_PENGGUNA = DHAS_1.NAMA_PENGGUNA AND PKP.peranan_kod = 'PTG'
    	) OR DHAS_1.PEJABAT_ID IN (SELECT PEJABAT_ID FROM VAR_PEJABAT_TERKAIT) OR DHAS_1.PEJABAT_ID IS NULL
	)

	AND (
		URSN_1.KOD IN (SELECT KOD FROM VAR_URUSAN_KOD_LIST)
		OR URSN_2.KOD IN (SELECT KOD FROM VAR_URUSAN_KOD_LIST)
	)

	AND EXISTS ( 
		SELECT 1
		FROM VAR_PERANAN_KOD_PENGGUNA PKP
		WHERE DHAS_1.PERANAN LIKE '%-' || PKP.PERANAN_KOD || '-%'
	)
	AND (APP_TGSN_1.A_TGSN_ID is null or APP_TGSN_1.A_TGSN_ID is not null )
	--IF 
		AND (
		    var_modul_kod IS NULL 
		    OR DHAS_1.modul = var_modul_kod
		)
		
		AND (
		    var_urusan_mdl_kod IS NULL
		    OR (
		        var_modul_kod IS DISTINCT FROM 'DFT'
		        AND COALESCE(URSN_1.KOD, URSN_2.KOD) = var_urusan_mdl_kod
		    )
		)
	-- END 
	),

VAR_GROUPED_TUGAS AS (
    SELECT
        mq.*,
        ROW_NUMBER() OVER (PARTITION BY ua.no_fail, mq.kod_tgsn ORDER BY mq.tgsn_semasa_id) AS rn
    FROM MAIN_QUERY mq
    LEFT JOIN umm_aplikasi ua ON mq.aplikasi_id = ua.aplikasi_id
    WHERE mq.kod_tgsn IN ('PPBKRPDPJPM', 'PPBKRSDPJPM', 'PPBKRCDPJPM') 
),
VAR_MODUL_PENGGUNA AS (
  SELECT DISTINCT p.nama_pengguna, m.kod AS modul_kod
  FROM pcp_capaian_pengguna cp
  JOIN pcp_pengguna p ON cp.pengguna_id = p.pengguna_id
  JOIN pcp_peranan_modul pm ON cp.peranan_modul_id = pm.peranan_modul_id
  JOIN ind_modul m ON pm.modul_id = m.modul_id
  WHERE p.nama_pengguna IN (var_nama_pengguna) 
    AND m.kod IN ('PNT', 'UAM')
),

VAR_BELUM_TUKAR_GANTI AS (
 SELECT unnest(ARRAY['HMSC', 'HMSTP', 'PRBB', 'OPRBB', 'HDHD', 'HMPV', 'HMV','HMVB','SSHM','SSSC','SW','SA','CRHMB','CSHMB','BETUL','PACT','PKH','PMKMH','PFT','REM','REMITAN'])
),
FINAL_QUERY_V1 AS (
	SELECT * FROM MAIN_QUERY AS DEFAULT_MAIN_PNT
	WHERE EXISTS (
	    SELECT 1
	    FROM VAR_MODUL_PENGGUNA mp
	    WHERE mp.nama_pengguna = DEFAULT_MAIN_PNT.nama_pengguna
	      OR DEFAULT_MAIN_PNT.modul IN ('PNT', 'UAM')
	  )
	AND DEFAULT_MAIN_PNT.kod_tgsn NOT IN ('KD', 'STRKD')
		AND NOT (
		  DEFAULT_MAIN_PNT.modul = 'CON'
		  AND DEFAULT_MAIN_PNT.kod_tgsn IN ('CSK', 'JSK')
		)
	UNION ALL
	SELECT * FROM MAIN_QUERY AS DEFAULT_MAIN
	WHERE DEFAULT_MAIN.KOD_TGSN NOT IN ('KD', 'STRKD')
	AND NOT (
	    DEFAULT_MAIN.MODUL = 'CON' AND 
	    (DEFAULT_MAIN.KOD_TGSN = 'CSK' OR DEFAULT_MAIN.KOD_TGSN = 'JSK')
	)
	AND DEFAULT_MAIN.MODUL NOT IN ('PNT', 'UAM')
	AND NOT (
	    DEFAULT_MAIN.kod_tgsn IN ('KD', 'STRKD')
	    OR (DEFAULT_MAIN.NAMA_PENGGUNA IS NOT NULL AND DEFAULT_MAIN.NAMA_PENGGUNA <> var_nama_pengguna)
	)
	AND NOT (
	    DEFAULT_MAIN.KOD_TGSN = 'PTBUT'
	    AND DEFAULT_MAIN.URUSAN_KOD IN ('PMQFT', 'PMQTFT')
	)

),

FIANL_QUERY_MERGE as (
	select * FROM FINAL_QUERY_V1 as FN_Q1
	WHERE NOT EXISTS (
		SELECT 1
   		FROM VAR_FILTER_TUGASAN_KOD_SET 
		 WHERE
	      (
	        stgsn_kod = 'PTB'
	        AND FN_Q1.KOD_TGSN LIKE '%' || stgsn_kod || '%'
	      )
			OR (
		    stgsn_kod <> 'PTB'
			  AND FN_Q1.KOD_TGSN = stgsn_kod
			)
	)

 	UNION ALL
	SELECT * from (

		SELECT DISTINCT ON (FN_Q1_v2.KOD_TGSN) FN_Q1_v2.*
		FROM FINAL_QUERY_V1 as FN_Q1_v2
		WHERE EXISTS (
			 SELECT 1
      		FROM VAR_FILTER_TUGASAN_KOD_SET
			where (
					UPPER(FN_Q1_v2.STATUS_PROSES) <> 'GANTUNG'

					AND (
			          (stgsn_kod = 'PTB' AND FN_Q1_v2.KOD_TGSN LIKE '%' || stgsn_kod || '%')
			          OR (stgsn_kod = 'SJR' AND FN_Q1_v2.KOD_TGSN LIKE '%' || stgsn_kod || '%')
			          OR (stgsn_kod = 'CTK_JR' AND FN_Q1_v2.KOD_TGSN LIKE '%' || stgsn_kod || '%')
			          OR (stgsn_kod = 'PJR' AND FN_Q1_v2.KOD_TGSN LIKE '%' || stgsn_kod || '%')
			          OR (
			            stgsn_kod NOT IN ('PTB', 'SJR', 'CTK_JR', 'PJR')
			            AND FN_Q1_v2.KOD_TGSN = stgsn_kod
			          )
			        )
			) order by FN_Q1_v2.KOD_TGSN, FN_Q1_v2.tgsn_semasa_id desc
		) limit 1 
	)

),
VAR_USER_PERANAN AS (
  SELECT LOWER(mdl.kod) AS modul, LOWER(sak.kod) AS peranan
  FROM pcp_capaian_pengguna cp
  JOIN pcp_pengguna pg ON cp.pengguna_id = pg.pengguna_id
  JOIN pcp_peranan_modul pm ON cp.peranan_modul_id = pm.peranan_modul_id
  JOIN ind_modul mdl ON pm.modul_id = mdl.modul_id
  JOIN rjk_senarai_ahli_kumpulan sak ON pm.peranan_id = sak.senarai_ahli_kumpulan_id
  WHERE pg.nama_pengguna = var_nama_pengguna
),
FINAL_QUERY AS (
  SELECT * 
  FROM FIANL_QUERY_MERGE AS DEFAULT_MAIN
  WHERE 1=1

	AND 
    (
      var_status_tugasan IS NULL
      OR UPPER(var_status_tugasan) NOT IN ('BARU', 'SEMASA')
      OR (
        UPPER(var_status_tugasan) = 'BARU' AND UPPER(DEFAULT_MAIN.STATUS_TUGASAN) = 'BARU'
      )
      OR (
        UPPER(var_status_tugasan) = 'SEMASA' AND UPPER(DEFAULT_MAIN.STATUS_TUGASAN) = 'DALAM TINDAKAN'
      )
    )
 AND (
    -- Ambil jika bukan PTB dan nama_pengguna tidak kosong
    (
      DEFAULT_MAIN.kod_tgsn NOT ILIKE '%PTB%'
      AND COALESCE(TRIM(DEFAULT_MAIN.nama_pengguna), '') <> ''
    )
    -- Atau: jika PTB / nama kosong, validasi modul dan peranan terhadap VAR_USER_PERANAN
    OR EXISTS (
      SELECT 1
      FROM VAR_USER_PERANAN u
      WHERE LOWER(u.modul) = LOWER(DEFAULT_MAIN.modul)
        AND EXISTS (
          SELECT 1
          FROM unnest(string_to_array(LOWER(DEFAULT_MAIN.peranan), '-')) AS p(peranan)
          WHERE p.peranan = u.peranan
        )
        AND (
          DEFAULT_MAIN.kod_tgsn ILIKE '%PTB%'
          OR COALESCE(TRIM(DEFAULT_MAIN.nama_pengguna), '') = ''
        )
    )
  
    )
    AND NOT (
      DEFAULT_MAIN.id_rujukan_smartbox IS NOT NULL
      AND DEFAULT_MAIN.id_rujukan_smartbox <> ''
      AND DEFAULT_MAIN.kod_tgsn IN ('ISHSB', 'KDSB')
    )
),

URUSAN_MODUL_PARENT_CTE AS (
  SELECT 
    A.APLIKASI_ID as APP_ID_CTE,
    M.KOD AS URUSAN_MODUL_PARENT
  FROM UMM_APLIKASI A
  LEFT JOIN IND_URSN U ON A.URSN_ID = U.URSN_ID
  LEFT JOIN IND_MODUL M ON U.MODUL_ID = M.MODUL_ID
),

FINAL_RESULT AS (
	SELECT * ,
	CASE 
	  WHEN EXISTS (
	    SELECT 1
	    FROM UMM_PERTANYAAN p
	    JOIN RJK_SENARAI_AHLI_KUMPULAN k ON p.STATUS_ID = k.SENARAI_AHLI_KUMPULAN_ID
	    JOIN UMM_APLIKASI a ON p.APLIKASI_ID = a.APLIKASI_ID
	    JOIN IND_URSN u ON a.URSN_ID = u.URSN_ID
	    WHERE p.A_TGSN_ID = FQ.APP_A_TGSN_ID
	      AND k.KOD != 'SELESAI'
	      AND u.TEMPOH_KUIRI ~ '^[0-9]+$'
	      AND DATE_PART('day', CURRENT_DATE - p.CREATED_DATE) > u.TEMPOH_KUIRI::INT
	  )
	  THEN ' (Pertanyaan) - Telah Melebihi Tempoh Kuiri'
	
	  WHEN EXISTS (
	    SELECT 1
	    FROM UMM_PERTANYAAN p
	    JOIN RJK_SENARAI_AHLI_KUMPULAN k ON p.STATUS_ID = k.SENARAI_AHLI_KUMPULAN_ID
	    WHERE p.A_TGSN_ID = FQ.APP_A_TGSN_ID
	      AND k.KOD != 'SELESAI'
	  )
	  THEN ' (Pertanyaan)'
	
	  ELSE NULL
	END AS pertanyaan_keterangan,


	--	color and flag
	CASE 
	    WHEN (
	        CASE
	            WHEN FQ.MINIT_KPI IS NOT NULL 
	                 AND FQ.TRKH_PNRMAN IS NOT NULL 
	                 AND FQ.DHAS_1_TRKH_KPI IS NULL
	            THEN FQ.TRKH_PNRMAN + (FQ.MINIT_KPI || ' minutes')::INTERVAL
	            ELSE FQ.DHAS_1_TRKH_KPI
	        END
	    ) IS NOT NULL 
	    AND (
	        CASE
	            WHEN FQ.MINIT_KPI IS NOT NULL 
	                 AND FQ.TRKH_PNRMAN IS NOT NULL 
	                 AND FQ.DHAS_1_TRKH_KPI IS NULL
	            THEN FQ.TRKH_PNRMAN + (FQ.MINIT_KPI || ' minutes')::INTERVAL
	            ELSE FQ.DHAS_1_TRKH_KPI
	        END
	    ) < CURRENT_DATE
	THEN 'TUNGGAK'
	ELSE NULL
	END AS STATUS,
	CASE 
	    WHEN (
	        CASE
	            WHEN FQ.MINIT_KPI IS NOT NULL 
	                 AND FQ.TRKH_PNRMAN IS NOT NULL 
	                 AND FQ.TRKH_KPI IS NULL
	            THEN FQ.TRKH_PNRMAN + (FQ.MINIT_KPI || ' minutes')::INTERVAL
	            ELSE FQ.DHAS_1_TRKH_KPI
	        END
	    ) IS NOT NULL 
	    AND (
	        CASE
	            WHEN FQ.MINIT_KPI IS NOT NULL 
	                 AND FQ.TRKH_PNRMAN IS NOT NULL 
	                 AND FQ.TRKH_KPI IS NULL
	            THEN FQ.TRKH_PNRMAN + (FQ.MINIT_KPI || ' minutes')::INTERVAL
	            ELSE FQ.DHAS_1_TRKH_KPI
	        END
	    ) < CURRENT_DATE
	THEN 'red' -- warna merah sebagai contoh
	ELSE NULL
	END AS COLOR,


	CASE
	    WHEN NOT FQ.SHOW_KPI THEN 'Hijau'
	    WHEN FQ.TARIKH_DAN_MASA_LUPUT_STRING IS NULL OR FQ.TARIKH_DAN_MASA_LUPUT_STRING = '-' THEN 'Hijau'
	    WHEN FQ.TRKH_TETAP IS NULL THEN
	        CASE
	            WHEN TO_DATE(FQ.TARIKH_DAN_MASA_LUPUT_STRING, 'DD/MM/YYYY') >= CURRENT_DATE THEN 'Hijau'
	            ELSE 'Merah'
	        END
	    WHEN TO_DATE(FQ.TARIKH_DAN_MASA_LUPUT_STRING, 'DD/MM/YYYY') <= FQ.TRKH_TETAP::DATE THEN 'Hijau'
	    ELSE 'Merah'
	END AS FLAG_STATUS,

	--end color and flag

CASE
  WHEN FQ.KOD_TGSN = 'ISH' THEN TRUE
  WHEN FQ.MODUL = 'KKS' THEN TRUE
  WHEN FQ.MODUL = 'PNT' AND URUSAN_MODUL_PARENT = 'KKS' THEN TRUE
  WHEN EXISTS (
    SELECT 1
    FROM UNNEST(STRING_TO_ARRAY(FQ.URUSAN_KOD_DASHBOARD, '<BR />')) AS URSN
    WHERE URSN IN (SELECT * FROM VAR_BELUM_TUKAR_GANTI)
  ) THEN TRUE
  WHEN EXISTS (
    SELECT 1
    FROM UNNEST(STRING_TO_ARRAY(FQ.URUSAN_KOD_DASHBOARD, '<BR />')) AS URSN
    WHERE URSN IS NOT NULL
      AND (
        URSN NOT IN (SELECT * FROM VAR_BELUM_TUKAR_GANTI)
        OR URSN IN (SELECT * FROM VAR_ALSAN_TUKARGANTI_KOD_SET_BATAL)
      )
or (
    (
      SELECT COUNT(*) FROM DFT_A_MOHON_HKMLK HM
      JOIN IND_MKLMT_HKMLK MH ON MH.mklmt_hkmlk_id = HM.ID_HKMLK
      JOIN rjk_senarai_ahli_kumpulan o ON o.senarai_ahli_kumpulan_id = MH.status_hkmlk_id
      WHERE HM.APLIKASI_ID = FQ.APLIKASI_ID AND o.kod = 'STAHMBT'
    ) = (
      SELECT COUNT(*) FROM DFT_A_MOHON_HKMLK HM
      WHERE HM.APLIKASI_ID = FQ.APLIKASI_ID
    )
    or NOT EXISTS (
      SELECT 1
      FROM DFT_A_MOHON_HKMLK HM
      JOIN IND_MKLMT_HKMLK MH ON MH.mklmt_hkmlk_id = HM.ID_HKMLK
      JOIN RJK_SENARAI_AHLI_KUMPULAN o ON o.senarai_ahli_kumpulan_id = MH.status_hkmlk_id
      WHERE HM.APLIKASI_ID = FQ.APLIKASI_ID
      AND o.kod = 'STAHDFT'
      AND EXISTS (
        SELECT 1 FROM IND_VERSI_DHD TG WHERE TG.hkmlk_id = HM.ID_HKMLK
      )
    )
  )
  )
  
  THEN TRUE
  ELSE FALSE
END AS IS_HAKMILIK_BELUM_TUKARGANTI,



CASE 
  WHEN FQ.TARIKH_DAN_MASA_LUPUT IS NULL THEN '-' 

  WHEN FQ.TARIKH_DAN_MASA_LUPUT <= NOW() THEN '0 Hari'

  WHEN DATE_PART('month', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 THEN
    TRIM(BOTH FROM CONCAT_WS(' ',
      CASE 
        WHEN DATE_PART('month', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('month', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Bulan' 
      END,
      CASE 
        WHEN DATE_PART('day', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('day', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Hari' 
      END,
      CASE 
        WHEN DATE_PART('hour', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('hour', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Jam' 
      END,
      CASE 
        WHEN DATE_PART('minute', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('minute', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Minit' 
      END
    ))

  ELSE
    TRIM(BOTH FROM CONCAT_WS(' ',
      CASE 
        WHEN DATE_PART('day', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('day', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Hari' 
      END,
      CASE 
        WHEN DATE_PART('hour', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('hour', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Jam' 
      END,
      CASE 
        WHEN DATE_PART('minute', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('minute', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Minit' 
      END
    ))
END AS BAKI_MASA





	
FROM FINAL_QUERY AS FQ 
LEFT JOIN URUSAN_MODUL_PARENT_CTE UMP ON UMP.APP_ID_CTE = FQ.APP_ID
	WHERE 1=1
	AND NOT (
		FQ.MODUL = 'PFIKM'   
		OR FQ.ID_TGSN IN (SELECT ID_TGSN_PELUPUSAN_PENGGUNA_FILTER FROM VAR_PELUPUSAN_TUGASAN_FILTERED)	
  	)
AND NOT (FQ.modul = 'UAM' AND FQ.URUSAN_KOD = 'BIO')


),



 RANGKAIAN_MERGERED AS (
    SELECT 
    MAX(fd.TGSN_SEMASA_ID)::BIGINT AS ID,
    MAX(fd.TRKH_PNRMAN) AS TRKH_PEN,
    MAX(fd.TARIKH_PENERIMAAN_STRING) AS TARIKH_PENERIMAAN_STRING,
    MAX(fd.TARIKH_DAN_MASA_LUPUT_STRING) AS TARIKH_DAN_MASA_LUPUT_STRING,
    STRING_AGG(fd.ID_HKMLK, '<br />') AS no_hakmilik,
    ra.RANGKAIAN_ID::TEXT AS rangkaian_id_merged,
    fd.kod_tgsn::TEXT,
    STRING_AGG(fd.ID_PERMOHONAN_DASHBOARD ::TEXT, '<br />') AS id_permohonan,
    STRING_AGG(fd.URUSAN_KOD_DASHBOARD ::TEXT, '<br />') AS urusan,
    MAX(fd.NO_FAIL_PEMOHON) AS NO_FAIL_PEMOHON,
    STRING_AGG(fd.NO_RESIT_DASHBOARD :: TEXT, '<br />') AS no_resit,
	MAX(fd.TGSN_PERIHAL) as tugas,
    MAX(fd.NAMA_PEMOHON) AS NAMA_PEMOHON,
    MAX(fd.NAMA_PEJABAT_PENDEK) AS PEJABAT,
    MAX(fd.ID_PENGHANTARAN) AS ID_PENYAMPAIAN,
	MAX(fd.APP_A_TGSN_ID ) as id_APP_A_TGSN,
	MAX(fd.APLIKASI_ID),
	MAX(fd.pertanyaan_keterangan) AS pertanyaan_keterangan,
	MAX(fd.TARIKH_SIASATAN_STRING) as TARIKH_SIASATAN_STRING,
	MAX(fd.STATUS) as ROW_STATUS,
	MAX(fd.COLOR) as ROW_COLOR,
	MAX(fd.FLAG_STATUS) as FLAG_STATUS,
	(MAX(CASE WHEN fd.IS_HAKMILIK_BELUM_TUKARGANTI THEN 1 ELSE 0 END) = 1),
	MAX(fd.BAKI_MASA) as BAKI_MASA,
	MAX(fd.NO_HAKMILIK_BARU) as NO_HAKMILIK_BARU

    FROM FINAL_RESULT fd
    JOIN UMM_APLIKASI ra ON fd.APLIKASI_ID = ra.APLIKASI_ID
    WHERE ra.RANGKAIAN_ID IS NOT NULL AND fd.kod_tgsn <> 'IMH'
    GROUP BY ra.RANGKAIAN_ID, fd.kod_tgsn
  ),

  REMAINING_ROW AS (
    SELECT 
    fd.TGSN_SEMASA_ID::BIGINT AS ID,
    fd.TRKH_PNRMAN AS TRKH_PEN,
    fd.TARIKH_PENERIMAAN_STRING,
    fd.TARIKH_DAN_MASA_LUPUT_STRING,
    fd.ID_HKMLK AS no_hakmilik,
      NULL::TEXT AS rangkaian_id_merged,
    fd.kod_tgsn::TEXT,
    fd.ID_PERMOHONAN_DASHBOARD AS id_permohonan,
    fd.URUSAN_KOD_DASHBOARD AS urusan,
    fd.NO_FAIL_PEMOHON AS NO_FAIL_PEMOHON,
    fd.NO_RESIT_DASHBOARD AS no_resit,
	fd.TGSN_PERIHAL as tugas,
    fd.NAMA_PEMOHON AS NAMA_PEMOHON,
    fd.NAMA_PEJABAT_PENDEK AS PEJABAT,
    fd.ID_PENGHANTARAN AS ID_PENYAMPAIAN,
	fd.APP_A_TGSN_ID as id_APP_A_TGSN,
	fd.APLIKASI_ID,
	fd.pertanyaan_keterangan,
	fd.TARIKH_SIASATAN_STRING as TARIKH_SIASATAN_STRING,
	fd.STATUS as ROW_STATUS,
	fd.COLOR as ROW_COLOR,
	fd.FLAG_STATUS as FLAG_STATUS, 
	fd.IS_HAKMILIK_BELUM_TUKARGANTI,
	fd.BAKI_MASA as BAKI_MASA, 
	fd.NO_HAKMILIK_BARU as NO_HAKMILIK_BARU

    FROM FINAL_RESULT fd
    LEFT JOIN UMM_APLIKASI ra ON fd.APLIKASI_ID = ra.APLIKASI_ID
    WHERE ra.RANGKAIAN_ID IS NULL OR fd.kod_tgsn = 'IMH'
  ),

--   FINAL_V2 AS (
--     SELECT * FROM RANGKAIAN_MERGERED
--     UNION ALL
--     SELECT * FROM REMAINING_ROW
--   ),
  FINAL_V2 AS (
  SELECT DISTINCT ON (merged.id) merged.*
  FROM (
    SELECT * FROM RANGKAIAN_MERGERED
    UNION ALL
    SELECT * FROM REMAINING_ROW
  ) merged
  ORDER BY merged.id, merged.trkh_pen DESC -- pilih row terbaru per id
),
   params AS (
    SELECT trim(c.col) AS fcol, trim(v.val) AS fval
    FROM unnest(string_to_array(var_filter_colum, ',')) WITH ORDINALITY AS c(col, idx)
    JOIN unnest(string_to_array(var_filter_val, '||')) WITH ORDINALITY AS v(val, idx2)
      ON c.idx = v.idx2
)


  SELECT count(*)
  FROM FINAL_V2 V2

WHERE
    -- Jika tidak ada filter sama sekali, kembalikan semua
    NOT EXISTS (SELECT 1 FROM params)
    
    -- Jika ada filter, cocokkan semua kolom
    OR (
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TARIKH_PENERIMAAN_STRING')
         OR v2.TARIKH_PENERIMAAN_STRING ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TARIKH_PENERIMAAN_STRING')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TARIKH_DAN_MASA_LUPUT_STRING')
         OR v2.TARIKH_DAN_MASA_LUPUT_STRING ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TARIKH_DAN_MASA_LUPUT_STRING')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TARIKH_SIASATAN_STRING')
         OR v2.TARIKH_SIASATAN_STRING ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TARIKH_SIASATAN_STRING')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'NO_HAKMILIK')
         OR v2.NO_HAKMILIK ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'NO_HAKMILIK')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'ID_PERMOHONAN')
         OR v2.ID_PERMOHONAN ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'ID_PERMOHONAN')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'NO_FAIL_PEMOHON')
         OR v2.NO_FAIL_PEMOHON ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'NO_FAIL_PEMOHON')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'NO_RESIT')
         OR v2.NO_RESIT ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'NO_RESIT')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'URUSAN')
         OR v2.URUSAN ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'URUSAN')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'NAMA_PEMOHON')
         OR v2.NAMA_PEMOHON ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'NAMA_PEMOHON')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'PERTANYAAN_KETERANGAN')
         OR v2.PERTANYAAN_KETERANGAN ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'PERTANYAAN_KETERANGAN')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TUGAS')
         OR v2.TUGAS ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TUGAS')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'PEJABAT')
         OR v2.PEJABAT ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'PEJABAT')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'ID_PENYAMPAIAN')
         OR v2.ID_PENYAMPAIAN ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'ID_PENYAMPAIAN')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TUGASAN')
         OR v2.TUGAS ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TUGASAN')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'FLAG_STATUS')
         OR v2.FLAG_STATUS ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'FLAG_STATUS')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'BAKI_MASA')
         OR v2.BAKI_MASA ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'BAKI_MASA')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TUGAS_AND_PERTANYAAN')
         OR (v2.TUGAS ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TUGAS_AND_PERTANYAAN'))
             OR v2.PERTANYAAN_KETERANGAN ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TUGAS_AND_PERTANYAAN'))))
    )

;


END;
$function$
;

-- DROP FUNCTION et_main_uat.get_dashboard_by_pengguna(numeric, numeric, _text, text, numeric, text, text, text, text, bool, text, text, text, text);

CREATE OR REPLACE FUNCTION et_main_uat.get_dashboard_by_pengguna(var_limit numeric DEFAULT NULL::numeric, var_offset numeric DEFAULT NULL::numeric, var_urusan_kod_list text[], var_nama_pengguna text DEFAULT NULL::text, var_pejabat_id numeric DEFAULT NULL::numeric, var_modul_kod text DEFAULT NULL::text, var_urusan_mdl_kod text DEFAULT NULL::text, var_status_tugasan text DEFAULT NULL::text, var_kod_negri text DEFAULT NULL::text, var_export boolean DEFAULT false, var_sort_colum text DEFAULT NULL::text, var_sort_type text DEFAULT NULL::text, var_filter_colum text DEFAULT NULL::text, var_filter_val text DEFAULT NULL::text)
 RETURNS TABLE(id bigint, trkh_pen timestamp without time zone, tarikh_penerimaan_string text, tarikh_dan_masa_luput_string text, no_hakmilik text, rangkaian_id_merged text, kod_tgsn text, id_permohonan text, urusan text, no_fail_pemohon text, no_resit text, tugas text, nama_pemohon text, pejabat text, id_penyampaian text, id_app_a_tgsn numeric, id_app_aplikasi numeric, pertanyaan_keterangan text, tarikh_siasatan_string text, row_status text, row_color text, flag_status text, is_hakmilik_belum_tukarganti boolean, baki_masa text, no_hakmilik_baru text, modul text)
 LANGUAGE plpgsql
AS $function$
BEGIN
  RETURN QUERY
WITH VAR_URUSAN_KOD_LIST AS (
    SELECT UNNEST(var_urusan_kod_list) AS KOD
  ),
VAR_PERANAN_KOD_PENGGUNA AS (
  SELECT DISTINCT PP.NAMA_PENGGUNA, RM.KOD AS PERANAN_KOD
  FROM PCP_CAPAIAN_PENGGUNA CP
  JOIN PCP_PENGGUNA PP ON CP.PENGGUNA_ID = PP.PENGGUNA_ID
  JOIN PCP_PERANAN_MODUL PM ON CP.PERANAN_MODUL_ID = PM.PERANAN_MODUL_ID
  JOIN RJK_SENARAI_AHLI_KUMPULAN RM ON PM.PERANAN_ID = RM.SENARAI_AHLI_KUMPULAN_ID
  WHERE PP.NAMA_PENGGUNA IN (var_nama_pengguna)
),
VAR_DAERAH_PENGGUNA AS (
    SELECT DISTINCT DAERAH_ID
    FROM IND_PEJABAT AS IP
    WHERE PEJABAT_ID IN (var_pejabat_id)
),
VAR_PEJABAT_TERKAIT AS (
    SELECT DISTINCT PEJABAT_ID
    FROM IND_PEJABAT AS IP
    WHERE DAERAH_ID IN (SELECT DAERAH_ID FROM VAR_DAERAH_PENGGUNA)
),
VAR_FILTER_TUGASAN_KOD_SET AS (
	SELECT UNNEST(ARRAY['PPBKRPJPM', 'PPBKRKPJPM', 'PTB', 'SJR',
    'PJR', 'CTK_JR', 'PMMP6PTB2', 'PPBBPTB2',
    'PPHSYBPTB2', 'PKJR', 'PKJRPP']) as stgsn_kod
),

VAR_PELUPUSAN_TUGASAN_FILTERED AS (
  SELECT ID_TGSN AS ID_TGSN_PELUPUSAN_PENGGUNA_FILTER
  FROM (
    SELECT A.ID_TGSN,
        ROW_NUMBER() OVER (
            PARTITION BY COALESCE(C.kod, E.kod), A.ID_TGSN
            ORDER BY A.ID_TGSN
    ) AS RN
    FROM UMM_TGSN_SEMASA A
    LEFT JOIN UMM_APLIKASI B ON B.APLIKASI_ID = A.APLIKASI_ID
    LEFT JOIN IND_URSN C ON C.URSN_ID = B.URSN_ID
    LEFT JOIN UMM_P_APLIKASI D ON D.APLIKASI_ID = A.APLIKASI_ID
    LEFT JOIN IND_URSN E ON E.URSN_ID = D.URSN_ID
    WHERE A.MODUL = 'PLP'
      AND A.KOD_TGSN = 'FPIKM'
      AND UPPER(A.FLAG_TGSN_SISTEM) = 'N'
  ) A
  WHERE RN = 1
),
VAR_PEJABAT_PERANAN_MAP AS (
  SELECT * FROM (VALUES
    ('TRG', ARRAY['PTG', 'TPTG', 'KPP']),
    ('PRK', ARRAY['PTG', 'KPP']),
    ('SEL', ARRAY['PTG', 'TPTG'])
  ) AS T (KOD_PEJABAT, PERANANS)
),
VAR_PLP_TUGASAN_KOD_SET AS (
    SELECT unnest(ARRAY['PDKM', 'SDKM', 'SDKM2', 'SDKM3', 'PPKM', 'CKM', 'CKMPPLN'])
),
VAR_ALSAN_TUKARGANTI_KOD_SET AS (
    SELECT unnest(ARRAY['KMPP', 'HMSC', 'HMSTP', 'PRBB', 'OPRBB', 'HDHD', 'HMPV', 'HMV', 'HMVB',
            'SSHM', 'SSSC', 'SW', 'SA', 'CRHMB', 'CSHMB', 'BETUL', 'PACT', 'PKH', 'PMKMH', 'PFT', 'REM', 'REMITAN'])
),
VAR_GROUP_BY_NO_FAIL_TUGASAN_KOD_SET AS (
    SELECT unnest(ARRAY['PPBKRPDPJPM', 'PPBKRSDPJPM', 'PPBKRCDPJPM'])
),

VAR_ALSAN_TUKARGANTI_KOD_SET_BATAL AS (
    SELECT unnest(ARRAY['HDHK', 'HPLN','PMKMH','HSSTB','HKSSS'])
),
VAR_NO_HAK_MILIK_BARU AS (
    SELECT
        mohon.APLIKASI_ID,
        STRING_AGG(mohon.id_hkmlk, '<br>') AS NO_HAKMILIK_BARU
    FROM dft_A_MOHON_HKMLK mohon
    JOIN UMM_APLIKASI appl ON appl.APLIKASI_ID = mohon.APLIKASI_ID
    JOIN IND_URSN urusan ON appl.URSN_ID = urusan.URSN_ID
    JOIN rjk_jns_ursn jenis ON jenis.jns_ursn_id = urusan.jns_ursn_id
    WHERE mohon.id_hkmlk IS NOT NULL
      AND jenis.KOD = 'MH'
    GROUP BY mohon.APLIKASI_ID
),
MAIN_QUERY AS (
	SELECT
  	DHAS_1.TGSN_SEMASA_ID,
	DHAS_1.TRKH_PNRMAN,
	MDL_1.KOD as MODUL,
	DHAS_1.ID_HKMLK,
	DHAS_1.NO_RESIT,
	DHAS_1.LOCKED_BY,
	DHAS_1.LOCKED_DATE,
	DHAS_1.PERANAN,
	DHAS_1.KOD_TGSN,
	DHAS_1.ID_TGSN,
	DHAS_1.TGSN_PERIHAL,
	DHAS_1.NAMA_PENGGUNA,
	APP_TGSN_1.TRKH_TETAP,
	APP_1.TRKH_PIAGAM,
	APP_1.APLIKASI_ID,
	APP_1.APLIKASI_ID as APP_ID,
	APP_1.RANGKAIAN_ID,
	APP_1.ID_PENGENALAN,
	APP_1.FLAG_INTEGRASI,
	APP_1.STATUS_KEPUTUSAN,
	APP_1.FAIL_INDUK,
	COALESCE(APP_1.STATUS_PROSES, SNR_1.NAMA) AS STATUS_PROSES,
    COALESCE(URSN_1.KOD, URSN_2.KOD) AS URUSAN_KOD,
    COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI) AS NO_RUJUKAN,
	IPJ_1.NAMA_PENDEK,
	IPJ_1.KOD AS PEJABAT_KOD,
	HNTR_1.ID_PENGHANTARAN,
	DHAS_1.a_tgsn_id as APP_A_TGSN_ID,
	IPJ_1.NAMA_PENDEK as NAMA_PEJABAT_PENDEK,
	TO_CHAR(MLS.TRKH_SIASATAN, 'DD/MM/YYYY') AS TARIKH_SIASATAN_STRING,
	APP_1.ID_RUJUKAN_SMARTBOX,
	DHAS_1.TRKH_KPI AS DHAS_1_TRKH_KPI,
	ITG_1.MINIT_KPI,
	CASE
      WHEN URSN_1.KOD = 'PSBS' AND DHAS_1.TGSN_PERIHAL = 'Penyediaan Fail Induk Kertas Mesyuarat' THEN FALSE
      ELSE TRUE
    END AS SHOW_ID_HAKMILIK,
	(
      SELECT STRING_AGG(mohon.id_hkmlk, '<br>')
      FROM dft_A_MOHON_HKMLK mohon
      JOIN UMM_APLIKASI appl ON appl.APLIKASI_ID = mohon.APLIKASI_ID
      JOIN IND_URSN urusan ON appl.URSN_ID = urusan.URSN_ID
      JOIN rjk_jns_ursn jenis ON jenis.jns_ursn_id = urusan.jns_ursn_id
      WHERE mohon.APLIKASI_ID = DHAS_1.APLIKASI_ID
        AND mohon.id_hkmlk IS NOT NULL
        AND jenis.KOD = CAST('MH' AS VARCHAR)
    ) AS NO_HAKMILIK_BARU,

	CASE
		WHEN DHAS_1.TRKH_KPI IS NULL
		     AND ITG_1.MINIT_KPI IS NOT NULL
		     AND DHAS_1.TRKH_PNRMAN IS NOT NULL
		THEN DHAS_1.TRKH_PNRMAN + (ITG_1.MINIT_KPI || ' minutes')::INTERVAL
		ELSE DHAS_1.TRKH_KPI
	END AS TRKH_KPI,
	CASE
		WHEN APP_TGSN_1.STATUS_TUGASAN IS NULL OR DHAS_1.TGSN_PERIHAL = 'Pengagihan Tugasan Baru'
		THEN 'Baru'
		ELSE APP_TGSN_1.STATUS_TUGASAN
	END AS STATUS_TUGASAN,

	CASE
		WHEN ITG_1.MINIT_KPI IS NOT NULL THEN TRUE
		ELSE FALSE
	END AS SHOW_KPI,
	CASE
    WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL
         AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
              OR DHAS_1.KOD_TGSN LIKE '%PTB%')
    THEN '-'
    ELSE TO_CHAR(DHAS_1.TRKH_PNRMAN, 'DD/MM/YYYY')
	END AS TARIKH_PENERIMAAN_STRING,

	CASE

		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL
			AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
				OR DHAS_1.KOD_TGSN LIKE '%PTB%')
		THEN '-'

		ELSE TO_CHAR(
			CASE
			WHEN ITG_1.MINIT_KPI IS NOT NULL
				AND DHAS_1.TRKH_PNRMAN IS NOT NULL
				AND DHAS_1.TRKH_KPI IS NULL
			THEN DHAS_1.TRKH_PNRMAN + (ITG_1.MINIT_KPI || ' minutes')::INTERVAL
			ELSE DHAS_1.TRKH_KPI
			END,
			'DD/MM/YYYY'
		)
	END AS TARIKH_DAN_MASA_LUPUT_STRING,
	CASE
  		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL
       AND (
         DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
         OR DHAS_1.KOD_TGSN LIKE '%PTB%'
       )
	THEN NULL
	ELSE
		CASE
		WHEN ITG_1.MINIT_KPI IS NOT NULL
			AND DHAS_1.TRKH_PNRMAN IS NOT NULL
			AND DHAS_1.TRKH_KPI IS NULL
		THEN DHAS_1.TRKH_PNRMAN + (ITG_1.MINIT_KPI || ' minutes')::INTERVAL
		ELSE DHAS_1.TRKH_KPI
		END
	END AS TARIKH_DAN_MASA_LUPUT,

	CASE
		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL
			AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
				OR DHAS_1.KOD_TGSN LIKE '%PTB%')
		THEN '-'
		ELSE TO_CHAR(APP_1.TRKH_PIAGAM, 'DD/MM/YYYY')
	END AS TARIKH_PIAGAM_STRING,
	CASE
		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL
			AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
				OR DHAS_1.KOD_TGSN LIKE '%PTB%')
		THEN '-'
		ELSE TO_CHAR(APP_TGSN_1.TRKH_TETAP, 'DD/MM/YYYY')
	END AS TARIKH_MULA_STRING,
	CASE
		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL
			AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
				OR DHAS_1.KOD_TGSN LIKE '%PTB%')
		THEN TRUE
		ELSE FALSE
	END AS IS_FILTER_TUGASAN,
	CASE
		WHEN ITG_1.MINIT_KPI IS NOT NULL
			AND DHAS_1.TRKH_PNRMAN IS NOT NULL
			AND DHAS_1.TRKH_KPI IS NULL
		THEN DHAS_1.TRKH_PNRMAN + (ITG_1.MINIT_KPI || ' minutes')::INTERVAL
		ELSE DHAS_1.TRKH_KPI
	END AS TARIKH_KPI,


	CASE
	  WHEN NOT (
	    TRIM(DHAS_1.KOD_TGSN) IS NOT NULL
	    AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
	         OR DHAS_1.KOD_TGSN LIKE '%PTB%')
	  )
	  THEN
	    CASE
	      -- Special handling for PRBB urusan: get idHkmlk from UMM_A_PERMOHONAN_TNH.maklumat_tambahan
	      WHEN COALESCE(URSN_1.KOD, URSN_2.KOD) = 'PRBB'
	      THEN (
	        SELECT apt.MKLMT_TMBHN::jsonb ->> 'idHkmlk'
	        FROM UMM_A_PERMOHONAN_TNH apt
	        WHERE apt.APLIKASI_ID = APP_1.APLIKASI_ID
	          AND apt.MKLMT_TMBHN IS NOT NULL
	          AND apt.MKLMT_TMBHN::jsonb ->> 'idHkmlk' IS NOT NULL
	        LIMIT 1
	      )

	      -- Special handling for HLPK urusan: get master id_hakmilik from IND_HKMLK via UMM_A_HKMLK
	      WHEN COALESCE(URSN_1.KOD, URSN_2.KOD) = 'HLPK'
	      THEN (
	        SELECT STRING_AGG(DISTINCT h.ID_HKMLK, ', ' ORDER BY h.ID_HKMLK)
	        FROM IND_HKMLK h
	        WHERE h.strata_induk_id IS NULL
	          AND h.ID_HKMLK IN (
	            SELECT ah.ID_HKMLK
	            FROM UMM_A_HKMLK ah
	            WHERE ah.APLIKASI_ID = APP_1.APLIKASI_ID
	          )
	      )

	      WHEN COALESCE(NULLIF(TRIM(DHAS_1.ID_HKMLK), ''), '-') = '-' THEN '-'
	      ELSE (
	        SELECT
	          CASE
	            WHEN COUNT(*) > 10
	            THEN (
	              SELECT string_agg(val, ', ') || '...'
	              FROM (
	                SELECT DISTINCT val
	                FROM unnest(string_to_array(DHAS_1.ID_HKMLK, ',')) AS val
	                ORDER BY val
	                LIMIT 10
	              ) sub
	            )
	            ELSE (
	              SELECT string_agg(DISTINCT val, ', ' ORDER BY val)
	              FROM unnest(string_to_array(DHAS_1.ID_HKMLK, ',')) AS val
	            )
	          END
	      )
	    END
	  ELSE COALESCE(NULLIF(TRIM(DHAS_1.ID_HKMLK), ''), '-')
	END AS NO_HAKMILIK_DASHBOARD,
	CASE
	  WHEN NOT (
	    TRIM(DHAS_1.KOD_TGSN) IS NOT NULL
	    AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
	         OR DHAS_1.KOD_TGSN LIKE '%PTB%')
	  )
	  THEN COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
	  ELSE NULL
	END AS APLIKASI_NO_PERMOHONAN,


	CASE
	  WHEN NOT (
	    TRIM(DHAS_1.KOD_TGSN) IS NOT NULL
	    AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
	         OR DHAS_1.KOD_TGSN LIKE '%PTB%')
	  )
		  THEN
		    CASE
		      WHEN COALESCE(NULLIF(TRIM(DHAS_1.NO_RESIT), ''), '-') = '-' THEN '-'
		      ELSE (
		        SELECT
		          CASE
		            WHEN COUNT(*) > 10
		            THEN (
		              SELECT string_agg(val, ', ') || '...'
		              FROM (
		                SELECT DISTINCT val
		                FROM unnest(string_to_array(DHAS_1.NO_RESIT, ',')) AS val
		                ORDER BY val
		                LIMIT 10
		              ) sub
		            )
		            ELSE (
		              SELECT string_agg(DISTINCT val, ', ' ORDER BY val)
		              FROM unnest(string_to_array(DHAS_1.NO_RESIT, ',')) AS val
		            )
		          END
		      )
		    END
		  ELSE COALESCE(NULLIF(TRIM(DHAS_1.NO_RESIT), ''), '-')
		END AS NO_RESIT_DASHBOARD,


		CASE
		  WHEN NOT (
		    TRIM(DHAS_1.KOD_TGSN) IS NOT NULL
		    AND (
		      DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
		      OR DHAS_1.KOD_TGSN LIKE '%PTB%'
		    )
		  )
		  THEN
		    CASE
		      WHEN HNTR_1.ID_PENGHANTARAN IS NOT NULL AND HNTR_1.ID_PENGHANTARAN LIKE 'PNL/%'
		        THEN 'UPNL'
		      ELSE COALESCE(URSN_1.KOD, URSN_2.KOD)
		    END
		  ELSE
		    COALESCE(URSN_1.KOD, URSN_2.KOD)
		END AS URUSAN_KOD_DASHBOARD,

		CASE
		  WHEN UPPER(APP_1.FLAG_INTEGRASI) ='Y' THEN
		    CASE
		      WHEN COALESCE(COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI), '') LIKE '%MF%'
		           AND COALESCE(COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI), '') LIKE '%(%' THEN
		        SPLIT_PART(COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI), '(', 1)

		      WHEN COALESCE(APP_1.URSN_ID, URSN_2.URSN_ID) IS NOT NULL
		           AND COALESCE(URSN_1.KOD, URSN_2.KOD) = 'KVSP' THEN
		        (
		          SELECT hubungan2.ID_PENGENALAN || ' / ' || COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
		          FROM UMM_APLIKASI hubungan1
		          JOIN UMM_APLIKASI hubungan2 ON hubungan1.ID_PENGENALAN = hubungan2.APLIKASI_ID
		          WHERE hubungan1.APLIKASI_ID = APP_1.APLIKASI_ID
		          LIMIT 1
		        )

		      ELSE
		        (
		          SELECT hubungan.no_rujukan_fail || ' / ' || COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
		          FROM UMM_APLIKASI hubungan
		          WHERE hubungan.APLIKASI_ID = APP_1.APLIKASI_ID
		          LIMIT 1
		        )
		    END
		  WHEN DHAS_1.KOD_TGSN  = 'STRSPRAP' THEN
		    APP_A_1.ID_TRANSAKSI

		   WHEN COALESCE(URSN_1.KOD, URSN_2.KOD) IN ('HDHK', 'HDHD', 'KVSPM')
			AND NOT (
			DHAS_1.MODUL = 'PNT'
			AND HNTR_1.ID_PENGHANTARAN LIKE 'PNL/%'
			AND APP_1.MKLMT_TMBHN IS NOT NULL
			AND APP_1.MKLMT_TMBHN::jsonb ->> 'idPengenalanInduk' IS NOT NULL
			)
		THEN
			COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI) ||
			' ' || (
			SELECT ID_PENGENALAN
			FROM UMM_APLIKASI
			WHERE NO_RUJUKAN_FAIL = COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
			LIMIT 1
			)

			WHEN DHAS_1.MODUL = 'PNT'
				AND HNTR_1.ID_PENGHANTARAN LIKE 'PNL/%'
				AND APP_1.MKLMT_TMBHN IS NOT NULL
				AND APP_1.MKLMT_TMBHN::jsonb ->> 'idPengenalanInduk' IS NOT NULL
			THEN
				APP_1.MKLMT_TMBHN::jsonb ->> 'idPengenalanInduk'

			WHEN DHAS_1.KOD_TGSN = 'PTB' THEN '-'
		ELSE
		    COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
		END AS ID_PERMOHONAN_DASHBOARD,

		  CASE
		    WHEN DHAS_1.kod_tgsn IN ('PPF', 'PPJUB', 'PPPK', 'PPSYT') THEN org_nama.nama
		    WHEN URSN_1.kod = 'PPLBL' THEN pelelong_nama.nama_pemohon
		    ELSE bkptg_nama.nama
		  END AS NAMA_PEMOHON,
		  COALESCE(KS.NO_KERTAS_SIASATAN, APP_1.NO_RUJUKAN_FAIL, '') as NO_FAIL_PEMOHON




FROM UMM_TGSN_SEMASA DHAS_1

LEFT JOIN UMM_APLIKASI APP_1 ON DHAS_1.APLIKASI_ID = APP_1.APLIKASI_ID
LEFT JOIN UMM_APLIKASI APP_2 ON DHAS_1.APLIKASI_ID = APP_2.APLIKASI_ID
LEFT JOIN IND_URSN URSN_1 ON APP_2.URSN_ID = URSN_1.URSN_ID

LEFT JOIN IND_MODUL MDL_1 ON URSN_1.MODUL_ID = MDL_1.MODUL_ID

LEFT JOIN UMM_APLIKASI APP_3 ON DHAS_1.APLIKASI_ID = APP_3.APLIKASI_ID
LEFT JOIN UMM_APLIKASI APP_4 ON APP_3.HUBUNGAN_APLIKASI_ID = APP_4.APLIKASI_ID

LEFT JOIN UMM_P_APLIKASI APP_A_1 ON DHAS_1.P_APLIKASI_ID = APP_A_1.P_APLIKASI_ID
LEFT JOIN UMM_P_APLIKASI APP_A_2 ON DHAS_1.P_APLIKASI_ID = APP_A_2.P_APLIKASI_ID
LEFT JOIN IND_URSN URSN_2 ON APP_A_2.URSN_ID = URSN_2.URSN_ID
LEFT JOIN UMM_P_APLIKASI APP_A_3 ON DHAS_1.P_APLIKASI_ID = APP_A_3.P_APLIKASI_ID

LEFT JOIN RJK_JNS_URSN RJU_1  on URSN_1.JNS_URSN_ID = RJU_1.JNS_URSN_ID
LEFT JOIN RJK_SENARAI_AHLI_KUMPULAN SNR_1 ON APP_A_3.STATUS_ID = SNR_1.SENARAI_AHLI_KUMPULAN_ID

LEFT JOIN UMM_A_TGSN APP_TGSN_1 ON DHAS_1.A_TGSN_ID = APP_TGSN_1.A_TGSN_ID
LEFT JOIN UMM_A_TGSN APP_TGSN_2 ON DHAS_1.A_TGSN_ID = APP_TGSN_2.A_TGSN_ID
LEFT JOIN IND_TGSN ITG_1 ON APP_TGSN_2.TGSN_ID = ITG_1.TGSN_ID

LEFT JOIN UMM_A_TGSN APP_A_4 ON DHAS_1.A_TGSN_ID = APP_A_4.A_TGSN_ID
LEFT JOIN PCP_PENGGUNA PGN_1 ON APP_A_4.PENGGUNA_SEMASA_ID = PGN_1.PENGGUNA_ID

LEFT JOIN UMM_MKLMT_LAPORAN_SIASATAN MLS ON DHAS_1.MKLMT_LAPORAN_SIASATAN_ID = MLS.MKLMT_LAPORAN_SIASATAN_ID

LEFT JOIN IND_PEJABAT IPJ_1 ON DHAS_1.PEJABAT_ID = IPJ_1.PEJABAT_ID
LEFT JOIN UMM_HANTARAN_NOTIS HNTR_1 ON DHAS_1.HANTARAN_NOTIS_ID = HNTR_1.HANTARAN_NOTIS_ID
LEFT JOIN PKS_A_KERTAS_SIASATAN KS ON DHAS_1.A_KERTAS_SIASATAN_ID = KS.A_KERTAS_SIASATAN_ID

LEFT JOIN LATERAL (
	  SELECT o.nama
	  FROM umm_p_daftar_organisasi o
	  WHERE o.p_daftar_organisasi_id IN (
	    SELECT MIN(o2.p_daftar_organisasi_id)
	    FROM umm_p_daftar_organisasi o2
	    --WHERE APP_A_1.id_transaksi = APP_1.id_pengenalan
	    WHERE APP_A_1.P_APLIKASI_ID = DHAS_1.P_APLIKASI_ID
	  )
	  LIMIT 1
	) AS org_nama ON DHAS_1.kod_tgsn IN ('PPF', 'PPJUB', 'PPPK', 'PPSYT')


	LEFT JOIN LATERAL (
	  SELECT p.nama_pemohon
	  FROM llg_a_daftar_pelelong p
	  WHERE p.aplikasi_id = DHAS_1.aplikasi_id
	  ORDER BY p.a_daftar_pelelong_id ASC
	  LIMIT 1
	) AS pelelong_nama ON URSN_1.kod = 'PPLBL'

	LEFT JOIN LATERAL (
	  SELECT r.nama
	  FROM umm_a_pihak_bkptg r
	  WHERE r.aplikasi_id = DHAS_1.aplikasi_id
	    AND UPPER(r.flag_pemohon) = 'Y'
	  ORDER BY r.a_pihak_bkptg_id ASC
	  LIMIT 1
	) AS bkptg_nama ON TRUE

	WHERE UPPER(DHAS_1.FLAG_TGSN_SISTEM) = 'N'
	AND (DHAS_1.NAMA_PENGGUNA = var_nama_pengguna OR DHAS_1.NAMA_PENGGUNA IS NULL)
	AND (EXISTS (
        SELECT 1 FROM VAR_PERANAN_KOD_PENGGUNA PKP
        WHERE PKP.NAMA_PENGGUNA = DHAS_1.NAMA_PENGGUNA AND PKP.peranan_kod = 'PTG'
    	) OR DHAS_1.PEJABAT_ID IN (SELECT PEJABAT_ID FROM VAR_PEJABAT_TERKAIT) OR DHAS_1.PEJABAT_ID IS NULL
	)

	AND (
		URSN_1.KOD IN (SELECT KOD FROM VAR_URUSAN_KOD_LIST)
		OR URSN_2.KOD IN (SELECT KOD FROM VAR_URUSAN_KOD_LIST)
	)

	AND EXISTS (
		SELECT 1
		FROM VAR_PERANAN_KOD_PENGGUNA PKP
		WHERE DHAS_1.PERANAN LIKE '%-' || PKP.PERANAN_KOD || '-%'
	)
	AND (APP_TGSN_1.A_TGSN_ID is null or APP_TGSN_1.A_TGSN_ID is not null )
	--IF
		AND (
		    var_modul_kod IS NULL
		    OR DHAS_1.modul = var_modul_kod
			AND (var_modul_kod = 'DFT' AND RJU_1.KOD = var_urusan_mdl_kod)

			or  (var_modul_kod != 'DFT' AND COALESCE(URSN_1.KOD, URSN_2.KOD) = var_urusan_mdl_kod)
		)

	-- END
	),

VAR_GROUPED_TUGAS AS (
    SELECT
        mq.*,
        ROW_NUMBER() OVER (PARTITION BY ua.no_fail, mq.kod_tgsn ORDER BY mq.tgsn_semasa_id) AS rn
    FROM MAIN_QUERY mq
    LEFT JOIN umm_aplikasi ua ON mq.aplikasi_id = ua.aplikasi_id
    WHERE mq.kod_tgsn IN ('PPBKRPDPJPM', 'PPBKRSDPJPM', 'PPBKRCDPJPM')
),
VAR_MODUL_PENGGUNA AS (
  SELECT DISTINCT p.nama_pengguna, m.kod AS modul_kod
  FROM pcp_capaian_pengguna cp
  JOIN pcp_pengguna p ON cp.pengguna_id = p.pengguna_id
  JOIN pcp_peranan_modul pm ON cp.peranan_modul_id = pm.peranan_modul_id
  JOIN ind_modul m ON pm.modul_id = m.modul_id
  WHERE p.nama_pengguna IN (var_nama_pengguna)
    AND m.kod IN ('PNT', 'UAM')
),

VAR_BELUM_TUKAR_GANTI AS (
 SELECT unnest(ARRAY['HMSC', 'HMSTP', 'PRBB', 'OPRBB', 'HDHD', 'HMPV', 'HMV','HMVB','SSHM','SSSC','SW','SA','CRHMB','CSHMB','BETUL','PACT','PKH','PMKMH','PFT','REM','REMITAN'])
),
FINAL_QUERY_V1 AS (
	SELECT * FROM MAIN_QUERY AS DEFAULT_MAIN_PNT
	WHERE EXISTS (
	    SELECT 1
	    FROM VAR_MODUL_PENGGUNA mp
	    WHERE mp.nama_pengguna = DEFAULT_MAIN_PNT.nama_pengguna
	      OR DEFAULT_MAIN_PNT.modul IN ('PNT', 'UAM')
	  )
	AND DEFAULT_MAIN_PNT.kod_tgsn NOT IN ('KD', 'STRKD')
		AND NOT (
		  DEFAULT_MAIN_PNT.modul = 'CON'
		  AND DEFAULT_MAIN_PNT.kod_tgsn IN ('CSK', 'JSK')
		)
	UNION ALL
	SELECT * FROM MAIN_QUERY AS DEFAULT_MAIN
	WHERE DEFAULT_MAIN.KOD_TGSN NOT IN ('KD', 'STRKD')
	AND NOT (
	    DEFAULT_MAIN.MODUL = 'CON' AND
	    (DEFAULT_MAIN.KOD_TGSN = 'CSK' OR DEFAULT_MAIN.KOD_TGSN = 'JSK')
	)
	AND DEFAULT_MAIN.MODUL NOT IN ('PNT', 'UAM')
	AND NOT (
	    DEFAULT_MAIN.kod_tgsn IN ('KD', 'STRKD')
	    OR (DEFAULT_MAIN.NAMA_PENGGUNA IS NOT NULL AND DEFAULT_MAIN.NAMA_PENGGUNA <> var_nama_pengguna)
	)
--new

--==========
--
	AND NOT (
	    DEFAULT_MAIN.KOD_TGSN = 'PTBUT'
	    AND DEFAULT_MAIN.URUSAN_KOD IN ('PMQFT', 'PMQTFT')
	)
--==========

),

FIANL_QUERY_MERGE as (
	select * FROM FINAL_QUERY_V1 as FN_Q1
	WHERE NOT EXISTS (
		SELECT 1
   		FROM VAR_FILTER_TUGASAN_KOD_SET
		 WHERE
	      (
	        stgsn_kod = 'PTB'
	        AND FN_Q1.KOD_TGSN LIKE '%' || stgsn_kod || '%'
	      )
			OR (
		    stgsn_kod <> 'PTB'
			  AND FN_Q1.KOD_TGSN = stgsn_kod
			)
	)

 	UNION ALL
	SELECT * from (

		SELECT DISTINCT ON (FN_Q1_v2.KOD_TGSN) FN_Q1_v2.*
		FROM FINAL_QUERY_V1 as FN_Q1_v2
		WHERE EXISTS (
			 SELECT 1
      		FROM VAR_FILTER_TUGASAN_KOD_SET
			where (
					UPPER(FN_Q1_v2.STATUS_PROSES) <> 'GANTUNG'

					AND (
			          (stgsn_kod = 'PTB' AND FN_Q1_v2.KOD_TGSN LIKE '%' || stgsn_kod || '%')
			          OR (stgsn_kod = 'SJR' AND FN_Q1_v2.KOD_TGSN LIKE '%' || stgsn_kod || '%')
			          OR (stgsn_kod = 'CTK_JR' AND FN_Q1_v2.KOD_TGSN LIKE '%' || stgsn_kod || '%')
			          OR (stgsn_kod = 'PJR' AND FN_Q1_v2.KOD_TGSN LIKE '%' || stgsn_kod || '%')
			          OR (
			            stgsn_kod NOT IN ('PTB', 'SJR', 'CTK_JR', 'PJR')
			            AND FN_Q1_v2.KOD_TGSN = stgsn_kod
			          )
			        )
			) order by FN_Q1_v2.KOD_TGSN, FN_Q1_v2.tgsn_semasa_id desc
		) limit 1
	)

),
VAR_USER_PERANAN AS (
  SELECT
    LOWER(mdl.kod) AS modul,
    LOWER(sak.kod) AS peranan
  FROM pcp_capaian_pengguna cp
  JOIN pcp_pengguna pg ON cp.pengguna_id = pg.pengguna_id
  JOIN pcp_peranan_modul pm ON cp.peranan_modul_id = pm.peranan_modul_id
  JOIN ind_modul mdl ON pm.modul_id = mdl.modul_id
  JOIN rjk_senarai_ahli_kumpulan sak ON pm.peranan_id = sak.senarai_ahli_kumpulan_id
  WHERE pg.nama_pengguna = var_nama_pengguna
),
FINAL_QUERY AS (
  SELECT *
  FROM FIANL_QUERY_MERGE AS DEFAULT_MAIN
  WHERE 1=1

	AND
    (
      var_status_tugasan IS NULL
      OR UPPER(var_status_tugasan) NOT IN ('BARU', 'SEMASA')
      OR (
        UPPER(var_status_tugasan) = 'BARU' AND UPPER(DEFAULT_MAIN.STATUS_TUGASAN) = 'BARU'
      )
      OR (
        UPPER(var_status_tugasan) = 'SEMASA' AND UPPER(DEFAULT_MAIN.STATUS_TUGASAN) = 'DALAM TINDAKAN'
      )
    )
    AND (
    -- Ambil jika bukan PTB dan nama_pengguna tidak kosong
    (
      DEFAULT_MAIN.kod_tgsn NOT ILIKE '%PTB%'
      AND COALESCE(TRIM(DEFAULT_MAIN.nama_pengguna), '') <> ''
    )
    -- Atau: jika PTB / nama kosong, validasi modul dan peranan terhadap VAR_USER_PERANAN
    OR EXISTS (
      SELECT 1
      FROM VAR_USER_PERANAN u
      WHERE LOWER(u.modul) = LOWER(DEFAULT_MAIN.modul)
        AND EXISTS (
          SELECT 1
          FROM unnest(string_to_array(LOWER(DEFAULT_MAIN.peranan), '-')) AS p(peranan)
          WHERE p.peranan = u.peranan
        )
        AND (
          DEFAULT_MAIN.kod_tgsn ILIKE '%PTB%'
          OR COALESCE(TRIM(DEFAULT_MAIN.nama_pengguna), '') = ''
        )
    )

    )
    AND NOT (
      DEFAULT_MAIN.id_rujukan_smartbox IS NOT NULL
      AND DEFAULT_MAIN.id_rujukan_smartbox <> ''
      AND DEFAULT_MAIN.kod_tgsn IN ('ISHSB', 'KDSB')
    )

),

VAR_KOD_TUGSAN_BY_PELUPUSAN AS (
SELECT unnest(ARRAY['PYKP', 'SKP', 'SKP2', 'SKP3', 'PKP',
    'PYJKPTD', 'SJKPTD', 'SJKPTD2', 'SJKPTD3', 'PJKPTD', 'CJKPTD',
    'KKJKPTD', 'SKJKPTD', 'PYMMKN', 'SMMKN', 'SMMKN2', 'SMMKN3',
    'PMMKN', 'PSSPTG', 'SDPDT', 'SKMPTG', 'SKMPTG2', 'SKMPTG3',
    'SKMPTG4', 'SKMPTG5', 'PKMPTG', 'CKMPTG', 'SKPPTG', 'SKPPTG2',
    'SKPPTG3', 'SKPPTG4', 'SKPPTG5', 'PKPPTG', 'PYKPMB', 'SKPMB',
    'SKPMB2', 'SKPMB3', 'PSKPMB', 'SKPMBPTG', 'SKPMBPTG2', 'SKPMBPTG3',
    'SKPMBPTG4', 'SKPMBPTG5', 'PKPMBPTG', 'CKPMBPTG', 'PTBUT3', 'PLT',
    'SDS', 'PTBUT4', 'PPM', 'SPM', 'PFI', 'PYKMPTG'])
),
URUSAN_MODUL_PARENT_CTE AS (
  SELECT
    A.APLIKASI_ID as APP_ID_CTE,
    M.KOD AS URUSAN_MODUL_PARENT
  FROM UMM_APLIKASI A
  LEFT JOIN IND_URSN U ON A.URSN_ID = U.URSN_ID
  LEFT JOIN IND_MODUL M ON U.MODUL_ID = M.MODUL_ID
),


VAR_CONSENT_KOD AS (
    SELECT unnest(ARRAY['PFMMK', 'PPPTG', 'SFMMK', 'SPTPTG', 'KPTG','KTPTG','KCADO','KDO','PDO','STSKP','KPTG2', 'KMB'])
),
CONSENT_FILTER AS (
	SELECT *
	FROM FINAL_QUERY f
	WHERE f.MODUL = 'CON'
	  AND NOT (
	    f.urusan_kod_dashboard = 'KPMP'
	    AND var_kod_negri = '08' -- 11= param
	  )
	  AND f.KOD_TGSN IN (SELECT * FROM VAR_CONSENT_KOD)
),


CONSENT_FILTER_ONE as (
	SELECT
	CON.tgsn_semasa_id,
NULL::timestamp as trkh_pnrman,
CON.modul,
CON.id_hkmlk,
CON.no_resit,
CON.locked_by,
CON.locked_date,
CON.peranan,
CON.kod_tgsn,
CON.id_tgsn,
CON.tgsn_perihal,
CON.nama_pengguna,
CON.trkh_tetap,
CON.trkh_piagam,
CON.aplikasi_id,
CON.app_id,
CON.rangkaian_id,
CON.id_pengenalan,
CON.flag_integrasi,
CON.status_keputusan,
CON.fail_induk,
CON.status_proses,
CON.urusan_kod,
CON.no_rujukan,
CON.nama_pendek,
CON.pejabat_kod,
CON.id_penghantaran,
CON.app_a_tgsn_id,
CON.nama_pejabat_pendek,
CON.tarikh_siasatan_string,
CON.id_rujukan_smartbox,
CON.dhas_1_trkh_kpi,
CON.minit_kpi,
CON.show_id_hakmilik,
CON.no_hakmilik_baru,
CON.trkh_kpi,
CON.status_tugasan,
CON.show_kpi,
'-' as tarikh_penerimaan_string,
'-' as tarikh_dan_masa_luput_string,
CON.tarikh_dan_masa_luput,
CON.tarikh_piagam_string,
CON.tarikh_mula_string,
CON.is_filter_tugasan,
CON.tarikh_kpi,
'' as no_hakmilik_dashboard,
CON.aplikasi_no_permohonan,
'' AS no_resit_dashboard,
'' as urusan_kod_dashboard,
id_permohonan_dashboard,
CON.nama_pemohon,
'' as no_fail_pemohon

	FROM CONSENT_FILTER CON
--	ORDER BY CON.tgsn_semasa_id
--	LIMIT 1
),

FINAL_FILTER_CON as (
SELECT *
	FROM FINAL_QUERY a
--	WHERE a.modul <> 'CON'

	UNION ALL

	SELECT * FROM CONSENT_FILTER_ONE
),


FINAL_FILTER_ALL  AS (
	SELECT * FROM FINAL_FILTER_CON AS FQ

	WHERE 1=1
	AND NOT (
		FQ.MODUL = 'PFIKM'
		OR FQ.ID_TGSN IN (SELECT ID_TGSN_PELUPUSAN_PENGGUNA_FILTER FROM VAR_PELUPUSAN_TUGASAN_FILTERED)
  	)
	AND NOT (FQ.modul = 'UAM' AND FQ.URUSAN_KOD = 'BIO')

    AND NOT (
      COALESCE(TRIM(FQ.locked_by), '') <> ''
      AND LOWER(FQ.locked_by) <> LOWER(var_nama_pengguna)
      AND FQ.locked_date IS NOT NULL
      AND FQ.locked_date > NOW() - INTERVAL '30 minutes'
    )
-- NEW 

OR FQ.modul IS NULL

),

FINAL_FILTER_ALL_V2 as (
	SELECT * FROM FINAL_FILTER_ALL
),




FINAL_RESULT AS (
	SELECT * ,
	CASE
	  WHEN EXISTS (
	    SELECT 1
	    FROM UMM_PERTANYAAN p
	    JOIN RJK_SENARAI_AHLI_KUMPULAN k ON p.STATUS_ID = k.SENARAI_AHLI_KUMPULAN_ID
	    JOIN UMM_APLIKASI a ON p.APLIKASI_ID = a.APLIKASI_ID
	    JOIN IND_URSN u ON a.URSN_ID = u.URSN_ID
	    WHERE p.A_TGSN_ID = FQ.APP_A_TGSN_ID
	      AND k.KOD != 'SELESAI'
	      AND u.TEMPOH_KUIRI ~ '^[0-9]+$'
	      AND DATE_PART('day', CURRENT_DATE - p.CREATED_DATE) > u.TEMPOH_KUIRI::INT
	  )
	  THEN ' (Pertanyaan) - Telah Melebihi Tempoh Kuiri'

	  WHEN EXISTS (
	    SELECT 1
	    FROM UMM_PERTANYAAN p
	    JOIN RJK_SENARAI_AHLI_KUMPULAN k ON p.STATUS_ID = k.SENARAI_AHLI_KUMPULAN_ID
	    WHERE p.A_TGSN_ID = FQ.APP_A_TGSN_ID
	      AND k.KOD != 'SELESAI'
	  )
	  THEN ' (Pertanyaan)'

	  ELSE NULL
	END AS pertanyaan_keterangan,


	--	color and flag
	CASE
	    WHEN (
	        CASE
	            WHEN FQ.MINIT_KPI IS NOT NULL
	                 AND FQ.TRKH_PNRMAN IS NOT NULL
	                 AND FQ.DHAS_1_TRKH_KPI IS NULL
	            THEN FQ.TRKH_PNRMAN + (FQ.MINIT_KPI || ' minutes')::INTERVAL
	            ELSE FQ.DHAS_1_TRKH_KPI
	        END
	    ) IS NOT NULL
	    AND (
	        CASE
	            WHEN FQ.MINIT_KPI IS NOT NULL
	                 AND FQ.TRKH_PNRMAN IS NOT NULL
	                 AND FQ.DHAS_1_TRKH_KPI IS NULL
	            THEN FQ.TRKH_PNRMAN + (FQ.MINIT_KPI || ' minutes')::INTERVAL
	            ELSE FQ.DHAS_1_TRKH_KPI
	        END
	    ) < CURRENT_DATE
	THEN 'TUNGGAK'
	ELSE NULL
	END AS STATUS,
	CASE
	    WHEN (
	        CASE
	            WHEN FQ.MINIT_KPI IS NOT NULL
	                 AND FQ.TRKH_PNRMAN IS NOT NULL
	                 AND FQ.TRKH_KPI IS NULL
	            THEN FQ.TRKH_PNRMAN + (FQ.MINIT_KPI || ' minutes')::INTERVAL
	            ELSE FQ.DHAS_1_TRKH_KPI
	        END
	    ) IS NOT NULL
	    AND (
	        CASE
	            WHEN FQ.MINIT_KPI IS NOT NULL
	                 AND FQ.TRKH_PNRMAN IS NOT NULL
	                 AND FQ.TRKH_KPI IS NULL
	            THEN FQ.TRKH_PNRMAN + (FQ.MINIT_KPI || ' minutes')::INTERVAL
	            ELSE FQ.DHAS_1_TRKH_KPI
	        END
	    ) < CURRENT_DATE
	THEN 'red' -- warna merah sebagai contoh
	ELSE NULL
	END AS COLOR,


	CASE
	    WHEN NOT FQ.SHOW_KPI THEN 'Hijau'
	    WHEN FQ.TARIKH_DAN_MASA_LUPUT_STRING IS NULL OR FQ.TARIKH_DAN_MASA_LUPUT_STRING = '-' THEN 'Hijau'
	    WHEN FQ.TRKH_TETAP IS NULL THEN
	        CASE
	            WHEN TO_DATE(FQ.TARIKH_DAN_MASA_LUPUT_STRING, 'DD/MM/YYYY') >= CURRENT_DATE THEN 'Hijau'
	            ELSE 'Merah'
	        END
	    WHEN TO_DATE(FQ.TARIKH_DAN_MASA_LUPUT_STRING, 'DD/MM/YYYY') <= FQ.TRKH_TETAP::DATE THEN 'Hijau'
	    ELSE 'Merah'
	END AS FLAG_STATUS,

	--end color and flag

CASE
  WHEN FQ.KOD_TGSN = 'ISH' THEN TRUE
 WHEN FQ.KOD_TGSN = 'KDO' THEN TRUE
  WHEN FQ.MODUL = 'KKS' THEN TRUE
  WHEN FQ.MODUL = 'PNT' AND URUSAN_MODUL_PARENT = 'KKS' THEN TRUE
  WHEN EXISTS (
    SELECT 1
    FROM UNNEST(STRING_TO_ARRAY(FQ.URUSAN_KOD_DASHBOARD, '<BR />')) AS URSN
    WHERE URSN IN (SELECT * FROM VAR_BELUM_TUKAR_GANTI)
  ) THEN TRUE
  WHEN EXISTS (
    SELECT 1
    FROM UNNEST(STRING_TO_ARRAY(FQ.URUSAN_KOD_DASHBOARD, '<BR />')) AS URSN
    WHERE URSN IS NOT NULL
      AND (
        URSN NOT IN (SELECT * FROM VAR_BELUM_TUKAR_GANTI)
        OR URSN IN (SELECT * FROM VAR_ALSAN_TUKARGANTI_KOD_SET_BATAL)
      )
or (
    (
      SELECT COUNT(*) FROM DFT_A_MOHON_HKMLK HM
      JOIN IND_MKLMT_HKMLK MH ON MH.mklmt_hkmlk_id = HM.ID_HKMLK
      JOIN rjk_senarai_ahli_kumpulan o ON o.senarai_ahli_kumpulan_id = MH.status_hkmlk_id
      WHERE HM.APLIKASI_ID = FQ.APLIKASI_ID AND o.kod = 'STAHMBT'
    ) = (
      SELECT COUNT(*) FROM DFT_A_MOHON_HKMLK HM
      WHERE HM.APLIKASI_ID = FQ.APLIKASI_ID
    )
    or NOT EXISTS (
      SELECT 1
      FROM DFT_A_MOHON_HKMLK HM
      JOIN IND_MKLMT_HKMLK MH ON MH.mklmt_hkmlk_id = HM.ID_HKMLK
      JOIN RJK_SENARAI_AHLI_KUMPULAN o ON o.senarai_ahli_kumpulan_id = MH.status_hkmlk_id
      WHERE HM.APLIKASI_ID = FQ.APLIKASI_ID
      AND o.kod = 'STAHDFT'
      AND EXISTS (
        SELECT 1 FROM IND_VERSI_DHD TG WHERE TG.hkmlk_id = HM.ID_HKMLK
      )
    )
  )
  )

  THEN TRUE
  ELSE FALSE
END AS IS_HAKMILIK_BELUM_TUKARGANTI,



CASE
  WHEN FQ.TARIKH_DAN_MASA_LUPUT IS NULL THEN '-'

  WHEN FQ.TARIKH_DAN_MASA_LUPUT <= NOW() THEN '0 Hari'

  WHEN DATE_PART('month', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 THEN
    TRIM(BOTH FROM CONCAT_WS(' ',
      CASE
        WHEN DATE_PART('month', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0
          THEN FLOOR(DATE_PART('month', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Bulan'
      END,
      CASE
        WHEN DATE_PART('day', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0
          THEN FLOOR(DATE_PART('day', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Hari'
      END,
      CASE
        WHEN DATE_PART('hour', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0
          THEN FLOOR(DATE_PART('hour', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Jam'
      END,
      CASE
        WHEN DATE_PART('minute', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0
          THEN FLOOR(DATE_PART('minute', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Minit'
      END
    ))

  ELSE
    TRIM(BOTH FROM CONCAT_WS(' ',
      CASE
        WHEN DATE_PART('day', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0
          THEN FLOOR(DATE_PART('day', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Hari'
      END,
      CASE
        WHEN DATE_PART('hour', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0
          THEN FLOOR(DATE_PART('hour', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Jam'
      END,
      CASE
        WHEN DATE_PART('minute', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0
          THEN FLOOR(DATE_PART('minute', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Minit'
      END
    ))
END AS BAKI_MASA




FROM FINAL_FILTER_ALL_V2 AS FQ
LEFT JOIN URUSAN_MODUL_PARENT_CTE UMP ON UMP.APP_ID_CTE = FQ.APP_ID
where UPPER(FQ.STATUS_TUGASAN) <> 'SELESAI'

),



 rangkaian_merged AS (
    SELECT
      MAX(fd.TGSN_SEMASA_ID)::BIGINT AS ID,
      MAX(fd.TRKH_PNRMAN) AS TRKH_PEN,
      MAX(fd.TARIKH_PENERIMAAN_STRING) AS TARIKH_PENERIMAAN_STRING,
      MAX(fd.TARIKH_DAN_MASA_LUPUT_STRING) AS TARIKH_DAN_MASA_LUPUT_STRING,
      COALESCE(STRING_AGG(DISTINCT NULLIF(fd.NO_HAKMILIK_DASHBOARD, '-'), '<br />'), '-') AS no_hakmilik,
      ra.RANGKAIAN_ID::TEXT AS rangkaian_id_merged,
      fd.kod_tgsn::TEXT,
      STRING_AGG( fd.ID_PERMOHONAN_DASHBOARD ::TEXT, '<br />') AS id_permohonan,
      STRING_AGG(fd.URUSAN_KOD_DASHBOARD ::TEXT, '<br />') AS urusan,
      MAX(fd.NO_FAIL_PEMOHON) AS NO_FAIL_PEMOHON,
      STRING_AGG(DISTINCT  fd.NO_RESIT_DASHBOARD :: TEXT, '<br />') AS no_resit,
	  max(fd.TGSN_PERIHAL) as tugas,
      MAX(fd.NAMA_PEMOHON) AS NAMA_PEMOHON,
      MAX(fd.NAMA_PEJABAT_PENDEK) AS PEJABAT,
      MAX(fd.ID_PENGHANTARAN) AS ID_PENYAMPAIAN,
		MAX(fd.APP_A_TGSN_ID ) as id_APP_A_TGSN,
		max(fd.APLIKASI_ID),
	MAX(fd.pertanyaan_keterangan) AS pertanyaan_keterangan,
	MAX(fd.TARIKH_SIASATAN_STRING) as TARIKH_SIASATAN_STRING,
	MAX(fd.STATUS) as ROW_STATUS,
	MAX(fd.COLOR) as ROW_COLOR,
	MAX(fd.FLAG_STATUS) as FLAG_STATUS,
	(MAX(CASE WHEN fd.IS_HAKMILIK_BELUM_TUKARGANTI THEN 1 ELSE 0 END) = 1),
	MAX(fd.BAKI_MASA) as BAKI_MASA,
	max(fd.NO_HAKMILIK_BARU) as NO_HAKMILIK_BARU,
	MAX(fd.MODUL) as MODUL

    FROM FINAL_RESULT fd
    JOIN UMM_APLIKASI ra ON fd.APLIKASI_ID = ra.APLIKASI_ID
    WHERE ra.RANGKAIAN_ID IS NOT NULL
      AND fd.kod_tgsn <> 'IMH'
    GROUP BY ra.RANGKAIAN_ID, fd.kod_tgsn
  ),

  remaining_rows AS (
    SELECT
      fd.TGSN_SEMASA_ID::BIGINT AS ID,
      fd.TRKH_PNRMAN AS TRKH_PEN,
      fd.TARIKH_PENERIMAAN_STRING,
      fd.TARIKH_DAN_MASA_LUPUT_STRING,
      COALESCE(fd.NO_HAKMILIK_DASHBOARD, '-') AS no_hakmilik,
      NULL::TEXT AS rangkaian_id_merged,
      fd.kod_tgsn::TEXT,
      fd.ID_PERMOHONAN_DASHBOARD AS id_permohonan,
      fd.URUSAN_KOD_DASHBOARD AS urusan,
      fd.NO_FAIL_PEMOHON AS NO_FAIL_PEMOHON,
      fd.NO_RESIT_DASHBOARD AS no_resit,
		fd.TGSN_PERIHAL as tugas,
      fd.NAMA_PEMOHON AS NAMA_PEMOHON,
      fd.NAMA_PEJABAT_PENDEK AS PEJABAT,
      fd.ID_PENGHANTARAN AS ID_PENYAMPAIAN,
	fd.APP_A_TGSN_ID as id_APP_A_TGSN,
	fd.APLIKASI_ID,

	fd.pertanyaan_keterangan,
	fd.TARIKH_SIASATAN_STRING as TARIKH_SIASATAN_STRING,
	fd.STATUS as ROW_STATUS,
	fd.COLOR as ROW_COLOR,
	fd.FLAG_STATUS as FLAG_STATUS,
	fd.IS_HAKMILIK_BELUM_TUKARGANTI,
	fd.BAKI_MASA as BAKI_MASA,
	fd.NO_HAKMILIK_BARU as NO_HAKMILIK_BARU,
	fd.MODUL as MODUL

    FROM FINAL_RESULT fd
    LEFT JOIN UMM_APLIKASI ra ON fd.APLIKASI_ID = ra.APLIKASI_ID


  ),

FINAL_V2 AS (
    SELECT DISTINCT ON (merged.id) merged.*
    FROM (
        SELECT * FROM rangkaian_merged
        UNION ALL
        SELECT * FROM remaining_rows
    ) merged

    WHERE (
        var_modul_kod IS NULL
        OR (
            merged.modul = var_modul_kod
            AND (
                var_modul_kod <> 'DFT'
                OR (
                    var_modul_kod = 'DFT'
                    AND merged.id IN (
                        SELECT
                            d.tgsn_semasa_id
                        FROM UMM_TGSN_SEMASA d
                        INNER JOIN UMM_APLIKASI a ON d.aplikasi_id = a.APLIKASI_ID
                        INNER JOIN IND_URSN u ON a.URSN_ID = u.URSN_ID
                        INNER JOIN RJK_JNS_URSN j ON u.JNS_URSN_ID = j.JNS_URSN_ID
                        INNER JOIN IND_MODUL m ON u.MODUL_ID = m.MODUL_ID
                        WHERE
                            m.kod = var_modul_kod
                            AND d.nama_pengguna = var_nama_pengguna
                            AND d.FLAG_TGSN_SISTEM = 'N'
                            AND d.pejabat_id = var_pejabat_id
                            AND d.TGSN_PERIHAL NOT IN ('Kutipan Dokumen', 'Imbasan Dokumen Hakmilik Batal')
                            AND a.status_keputusan <> 'Batal'
                            AND j.kod = var_urusan_mdl_kod
                    )
                )
            )
        )
    )

    ORDER BY merged.id, merged.trkh_pen DESC
),

  params AS (
    SELECT trim(c.col) AS fcol, trim(v.val) AS fval
    FROM unnest(string_to_array(var_filter_colum, ',')) WITH ORDINALITY AS c(col, idx)
    JOIN unnest(string_to_array(var_filter_val, '||')) WITH ORDINALITY AS v(val, idx2)
      ON c.idx = v.idx2
)


SELECT *
FROM FINAL_V2 v2
WHERE
    -- Jika tidak ada filter sama sekali, kembalikan semua
    NOT EXISTS (SELECT 1 FROM params)

    -- Jika ada filter, cocokkan semua kolom
    OR (
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TARIKH_PENERIMAAN_STRING')
         OR v2.TARIKH_PENERIMAAN_STRING ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TARIKH_PENERIMAAN_STRING')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TARIKH_DAN_MASA_LUPUT_STRING')
         OR v2.TARIKH_DAN_MASA_LUPUT_STRING ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TARIKH_DAN_MASA_LUPUT_STRING')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TARIKH_SIASATAN_STRING')
         OR v2.TARIKH_SIASATAN_STRING ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TARIKH_SIASATAN_STRING')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'NO_HAKMILIK')
         OR v2.NO_HAKMILIK ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'NO_HAKMILIK')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'ID_PERMOHONAN')
         OR v2.ID_PERMOHONAN ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'ID_PERMOHONAN')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'NO_FAIL_PEMOHON')
         OR v2.NO_FAIL_PEMOHON ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'NO_FAIL_PEMOHON')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'NO_RESIT')
         OR v2.NO_RESIT ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'NO_RESIT')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'URUSAN')
         OR v2.URUSAN ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'URUSAN')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'NAMA_PEMOHON')
         OR v2.NAMA_PEMOHON ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'NAMA_PEMOHON')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'PERTANYAAN_KETERANGAN')
         OR v2.PERTANYAAN_KETERANGAN ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'PERTANYAAN_KETERANGAN')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TUGAS')
         OR v2.TUGAS ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TUGAS')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'PEJABAT')
         OR v2.PEJABAT ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'PEJABAT')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'ID_PENYAMPAIAN')
         OR v2.ID_PENYAMPAIAN ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'ID_PENYAMPAIAN')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TUGASAN')
         OR v2.TUGAS ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TUGASAN')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'FLAG_STATUS')
         OR v2.FLAG_STATUS ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'FLAG_STATUS')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'BAKI_MASA')
         OR v2.BAKI_MASA ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'BAKI_MASA')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TUGAS_AND_PERTANYAAN')
         OR (v2.TUGAS ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TUGAS_AND_PERTANYAAN'))
             OR v2.PERTANYAAN_KETERANGAN ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TUGAS_AND_PERTANYAAN'))))
    )

 ORDER BY
  -- Default fallback kalau tidak ada kolom urutan diberikan
  CASE
    WHEN var_sort_colum IS NULL THEN V2.TARIKH_PENERIMAAN_STRING
  END ASC,

  -- Jika kolom urutan diberikan, gunakan CASE berdasarkan nama kolom dan tipe sort
  CASE WHEN var_sort_colum = 'TARIKH_PENERIMAAN_STRING' AND var_sort_type = 'ASC' THEN V2.TRKH_PEN END ASC,
  CASE WHEN var_sort_colum = 'TARIKH_PENERIMAAN_STRING' AND var_sort_type = 'DESC' THEN V2.TRKH_PEN END DESC,

  CASE WHEN var_sort_colum = 'TARIKH_DAN_MASA_LUPUT_STRING' AND var_sort_type = 'ASC' THEN V2.TARIKH_DAN_MASA_LUPUT_STRING END ASC,
  CASE WHEN var_sort_colum = 'TARIKH_DAN_MASA_LUPUT_STRING' AND var_sort_type = 'DESC' THEN V2.TARIKH_DAN_MASA_LUPUT_STRING END DESC,

  CASE WHEN var_sort_colum = 'TARIKH_SIASATAN_STRING' AND var_sort_type = 'ASC' THEN V2.TARIKH_SIASATAN_STRING END ASC,
  CASE WHEN var_sort_colum = 'TARIKH_SIASATAN_STRING' AND var_sort_type = 'DESC' THEN V2.TARIKH_SIASATAN_STRING END DESC,

  CASE WHEN var_sort_colum = 'NO_HAKMILIK' AND var_sort_type = 'ASC' THEN V2.NO_HAKMILIK END ASC,
  CASE WHEN var_sort_colum = 'NO_HAKMILIK' AND var_sort_type = 'DESC' THEN V2.NO_HAKMILIK END DESC,

  CASE WHEN var_sort_colum = 'KOD_TGSN' AND var_sort_type = 'ASC' THEN V2.KOD_TGSN END ASC,
  CASE WHEN var_sort_colum = 'KOD_TGSN' AND var_sort_type = 'DESC' THEN V2.KOD_TGSN END DESC,

  CASE WHEN var_sort_colum = 'ID_PERMOHONAN' AND var_sort_type = 'ASC' THEN V2.ID_PERMOHONAN END ASC,
  CASE WHEN var_sort_colum = 'ID_PERMOHONAN' AND var_sort_type = 'DESC' THEN V2.ID_PERMOHONAN END DESC,

  CASE WHEN var_sort_colum = 'URUSAN' AND var_sort_type = 'ASC' THEN V2.URUSAN END ASC,
  CASE WHEN var_sort_colum = 'URUSAN' AND var_sort_type = 'DESC' THEN V2.URUSAN END DESC,

  CASE WHEN var_sort_colum = 'NO_FAIL_PEMOHON' AND var_sort_type = 'ASC' THEN V2.NO_FAIL_PEMOHON END ASC,
  CASE WHEN var_sort_colum = 'NO_FAIL_PEMOHON' AND var_sort_type = 'DESC' THEN V2.NO_FAIL_PEMOHON END DESC,

  CASE WHEN var_sort_colum = 'NO_RESIT' AND var_sort_type = 'ASC' THEN V2.NO_RESIT END ASC,
  CASE WHEN var_sort_colum = 'NO_RESIT' AND var_sort_type = 'DESC' THEN V2.NO_RESIT END DESC,

  CASE WHEN var_sort_colum = 'TUGAS' AND var_sort_type = 'ASC' THEN V2.TUGAS END ASC,
  CASE WHEN var_sort_colum = 'TUGAS' AND var_sort_type = 'DESC' THEN V2.TUGAS END DESC,

  CASE WHEN var_sort_colum = 'NAMA_PEMOHON' AND var_sort_type = 'ASC' THEN V2.NAMA_PEMOHON END ASC,
  CASE WHEN var_sort_colum = 'NAMA_PEMOHON' AND var_sort_type = 'DESC' THEN V2.NAMA_PEMOHON END DESC,

  CASE WHEN var_sort_colum = 'PEJABAT' AND var_sort_type = 'ASC' THEN V2.PEJABAT END ASC,
  CASE WHEN var_sort_colum = 'PEJABAT' AND var_sort_type = 'DESC' THEN V2.PEJABAT END DESC,

  CASE WHEN var_sort_colum = 'PERTANYAAN_KETERANGAN' AND var_sort_type = 'ASC' THEN V2.PERTANYAAN_KETERANGAN END ASC,
  CASE WHEN var_sort_colum = 'PERTANYAAN_KETERANGAN' AND var_sort_type = 'DESC' THEN V2.PERTANYAAN_KETERANGAN END DESC,

  CASE WHEN var_sort_colum = 'ID_PENYAMPAIAN' AND var_sort_type = 'ASC' THEN V2.ID_PENYAMPAIAN END ASC,
  CASE WHEN var_sort_colum = 'ID_PENYAMPAIAN' AND var_sort_type = 'DESC' THEN V2.ID_PENYAMPAIAN END DESC,

	CASE WHEN var_sort_colum = 'BAKI_MASA' AND var_sort_type = 'ASC' THEN V2.BAKI_MASA END ASC,
  CASE WHEN var_sort_colum = 'BAKI_MASA' AND var_sort_type = 'DESC' THEN V2.BAKI_MASA END DESC,


  CASE WHEN var_sort_colum = 'TUGAS_AND_PERTANYAAN' AND var_sort_type = 'ASC' THEN V2.TUGAS END ASC,
  CASE WHEN var_sort_colum = 'TUGAS_AND_PERTANYAAN' AND var_sort_type = 'DESC' THEN V2.TUGAS END DESC



	LIMIT CASE WHEN NOT var_export AND var_limit IS NOT NULL THEN var_limit ELSE NULL
	END
	OFFSET CASE WHEN NOT var_export AND var_offset IS NOT NULL THEN var_offset ELSE 0
	END;


END;
$function$
;

-- DROP FUNCTION et_main_uat.get_dashboard_by_pengguna_test(numeric, numeric, _text, text, numeric, text, text, text, text, bool, text, text, text, text);

CREATE OR REPLACE FUNCTION et_main_uat.get_dashboard_by_pengguna_test(var_limit numeric DEFAULT NULL::numeric, var_offset numeric DEFAULT NULL::numeric, var_urusan_kod_list text[], var_nama_pengguna text DEFAULT NULL::text, var_pejabat_id numeric DEFAULT NULL::numeric, var_modul_kod text DEFAULT NULL::text, var_urusan_mdl_kod text DEFAULT NULL::text, var_status_tugasan text DEFAULT NULL::text, var_kod_negri text DEFAULT NULL::text, var_export boolean DEFAULT false, var_sort_colum text DEFAULT NULL::text, var_sort_type text DEFAULT NULL::text, var_filter_colum text DEFAULT NULL::text, var_filter_val text DEFAULT NULL::text)
 RETURNS TABLE(id bigint, trkh_pen timestamp without time zone, tarikh_penerimaan_string text, tarikh_dan_masa_luput_string text, no_hakmilik text, rangkaian_id_merged text, kod_tgsn text, id_permohonan text, urusan text, no_fail_pemohon text, no_resit text, tugas text, nama_pemohon text, pejabat text, id_penyampaian text, id_app_a_tgsn numeric, id_app_aplikasi numeric, pertanyaan_keterangan text, tarikh_siasatan_string text, row_status text, row_color text, flag_status text, is_hakmilik_belum_tukarganti boolean, baki_masa text, no_hakmilik_baru text, modul text)
 LANGUAGE plpgsql
AS $function$
BEGIN
  RETURN QUERY
WITH VAR_URUSAN_KOD_LIST AS (
    SELECT UNNEST(var_urusan_kod_list) AS KOD
  ),
VAR_PERANAN_KOD_PENGGUNA AS (
  SELECT DISTINCT PP.NAMA_PENGGUNA, RM.KOD AS PERANAN_KOD
  FROM PCP_CAPAIAN_PENGGUNA CP
  JOIN PCP_PENGGUNA PP ON CP.PENGGUNA_ID = PP.PENGGUNA_ID
  JOIN PCP_PERANAN_MODUL PM ON CP.PERANAN_MODUL_ID = PM.PERANAN_MODUL_ID
  JOIN RJK_SENARAI_AHLI_KUMPULAN RM ON PM.PERANAN_ID = RM.SENARAI_AHLI_KUMPULAN_ID
  WHERE PP.NAMA_PENGGUNA IN (var_nama_pengguna)
),
VAR_DAERAH_PENGGUNA AS (
    SELECT DISTINCT DAERAH_ID
    FROM IND_PEJABAT AS IP
    WHERE PEJABAT_ID IN (var_pejabat_id) 
),
VAR_PEJABAT_TERKAIT AS (
    SELECT DISTINCT PEJABAT_ID
    FROM IND_PEJABAT AS IP
    WHERE DAERAH_ID IN (SELECT DAERAH_ID FROM VAR_DAERAH_PENGGUNA)
),
VAR_FILTER_TUGASAN_KOD_SET AS (
	SELECT UNNEST(ARRAY['PPBKRPJPM', 'PPBKRKPJPM', 'PTB', 'SJR',
    'PJR', 'CTK_JR', 'PMMP6PTB2', 'PPBBPTB2',
    'PPHSYBPTB2', 'PKJR', 'PKJRPP']) as stgsn_kod
),

VAR_PELUPUSAN_TUGASAN_FILTERED AS (
  SELECT ID_TGSN AS ID_TGSN_PELUPUSAN_PENGGUNA_FILTER
  FROM (
    SELECT A.ID_TGSN,
        ROW_NUMBER() OVER (
            PARTITION BY COALESCE(C.kod, E.kod), A.ID_TGSN
            ORDER BY A.ID_TGSN
    ) AS RN
    FROM UMM_TGSN_SEMASA A
    LEFT JOIN UMM_APLIKASI B ON B.APLIKASI_ID = A.APLIKASI_ID
    LEFT JOIN IND_URSN C ON C.URSN_ID = B.URSN_ID
    LEFT JOIN UMM_P_APLIKASI D ON D.APLIKASI_ID = A.APLIKASI_ID
    LEFT JOIN IND_URSN E ON E.URSN_ID = D.URSN_ID
    WHERE A.MODUL = 'PLP'
      AND A.KOD_TGSN = 'FPIKM'
      AND UPPER(A.FLAG_TGSN_SISTEM) = 'N'
  ) A
  WHERE RN = 1
),
VAR_PEJABAT_PERANAN_MAP AS (
  SELECT * FROM (VALUES
    ('TRG', ARRAY['PTG', 'TPTG', 'KPP']),
    ('PRK', ARRAY['PTG', 'KPP']),
    ('SEL', ARRAY['PTG', 'TPTG'])
  ) AS T (KOD_PEJABAT, PERANANS)
),
VAR_PLP_TUGASAN_KOD_SET AS (
    SELECT unnest(ARRAY['PDKM', 'SDKM', 'SDKM2', 'SDKM3', 'PPKM', 'CKM', 'CKMPPLN'])
),
VAR_ALSAN_TUKARGANTI_KOD_SET AS (
    SELECT unnest(ARRAY['KMPP', 'HMSC', 'HMSTP', 'PRBB', 'OPRBB', 'HDHD', 'HMPV', 'HMV', 'HMVB',
            'SSHM', 'SSSC', 'SW', 'SA', 'CRHMB', 'CSHMB', 'BETUL', 'PACT', 'PKH', 'PMKMH', 'PFT', 'REM', 'REMITAN'])
),
VAR_GROUP_BY_NO_FAIL_TUGASAN_KOD_SET AS (
    SELECT unnest(ARRAY['PPBKRPDPJPM', 'PPBKRSDPJPM', 'PPBKRCDPJPM'])
),

VAR_ALSAN_TUKARGANTI_KOD_SET_BATAL AS (
    SELECT unnest(ARRAY['HDHK', 'HPLN','PMKMH','HSSTB','HKSSS'])
),
VAR_NO_HAK_MILIK_BARU AS (
    SELECT 
        mohon.APLIKASI_ID,
        STRING_AGG(mohon.id_hkmlk, '<br>') AS NO_HAKMILIK_BARU
    FROM dft_A_MOHON_HKMLK mohon
    JOIN UMM_APLIKASI appl ON appl.APLIKASI_ID = mohon.APLIKASI_ID
    JOIN IND_URSN urusan ON appl.URSN_ID = urusan.URSN_ID
    JOIN rjk_jns_ursn jenis ON jenis.jns_ursn_id = urusan.jns_ursn_id
    WHERE mohon.id_hkmlk IS NOT NULL
      AND jenis.KOD = 'MH'
    GROUP BY mohon.APLIKASI_ID
),
MAIN_QUERY AS (
	SELECT 
  	DHAS_1.TGSN_SEMASA_ID,
	DHAS_1.TRKH_PNRMAN,
	DHAS_1.MODUL,
	DHAS_1.ID_HKMLK,
	DHAS_1.NO_RESIT,
	DHAS_1.LOCKED_BY,
	DHAS_1.LOCKED_DATE,
	DHAS_1.PERANAN,
	DHAS_1.KOD_TGSN,
	DHAS_1.ID_TGSN,
	DHAS_1.TGSN_PERIHAL,
	DHAS_1.NAMA_PENGGUNA,
	APP_TGSN_1.TRKH_TETAP,
	APP_1.TRKH_PIAGAM,
	APP_1.APLIKASI_ID,
	APP_1.APLIKASI_ID as APP_ID,
	APP_1.RANGKAIAN_ID,
	APP_1.ID_PENGENALAN,
	APP_1.FLAG_INTEGRASI,
	APP_1.STATUS_KEPUTUSAN,
	APP_1.FAIL_INDUK,
	COALESCE(APP_1.STATUS_PROSES, SNR_1.NAMA) AS STATUS_PROSES,
    COALESCE(URSN_1.KOD, URSN_2.KOD) AS URUSAN_KOD,
    COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI) AS NO_RUJUKAN,
	IPJ_1.NAMA_PENDEK,
	IPJ_1.KOD AS PEJABAT_KOD,
	HNTR_1.ID_PENGHANTARAN,
	DHAS_1.a_tgsn_id as APP_A_TGSN_ID,
	IPJ_1.NAMA_PENDEK as NAMA_PEJABAT_PENDEK,
	TO_CHAR(MLS.TRKH_SIASATAN, 'DD/MM/YYYY') AS TARIKH_SIASATAN_STRING,
	APP_1.ID_RUJUKAN_SMARTBOX,
	DHAS_1.TRKH_KPI AS DHAS_1_TRKH_KPI,
	ITG_1.MINIT_KPI,
	CASE 
      WHEN URSN_1.KOD = 'PSBS' AND DHAS_1.TGSN_PERIHAL = 'Penyediaan Fail Induk Kertas Mesyuarat' THEN FALSE
      ELSE TRUE 
    END AS SHOW_ID_HAKMILIK,
	(
      SELECT STRING_AGG(mohon.id_hkmlk, '<br>')
      FROM dft_A_MOHON_HKMLK mohon
      JOIN UMM_APLIKASI appl ON appl.APLIKASI_ID = mohon.APLIKASI_ID
      JOIN IND_URSN urusan ON appl.URSN_ID = urusan.URSN_ID
      JOIN rjk_jns_ursn jenis ON jenis.jns_ursn_id = urusan.jns_ursn_id
      WHERE mohon.APLIKASI_ID = DHAS_1.APLIKASI_ID
        AND mohon.id_hkmlk IS NOT NULL
        AND jenis.KOD = CAST('MH' AS VARCHAR)
    ) AS NO_HAKMILIK_BARU,
	
	CASE 
		WHEN DHAS_1.TRKH_KPI IS NULL 
		     AND ITG_1.MINIT_KPI IS NOT NULL 
		     AND DHAS_1.TRKH_PNRMAN IS NOT NULL
		THEN DHAS_1.TRKH_PNRMAN + (ITG_1.MINIT_KPI || ' minutes')::INTERVAL
		ELSE DHAS_1.TRKH_KPI
	END AS TRKH_KPI,
	CASE 
		WHEN APP_TGSN_1.STATUS_TUGASAN IS NULL OR DHAS_1.TGSN_PERIHAL = 'Pengagihan Tugasan Baru' 
		THEN 'Baru'
		ELSE APP_TGSN_1.STATUS_TUGASAN
	END AS STATUS_TUGASAN,

	CASE 
		WHEN ITG_1.MINIT_KPI IS NOT NULL THEN TRUE
		ELSE FALSE
	END AS SHOW_KPI,
	CASE 
    WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
         AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
              OR DHAS_1.KOD_TGSN LIKE '%PTB%')
    THEN '-' 
    ELSE TO_CHAR(DHAS_1.TRKH_PNRMAN, 'DD/MM/YYYY')
	END AS TARIKH_PENERIMAAN_STRING,

	CASE 
	
		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
			AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
				OR DHAS_1.KOD_TGSN LIKE '%PTB%')
		THEN '-' 

		ELSE TO_CHAR(
			CASE
			WHEN ITG_1.MINIT_KPI IS NOT NULL 
				AND DHAS_1.TRKH_PNRMAN IS NOT NULL 
				AND DHAS_1.TRKH_KPI IS NULL
			THEN DHAS_1.TRKH_PNRMAN + (ITG_1.MINIT_KPI || ' minutes')::INTERVAL
			ELSE DHAS_1.TRKH_KPI
			END,
			'DD/MM/YYYY'
		)
	END AS TARIKH_DAN_MASA_LUPUT_STRING,
	CASE
  		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL
       AND (
         DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
         OR DHAS_1.KOD_TGSN LIKE '%PTB%'
       )
	THEN NULL
	ELSE
		CASE
		WHEN ITG_1.MINIT_KPI IS NOT NULL
			AND DHAS_1.TRKH_PNRMAN IS NOT NULL
			AND DHAS_1.TRKH_KPI IS NULL
		THEN DHAS_1.TRKH_PNRMAN + (ITG_1.MINIT_KPI || ' minutes')::INTERVAL
		ELSE DHAS_1.TRKH_KPI
		END
	END AS TARIKH_DAN_MASA_LUPUT,

	CASE 
		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
			AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
				OR DHAS_1.KOD_TGSN LIKE '%PTB%')
		THEN '-' 
		ELSE TO_CHAR(APP_1.TRKH_PIAGAM, 'DD/MM/YYYY')
	END AS TARIKH_PIAGAM_STRING,
	CASE 
		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
			AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
				OR DHAS_1.KOD_TGSN LIKE '%PTB%')
		THEN '-' 
		ELSE TO_CHAR(APP_TGSN_1.TRKH_TETAP, 'DD/MM/YYYY')
	END AS TARIKH_MULA_STRING,
	CASE 
		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
			AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
				OR DHAS_1.KOD_TGSN LIKE '%PTB%')
		THEN TRUE 
		ELSE FALSE 
	END AS IS_FILTER_TUGASAN,
	CASE
		WHEN ITG_1.MINIT_KPI IS NOT NULL 
			AND DHAS_1.TRKH_PNRMAN IS NOT NULL 
			AND DHAS_1.TRKH_KPI IS NULL
		THEN DHAS_1.TRKH_PNRMAN + (ITG_1.MINIT_KPI || ' minutes')::INTERVAL
		ELSE DHAS_1.TRKH_KPI
	END AS TARIKH_KPI,
	

	CASE 
	  WHEN NOT (
	    TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
	    AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
	         OR DHAS_1.KOD_TGSN LIKE '%PTB%')
	  )
	  THEN 
	    CASE 
	      WHEN COALESCE(NULLIF(TRIM(DHAS_1.ID_HKMLK), ''), '-') = '-' THEN '-'
	      ELSE (
	        SELECT 
	          CASE 
	            WHEN COUNT(*) > 10 
	            THEN (
	              SELECT string_agg(val, ', ') || '...'
	              FROM (
	                SELECT DISTINCT val
	                FROM unnest(string_to_array(DHAS_1.ID_HKMLK, ',')) AS val
	                ORDER BY val
	                LIMIT 10
	              ) sub
	            )
	            ELSE (
	              SELECT string_agg(DISTINCT val, ', ' ORDER BY val)
	              FROM unnest(string_to_array(DHAS_1.ID_HKMLK, ',')) AS val
	            )
	          END
	      )
	    END
	  ELSE COALESCE(NULLIF(TRIM(DHAS_1.ID_HKMLK), ''), '-') 
	END AS NO_HAKMILIK_DASHBOARD,
	CASE 
	  WHEN NOT (
	    TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
	    AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
	         OR DHAS_1.KOD_TGSN LIKE '%PTB%')
	  )
	  THEN COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
	  ELSE NULL
	END AS APLIKASI_NO_PERMOHONAN,
	
	
	CASE 
	  WHEN NOT (
	    TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
	    AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
	         OR DHAS_1.KOD_TGSN LIKE '%PTB%')
	  )
		  THEN 
		    CASE 
		      WHEN COALESCE(NULLIF(TRIM(DHAS_1.NO_RESIT), ''), '-') = '-' THEN '-'
		      ELSE (
		        SELECT 
		          CASE 
		            WHEN COUNT(*) > 10 
		            THEN (
		              SELECT string_agg(val, ', ') || '...'
		              FROM (
		                SELECT DISTINCT val
		                FROM unnest(string_to_array(DHAS_1.NO_RESIT, ',')) AS val
		                ORDER BY val
		                LIMIT 10
		              ) sub
		            )
		            ELSE (
		              SELECT string_agg(DISTINCT val, ', ' ORDER BY val)
		              FROM unnest(string_to_array(DHAS_1.NO_RESIT, ',')) AS val
		            )
		          END
		      )
		    END
		  ELSE COALESCE(NULLIF(TRIM(DHAS_1.NO_RESIT), ''), '-') 
		END AS NO_RESIT_DASHBOARD,
		
		
		CASE
		  WHEN NOT (
		    TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
		    AND (
		      DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
		      OR DHAS_1.KOD_TGSN LIKE '%PTB%'
		    )
		  )
		  THEN
		    CASE 
		      WHEN HNTR_1.ID_PENGHANTARAN IS NOT NULL AND HNTR_1.ID_PENGHANTARAN LIKE 'PNL/%'
		        THEN 'UPNL'
		      ELSE COALESCE(URSN_1.KOD, URSN_2.KOD)
		    END
		  ELSE
		    COALESCE(URSN_1.KOD, URSN_2.KOD)
		END AS URUSAN_KOD_DASHBOARD,

		CASE
		  WHEN UPPER(APP_1.FLAG_INTEGRASI) ='Y' THEN
		    CASE
		      WHEN COALESCE(COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI), '') LIKE '%MF%' 
		           AND COALESCE(COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI), '') LIKE '%(%' THEN
		        SPLIT_PART(COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI), '(', 1)
		        
		      WHEN COALESCE(APP_1.URSN_ID, URSN_2.URSN_ID) IS NOT NULL 
		           AND COALESCE(URSN_1.KOD, URSN_2.KOD) = 'KVSP' THEN
		        (
		          SELECT hubungan2.ID_PENGENALAN || ' / ' || COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
		          FROM UMM_APLIKASI hubungan1
		          JOIN UMM_APLIKASI hubungan2 ON hubungan1.ID_PENGENALAN = hubungan2.APLIKASI_ID
		          WHERE hubungan1.APLIKASI_ID = APP_1.APLIKASI_ID
		          LIMIT 1
		        )
		        
		      ELSE
		        (
		          SELECT hubungan.no_rujukan_fail || ' / ' || COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
		          FROM UMM_APLIKASI hubungan
		          WHERE hubungan.APLIKASI_ID = APP_1.APLIKASI_ID
		          LIMIT 1
		        )
		    END
		  WHEN DHAS_1.KOD_TGSN  = 'STRSPRAP' THEN
		    APP_A_1.ID_TRANSAKSI

		   WHEN COALESCE(URSN_1.KOD, URSN_2.KOD) IN ('HDHK', 'HDHD', 'KVSPM')
			AND NOT (
			DHAS_1.MODUL = 'PNT'
			AND HNTR_1.ID_PENGHANTARAN LIKE 'PNL/%'
			AND APP_1.MKLMT_TMBHN IS NOT NULL
			AND APP_1.MKLMT_TMBHN::jsonb ->> 'idPengenalanInduk' IS NOT NULL
			)
		THEN
			COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI) || 
			' ' || (
			SELECT ID_PENGENALAN 
			FROM UMM_APLIKASI 
			WHERE NO_RUJUKAN_FAIL = COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
			LIMIT 1
			)

			WHEN DHAS_1.MODUL = 'PNT'
				AND HNTR_1.ID_PENGHANTARAN LIKE 'PNL/%'
				AND APP_1.MKLMT_TMBHN IS NOT NULL
				AND APP_1.MKLMT_TMBHN::jsonb ->> 'idPengenalanInduk' IS NOT NULL
			THEN
				APP_1.MKLMT_TMBHN::jsonb ->> 'idPengenalanInduk'
		
			WHEN DHAS_1.KOD_TGSN = 'PTB' THEN '-'
		ELSE
		    COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
		END AS ID_PERMOHONAN_DASHBOARD,
	
		  CASE
		    WHEN DHAS_1.kod_tgsn IN ('PPF', 'PPJUB', 'PPPK', 'PPSYT') THEN org_nama.nama
		    WHEN URSN_1.kod = 'PPLBL' THEN pelelong_nama.nama_pemohon
		    ELSE bkptg_nama.nama
		  END AS NAMA_PEMOHON,
		  COALESCE(KS.NO_KERTAS_SIASATAN, APP_1.NO_RUJUKAN_FAIL, '') as NO_FAIL_PEMOHON
	



FROM UMM_TGSN_SEMASA DHAS_1

LEFT JOIN UMM_APLIKASI APP_1 ON DHAS_1.APLIKASI_ID = APP_1.APLIKASI_ID
LEFT JOIN UMM_APLIKASI APP_2 ON DHAS_1.APLIKASI_ID = APP_2.APLIKASI_ID
LEFT JOIN IND_URSN URSN_1 ON APP_2.URSN_ID = URSN_1.URSN_ID

LEFT JOIN UMM_APLIKASI APP_3 ON DHAS_1.APLIKASI_ID = APP_3.APLIKASI_ID
LEFT JOIN UMM_APLIKASI APP_4 ON APP_3.HUBUNGAN_APLIKASI_ID = APP_4.APLIKASI_ID

LEFT JOIN UMM_P_APLIKASI APP_A_1 ON DHAS_1.P_APLIKASI_ID = APP_A_1.P_APLIKASI_ID
LEFT JOIN UMM_P_APLIKASI APP_A_2 ON DHAS_1.P_APLIKASI_ID = APP_A_2.P_APLIKASI_ID
LEFT JOIN IND_URSN URSN_2 ON APP_A_2.URSN_ID = URSN_2.URSN_ID
LEFT JOIN UMM_P_APLIKASI APP_A_3 ON DHAS_1.P_APLIKASI_ID = APP_A_3.P_APLIKASI_ID

LEFT JOIN RJK_JNS_URSN RJU_1  on URSN_1.JNS_URSN_ID = RJU_1.JNS_URSN_ID
LEFT JOIN RJK_SENARAI_AHLI_KUMPULAN SNR_1 ON APP_A_3.STATUS_ID = SNR_1.SENARAI_AHLI_KUMPULAN_ID

LEFT JOIN UMM_A_TGSN APP_TGSN_1 ON DHAS_1.A_TGSN_ID = APP_TGSN_1.A_TGSN_ID
LEFT JOIN UMM_A_TGSN APP_TGSN_2 ON DHAS_1.A_TGSN_ID = APP_TGSN_2.A_TGSN_ID
LEFT JOIN IND_TGSN ITG_1 ON APP_TGSN_2.TGSN_ID = ITG_1.TGSN_ID

LEFT JOIN UMM_A_TGSN APP_A_4 ON DHAS_1.A_TGSN_ID = APP_A_4.A_TGSN_ID
LEFT JOIN PCP_PENGGUNA PGN_1 ON APP_A_4.PENGGUNA_SEMASA_ID = PGN_1.PENGGUNA_ID

LEFT JOIN UMM_MKLMT_LAPORAN_SIASATAN MLS ON DHAS_1.MKLMT_LAPORAN_SIASATAN_ID = MLS.MKLMT_LAPORAN_SIASATAN_ID

LEFT JOIN IND_PEJABAT IPJ_1 ON DHAS_1.PEJABAT_ID = IPJ_1.PEJABAT_ID
LEFT JOIN UMM_HANTARAN_NOTIS HNTR_1 ON DHAS_1.HANTARAN_NOTIS_ID = HNTR_1.HANTARAN_NOTIS_ID
LEFT JOIN PKS_A_KERTAS_SIASATAN KS ON DHAS_1.A_KERTAS_SIASATAN_ID = KS.A_KERTAS_SIASATAN_ID

LEFT JOIN LATERAL (
	  SELECT o.nama
	  FROM umm_p_daftar_organisasi o
	  WHERE o.p_daftar_organisasi_id IN (
	    SELECT MIN(o2.p_daftar_organisasi_id)
	    FROM umm_p_daftar_organisasi o2
	    --WHERE APP_A_1.id_transaksi = APP_1.id_pengenalan
	    WHERE APP_A_1.P_APLIKASI_ID = DHAS_1.P_APLIKASI_ID
	  )
	  LIMIT 1
	) AS org_nama ON DHAS_1.kod_tgsn IN ('PPF', 'PPJUB', 'PPPK', 'PPSYT')
	

	LEFT JOIN LATERAL (
	  SELECT p.nama_pemohon
	  FROM llg_a_daftar_pelelong p
	  WHERE p.aplikasi_id = DHAS_1.aplikasi_id
	  ORDER BY p.a_daftar_pelelong_id ASC
	  LIMIT 1
	) AS pelelong_nama ON URSN_1.kod = 'PPLBL'
	
	LEFT JOIN LATERAL (
	  SELECT r.nama
	  FROM umm_a_pihak_bkptg r
	  WHERE r.aplikasi_id = DHAS_1.aplikasi_id
	    AND UPPER(r.flag_pemohon) = 'Y'
	  ORDER BY r.a_pihak_bkptg_id ASC
	  LIMIT 1
	) AS bkptg_nama ON TRUE
  	
	WHERE UPPER(DHAS_1.FLAG_TGSN_SISTEM) = 'N'
	AND (DHAS_1.NAMA_PENGGUNA = var_nama_pengguna OR DHAS_1.NAMA_PENGGUNA IS NULL)
	AND (EXISTS (
        SELECT 1 FROM VAR_PERANAN_KOD_PENGGUNA PKP
        WHERE PKP.NAMA_PENGGUNA = DHAS_1.NAMA_PENGGUNA AND PKP.peranan_kod = 'PTG'
    	) OR DHAS_1.PEJABAT_ID IN (SELECT PEJABAT_ID FROM VAR_PEJABAT_TERKAIT) OR DHAS_1.PEJABAT_ID IS NULL
	)

	AND (
		URSN_1.KOD IN (SELECT KOD FROM VAR_URUSAN_KOD_LIST)
		OR URSN_2.KOD IN (SELECT KOD FROM VAR_URUSAN_KOD_LIST)
	)

	AND EXISTS ( 
		SELECT 1
		FROM VAR_PERANAN_KOD_PENGGUNA PKP
		WHERE DHAS_1.PERANAN LIKE '%-' || PKP.PERANAN_KOD || '-%'
	)
	AND (APP_TGSN_1.A_TGSN_ID is null or APP_TGSN_1.A_TGSN_ID is not null )
	--IF 
		AND (
		    var_modul_kod IS NULL 
		    OR DHAS_1.modul = var_modul_kod
			AND (var_modul_kod = 'DFT' AND RJU_1.KOD = var_urusan_mdl_kod)

			or  (var_modul_kod != 'DFT' AND COALESCE(URSN_1.KOD, URSN_2.KOD) = var_urusan_mdl_kod)
		)

	-- END 
	),

VAR_GROUPED_TUGAS AS (
    SELECT
        mq.*,
        ROW_NUMBER() OVER (PARTITION BY ua.no_fail, mq.kod_tgsn ORDER BY mq.tgsn_semasa_id) AS rn
    FROM MAIN_QUERY mq
    LEFT JOIN umm_aplikasi ua ON mq.aplikasi_id = ua.aplikasi_id
    WHERE mq.kod_tgsn IN ('PPBKRPDPJPM', 'PPBKRSDPJPM', 'PPBKRCDPJPM') 
),
VAR_MODUL_PENGGUNA AS (
  SELECT DISTINCT p.nama_pengguna, m.kod AS modul_kod
  FROM pcp_capaian_pengguna cp
  JOIN pcp_pengguna p ON cp.pengguna_id = p.pengguna_id
  JOIN pcp_peranan_modul pm ON cp.peranan_modul_id = pm.peranan_modul_id
  JOIN ind_modul m ON pm.modul_id = m.modul_id
  WHERE p.nama_pengguna IN (var_nama_pengguna) 
    AND m.kod IN ('PNT', 'UAM')
),

VAR_BELUM_TUKAR_GANTI AS (
 SELECT unnest(ARRAY['HMSC', 'HMSTP', 'PRBB', 'OPRBB', 'HDHD', 'HMPV', 'HMV','HMVB','SSHM','SSSC','SW','SA','CRHMB','CSHMB','BETUL','PACT','PKH','PMKMH','PFT','REM','REMITAN'])
),
FINAL_QUERY_V1 AS (
	SELECT * FROM MAIN_QUERY AS DEFAULT_MAIN_PNT
	WHERE EXISTS (
	    SELECT 1
	    FROM VAR_MODUL_PENGGUNA mp
	    WHERE mp.nama_pengguna = DEFAULT_MAIN_PNT.nama_pengguna
	      OR DEFAULT_MAIN_PNT.modul IN ('PNT', 'UAM')
	  )
	AND DEFAULT_MAIN_PNT.kod_tgsn NOT IN ('KD', 'STRKD')
		AND NOT (
		  DEFAULT_MAIN_PNT.modul = 'CON'
		  AND DEFAULT_MAIN_PNT.kod_tgsn IN ('CSK', 'JSK')
		)
	UNION ALL
	SELECT * FROM MAIN_QUERY AS DEFAULT_MAIN
	WHERE DEFAULT_MAIN.KOD_TGSN NOT IN ('KD', 'STRKD')
	AND NOT (
	    DEFAULT_MAIN.MODUL = 'CON' AND 
	    (DEFAULT_MAIN.KOD_TGSN = 'CSK' OR DEFAULT_MAIN.KOD_TGSN = 'JSK')
	)
	AND DEFAULT_MAIN.MODUL NOT IN ('PNT', 'UAM')
	AND NOT (
	    DEFAULT_MAIN.kod_tgsn IN ('KD', 'STRKD')
	    OR (DEFAULT_MAIN.NAMA_PENGGUNA IS NOT NULL AND DEFAULT_MAIN.NAMA_PENGGUNA <> var_nama_pengguna)
	)
--new

--==========
--
	AND NOT (
	    DEFAULT_MAIN.KOD_TGSN = 'PTBUT'
	    AND DEFAULT_MAIN.URUSAN_KOD IN ('PMQFT', 'PMQTFT')
	)
--==========

),

FIANL_QUERY_MERGE as (
	select * FROM FINAL_QUERY_V1 as FN_Q1
	WHERE NOT EXISTS (
		SELECT 1
   		FROM VAR_FILTER_TUGASAN_KOD_SET 
		 WHERE
	      (
	        stgsn_kod = 'PTB'
	        AND FN_Q1.KOD_TGSN LIKE '%' || stgsn_kod || '%'
	      )
			OR (
		    stgsn_kod <> 'PTB'
			  AND FN_Q1.KOD_TGSN = stgsn_kod
			)
	)

 	UNION ALL
	SELECT * from (

		SELECT DISTINCT ON (FN_Q1_v2.KOD_TGSN) FN_Q1_v2.*
		FROM FINAL_QUERY_V1 as FN_Q1_v2
		WHERE EXISTS (
			 SELECT 1
      		FROM VAR_FILTER_TUGASAN_KOD_SET
			where (
					UPPER(FN_Q1_v2.STATUS_PROSES) <> 'GANTUNG'

					AND (
			          (stgsn_kod = 'PTB' AND FN_Q1_v2.KOD_TGSN LIKE '%' || stgsn_kod || '%')
			          OR (stgsn_kod = 'SJR' AND FN_Q1_v2.KOD_TGSN LIKE '%' || stgsn_kod || '%')
			          OR (stgsn_kod = 'CTK_JR' AND FN_Q1_v2.KOD_TGSN LIKE '%' || stgsn_kod || '%')
			          OR (stgsn_kod = 'PJR' AND FN_Q1_v2.KOD_TGSN LIKE '%' || stgsn_kod || '%')
			          OR (
			            stgsn_kod NOT IN ('PTB', 'SJR', 'CTK_JR', 'PJR')
			            AND FN_Q1_v2.KOD_TGSN = stgsn_kod
			          )
			        )
			) order by FN_Q1_v2.KOD_TGSN, FN_Q1_v2.tgsn_semasa_id desc
		) limit 1 
	)

),
VAR_USER_PERANAN AS (
  SELECT 
    LOWER(mdl.kod) AS modul,
    LOWER(sak.kod) AS peranan
  FROM pcp_capaian_pengguna cp
  JOIN pcp_pengguna pg ON cp.pengguna_id = pg.pengguna_id
  JOIN pcp_peranan_modul pm ON cp.peranan_modul_id = pm.peranan_modul_id
  JOIN ind_modul mdl ON pm.modul_id = mdl.modul_id
  JOIN rjk_senarai_ahli_kumpulan sak ON pm.peranan_id = sak.senarai_ahli_kumpulan_id
  WHERE pg.nama_pengguna = var_nama_pengguna
),
FINAL_QUERY AS (
  SELECT * 
  FROM FIANL_QUERY_MERGE AS DEFAULT_MAIN
  WHERE 1=1

	AND 
    (
      var_status_tugasan IS NULL
      OR UPPER(var_status_tugasan) NOT IN ('BARU', 'SEMASA')
      OR (
        UPPER(var_status_tugasan) = 'BARU' AND UPPER(DEFAULT_MAIN.STATUS_TUGASAN) = 'BARU'
      )
      OR (
        UPPER(var_status_tugasan) = 'SEMASA' AND UPPER(DEFAULT_MAIN.STATUS_TUGASAN) = 'DALAM TINDAKAN'
      )
    )
    AND (
    -- Ambil jika bukan PTB dan nama_pengguna tidak kosong
    (
      DEFAULT_MAIN.kod_tgsn NOT ILIKE '%PTB%'
      AND COALESCE(TRIM(DEFAULT_MAIN.nama_pengguna), '') <> ''
    )
    -- Atau: jika PTB / nama kosong, validasi modul dan peranan terhadap VAR_USER_PERANAN
    OR EXISTS (
      SELECT 1
      FROM VAR_USER_PERANAN u
      WHERE LOWER(u.modul) = LOWER(DEFAULT_MAIN.modul)
        AND EXISTS (
          SELECT 1
          FROM unnest(string_to_array(LOWER(DEFAULT_MAIN.peranan), '-')) AS p(peranan)
          WHERE p.peranan = u.peranan
        )
        AND (
          DEFAULT_MAIN.kod_tgsn ILIKE '%PTB%'
          OR COALESCE(TRIM(DEFAULT_MAIN.nama_pengguna), '') = ''
        )
    )
  
    )
    AND NOT (
      DEFAULT_MAIN.id_rujukan_smartbox IS NOT NULL
      AND DEFAULT_MAIN.id_rujukan_smartbox <> ''
      AND DEFAULT_MAIN.kod_tgsn IN ('ISHSB', 'KDSB')
    )

),

VAR_KOD_TUGSAN_BY_PELUPUSAN AS (
SELECT unnest(ARRAY['PYKP', 'SKP', 'SKP2', 'SKP3', 'PKP',
    'PYJKPTD', 'SJKPTD', 'SJKPTD2', 'SJKPTD3', 'PJKPTD', 'CJKPTD',
    'KKJKPTD', 'SKJKPTD', 'PYMMKN', 'SMMKN', 'SMMKN2', 'SMMKN3',
    'PMMKN', 'PSSPTG', 'SDPDT', 'SKMPTG', 'SKMPTG2', 'SKMPTG3',
    'SKMPTG4', 'SKMPTG5', 'PKMPTG', 'CKMPTG', 'SKPPTG', 'SKPPTG2',
    'SKPPTG3', 'SKPPTG4', 'SKPPTG5', 'PKPPTG', 'PYKPMB', 'SKPMB',
    'SKPMB2', 'SKPMB3', 'PSKPMB', 'SKPMBPTG', 'SKPMBPTG2', 'SKPMBPTG3',
    'SKPMBPTG4', 'SKPMBPTG5', 'PKPMBPTG', 'CKPMBPTG', 'PTBUT3', 'PLT',
    'SDS', 'PTBUT4', 'PPM', 'SPM', 'PFI', 'PYKMPTG'])
),
URUSAN_MODUL_PARENT_CTE AS (
  SELECT 
    A.APLIKASI_ID as APP_ID_CTE,
    M.KOD AS URUSAN_MODUL_PARENT
  FROM UMM_APLIKASI A
  LEFT JOIN IND_URSN U ON A.URSN_ID = U.URSN_ID
  LEFT JOIN IND_MODUL M ON U.MODUL_ID = M.MODUL_ID
),


VAR_CONSENT_KOD AS (
    SELECT unnest(ARRAY['PFMMK', 'PPPTG', 'SFMMK', 'SPTPTG', 'KPTG','KTPTG','KCADO','KDO','PDO','STSKP','KPTG2', 'KMB'])
),
CONSENT_FILTER AS (
	SELECT *
	FROM FINAL_QUERY f
	WHERE f.MODUL = 'CON'
	  AND NOT (
	    f.urusan_kod_dashboard = 'KPMP'
	    AND var_kod_negri = '08' -- 11= param
	  )
	  AND f.KOD_TGSN IN (SELECT * FROM VAR_CONSENT_KOD) 
),


CONSENT_FILTER_ONE as (
	SELECT 
	CON.tgsn_semasa_id,
NULL::timestamp as trkh_pnrman,
CON.modul,
CON.id_hkmlk,
CON.no_resit,
CON.locked_by,
CON.locked_date,
CON.peranan,
CON.kod_tgsn,
CON.id_tgsn,
CON.tgsn_perihal,
CON.nama_pengguna,
CON.trkh_tetap,
CON.trkh_piagam,
CON.aplikasi_id,
CON.app_id,
CON.rangkaian_id,
CON.id_pengenalan,
CON.flag_integrasi,
CON.status_keputusan,
CON.fail_induk,
CON.status_proses,
CON.urusan_kod,
CON.no_rujukan,
CON.nama_pendek,
CON.pejabat_kod,
CON.id_penghantaran,
CON.app_a_tgsn_id,
CON.nama_pejabat_pendek,
CON.tarikh_siasatan_string,
CON.id_rujukan_smartbox,
CON.dhas_1_trkh_kpi,
CON.minit_kpi,
CON.show_id_hakmilik,
CON.no_hakmilik_baru,
CON.trkh_kpi,
CON.status_tugasan,
CON.show_kpi,
'-' as tarikh_penerimaan_string,
'-' as tarikh_dan_masa_luput_string,
CON.tarikh_dan_masa_luput,
CON.tarikh_piagam_string,
CON.tarikh_mula_string,
CON.is_filter_tugasan,
CON.tarikh_kpi,
'' as no_hakmilik_dashboard,
CON.aplikasi_no_permohonan,
'' AS no_resit_dashboard,
'' as urusan_kod_dashboard,
id_permohonan_dashboard,
CON.nama_pemohon,
'' as no_fail_pemohon

	FROM CONSENT_FILTER CON
--	ORDER BY CON.tgsn_semasa_id
--	LIMIT 1
),

FINAL_FILTER_CON as (
SELECT *
	FROM FINAL_QUERY a
--	WHERE a.modul <> 'CON'

	UNION ALL

	SELECT * FROM CONSENT_FILTER_ONE
),


FINAL_FILTER_ALL  AS (
	SELECT * FROM FINAL_FILTER_CON AS FQ
	
	WHERE 1=1
	AND NOT (
		FQ.MODUL = 'PFIKM'   
		OR FQ.ID_TGSN IN (SELECT ID_TGSN_PELUPUSAN_PENGGUNA_FILTER FROM VAR_PELUPUSAN_TUGASAN_FILTERED)	
  	)
	AND NOT (FQ.modul = 'UAM' AND FQ.URUSAN_KOD = 'BIO')

    AND NOT (
      COALESCE(TRIM(FQ.locked_by), '') <> ''
      AND LOWER(FQ.locked_by) <> LOWER(var_nama_pengguna)
      AND FQ.locked_date IS NOT NULL
      AND FQ.locked_date > NOW() - INTERVAL '30 minutes'
    )
	 
),

FINAL_FILTER_ALL_V2 as (
	SELECT * FROM FINAL_FILTER_ALL
),




FINAL_RESULT AS (
	SELECT * ,
	CASE 
	  WHEN EXISTS (
	    SELECT 1
	    FROM UMM_PERTANYAAN p
	    JOIN RJK_SENARAI_AHLI_KUMPULAN k ON p.STATUS_ID = k.SENARAI_AHLI_KUMPULAN_ID
	    JOIN UMM_APLIKASI a ON p.APLIKASI_ID = a.APLIKASI_ID
	    JOIN IND_URSN u ON a.URSN_ID = u.URSN_ID
	    WHERE p.A_TGSN_ID = FQ.APP_A_TGSN_ID
	      AND k.KOD != 'SELESAI'
	      AND u.TEMPOH_KUIRI ~ '^[0-9]+$'
	      AND DATE_PART('day', CURRENT_DATE - p.CREATED_DATE) > u.TEMPOH_KUIRI::INT
	  )
	  THEN ' (Pertanyaan) - Telah Melebihi Tempoh Kuiri'
	
	  WHEN EXISTS (
	    SELECT 1
	    FROM UMM_PERTANYAAN p
	    JOIN RJK_SENARAI_AHLI_KUMPULAN k ON p.STATUS_ID = k.SENARAI_AHLI_KUMPULAN_ID
	    WHERE p.A_TGSN_ID = FQ.APP_A_TGSN_ID
	      AND k.KOD != 'SELESAI'
	  )
	  THEN ' (Pertanyaan)'
	
	  ELSE NULL
	END AS pertanyaan_keterangan,


	--	color and flag
	CASE 
	    WHEN (
	        CASE
	            WHEN FQ.MINIT_KPI IS NOT NULL 
	                 AND FQ.TRKH_PNRMAN IS NOT NULL 
	                 AND FQ.DHAS_1_TRKH_KPI IS NULL
	            THEN FQ.TRKH_PNRMAN + (FQ.MINIT_KPI || ' minutes')::INTERVAL
	            ELSE FQ.DHAS_1_TRKH_KPI
	        END
	    ) IS NOT NULL 
	    AND (
	        CASE
	            WHEN FQ.MINIT_KPI IS NOT NULL 
	                 AND FQ.TRKH_PNRMAN IS NOT NULL 
	                 AND FQ.DHAS_1_TRKH_KPI IS NULL
	            THEN FQ.TRKH_PNRMAN + (FQ.MINIT_KPI || ' minutes')::INTERVAL
	            ELSE FQ.DHAS_1_TRKH_KPI
	        END
	    ) < CURRENT_DATE
	THEN 'TUNGGAK'
	ELSE NULL
	END AS STATUS,
	CASE 
	    WHEN (
	        CASE
	            WHEN FQ.MINIT_KPI IS NOT NULL 
	                 AND FQ.TRKH_PNRMAN IS NOT NULL 
	                 AND FQ.TRKH_KPI IS NULL
	            THEN FQ.TRKH_PNRMAN + (FQ.MINIT_KPI || ' minutes')::INTERVAL
	            ELSE FQ.DHAS_1_TRKH_KPI
	        END
	    ) IS NOT NULL 
	    AND (
	        CASE
	            WHEN FQ.MINIT_KPI IS NOT NULL 
	                 AND FQ.TRKH_PNRMAN IS NOT NULL 
	                 AND FQ.TRKH_KPI IS NULL
	            THEN FQ.TRKH_PNRMAN + (FQ.MINIT_KPI || ' minutes')::INTERVAL
	            ELSE FQ.DHAS_1_TRKH_KPI
	        END
	    ) < CURRENT_DATE
	THEN 'red' -- warna merah sebagai contoh
	ELSE NULL
	END AS COLOR,


	CASE
	    WHEN NOT FQ.SHOW_KPI THEN 'Hijau'
	    WHEN FQ.TARIKH_DAN_MASA_LUPUT_STRING IS NULL OR FQ.TARIKH_DAN_MASA_LUPUT_STRING = '-' THEN 'Hijau'
	    WHEN FQ.TRKH_TETAP IS NULL THEN
	        CASE
	            WHEN TO_DATE(FQ.TARIKH_DAN_MASA_LUPUT_STRING, 'DD/MM/YYYY') >= CURRENT_DATE THEN 'Hijau'
	            ELSE 'Merah'
	        END
	    WHEN TO_DATE(FQ.TARIKH_DAN_MASA_LUPUT_STRING, 'DD/MM/YYYY') <= FQ.TRKH_TETAP::DATE THEN 'Hijau'
	    ELSE 'Merah'
	END AS FLAG_STATUS,

	--end color and flag

CASE
  WHEN FQ.KOD_TGSN = 'ISH' THEN TRUE
 WHEN FQ.KOD_TGSN = 'KDO' THEN TRUE
  WHEN FQ.MODUL = 'KKS' THEN TRUE
  WHEN FQ.MODUL = 'PNT' AND URUSAN_MODUL_PARENT = 'KKS' THEN TRUE
  WHEN EXISTS (
    SELECT 1
    FROM UNNEST(STRING_TO_ARRAY(FQ.URUSAN_KOD_DASHBOARD, '<BR />')) AS URSN
    WHERE URSN IN (SELECT * FROM VAR_BELUM_TUKAR_GANTI)
  ) THEN TRUE
  WHEN EXISTS (
    SELECT 1
    FROM UNNEST(STRING_TO_ARRAY(FQ.URUSAN_KOD_DASHBOARD, '<BR />')) AS URSN
    WHERE URSN IS NOT NULL
      AND (
        URSN NOT IN (SELECT * FROM VAR_BELUM_TUKAR_GANTI)
        OR URSN IN (SELECT * FROM VAR_ALSAN_TUKARGANTI_KOD_SET_BATAL)
      )
or (
    (
      SELECT COUNT(*) FROM DFT_A_MOHON_HKMLK HM
      JOIN IND_MKLMT_HKMLK MH ON MH.mklmt_hkmlk_id = HM.ID_HKMLK
      JOIN rjk_senarai_ahli_kumpulan o ON o.senarai_ahli_kumpulan_id = MH.status_hkmlk_id
      WHERE HM.APLIKASI_ID = FQ.APLIKASI_ID AND o.kod = 'STAHMBT'
    ) = (
      SELECT COUNT(*) FROM DFT_A_MOHON_HKMLK HM
      WHERE HM.APLIKASI_ID = FQ.APLIKASI_ID
    )
    or NOT EXISTS (
      SELECT 1
      FROM DFT_A_MOHON_HKMLK HM
      JOIN IND_MKLMT_HKMLK MH ON MH.mklmt_hkmlk_id = HM.ID_HKMLK
      JOIN RJK_SENARAI_AHLI_KUMPULAN o ON o.senarai_ahli_kumpulan_id = MH.status_hkmlk_id
      WHERE HM.APLIKASI_ID = FQ.APLIKASI_ID
      AND o.kod = 'STAHDFT'
      AND EXISTS (
        SELECT 1 FROM IND_VERSI_DHD TG WHERE TG.hkmlk_id = HM.ID_HKMLK
      )
    )
  )
  )
  
  THEN TRUE
  ELSE FALSE
END AS IS_HAKMILIK_BELUM_TUKARGANTI,



CASE 
  WHEN FQ.TARIKH_DAN_MASA_LUPUT IS NULL THEN '-' 

  WHEN FQ.TARIKH_DAN_MASA_LUPUT <= NOW() THEN '0 Hari'

  WHEN DATE_PART('month', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 THEN
    TRIM(BOTH FROM CONCAT_WS(' ',
      CASE 
        WHEN DATE_PART('month', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('month', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Bulan' 
      END,
      CASE 
        WHEN DATE_PART('day', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('day', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Hari' 
      END,
      CASE 
        WHEN DATE_PART('hour', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('hour', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Jam' 
      END,
      CASE 
        WHEN DATE_PART('minute', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('minute', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Minit' 
      END
    ))

  ELSE
    TRIM(BOTH FROM CONCAT_WS(' ',
      CASE 
        WHEN DATE_PART('day', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('day', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Hari' 
      END,
      CASE 
        WHEN DATE_PART('hour', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('hour', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Jam' 
      END,
      CASE 
        WHEN DATE_PART('minute', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('minute', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Minit' 
      END
    ))
END AS BAKI_MASA



	
FROM FINAL_FILTER_ALL_V2 AS FQ 
LEFT JOIN URUSAN_MODUL_PARENT_CTE UMP ON UMP.APP_ID_CTE = FQ.APP_ID
where UPPER(FQ.STATUS_TUGASAN) <> 'SELESAI' 

),



 rangkaian_merged AS (
    SELECT 
      MAX(fd.TGSN_SEMASA_ID)::BIGINT AS ID,
      MAX(fd.TRKH_PNRMAN) AS TRKH_PEN,
      MAX(fd.TARIKH_PENERIMAAN_STRING) AS TARIKH_PENERIMAAN_STRING,
      MAX(fd.TARIKH_DAN_MASA_LUPUT_STRING) AS TARIKH_DAN_MASA_LUPUT_STRING,
      STRING_AGG(DISTINCT  fd.ID_HKMLK, '<br />') AS no_hakmilik,
      ra.RANGKAIAN_ID::TEXT AS rangkaian_id_merged,
      fd.kod_tgsn::TEXT,
      STRING_AGG( fd.ID_PERMOHONAN_DASHBOARD ::TEXT, '<br />') AS id_permohonan,
      STRING_AGG(fd.URUSAN_KOD_DASHBOARD ::TEXT, '<br />') AS urusan,
      MAX(fd.NO_FAIL_PEMOHON) AS NO_FAIL_PEMOHON,
      STRING_AGG(DISTINCT  fd.NO_RESIT_DASHBOARD :: TEXT, '<br />') AS no_resit,
	  max(fd.TGSN_PERIHAL) as tugas,
      MAX(fd.NAMA_PEMOHON) AS NAMA_PEMOHON,
      MAX(fd.NAMA_PEJABAT_PENDEK) AS PEJABAT,
      MAX(fd.ID_PENGHANTARAN) AS ID_PENYAMPAIAN,
		MAX(fd.APP_A_TGSN_ID ) as id_APP_A_TGSN,
		max(fd.APLIKASI_ID),
	MAX(fd.pertanyaan_keterangan) AS pertanyaan_keterangan,
	MAX(fd.TARIKH_SIASATAN_STRING) as TARIKH_SIASATAN_STRING,
	MAX(fd.STATUS) as ROW_STATUS,
	MAX(fd.COLOR) as ROW_COLOR,
	MAX(fd.FLAG_STATUS) as FLAG_STATUS,
	(MAX(CASE WHEN fd.IS_HAKMILIK_BELUM_TUKARGANTI THEN 1 ELSE 0 END) = 1),
	MAX(fd.BAKI_MASA) as BAKI_MASA, 
	max(fd.NO_HAKMILIK_BARU) as NO_HAKMILIK_BARU,
	MAX(fd.MODUL) as MODUL

    FROM FINAL_RESULT fd
    JOIN UMM_APLIKASI ra ON fd.APLIKASI_ID = ra.APLIKASI_ID
    WHERE ra.RANGKAIAN_ID IS NOT NULL
      AND fd.kod_tgsn <> 'IMH'
    GROUP BY ra.RANGKAIAN_ID, fd.kod_tgsn
  ),

  remaining_rows AS (
    SELECT 
      fd.TGSN_SEMASA_ID::BIGINT AS ID,
      fd.TRKH_PNRMAN AS TRKH_PEN,
      fd.TARIKH_PENERIMAAN_STRING,
      fd.TARIKH_DAN_MASA_LUPUT_STRING,
      fd.ID_HKMLK AS no_hakmilik,
      NULL::TEXT AS rangkaian_id_merged,
      fd.kod_tgsn::TEXT,
      fd.ID_PERMOHONAN_DASHBOARD AS id_permohonan,
      fd.URUSAN_KOD_DASHBOARD AS urusan,
      fd.NO_FAIL_PEMOHON AS NO_FAIL_PEMOHON,
      fd.NO_RESIT_DASHBOARD AS no_resit,
		fd.TGSN_PERIHAL as tugas,
      fd.NAMA_PEMOHON AS NAMA_PEMOHON,
      fd.NAMA_PEJABAT_PENDEK AS PEJABAT,
      fd.ID_PENGHANTARAN AS ID_PENYAMPAIAN,
	fd.APP_A_TGSN_ID as id_APP_A_TGSN,
	fd.APLIKASI_ID,
	
	fd.pertanyaan_keterangan,
	fd.TARIKH_SIASATAN_STRING as TARIKH_SIASATAN_STRING,
	fd.STATUS as ROW_STATUS,
	fd.COLOR as ROW_COLOR,
	fd.FLAG_STATUS as FLAG_STATUS, 
	fd.IS_HAKMILIK_BELUM_TUKARGANTI,
	fd.BAKI_MASA as BAKI_MASA,
	fd.NO_HAKMILIK_BARU as NO_HAKMILIK_BARU,
	fd.MODUL as MODUL

    FROM FINAL_RESULT fd
    LEFT JOIN UMM_APLIKASI ra ON fd.APLIKASI_ID = ra.APLIKASI_ID
    
--	tetsing
--	WHERE ra.RANGKAIAN_ID IS NULL
--       OR fd.kod_tgsn = 'IMH'
  ),

--   FINAL_V2 AS (
--     SELECT * FROM rangkaian_merged
--     UNION ALL
--     SELECT * FROM remaining_rows
--   ),
FINAL_V2 AS (
    SELECT DISTINCT ON (merged.id) merged.*
    FROM (
        SELECT * FROM rangkaian_merged
        UNION ALL
        SELECT * FROM remaining_rows
    ) merged

    WHERE (
        var_modul_kod IS NULL
        OR (
            merged.modul = var_modul_kod
            AND (
                var_modul_kod <> 'DFT'
                OR (
                    var_modul_kod = 'DFT'
                    AND merged.id IN (
                        SELECT 
                            d.tgsn_semasa_id
                        FROM UMM_TGSN_SEMASA d
                        INNER JOIN UMM_APLIKASI a ON d.aplikasi_id = a.APLIKASI_ID
                        INNER JOIN IND_URSN u ON a.URSN_ID = u.URSN_ID
                        INNER JOIN RJK_JNS_URSN j ON u.JNS_URSN_ID = j.JNS_URSN_ID
                        INNER JOIN IND_MODUL m ON u.MODUL_ID = m.MODUL_ID
                        WHERE 
                            m.kod = var_modul_kod
                            AND d.nama_pengguna = var_nama_pengguna
                            AND d.FLAG_TGSN_SISTEM = 'N'
                            AND d.pejabat_id = var_pejabat_id
                            AND d.TGSN_PERIHAL NOT IN ('Kutipan Dokumen', 'Imbasan Dokumen Hakmilik Batal')
                            AND a.status_keputusan <> 'Batal'
                            AND j.kod = var_urusan_mdl_kod
                    )
                )
            )
        )
    )

    ORDER BY merged.id, merged.trkh_pen DESC
),


  params AS (
    SELECT trim(c.col) AS fcol, trim(v.val) AS fval
    FROM unnest(string_to_array(var_filter_colum, ',')) WITH ORDINALITY AS c(col, idx)
    JOIN unnest(string_to_array(var_filter_val, '||')) WITH ORDINALITY AS v(val, idx2)
      ON c.idx = v.idx2
)


SELECT *
FROM FINAL_V2 v2
WHERE
    -- Jika tidak ada filter sama sekali, kembalikan semua
    NOT EXISTS (SELECT 1 FROM params)
    
    -- Jika ada filter, cocokkan semua kolom
    OR (
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TARIKH_PENERIMAAN_STRING')
         OR v2.TARIKH_PENERIMAAN_STRING ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TARIKH_PENERIMAAN_STRING')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TARIKH_DAN_MASA_LUPUT_STRING')
         OR v2.TARIKH_DAN_MASA_LUPUT_STRING ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TARIKH_DAN_MASA_LUPUT_STRING')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TARIKH_SIASATAN_STRING')
         OR v2.TARIKH_SIASATAN_STRING ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TARIKH_SIASATAN_STRING')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'NO_HAKMILIK')
         OR v2.NO_HAKMILIK ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'NO_HAKMILIK')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'ID_PERMOHONAN')
         OR v2.ID_PERMOHONAN ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'ID_PERMOHONAN')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'NO_FAIL_PEMOHON')
         OR v2.NO_FAIL_PEMOHON ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'NO_FAIL_PEMOHON')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'NO_RESIT')
         OR v2.NO_RESIT ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'NO_RESIT')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'URUSAN')
         OR v2.URUSAN ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'URUSAN')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'NAMA_PEMOHON')
         OR v2.NAMA_PEMOHON ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'NAMA_PEMOHON')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'PERTANYAAN_KETERANGAN')
         OR v2.PERTANYAAN_KETERANGAN ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'PERTANYAAN_KETERANGAN')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TUGAS')
         OR v2.TUGAS ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TUGAS')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'PEJABAT')
         OR v2.PEJABAT ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'PEJABAT')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'ID_PENYAMPAIAN')
         OR v2.ID_PENYAMPAIAN ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'ID_PENYAMPAIAN')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TUGASAN')
         OR v2.TUGAS ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TUGASAN')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'FLAG_STATUS')
         OR v2.FLAG_STATUS ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'FLAG_STATUS')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'BAKI_MASA')
         OR v2.BAKI_MASA ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'BAKI_MASA')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TUGAS_AND_PERTANYAAN')
         OR (v2.TUGAS ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TUGAS_AND_PERTANYAAN'))
             OR v2.PERTANYAAN_KETERANGAN ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TUGAS_AND_PERTANYAAN'))))
    )
	
 ORDER BY
  -- Default fallback kalau tidak ada kolom urutan diberikan
  CASE 
    WHEN var_sort_colum IS NULL THEN V2.TARIKH_PENERIMAAN_STRING 
  END ASC,

  -- Jika kolom urutan diberikan, gunakan CASE berdasarkan nama kolom dan tipe sort
  CASE WHEN var_sort_colum = 'TARIKH_PENERIMAAN_STRING' AND var_sort_type = 'ASC' THEN V2.TRKH_PEN END ASC,
  CASE WHEN var_sort_colum = 'TARIKH_PENERIMAAN_STRING' AND var_sort_type = 'DESC' THEN V2.TRKH_PEN END DESC,
  
  CASE WHEN var_sort_colum = 'TARIKH_DAN_MASA_LUPUT_STRING' AND var_sort_type = 'ASC' THEN V2.TARIKH_DAN_MASA_LUPUT_STRING END ASC,
  CASE WHEN var_sort_colum = 'TARIKH_DAN_MASA_LUPUT_STRING' AND var_sort_type = 'DESC' THEN V2.TARIKH_DAN_MASA_LUPUT_STRING END DESC,

  CASE WHEN var_sort_colum = 'TARIKH_SIASATAN_STRING' AND var_sort_type = 'ASC' THEN V2.TARIKH_SIASATAN_STRING END ASC,
  CASE WHEN var_sort_colum = 'TARIKH_SIASATAN_STRING' AND var_sort_type = 'DESC' THEN V2.TARIKH_SIASATAN_STRING END DESC,

  CASE WHEN var_sort_colum = 'NO_HAKMILIK' AND var_sort_type = 'ASC' THEN V2.NO_HAKMILIK END ASC,
  CASE WHEN var_sort_colum = 'NO_HAKMILIK' AND var_sort_type = 'DESC' THEN V2.NO_HAKMILIK END DESC,

  CASE WHEN var_sort_colum = 'KOD_TGSN' AND var_sort_type = 'ASC' THEN V2.KOD_TGSN END ASC,
  CASE WHEN var_sort_colum = 'KOD_TGSN' AND var_sort_type = 'DESC' THEN V2.KOD_TGSN END DESC,

  CASE WHEN var_sort_colum = 'ID_PERMOHONAN' AND var_sort_type = 'ASC' THEN V2.ID_PERMOHONAN END ASC,
  CASE WHEN var_sort_colum = 'ID_PERMOHONAN' AND var_sort_type = 'DESC' THEN V2.ID_PERMOHONAN END DESC,

  CASE WHEN var_sort_colum = 'URUSAN' AND var_sort_type = 'ASC' THEN V2.URUSAN END ASC,
  CASE WHEN var_sort_colum = 'URUSAN' AND var_sort_type = 'DESC' THEN V2.URUSAN END DESC,

  CASE WHEN var_sort_colum = 'NO_FAIL_PEMOHON' AND var_sort_type = 'ASC' THEN V2.NO_FAIL_PEMOHON END ASC,
  CASE WHEN var_sort_colum = 'NO_FAIL_PEMOHON' AND var_sort_type = 'DESC' THEN V2.NO_FAIL_PEMOHON END DESC,

  CASE WHEN var_sort_colum = 'NO_RESIT' AND var_sort_type = 'ASC' THEN V2.NO_RESIT END ASC,
  CASE WHEN var_sort_colum = 'NO_RESIT' AND var_sort_type = 'DESC' THEN V2.NO_RESIT END DESC,

  CASE WHEN var_sort_colum = 'TUGAS' AND var_sort_type = 'ASC' THEN V2.TUGAS END ASC,
  CASE WHEN var_sort_colum = 'TUGAS' AND var_sort_type = 'DESC' THEN V2.TUGAS END DESC,

  CASE WHEN var_sort_colum = 'NAMA_PEMOHON' AND var_sort_type = 'ASC' THEN V2.NAMA_PEMOHON END ASC,
  CASE WHEN var_sort_colum = 'NAMA_PEMOHON' AND var_sort_type = 'DESC' THEN V2.NAMA_PEMOHON END DESC,

  CASE WHEN var_sort_colum = 'PEJABAT' AND var_sort_type = 'ASC' THEN V2.PEJABAT END ASC,
  CASE WHEN var_sort_colum = 'PEJABAT' AND var_sort_type = 'DESC' THEN V2.PEJABAT END DESC,

  CASE WHEN var_sort_colum = 'PERTANYAAN_KETERANGAN' AND var_sort_type = 'ASC' THEN V2.PERTANYAAN_KETERANGAN END ASC,
  CASE WHEN var_sort_colum = 'PERTANYAAN_KETERANGAN' AND var_sort_type = 'DESC' THEN V2.PERTANYAAN_KETERANGAN END DESC,

  CASE WHEN var_sort_colum = 'ID_PENYAMPAIAN' AND var_sort_type = 'ASC' THEN V2.ID_PENYAMPAIAN END ASC,
  CASE WHEN var_sort_colum = 'ID_PENYAMPAIAN' AND var_sort_type = 'DESC' THEN V2.ID_PENYAMPAIAN END DESC,

	CASE WHEN var_sort_colum = 'BAKI_MASA' AND var_sort_type = 'ASC' THEN V2.BAKI_MASA END ASC,
  CASE WHEN var_sort_colum = 'BAKI_MASA' AND var_sort_type = 'DESC' THEN V2.BAKI_MASA END DESC,


  CASE WHEN var_sort_colum = 'TUGAS_AND_PERTANYAAN' AND var_sort_type = 'ASC' THEN V2.TUGAS END ASC,
  CASE WHEN var_sort_colum = 'TUGAS_AND_PERTANYAAN' AND var_sort_type = 'DESC' THEN V2.TUGAS END DESC



	LIMIT CASE WHEN NOT var_export AND var_limit IS NOT NULL THEN var_limit ELSE NULL 
	END
	OFFSET CASE WHEN NOT var_export AND var_offset IS NOT NULL THEN var_offset ELSE 0 
	END;


END;
$function$
;

-- DROP FUNCTION et_main_uat.get_dashboard_by_pengguna_test_2(numeric, numeric, _text, text, numeric, text, text, text, text, bool, text, text, text, text);

CREATE OR REPLACE FUNCTION et_main_uat.get_dashboard_by_pengguna_test_2(var_limit numeric DEFAULT NULL::numeric, var_offset numeric DEFAULT NULL::numeric, var_urusan_kod_list text[], var_nama_pengguna text DEFAULT NULL::text, var_pejabat_id numeric DEFAULT NULL::numeric, var_modul_kod text DEFAULT NULL::text, var_urusan_mdl_kod text DEFAULT NULL::text, var_status_tugasan text DEFAULT NULL::text, var_kod_negri text DEFAULT NULL::text, var_export boolean DEFAULT false, var_sort_colum text DEFAULT NULL::text, var_sort_type text DEFAULT NULL::text, var_filter_colum text DEFAULT NULL::text, var_filter_val text DEFAULT NULL::text)
 RETURNS TABLE(id bigint, trkh_pen timestamp without time zone, tarikh_penerimaan_string text, tarikh_dan_masa_luput_string text, no_hakmilik text, rangkaian_id_merged text, kod_tgsn text, id_permohonan text, urusan text, no_fail_pemohon text, no_resit text, tugas text, nama_pemohon text, pejabat text, id_penyampaian text, id_app_a_tgsn numeric, id_app_aplikasi numeric, pertanyaan_keterangan text, tarikh_siasatan_string text, row_status text, row_color text, flag_status text, is_hakmilik_belum_tukarganti boolean, baki_masa text, no_hakmilik_baru text, modul text)
 LANGUAGE plpgsql
AS $function$
BEGIN
  RETURN QUERY
WITH VAR_URUSAN_KOD_LIST AS (
    SELECT UNNEST(var_urusan_kod_list) AS KOD
  ),
VAR_PERANAN_KOD_PENGGUNA AS (
  SELECT DISTINCT PP.NAMA_PENGGUNA, RM.KOD AS PERANAN_KOD
  FROM PCP_CAPAIAN_PENGGUNA CP
  JOIN PCP_PENGGUNA PP ON CP.PENGGUNA_ID = PP.PENGGUNA_ID
  JOIN PCP_PERANAN_MODUL PM ON CP.PERANAN_MODUL_ID = PM.PERANAN_MODUL_ID
  JOIN RJK_SENARAI_AHLI_KUMPULAN RM ON PM.PERANAN_ID = RM.SENARAI_AHLI_KUMPULAN_ID
  WHERE PP.NAMA_PENGGUNA IN (var_nama_pengguna)
),
VAR_DAERAH_PENGGUNA AS (
    SELECT DISTINCT DAERAH_ID
    FROM IND_PEJABAT AS IP
    WHERE PEJABAT_ID IN (var_pejabat_id)
),
VAR_PEJABAT_TERKAIT AS (
    SELECT DISTINCT PEJABAT_ID
    FROM IND_PEJABAT AS IP
    WHERE DAERAH_ID IN (SELECT DAERAH_ID FROM VAR_DAERAH_PENGGUNA)
),
VAR_FILTER_TUGASAN_KOD_SET AS (
	SELECT UNNEST(ARRAY['PPBKRPJPM', 'PPBKRKPJPM', 'PTB', 'SJR',
    'PJR', 'CTK_JR', 'PMMP6PTB2', 'PPBBPTB2',
    'PPHSYBPTB2', 'PKJR', 'PKJRPP']) as stgsn_kod
),

VAR_PELUPUSAN_TUGASAN_FILTERED AS (
  SELECT ID_TGSN AS ID_TGSN_PELUPUSAN_PENGGUNA_FILTER
  FROM (
    SELECT A.ID_TGSN,
        ROW_NUMBER() OVER (
            PARTITION BY COALESCE(C.kod, E.kod), A.ID_TGSN
            ORDER BY A.ID_TGSN
    ) AS RN
    FROM UMM_TGSN_SEMASA A
    LEFT JOIN UMM_APLIKASI B ON B.APLIKASI_ID = A.APLIKASI_ID
    LEFT JOIN IND_URSN C ON C.URSN_ID = B.URSN_ID
    LEFT JOIN UMM_P_APLIKASI D ON D.APLIKASI_ID = A.APLIKASI_ID
    LEFT JOIN IND_URSN E ON E.URSN_ID = D.URSN_ID
    WHERE A.MODUL = 'PLP'
      AND A.KOD_TGSN = 'FPIKM'
      AND UPPER(A.FLAG_TGSN_SISTEM) = 'N'
  ) A
  WHERE RN = 1
),
VAR_PEJABAT_PERANAN_MAP AS (
  SELECT * FROM (VALUES
    ('TRG', ARRAY['PTG', 'TPTG', 'KPP']),
    ('PRK', ARRAY['PTG', 'KPP']),
    ('SEL', ARRAY['PTG', 'TPTG'])
  ) AS T (KOD_PEJABAT, PERANANS)
),
VAR_PLP_TUGASAN_KOD_SET AS (
    SELECT unnest(ARRAY['PDKM', 'SDKM', 'SDKM2', 'SDKM3', 'PPKM', 'CKM', 'CKMPPLN'])
),
VAR_ALSAN_TUKARGANTI_KOD_SET AS (
    SELECT unnest(ARRAY['KMPP', 'HMSC', 'HMSTP', 'PRBB', 'OPRBB', 'HDHD', 'HMPV', 'HMV', 'HMVB',
            'SSHM', 'SSSC', 'SW', 'SA', 'CRHMB', 'CSHMB', 'BETUL', 'PACT', 'PKH', 'PMKMH', 'PFT', 'REM', 'REMITAN'])
),
VAR_GROUP_BY_NO_FAIL_TUGASAN_KOD_SET AS (
    SELECT unnest(ARRAY['PPBKRPDPJPM', 'PPBKRSDPJPM', 'PPBKRCDPJPM'])
),

VAR_ALSAN_TUKARGANTI_KOD_SET_BATAL AS (
    SELECT unnest(ARRAY['HDHK', 'HPLN','PMKMH','HSSTB','HKSSS'])
),
VAR_NO_HAK_MILIK_BARU AS (
    SELECT
        mohon.APLIKASI_ID,
        STRING_AGG(mohon.id_hkmlk, '<br>') AS NO_HAKMILIK_BARU
    FROM dft_A_MOHON_HKMLK mohon
    JOIN UMM_APLIKASI appl ON appl.APLIKASI_ID = mohon.APLIKASI_ID
    JOIN IND_URSN urusan ON appl.URSN_ID = urusan.URSN_ID
    JOIN rjk_jns_ursn jenis ON jenis.jns_ursn_id = urusan.jns_ursn_id
    WHERE mohon.id_hkmlk IS NOT NULL
      AND jenis.KOD = 'MH'
    GROUP BY mohon.APLIKASI_ID
),
MAIN_QUERY AS (
	SELECT
  	DHAS_1.TGSN_SEMASA_ID,
	DHAS_1.TRKH_PNRMAN,
	MDL_1.KOD as MODUL,
	DHAS_1.ID_HKMLK,
	DHAS_1.NO_RESIT,
	DHAS_1.LOCKED_BY,
	DHAS_1.LOCKED_DATE,
	DHAS_1.PERANAN,
	DHAS_1.KOD_TGSN,
	DHAS_1.ID_TGSN,
	DHAS_1.TGSN_PERIHAL,
	DHAS_1.NAMA_PENGGUNA,
	APP_TGSN_1.TRKH_TETAP,
	APP_1.TRKH_PIAGAM,
	APP_1.APLIKASI_ID,
	APP_1.APLIKASI_ID as APP_ID,
	APP_1.RANGKAIAN_ID,
	APP_1.ID_PENGENALAN,
	APP_1.FLAG_INTEGRASI,
	APP_1.STATUS_KEPUTUSAN,
	APP_1.FAIL_INDUK,
	COALESCE(APP_1.STATUS_PROSES, SNR_1.NAMA) AS STATUS_PROSES,
    COALESCE(URSN_1.KOD, URSN_2.KOD) AS URUSAN_KOD,
    COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI) AS NO_RUJUKAN,
	IPJ_1.NAMA_PENDEK,
	IPJ_1.KOD AS PEJABAT_KOD,
	HNTR_1.ID_PENGHANTARAN,
	DHAS_1.a_tgsn_id as APP_A_TGSN_ID,
	IPJ_1.NAMA_PENDEK as NAMA_PEJABAT_PENDEK,
	TO_CHAR(MLS.TRKH_SIASATAN, 'DD/MM/YYYY') AS TARIKH_SIASATAN_STRING,
	APP_1.ID_RUJUKAN_SMARTBOX,
	DHAS_1.TRKH_KPI AS DHAS_1_TRKH_KPI,
	ITG_1.MINIT_KPI,
	CASE
      WHEN URSN_1.KOD = 'PSBS' AND DHAS_1.TGSN_PERIHAL = 'Penyediaan Fail Induk Kertas Mesyuarat' THEN FALSE
      ELSE TRUE
    END AS SHOW_ID_HAKMILIK,
	(
      SELECT STRING_AGG(mohon.id_hkmlk, '<br>')
      FROM dft_A_MOHON_HKMLK mohon
      JOIN UMM_APLIKASI appl ON appl.APLIKASI_ID = mohon.APLIKASI_ID
      JOIN IND_URSN urusan ON appl.URSN_ID = urusan.URSN_ID
      JOIN rjk_jns_ursn jenis ON jenis.jns_ursn_id = urusan.jns_ursn_id
      WHERE mohon.APLIKASI_ID = DHAS_1.APLIKASI_ID
        AND mohon.id_hkmlk IS NOT NULL
        AND jenis.KOD = CAST('MH' AS VARCHAR)
    ) AS NO_HAKMILIK_BARU,

	CASE
		WHEN DHAS_1.TRKH_KPI IS NULL
		     AND ITG_1.MINIT_KPI IS NOT NULL
		     AND DHAS_1.TRKH_PNRMAN IS NOT NULL
		THEN DHAS_1.TRKH_PNRMAN + (ITG_1.MINIT_KPI || ' minutes')::INTERVAL
		ELSE DHAS_1.TRKH_KPI
	END AS TRKH_KPI,
	CASE
		WHEN APP_TGSN_1.STATUS_TUGASAN IS NULL OR DHAS_1.TGSN_PERIHAL = 'Pengagihan Tugasan Baru'
		THEN 'Baru'
		ELSE APP_TGSN_1.STATUS_TUGASAN
	END AS STATUS_TUGASAN,

	CASE
		WHEN ITG_1.MINIT_KPI IS NOT NULL THEN TRUE
		ELSE FALSE
	END AS SHOW_KPI,
	CASE
    WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL
         AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
              OR DHAS_1.KOD_TGSN LIKE '%PTB%')
    THEN '-'
    ELSE TO_CHAR(DHAS_1.TRKH_PNRMAN, 'DD/MM/YYYY')
	END AS TARIKH_PENERIMAAN_STRING,

	CASE

		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL
			AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
				OR DHAS_1.KOD_TGSN LIKE '%PTB%')
		THEN '-'

		ELSE TO_CHAR(
			CASE
			WHEN ITG_1.MINIT_KPI IS NOT NULL
				AND DHAS_1.TRKH_PNRMAN IS NOT NULL
				AND DHAS_1.TRKH_KPI IS NULL
			THEN DHAS_1.TRKH_PNRMAN + (ITG_1.MINIT_KPI || ' minutes')::INTERVAL
			ELSE DHAS_1.TRKH_KPI
			END,
			'DD/MM/YYYY'
		)
	END AS TARIKH_DAN_MASA_LUPUT_STRING,
	CASE
  		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL
       AND (
         DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
         OR DHAS_1.KOD_TGSN LIKE '%PTB%'
       )
	THEN NULL
	ELSE
		CASE
		WHEN ITG_1.MINIT_KPI IS NOT NULL
			AND DHAS_1.TRKH_PNRMAN IS NOT NULL
			AND DHAS_1.TRKH_KPI IS NULL
		THEN DHAS_1.TRKH_PNRMAN + (ITG_1.MINIT_KPI || ' minutes')::INTERVAL
		ELSE DHAS_1.TRKH_KPI
		END
	END AS TARIKH_DAN_MASA_LUPUT,

	CASE
		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL
			AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
				OR DHAS_1.KOD_TGSN LIKE '%PTB%')
		THEN '-'
		ELSE TO_CHAR(APP_1.TRKH_PIAGAM, 'DD/MM/YYYY')
	END AS TARIKH_PIAGAM_STRING,
	CASE
		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL
			AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
				OR DHAS_1.KOD_TGSN LIKE '%PTB%')
		THEN '-'
		ELSE TO_CHAR(APP_TGSN_1.TRKH_TETAP, 'DD/MM/YYYY')
	END AS TARIKH_MULA_STRING,
	CASE
		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL
			AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
				OR DHAS_1.KOD_TGSN LIKE '%PTB%')
		THEN TRUE
		ELSE FALSE
	END AS IS_FILTER_TUGASAN,
	CASE
		WHEN ITG_1.MINIT_KPI IS NOT NULL
			AND DHAS_1.TRKH_PNRMAN IS NOT NULL
			AND DHAS_1.TRKH_KPI IS NULL
		THEN DHAS_1.TRKH_PNRMAN + (ITG_1.MINIT_KPI || ' minutes')::INTERVAL
		ELSE DHAS_1.TRKH_KPI
	END AS TARIKH_KPI,


	CASE
	  WHEN NOT (
	    TRIM(DHAS_1.KOD_TGSN) IS NOT NULL
	    AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
	         OR DHAS_1.KOD_TGSN LIKE '%PTB%')
	  )
	  THEN
	    CASE
	      -- Special handling for PRBB urusan: get idHkmlk from UMM_A_PERMOHONAN_TNH.maklumat_tambahan
	      WHEN COALESCE(URSN_1.KOD, URSN_2.KOD) = 'PRBB'
	      THEN (
	        SELECT apt.MKLMT_TMBHN::jsonb ->> 'idHkmlk'
	        FROM UMM_A_PERMOHONAN_TNH apt
	        WHERE apt.APLIKASI_ID = APP_1.APLIKASI_ID
	          AND apt.MKLMT_TMBHN IS NOT NULL
	          AND apt.MKLMT_TMBHN::jsonb ->> 'idHkmlk' IS NOT NULL
	        LIMIT 1
	      )

	      -- Special handling for HLPK urusan: get master id_hakmilik from IND_HKMLK via UMM_A_HKMLK
	      WHEN COALESCE(URSN_1.KOD, URSN_2.KOD) = 'HLPK'
	      THEN (
	        SELECT STRING_AGG(DISTINCT h.ID_HKMLK, ', ' ORDER BY h.ID_HKMLK)
	        FROM IND_HKMLK h
	        WHERE h.strata_induk_id IS NULL
	          AND h.ID_HKMLK IN (
	            SELECT ah.ID_HKMLK
	            FROM UMM_A_HKMLK ah
	            WHERE ah.APLIKASI_ID = APP_1.APLIKASI_ID
	          )
	      )

	      WHEN COALESCE(NULLIF(TRIM(DHAS_1.ID_HKMLK), ''), '-') = '-' THEN '-'
	      ELSE (
	        SELECT
	          CASE
	            WHEN COUNT(*) > 10
	            THEN (
	              SELECT string_agg(val, ', ') || '...'
	              FROM (
	                SELECT DISTINCT val
	                FROM unnest(string_to_array(DHAS_1.ID_HKMLK, ',')) AS val
	                ORDER BY val
	                LIMIT 10
	              ) sub
	            )
	            ELSE (
	              SELECT string_agg(DISTINCT val, ', ' ORDER BY val)
	              FROM unnest(string_to_array(DHAS_1.ID_HKMLK, ',')) AS val
	            )
	          END
	      )
	    END
	  ELSE COALESCE(NULLIF(TRIM(DHAS_1.ID_HKMLK), ''), '-')
	END AS NO_HAKMILIK_DASHBOARD,
	CASE
	  WHEN NOT (
	    TRIM(DHAS_1.KOD_TGSN) IS NOT NULL
	    AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
	         OR DHAS_1.KOD_TGSN LIKE '%PTB%')
	  )
	  THEN COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
	  ELSE NULL
	END AS APLIKASI_NO_PERMOHONAN,


	CASE
	  WHEN NOT (
	    TRIM(DHAS_1.KOD_TGSN) IS NOT NULL
	    AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
	         OR DHAS_1.KOD_TGSN LIKE '%PTB%')
	  )
		  THEN
		    CASE
		      WHEN COALESCE(NULLIF(TRIM(DHAS_1.NO_RESIT), ''), '-') = '-' THEN '-'
		      ELSE (
		        SELECT
		          CASE
		            WHEN COUNT(*) > 10
		            THEN (
		              SELECT string_agg(val, ', ') || '...'
		              FROM (
		                SELECT DISTINCT val
		                FROM unnest(string_to_array(DHAS_1.NO_RESIT, ',')) AS val
		                ORDER BY val
		                LIMIT 10
		              ) sub
		            )
		            ELSE (
		              SELECT string_agg(DISTINCT val, ', ' ORDER BY val)
		              FROM unnest(string_to_array(DHAS_1.NO_RESIT, ',')) AS val
		            )
		          END
		      )
		    END
		  ELSE COALESCE(NULLIF(TRIM(DHAS_1.NO_RESIT), ''), '-')
		END AS NO_RESIT_DASHBOARD,


		CASE
		  WHEN NOT (
		    TRIM(DHAS_1.KOD_TGSN) IS NOT NULL
		    AND (
		      DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
		      OR DHAS_1.KOD_TGSN LIKE '%PTB%'
		    )
		  )
		  THEN
		    CASE
		      WHEN HNTR_1.ID_PENGHANTARAN IS NOT NULL AND HNTR_1.ID_PENGHANTARAN LIKE 'PNL/%'
		        THEN 'UPNL'
		      ELSE COALESCE(URSN_1.KOD, URSN_2.KOD)
		    END
		  ELSE
		    COALESCE(URSN_1.KOD, URSN_2.KOD)
		END AS URUSAN_KOD_DASHBOARD,

		CASE
		  WHEN UPPER(APP_1.FLAG_INTEGRASI) ='Y' THEN
		    CASE
		      WHEN COALESCE(COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI), '') LIKE '%MF%'
		           AND COALESCE(COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI), '') LIKE '%(%' THEN
		        SPLIT_PART(COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI), '(', 1)

		      WHEN COALESCE(APP_1.URSN_ID, URSN_2.URSN_ID) IS NOT NULL
		           AND COALESCE(URSN_1.KOD, URSN_2.KOD) = 'KVSP' THEN
		        (
		          SELECT hubungan2.ID_PENGENALAN || ' / ' || COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
		          FROM UMM_APLIKASI hubungan1
		          JOIN UMM_APLIKASI hubungan2 ON hubungan1.ID_PENGENALAN = hubungan2.APLIKASI_ID
		          WHERE hubungan1.APLIKASI_ID = APP_1.APLIKASI_ID
		          LIMIT 1
		        )

		      ELSE
		        (
		          SELECT hubungan.no_rujukan_fail || ' / ' || COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
		          FROM UMM_APLIKASI hubungan
		          WHERE hubungan.APLIKASI_ID = APP_1.APLIKASI_ID
		          LIMIT 1
		        )
		    END
		  WHEN DHAS_1.KOD_TGSN  = 'STRSPRAP' THEN
		    APP_A_1.ID_TRANSAKSI

		   WHEN COALESCE(URSN_1.KOD, URSN_2.KOD) IN ('HDHK', 'HDHD', 'KVSPM')
			AND NOT (
			DHAS_1.MODUL = 'PNT'
			AND HNTR_1.ID_PENGHANTARAN LIKE 'PNL/%'
			AND APP_1.MKLMT_TMBHN IS NOT NULL
			AND APP_1.MKLMT_TMBHN::jsonb ->> 'idPengenalanInduk' IS NOT NULL
			)
		THEN
			COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI) ||
			' ' || (
			SELECT ID_PENGENALAN
			FROM UMM_APLIKASI
			WHERE NO_RUJUKAN_FAIL = COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
			LIMIT 1
			)

			WHEN DHAS_1.MODUL = 'PNT'
				AND HNTR_1.ID_PENGHANTARAN LIKE 'PNL/%'
				AND APP_1.MKLMT_TMBHN IS NOT NULL
				AND APP_1.MKLMT_TMBHN::jsonb ->> 'idPengenalanInduk' IS NOT NULL
			THEN
				APP_1.MKLMT_TMBHN::jsonb ->> 'idPengenalanInduk'

			WHEN DHAS_1.KOD_TGSN = 'PTB' THEN '-'
		ELSE
		    COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
		END AS ID_PERMOHONAN_DASHBOARD,

		  CASE
		    WHEN DHAS_1.kod_tgsn IN ('PPF', 'PPJUB', 'PPPK', 'PPSYT') THEN org_nama.nama
		    WHEN URSN_1.kod = 'PPLBL' THEN pelelong_nama.nama_pemohon
		    ELSE bkptg_nama.nama
		  END AS NAMA_PEMOHON,
		  COALESCE(KS.NO_KERTAS_SIASATAN, APP_1.NO_RUJUKAN_FAIL, '') as NO_FAIL_PEMOHON




FROM UMM_TGSN_SEMASA DHAS_1

LEFT JOIN UMM_APLIKASI APP_1 ON DHAS_1.APLIKASI_ID = APP_1.APLIKASI_ID
LEFT JOIN UMM_APLIKASI APP_2 ON DHAS_1.APLIKASI_ID = APP_2.APLIKASI_ID
LEFT JOIN IND_URSN URSN_1 ON APP_2.URSN_ID = URSN_1.URSN_ID

LEFT JOIN IND_MODUL MDL_1 ON URSN_1.MODUL_ID = MDL_1.MODUL_ID

LEFT JOIN UMM_APLIKASI APP_3 ON DHAS_1.APLIKASI_ID = APP_3.APLIKASI_ID
LEFT JOIN UMM_APLIKASI APP_4 ON APP_3.HUBUNGAN_APLIKASI_ID = APP_4.APLIKASI_ID

LEFT JOIN UMM_P_APLIKASI APP_A_1 ON DHAS_1.P_APLIKASI_ID = APP_A_1.P_APLIKASI_ID
LEFT JOIN UMM_P_APLIKASI APP_A_2 ON DHAS_1.P_APLIKASI_ID = APP_A_2.P_APLIKASI_ID
LEFT JOIN IND_URSN URSN_2 ON APP_A_2.URSN_ID = URSN_2.URSN_ID
LEFT JOIN UMM_P_APLIKASI APP_A_3 ON DHAS_1.P_APLIKASI_ID = APP_A_3.P_APLIKASI_ID

LEFT JOIN RJK_JNS_URSN RJU_1  on URSN_1.JNS_URSN_ID = RJU_1.JNS_URSN_ID
LEFT JOIN RJK_SENARAI_AHLI_KUMPULAN SNR_1 ON APP_A_3.STATUS_ID = SNR_1.SENARAI_AHLI_KUMPULAN_ID

LEFT JOIN UMM_A_TGSN APP_TGSN_1 ON DHAS_1.A_TGSN_ID = APP_TGSN_1.A_TGSN_ID
LEFT JOIN UMM_A_TGSN APP_TGSN_2 ON DHAS_1.A_TGSN_ID = APP_TGSN_2.A_TGSN_ID
LEFT JOIN IND_TGSN ITG_1 ON APP_TGSN_2.TGSN_ID = ITG_1.TGSN_ID

LEFT JOIN UMM_A_TGSN APP_A_4 ON DHAS_1.A_TGSN_ID = APP_A_4.A_TGSN_ID
LEFT JOIN PCP_PENGGUNA PGN_1 ON APP_A_4.PENGGUNA_SEMASA_ID = PGN_1.PENGGUNA_ID

LEFT JOIN UMM_MKLMT_LAPORAN_SIASATAN MLS ON DHAS_1.MKLMT_LAPORAN_SIASATAN_ID = MLS.MKLMT_LAPORAN_SIASATAN_ID

LEFT JOIN IND_PEJABAT IPJ_1 ON DHAS_1.PEJABAT_ID = IPJ_1.PEJABAT_ID
LEFT JOIN UMM_HANTARAN_NOTIS HNTR_1 ON DHAS_1.HANTARAN_NOTIS_ID = HNTR_1.HANTARAN_NOTIS_ID
LEFT JOIN PKS_A_KERTAS_SIASATAN KS ON DHAS_1.A_KERTAS_SIASATAN_ID = KS.A_KERTAS_SIASATAN_ID

LEFT JOIN LATERAL (
	  SELECT o.nama
	  FROM umm_p_daftar_organisasi o
	  WHERE o.p_daftar_organisasi_id IN (
	    SELECT MIN(o2.p_daftar_organisasi_id)
	    FROM umm_p_daftar_organisasi o2
	    --WHERE APP_A_1.id_transaksi = APP_1.id_pengenalan
	    WHERE APP_A_1.P_APLIKASI_ID = DHAS_1.P_APLIKASI_ID
	  )
	  LIMIT 1
	) AS org_nama ON DHAS_1.kod_tgsn IN ('PPF', 'PPJUB', 'PPPK', 'PPSYT')


	LEFT JOIN LATERAL (
	  SELECT p.nama_pemohon
	  FROM llg_a_daftar_pelelong p
	  WHERE p.aplikasi_id = DHAS_1.aplikasi_id
	  ORDER BY p.a_daftar_pelelong_id ASC
	  LIMIT 1
	) AS pelelong_nama ON URSN_1.kod = 'PPLBL'

	LEFT JOIN LATERAL (
	  SELECT r.nama
	  FROM umm_a_pihak_bkptg r
	  WHERE r.aplikasi_id = DHAS_1.aplikasi_id
	    AND UPPER(r.flag_pemohon) = 'Y'
	  ORDER BY r.a_pihak_bkptg_id ASC
	  LIMIT 1
	) AS bkptg_nama ON TRUE

	WHERE UPPER(DHAS_1.FLAG_TGSN_SISTEM) = 'N'
	AND (DHAS_1.NAMA_PENGGUNA = var_nama_pengguna OR DHAS_1.NAMA_PENGGUNA IS NULL)
	AND (EXISTS (
        SELECT 1 FROM VAR_PERANAN_KOD_PENGGUNA PKP
        WHERE PKP.NAMA_PENGGUNA = DHAS_1.NAMA_PENGGUNA AND PKP.peranan_kod = 'PTG'
    	) OR DHAS_1.PEJABAT_ID IN (SELECT PEJABAT_ID FROM VAR_PEJABAT_TERKAIT) OR DHAS_1.PEJABAT_ID IS NULL
	)

	AND (
		URSN_1.KOD IN (SELECT KOD FROM VAR_URUSAN_KOD_LIST)
		OR URSN_2.KOD IN (SELECT KOD FROM VAR_URUSAN_KOD_LIST)
	)

	AND EXISTS (
		SELECT 1
		FROM VAR_PERANAN_KOD_PENGGUNA PKP
		WHERE DHAS_1.PERANAN LIKE '%-' || PKP.PERANAN_KOD || '-%'
	)
	AND (APP_TGSN_1.A_TGSN_ID is null or APP_TGSN_1.A_TGSN_ID is not null )
	--IF
		AND (
		    var_modul_kod IS NULL
		    OR DHAS_1.modul = var_modul_kod
			AND (var_modul_kod = 'DFT' AND RJU_1.KOD = var_urusan_mdl_kod)

			or  (var_modul_kod != 'DFT' AND COALESCE(URSN_1.KOD, URSN_2.KOD) = var_urusan_mdl_kod)
		)

	-- END
	),

VAR_GROUPED_TUGAS AS (
    SELECT
        mq.*,
        ROW_NUMBER() OVER (PARTITION BY ua.no_fail, mq.kod_tgsn ORDER BY mq.tgsn_semasa_id) AS rn
    FROM MAIN_QUERY mq
    LEFT JOIN umm_aplikasi ua ON mq.aplikasi_id = ua.aplikasi_id
    WHERE mq.kod_tgsn IN ('PPBKRPDPJPM', 'PPBKRSDPJPM', 'PPBKRCDPJPM')
),
VAR_MODUL_PENGGUNA AS (
  SELECT DISTINCT p.nama_pengguna, m.kod AS modul_kod
  FROM pcp_capaian_pengguna cp
  JOIN pcp_pengguna p ON cp.pengguna_id = p.pengguna_id
  JOIN pcp_peranan_modul pm ON cp.peranan_modul_id = pm.peranan_modul_id
  JOIN ind_modul m ON pm.modul_id = m.modul_id
  WHERE p.nama_pengguna IN (var_nama_pengguna)
    AND m.kod IN ('PNT', 'UAM')
),

VAR_BELUM_TUKAR_GANTI AS (
 SELECT unnest(ARRAY['HMSC', 'HMSTP', 'PRBB', 'OPRBB', 'HDHD', 'HMPV', 'HMV','HMVB','SSHM','SSSC','SW','SA','CRHMB','CSHMB','BETUL','PACT','PKH','PMKMH','PFT','REM','REMITAN'])
),
FINAL_QUERY_V1 AS (
	SELECT * FROM MAIN_QUERY AS DEFAULT_MAIN_PNT
	WHERE EXISTS (
	    SELECT 1
	    FROM VAR_MODUL_PENGGUNA mp
	    WHERE mp.nama_pengguna = DEFAULT_MAIN_PNT.nama_pengguna
	      OR DEFAULT_MAIN_PNT.modul IN ('PNT', 'UAM')
	  )
	AND DEFAULT_MAIN_PNT.kod_tgsn NOT IN ('KD', 'STRKD')
		AND NOT (
		  DEFAULT_MAIN_PNT.modul = 'CON'
		  AND DEFAULT_MAIN_PNT.kod_tgsn IN ('CSK', 'JSK')
		)
	UNION ALL
	SELECT * FROM MAIN_QUERY AS DEFAULT_MAIN
	WHERE DEFAULT_MAIN.KOD_TGSN NOT IN ('KD', 'STRKD')
	AND NOT (
	    DEFAULT_MAIN.MODUL = 'CON' AND
	    (DEFAULT_MAIN.KOD_TGSN = 'CSK' OR DEFAULT_MAIN.KOD_TGSN = 'JSK')
	)
	AND DEFAULT_MAIN.MODUL NOT IN ('PNT', 'UAM')
	AND NOT (
	    DEFAULT_MAIN.kod_tgsn IN ('KD', 'STRKD')
	    OR (DEFAULT_MAIN.NAMA_PENGGUNA IS NOT NULL AND DEFAULT_MAIN.NAMA_PENGGUNA <> var_nama_pengguna)
	)
--new

--==========
--
	AND NOT (
	    DEFAULT_MAIN.KOD_TGSN = 'PTBUT'
	    AND DEFAULT_MAIN.URUSAN_KOD IN ('PMQFT', 'PMQTFT')
	)
--==========

),

FIANL_QUERY_MERGE as (
	select * FROM FINAL_QUERY_V1 as FN_Q1
	WHERE NOT EXISTS (
		SELECT 1
   		FROM VAR_FILTER_TUGASAN_KOD_SET
		 WHERE
	      (
	        stgsn_kod = 'PTB'
	        AND FN_Q1.KOD_TGSN LIKE '%' || stgsn_kod || '%'
	      )
			OR (
		    stgsn_kod <> 'PTB'
			  AND FN_Q1.KOD_TGSN = stgsn_kod
			)
	)

 	UNION ALL
	SELECT * from (

		SELECT DISTINCT ON (FN_Q1_v2.KOD_TGSN) FN_Q1_v2.*
		FROM FINAL_QUERY_V1 as FN_Q1_v2
		WHERE EXISTS (
			 SELECT 1
      		FROM VAR_FILTER_TUGASAN_KOD_SET
			where (
					UPPER(FN_Q1_v2.STATUS_PROSES) <> 'GANTUNG'

					AND (
			          (stgsn_kod = 'PTB' AND FN_Q1_v2.KOD_TGSN LIKE '%' || stgsn_kod || '%')
			          OR (stgsn_kod = 'SJR' AND FN_Q1_v2.KOD_TGSN LIKE '%' || stgsn_kod || '%')
			          OR (stgsn_kod = 'CTK_JR' AND FN_Q1_v2.KOD_TGSN LIKE '%' || stgsn_kod || '%')
			          OR (stgsn_kod = 'PJR' AND FN_Q1_v2.KOD_TGSN LIKE '%' || stgsn_kod || '%')
			          OR (
			            stgsn_kod NOT IN ('PTB', 'SJR', 'CTK_JR', 'PJR')
			            AND FN_Q1_v2.KOD_TGSN = stgsn_kod
			          )
			        )
			) order by FN_Q1_v2.KOD_TGSN, FN_Q1_v2.tgsn_semasa_id desc
		) limit 1
	)

),
VAR_USER_PERANAN AS (
  SELECT
    LOWER(mdl.kod) AS modul,
    LOWER(sak.kod) AS peranan
  FROM pcp_capaian_pengguna cp
  JOIN pcp_pengguna pg ON cp.pengguna_id = pg.pengguna_id
  JOIN pcp_peranan_modul pm ON cp.peranan_modul_id = pm.peranan_modul_id
  JOIN ind_modul mdl ON pm.modul_id = mdl.modul_id
  JOIN rjk_senarai_ahli_kumpulan sak ON pm.peranan_id = sak.senarai_ahli_kumpulan_id
  WHERE pg.nama_pengguna = var_nama_pengguna
),
FINAL_QUERY AS (
  SELECT *
  FROM FIANL_QUERY_MERGE AS DEFAULT_MAIN
  WHERE 1=1

	AND
    (
      var_status_tugasan IS NULL
      OR UPPER(var_status_tugasan) NOT IN ('BARU', 'SEMASA')
      OR (
        UPPER(var_status_tugasan) = 'BARU' AND UPPER(DEFAULT_MAIN.STATUS_TUGASAN) = 'BARU'
      )
      OR (
        UPPER(var_status_tugasan) = 'SEMASA' AND UPPER(DEFAULT_MAIN.STATUS_TUGASAN) = 'DALAM TINDAKAN'
      )
    )
    AND (
    -- Ambil jika bukan PTB dan nama_pengguna tidak kosong
    (
      DEFAULT_MAIN.kod_tgsn NOT ILIKE '%PTB%'
      AND COALESCE(TRIM(DEFAULT_MAIN.nama_pengguna), '') <> ''
    )
    -- Atau: jika PTB / nama kosong, validasi modul dan peranan terhadap VAR_USER_PERANAN
    OR EXISTS (
      SELECT 1
      FROM VAR_USER_PERANAN u
      WHERE LOWER(u.modul) = LOWER(DEFAULT_MAIN.modul)
        AND EXISTS (
          SELECT 1
          FROM unnest(string_to_array(LOWER(DEFAULT_MAIN.peranan), '-')) AS p(peranan)
          WHERE p.peranan = u.peranan
        )
        AND (
          DEFAULT_MAIN.kod_tgsn ILIKE '%PTB%'
          OR COALESCE(TRIM(DEFAULT_MAIN.nama_pengguna), '') = ''
        )
    )

    )
    AND NOT (
      DEFAULT_MAIN.id_rujukan_smartbox IS NOT NULL
      AND DEFAULT_MAIN.id_rujukan_smartbox <> ''
      AND DEFAULT_MAIN.kod_tgsn IN ('ISHSB', 'KDSB')
    )

),

VAR_KOD_TUGSAN_BY_PELUPUSAN AS (
SELECT unnest(ARRAY['PYKP', 'SKP', 'SKP2', 'SKP3', 'PKP',
    'PYJKPTD', 'SJKPTD', 'SJKPTD2', 'SJKPTD3', 'PJKPTD', 'CJKPTD',
    'KKJKPTD', 'SKJKPTD', 'PYMMKN', 'SMMKN', 'SMMKN2', 'SMMKN3',
    'PMMKN', 'PSSPTG', 'SDPDT', 'SKMPTG', 'SKMPTG2', 'SKMPTG3',
    'SKMPTG4', 'SKMPTG5', 'PKMPTG', 'CKMPTG', 'SKPPTG', 'SKPPTG2',
    'SKPPTG3', 'SKPPTG4', 'SKPPTG5', 'PKPPTG', 'PYKPMB', 'SKPMB',
    'SKPMB2', 'SKPMB3', 'PSKPMB', 'SKPMBPTG', 'SKPMBPTG2', 'SKPMBPTG3',
    'SKPMBPTG4', 'SKPMBPTG5', 'PKPMBPTG', 'CKPMBPTG', 'PTBUT3', 'PLT',
    'SDS', 'PTBUT4', 'PPM', 'SPM', 'PFI', 'PYKMPTG'])
),
URUSAN_MODUL_PARENT_CTE AS (
  SELECT
    A.APLIKASI_ID as APP_ID_CTE,
    M.KOD AS URUSAN_MODUL_PARENT
  FROM UMM_APLIKASI A
  LEFT JOIN IND_URSN U ON A.URSN_ID = U.URSN_ID
  LEFT JOIN IND_MODUL M ON U.MODUL_ID = M.MODUL_ID
),


VAR_CONSENT_KOD AS (
    SELECT unnest(ARRAY['PFMMK', 'PPPTG', 'SFMMK', 'SPTPTG', 'KPTG','KTPTG','KCADO','KDO','PDO','STSKP','KPTG2', 'KMB'])
),
CONSENT_FILTER AS (
	SELECT *
	FROM FINAL_QUERY f
	WHERE f.MODUL = 'CON'
	  AND NOT (
	    f.urusan_kod_dashboard = 'KPMP'
	    AND var_kod_negri = '08' -- 11= param
	  )
	  AND f.KOD_TGSN IN (SELECT * FROM VAR_CONSENT_KOD)
),


CONSENT_FILTER_ONE as (
	SELECT
	CON.tgsn_semasa_id,
NULL::timestamp as trkh_pnrman,
CON.modul,
CON.id_hkmlk,
CON.no_resit,
CON.locked_by,
CON.locked_date,
CON.peranan,
CON.kod_tgsn,
CON.id_tgsn,
CON.tgsn_perihal,
CON.nama_pengguna,
CON.trkh_tetap,
CON.trkh_piagam,
CON.aplikasi_id,
CON.app_id,
CON.rangkaian_id,
CON.id_pengenalan,
CON.flag_integrasi,
CON.status_keputusan,
CON.fail_induk,
CON.status_proses,
CON.urusan_kod,
CON.no_rujukan,
CON.nama_pendek,
CON.pejabat_kod,
CON.id_penghantaran,
CON.app_a_tgsn_id,
CON.nama_pejabat_pendek,
CON.tarikh_siasatan_string,
CON.id_rujukan_smartbox,
CON.dhas_1_trkh_kpi,
CON.minit_kpi,
CON.show_id_hakmilik,
CON.no_hakmilik_baru,
CON.trkh_kpi,
CON.status_tugasan,
CON.show_kpi,
'-' as tarikh_penerimaan_string,
'-' as tarikh_dan_masa_luput_string,
CON.tarikh_dan_masa_luput,
CON.tarikh_piagam_string,
CON.tarikh_mula_string,
CON.is_filter_tugasan,
CON.tarikh_kpi,
'' as no_hakmilik_dashboard,
CON.aplikasi_no_permohonan,
'' AS no_resit_dashboard,
'' as urusan_kod_dashboard,
id_permohonan_dashboard,
CON.nama_pemohon,
'' as no_fail_pemohon

	FROM CONSENT_FILTER CON
--	ORDER BY CON.tgsn_semasa_id
--	LIMIT 1
),

FINAL_FILTER_CON as (
SELECT *
	FROM FINAL_QUERY a
--	WHERE a.modul <> 'CON'

	UNION ALL

	SELECT * FROM CONSENT_FILTER_ONE
),


FINAL_FILTER_ALL  AS (
	SELECT * FROM FINAL_FILTER_CON AS FQ

	WHERE 1=1
	AND NOT (
		FQ.MODUL = 'PFIKM'
		OR FQ.ID_TGSN IN (SELECT ID_TGSN_PELUPUSAN_PENGGUNA_FILTER FROM VAR_PELUPUSAN_TUGASAN_FILTERED)
  	)
	AND NOT (FQ.modul = 'UAM' AND FQ.URUSAN_KOD = 'BIO')

    AND NOT (
      COALESCE(TRIM(FQ.locked_by), '') <> ''
      AND LOWER(FQ.locked_by) <> LOWER(var_nama_pengguna)
      AND FQ.locked_date IS NOT NULL
      AND FQ.locked_date > NOW() - INTERVAL '30 minutes'
    )

),

FINAL_FILTER_ALL_V2 as (
	SELECT * FROM FINAL_FILTER_ALL
),




FINAL_RESULT AS (
	SELECT * ,
	CASE
	  WHEN EXISTS (
	    SELECT 1
	    FROM UMM_PERTANYAAN p
	    JOIN RJK_SENARAI_AHLI_KUMPULAN k ON p.STATUS_ID = k.SENARAI_AHLI_KUMPULAN_ID
	    JOIN UMM_APLIKASI a ON p.APLIKASI_ID = a.APLIKASI_ID
	    JOIN IND_URSN u ON a.URSN_ID = u.URSN_ID
	    WHERE p.A_TGSN_ID = FQ.APP_A_TGSN_ID
	      AND k.KOD != 'SELESAI'
	      AND u.TEMPOH_KUIRI ~ '^[0-9]+$'
	      AND DATE_PART('day', CURRENT_DATE - p.CREATED_DATE) > u.TEMPOH_KUIRI::INT
	  )
	  THEN ' (Pertanyaan) - Telah Melebihi Tempoh Kuiri'

	  WHEN EXISTS (
	    SELECT 1
	    FROM UMM_PERTANYAAN p
	    JOIN RJK_SENARAI_AHLI_KUMPULAN k ON p.STATUS_ID = k.SENARAI_AHLI_KUMPULAN_ID
	    WHERE p.A_TGSN_ID = FQ.APP_A_TGSN_ID
	      AND k.KOD != 'SELESAI'
	  )
	  THEN ' (Pertanyaan)'

	  ELSE NULL
	END AS pertanyaan_keterangan,


	--	color and flag
	CASE
	    WHEN (
	        CASE
	            WHEN FQ.MINIT_KPI IS NOT NULL
	                 AND FQ.TRKH_PNRMAN IS NOT NULL
	                 AND FQ.DHAS_1_TRKH_KPI IS NULL
	            THEN FQ.TRKH_PNRMAN + (FQ.MINIT_KPI || ' minutes')::INTERVAL
	            ELSE FQ.DHAS_1_TRKH_KPI
	        END
	    ) IS NOT NULL
	    AND (
	        CASE
	            WHEN FQ.MINIT_KPI IS NOT NULL
	                 AND FQ.TRKH_PNRMAN IS NOT NULL
	                 AND FQ.DHAS_1_TRKH_KPI IS NULL
	            THEN FQ.TRKH_PNRMAN + (FQ.MINIT_KPI || ' minutes')::INTERVAL
	            ELSE FQ.DHAS_1_TRKH_KPI
	        END
	    ) < CURRENT_DATE
	THEN 'TUNGGAK'
	ELSE NULL
	END AS STATUS,
	CASE
	    WHEN (
	        CASE
	            WHEN FQ.MINIT_KPI IS NOT NULL
	                 AND FQ.TRKH_PNRMAN IS NOT NULL
	                 AND FQ.TRKH_KPI IS NULL
	            THEN FQ.TRKH_PNRMAN + (FQ.MINIT_KPI || ' minutes')::INTERVAL
	            ELSE FQ.DHAS_1_TRKH_KPI
	        END
	    ) IS NOT NULL
	    AND (
	        CASE
	            WHEN FQ.MINIT_KPI IS NOT NULL
	                 AND FQ.TRKH_PNRMAN IS NOT NULL
	                 AND FQ.TRKH_KPI IS NULL
	            THEN FQ.TRKH_PNRMAN + (FQ.MINIT_KPI || ' minutes')::INTERVAL
	            ELSE FQ.DHAS_1_TRKH_KPI
	        END
	    ) < CURRENT_DATE
	THEN 'red' -- warna merah sebagai contoh
	ELSE NULL
	END AS COLOR,


	CASE
	    WHEN NOT FQ.SHOW_KPI THEN 'Hijau'
	    WHEN FQ.TARIKH_DAN_MASA_LUPUT_STRING IS NULL OR FQ.TARIKH_DAN_MASA_LUPUT_STRING = '-' THEN 'Hijau'
	    WHEN FQ.TRKH_TETAP IS NULL THEN
	        CASE
	            WHEN TO_DATE(FQ.TARIKH_DAN_MASA_LUPUT_STRING, 'DD/MM/YYYY') >= CURRENT_DATE THEN 'Hijau'
	            ELSE 'Merah'
	        END
	    WHEN TO_DATE(FQ.TARIKH_DAN_MASA_LUPUT_STRING, 'DD/MM/YYYY') <= FQ.TRKH_TETAP::DATE THEN 'Hijau'
	    ELSE 'Merah'
	END AS FLAG_STATUS,

	--end color and flag

CASE
  WHEN FQ.KOD_TGSN = 'ISH' THEN TRUE
 WHEN FQ.KOD_TGSN = 'KDO' THEN TRUE
  WHEN FQ.MODUL = 'KKS' THEN TRUE
  WHEN FQ.MODUL = 'PNT' AND URUSAN_MODUL_PARENT = 'KKS' THEN TRUE
  WHEN EXISTS (
    SELECT 1
    FROM UNNEST(STRING_TO_ARRAY(FQ.URUSAN_KOD_DASHBOARD, '<BR />')) AS URSN
    WHERE URSN IN (SELECT * FROM VAR_BELUM_TUKAR_GANTI)
  ) THEN TRUE
  WHEN EXISTS (
    SELECT 1
    FROM UNNEST(STRING_TO_ARRAY(FQ.URUSAN_KOD_DASHBOARD, '<BR />')) AS URSN
    WHERE URSN IS NOT NULL
      AND (
        URSN NOT IN (SELECT * FROM VAR_BELUM_TUKAR_GANTI)
        OR URSN IN (SELECT * FROM VAR_ALSAN_TUKARGANTI_KOD_SET_BATAL)
      )
or (
    (
      SELECT COUNT(*) FROM DFT_A_MOHON_HKMLK HM
      JOIN IND_MKLMT_HKMLK MH ON MH.mklmt_hkmlk_id = HM.ID_HKMLK
      JOIN rjk_senarai_ahli_kumpulan o ON o.senarai_ahli_kumpulan_id = MH.status_hkmlk_id
      WHERE HM.APLIKASI_ID = FQ.APLIKASI_ID AND o.kod = 'STAHMBT'
    ) = (
      SELECT COUNT(*) FROM DFT_A_MOHON_HKMLK HM
      WHERE HM.APLIKASI_ID = FQ.APLIKASI_ID
    )
    or NOT EXISTS (
      SELECT 1
      FROM DFT_A_MOHON_HKMLK HM
      JOIN IND_MKLMT_HKMLK MH ON MH.mklmt_hkmlk_id = HM.ID_HKMLK
      JOIN RJK_SENARAI_AHLI_KUMPULAN o ON o.senarai_ahli_kumpulan_id = MH.status_hkmlk_id
      WHERE HM.APLIKASI_ID = FQ.APLIKASI_ID
      AND o.kod = 'STAHDFT'
      AND EXISTS (
        SELECT 1 FROM IND_VERSI_DHD TG WHERE TG.hkmlk_id = HM.ID_HKMLK
      )
    )
  )
  )

  THEN TRUE
  ELSE FALSE
END AS IS_HAKMILIK_BELUM_TUKARGANTI,



CASE
  WHEN FQ.TARIKH_DAN_MASA_LUPUT IS NULL THEN '-'

  WHEN FQ.TARIKH_DAN_MASA_LUPUT <= NOW() THEN '0 Hari'

  WHEN DATE_PART('month', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 THEN
    TRIM(BOTH FROM CONCAT_WS(' ',
      CASE
        WHEN DATE_PART('month', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0
          THEN FLOOR(DATE_PART('month', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Bulan'
      END,
      CASE
        WHEN DATE_PART('day', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0
          THEN FLOOR(DATE_PART('day', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Hari'
      END,
      CASE
        WHEN DATE_PART('hour', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0
          THEN FLOOR(DATE_PART('hour', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Jam'
      END,
      CASE
        WHEN DATE_PART('minute', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0
          THEN FLOOR(DATE_PART('minute', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Minit'
      END
    ))

  ELSE
    TRIM(BOTH FROM CONCAT_WS(' ',
      CASE
        WHEN DATE_PART('day', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0
          THEN FLOOR(DATE_PART('day', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Hari'
      END,
      CASE
        WHEN DATE_PART('hour', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0
          THEN FLOOR(DATE_PART('hour', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Jam'
      END,
      CASE
        WHEN DATE_PART('minute', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0
          THEN FLOOR(DATE_PART('minute', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Minit'
      END
    ))
END AS BAKI_MASA




FROM FINAL_FILTER_ALL_V2 AS FQ
LEFT JOIN URUSAN_MODUL_PARENT_CTE UMP ON UMP.APP_ID_CTE = FQ.APP_ID
where UPPER(FQ.STATUS_TUGASAN) <> 'SELESAI'

),



 rangkaian_merged AS (
    SELECT
      MAX(fd.TGSN_SEMASA_ID)::BIGINT AS ID,
      MAX(fd.TRKH_PNRMAN) AS TRKH_PEN,
      MAX(fd.TARIKH_PENERIMAAN_STRING) AS TARIKH_PENERIMAAN_STRING,
      MAX(fd.TARIKH_DAN_MASA_LUPUT_STRING) AS TARIKH_DAN_MASA_LUPUT_STRING,
      COALESCE(STRING_AGG(DISTINCT NULLIF(fd.NO_HAKMILIK_DASHBOARD, '-'), '<br />'), '-') AS no_hakmilik,
      ra.RANGKAIAN_ID::TEXT AS rangkaian_id_merged,
      fd.kod_tgsn::TEXT,
      STRING_AGG( fd.ID_PERMOHONAN_DASHBOARD ::TEXT, '<br />') AS id_permohonan,
      STRING_AGG(fd.URUSAN_KOD_DASHBOARD ::TEXT, '<br />') AS urusan,
      MAX(fd.NO_FAIL_PEMOHON) AS NO_FAIL_PEMOHON,
      STRING_AGG(DISTINCT  fd.NO_RESIT_DASHBOARD :: TEXT, '<br />') AS no_resit,
	  max(fd.TGSN_PERIHAL) as tugas,
      MAX(fd.NAMA_PEMOHON) AS NAMA_PEMOHON,
      MAX(fd.NAMA_PEJABAT_PENDEK) AS PEJABAT,
      MAX(fd.ID_PENGHANTARAN) AS ID_PENYAMPAIAN,
		MAX(fd.APP_A_TGSN_ID ) as id_APP_A_TGSN,
		max(fd.APLIKASI_ID),
	MAX(fd.pertanyaan_keterangan) AS pertanyaan_keterangan,
	MAX(fd.TARIKH_SIASATAN_STRING) as TARIKH_SIASATAN_STRING,
	MAX(fd.STATUS) as ROW_STATUS,
	MAX(fd.COLOR) as ROW_COLOR,
	MAX(fd.FLAG_STATUS) as FLAG_STATUS,
	(MAX(CASE WHEN fd.IS_HAKMILIK_BELUM_TUKARGANTI THEN 1 ELSE 0 END) = 1),
	MAX(fd.BAKI_MASA) as BAKI_MASA,
	max(fd.NO_HAKMILIK_BARU) as NO_HAKMILIK_BARU,
	MAX(fd.MODUL) as MODUL

    FROM FINAL_RESULT fd
    JOIN UMM_APLIKASI ra ON fd.APLIKASI_ID = ra.APLIKASI_ID
    WHERE ra.RANGKAIAN_ID IS NOT NULL
      AND fd.kod_tgsn <> 'IMH'
    GROUP BY ra.RANGKAIAN_ID, fd.kod_tgsn
  ),

  remaining_rows AS (
    SELECT
      fd.TGSN_SEMASA_ID::BIGINT AS ID,
      fd.TRKH_PNRMAN AS TRKH_PEN,
      fd.TARIKH_PENERIMAAN_STRING,
      fd.TARIKH_DAN_MASA_LUPUT_STRING,
      COALESCE(fd.NO_HAKMILIK_DASHBOARD, '-') AS no_hakmilik,
      NULL::TEXT AS rangkaian_id_merged,
      fd.kod_tgsn::TEXT,
      fd.ID_PERMOHONAN_DASHBOARD AS id_permohonan,
      fd.URUSAN_KOD_DASHBOARD AS urusan,
      fd.NO_FAIL_PEMOHON AS NO_FAIL_PEMOHON,
      fd.NO_RESIT_DASHBOARD AS no_resit,
		fd.TGSN_PERIHAL as tugas,
      fd.NAMA_PEMOHON AS NAMA_PEMOHON,
      fd.NAMA_PEJABAT_PENDEK AS PEJABAT,
      fd.ID_PENGHANTARAN AS ID_PENYAMPAIAN,
	fd.APP_A_TGSN_ID as id_APP_A_TGSN,
	fd.APLIKASI_ID,

	fd.pertanyaan_keterangan,
	fd.TARIKH_SIASATAN_STRING as TARIKH_SIASATAN_STRING,
	fd.STATUS as ROW_STATUS,
	fd.COLOR as ROW_COLOR,
	fd.FLAG_STATUS as FLAG_STATUS,
	fd.IS_HAKMILIK_BELUM_TUKARGANTI,
	fd.BAKI_MASA as BAKI_MASA,
	fd.NO_HAKMILIK_BARU as NO_HAKMILIK_BARU,
	fd.MODUL as MODUL

    FROM FINAL_RESULT fd
    LEFT JOIN UMM_APLIKASI ra ON fd.APLIKASI_ID = ra.APLIKASI_ID


  ),

FINAL_V2 AS (
    SELECT DISTINCT ON (merged.id) merged.*
    FROM (
        SELECT * FROM rangkaian_merged
        UNION ALL
        SELECT * FROM remaining_rows
    ) merged

    WHERE (
        var_modul_kod IS NULL
        OR (
            merged.modul = var_modul_kod
            AND (
                var_modul_kod <> 'DFT'
                OR (
                    var_modul_kod = 'DFT'
                    AND merged.id IN (
                        SELECT
                            d.tgsn_semasa_id
                        FROM UMM_TGSN_SEMASA d
                        INNER JOIN UMM_APLIKASI a ON d.aplikasi_id = a.APLIKASI_ID
                        INNER JOIN IND_URSN u ON a.URSN_ID = u.URSN_ID
                        INNER JOIN RJK_JNS_URSN j ON u.JNS_URSN_ID = j.JNS_URSN_ID
                        INNER JOIN IND_MODUL m ON u.MODUL_ID = m.MODUL_ID
                        WHERE
                            m.kod = var_modul_kod
                            AND d.nama_pengguna = var_nama_pengguna
                            AND d.FLAG_TGSN_SISTEM = 'N'
                            AND d.pejabat_id = var_pejabat_id
                            AND d.TGSN_PERIHAL NOT IN ('Kutipan Dokumen', 'Imbasan Dokumen Hakmilik Batal')
                            AND a.status_keputusan <> 'Batal'
                            AND j.kod = var_urusan_mdl_kod
                    )
                )
            )
        )
    )

    ORDER BY merged.id, merged.trkh_pen DESC
),

  params AS (
    SELECT trim(c.col) AS fcol, trim(v.val) AS fval
    FROM unnest(string_to_array(var_filter_colum, ',')) WITH ORDINALITY AS c(col, idx)
    JOIN unnest(string_to_array(var_filter_val, '||')) WITH ORDINALITY AS v(val, idx2)
      ON c.idx = v.idx2
)


SELECT *
FROM FINAL_V2 v2
WHERE
    -- Jika tidak ada filter sama sekali, kembalikan semua
    NOT EXISTS (SELECT 1 FROM params)

    -- Jika ada filter, cocokkan semua kolom
    OR (
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TARIKH_PENERIMAAN_STRING')
         OR v2.TARIKH_PENERIMAAN_STRING ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TARIKH_PENERIMAAN_STRING')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TARIKH_DAN_MASA_LUPUT_STRING')
         OR v2.TARIKH_DAN_MASA_LUPUT_STRING ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TARIKH_DAN_MASA_LUPUT_STRING')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TARIKH_SIASATAN_STRING')
         OR v2.TARIKH_SIASATAN_STRING ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TARIKH_SIASATAN_STRING')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'NO_HAKMILIK')
         OR v2.NO_HAKMILIK ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'NO_HAKMILIK')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'ID_PERMOHONAN')
         OR v2.ID_PERMOHONAN ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'ID_PERMOHONAN')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'NO_FAIL_PEMOHON')
         OR v2.NO_FAIL_PEMOHON ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'NO_FAIL_PEMOHON')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'NO_RESIT')
         OR v2.NO_RESIT ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'NO_RESIT')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'URUSAN')
         OR v2.URUSAN ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'URUSAN')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'NAMA_PEMOHON')
         OR v2.NAMA_PEMOHON ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'NAMA_PEMOHON')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'PERTANYAAN_KETERANGAN')
         OR v2.PERTANYAAN_KETERANGAN ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'PERTANYAAN_KETERANGAN')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TUGAS')
         OR v2.TUGAS ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TUGAS')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'PEJABAT')
         OR v2.PEJABAT ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'PEJABAT')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'ID_PENYAMPAIAN')
         OR v2.ID_PENYAMPAIAN ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'ID_PENYAMPAIAN')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TUGASAN')
         OR v2.TUGAS ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TUGASAN')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'FLAG_STATUS')
         OR v2.FLAG_STATUS ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'FLAG_STATUS')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'BAKI_MASA')
         OR v2.BAKI_MASA ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'BAKI_MASA')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TUGAS_AND_PERTANYAAN')
         OR (v2.TUGAS ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TUGAS_AND_PERTANYAAN'))
             OR v2.PERTANYAAN_KETERANGAN ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TUGAS_AND_PERTANYAAN'))))
    )

 ORDER BY
  -- Default fallback kalau tidak ada kolom urutan diberikan
  CASE
    WHEN var_sort_colum IS NULL THEN V2.TARIKH_PENERIMAAN_STRING
  END ASC,

  -- Jika kolom urutan diberikan, gunakan CASE berdasarkan nama kolom dan tipe sort
  CASE WHEN var_sort_colum = 'TARIKH_PENERIMAAN_STRING' AND var_sort_type = 'ASC' THEN V2.TRKH_PEN END ASC,
  CASE WHEN var_sort_colum = 'TARIKH_PENERIMAAN_STRING' AND var_sort_type = 'DESC' THEN V2.TRKH_PEN END DESC,

  CASE WHEN var_sort_colum = 'TARIKH_DAN_MASA_LUPUT_STRING' AND var_sort_type = 'ASC' THEN V2.TARIKH_DAN_MASA_LUPUT_STRING END ASC,
  CASE WHEN var_sort_colum = 'TARIKH_DAN_MASA_LUPUT_STRING' AND var_sort_type = 'DESC' THEN V2.TARIKH_DAN_MASA_LUPUT_STRING END DESC,

  CASE WHEN var_sort_colum = 'TARIKH_SIASATAN_STRING' AND var_sort_type = 'ASC' THEN V2.TARIKH_SIASATAN_STRING END ASC,
  CASE WHEN var_sort_colum = 'TARIKH_SIASATAN_STRING' AND var_sort_type = 'DESC' THEN V2.TARIKH_SIASATAN_STRING END DESC,

  CASE WHEN var_sort_colum = 'NO_HAKMILIK' AND var_sort_type = 'ASC' THEN V2.NO_HAKMILIK END ASC,
  CASE WHEN var_sort_colum = 'NO_HAKMILIK' AND var_sort_type = 'DESC' THEN V2.NO_HAKMILIK END DESC,

  CASE WHEN var_sort_colum = 'KOD_TGSN' AND var_sort_type = 'ASC' THEN V2.KOD_TGSN END ASC,
  CASE WHEN var_sort_colum = 'KOD_TGSN' AND var_sort_type = 'DESC' THEN V2.KOD_TGSN END DESC,

  CASE WHEN var_sort_colum = 'ID_PERMOHONAN' AND var_sort_type = 'ASC' THEN V2.ID_PERMOHONAN END ASC,
  CASE WHEN var_sort_colum = 'ID_PERMOHONAN' AND var_sort_type = 'DESC' THEN V2.ID_PERMOHONAN END DESC,

  CASE WHEN var_sort_colum = 'URUSAN' AND var_sort_type = 'ASC' THEN V2.URUSAN END ASC,
  CASE WHEN var_sort_colum = 'URUSAN' AND var_sort_type = 'DESC' THEN V2.URUSAN END DESC,

  CASE WHEN var_sort_colum = 'NO_FAIL_PEMOHON' AND var_sort_type = 'ASC' THEN V2.NO_FAIL_PEMOHON END ASC,
  CASE WHEN var_sort_colum = 'NO_FAIL_PEMOHON' AND var_sort_type = 'DESC' THEN V2.NO_FAIL_PEMOHON END DESC,

  CASE WHEN var_sort_colum = 'NO_RESIT' AND var_sort_type = 'ASC' THEN V2.NO_RESIT END ASC,
  CASE WHEN var_sort_colum = 'NO_RESIT' AND var_sort_type = 'DESC' THEN V2.NO_RESIT END DESC,

  CASE WHEN var_sort_colum = 'TUGAS' AND var_sort_type = 'ASC' THEN V2.TUGAS END ASC,
  CASE WHEN var_sort_colum = 'TUGAS' AND var_sort_type = 'DESC' THEN V2.TUGAS END DESC,

  CASE WHEN var_sort_colum = 'NAMA_PEMOHON' AND var_sort_type = 'ASC' THEN V2.NAMA_PEMOHON END ASC,
  CASE WHEN var_sort_colum = 'NAMA_PEMOHON' AND var_sort_type = 'DESC' THEN V2.NAMA_PEMOHON END DESC,

  CASE WHEN var_sort_colum = 'PEJABAT' AND var_sort_type = 'ASC' THEN V2.PEJABAT END ASC,
  CASE WHEN var_sort_colum = 'PEJABAT' AND var_sort_type = 'DESC' THEN V2.PEJABAT END DESC,

  CASE WHEN var_sort_colum = 'PERTANYAAN_KETERANGAN' AND var_sort_type = 'ASC' THEN V2.PERTANYAAN_KETERANGAN END ASC,
  CASE WHEN var_sort_colum = 'PERTANYAAN_KETERANGAN' AND var_sort_type = 'DESC' THEN V2.PERTANYAAN_KETERANGAN END DESC,

  CASE WHEN var_sort_colum = 'ID_PENYAMPAIAN' AND var_sort_type = 'ASC' THEN V2.ID_PENYAMPAIAN END ASC,
  CASE WHEN var_sort_colum = 'ID_PENYAMPAIAN' AND var_sort_type = 'DESC' THEN V2.ID_PENYAMPAIAN END DESC,

	CASE WHEN var_sort_colum = 'BAKI_MASA' AND var_sort_type = 'ASC' THEN V2.BAKI_MASA END ASC,
  CASE WHEN var_sort_colum = 'BAKI_MASA' AND var_sort_type = 'DESC' THEN V2.BAKI_MASA END DESC,


  CASE WHEN var_sort_colum = 'TUGAS_AND_PERTANYAAN' AND var_sort_type = 'ASC' THEN V2.TUGAS END ASC,
  CASE WHEN var_sort_colum = 'TUGAS_AND_PERTANYAAN' AND var_sort_type = 'DESC' THEN V2.TUGAS END DESC



	LIMIT CASE WHEN NOT var_export AND var_limit IS NOT NULL THEN var_limit ELSE NULL
	END
	OFFSET CASE WHEN NOT var_export AND var_offset IS NOT NULL THEN var_offset ELSE 0
	END;


END;
$function$
;

-- DROP FUNCTION et_main_uat.get_dashboard_by_pengguna_v2(numeric, numeric, _text, text, numeric, text, text, text, text, bool, text, text, text, text);

CREATE OR REPLACE FUNCTION et_main_uat.get_dashboard_by_pengguna_v2(var_limit numeric DEFAULT NULL::numeric, var_offset numeric DEFAULT NULL::numeric, var_urusan_kod_list text[], var_nama_pengguna text DEFAULT NULL::text, var_pejabat_id numeric DEFAULT NULL::numeric, var_modul_kod text DEFAULT NULL::text, var_urusan_mdl_kod text DEFAULT NULL::text, var_status_tugasan text DEFAULT NULL::text, var_id_pengenalan text DEFAULT NULL::text, var_export boolean DEFAULT false, var_sort_colum text DEFAULT NULL::text, var_sort_type text DEFAULT NULL::text, var_filter_colum text DEFAULT NULL::text, var_filter_val text DEFAULT NULL::text)
 RETURNS TABLE(id bigint, trkh_pen timestamp without time zone, tarikh_penerimaan_string text, tarikh_dan_masa_luput_string text, no_hakmilik text, rangkaian_id_merged text, kod_tgsn text, id_permohonan text, urusan text, no_fail_pemohon text, no_resit text, tugas text, nama_pemohon text, pejabat text, id_penyampaian text, id_app_a_tgsn numeric, id_app_aplikasi numeric, pertanyaan_keterangan text, tarikh_siasatan_string text, row_status text, row_color text, flag_status text, is_hakmilik_belum_tukarganti boolean, baki_masa text, no_hakmilik_baru text, modul text)
 LANGUAGE plpgsql
AS $function$
BEGIN
  RETURN QUERY
WITH VAR_URUSAN_KOD_LIST AS (
    SELECT UNNEST(var_urusan_kod_list) AS KOD
  ),
VAR_PERANAN_KOD_PENGGUNA AS (
  SELECT DISTINCT PP.NAMA_PENGGUNA, RM.KOD AS PERANAN_KOD
  FROM PCP_CAPAIAN_PENGGUNA CP
  JOIN PCP_PENGGUNA PP ON CP.PENGGUNA_ID = PP.PENGGUNA_ID
  JOIN PCP_PERANAN_MODUL PM ON CP.PERANAN_MODUL_ID = PM.PERANAN_MODUL_ID
  JOIN RJK_SENARAI_AHLI_KUMPULAN RM ON PM.PERANAN_ID = RM.SENARAI_AHLI_KUMPULAN_ID
  WHERE PP.NAMA_PENGGUNA IN (var_nama_pengguna)
),
VAR_DAERAH_PENGGUNA AS (
    SELECT DISTINCT DAERAH_ID
    FROM IND_PEJABAT AS IP
    WHERE PEJABAT_ID IN (var_pejabat_id) 
),
VAR_PEJABAT_TERKAIT AS (
    SELECT DISTINCT PEJABAT_ID
    FROM IND_PEJABAT AS IP
    WHERE DAERAH_ID IN (SELECT DAERAH_ID FROM VAR_DAERAH_PENGGUNA)
),
VAR_FILTER_TUGASAN_KOD_SET AS (
	SELECT UNNEST(ARRAY['PPBKRPJPM', 'PPBKRKPJPM', 'PTB', 'SJR',
    'PJR', 'CTK_JR', 'PMMP6PTB2', 'PPBBPTB2',
    'PPHSYBPTB2', 'PKJR', 'PKJRPP']) as stgsn_kod
),

VAR_PELUPUSAN_TUGASAN_FILTERED AS (
  SELECT ID_TGSN AS ID_TGSN_PELUPUSAN_PENGGUNA_FILTER
  FROM (
    SELECT A.ID_TGSN,
        ROW_NUMBER() OVER (
            PARTITION BY COALESCE(C.kod, E.kod), A.ID_TGSN
            ORDER BY A.ID_TGSN
    ) AS RN
    FROM UMM_TGSN_SEMASA A
    LEFT JOIN UMM_APLIKASI B ON B.APLIKASI_ID = A.APLIKASI_ID
    LEFT JOIN IND_URSN C ON C.URSN_ID = B.URSN_ID
    LEFT JOIN UMM_P_APLIKASI D ON D.APLIKASI_ID = A.APLIKASI_ID
    LEFT JOIN IND_URSN E ON E.URSN_ID = D.URSN_ID
    WHERE A.MODUL = 'PLP'
      AND A.KOD_TGSN = 'FPIKM'
      AND UPPER(A.FLAG_TGSN_SISTEM) = 'N'
  ) A
  WHERE RN = 1
),
VAR_PEJABAT_PERANAN_MAP AS (
  SELECT * FROM (VALUES
    ('TRG', ARRAY['PTG', 'TPTG', 'KPP']),
    ('PRK', ARRAY['PTG', 'KPP']),
    ('SEL', ARRAY['PTG', 'TPTG'])
  ) AS T (KOD_PEJABAT, PERANANS)
),
VAR_PLP_TUGASAN_KOD_SET AS (
    SELECT unnest(ARRAY['PDKM', 'SDKM', 'SDKM2', 'SDKM3', 'PPKM', 'CKM', 'CKMPPLN'])
),
VAR_ALSAN_TUKARGANTI_KOD_SET AS (
    SELECT unnest(ARRAY['KMPP', 'HMSC', 'HMSTP', 'PRBB', 'OPRBB', 'HDHD', 'HMPV', 'HMV', 'HMVB',
            'SSHM', 'SSSC', 'SW', 'SA', 'CRHMB', 'CSHMB', 'BETUL', 'PACT', 'PKH', 'PMKMH', 'PFT', 'REM', 'REMITAN'])
),
VAR_GROUP_BY_NO_FAIL_TUGASAN_KOD_SET AS (
    SELECT unnest(ARRAY['PPBKRPDPJPM', 'PPBKRSDPJPM', 'PPBKRCDPJPM'])
),

VAR_ALSAN_TUKARGANTI_KOD_SET_BATAL AS (
    SELECT unnest(ARRAY['HDHK', 'HPLN','PMKMH','HSSTB','HKSSS'])
),
VAR_NO_HAK_MILIK_BARU AS (
    SELECT 
        mohon.APLIKASI_ID,
        STRING_AGG(mohon.id_hkmlk, '<br>') AS NO_HAKMILIK_BARU
    FROM dft_A_MOHON_HKMLK mohon
    JOIN UMM_APLIKASI appl ON appl.APLIKASI_ID = mohon.APLIKASI_ID
    JOIN IND_URSN urusan ON appl.URSN_ID = urusan.URSN_ID
    JOIN rjk_jns_ursn jenis ON jenis.jns_ursn_id = urusan.jns_ursn_id
    WHERE mohon.id_hkmlk IS NOT NULL
      AND jenis.KOD = 'MH'
    GROUP BY mohon.APLIKASI_ID
),
MAIN_QUERY AS (
	SELECT 
  	DHAS_1.TGSN_SEMASA_ID,
	DHAS_1.TRKH_PNRMAN,
	DHAS_1.MODUL,
	DHAS_1.ID_HKMLK,
	DHAS_1.NO_RESIT,
	DHAS_1.LOCKED_BY,
	DHAS_1.LOCKED_DATE,
	DHAS_1.PERANAN,
	DHAS_1.KOD_TGSN,
	DHAS_1.ID_TGSN,
	DHAS_1.TGSN_PERIHAL,
	DHAS_1.NAMA_PENGGUNA,
	APP_TGSN_1.TRKH_TETAP,
	APP_1.TRKH_PIAGAM,
	APP_1.APLIKASI_ID,
	APP_1.APLIKASI_ID as APP_ID,
	APP_1.RANGKAIAN_ID,
	APP_1.ID_PENGENALAN,
	APP_1.FLAG_INTEGRASI,
	APP_1.STATUS_KEPUTUSAN,
	APP_1.FAIL_INDUK,
	COALESCE(APP_1.STATUS_PROSES, SNR_1.NAMA) AS STATUS_PROSES,
    COALESCE(URSN_1.KOD, URSN_2.KOD) AS URUSAN_KOD,
    COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI) AS NO_RUJUKAN,
	IPJ_1.NAMA_PENDEK,
	IPJ_1.KOD AS PEJABAT_KOD,
	HNTR_1.ID_PENGHANTARAN,
	DHAS_1.a_tgsn_id as APP_A_TGSN_ID,
	IPJ_1.NAMA_PENDEK as NAMA_PEJABAT_PENDEK,
	TO_CHAR(MLS.TRKH_SIASATAN, 'DD/MM/YYYY') AS TARIKH_SIASATAN_STRING,
	APP_1.ID_RUJUKAN_SMARTBOX,
	DHAS_1.TRKH_KPI AS DHAS_1_TRKH_KPI,
	ITG_1.MINIT_KPI,
	CASE 
      WHEN URSN_1.KOD = 'PSBS' AND DHAS_1.TGSN_PERIHAL = 'Penyediaan Fail Induk Kertas Mesyuarat' THEN FALSE
      ELSE TRUE 
    END AS SHOW_ID_HAKMILIK,
	(
      SELECT STRING_AGG(mohon.id_hkmlk, '<br>')
      FROM dft_A_MOHON_HKMLK mohon
      JOIN UMM_APLIKASI appl ON appl.APLIKASI_ID = mohon.APLIKASI_ID
      JOIN IND_URSN urusan ON appl.URSN_ID = urusan.URSN_ID
      JOIN rjk_jns_ursn jenis ON jenis.jns_ursn_id = urusan.jns_ursn_id
      WHERE mohon.APLIKASI_ID = DHAS_1.APLIKASI_ID
        AND mohon.id_hkmlk IS NOT NULL
        AND jenis.KOD = CAST('MH' AS VARCHAR)
    ) AS NO_HAKMILIK_BARU,
	
	CASE 
		WHEN DHAS_1.TRKH_KPI IS NULL 
		     AND ITG_1.MINIT_KPI IS NOT NULL 
		     AND DHAS_1.TRKH_PNRMAN IS NOT NULL
		THEN DHAS_1.TRKH_PNRMAN + (ITG_1.MINIT_KPI || ' minutes')::INTERVAL
		ELSE DHAS_1.TRKH_KPI
	END AS TRKH_KPI,
	CASE 
		WHEN APP_TGSN_1.STATUS_TUGASAN IS NULL OR DHAS_1.TGSN_PERIHAL = 'Pengagihan Tugasan Baru' 
		THEN 'Baru'
		ELSE APP_TGSN_1.STATUS_TUGASAN
	END AS STATUS_TUGASAN,

	CASE 
		WHEN ITG_1.MINIT_KPI IS NOT NULL THEN TRUE
		ELSE FALSE
	END AS SHOW_KPI,
	CASE 
    WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
         AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
              OR DHAS_1.KOD_TGSN LIKE '%PTB%')
    THEN '-' 
    ELSE TO_CHAR(DHAS_1.TRKH_PNRMAN, 'DD/MM/YYYY')
	END AS TARIKH_PENERIMAAN_STRING,

	CASE 
	
		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
			AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
				OR DHAS_1.KOD_TGSN LIKE '%PTB%')
		THEN '-' 

		ELSE TO_CHAR(
			CASE
			WHEN ITG_1.MINIT_KPI IS NOT NULL 
				AND DHAS_1.TRKH_PNRMAN IS NOT NULL 
				AND DHAS_1.TRKH_KPI IS NULL
			THEN DHAS_1.TRKH_PNRMAN + (ITG_1.MINIT_KPI || ' minutes')::INTERVAL
			ELSE DHAS_1.TRKH_KPI
			END,
			'DD/MM/YYYY'
		)
	END AS TARIKH_DAN_MASA_LUPUT_STRING,
	CASE
  		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL
       AND (
         DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
         OR DHAS_1.KOD_TGSN LIKE '%PTB%'
       )
	THEN NULL
	ELSE
		CASE
		WHEN ITG_1.MINIT_KPI IS NOT NULL
			AND DHAS_1.TRKH_PNRMAN IS NOT NULL
			AND DHAS_1.TRKH_KPI IS NULL
		THEN DHAS_1.TRKH_PNRMAN + (ITG_1.MINIT_KPI || ' minutes')::INTERVAL
		ELSE DHAS_1.TRKH_KPI
		END
	END AS TARIKH_DAN_MASA_LUPUT,

	CASE 
		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
			AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
				OR DHAS_1.KOD_TGSN LIKE '%PTB%')
		THEN '-' 
		ELSE TO_CHAR(APP_1.TRKH_PIAGAM, 'DD/MM/YYYY')
	END AS TARIKH_PIAGAM_STRING,
	CASE 
		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
			AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
				OR DHAS_1.KOD_TGSN LIKE '%PTB%')
		THEN '-' 
		ELSE TO_CHAR(APP_TGSN_1.TRKH_TETAP, 'DD/MM/YYYY')
	END AS TARIKH_MULA_STRING,
	CASE 
		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
			AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
				OR DHAS_1.KOD_TGSN LIKE '%PTB%')
		THEN TRUE 
		ELSE FALSE 
	END AS IS_FILTER_TUGASAN,
	CASE
		WHEN ITG_1.MINIT_KPI IS NOT NULL 
			AND DHAS_1.TRKH_PNRMAN IS NOT NULL 
			AND DHAS_1.TRKH_KPI IS NULL
		THEN DHAS_1.TRKH_PNRMAN + (ITG_1.MINIT_KPI || ' minutes')::INTERVAL
		ELSE DHAS_1.TRKH_KPI
	END AS TARIKH_KPI,
	

	CASE 
	  WHEN NOT (
	    TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
	    AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
	         OR DHAS_1.KOD_TGSN LIKE '%PTB%')
	  )
	  THEN 
	    CASE 
	      WHEN COALESCE(NULLIF(TRIM(DHAS_1.ID_HKMLK), ''), '-') = '-' THEN '-'
	      ELSE (
	        SELECT 
	          CASE 
	            WHEN COUNT(*) > 10 
	            THEN (
	              SELECT string_agg(val, ', ') || '...'
	              FROM (
	                SELECT DISTINCT val
	                FROM unnest(string_to_array(DHAS_1.ID_HKMLK, ',')) AS val
	                ORDER BY val
	                LIMIT 10
	              ) sub
	            )
	            ELSE (
	              SELECT string_agg(DISTINCT val, ', ' ORDER BY val)
	              FROM unnest(string_to_array(DHAS_1.ID_HKMLK, ',')) AS val
	            )
	          END
	      )
	    END
	  ELSE COALESCE(NULLIF(TRIM(DHAS_1.ID_HKMLK), ''), '-') 
	END AS NO_HAKMILIK_DASHBOARD,
	CASE 
	  WHEN NOT (
	    TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
	    AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
	         OR DHAS_1.KOD_TGSN LIKE '%PTB%')
	  )
	  THEN COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
	  ELSE NULL
	END AS APLIKASI_NO_PERMOHONAN,
	
	
	CASE 
	  WHEN NOT (
	    TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
	    AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
	         OR DHAS_1.KOD_TGSN LIKE '%PTB%')
	  )
		  THEN 
		    CASE 
		      WHEN COALESCE(NULLIF(TRIM(DHAS_1.NO_RESIT), ''), '-') = '-' THEN '-'
		      ELSE (
		        SELECT 
		          CASE 
		            WHEN COUNT(*) > 10 
		            THEN (
		              SELECT string_agg(val, ', ') || '...'
		              FROM (
		                SELECT DISTINCT val
		                FROM unnest(string_to_array(DHAS_1.NO_RESIT, ',')) AS val
		                ORDER BY val
		                LIMIT 10
		              ) sub
		            )
		            ELSE (
		              SELECT string_agg(DISTINCT val, ', ' ORDER BY val)
		              FROM unnest(string_to_array(DHAS_1.NO_RESIT, ',')) AS val
		            )
		          END
		      )
		    END
		  ELSE COALESCE(NULLIF(TRIM(DHAS_1.NO_RESIT), ''), '-') 
		END AS NO_RESIT_DASHBOARD,
		
		
		CASE
		  WHEN NOT (
		    TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
		    AND (
		      DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
		      OR DHAS_1.KOD_TGSN LIKE '%PTB%'
		    )
		  )
		  THEN
		    CASE 
		      WHEN HNTR_1.ID_PENGHANTARAN IS NOT NULL AND HNTR_1.ID_PENGHANTARAN LIKE 'PNL/%'
		        THEN 'UPNL'
		      ELSE COALESCE(URSN_1.KOD, URSN_2.KOD)
		    END
		  ELSE
		    COALESCE(URSN_1.KOD, URSN_2.KOD)
		END AS URUSAN_KOD_DASHBOARD,

		CASE
		  WHEN UPPER(APP_1.FLAG_INTEGRASI) ='Y' THEN
		    CASE
		      WHEN COALESCE(COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI), '') LIKE '%MF%' 
		           AND COALESCE(COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI), '') LIKE '%(%' THEN
		        SPLIT_PART(COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI), '(', 1)
		        
		      WHEN COALESCE(APP_1.URSN_ID, URSN_2.URSN_ID) IS NOT NULL 
		           AND COALESCE(URSN_1.KOD, URSN_2.KOD) = 'KVSP' THEN
		        (
		          SELECT hubungan2.ID_PENGENALAN || ' / ' || COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
		          FROM UMM_APLIKASI hubungan1
		          JOIN UMM_APLIKASI hubungan2 ON hubungan1.ID_PENGENALAN = hubungan2.APLIKASI_ID
		          WHERE hubungan1.APLIKASI_ID = APP_1.APLIKASI_ID
		          LIMIT 1
		        )
		        
		      ELSE
		        (
		          SELECT hubungan.no_rujukan_fail || ' / ' || COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
		          FROM UMM_APLIKASI hubungan
		          WHERE hubungan.APLIKASI_ID = APP_1.APLIKASI_ID
		          LIMIT 1
		        )
		    END
		  WHEN DHAS_1.KOD_TGSN  = 'STRSPRAP' THEN
		    APP_A_1.ID_TRANSAKSI

		   WHEN COALESCE(URSN_1.KOD, URSN_2.KOD) IN ('HDHK', 'HDHD', 'KVSPM')
			AND NOT (
			DHAS_1.MODUL = 'PNT'
			AND HNTR_1.ID_PENGHANTARAN LIKE 'PNL/%'
			AND APP_1.MKLMT_TMBHN IS NOT NULL
			AND APP_1.MKLMT_TMBHN::jsonb ->> 'idPengenalanInduk' IS NOT NULL
			)
		THEN
			COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI) || 
			' ' || (
			SELECT ID_PENGENALAN 
			FROM UMM_APLIKASI 
			WHERE NO_RUJUKAN_FAIL = COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
			LIMIT 1
			)

			WHEN DHAS_1.MODUL = 'PNT'
				AND HNTR_1.ID_PENGHANTARAN LIKE 'PNL/%'
				AND APP_1.MKLMT_TMBHN IS NOT NULL
				AND APP_1.MKLMT_TMBHN::jsonb ->> 'idPengenalanInduk' IS NOT NULL
			THEN
				APP_1.MKLMT_TMBHN::jsonb ->> 'idPengenalanInduk'

		ELSE
		    COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
		END AS ID_PERMOHONAN_DASHBOARD,
	
		  CASE
		    WHEN DHAS_1.kod_tgsn IN ('PPF', 'PPJUB', 'PPPK', 'PPSYT') THEN org_nama.nama
		    WHEN URSN_1.kod = 'PPLBL' THEN pelelong_nama.nama_pemohon
		    ELSE bkptg_nama.nama
		  END AS NAMA_PEMOHON,
		  COALESCE(KS.NO_KERTAS_SIASATAN, APP_1.NO_RUJUKAN_FAIL, '') as NO_FAIL_PEMOHON
	



FROM UMM_TGSN_SEMASA DHAS_1

LEFT JOIN UMM_APLIKASI APP_1 ON DHAS_1.APLIKASI_ID = APP_1.APLIKASI_ID
LEFT JOIN UMM_APLIKASI APP_2 ON DHAS_1.APLIKASI_ID = APP_2.APLIKASI_ID
LEFT JOIN IND_URSN URSN_1 ON APP_2.URSN_ID = URSN_1.URSN_ID

LEFT JOIN UMM_APLIKASI APP_3 ON DHAS_1.APLIKASI_ID = APP_3.APLIKASI_ID
LEFT JOIN UMM_APLIKASI APP_4 ON APP_3.HUBUNGAN_APLIKASI_ID = APP_4.APLIKASI_ID

LEFT JOIN UMM_P_APLIKASI APP_A_1 ON DHAS_1.P_APLIKASI_ID = APP_A_1.P_APLIKASI_ID
LEFT JOIN UMM_P_APLIKASI APP_A_2 ON DHAS_1.P_APLIKASI_ID = APP_A_2.P_APLIKASI_ID
LEFT JOIN IND_URSN URSN_2 ON APP_A_2.URSN_ID = URSN_2.URSN_ID
LEFT JOIN UMM_P_APLIKASI APP_A_3 ON DHAS_1.P_APLIKASI_ID = APP_A_3.P_APLIKASI_ID

LEFT JOIN RJK_SENARAI_AHLI_KUMPULAN SNR_1 ON APP_A_3.STATUS_ID = SNR_1.SENARAI_AHLI_KUMPULAN_ID

LEFT JOIN UMM_A_TGSN APP_TGSN_1 ON DHAS_1.A_TGSN_ID = APP_TGSN_1.A_TGSN_ID
LEFT JOIN UMM_A_TGSN APP_TGSN_2 ON DHAS_1.A_TGSN_ID = APP_TGSN_2.A_TGSN_ID
LEFT JOIN IND_TGSN ITG_1 ON APP_TGSN_2.TGSN_ID = ITG_1.TGSN_ID

LEFT JOIN UMM_A_TGSN APP_A_4 ON DHAS_1.A_TGSN_ID = APP_A_4.A_TGSN_ID
LEFT JOIN PCP_PENGGUNA PGN_1 ON APP_A_4.PENGGUNA_SEMASA_ID = PGN_1.PENGGUNA_ID

LEFT JOIN UMM_MKLMT_LAPORAN_SIASATAN MLS ON DHAS_1.MKLMT_LAPORAN_SIASATAN_ID = MLS.MKLMT_LAPORAN_SIASATAN_ID

LEFT JOIN IND_PEJABAT IPJ_1 ON DHAS_1.PEJABAT_ID = IPJ_1.PEJABAT_ID
LEFT JOIN UMM_HANTARAN_NOTIS HNTR_1 ON DHAS_1.HANTARAN_NOTIS_ID = HNTR_1.HANTARAN_NOTIS_ID
LEFT JOIN PKS_A_KERTAS_SIASATAN KS ON DHAS_1.A_KERTAS_SIASATAN_ID = KS.A_KERTAS_SIASATAN_ID

LEFT JOIN LATERAL (
	  SELECT o.nama
	  FROM umm_p_daftar_organisasi o
	  WHERE o.p_daftar_organisasi_id IN (
	    SELECT MIN(o2.p_daftar_organisasi_id)
	    FROM umm_p_daftar_organisasi o2
	    --WHERE APP_A_1.id_transaksi = APP_1.id_pengenalan
	    WHERE APP_A_1.P_APLIKASI_ID = DHAS_1.P_APLIKASI_ID
	  )
	  LIMIT 1
	) AS org_nama ON DHAS_1.kod_tgsn IN ('PPF', 'PPJUB', 'PPPK', 'PPSYT')
	

	LEFT JOIN LATERAL (
	  SELECT p.nama_pemohon
	  FROM llg_a_daftar_pelelong p
	  WHERE p.aplikasi_id = DHAS_1.aplikasi_id
	  ORDER BY p.a_daftar_pelelong_id ASC
	  LIMIT 1
	) AS pelelong_nama ON URSN_1.kod = 'PPLBL'
	
	LEFT JOIN LATERAL (
	  SELECT r.nama
	  FROM umm_a_pihak_bkptg r
	  WHERE r.aplikasi_id = DHAS_1.aplikasi_id
	    AND UPPER(r.flag_pemohon) = 'Y'
	  ORDER BY r.a_pihak_bkptg_id ASC
	  LIMIT 1
	) AS bkptg_nama ON TRUE
  	
	WHERE UPPER(DHAS_1.FLAG_TGSN_SISTEM) = 'N'
	AND (DHAS_1.NAMA_PENGGUNA = var_nama_pengguna OR DHAS_1.NAMA_PENGGUNA IS NULL)
	AND (EXISTS (
        SELECT 1 FROM VAR_PERANAN_KOD_PENGGUNA PKP
        WHERE PKP.NAMA_PENGGUNA = DHAS_1.NAMA_PENGGUNA AND PKP.peranan_kod = 'PTG'
    	) OR DHAS_1.PEJABAT_ID IN (SELECT PEJABAT_ID FROM VAR_PEJABAT_TERKAIT) OR DHAS_1.PEJABAT_ID IS NULL
	)

	AND (
		URSN_1.KOD IN (SELECT KOD FROM VAR_URUSAN_KOD_LIST)
		OR URSN_2.KOD IN (SELECT KOD FROM VAR_URUSAN_KOD_LIST)
	)

	AND EXISTS ( 
		SELECT 1
		FROM VAR_PERANAN_KOD_PENGGUNA PKP
		WHERE DHAS_1.PERANAN LIKE '%-' || PKP.PERANAN_KOD || '-%'
	)
	AND (APP_TGSN_1.A_TGSN_ID is null or APP_TGSN_1.A_TGSN_ID is not null )
	--IF 
		AND (
		    var_modul_kod IS NULL 
		    OR DHAS_1.modul = var_modul_kod
		)
		
		AND (
		    var_urusan_mdl_kod IS NULL
		    OR (
		        var_modul_kod IS DISTINCT FROM 'DFT'
		        AND COALESCE(URSN_1.KOD, URSN_2.KOD) = var_urusan_mdl_kod
		    )
		)
	-- END 
	),

VAR_GROUPED_TUGAS AS (
    SELECT
        mq.*,
        ROW_NUMBER() OVER (PARTITION BY ua.no_fail, mq.kod_tgsn ORDER BY mq.tgsn_semasa_id) AS rn
    FROM MAIN_QUERY mq
    LEFT JOIN umm_aplikasi ua ON mq.aplikasi_id = ua.aplikasi_id
    WHERE mq.kod_tgsn IN ('PPBKRPDPJPM', 'PPBKRSDPJPM', 'PPBKRCDPJPM') 
),
VAR_MODUL_PENGGUNA AS (
  SELECT DISTINCT p.nama_pengguna, m.kod AS modul_kod
  FROM pcp_capaian_pengguna cp
  JOIN pcp_pengguna p ON cp.pengguna_id = p.pengguna_id
  JOIN pcp_peranan_modul pm ON cp.peranan_modul_id = pm.peranan_modul_id
  JOIN ind_modul m ON pm.modul_id = m.modul_id
  WHERE p.nama_pengguna IN (var_nama_pengguna) 
    AND m.kod IN ('PNT', 'UAM')
),

VAR_BELUM_TUKAR_GANTI AS (
 SELECT unnest(ARRAY['HMSC', 'HMSTP', 'PRBB', 'OPRBB', 'HDHD', 'HMPV', 'HMV','HMVB','SSHM','SSSC','SW','SA','CRHMB','CSHMB','BETUL','PACT','PKH','PMKMH','PFT','REM','REMITAN'])
),
FINAL_QUERY_V1 AS (
	SELECT * FROM MAIN_QUERY AS DEFAULT_MAIN_PNT
	WHERE EXISTS (
	    SELECT 1
	    FROM VAR_MODUL_PENGGUNA mp
	    WHERE mp.nama_pengguna = DEFAULT_MAIN_PNT.nama_pengguna
	      OR DEFAULT_MAIN_PNT.modul IN ('PNT', 'UAM')
	  )
	AND DEFAULT_MAIN_PNT.kod_tgsn NOT IN ('KD', 'STRKD')
		AND NOT (
		  DEFAULT_MAIN_PNT.modul = 'CON'
		  AND DEFAULT_MAIN_PNT.kod_tgsn IN ('CSK', 'JSK')
		)
	UNION ALL
	SELECT * FROM MAIN_QUERY AS DEFAULT_MAIN
	WHERE DEFAULT_MAIN.KOD_TGSN NOT IN ('KD', 'STRKD')
	AND NOT (
	    DEFAULT_MAIN.MODUL = 'CON' AND 
	    (DEFAULT_MAIN.KOD_TGSN = 'CSK' OR DEFAULT_MAIN.KOD_TGSN = 'JSK')
	)
	AND DEFAULT_MAIN.MODUL NOT IN ('PNT', 'UAM')
	AND NOT (
	    DEFAULT_MAIN.kod_tgsn IN ('KD', 'STRKD')
	    OR (DEFAULT_MAIN.NAMA_PENGGUNA IS NOT NULL AND DEFAULT_MAIN.NAMA_PENGGUNA <> var_nama_pengguna)
	)
--new

--==========
--
	AND NOT (
	    DEFAULT_MAIN.KOD_TGSN = 'PTBUT'
	    AND DEFAULT_MAIN.URUSAN_KOD IN ('PMQFT', 'PMQTFT')
	)
--==========

),

FIANL_QUERY_MERGE as (
	select * FROM FINAL_QUERY_V1 as FN_Q1
	WHERE NOT EXISTS (
		SELECT 1
   		FROM VAR_FILTER_TUGASAN_KOD_SET 
		 WHERE
	      (
	        stgsn_kod = 'PTB'
	        AND FN_Q1.KOD_TGSN LIKE '%' || stgsn_kod || '%'
	      )
			OR (
		    stgsn_kod <> 'PTB'
			  AND FN_Q1.KOD_TGSN = stgsn_kod
			)
	)

 	UNION ALL
	SELECT * from (

		SELECT DISTINCT ON (FN_Q1_v2.KOD_TGSN) FN_Q1_v2.*
		FROM FINAL_QUERY_V1 as FN_Q1_v2
		WHERE EXISTS (
			 SELECT 1
      		FROM VAR_FILTER_TUGASAN_KOD_SET
			where (
					UPPER(FN_Q1_v2.STATUS_PROSES) <> 'GANTUNG'

					AND (
			          (stgsn_kod = 'PTB' AND FN_Q1_v2.KOD_TGSN LIKE '%' || stgsn_kod || '%')
			          OR (stgsn_kod = 'SJR' AND FN_Q1_v2.KOD_TGSN LIKE '%' || stgsn_kod || '%')
			          OR (stgsn_kod = 'CTK_JR' AND FN_Q1_v2.KOD_TGSN LIKE '%' || stgsn_kod || '%')
			          OR (stgsn_kod = 'PJR' AND FN_Q1_v2.KOD_TGSN LIKE '%' || stgsn_kod || '%')
			          OR (
			            stgsn_kod NOT IN ('PTB', 'SJR', 'CTK_JR', 'PJR')
			            AND FN_Q1_v2.KOD_TGSN = stgsn_kod
			          )
			        )
			) order by FN_Q1_v2.KOD_TGSN, FN_Q1_v2.tgsn_semasa_id desc
		) limit 1 
	)

),
VAR_USER_PERANAN AS (
  SELECT 
    LOWER(mdl.kod) AS modul,
    LOWER(sak.kod) AS peranan
  FROM pcp_capaian_pengguna cp
  JOIN pcp_pengguna pg ON cp.pengguna_id = pg.pengguna_id
  JOIN pcp_peranan_modul pm ON cp.peranan_modul_id = pm.peranan_modul_id
  JOIN ind_modul mdl ON pm.modul_id = mdl.modul_id
  JOIN rjk_senarai_ahli_kumpulan sak ON pm.peranan_id = sak.senarai_ahli_kumpulan_id
  WHERE pg.nama_pengguna = var_nama_pengguna
),
FINAL_QUERY AS (
  SELECT * 
  FROM FIANL_QUERY_MERGE AS DEFAULT_MAIN
  WHERE 1=1

	AND 
    (
      var_status_tugasan IS NULL
      OR UPPER(var_status_tugasan) NOT IN ('BARU', 'SEMASA')
      OR (
        UPPER(var_status_tugasan) = 'BARU' AND UPPER(DEFAULT_MAIN.STATUS_TUGASAN) = 'BARU'
      )
      OR (
        UPPER(var_status_tugasan) = 'SEMASA' AND UPPER(DEFAULT_MAIN.STATUS_TUGASAN) = 'DALAM TINDAKAN'
      )
    )
    AND (
    -- Ambil jika bukan PTB dan nama_pengguna tidak kosong
    (
      DEFAULT_MAIN.kod_tgsn NOT ILIKE '%PTB%'
      AND COALESCE(TRIM(DEFAULT_MAIN.nama_pengguna), '') <> ''
    )
    -- Atau: jika PTB / nama kosong, validasi modul dan peranan terhadap VAR_USER_PERANAN
    OR EXISTS (
      SELECT 1
      FROM VAR_USER_PERANAN u
      WHERE LOWER(u.modul) = LOWER(DEFAULT_MAIN.modul)
        AND EXISTS (
          SELECT 1
          FROM unnest(string_to_array(LOWER(DEFAULT_MAIN.peranan), '-')) AS p(peranan)
          WHERE p.peranan = u.peranan
        )
        AND (
          DEFAULT_MAIN.kod_tgsn ILIKE '%PTB%'
          OR COALESCE(TRIM(DEFAULT_MAIN.nama_pengguna), '') = ''
        )
    )
  
    )
    AND NOT (
      DEFAULT_MAIN.id_rujukan_smartbox IS NOT NULL
      AND DEFAULT_MAIN.id_rujukan_smartbox <> ''
      AND DEFAULT_MAIN.kod_tgsn IN ('ISHSB', 'KDSB')
    )

),

VAR_KOD_TUGSAN_BY_PELUPUSAN AS (
SELECT unnest(ARRAY['PYKP', 'SKP', 'SKP2', 'SKP3', 'PKP',
    'PYJKPTD', 'SJKPTD', 'SJKPTD2', 'SJKPTD3', 'PJKPTD', 'CJKPTD',
    'KKJKPTD', 'SKJKPTD', 'PYMMKN', 'SMMKN', 'SMMKN2', 'SMMKN3',
    'PMMKN', 'PSSPTG', 'SDPDT', 'SKMPTG', 'SKMPTG2', 'SKMPTG3',
    'SKMPTG4', 'SKMPTG5', 'PKMPTG', 'CKMPTG', 'SKPPTG', 'SKPPTG2',
    'SKPPTG3', 'SKPPTG4', 'SKPPTG5', 'PKPPTG', 'PYKPMB', 'SKPMB',
    'SKPMB2', 'SKPMB3', 'PSKPMB', 'SKPMBPTG', 'SKPMBPTG2', 'SKPMBPTG3',
    'SKPMBPTG4', 'SKPMBPTG5', 'PKPMBPTG', 'CKPMBPTG', 'PTBUT3', 'PLT',
    'SDS', 'PTBUT4', 'PPM', 'SPM', 'PFI', 'PYKMPTG'])
),
URUSAN_MODUL_PARENT_CTE AS (
  SELECT 
    A.APLIKASI_ID as APP_ID_CTE,
    M.KOD AS URUSAN_MODUL_PARENT
  FROM UMM_APLIKASI A
  LEFT JOIN IND_URSN U ON A.URSN_ID = U.URSN_ID
  LEFT JOIN IND_MODUL M ON U.MODUL_ID = M.MODUL_ID
),


FINAL_FILTER_ALL  AS (
	SELECT * FROM FINAL_QUERY AS FQ
	
	WHERE 1=1
	AND NOT (
		FQ.MODUL = 'PFIKM'   
		OR FQ.ID_TGSN IN (SELECT ID_TGSN_PELUPUSAN_PENGGUNA_FILTER FROM VAR_PELUPUSAN_TUGASAN_FILTERED)	
  	)
	AND NOT (FQ.modul = 'UAM' AND FQ.URUSAN_KOD = 'BIO')

    AND NOT (
      COALESCE(TRIM(FQ.locked_by), '') <> ''
      AND LOWER(FQ.locked_by) <> LOWER(var_nama_pengguna)
      AND FQ.locked_date IS NOT NULL
      AND FQ.locked_date > NOW() - INTERVAL '30 minutes'
    )
	 
),

FINAL_FILTER_ALL_V2 as (
	SELECT * FROM FINAL_FILTER_ALL
),




FINAL_RESULT AS (
	SELECT * ,
	CASE 
	  WHEN EXISTS (
	    SELECT 1
	    FROM UMM_PERTANYAAN p
	    JOIN RJK_SENARAI_AHLI_KUMPULAN k ON p.STATUS_ID = k.SENARAI_AHLI_KUMPULAN_ID
	    JOIN UMM_APLIKASI a ON p.APLIKASI_ID = a.APLIKASI_ID
	    JOIN IND_URSN u ON a.URSN_ID = u.URSN_ID
	    WHERE p.A_TGSN_ID = FQ.APP_A_TGSN_ID
	      AND k.KOD != 'SELESAI'
	      AND u.TEMPOH_KUIRI ~ '^[0-9]+$'
	      AND DATE_PART('day', CURRENT_DATE - p.CREATED_DATE) > u.TEMPOH_KUIRI::INT
	  )
	  THEN ' (Pertanyaan) - Telah Melebihi Tempoh Kuiri'
	
	  WHEN EXISTS (
	    SELECT 1
	    FROM UMM_PERTANYAAN p
	    JOIN RJK_SENARAI_AHLI_KUMPULAN k ON p.STATUS_ID = k.SENARAI_AHLI_KUMPULAN_ID
	    WHERE p.A_TGSN_ID = FQ.APP_A_TGSN_ID
	      AND k.KOD != 'SELESAI'
	  )
	  THEN ' (Pertanyaan)'
	
	  ELSE NULL
	END AS pertanyaan_keterangan,


	--	color and flag
	CASE 
	    WHEN (
	        CASE
	            WHEN FQ.MINIT_KPI IS NOT NULL 
	                 AND FQ.TRKH_PNRMAN IS NOT NULL 
	                 AND FQ.DHAS_1_TRKH_KPI IS NULL
	            THEN FQ.TRKH_PNRMAN + (FQ.MINIT_KPI || ' minutes')::INTERVAL
	            ELSE FQ.DHAS_1_TRKH_KPI
	        END
	    ) IS NOT NULL 
	    AND (
	        CASE
	            WHEN FQ.MINIT_KPI IS NOT NULL 
	                 AND FQ.TRKH_PNRMAN IS NOT NULL 
	                 AND FQ.DHAS_1_TRKH_KPI IS NULL
	            THEN FQ.TRKH_PNRMAN + (FQ.MINIT_KPI || ' minutes')::INTERVAL
	            ELSE FQ.DHAS_1_TRKH_KPI
	        END
	    ) < CURRENT_DATE
	THEN 'TUNGGAK'
	ELSE NULL
	END AS STATUS,
	CASE 
	    WHEN (
	        CASE
	            WHEN FQ.MINIT_KPI IS NOT NULL 
	                 AND FQ.TRKH_PNRMAN IS NOT NULL 
	                 AND FQ.TRKH_KPI IS NULL
	            THEN FQ.TRKH_PNRMAN + (FQ.MINIT_KPI || ' minutes')::INTERVAL
	            ELSE FQ.DHAS_1_TRKH_KPI
	        END
	    ) IS NOT NULL 
	    AND (
	        CASE
	            WHEN FQ.MINIT_KPI IS NOT NULL 
	                 AND FQ.TRKH_PNRMAN IS NOT NULL 
	                 AND FQ.TRKH_KPI IS NULL
	            THEN FQ.TRKH_PNRMAN + (FQ.MINIT_KPI || ' minutes')::INTERVAL
	            ELSE FQ.DHAS_1_TRKH_KPI
	        END
	    ) < CURRENT_DATE
	THEN 'red' -- warna merah sebagai contoh
	ELSE NULL
	END AS COLOR,


	CASE
	    WHEN NOT FQ.SHOW_KPI THEN 'Hijau'
	    WHEN FQ.TARIKH_DAN_MASA_LUPUT_STRING IS NULL OR FQ.TARIKH_DAN_MASA_LUPUT_STRING = '-' THEN 'Hijau'
	    WHEN FQ.TRKH_TETAP IS NULL THEN
	        CASE
	            WHEN TO_DATE(FQ.TARIKH_DAN_MASA_LUPUT_STRING, 'DD/MM/YYYY') >= CURRENT_DATE THEN 'Hijau'
	            ELSE 'Merah'
	        END
	    WHEN TO_DATE(FQ.TARIKH_DAN_MASA_LUPUT_STRING, 'DD/MM/YYYY') <= FQ.TRKH_TETAP::DATE THEN 'Hijau'
	    ELSE 'Merah'
	END AS FLAG_STATUS,

	--end color and flag

CASE
  WHEN FQ.KOD_TGSN = 'ISH' THEN TRUE
  WHEN FQ.MODUL = 'KKS' THEN TRUE
  WHEN FQ.MODUL = 'PNT' AND URUSAN_MODUL_PARENT = 'KKS' THEN TRUE
  WHEN EXISTS (
    SELECT 1
    FROM UNNEST(STRING_TO_ARRAY(FQ.URUSAN_KOD_DASHBOARD, '<BR />')) AS URSN
    WHERE URSN IN (SELECT * FROM VAR_BELUM_TUKAR_GANTI)
  ) THEN TRUE
  WHEN EXISTS (
    SELECT 1
    FROM UNNEST(STRING_TO_ARRAY(FQ.URUSAN_KOD_DASHBOARD, '<BR />')) AS URSN
    WHERE URSN IS NOT NULL
      AND (
        URSN NOT IN (SELECT * FROM VAR_BELUM_TUKAR_GANTI)
        OR URSN IN (SELECT * FROM VAR_ALSAN_TUKARGANTI_KOD_SET_BATAL)
      )
or (
    (
      SELECT COUNT(*) FROM DFT_A_MOHON_HKMLK HM
      JOIN IND_MKLMT_HKMLK MH ON MH.mklmt_hkmlk_id = HM.ID_HKMLK
      JOIN rjk_senarai_ahli_kumpulan o ON o.senarai_ahli_kumpulan_id = MH.status_hkmlk_id
      WHERE HM.APLIKASI_ID = FQ.APLIKASI_ID AND o.kod = 'STAHMBT'
    ) = (
      SELECT COUNT(*) FROM DFT_A_MOHON_HKMLK HM
      WHERE HM.APLIKASI_ID = FQ.APLIKASI_ID
    )
    or NOT EXISTS (
      SELECT 1
      FROM DFT_A_MOHON_HKMLK HM
      JOIN IND_MKLMT_HKMLK MH ON MH.mklmt_hkmlk_id = HM.ID_HKMLK
      JOIN RJK_SENARAI_AHLI_KUMPULAN o ON o.senarai_ahli_kumpulan_id = MH.status_hkmlk_id
      WHERE HM.APLIKASI_ID = FQ.APLIKASI_ID
      AND o.kod = 'STAHDFT'
      AND EXISTS (
        SELECT 1 FROM IND_VERSI_DHD TG WHERE TG.hkmlk_id = HM.ID_HKMLK
      )
    )
  )
  )
  
  THEN TRUE
  ELSE FALSE
END AS IS_HAKMILIK_BELUM_TUKARGANTI,



CASE 
  WHEN FQ.TARIKH_DAN_MASA_LUPUT IS NULL THEN '-' 

  WHEN FQ.TARIKH_DAN_MASA_LUPUT <= NOW() THEN '0 Hari'

  WHEN DATE_PART('month', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 THEN
    TRIM(BOTH FROM CONCAT_WS(' ',
      CASE 
        WHEN DATE_PART('month', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('month', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Bulan' 
      END,
      CASE 
        WHEN DATE_PART('day', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('day', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Hari' 
      END,
      CASE 
        WHEN DATE_PART('hour', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('hour', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Jam' 
      END,
      CASE 
        WHEN DATE_PART('minute', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('minute', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Minit' 
      END
    ))

  ELSE
    TRIM(BOTH FROM CONCAT_WS(' ',
      CASE 
        WHEN DATE_PART('day', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('day', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Hari' 
      END,
      CASE 
        WHEN DATE_PART('hour', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('hour', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Jam' 
      END,
      CASE 
        WHEN DATE_PART('minute', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('minute', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Minit' 
      END
    ))
END AS BAKI_MASA



	
FROM FINAL_FILTER_ALL_V2 AS FQ 
LEFT JOIN URUSAN_MODUL_PARENT_CTE UMP ON UMP.APP_ID_CTE = FQ.APP_ID

),



 rangkaian_merged AS (
    SELECT 
      MAX(fd.TGSN_SEMASA_ID)::BIGINT AS ID,
      MAX(fd.TRKH_PNRMAN) AS TRKH_PEN,
      MAX(fd.TARIKH_PENERIMAAN_STRING) AS TARIKH_PENERIMAAN_STRING,
      MAX(fd.TARIKH_DAN_MASA_LUPUT_STRING) AS TARIKH_DAN_MASA_LUPUT_STRING,
      STRING_AGG(DISTINCT  fd.ID_HKMLK, '<br />') AS no_hakmilik,
      ra.RANGKAIAN_ID::TEXT AS rangkaian_id_merged,
      fd.kod_tgsn::TEXT,
      STRING_AGG( fd.ID_PERMOHONAN_DASHBOARD ::TEXT, '<br />') AS id_permohonan,
      STRING_AGG(fd.URUSAN_KOD_DASHBOARD ::TEXT, '<br />') AS urusan,
      MAX(fd.NO_FAIL_PEMOHON) AS NO_FAIL_PEMOHON,
      STRING_AGG(DISTINCT  fd.NO_RESIT_DASHBOARD :: TEXT, '<br />') AS no_resit,
	  max(fd.TGSN_PERIHAL) as tugas,
      MAX(fd.NAMA_PEMOHON) AS NAMA_PEMOHON,
      MAX(fd.NAMA_PEJABAT_PENDEK) AS PEJABAT,
      MAX(fd.ID_PENGHANTARAN) AS ID_PENYAMPAIAN,
		MAX(fd.APP_A_TGSN_ID ) as id_APP_A_TGSN,
		max(fd.APLIKASI_ID),
	MAX(fd.pertanyaan_keterangan) AS pertanyaan_keterangan,
	MAX(fd.TARIKH_SIASATAN_STRING) as TARIKH_SIASATAN_STRING,
	MAX(fd.STATUS) as ROW_STATUS,
	MAX(fd.COLOR) as ROW_COLOR,
	MAX(fd.FLAG_STATUS) as FLAG_STATUS,
	(MAX(CASE WHEN fd.IS_HAKMILIK_BELUM_TUKARGANTI THEN 1 ELSE 0 END) = 1),
	MAX(fd.BAKI_MASA) as BAKI_MASA, 
	max(fd.NO_HAKMILIK_BARU) as NO_HAKMILIK_BARU,
	MAX(fd.MODUL) as MODUL

    FROM FINAL_RESULT fd
    JOIN UMM_APLIKASI ra ON fd.APLIKASI_ID = ra.APLIKASI_ID
    WHERE ra.RANGKAIAN_ID IS NOT NULL
      AND fd.kod_tgsn <> 'IMH'
    GROUP BY ra.RANGKAIAN_ID, fd.kod_tgsn
  ),

  remaining_rows AS (
    SELECT 
      fd.TGSN_SEMASA_ID::BIGINT AS ID,
      fd.TRKH_PNRMAN AS TRKH_PEN,
      fd.TARIKH_PENERIMAAN_STRING,
      fd.TARIKH_DAN_MASA_LUPUT_STRING,
      fd.ID_HKMLK AS no_hakmilik,
      NULL::TEXT AS rangkaian_id_merged,
      fd.kod_tgsn::TEXT,
      fd.ID_PERMOHONAN_DASHBOARD AS id_permohonan,
      fd.URUSAN_KOD_DASHBOARD AS urusan,
      fd.NO_FAIL_PEMOHON AS NO_FAIL_PEMOHON,
      fd.NO_RESIT_DASHBOARD AS no_resit,
		fd.TGSN_PERIHAL as tugas,
      fd.NAMA_PEMOHON AS NAMA_PEMOHON,
      fd.NAMA_PEJABAT_PENDEK AS PEJABAT,
      fd.ID_PENGHANTARAN AS ID_PENYAMPAIAN,
	fd.APP_A_TGSN_ID as id_APP_A_TGSN,
	fd.APLIKASI_ID,
	
	fd.pertanyaan_keterangan,
	fd.TARIKH_SIASATAN_STRING as TARIKH_SIASATAN_STRING,
	fd.STATUS as ROW_STATUS,
	fd.COLOR as ROW_COLOR,
	fd.FLAG_STATUS as FLAG_STATUS, 
	fd.IS_HAKMILIK_BELUM_TUKARGANTI,
	fd.BAKI_MASA as BAKI_MASA,
	fd.NO_HAKMILIK_BARU as NO_HAKMILIK_BARU,
	fd.MODUL as MODUL

    FROM FINAL_RESULT fd
    LEFT JOIN UMM_APLIKASI ra ON fd.APLIKASI_ID = ra.APLIKASI_ID
    WHERE ra.RANGKAIAN_ID IS NULL
       OR fd.kod_tgsn = 'IMH'
  ),

--   FINAL_V2 AS (
--     SELECT * FROM rangkaian_merged
--     UNION ALL
--     SELECT * FROM remaining_rows
--   ),
FINAL_V2 AS (
  SELECT DISTINCT ON (merged.id) merged.*
  FROM (
    SELECT * FROM rangkaian_merged
    UNION ALL
    SELECT * FROM remaining_rows
  ) merged
  ORDER BY merged.id, merged.trkh_pen DESC -- pilih row terbaru per id
),

  params AS (
    SELECT trim(c.col) AS fcol, trim(v.val) AS fval
    FROM unnest(string_to_array(var_filter_colum, ',')) WITH ORDINALITY AS c(col, idx)
    JOIN unnest(string_to_array(var_filter_val, '||')) WITH ORDINALITY AS v(val, idx2)
      ON c.idx = v.idx2
)


SELECT *
FROM FINAL_V2 v2
WHERE
    -- Jika tidak ada filter sama sekali, kembalikan semua
    NOT EXISTS (SELECT 1 FROM params)
    
    -- Jika ada filter, cocokkan semua kolom
    OR (
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TARIKH_PENERIMAAN_STRING')
         OR v2.TARIKH_PENERIMAAN_STRING ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TARIKH_PENERIMAAN_STRING')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TARIKH_DAN_MASA_LUPUT_STRING')
         OR v2.TARIKH_DAN_MASA_LUPUT_STRING ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TARIKH_DAN_MASA_LUPUT_STRING')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TARIKH_SIASATAN_STRING')
         OR v2.TARIKH_SIASATAN_STRING ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TARIKH_SIASATAN_STRING')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'NO_HAKMILIK')
         OR v2.NO_HAKMILIK ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'NO_HAKMILIK')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'ID_PERMOHONAN')
         OR v2.ID_PERMOHONAN ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'ID_PERMOHONAN')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'NO_FAIL_PEMOHON')
         OR v2.NO_FAIL_PEMOHON ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'NO_FAIL_PEMOHON')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'NO_RESIT')
         OR v2.NO_RESIT ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'NO_RESIT')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'URUSAN')
         OR v2.URUSAN ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'URUSAN')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'NAMA_PEMOHON')
         OR v2.NAMA_PEMOHON ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'NAMA_PEMOHON')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'PERTANYAAN_KETERANGAN')
         OR v2.PERTANYAAN_KETERANGAN ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'PERTANYAAN_KETERANGAN')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TUGAS')
         OR v2.TUGAS ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TUGAS')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'PEJABAT')
         OR v2.PEJABAT ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'PEJABAT')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'ID_PENYAMPAIAN')
         OR v2.ID_PENYAMPAIAN ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'ID_PENYAMPAIAN')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TUGASAN')
         OR v2.TUGAS ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TUGASAN')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'FLAG_STATUS')
         OR v2.FLAG_STATUS ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'FLAG_STATUS')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'BAKI_MASA')
         OR v2.BAKI_MASA ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'BAKI_MASA')))
        AND
        (NOT EXISTS (SELECT 1 FROM params pm WHERE pm.fcol = 'TUGAS_AND_PERTANYAAN')
         OR (v2.TUGAS ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TUGAS_AND_PERTANYAAN'))
             OR v2.PERTANYAAN_KETERANGAN ILIKE ANY (ARRAY(SELECT '%' || pm.fval || '%' FROM params pm WHERE pm.fcol = 'TUGAS_AND_PERTANYAAN'))))
    )
	
 ORDER BY
  -- Default fallback kalau tidak ada kolom urutan diberikan
  CASE 
    WHEN var_sort_colum IS NULL THEN V2.TARIKH_PENERIMAAN_STRING 
  END DESC,

  -- Jika kolom urutan diberikan, gunakan CASE berdasarkan nama kolom dan tipe sort
  CASE WHEN var_sort_colum = 'TARIKH_PENERIMAAN_STRING' AND var_sort_type = 'ASC' THEN V2.TRKH_PEN END ASC,
  CASE WHEN var_sort_colum = 'TARIKH_PENERIMAAN_STRING' AND var_sort_type = 'DESC' THEN V2.TRKH_PEN END DESC,
  
  CASE WHEN var_sort_colum = 'TARIKH_DAN_MASA_LUPUT_STRING' AND var_sort_type = 'ASC' THEN V2.TARIKH_DAN_MASA_LUPUT_STRING END ASC,
  CASE WHEN var_sort_colum = 'TARIKH_DAN_MASA_LUPUT_STRING' AND var_sort_type = 'DESC' THEN V2.TARIKH_DAN_MASA_LUPUT_STRING END DESC,

  CASE WHEN var_sort_colum = 'TARIKH_SIASATAN_STRING' AND var_sort_type = 'ASC' THEN V2.TARIKH_SIASATAN_STRING END ASC,
  CASE WHEN var_sort_colum = 'TARIKH_SIASATAN_STRING' AND var_sort_type = 'DESC' THEN V2.TARIKH_SIASATAN_STRING END DESC,

  CASE WHEN var_sort_colum = 'NO_HAKMILIK' AND var_sort_type = 'ASC' THEN V2.NO_HAKMILIK END ASC,
  CASE WHEN var_sort_colum = 'NO_HAKMILIK' AND var_sort_type = 'DESC' THEN V2.NO_HAKMILIK END DESC,

  CASE WHEN var_sort_colum = 'KOD_TGSN' AND var_sort_type = 'ASC' THEN V2.KOD_TGSN END ASC,
  CASE WHEN var_sort_colum = 'KOD_TGSN' AND var_sort_type = 'DESC' THEN V2.KOD_TGSN END DESC,

  CASE WHEN var_sort_colum = 'ID_PERMOHONAN' AND var_sort_type = 'ASC' THEN V2.ID_PERMOHONAN END ASC,
  CASE WHEN var_sort_colum = 'ID_PERMOHONAN' AND var_sort_type = 'DESC' THEN V2.ID_PERMOHONAN END DESC,

  CASE WHEN var_sort_colum = 'URUSAN' AND var_sort_type = 'ASC' THEN V2.URUSAN END ASC,
  CASE WHEN var_sort_colum = 'URUSAN' AND var_sort_type = 'DESC' THEN V2.URUSAN END DESC,

  CASE WHEN var_sort_colum = 'NO_FAIL_PEMOHON' AND var_sort_type = 'ASC' THEN V2.NO_FAIL_PEMOHON END ASC,
  CASE WHEN var_sort_colum = 'NO_FAIL_PEMOHON' AND var_sort_type = 'DESC' THEN V2.NO_FAIL_PEMOHON END DESC,

  CASE WHEN var_sort_colum = 'NO_RESIT' AND var_sort_type = 'ASC' THEN V2.NO_RESIT END ASC,
  CASE WHEN var_sort_colum = 'NO_RESIT' AND var_sort_type = 'DESC' THEN V2.NO_RESIT END DESC,

  CASE WHEN var_sort_colum = 'TUGAS' AND var_sort_type = 'ASC' THEN V2.TUGAS END ASC,
  CASE WHEN var_sort_colum = 'TUGAS' AND var_sort_type = 'DESC' THEN V2.TUGAS END DESC,

  CASE WHEN var_sort_colum = 'NAMA_PEMOHON' AND var_sort_type = 'ASC' THEN V2.NAMA_PEMOHON END ASC,
  CASE WHEN var_sort_colum = 'NAMA_PEMOHON' AND var_sort_type = 'DESC' THEN V2.NAMA_PEMOHON END DESC,

  CASE WHEN var_sort_colum = 'PEJABAT' AND var_sort_type = 'ASC' THEN V2.PEJABAT END ASC,
  CASE WHEN var_sort_colum = 'PEJABAT' AND var_sort_type = 'DESC' THEN V2.PEJABAT END DESC,

  CASE WHEN var_sort_colum = 'PERTANYAAN_KETERANGAN' AND var_sort_type = 'ASC' THEN V2.PERTANYAAN_KETERANGAN END ASC,
  CASE WHEN var_sort_colum = 'PERTANYAAN_KETERANGAN' AND var_sort_type = 'DESC' THEN V2.PERTANYAAN_KETERANGAN END DESC,

  CASE WHEN var_sort_colum = 'ID_PENYAMPAIAN' AND var_sort_type = 'ASC' THEN V2.ID_PENYAMPAIAN END ASC,
  CASE WHEN var_sort_colum = 'ID_PENYAMPAIAN' AND var_sort_type = 'DESC' THEN V2.ID_PENYAMPAIAN END DESC,

	CASE WHEN var_sort_colum = 'BAKI_MASA' AND var_sort_type = 'ASC' THEN V2.BAKI_MASA END ASC,
  CASE WHEN var_sort_colum = 'BAKI_MASA' AND var_sort_type = 'DESC' THEN V2.BAKI_MASA END DESC,


  CASE WHEN var_sort_colum = 'TUGAS_AND_PERTANYAAN' AND var_sort_type = 'ASC' THEN V2.TUGAS END ASC,
  CASE WHEN var_sort_colum = 'TUGAS_AND_PERTANYAAN' AND var_sort_type = 'DESC' THEN V2.TUGAS END DESC



	LIMIT CASE WHEN NOT var_export AND var_limit IS NOT NULL THEN var_limit ELSE NULL 
	END
	OFFSET CASE WHEN NOT var_export AND var_offset IS NOT NULL THEN var_offset ELSE 0 
	END;


END;
$function$
;

-- DROP FUNCTION et_main_uat.get_dashboard_penyampaian_notis_by_pengguna(numeric, numeric, text, numeric, text, text, text, text);

CREATE OR REPLACE FUNCTION et_main_uat.get_dashboard_penyampaian_notis_by_pengguna(var_limit numeric DEFAULT NULL::numeric, var_offset numeric DEFAULT NULL::numeric, var_nama_pengguna text DEFAULT NULL::text, var_pejabat_id numeric DEFAULT NULL::numeric, var_sort_colum text DEFAULT NULL::text, var_sort_type text DEFAULT NULL::text, var_filter_colum text DEFAULT NULL::text, var_filter_val text DEFAULT NULL::text)
 RETURNS TABLE(id bigint, penghantaran_id text, tugasan_perihal text, nama_pengguna text, trkh_pnrman timestamp without time zone, trkh_kpi timestamp without time zone, tarikh_mula timestamp without time zone, tarikh_tamat timestamp without time zone, id_permohonan text, nama_penerima text, alamat_penerima text, show_link numeric, tampal_flag numeric, modul_name text, lokasi_tampal_list text[], display_nama_pengguna text, maklumat_penerima text, flag text)
 LANGUAGE plpgsql
AS $function$
BEGIN
  RETURN QUERY

with MAIN_Q as (SELECT 
    DHAS_1.TGSN_SEMASA_ID::BIGINT AS ID,
    HNTR_1.ID_PENGHANTARAN AS PENGHANTARAN_ID,
    DHAS_1.TGSN_PERIHAL AS TUGASAN_PERIHAL,
    DHAS_1.NAMA_PENGGUNA AS NAMA_PENGGUNA,
    DHAS_1.TRKH_PNRMAN AS TRKH_PNRMAN,
    DHAS_1.TRKH_KPI AS TRKH_KPI,
    APP_TGSN_1.TRKH_MULA AS TARIKH_MULA,
    APP_TGSN_1.TRKH_TETAP AS TARIKH_TAMAT,
    APP_TGSN_1.TEMPOH_KPI AS TEMPOH_PERINGATAN_KPI,
    
    CASE 
        WHEN HNTR_1.ID_PENGHANTARAN LIKE 'PNL%' 
             AND SP_1.KOD = 'JENIS_PENYAMPAIAN_T'
             THEN APP_1.MKLMT_TMBHN::jsonb ->> 'idPengenalanInduk'
        ELSE APP_1.ID_PENGENALAN
    END AS ID_PERMOHONAN,
    
    ALMT_1.NAMA_PNRM AS NAMA_PENERIMA,
    
    TRIM(
	    COALESCE(ALMT_1.ALAMAT,'') || ' ' ||
	    COALESCE(ALMT_1.ALAMAT2,'') || ' ' ||
	    COALESCE(ALMT_1.ALAMAT3,'') || ' ' ||
	    COALESCE(ALMT_1.ALAMAT4,'') || ' ' ||
	    COALESCE(ALMT_1.POSKOD,'') || ' ' ||
	    CASE WHEN MDL_1.KOD='BANDAR_LAIN' THEN MAX(ALMT_1.BANDAR_LAIN) ELSE MAX(MDL_1.NAMA) END || ' ' ||
	    MAX(NEGERI.NAMA)
	) AS ALAMAT_PENERIMA,
	
	TRIM(
	    COALESCE(PEJABAT.ALAMAT,'') || ' ' ||
	    COALESCE(PEJABAT.ALAMAT2,'') || ' ' ||
	    COALESCE(PEJABAT.ALAMAT3,'') || ' ' ||
	    COALESCE(PEJABAT.ALAMAT4,'') || ' ' ||
	    COALESCE(PEJABAT.POSKOD,'') || ' ' ||
	    CASE WHEN MDL_1.KOD='BANDAR_LAIN' THEN PEJABAT.BANDAR_LAIN ELSE MDL_1.NAMA END || ' ' ||
	    NEGERI.NAMA
	) AS ALAMAT_PEJABAT_PENERIMA,
	ALMT_1.jns_alamat AS JENIS_ALAMAT,
	CASE 
        WHEN DHAS_1.NAMA_PENGGUNA IS NULL OR DHAS_1.NAMA_PENGGUNA = var_nama_pengguna THEN 1
        ELSE 0
    END AS SHOW_LINK,
    CASE 
        WHEN DHAS_1.PERANAN = '-PN-' THEN 1
        ELSE 0
    END AS ENABLE_AGIH,
	HNTR_1.FLAG_SEGERA AS SEGERA_FLAG,
	CASE WHEN DHAS_1.TGSN_PERIHAL LIKE '%Pembetulan%' THEN 1 ELSE 0 END AS PEMBETULAN_FLAG,
    CASE 
	    WHEN SP_1.KOD = 'JENIS_PENYAMPAIAN_T' THEN 1
	    ELSE 0
	END AS TAMPAL_FLAG,
	COALESCE(MDL_1.NAMA, '-') AS MODUL_NAME,
	ARRAY_AGG(
    CASE 
        WHEN ALMT_1.jns_alamat = 'TH'
            THEN 'Di atas tanah ' || COALESCE(ALMT_1.alamat,'')
        WHEN ALMT_1.jns_alamat = 'PT'
            THEN 'Di papan kenyataan ' || COALESCE(ALMT_1.nama_pnrm,'')
        WHEN ALMT_1.jns_alamat = 'PP'
            THEN 'Di papan kenyataan Pejabat Penghulu'
        WHEN ALMT_1.jns_alamat = 'TA'
            THEN 'Di papan kenyataan Tempat Awam'
        ELSE '-'
    END
) AS LOKASI_TAMPAL_LIST

	
FROM UMM_TGSN_SEMASA DHAS_1
LEFT JOIN UMM_A_TGSN APP_TGSN_1 
    ON DHAS_1.A_TGSN_ID = APP_TGSN_1.A_TGSN_ID
LEFT JOIN UMM_APLIKASI APP_1 
    ON DHAS_1.APLIKASI_ID = APP_1.APLIKASI_ID
LEFT JOIN UMM_HANTARAN_NOTIS HNTR_1 
    ON DHAS_1.HANTARAN_NOTIS_ID = HNTR_1.HANTARAN_NOTIS_ID
LEFT JOIN IND_MODUL MDL_1 
    ON HNTR_1.UNIT_ID = MDL_1.MODUL_ID
LEFT JOIN UMM_BTRN_HANTARAN_NOTIS BHNTR_1
    ON HNTR_1.HANTARAN_NOTIS_ID = BHNTR_1.HANTARAN_NOTIS_ID
LEFT JOIN RJK_SENARAI_AHLI_KUMPULAN SP_1
    ON BHNTR_1.jns_penyampaian_id = SP_1.senarai_ahli_kumpulan_id
LEFT JOIN UMM_ALAMAT_PNRM_NOTIS ALMT_1
    ON BHNTR_1.alamat_pnrm_notis_id = ALMT_1.alamat_pnrm_notis_id
LEFT JOIN RJK_SENARAI_AHLI_KUMPULAN NEGERI
    ON ALMT_1.NEGERI_ID = NEGERI.SENARAI_AHLI_KUMPULAN_ID
LEFT JOIN IND_PEJABAT PEJABAT
    ON ALMT_1.PEJABAT_ID = PEJABAT.PEJABAT_ID
WHERE DHAS_1.HANTARAN_NOTIS_ID IS NOT NULL
AND (DHAS_1.NAMA_PENGGUNA = var_nama_pengguna OR DHAS_1.NAMA_PENGGUNA IS NULL)
AND (var_pejabat_id IS NULL OR DHAS_1.PEJABAT_ID = var_pejabat_id)
AND DHAS_1.PERANAN LIKE '%-PN-%'
GROUP BY 
    DHAS_1.TGSN_SEMASA_ID,
    HNTR_1.ID_PENGHANTARAN,
    DHAS_1.TGSN_PERIHAL,
    DHAS_1.NAMA_PENGGUNA,
    DHAS_1.TRKH_PNRMAN,
    DHAS_1.TRKH_KPI,
    APP_TGSN_1.TRKH_MULA,
    APP_TGSN_1.TRKH_TETAP,
    APP_TGSN_1.TEMPOH_KPI,
    APP_1.ID_PENGENALAN,
    APP_1.MKLMT_TMBHN,
    ALMT_1.NAMA_PNRM,
    ALMT_1.ALAMAT,
    ALMT_1.ALAMAT2,
    ALMT_1.ALAMAT3,
    ALMT_1.ALAMAT4,
    ALMT_1.POSKOD,
    ALMT_1.jns_alamat,
    PEJABAT.ALAMAT,
    PEJABAT.ALAMAT2,
    PEJABAT.ALAMAT3,
    PEJABAT.ALAMAT4,
    PEJABAT.POSKOD,
    PEJABAT.BANDAR_LAIN,
    MDL_1.KOD,
    MDL_1.NAMA,
    NEGERI.NAMA,
    DHAS_1.PERANAN,
    HNTR_1.FLAG_SEGERA,
    SP_1.KOD
  
)

select
    Q_.ID,
    Q_.PENGHANTARAN_ID::TEXT as PENGHANTARAN_ID,
    Q_.TUGASAN_PERIHAL::TEXT as TUGASAN_PERIHAL,
    Q_.NAMA_PENGGUNA::TEXT as NAMA_PENGGUNA,
    Q_.TRKH_PNRMAN as TRKH_PNRMAN,
    Q_.TRKH_KPI as TRKH_KPI,
 	Q_.TARIKH_MULA,
 	Q_.TARIKH_TAMAT,
	Q_.ID_PERMOHONAN::TEXT as ID_PERMOHONAN,
	Q_.NAMA_PENERIMA :: TEXT as NAMA_PENERIMA, 
	Q_.ALAMAT_PENERIMA::TEXT AS ALAMAT_PENERIMA,
	Q_.SHOW_LINK::number as SHOW_LINK,
	Q_.TAMPAL_FLAG::number as TAMPAL_FLAG,
	Q_.MODUL_NAME::TEXT as MODUL_NAME,
	Q_.LOKASI_TAMPAL_LIST as LOKASI_TAMPAL_LIST,

	split_part(Q_.NAMA_PENGGUNA, '@', 1) AS DISPLAY_NAMA_PENGGUNA,
split_part(Q_.NAMA_PENGGUNA, '@', 1) || E'\n' || Q_.ALAMAT_PENERIMA AS MAKLUMAT_PENERIMA ,
--COALESCE(Q_.TRKH_KPI, CURRENT_DATE) AS TARIKH_SUSUNAN,
CASE
            WHEN Q_.TRKH_KPI IS NULL THEN 'Hijau'
            ELSE
                CASE
                    WHEN Q_.TARIKH_TAMAT IS NULL THEN
                        CASE
                            WHEN Q_.TEMPOH_PERINGATAN_KPI IS NOT NULL THEN
                                CASE
                                    WHEN Q_.TRKH_KPI > Q_.TARIKH_MULA + (Q_.TEMPOH_PERINGATAN_KPI || ' minutes')::interval
                                         AND NOW() >= Q_.TARIKH_MULA + (Q_.TEMPOH_PERINGATAN_KPI || ' minutes')::interval
                                         AND NOW() < Q_.TRKH_KPI
                                         THEN 'Kuning'
                                    WHEN NOW() > Q_.TRKH_KPI THEN 'Merah'
                                    WHEN NOW() < Q_.TRKH_KPI THEN 'Hijau'
                                    ELSE 'Merah'
                                END
                            ELSE
                                CASE
                                    WHEN NOW() < Q_.TRKH_KPI THEN 'Hijau'
                                    ELSE 'Merah'
                                END
                        END
                    ELSE
                        CASE
                            WHEN Q_.TRKH_KPI < Q_.TARIKH_TAMAT THEN 'Hijau'
                            ELSE 'Merah'
                        END
                END
       END AS FLAG
--
--CASE 
--	WHEN Q_.TRKH_KPI IS NOT NULL THEN
--            'Notis Penting hantar sebelum ' || TO_CHAR(Q_.TRKH_KPI, 'DD/MM/YYYY')
--        ELSE 'Sila tentukan tarikh aktiviti'
--    END AS SEGERA_TOOLTIP
from MAIN_Q Q_

WHERE
  (var_filter_colum IS NULL OR var_filter_val IS NULL OR (
  (var_filter_colum = 'MODUL_NAME' AND Q_.MODUL_NAME ILIKE '%' || var_filter_val || '%') or 
(var_filter_colum = 'PENGHANTARAN_ID' AND Q_.PENGHANTARAN_ID ILIKE '%' || var_filter_val || '%') or
(var_filter_colum = 'ID_PERMOHONAN' AND Q_.ID_PERMOHONAN ILIKE '%' || var_filter_val || '%') or
(var_filter_colum = 'TRKH_PNRMAN' AND Q_.TRKH_PNRMAN ILIKE '%' || var_filter_val || '%') or
(var_filter_colum = 'MAKLUMAT_PENERIMA' AND MAKLUMAT_PENERIMA ILIKE '%' || var_filter_val || '%') or
(var_filter_colum = 'NAMA_PENGGUNA' AND Q_.NAMA_PENGGUNA ILIKE '%' || var_filter_val || '%') or
(var_filter_colum = 'TUGASAN_PERIHAL' AND Q_.TUGASAN_PERIHAL ILIKE '%' || var_filter_val || '%') or
(var_filter_colum = 'FLAG' AND FLAG ILIKE '%' || var_filter_val || '%')

 ))




ORDER BY
  CASE 
    WHEN var_sort_colum IS NULL THEN Q_.TRKH_PNRMAN 
  END DESC,
  CASE WHEN var_sort_colum = 'PENGHANTARAN_ID' AND var_sort_type = 'ASC' THEN Q_.PENGHANTARAN_ID END ASC,
  CASE WHEN var_sort_colum = 'PENGHANTARAN_ID' AND var_sort_type = 'DESC' THEN Q_.PENGHANTARAN_ID END DESC,

  CASE WHEN var_sort_colum = 'ID_PERMOHONAN' AND var_sort_type = 'ASC' THEN Q_.ID_PERMOHONAN END ASC,
  CASE WHEN var_sort_colum = 'ID_PERMOHONAN' AND var_sort_type = 'DESC' THEN Q_.ID_PERMOHONAN END DESC,

CASE WHEN var_sort_colum = 'MODUL_NAME' AND var_sort_type = 'ASC' THEN Q_.MODUL_NAME END ASC,
  CASE WHEN var_sort_colum = 'MODUL_NAME' AND var_sort_type = 'DESC' THEN Q_.MODUL_NAME END DESC,

CASE WHEN var_sort_colum = 'TRKH_PNRMAN' AND var_sort_type = 'ASC' THEN Q_.TRKH_PNRMAN END ASC,
  CASE WHEN var_sort_colum = 'TRKH_PNRMAN' AND var_sort_type = 'DESC' THEN Q_.TRKH_PNRMAN END DESC,


CASE WHEN var_sort_colum = 'MAKLUMAT_PENERIMA' AND var_sort_type = 'ASC' THEN MAKLUMAT_PENERIMA END ASC,
  CASE WHEN var_sort_colum = 'MAKLUMAT_PENERIMA' AND var_sort_type = 'DESC' THEN MAKLUMAT_PENERIMA END DESC,

CASE WHEN var_sort_colum = 'NAMA_PENGGUNA' AND var_sort_type = 'ASC' THEN Q_.NAMA_PENGGUNA END ASC,
  CASE WHEN var_sort_colum = 'NAMA_PENGGUNA' AND var_sort_type = 'DESC' THEN Q_.NAMA_PENGGUNA END DESC,


	CASE WHEN var_sort_colum = 'TUGASAN_PERIHAL' AND var_sort_type = 'ASC' THEN Q_.TUGASAN_PERIHAL END ASC,
  CASE WHEN var_sort_colum = 'TUGASAN_PERIHAL' AND var_sort_type = 'DESC' THEN Q_.TUGASAN_PERIHAL END DESC

  

LIMIT var_limit
OFFSET var_offset
;
END;
$function$
;

-- DROP FUNCTION et_main_uat.get_end_business_date(timestamp, int4);

CREATE OR REPLACE FUNCTION et_main_uat.get_end_business_date(v_start_date timestamp without time zone, v_num_days integer)
 RETURNS numeric
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_counter INT := 0;
    v_current_date DATE := v_start_date;
BEGIN
    IF v_num_days <= 0 THEN
        RETURN 0;
    END IF;

    WHILE v_counter < v_num_days LOOP
        v_current_date := v_current_date + 1;

        -- Skip weekends
        IF EXTRACT(DOW FROM v_current_date) IN (0, 6) THEN
            CONTINUE;
        END IF;

        -- Skip holidays
        IF EXISTS (
            SELECT 1
            FROM rjk_hari_kelepasan_am b
            WHERE v_current_date BETWEEN b.trkh AND b.trkh_hingga
        ) THEN
            CONTINUE;
        END IF;

        v_counter := v_counter + 1;
    END LOOP;

   RETURN EXTRACT(DAY FROM (v_current_date - v_start_date));
END;
$function$
;

-- DROP FUNCTION et_main_uat.get_new_fr_old_id_pengguna(varchar, varchar);

CREATE OR REPLACE FUNCTION et_main_uat.get_new_fr_old_id_pengguna(v_old_id_pengguna character varying, v_old_system character varying)
 RETURNS character varying
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_new_id_pengguna_email VARCHAR2(50);
BEGIN
    SELECT emel
    INTO v_new_id_pengguna_email
    FROM migrate_id_pengguna
    WHERE (id_sptb = v_old_id_pengguna AND v_old_system = 'sptb')
        OR (id_sphtb = v_old_id_pengguna AND v_old_system = 'sphtb')
        OR (id_biometrik = v_old_id_pengguna AND v_old_system = 'bio');

    RETURN v_new_id_pengguna_email;
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        RETURN NULL;
    WHEN TOO_MANY_ROWS THEN
        RETURN NULL;
    WHEN OTHERS THEN
        RAISE;
END;
$function$
;

