            WHEN p_kod_pejabat = '01' AND p_kod_carabayar IN ('cabadc', 'cabacc') THEN '012101109873'
            WHEN p_kod_pejabat = '01' AND p_kod_carabayar IN ('cabatu', 'cabakw', 'cabawp', 'cababd', 'cabaeft', 'cabacek') THEN '8001954651'
            WHEN p_kod_pejabat = '02' AND p_kod_carabayar IN ('cabadc', 'cabacc') THEN '012101109873'
            WHEN p_kod_pejabat = '02' AND p_kod_carabayar IN ('cabatu', 'cabakw', 'cabawp', 'cababd', 'cabaeft', 'cabacek', 'cabampkl') THEN '8001954651'
            WHEN p_kod_pejabat = '04' AND p_kod_carabayar IN ('cabadc', 'cabacc') THEN '012101109873'
            WHEN p_kod_pejabat = '04' AND p_kod_carabayar IN ('cabatu', 'cabakw', 'cabawp', 'cababd', 'cabaeft', 'cabacek') THEN '8001954651'
            WHEN p_kod_pejabat = '05' AND p_kod_carabayar IN ('cabadc', 'cabacc') THEN '012101109873'
            WHEN p_kod_pejabat = '05' AND p_kod_carabayar IN ('cabatu', 'cabakw', 'cabawp', 'cababd', 'cabaeft', 'cabacek') THEN '8001954651'
            WHEN p_kod_pejabat = '06' AND p_kod_carabayar IN ('cabadc', 'cabacc') THEN '012101109873'
            WHEN p_kod_pejabat = '06' AND p_kod_carabayar IN ('cabatu', 'cabakw', 'cabawp', 'cababd', 'cabaeft', 'cabacek') THEN '8001954651'
            WHEN p_kod_pejabat = '07' AND p_kod_carabayar IN ('cabatu', 'cabadc', 'cabacc', 'cabakw', 'cabawp', 'cababd', 'cabacek') THEN '012101109873'
            WHEN p_kod_pejabat = '07' AND p_kod_carabayar IN ('cabaeft') THEN '8001954651'
            WHEN p_kod_pejabat = '08' AND p_kod_carabayar IN ('cabadc', 'cabacc', 'cabambpj', 'cabambsj') THEN '012101109873'
            WHEN p_kod_pejabat = '08' AND p_kod_carabayar IN ('cabatu', 'cabakw', 'cabawp', 'cababd', 'cabaeft', 'cabacek', 'cabambsa') THEN '8001954651'
            WHEN p_kod_pejabat = '09' AND p_kod_carabayar IN ('cabadc', 'cabacc') THEN '012101109873'
            WHEN p_kod_pejabat = '09' AND p_kod_carabayar IN ('cabatu', 'cabakw', 'cabawp', 'cababd', 'cabaeft', 'cabacek') THEN '8001954651'
            WHEN p_kod_pejabat = '09' AND p_kod_carabayar IN ('cabamps', 'cabampaj') THEN '12038010134121'
            WHEN p_kod_pejabat = '10' AND p_kod_carabayar IN ('cabadc', 'cabacc') THEN '012101109873'
            WHEN p_kod_pejabat = '10' AND p_kod_carabayar IN ('cabatu', 'cabakw', 'cabawp', 'cababd', 'cabaeft', 'cabacek', 'cabampsp') THEN '8001954651'
            ELSE ''
        END INTO v_no_akaun;

    RETURN v_no_akaun;

    EXCEPTION
        WHEN others THEN
            RETURN NULL;
END;
$function$
