-- DROP FUNCTION et_main_uat.get_no_penyata_pemungut(varchar);

CREATE OR REPLACE FUNCTION et_main_uat.get_no_penyata_pemungut(p_no_resit character varying)
 RETURNS character varying
 LANGUAGE plpgsql
AS $function$
DECLARE
    no_pp VARCHAR(4000);
BEGIN
    no_pp := null;

    SELECT string_agg(pp.id_pengenalan, ' | ') 
    INTO no_pp
    FROM (
        SELECT DISTINCT d.id_pengenalan
        FROM et_main_mig.hsl_bayaran x
        JOIN et_main_mig.hsl_btrn_bayaran y ON x.bayaran_id = y.bayaran_id
        JOIN et_main_mig.hsl_cara_bayaran z ON y.cara_bayaran_id = z.cara_bayaran_id
        JOIN et_main_mig.umm_aplikasi d ON x.pejabat_id = d.pejabat_id
        JOIN et_main_mig.hsl_a_penyata_pemungut e ON d.aplikasi_id = e.aplikasi_id
        WHERE CONCAT(to_char(x.created_date, 'yyyymmdd'), x.sesi) BETWEEN e.pungutan_mula AND e.pungutan_tamat
            AND e.kod_cara_bayar_id = z.kod_cara_bayaran_id
            AND x.hasil_pejabat = e.hasil_pejabat
            AND x.no_resit = p_no_resit
    ) pp;

    RETURN no_pp;

    EXCEPTION
        WHEN OTHERS THEN
            RETURN NULL;
END;
$function$
;

-- DROP FUNCTION et_main_uat.get_pejabat_by_idhakmilik(varchar);

CREATE OR REPLACE FUNCTION et_main_uat.get_pejabat_by_idhakmilik(idhakmilik character varying)
 RETURNS character varying
 LANGUAGE plpgsql
AS $function$
DECLARE
    namapejabat VARCHAR(500);
BEGIN
    SELECT
        CASE
            WHEN jns_hkmlk_id IN (2, 7, 4) THEN 'ptg'
            ELSE pj.nama
        END
    INTO namapejabat
    FROM ind_hkmlk h
    JOIN ind_bandar_pekan_mukim bpm ON h.bandar_pekan_mukim_id = bpm.bandar_pekan_mukim_id
    JOIN ind_pejabat pj ON bpm.pejabat_id = pj.pejabat_id
    WHERE h.id_hkmlk = idhakmilik;

    RETURN namapejabat;

    EXCEPTION
        WHEN OTHERS THEN
            RETURN NULL;
END;
$function$
;

-- DROP FUNCTION et_main_uat.get_syer_ketuanpunyaan_new(numeric);

CREATE OR REPLACE FUNCTION et_main_uat.get_syer_ketuanpunyaan_new(p_pihak_bkptg_id numeric)
 RETURNS character varying
 LANGUAGE plpgsql
AS $function$
DECLARE
    
    v_count integer := 0;
    pb_rec record;
    
    total_numerator NUMERIC := 0;
    total_denominator NUMERIC := 1;
    divisor NUMERIC;
    
BEGIN
    FOR pb_rec IN (
        SELECT
            x.pihak_bkptg_id,
            x.versi_akhir_id,
            trim(x.nama) AS nama,
            x.no_kp,
            x.syer_pembilang,
            x.syer_penyebut
        FROM
            ind_pihak_bkptg x,
            ind_pihak_bkptg y
        WHERE
            x.jns_pihak_bkptg_id = y.jns_pihak_bkptg_id
            AND x.versi_akhir_id = y.versi_akhir_id
            AND x.nama = y.nama
            AND x.no_kp = y.no_kp
            AND (x.id_kumpulan = y.id_kumpulan OR y.id_kumpulan IS NULL)
            AND x.flag_kuatkuasa = 'Y'
            AND y.pihak_bkptg_id = p_pihak_bkptg_id
            AND COALESCE(x.syer_pembilang, 0) <> 0
            AND COALESCE(x.syer_penyebut, 0) <> 0
            AND COALESCE(y.syer_penyebut, 0) <> 0
    )
    LOOP
        v_count := v_count + 1;       
        IF pb_rec.syer_penyebut != 0 THEN
            total_numerator := (total_numerator * pb_rec.syer_penyebut) + (pb_rec.syer_pembilang * total_denominator);
            total_denominator := total_denominator * pb_rec.syer_penyebut;
        END IF;
    END LOOP;
    
    IF v_count = 0 then
    	 RETURN '0/0';
    ELSE
	    IF total_denominator != 0 then
	    	divisor := gcd(total_numerator, total_denominator);
	    	IF divisor != 0 THEN
		        total_numerator := total_numerator / divisor;
		        total_denominator := total_denominator / divisor;
		    END IF;
	    	
	        RETURN TRUNC(total_numerator) || '/' ||  TRUNC(total_denominator);
	    ELSE
	        RETURN '0/0';
	    END IF;  
	END IF;

EXCEPTION
    WHEN OTHERS THEN
        null;
END;
$function$
;

-- DROP FUNCTION et_main_uat.get_syer_ketuanpunyaan_new(int4);

CREATE OR REPLACE FUNCTION et_main_uat.get_syer_ketuanpunyaan_new(p_pihak_bkptg_id integer)
 RETURNS character varying
 LANGUAGE plpgsql
AS $function$
DECLARE
    jumlah numeric;
    v_count integer := 0;
    pb_rec record;
BEGIN
    FOR pb_rec IN (
        SELECT
            x.pihak_bkptg_id,
            x.versi_akhir_id,
            trim(x.nama) AS nama,
            x.no_kp,
            x.syer_pembilang,
            x.syer_penyebut
        FROM
            ind_pihak_bkptg x,
            ind_pihak_bkptg y
        WHERE
            x.jns_pihak_bkptg_id = y.jns_pihak_bkptg_id
            AND x.versi_akhir_id = y.versi_akhir_id
            AND x.nama = y.nama
            AND x.no_kp = y.no_kp
            AND (x.id_kumpulan = y.id_kumpulan OR y.id_kumpulan IS NULL)
            AND x.flag_kuatkuasa = 'Y'
            AND y.pihak_bkptg_id = p_pihak_bkptg_id
            AND COALESCE(x.syer_pembilang, 0) <> 0
            AND COALESCE(x.syer_penyebut, 0) <> 0
            AND COALESCE(y.syer_penyebut, 0) <> 0
    )
    LOOP
        v_count := v_count + 1;
        IF jumlah IS NULL THEN
            jumlah := pb_rec.syer_pembilang::numeric / pb_rec.syer_penyebut::numeric;
        ELSE
            jumlah := jumlah + pb_rec.syer_pembilang::numeric / pb_rec.syer_penyebut::numeric;
        END IF;
    END LOOP;

    IF v_count = 0 THEN
        RETURN '0/0';
    ELSE
        RETURN jumlah::text;
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        RETURN null;
END;
$function$
;

-- DROP FUNCTION et_main_uat.get_total_dashboard_by_pengguna(_text, text, numeric, text, text, text);

CREATE OR REPLACE FUNCTION et_main_uat.get_total_dashboard_by_pengguna(var_urusan_kod_list text[], var_nama_pengguna text DEFAULT NULL::text, var_pejabat_id numeric DEFAULT NULL::numeric, var_modul_kod text DEFAULT NULL::text, var_urusan_mdl_kod text DEFAULT NULL::text, var_kod_negri text DEFAULT NULL::text)
 RETURNS TABLE(title text, total bigint)
 LANGUAGE plpgsql
AS $function$
BEGIN
  RETURN QUERY
WITH VAR_URUSAN_KOD_LIST AS (
    SELECT UNNEST(var_urusan_kod_list) AS KOD
  ),
VAR_PERANAN_KOD_PENGGUNA AS (
  SELECT DISTINCT PP.NAMA_PENGGUNA, RM.KOD AS PERANAN_KOD
  FROM PCP_CAPAIAN_PENGGUNA CP
  JOIN PCP_PENGGUNA PP ON CP.PENGGUNA_ID = PP.PENGGUNA_ID
  JOIN PCP_PERANAN_MODUL PM ON CP.PERANAN_MODUL_ID = PM.PERANAN_MODUL_ID
  JOIN RJK_SENARAI_AHLI_KUMPULAN RM ON PM.PERANAN_ID = RM.SENARAI_AHLI_KUMPULAN_ID
  WHERE PP.NAMA_PENGGUNA IN (var_nama_pengguna)
),
VAR_DAERAH_PENGGUNA AS (
    SELECT DISTINCT DAERAH_ID
    FROM IND_PEJABAT AS IP
    WHERE PEJABAT_ID IN (var_pejabat_id) 
),
VAR_PEJABAT_TERKAIT AS (
    SELECT DISTINCT PEJABAT_ID
    FROM IND_PEJABAT AS IP
    WHERE DAERAH_ID IN (SELECT DAERAH_ID FROM VAR_DAERAH_PENGGUNA)
),
VAR_FILTER_TUGASAN_KOD_SET AS (
	SELECT UNNEST(ARRAY[ 'PPBKRPJPM', 'PPBKRKPJPM', 'PTB', 'SJR',
    'PJR', 'CTK_JR', 'PMMP6PTB2', 'PPBBPTB2',
    'PPHSYBPTB2', 'PKJR', 'PKJRPP']) as stgsn_kod
),

VAR_PELUPUSAN_TUGASAN_FILTERED AS (
  SELECT ID_TGSN AS ID_TGSN_PELUPUSAN_PENGGUNA_FILTER
  FROM (
    SELECT A.ID_TGSN,
        ROW_NUMBER() OVER (
            PARTITION BY COALESCE(C.kod, E.kod), A.ID_TGSN
            ORDER BY A.ID_TGSN
    ) AS RN
    FROM UMM_TGSN_SEMASA A
    LEFT JOIN UMM_APLIKASI B ON B.APLIKASI_ID = A.APLIKASI_ID
    LEFT JOIN IND_URSN C ON C.URSN_ID = B.URSN_ID
    LEFT JOIN UMM_P_APLIKASI D ON D.APLIKASI_ID = A.APLIKASI_ID
    LEFT JOIN IND_URSN E ON E.URSN_ID = D.URSN_ID
    WHERE A.MODUL = 'PLP'
      AND A.KOD_TGSN = 'FPIKM'
      AND UPPER(A.FLAG_TGSN_SISTEM) = 'N'
  ) A
  WHERE RN = 1
),
VAR_PEJABAT_PERANAN_MAP AS (
  SELECT * FROM (VALUES
    ('TRG', ARRAY['PTG', 'TPTG', 'KPP']),
    ('PRK', ARRAY['PTG', 'KPP']),
    ('SEL', ARRAY['PTG', 'TPTG'])
  ) AS T (KOD_PEJABAT, PERANANS)
),
VAR_PLP_TUGASAN_KOD_SET AS (
    SELECT unnest(ARRAY['PDKM', 'SDKM', 'SDKM2', 'SDKM3', 'PPKM', 'CKM', 'CKMPPLN'])
),
VAR_ALSAN_TUKARGANTI_KOD_SET AS (
    SELECT unnest(ARRAY['KMPP', 'HMSC', 'HMSTP', 'PRBB', 'OPRBB', 'HDHD', 'HMPV', 'HMV', 'HMVB',
            'SSHM', 'SSSC', 'SW', 'SA', 'CRHMB', 'CSHMB', 'BETUL', 'PACT', 'PKH', 'PMKMH', 'PFT', 'REM', 'REMITAN'])
),
VAR_GROUP_BY_NO_FAIL_TUGASAN_KOD_SET AS (
    SELECT unnest(ARRAY['PPBKRPDPJPM', 'PPBKRSDPJPM', 'PPBKRCDPJPM'])
),

VAR_ALSAN_TUKARGANTI_KOD_SET_BATAL AS (
    SELECT unnest(ARRAY['HDHK', 'HPLN','PMKMH','HSSTB','HKSSS'])
),
VAR_NO_HAK_MILIK_BARU AS (
    SELECT 
        mohon.APLIKASI_ID,
        STRING_AGG(mohon.id_hkmlk, '<br>') AS NO_HAKMILIK_BARU
    FROM dft_A_MOHON_HKMLK mohon
    JOIN UMM_APLIKASI appl ON appl.APLIKASI_ID = mohon.APLIKASI_ID
    JOIN IND_URSN urusan ON appl.URSN_ID = urusan.URSN_ID
    JOIN rjk_jns_ursn jenis ON jenis.jns_ursn_id = urusan.jns_ursn_id
    WHERE mohon.id_hkmlk IS NOT NULL
      AND jenis.KOD = 'MH'
    GROUP BY mohon.APLIKASI_ID
),
MAIN_QUERY AS (
	SELECT 
  	DHAS_1.TGSN_SEMASA_ID,
	DHAS_1.TRKH_PNRMAN,
	MDL_1.KOD as MODUL,
	DHAS_1.ID_HKMLK,
	DHAS_1.NO_RESIT,
	DHAS_1.LOCKED_BY,
	DHAS_1.LOCKED_DATE,
	DHAS_1.PERANAN,
	DHAS_1.KOD_TGSN,
	DHAS_1.ID_TGSN,
	DHAS_1.TGSN_PERIHAL,
	DHAS_1.NAMA_PENGGUNA,
	APP_TGSN_1.TRKH_TETAP,
	APP_1.TRKH_PIAGAM,
	APP_1.APLIKASI_ID,
	APP_1.APLIKASI_ID as APP_ID,
	APP_1.RANGKAIAN_ID,
	APP_1.ID_PENGENALAN,
	APP_1.FLAG_INTEGRASI,
	APP_1.STATUS_KEPUTUSAN,
	COALESCE(APP_1.STATUS_PROSES, SNR_1.NAMA) AS STATUS_PROSES,
    COALESCE(URSN_1.KOD, URSN_2.KOD) AS URUSAN_KOD,
    COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI) AS NO_RUJUKAN,
	IPJ_1.NAMA_PENDEK,
	IPJ_1.KOD AS PEJABAT_KOD,
	HNTR_1.ID_PENGHANTARAN,
	DHAS_1.a_tgsn_id as APP_A_TGSN_ID,
	IPJ_1.NAMA_PENDEK as NAMA_PEJABAT_PENDEK,
	TO_CHAR(MLS.TRKH_SIASATAN, 'DD/MM/YYYY') AS TARIKH_SIASATAN_STRING,
	APP_1.ID_RUJUKAN_SMARTBOX,
	DHAS_1.TRKH_KPI AS DHAS_1_TRKH_KPI,
	ITG_1.MINIT_KPI,
	CASE 
      WHEN URSN_1.KOD = 'PSBS' AND DHAS_1.TGSN_PERIHAL = 'Penyediaan Fail Induk Kertas Mesyuarat' THEN FALSE
      ELSE TRUE 
    END AS SHOW_ID_HAKMILIK,
	(
      SELECT STRING_AGG(mohon.id_hkmlk, '<br>')
      FROM dft_A_MOHON_HKMLK mohon
      JOIN UMM_APLIKASI appl ON appl.APLIKASI_ID = mohon.APLIKASI_ID
      JOIN IND_URSN urusan ON appl.URSN_ID = urusan.URSN_ID
      JOIN rjk_jns_ursn jenis ON jenis.jns_ursn_id = urusan.jns_ursn_id
      WHERE mohon.APLIKASI_ID = DHAS_1.APLIKASI_ID
        AND mohon.id_hkmlk IS NOT NULL
        AND jenis.KOD = CAST('MH' AS VARCHAR)
    ) AS NO_HAKMILIK_BARU,
	
	CASE 
		WHEN DHAS_1.TRKH_KPI IS NULL 
		     AND ITG_1.MINIT_KPI IS NOT NULL 
		     AND DHAS_1.TRKH_PNRMAN IS NOT NULL
		THEN DHAS_1.TRKH_PNRMAN + (ITG_1.MINIT_KPI || ' minutes')::INTERVAL
		ELSE DHAS_1.TRKH_KPI
	END AS TRKH_KPI,
	CASE 
		WHEN APP_TGSN_1.STATUS_TUGASAN IS NULL 
			OR DHAS_1.TGSN_PERIHAL = 'Pengagihan Tugasan Baru' 
		THEN 'Baru'
		ELSE APP_TGSN_1.STATUS_TUGASAN
	END AS STATUS_TUGASAN,

	CASE 
		WHEN ITG_1.MINIT_KPI IS NOT NULL THEN TRUE
		ELSE FALSE
	END AS SHOW_KPI,
	CASE 
    WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
         AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
              OR DHAS_1.KOD_TGSN LIKE '%PTB%')
    THEN '-' 
    ELSE TO_CHAR(DHAS_1.TRKH_PNRMAN, 'DD/MM/YYYY')
	END AS TARIKH_PENERIMAAN_STRING,

	CASE 
	
		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
			AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
				OR DHAS_1.KOD_TGSN LIKE '%PTB%')
		THEN '-' 

		ELSE TO_CHAR(
			CASE
			WHEN ITG_1.MINIT_KPI IS NOT NULL 
				AND DHAS_1.TRKH_PNRMAN IS NOT NULL 
				AND DHAS_1.TRKH_KPI IS NULL
			THEN DHAS_1.TRKH_PNRMAN + (ITG_1.MINIT_KPI || ' minutes')::INTERVAL
			ELSE DHAS_1.TRKH_KPI
			END,
			'DD/MM/YYYY'
		)
	END AS TARIKH_DAN_MASA_LUPUT_STRING,
CASE
  WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL
       AND (
         DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
         OR DHAS_1.KOD_TGSN LIKE '%PTB%'
       )
  THEN NULL
  ELSE
    CASE
      WHEN ITG_1.MINIT_KPI IS NOT NULL
           AND DHAS_1.TRKH_PNRMAN IS NOT NULL
           AND DHAS_1.TRKH_KPI IS NULL
      THEN DHAS_1.TRKH_PNRMAN + (ITG_1.MINIT_KPI || ' minutes')::INTERVAL
      ELSE DHAS_1.TRKH_KPI
    END
END AS TARIKH_DAN_MASA_LUPUT,

	CASE 
		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
			AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
				OR DHAS_1.KOD_TGSN LIKE '%PTB%')
		THEN '-' 
		ELSE TO_CHAR(APP_1.TRKH_PIAGAM, 'DD/MM/YYYY')
	END AS TARIKH_PIAGAM_STRING,
	CASE 
		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
			AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
				OR DHAS_1.KOD_TGSN LIKE '%PTB%')
		THEN '-' 
		ELSE TO_CHAR(APP_TGSN_1.TRKH_TETAP, 'DD/MM/YYYY')
	END AS TARIKH_MULA_STRING,
	CASE 
		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
			AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
				OR DHAS_1.KOD_TGSN LIKE '%PTB%')
		THEN TRUE 
		ELSE FALSE 
	END AS IS_FILTER_TUGASAN,
	CASE
		WHEN ITG_1.MINIT_KPI IS NOT NULL 
			AND DHAS_1.TRKH_PNRMAN IS NOT NULL 
			AND DHAS_1.TRKH_KPI IS NULL
		THEN DHAS_1.TRKH_PNRMAN + (ITG_1.MINIT_KPI || ' minutes')::INTERVAL
		ELSE DHAS_1.TRKH_KPI
	END AS TARIKH_KPI,
	

	CASE 
	  WHEN NOT (
	    TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
	    AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
	         OR DHAS_1.KOD_TGSN LIKE '%PTB%')
	  )
	  THEN 
	    CASE 
	      WHEN COALESCE(NULLIF(TRIM(DHAS_1.ID_HKMLK), ''), '-') = '-' THEN '-'
	      ELSE (
	        SELECT 
	          CASE 
	            WHEN COUNT(*) > 10 
	            THEN (
	              SELECT string_agg(val, ', ') || '...'
	              FROM (
	                SELECT DISTINCT val
	                FROM unnest(string_to_array(DHAS_1.ID_HKMLK, ',')) AS val
	                ORDER BY val
	                LIMIT 10
	              ) sub
	            )
	            ELSE (
	              SELECT string_agg(DISTINCT val, ', ' ORDER BY val)
	              FROM unnest(string_to_array(DHAS_1.ID_HKMLK, ',')) AS val
	            )
	          END
	      )
	    END
	  ELSE COALESCE(NULLIF(TRIM(DHAS_1.ID_HKMLK), ''), '-') 
	END AS NO_HAKMILIK_DASHBOARD,
	CASE 
	  WHEN NOT (
	    TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
	    AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
	         OR DHAS_1.KOD_TGSN LIKE '%PTB%')
	  )
	  THEN COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
	  ELSE NULL
	END AS APLIKASI_NO_PERMOHONAN,
	
	
	CASE 
	  WHEN NOT (
	    TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
	    AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
	         OR DHAS_1.KOD_TGSN LIKE '%PTB%')
	  )
		  THEN 
		    CASE 
		      WHEN COALESCE(NULLIF(TRIM(DHAS_1.NO_RESIT), ''), '-') = '-' THEN '-'
		      ELSE (
		        SELECT 
		          CASE 
		            WHEN COUNT(*) > 10 
		            THEN (
		              SELECT string_agg(val, ', ') || '...'
		              FROM (
		                SELECT DISTINCT val
		                FROM unnest(string_to_array(DHAS_1.NO_RESIT, ',')) AS val
		                ORDER BY val
		                LIMIT 10
		              ) sub
		            )
		            ELSE (
		              SELECT string_agg(DISTINCT val, ', ' ORDER BY val)
		              FROM unnest(string_to_array(DHAS_1.NO_RESIT, ',')) AS val
		            )
		          END
		      )
		    END
		  ELSE COALESCE(NULLIF(TRIM(DHAS_1.NO_RESIT), ''), '-') 
		END AS NO_RESIT_DASHBOARD,
		
		
		CASE
		  WHEN NOT (
		    TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
		    AND (
		      DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
		      OR DHAS_1.KOD_TGSN LIKE '%PTB%'
		    )
		  )
		  THEN
		    CASE 
		      WHEN HNTR_1.ID_PENGHANTARAN IS NOT NULL AND HNTR_1.ID_PENGHANTARAN LIKE 'PNL/%'
		        THEN 'UPNL'
		      ELSE COALESCE(URSN_1.KOD, URSN_2.KOD)
		    END
		  ELSE
		    COALESCE(URSN_1.KOD, URSN_2.KOD)
		END AS URUSAN_KOD_DASHBOARD,

		CASE
		  WHEN UPPER(APP_1.FLAG_INTEGRASI) ='Y' THEN
		    CASE
		      WHEN COALESCE(COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI), '') LIKE '%MF%' 
		           AND COALESCE(COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI), '') LIKE '%(%' THEN
		        SPLIT_PART(COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI), '(', 1)
		        
		      WHEN COALESCE(APP_1.URSN_ID, URSN_2.URSN_ID) IS NOT NULL 
		           AND COALESCE(URSN_1.KOD, URSN_2.KOD) = 'KVSP' THEN
		        (
		          SELECT hubungan2.ID_PENGENALAN || ' / ' || COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
		          FROM UMM_APLIKASI hubungan1
		          JOIN UMM_APLIKASI hubungan2 ON hubungan1.ID_PENGENALAN = hubungan2.APLIKASI_ID
		          WHERE hubungan1.APLIKASI_ID = APP_1.APLIKASI_ID
		          LIMIT 1
		        )
		        
		      ELSE
		        (
		          SELECT hubungan.no_rujukan_fail || ' / ' || COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
		          FROM UMM_APLIKASI hubungan
		          WHERE hubungan.APLIKASI_ID = APP_1.APLIKASI_ID
		          LIMIT 1
		        )
		    END
		  WHEN DHAS_1.KOD_TGSN  = 'STRSPRAP' THEN
		    APP_A_1.ID_TRANSAKSI

		   WHEN COALESCE(URSN_1.KOD, URSN_2.KOD) IN ('HDHK', 'HDHD', 'KVSPM')
    AND NOT (
      DHAS_1.MODUL = 'PNT'
      AND HNTR_1.ID_PENGHANTARAN LIKE 'PNL/%'
      AND APP_1.MKLMT_TMBHN IS NOT NULL
      AND APP_1.MKLMT_TMBHN::jsonb ->> 'idPengenalanInduk' IS NOT NULL
    )
  THEN
    COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI) || 
    ' ' || (
      SELECT ID_PENGENALAN 
      FROM UMM_APLIKASI 
      WHERE NO_RUJUKAN_FAIL = COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
      LIMIT 1
    )

  WHEN DHAS_1.MODUL = 'PNT'
    AND HNTR_1.ID_PENGHANTARAN LIKE 'PNL/%'
    AND APP_1.MKLMT_TMBHN IS NOT NULL
    AND APP_1.MKLMT_TMBHN::jsonb ->> 'idPengenalanInduk' IS NOT NULL
  THEN
    APP_1.MKLMT_TMBHN::jsonb ->> 'idPengenalanInduk'

		  ELSE
		    COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
		END AS ID_PERMOHONAN_DASHBOARD,
	
		  CASE
		    WHEN DHAS_1.kod_tgsn IN ('PPF', 'PPJUB', 'PPPK', 'PPSYT') THEN org_nama.nama
		    WHEN URSN_1.kod = 'PPLBL' THEN pelelong_nama.nama_pemohon
		    ELSE bkptg_nama.nama
		  END AS NAMA_PEMOHON,
		  COALESCE(KS.NO_KERTAS_SIASATAN, APP_1.NO_RUJUKAN_FAIL, '') as NO_FAIL_PEMOHON
		    
		


FROM UMM_TGSN_SEMASA DHAS_1

LEFT JOIN UMM_APLIKASI APP_1 ON DHAS_1.APLIKASI_ID = APP_1.APLIKASI_ID
LEFT JOIN UMM_APLIKASI APP_2 ON DHAS_1.APLIKASI_ID = APP_2.APLIKASI_ID
LEFT JOIN IND_URSN URSN_1 ON APP_2.URSN_ID = URSN_1.URSN_ID

LEFT JOIN IND_MODUL MDL_1 ON URSN_1.MODUL_ID = MDL_1.MODUL_ID

LEFT JOIN UMM_APLIKASI APP_3 ON DHAS_1.APLIKASI_ID = APP_3.APLIKASI_ID
LEFT JOIN UMM_APLIKASI APP_4 ON APP_3.HUBUNGAN_APLIKASI_ID = APP_4.APLIKASI_ID

LEFT JOIN UMM_P_APLIKASI APP_A_1 ON DHAS_1.P_APLIKASI_ID = APP_A_1.P_APLIKASI_ID
LEFT JOIN UMM_P_APLIKASI APP_A_2 ON DHAS_1.P_APLIKASI_ID = APP_A_2.P_APLIKASI_ID
LEFT JOIN IND_URSN URSN_2 ON APP_A_2.URSN_ID = URSN_2.URSN_ID
LEFT JOIN UMM_P_APLIKASI APP_A_3 ON DHAS_1.P_APLIKASI_ID = APP_A_3.P_APLIKASI_ID

LEFT JOIN RJK_JNS_URSN RJU_1  on URSN_1.JNS_URSN_ID = RJU_1.JNS_URSN_ID
LEFT JOIN RJK_SENARAI_AHLI_KUMPULAN SNR_1 ON APP_A_3.STATUS_ID = SNR_1.SENARAI_AHLI_KUMPULAN_ID

LEFT JOIN UMM_A_TGSN APP_TGSN_1 ON DHAS_1.A_TGSN_ID = APP_TGSN_1.A_TGSN_ID
LEFT JOIN UMM_A_TGSN APP_TGSN_2 ON DHAS_1.A_TGSN_ID = APP_TGSN_2.A_TGSN_ID
LEFT JOIN IND_TGSN ITG_1 ON APP_TGSN_2.TGSN_ID = ITG_1.TGSN_ID

LEFT JOIN UMM_A_TGSN APP_A_4 ON DHAS_1.A_TGSN_ID = APP_A_4.A_TGSN_ID
LEFT JOIN PCP_PENGGUNA PGN_1 ON APP_A_4.PENGGUNA_SEMASA_ID = PGN_1.PENGGUNA_ID

LEFT JOIN UMM_MKLMT_LAPORAN_SIASATAN MLS ON DHAS_1.MKLMT_LAPORAN_SIASATAN_ID = MLS.MKLMT_LAPORAN_SIASATAN_ID

LEFT JOIN IND_PEJABAT IPJ_1 ON DHAS_1.PEJABAT_ID = IPJ_1.PEJABAT_ID
LEFT JOIN UMM_HANTARAN_NOTIS HNTR_1 ON DHAS_1.HANTARAN_NOTIS_ID = HNTR_1.HANTARAN_NOTIS_ID
LEFT JOIN PKS_A_KERTAS_SIASATAN KS ON DHAS_1.A_KERTAS_SIASATAN_ID = KS.A_KERTAS_SIASATAN_ID




LEFT JOIN LATERAL (
	  SELECT o.nama
	  FROM umm_p_daftar_organisasi o
	  WHERE o.p_daftar_organisasi_id IN (
	    SELECT MIN(o2.p_daftar_organisasi_id)
	    FROM umm_p_daftar_organisasi o2
	    WHERE APP_A_1.id_transaksi = APP_1.id_pengenalan
	  )
	  LIMIT 1
	) AS org_nama ON DHAS_1.kod_tgsn IN ('PPF', 'PPJUB', 'PPPK', 'PPSYT')
	
	-- Join nama pelelong jika kod urusan 'PPLBL'
	LEFT JOIN LATERAL (
	  SELECT p.nama_pemohon
	  FROM llg_a_daftar_pelelong p
	  WHERE p.aplikasi_id = DHAS_1.aplikasi_id
	  ORDER BY p.a_daftar_pelelong_id ASC
	  LIMIT 1
	) AS pelelong_nama ON URSN_1.kod = 'PPLBL'
	
	-- Join nama pihak berkepentingan
	LEFT JOIN LATERAL (
	  SELECT r.nama
	  FROM umm_a_pihak_bkptg r
	  WHERE r.aplikasi_id = DHAS_1.aplikasi_id
	    AND UPPER(r.flag_pemohon) = 'Y'
	  ORDER BY r.a_pihak_bkptg_id ASC
	  LIMIT 1
	) AS bkptg_nama ON TRUE
  	
	WHERE UPPER(DHAS_1.FLAG_TGSN_SISTEM) = 'N'
	AND (DHAS_1.NAMA_PENGGUNA = var_nama_pengguna OR DHAS_1.NAMA_PENGGUNA IS NULL)
	AND (EXISTS (
        SELECT 1 FROM VAR_PERANAN_KOD_PENGGUNA PKP
        WHERE PKP.NAMA_PENGGUNA = DHAS_1.NAMA_PENGGUNA AND PKP.peranan_kod = 'PTG'
    	) OR DHAS_1.PEJABAT_ID IN (SELECT PEJABAT_ID FROM VAR_PEJABAT_TERKAIT) OR DHAS_1.PEJABAT_ID IS NULL
	)

	AND (
		URSN_1.KOD IN (SELECT KOD FROM VAR_URUSAN_KOD_LIST)
		OR URSN_2.KOD IN (SELECT KOD FROM VAR_URUSAN_KOD_LIST)
	)

	AND EXISTS ( 
		SELECT 1
		FROM VAR_PERANAN_KOD_PENGGUNA PKP
		WHERE DHAS_1.PERANAN LIKE '%-' || PKP.PERANAN_KOD || '-%'
	)
	AND (APP_TGSN_1.A_TGSN_ID is null or APP_TGSN_1.A_TGSN_ID is not null )
	
	),

VAR_GROUPED_TUGAS AS (
    SELECT
        mq.*,
        ROW_NUMBER() OVER (PARTITION BY ua.no_fail, mq.kod_tgsn ORDER BY mq.tgsn_semasa_id) AS rn
    FROM MAIN_QUERY mq
    LEFT JOIN umm_aplikasi ua ON mq.aplikasi_id = ua.aplikasi_id
    WHERE mq.kod_tgsn IN ('PPBKRPDPJPM', 'PPBKRSDPJPM', 'PPBKRCDPJPM') 
),
VAR_MODUL_PENGGUNA AS (
  SELECT DISTINCT p.nama_pengguna, m.kod AS modul_kod
  FROM pcp_capaian_pengguna cp
  JOIN pcp_pengguna p ON cp.pengguna_id = p.pengguna_id
  JOIN pcp_peranan_modul pm ON cp.peranan_modul_id = pm.peranan_modul_id
  JOIN ind_modul m ON pm.modul_id = m.modul_id
  WHERE p.nama_pengguna IN (var_nama_pengguna) 
    AND m.kod IN ('PNT', 'UAM')
),

VAR_BELUM_TUKAR_GANTI AS (
 SELECT unnest(ARRAY['HMSC', 'HMSTP', 'PRBB', 'OPRBB', 'HDHD', 'HMPV', 'HMV','HMVB','SSHM','SSSC','SW','SA','CRHMB','CSHMB','BETUL','PACT','PKH','PMKMH','PFT','REM','REMITAN'])
),
FINAL_QUERY_V1 AS (
	SELECT * FROM MAIN_QUERY AS DEFAULT_MAIN_PNT
	WHERE EXISTS (
	    SELECT 1
	    FROM VAR_MODUL_PENGGUNA mp
	    WHERE mp.nama_pengguna = DEFAULT_MAIN_PNT.nama_pengguna
	      OR DEFAULT_MAIN_PNT.modul IN ('PNT', 'UAM')
	  )
	AND DEFAULT_MAIN_PNT.kod_tgsn NOT IN ('KD', 'STRKD')
		AND NOT (
		  DEFAULT_MAIN_PNT.modul = 'CON'
		  AND DEFAULT_MAIN_PNT.kod_tgsn IN ('CSK', 'JSK')
		)
	UNION ALL
	SELECT * FROM MAIN_QUERY AS DEFAULT_MAIN
	WHERE DEFAULT_MAIN.KOD_TGSN NOT IN ('KD', 'STRKD')
	AND NOT (
	    DEFAULT_MAIN.MODUL = 'CON' AND 
	    (DEFAULT_MAIN.KOD_TGSN = 'CSK' OR DEFAULT_MAIN.KOD_TGSN = 'JSK')
	)
	AND DEFAULT_MAIN.MODUL NOT IN ('PNT', 'UAM')
	AND NOT (
	    DEFAULT_MAIN.kod_tgsn IN ('KD', 'STRKD')
	    OR (DEFAULT_MAIN.NAMA_PENGGUNA IS NOT NULL AND DEFAULT_MAIN.NAMA_PENGGUNA <> var_nama_pengguna)
	)
	AND NOT (
	    DEFAULT_MAIN.KOD_TGSN = 'PTBUT'
	    AND DEFAULT_MAIN.URUSAN_KOD IN ('PMQFT', 'PMQTFT')
	)

),

FIANL_QUERY_MERGE as (
	select * FROM FINAL_QUERY_V1 as FN_Q1
	WHERE NOT EXISTS (
		SELECT 1
   		FROM VAR_FILTER_TUGASAN_KOD_SET 
		 WHERE
	      (
	        stgsn_kod = 'PTB'
	        AND FN_Q1.KOD_TGSN LIKE '%' || stgsn_kod || '%'
	      )
			OR (
		    stgsn_kod <> 'PTB'
			  AND FN_Q1.KOD_TGSN = stgsn_kod
			)
	)

 	UNION ALL
	SELECT * from (

		SELECT DISTINCT ON (FN_Q1_v2.KOD_TGSN) FN_Q1_v2.*
		FROM FINAL_QUERY_V1 as FN_Q1_v2
		WHERE EXISTS (
			 SELECT 1
      		FROM VAR_FILTER_TUGASAN_KOD_SET
			where (
					UPPER(FN_Q1_v2.STATUS_PROSES) <> 'GANTUNG'

					AND (
			          (stgsn_kod = 'PTB' AND FN_Q1_v2.KOD_TGSN LIKE '%' || stgsn_kod || '%')
			          OR (stgsn_kod = 'SJR' AND FN_Q1_v2.KOD_TGSN LIKE '%' || stgsn_kod || '%')
			          OR (stgsn_kod = 'CTK_JR' AND FN_Q1_v2.KOD_TGSN LIKE '%' || stgsn_kod || '%')
			          OR (stgsn_kod = 'PJR' AND FN_Q1_v2.KOD_TGSN LIKE '%' || stgsn_kod || '%')
			          OR (
			            stgsn_kod NOT IN ('PTB', 'SJR', 'CTK_JR', 'PJR')
			            AND FN_Q1_v2.KOD_TGSN = stgsn_kod
			          )
			        )
			) order by FN_Q1_v2.KOD_TGSN, FN_Q1_v2.tgsn_semasa_id desc
		) limit 1 
	)

),
VAR_USER_PERANAN AS (
  SELECT LOWER(mdl.kod) AS modul, LOWER(sak.kod) AS peranan
  FROM pcp_capaian_pengguna cp
  JOIN pcp_pengguna pg ON cp.pengguna_id = pg.pengguna_id
  JOIN pcp_peranan_modul pm ON cp.peranan_modul_id = pm.peranan_modul_id
  JOIN ind_modul mdl ON pm.modul_id = mdl.modul_id
  JOIN rjk_senarai_ahli_kumpulan sak ON pm.peranan_id = sak.senarai_ahli_kumpulan_id
  WHERE pg.nama_pengguna = var_nama_pengguna
),
FINAL_QUERY AS (
  SELECT * 
  FROM FIANL_QUERY_MERGE AS DEFAULT_MAIN
  WHERE 1=1


 AND (
    -- Ambil jika bukan PTB dan nama_pengguna tidak kosong
    (
      DEFAULT_MAIN.kod_tgsn NOT ILIKE '%PTB%'
      AND COALESCE(TRIM(DEFAULT_MAIN.nama_pengguna), '') <> ''
    )
    -- Atau: jika PTB / nama kosong, validasi modul dan peranan terhadap VAR_USER_PERANAN
    OR EXISTS (
      SELECT 1
      FROM VAR_USER_PERANAN u
      WHERE LOWER(u.modul) = LOWER(DEFAULT_MAIN.modul)
        AND EXISTS (
          SELECT 1
          FROM unnest(string_to_array(LOWER(DEFAULT_MAIN.peranan), '-')) AS p(peranan)
          WHERE p.peranan = u.peranan
        )
        AND (
          DEFAULT_MAIN.kod_tgsn ILIKE '%PTB%'
          OR COALESCE(TRIM(DEFAULT_MAIN.nama_pengguna), '') = ''
        )
    )
  
    )
    AND NOT (
      DEFAULT_MAIN.id_rujukan_smartbox IS NOT NULL
      AND DEFAULT_MAIN.id_rujukan_smartbox <> ''
      AND DEFAULT_MAIN.kod_tgsn IN ('ISHSB', 'KDSB')
    )
),

URUSAN_MODUL_PARENT_CTE AS (
  SELECT 
    A.APLIKASI_ID as APP_ID_CTE,
    M.KOD AS URUSAN_MODUL_PARENT
  FROM UMM_APLIKASI A
  LEFT JOIN IND_URSN U ON A.URSN_ID = U.URSN_ID
  LEFT JOIN IND_MODUL M ON U.MODUL_ID = M.MODUL_ID
),

VAR_CONSENT_KOD AS (
    SELECT unnest(ARRAY['PFMMK', 'PPPTG', 'SFMMK', 'SPTPTG', 'KPTG','KTPTG','KCADO','KDO','PDO','STSKP','KPTG2', 'KMB'])
),
CONSENT_FILTER AS (
	SELECT *
	FROM FINAL_QUERY f
	WHERE f.MODUL = 'CON'
	  AND NOT (
	    f.urusan_kod_dashboard = 'KPMP'
	    AND var_kod_negri = '08' -- 11= param
	  )
	  AND f.KOD_TGSN IN (SELECT * FROM VAR_CONSENT_KOD) 
),


CONSENT_FILTER_ONE as (
	SELECT *
	FROM CONSENT_FILTER CON
	ORDER BY CON.tgsn_semasa_id
	LIMIT 1
),

FINAL_FILTER_CON as (
SELECT *
	FROM FINAL_QUERY a
--	WHERE a.modul <> 'CON'

	UNION ALL

	SELECT * FROM CONSENT_FILTER_ONE
),
FINAL_FILTER_ALL  AS (
	SELECT * FROM FINAL_FILTER_CON AS FQ
	
	WHERE 1=1
	AND NOT (
		FQ.MODUL = 'PFIKM'   
		OR FQ.ID_TGSN IN (SELECT ID_TGSN_PELUPUSAN_PENGGUNA_FILTER FROM VAR_PELUPUSAN_TUGASAN_FILTERED)	
  	)
	AND NOT (FQ.modul = 'UAM' AND FQ.URUSAN_KOD = 'BIO')

    AND NOT (
      COALESCE(TRIM(FQ.locked_by), '') <> ''
      AND LOWER(FQ.locked_by) <> LOWER(var_nama_pengguna)
      AND FQ.locked_date IS NOT NULL
      AND FQ.locked_date > NOW() - INTERVAL '30 minutes'
    )
-- NEW 

OR FQ.modul IS NULL
	 
),

FINAL_FILTER_ALL_V2 as (
	SELECT * FROM FINAL_FILTER_ALL
),


FINAL_RESULT AS (
	SELECT * ,
	CASE 
	  WHEN EXISTS (
	    SELECT 1
	    FROM UMM_PERTANYAAN p
	    JOIN RJK_SENARAI_AHLI_KUMPULAN k ON p.STATUS_ID = k.SENARAI_AHLI_KUMPULAN_ID
	    JOIN UMM_APLIKASI a ON p.APLIKASI_ID = a.APLIKASI_ID
	    JOIN IND_URSN u ON a.URSN_ID = u.URSN_ID
	    WHERE p.A_TGSN_ID = FQ.APP_A_TGSN_ID
	      AND k.KOD != 'SELESAI'
	      AND u.TEMPOH_KUIRI ~ '^[0-9]+$'
	      AND DATE_PART('day', CURRENT_DATE - p.CREATED_DATE) > u.TEMPOH_KUIRI::INT
	  )
	  THEN ' (Pertanyaan) - Telah Melebihi Tempoh Kuiri'
	
	  WHEN EXISTS (
	    SELECT 1
	    FROM UMM_PERTANYAAN p
	    JOIN RJK_SENARAI_AHLI_KUMPULAN k ON p.STATUS_ID = k.SENARAI_AHLI_KUMPULAN_ID
	    WHERE p.A_TGSN_ID = FQ.APP_A_TGSN_ID
	      AND k.KOD != 'SELESAI'
	  )
	  THEN ' (Pertanyaan)'
	
	  ELSE NULL
	END AS pertanyaan_keterangan,


	--	color and flag
	CASE 
	    WHEN (
	        CASE
	            WHEN FQ.MINIT_KPI IS NOT NULL 
	                 AND FQ.TRKH_PNRMAN IS NOT NULL 
	                 AND FQ.DHAS_1_TRKH_KPI IS NULL
	            THEN FQ.TRKH_PNRMAN + (FQ.MINIT_KPI || ' minutes')::INTERVAL
	            ELSE FQ.DHAS_1_TRKH_KPI
	        END
	    ) IS NOT NULL 
	    AND (
	        CASE
	            WHEN FQ.MINIT_KPI IS NOT NULL 
	                 AND FQ.TRKH_PNRMAN IS NOT NULL 
	                 AND FQ.DHAS_1_TRKH_KPI IS NULL
	            THEN FQ.TRKH_PNRMAN + (FQ.MINIT_KPI || ' minutes')::INTERVAL
	            ELSE FQ.DHAS_1_TRKH_KPI
	        END
	    ) < CURRENT_DATE
	THEN 'TUNGGAK'
	ELSE NULL
	END AS STATUS,
	CASE 
	    WHEN (
	        CASE
	            WHEN FQ.MINIT_KPI IS NOT NULL 
	                 AND FQ.TRKH_PNRMAN IS NOT NULL 
	                 AND FQ.TRKH_KPI IS NULL
	            THEN FQ.TRKH_PNRMAN + (FQ.MINIT_KPI || ' minutes')::INTERVAL
	            ELSE FQ.DHAS_1_TRKH_KPI
	        END
	    ) IS NOT NULL 
	    AND (
	        CASE
	            WHEN FQ.MINIT_KPI IS NOT NULL 
	                 AND FQ.TRKH_PNRMAN IS NOT NULL 
	                 AND FQ.TRKH_KPI IS NULL
	            THEN FQ.TRKH_PNRMAN + (FQ.MINIT_KPI || ' minutes')::INTERVAL
	            ELSE FQ.DHAS_1_TRKH_KPI
	        END
	    ) < CURRENT_DATE
	THEN 'red' -- warna merah sebagai contoh
	ELSE NULL
	END AS COLOR,


	CASE
	    WHEN NOT FQ.SHOW_KPI THEN 'Hijau'
	    WHEN FQ.TARIKH_DAN_MASA_LUPUT_STRING IS NULL OR FQ.TARIKH_DAN_MASA_LUPUT_STRING = '-' THEN 'Hijau'
	    WHEN FQ.TRKH_TETAP IS NULL THEN
	        CASE
	            WHEN TO_DATE(FQ.TARIKH_DAN_MASA_LUPUT_STRING, 'DD/MM/YYYY') >= CURRENT_DATE THEN 'Hijau'
	            ELSE 'Merah'
	        END
	    WHEN TO_DATE(FQ.TARIKH_DAN_MASA_LUPUT_STRING, 'DD/MM/YYYY') <= FQ.TRKH_TETAP::DATE THEN 'Hijau'
	    ELSE 'Merah'
	END AS FLAG_STATUS,

	--end color and flag

CASE
  WHEN FQ.KOD_TGSN = 'ISH' THEN TRUE
  WHEN FQ.MODUL = 'KKS' THEN TRUE
  WHEN FQ.MODUL = 'PNT' AND URUSAN_MODUL_PARENT = 'KKS' THEN TRUE
  WHEN EXISTS (
    SELECT 1
    FROM UNNEST(STRING_TO_ARRAY(FQ.URUSAN_KOD_DASHBOARD, '<BR />')) AS URSN
    WHERE URSN IN (SELECT * FROM VAR_BELUM_TUKAR_GANTI)
  ) THEN TRUE
  WHEN EXISTS (
    SELECT 1
    FROM UNNEST(STRING_TO_ARRAY(FQ.URUSAN_KOD_DASHBOARD, '<BR />')) AS URSN
    WHERE URSN IS NOT NULL
      AND (
        URSN NOT IN (SELECT * FROM VAR_BELUM_TUKAR_GANTI)
        OR URSN IN (SELECT * FROM VAR_ALSAN_TUKARGANTI_KOD_SET_BATAL)
      )
or (
    (
      SELECT COUNT(*) FROM DFT_A_MOHON_HKMLK HM
      JOIN IND_MKLMT_HKMLK MH ON MH.mklmt_hkmlk_id = HM.ID_HKMLK
      JOIN rjk_senarai_ahli_kumpulan o ON o.senarai_ahli_kumpulan_id = MH.status_hkmlk_id
      WHERE HM.APLIKASI_ID = FQ.APLIKASI_ID AND o.kod = 'STAHMBT'
    ) = (
      SELECT COUNT(*) FROM DFT_A_MOHON_HKMLK HM
      WHERE HM.APLIKASI_ID = FQ.APLIKASI_ID
    )
    or NOT EXISTS (
      SELECT 1
      FROM DFT_A_MOHON_HKMLK HM
      JOIN IND_MKLMT_HKMLK MH ON MH.mklmt_hkmlk_id = HM.ID_HKMLK
      JOIN RJK_SENARAI_AHLI_KUMPULAN o ON o.senarai_ahli_kumpulan_id = MH.status_hkmlk_id
      WHERE HM.APLIKASI_ID = FQ.APLIKASI_ID
      AND o.kod = 'STAHDFT'
      AND EXISTS (
        SELECT 1 FROM IND_VERSI_DHD TG WHERE TG.hkmlk_id = HM.ID_HKMLK
      )
    )
  )
  )
  
  THEN TRUE
  ELSE FALSE
END AS IS_HAKMILIK_BELUM_TUKARGANTI,



CASE 
  WHEN FQ.TARIKH_DAN_MASA_LUPUT IS NULL THEN '-' 

  WHEN FQ.TARIKH_DAN_MASA_LUPUT <= NOW() THEN '0 Hari'

  WHEN DATE_PART('month', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 THEN
    TRIM(BOTH FROM CONCAT_WS(' ',
      CASE 
        WHEN DATE_PART('month', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('month', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Bulan' 
      END,
      CASE 
        WHEN DATE_PART('day', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('day', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Hari' 
      END,
      CASE 
        WHEN DATE_PART('hour', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('hour', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Jam' 
      END,
      CASE 
        WHEN DATE_PART('minute', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('minute', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Minit' 
      END
    ))

  ELSE
    TRIM(BOTH FROM CONCAT_WS(' ',
      CASE 
        WHEN DATE_PART('day', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('day', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Hari' 
      END,
      CASE 
        WHEN DATE_PART('hour', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('hour', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Jam' 
      END,
      CASE 
        WHEN DATE_PART('minute', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('minute', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Minit' 
      END
    ))
END AS BAKI_MASA





	
FROM FINAL_FILTER_ALL_V2 AS FQ 
LEFT JOIN URUSAN_MODUL_PARENT_CTE UMP ON UMP.APP_ID_CTE = FQ.APP_ID
where UPPER(FQ.STATUS_TUGASAN) <> 'SELESAI'
--	WHERE 1=1
--	AND NOT (
--		FQ.MODUL = 'PFIKM'   
--		OR FQ.ID_TGSN IN (SELECT ID_TGSN_PELUPUSAN_PENGGUNA_FILTER FROM VAR_PELUPUSAN_TUGASAN_FILTERED)	
--  	)
--AND NOT (FQ.modul = 'UAM' AND FQ.URUSAN_KOD = 'BIO')


),



 RANGKAIAN_MERGERED AS (
    SELECT 
    MAX(fd.TGSN_SEMASA_ID)::BIGINT AS ID,
    MAX(fd.TRKH_PNRMAN) AS TRKH_PEN,
    MAX(fd.TARIKH_PENERIMAAN_STRING) AS TARIKH_PENERIMAAN_STRING,
    MAX(fd.TARIKH_DAN_MASA_LUPUT_STRING) AS TARIKH_DAN_MASA_LUPUT_STRING,
    STRING_AGG(fd.ID_HKMLK, '<br />') AS no_hakmilik,
    ra.RANGKAIAN_ID::TEXT AS rangkaian_id_merged,
    fd.kod_tgsn::TEXT,
    STRING_AGG(fd.ID_PERMOHONAN_DASHBOARD ::TEXT, '<br />') AS id_permohonan,
    STRING_AGG(fd.URUSAN_KOD_DASHBOARD ::TEXT, '<br />') AS urusan,
    MAX(fd.NO_FAIL_PEMOHON) AS NO_FAIL_PEMOHON,
    STRING_AGG(fd.NO_RESIT_DASHBOARD :: TEXT, '<br />') AS no_resit,
	MAX(fd.TGSN_PERIHAL) as tugas,
    MAX(fd.NAMA_PEMOHON) AS NAMA_PEMOHON,
    MAX(fd.NAMA_PEJABAT_PENDEK) AS PEJABAT,
    MAX(fd.ID_PENGHANTARAN) AS ID_PENYAMPAIAN,
	MAX(fd.APP_A_TGSN_ID ) as id_APP_A_TGSN,
	MAX(fd.APLIKASI_ID),
	MAX(fd.pertanyaan_keterangan) AS pertanyaan_keterangan,
	MAX(fd.TARIKH_SIASATAN_STRING) as TARIKH_SIASATAN_STRING,
	MAX(fd.STATUS) as ROW_STATUS,
	MAX(fd.COLOR) as ROW_COLOR,
	MAX(fd.FLAG_STATUS) as FLAG_STATUS,
	(MAX(CASE WHEN fd.IS_HAKMILIK_BELUM_TUKARGANTI THEN 1 ELSE 0 END) = 1),
	MAX(fd.BAKI_MASA) as BAKI_MASA,
	MAX(fd.NO_HAKMILIK_BARU) as NO_HAKMILIK_BARU,
  MAX(fd.STATUS_TUGASAN) as STATUS_TUGASAN

    FROM FINAL_RESULT fd
    JOIN UMM_APLIKASI ra ON fd.APLIKASI_ID = ra.APLIKASI_ID
    WHERE ra.RANGKAIAN_ID IS NOT NULL AND fd.kod_tgsn <> 'IMH'
    GROUP BY ra.RANGKAIAN_ID, fd.kod_tgsn
  ),

  REMAINING_ROW AS (
    SELECT 
    fd.TGSN_SEMASA_ID::BIGINT AS ID,
    fd.TRKH_PNRMAN AS TRKH_PEN,
    fd.TARIKH_PENERIMAAN_STRING,
    fd.TARIKH_DAN_MASA_LUPUT_STRING,
    fd.ID_HKMLK AS no_hakmilik,
      NULL::TEXT AS rangkaian_id_merged,
    fd.kod_tgsn::TEXT,
    fd.ID_PERMOHONAN_DASHBOARD AS id_permohonan,
    fd.URUSAN_KOD_DASHBOARD AS urusan,
    fd.NO_FAIL_PEMOHON AS NO_FAIL_PEMOHON,
    fd.NO_RESIT_DASHBOARD AS no_resit,
	fd.TGSN_PERIHAL as tugas,
    fd.NAMA_PEMOHON AS NAMA_PEMOHON,
    fd.NAMA_PEJABAT_PENDEK AS PEJABAT,
    fd.ID_PENGHANTARAN AS ID_PENYAMPAIAN,
	fd.APP_A_TGSN_ID as id_APP_A_TGSN,
	fd.APLIKASI_ID,
	fd.pertanyaan_keterangan,
	fd.TARIKH_SIASATAN_STRING as TARIKH_SIASATAN_STRING,
	fd.STATUS as ROW_STATUS,
	fd.COLOR as ROW_COLOR,
	fd.FLAG_STATUS as FLAG_STATUS, 
	fd.IS_HAKMILIK_BELUM_TUKARGANTI,
	fd.BAKI_MASA as BAKI_MASA, 
	fd.NO_HAKMILIK_BARU as NO_HAKMILIK_BARU,
  fd.STATUS_TUGASAN as STATUS_TUGASAN

    FROM FINAL_RESULT fd
    LEFT JOIN UMM_APLIKASI ra ON fd.APLIKASI_ID = ra.APLIKASI_ID
--    WHERE ra.RANGKAIAN_ID IS NULL OR fd.kod_tgsn = 'IMH'
  ),


  FINAL_V2 AS (
  SELECT DISTINCT ON (merged.id) merged.*
  FROM (
    SELECT * FROM RANGKAIAN_MERGERED
    UNION ALL
    SELECT * FROM REMAINING_ROW
  ) merged

),
FINAL_OUTPUT AS (

 	SELECT 
        'Tugasan' AS title, COUNT(*) AS total
    FROM 
        FINAL_V2 V2
    WHERE 
        UPPER(V2.STATUS_TUGASAN) IN ('BARU','DALAM TINDAKAN')
	UNION ALL 
    SELECT 
        'Baru' AS title, COUNT(*) AS total
    FROM 
        FINAL_V2 V2
    WHERE 
        UPPER(V2.STATUS_TUGASAN) = 'BARU'

    UNION ALL

    SELECT 
        'Dalam Tindakan' AS title, COUNT(*) AS total
    FROM 
        FINAL_V2 V2
    WHERE 
        UPPER(V2.STATUS_TUGASAN) = 'DALAM TINDAKAN'

	UNION ALL

    SELECT 'Selesai' AS title, COUNT(*) AS total
	FROM UMM_A_TGSN A_APP1 
	INNER JOIN UMM_APLIKASI APP_1 ON A_APP1.APLIKASI_ID=APP_1.APLIKASI_ID 
	INNER JOIN UMM_APLIKASI APP_2 ON A_APP1.APLIKASI_ID=APP_2.APLIKASI_ID 
	INNER JOIN IND_URSN URSN_1 ON APP_2.URSN_ID=URSN_1.URSN_ID 
	INNER JOIN IND_MODUL MOD_1 ON URSN_1.MODUL_ID=MOD_1.MODUL_ID 
	CROSS JOIN PCP_PENGGUNA CP_PEN 
	WHERE A_APP1.PENGGUNA_SEMASA_ID=CP_PEN.PENGGUNA_ID 
	AND (A_APP1.PENGGUNA_SEMASA_ID IS NOT NULL) AND (CP_PEN.NAMA_PENGGUNA=var_nama_pengguna)
	AND (A_APP1.STATUS_TUGASAN IS NOT NULL) AND UPPER(A_APP1.STATUS_TUGASAN)='SELESAI'
),

FINAL_OUTPUT_V2 AS (
	SELECT * FROM FINAL_OUTPUT 
	UNION ALL
	SELECT 
		'Jumlah Tugasan' AS title,
		(SELECT FO.total FROM FINAL_OUTPUT FO WHERE UPPER(FO.title) = 'TUGASAN') + 
		(SELECT FO.total FROM FINAL_OUTPUT FO WHERE UPPER(FO.title) = 'SELESAI') AS total
)


SELECT * FROM FINAL_OUTPUT_V2 FO_V2
WHERE UPPER(FO_V2.title) <> 'TUGASAN';

	
END;
$function$
;

-- DROP FUNCTION et_main_uat.get_total_dashboard_by_pengguna(_text, text, numeric, text, text);

CREATE OR REPLACE FUNCTION et_main_uat.get_total_dashboard_by_pengguna(var_urusan_kod_list text[], var_nama_pengguna text DEFAULT NULL::text, var_pejabat_id numeric DEFAULT NULL::numeric, var_modul_kod text DEFAULT NULL::text, var_urusan_mdl_kod text DEFAULT NULL::text)
 RETURNS TABLE(title text, total bigint)
 LANGUAGE plpgsql
AS $function$
BEGIN
  RETURN QUERY
WITH VAR_URUSAN_KOD_LIST AS (
    SELECT UNNEST(var_urusan_kod_list) AS KOD
  ),
VAR_PERANAN_KOD_PENGGUNA AS (
  SELECT DISTINCT PP.NAMA_PENGGUNA, RM.KOD AS PERANAN_KOD
  FROM PCP_CAPAIAN_PENGGUNA CP
  JOIN PCP_PENGGUNA PP ON CP.PENGGUNA_ID = PP.PENGGUNA_ID
  JOIN PCP_PERANAN_MODUL PM ON CP.PERANAN_MODUL_ID = PM.PERANAN_MODUL_ID
  JOIN RJK_SENARAI_AHLI_KUMPULAN RM ON PM.PERANAN_ID = RM.SENARAI_AHLI_KUMPULAN_ID
  WHERE PP.NAMA_PENGGUNA IN (var_nama_pengguna)
),
VAR_DAERAH_PENGGUNA AS (
    SELECT DISTINCT DAERAH_ID
    FROM IND_PEJABAT AS IP
    WHERE PEJABAT_ID IN (var_pejabat_id) 
),
VAR_PEJABAT_TERKAIT AS (
    SELECT DISTINCT PEJABAT_ID
    FROM IND_PEJABAT AS IP
    WHERE DAERAH_ID IN (SELECT DAERAH_ID FROM VAR_DAERAH_PENGGUNA)
),
VAR_FILTER_TUGASAN_KOD_SET AS (
	SELECT UNNEST(ARRAY[ 'PPBKRPJPM', 'PPBKRKPJPM', 'PTB', 'SJR',
    'PJR', 'CTK_JR', 'PMMP6PTB2', 'PPBBPTB2',
    'PPHSYBPTB2', 'PKJR', 'PKJRPP']) as stgsn_kod
),

VAR_PELUPUSAN_TUGASAN_FILTERED AS (
  SELECT ID_TGSN AS ID_TGSN_PELUPUSAN_PENGGUNA_FILTER
  FROM (
    SELECT A.ID_TGSN,
        ROW_NUMBER() OVER (
            PARTITION BY COALESCE(C.kod, E.kod), A.ID_TGSN
            ORDER BY A.ID_TGSN
    ) AS RN
    FROM UMM_TGSN_SEMASA A
    LEFT JOIN UMM_APLIKASI B ON B.APLIKASI_ID = A.APLIKASI_ID
    LEFT JOIN IND_URSN C ON C.URSN_ID = B.URSN_ID
    LEFT JOIN UMM_P_APLIKASI D ON D.APLIKASI_ID = A.APLIKASI_ID
    LEFT JOIN IND_URSN E ON E.URSN_ID = D.URSN_ID
    WHERE A.MODUL = 'PLP'
      AND A.KOD_TGSN = 'FPIKM'
      AND UPPER(A.FLAG_TGSN_SISTEM) = 'N'
  ) A
  WHERE RN = 1
),
VAR_PEJABAT_PERANAN_MAP AS (
  SELECT * FROM (VALUES
    ('TRG', ARRAY['PTG', 'TPTG', 'KPP']),
    ('PRK', ARRAY['PTG', 'KPP']),
    ('SEL', ARRAY['PTG', 'TPTG'])
  ) AS T (KOD_PEJABAT, PERANANS)
),
VAR_PLP_TUGASAN_KOD_SET AS (
    SELECT unnest(ARRAY['PDKM', 'SDKM', 'SDKM2', 'SDKM3', 'PPKM', 'CKM', 'CKMPPLN'])
),
VAR_ALSAN_TUKARGANTI_KOD_SET AS (
    SELECT unnest(ARRAY['KMPP', 'HMSC', 'HMSTP', 'PRBB', 'OPRBB', 'HDHD', 'HMPV', 'HMV', 'HMVB',
            'SSHM', 'SSSC', 'SW', 'SA', 'CRHMB', 'CSHMB', 'BETUL', 'PACT', 'PKH', 'PMKMH', 'PFT', 'REM', 'REMITAN'])
),
VAR_GROUP_BY_NO_FAIL_TUGASAN_KOD_SET AS (
    SELECT unnest(ARRAY['PPBKRPDPJPM', 'PPBKRSDPJPM', 'PPBKRCDPJPM'])
),

VAR_ALSAN_TUKARGANTI_KOD_SET_BATAL AS (
    SELECT unnest(ARRAY['HDHK', 'HPLN','PMKMH','HSSTB','HKSSS'])
),
VAR_NO_HAK_MILIK_BARU AS (
    SELECT 
        mohon.APLIKASI_ID,
        STRING_AGG(mohon.id_hkmlk, '<br>') AS NO_HAKMILIK_BARU
    FROM dft_A_MOHON_HKMLK mohon
    JOIN UMM_APLIKASI appl ON appl.APLIKASI_ID = mohon.APLIKASI_ID
    JOIN IND_URSN urusan ON appl.URSN_ID = urusan.URSN_ID
    JOIN rjk_jns_ursn jenis ON jenis.jns_ursn_id = urusan.jns_ursn_id
    WHERE mohon.id_hkmlk IS NOT NULL
      AND jenis.KOD = 'MH'
    GROUP BY mohon.APLIKASI_ID
),
MAIN_QUERY AS (
	SELECT 
  	DHAS_1.TGSN_SEMASA_ID,
	DHAS_1.TRKH_PNRMAN,
	DHAS_1.MODUL,
	DHAS_1.ID_HKMLK,
	DHAS_1.NO_RESIT,
	DHAS_1.LOCKED_BY,
	DHAS_1.LOCKED_DATE,
	DHAS_1.PERANAN,
	DHAS_1.KOD_TGSN,
	DHAS_1.ID_TGSN,
	DHAS_1.TGSN_PERIHAL,
	DHAS_1.NAMA_PENGGUNA,
	APP_TGSN_1.TRKH_TETAP,
	APP_1.TRKH_PIAGAM,
	APP_1.APLIKASI_ID,
	APP_1.APLIKASI_ID as APP_ID,
	APP_1.RANGKAIAN_ID,
	APP_1.ID_PENGENALAN,
	APP_1.FLAG_INTEGRASI,
	APP_1.STATUS_KEPUTUSAN,
	COALESCE(APP_1.STATUS_PROSES, SNR_1.NAMA) AS STATUS_PROSES,
    COALESCE(URSN_1.KOD, URSN_2.KOD) AS URUSAN_KOD,
    COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI) AS NO_RUJUKAN,
	IPJ_1.NAMA_PENDEK,
	IPJ_1.KOD AS PEJABAT_KOD,
	HNTR_1.ID_PENGHANTARAN,
	DHAS_1.a_tgsn_id as APP_A_TGSN_ID,
	IPJ_1.NAMA_PENDEK as NAMA_PEJABAT_PENDEK,
	TO_CHAR(MLS.TRKH_SIASATAN, 'DD/MM/YYYY') AS TARIKH_SIASATAN_STRING,
	APP_1.ID_RUJUKAN_SMARTBOX,
	DHAS_1.TRKH_KPI AS DHAS_1_TRKH_KPI,
	ITG_1.MINIT_KPI,
	CASE 
      WHEN URSN_1.KOD = 'PSBS' AND DHAS_1.TGSN_PERIHAL = 'Penyediaan Fail Induk Kertas Mesyuarat' THEN FALSE
      ELSE TRUE 
    END AS SHOW_ID_HAKMILIK,
	(
      SELECT STRING_AGG(mohon.id_hkmlk, '<br>')
      FROM dft_A_MOHON_HKMLK mohon
      JOIN UMM_APLIKASI appl ON appl.APLIKASI_ID = mohon.APLIKASI_ID
      JOIN IND_URSN urusan ON appl.URSN_ID = urusan.URSN_ID
      JOIN rjk_jns_ursn jenis ON jenis.jns_ursn_id = urusan.jns_ursn_id
      WHERE mohon.APLIKASI_ID = DHAS_1.APLIKASI_ID
        AND mohon.id_hkmlk IS NOT NULL
        AND jenis.KOD = CAST('MH' AS VARCHAR)
    ) AS NO_HAKMILIK_BARU,
	
	CASE 
		WHEN DHAS_1.TRKH_KPI IS NULL 
		     AND ITG_1.MINIT_KPI IS NOT NULL 
		     AND DHAS_1.TRKH_PNRMAN IS NOT NULL
		THEN DHAS_1.TRKH_PNRMAN + (ITG_1.MINIT_KPI || ' minutes')::INTERVAL
		ELSE DHAS_1.TRKH_KPI
	END AS TRKH_KPI,
	CASE 
		WHEN APP_TGSN_1.STATUS_TUGASAN IS NULL 
			OR DHAS_1.TGSN_PERIHAL = 'Pengagihan Tugasan Baru' 
		THEN 'Baru'
		ELSE APP_TGSN_1.STATUS_TUGASAN
	END AS STATUS_TUGASAN,

	CASE 
		WHEN ITG_1.MINIT_KPI IS NOT NULL THEN TRUE
		ELSE FALSE
	END AS SHOW_KPI,
	CASE 
    WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
         AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
              OR DHAS_1.KOD_TGSN LIKE '%PTB%')
    THEN '-' 
    ELSE TO_CHAR(DHAS_1.TRKH_PNRMAN, 'DD/MM/YYYY')
	END AS TARIKH_PENERIMAAN_STRING,

	CASE 
	
		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
			AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
				OR DHAS_1.KOD_TGSN LIKE '%PTB%')
		THEN '-' 

		ELSE TO_CHAR(
			CASE
			WHEN ITG_1.MINIT_KPI IS NOT NULL 
				AND DHAS_1.TRKH_PNRMAN IS NOT NULL 
				AND DHAS_1.TRKH_KPI IS NULL
			THEN DHAS_1.TRKH_PNRMAN + (ITG_1.MINIT_KPI || ' minutes')::INTERVAL
			ELSE DHAS_1.TRKH_KPI
			END,
			'DD/MM/YYYY'
		)
	END AS TARIKH_DAN_MASA_LUPUT_STRING,
CASE
  WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL
       AND (
         DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
         OR DHAS_1.KOD_TGSN LIKE '%PTB%'
       )
  THEN NULL
  ELSE
    CASE
      WHEN ITG_1.MINIT_KPI IS NOT NULL
           AND DHAS_1.TRKH_PNRMAN IS NOT NULL
           AND DHAS_1.TRKH_KPI IS NULL
      THEN DHAS_1.TRKH_PNRMAN + (ITG_1.MINIT_KPI || ' minutes')::INTERVAL
      ELSE DHAS_1.TRKH_KPI
    END
END AS TARIKH_DAN_MASA_LUPUT,

	CASE 
		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
			AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
				OR DHAS_1.KOD_TGSN LIKE '%PTB%')
		THEN '-' 
		ELSE TO_CHAR(APP_1.TRKH_PIAGAM, 'DD/MM/YYYY')
	END AS TARIKH_PIAGAM_STRING,
	CASE 
		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
			AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
				OR DHAS_1.KOD_TGSN LIKE '%PTB%')
		THEN '-' 
		ELSE TO_CHAR(APP_TGSN_1.TRKH_TETAP, 'DD/MM/YYYY')
	END AS TARIKH_MULA_STRING,
	CASE 
		WHEN TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
			AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
				OR DHAS_1.KOD_TGSN LIKE '%PTB%')
		THEN TRUE 
		ELSE FALSE 
	END AS IS_FILTER_TUGASAN,
	CASE
		WHEN ITG_1.MINIT_KPI IS NOT NULL 
			AND DHAS_1.TRKH_PNRMAN IS NOT NULL 
			AND DHAS_1.TRKH_KPI IS NULL
		THEN DHAS_1.TRKH_PNRMAN + (ITG_1.MINIT_KPI || ' minutes')::INTERVAL
		ELSE DHAS_1.TRKH_KPI
	END AS TARIKH_KPI,
	

	CASE 
	  WHEN NOT (
	    TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
	    AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
	         OR DHAS_1.KOD_TGSN LIKE '%PTB%')
	  )
	  THEN 
	    CASE 
	      WHEN COALESCE(NULLIF(TRIM(DHAS_1.ID_HKMLK), ''), '-') = '-' THEN '-'
	      ELSE (
	        SELECT 
	          CASE 
	            WHEN COUNT(*) > 10 
	            THEN (
	              SELECT string_agg(val, ', ') || '...'
	              FROM (
	                SELECT DISTINCT val
	                FROM unnest(string_to_array(DHAS_1.ID_HKMLK, ',')) AS val
	                ORDER BY val
	                LIMIT 10
	              ) sub
	            )
	            ELSE (
	              SELECT string_agg(DISTINCT val, ', ' ORDER BY val)
	              FROM unnest(string_to_array(DHAS_1.ID_HKMLK, ',')) AS val
	            )
	          END
	      )
	    END
	  ELSE COALESCE(NULLIF(TRIM(DHAS_1.ID_HKMLK), ''), '-') 
	END AS NO_HAKMILIK_DASHBOARD,
	CASE 
	  WHEN NOT (
	    TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
	    AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
	         OR DHAS_1.KOD_TGSN LIKE '%PTB%')
	  )
	  THEN COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
	  ELSE NULL
	END AS APLIKASI_NO_PERMOHONAN,
	
	
	CASE 
	  WHEN NOT (
	    TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
	    AND (DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
	         OR DHAS_1.KOD_TGSN LIKE '%PTB%')
	  )
		  THEN 
		    CASE 
		      WHEN COALESCE(NULLIF(TRIM(DHAS_1.NO_RESIT), ''), '-') = '-' THEN '-'
		      ELSE (
		        SELECT 
		          CASE 
		            WHEN COUNT(*) > 10 
		            THEN (
		              SELECT string_agg(val, ', ') || '...'
		              FROM (
		                SELECT DISTINCT val
		                FROM unnest(string_to_array(DHAS_1.NO_RESIT, ',')) AS val
		                ORDER BY val
		                LIMIT 10
		              ) sub
		            )
		            ELSE (
		              SELECT string_agg(DISTINCT val, ', ' ORDER BY val)
		              FROM unnest(string_to_array(DHAS_1.NO_RESIT, ',')) AS val
		            )
		          END
		      )
		    END
		  ELSE COALESCE(NULLIF(TRIM(DHAS_1.NO_RESIT), ''), '-') 
		END AS NO_RESIT_DASHBOARD,
		
		
		CASE
		  WHEN NOT (
		    TRIM(DHAS_1.KOD_TGSN) IS NOT NULL 
		    AND (
		      DHAS_1.KOD_TGSN IN (SELECT * FROM VAR_FILTER_TUGASAN_KOD_SET)
		      OR DHAS_1.KOD_TGSN LIKE '%PTB%'
		    )
		  )
		  THEN
		    CASE 
		      WHEN HNTR_1.ID_PENGHANTARAN IS NOT NULL AND HNTR_1.ID_PENGHANTARAN LIKE 'PNL/%'
		        THEN 'UPNL'
		      ELSE COALESCE(URSN_1.KOD, URSN_2.KOD)
		    END
		  ELSE
		    COALESCE(URSN_1.KOD, URSN_2.KOD)
		END AS URUSAN_KOD_DASHBOARD,

		CASE
		  WHEN UPPER(APP_1.FLAG_INTEGRASI) ='Y' THEN
		    CASE
		      WHEN COALESCE(COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI), '') LIKE '%MF%' 
		           AND COALESCE(COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI), '') LIKE '%(%' THEN
		        SPLIT_PART(COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI), '(', 1)
		        
		      WHEN COALESCE(APP_1.URSN_ID, URSN_2.URSN_ID) IS NOT NULL 
		           AND COALESCE(URSN_1.KOD, URSN_2.KOD) = 'KVSP' THEN
		        (
		          SELECT hubungan2.ID_PENGENALAN || ' / ' || COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
		          FROM UMM_APLIKASI hubungan1
		          JOIN UMM_APLIKASI hubungan2 ON hubungan1.ID_PENGENALAN = hubungan2.APLIKASI_ID
		          WHERE hubungan1.APLIKASI_ID = APP_1.APLIKASI_ID
		          LIMIT 1
		        )
		        
		      ELSE
		        (
		          SELECT hubungan.no_rujukan_fail || ' / ' || COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
		          FROM UMM_APLIKASI hubungan
		          WHERE hubungan.APLIKASI_ID = APP_1.APLIKASI_ID
		          LIMIT 1
		        )
		    END
		  WHEN DHAS_1.KOD_TGSN  = 'STRSPRAP' THEN
		    APP_A_1.ID_TRANSAKSI

		   WHEN COALESCE(URSN_1.KOD, URSN_2.KOD) IN ('HDHK', 'HDHD', 'KVSPM')
    AND NOT (
      DHAS_1.MODUL = 'PNT'
      AND HNTR_1.ID_PENGHANTARAN LIKE 'PNL/%'
      AND APP_1.MKLMT_TMBHN IS NOT NULL
      AND APP_1.MKLMT_TMBHN::jsonb ->> 'idPengenalanInduk' IS NOT NULL
    )
  THEN
    COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI) || 
    ' ' || (
      SELECT ID_PENGENALAN 
      FROM UMM_APLIKASI 
      WHERE NO_RUJUKAN_FAIL = COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
      LIMIT 1
    )

  WHEN DHAS_1.MODUL = 'PNT'
    AND HNTR_1.ID_PENGHANTARAN LIKE 'PNL/%'
    AND APP_1.MKLMT_TMBHN IS NOT NULL
    AND APP_1.MKLMT_TMBHN::jsonb ->> 'idPengenalanInduk' IS NOT NULL
  THEN
    APP_1.MKLMT_TMBHN::jsonb ->> 'idPengenalanInduk'

		  ELSE
		    COALESCE(APP_1.ID_PENGENALAN, APP_A_1.ID_TRANSAKSI)
		END AS ID_PERMOHONAN_DASHBOARD,
	
		  CASE
		    WHEN DHAS_1.kod_tgsn IN ('PPF', 'PPJUB', 'PPPK', 'PPSYT') THEN org_nama.nama
		    WHEN URSN_1.kod = 'PPLBL' THEN pelelong_nama.nama_pemohon
		    ELSE bkptg_nama.nama
		  END AS NAMA_PEMOHON,
		  COALESCE(KS.NO_KERTAS_SIASATAN, APP_1.NO_RUJUKAN_FAIL, '') as NO_FAIL_PEMOHON
	



FROM UMM_TGSN_SEMASA DHAS_1

LEFT JOIN UMM_APLIKASI APP_1 ON DHAS_1.APLIKASI_ID = APP_1.APLIKASI_ID
LEFT JOIN UMM_APLIKASI APP_2 ON DHAS_1.APLIKASI_ID = APP_2.APLIKASI_ID
LEFT JOIN IND_URSN URSN_1 ON APP_2.URSN_ID = URSN_1.URSN_ID

LEFT JOIN UMM_APLIKASI APP_3 ON DHAS_1.APLIKASI_ID = APP_3.APLIKASI_ID
LEFT JOIN UMM_APLIKASI APP_4 ON APP_3.HUBUNGAN_APLIKASI_ID = APP_4.APLIKASI_ID

LEFT JOIN UMM_P_APLIKASI APP_A_1 ON DHAS_1.P_APLIKASI_ID = APP_A_1.P_APLIKASI_ID
LEFT JOIN UMM_P_APLIKASI APP_A_2 ON DHAS_1.P_APLIKASI_ID = APP_A_2.P_APLIKASI_ID
LEFT JOIN IND_URSN URSN_2 ON APP_A_2.URSN_ID = URSN_2.URSN_ID
LEFT JOIN UMM_P_APLIKASI APP_A_3 ON DHAS_1.P_APLIKASI_ID = APP_A_3.P_APLIKASI_ID

LEFT JOIN RJK_SENARAI_AHLI_KUMPULAN SNR_1 ON APP_A_3.STATUS_ID = SNR_1.SENARAI_AHLI_KUMPULAN_ID

LEFT JOIN UMM_A_TGSN APP_TGSN_1 ON DHAS_1.A_TGSN_ID = APP_TGSN_1.A_TGSN_ID
LEFT JOIN UMM_A_TGSN APP_TGSN_2 ON DHAS_1.A_TGSN_ID = APP_TGSN_2.A_TGSN_ID
LEFT JOIN IND_TGSN ITG_1 ON APP_TGSN_2.TGSN_ID = ITG_1.TGSN_ID

LEFT JOIN UMM_A_TGSN APP_A_4 ON DHAS_1.A_TGSN_ID = APP_A_4.A_TGSN_ID
LEFT JOIN PCP_PENGGUNA PGN_1 ON APP_A_4.PENGGUNA_SEMASA_ID = PGN_1.PENGGUNA_ID

LEFT JOIN UMM_MKLMT_LAPORAN_SIASATAN MLS ON DHAS_1.MKLMT_LAPORAN_SIASATAN_ID = MLS.MKLMT_LAPORAN_SIASATAN_ID

LEFT JOIN IND_PEJABAT IPJ_1 ON DHAS_1.PEJABAT_ID = IPJ_1.PEJABAT_ID
LEFT JOIN UMM_HANTARAN_NOTIS HNTR_1 ON DHAS_1.HANTARAN_NOTIS_ID = HNTR_1.HANTARAN_NOTIS_ID
LEFT JOIN PKS_A_KERTAS_SIASATAN KS ON DHAS_1.A_KERTAS_SIASATAN_ID = KS.A_KERTAS_SIASATAN_ID




LEFT JOIN LATERAL (
	  SELECT o.nama
	  FROM umm_p_daftar_organisasi o
	  WHERE o.p_daftar_organisasi_id IN (
	    SELECT MIN(o2.p_daftar_organisasi_id)
	    FROM umm_p_daftar_organisasi o2
	    WHERE APP_A_1.id_transaksi = APP_1.id_pengenalan
	  )
	  LIMIT 1
	) AS org_nama ON DHAS_1.kod_tgsn IN ('PPF', 'PPJUB', 'PPPK', 'PPSYT')
	
	-- Join nama pelelong jika kod urusan 'PPLBL'
	LEFT JOIN LATERAL (
	  SELECT p.nama_pemohon
	  FROM llg_a_daftar_pelelong p
	  WHERE p.aplikasi_id = DHAS_1.aplikasi_id
	  ORDER BY p.a_daftar_pelelong_id ASC
	  LIMIT 1
	) AS pelelong_nama ON URSN_1.kod = 'PPLBL'
	
	-- Join nama pihak berkepentingan
	LEFT JOIN LATERAL (
	  SELECT r.nama
	  FROM umm_a_pihak_bkptg r
	  WHERE r.aplikasi_id = DHAS_1.aplikasi_id
	    AND UPPER(r.flag_pemohon) = 'Y'
	  ORDER BY r.a_pihak_bkptg_id ASC
	  LIMIT 1
	) AS bkptg_nama ON TRUE
  	
	WHERE UPPER(DHAS_1.FLAG_TGSN_SISTEM) = 'N'
	AND (DHAS_1.NAMA_PENGGUNA = var_nama_pengguna OR DHAS_1.NAMA_PENGGUNA IS NULL)
	AND (EXISTS (
        SELECT 1 FROM VAR_PERANAN_KOD_PENGGUNA PKP
        WHERE PKP.NAMA_PENGGUNA = DHAS_1.NAMA_PENGGUNA AND PKP.peranan_kod = 'PTG'
    	) OR DHAS_1.PEJABAT_ID IN (SELECT PEJABAT_ID FROM VAR_PEJABAT_TERKAIT) OR DHAS_1.PEJABAT_ID IS NULL
	)

	AND (
		URSN_1.KOD IN (SELECT KOD FROM VAR_URUSAN_KOD_LIST)
		OR URSN_2.KOD IN (SELECT KOD FROM VAR_URUSAN_KOD_LIST)
	)

	AND EXISTS ( 
		SELECT 1
		FROM VAR_PERANAN_KOD_PENGGUNA PKP
		WHERE DHAS_1.PERANAN LIKE '%-' || PKP.PERANAN_KOD || '-%'
	)
	AND (APP_TGSN_1.A_TGSN_ID is null or APP_TGSN_1.A_TGSN_ID is not null )
	--IF 
		AND (
		    var_modul_kod IS NULL 
		    OR DHAS_1.modul = var_modul_kod
		)
		
		AND (
		    var_urusan_mdl_kod IS NULL
		    OR (
		        var_modul_kod IS DISTINCT FROM 'DFT'
		        AND COALESCE(URSN_1.KOD, URSN_2.KOD) = var_urusan_mdl_kod
		    )
		)
	-- END 
	),

VAR_GROUPED_TUGAS AS (
    SELECT
        mq.*,
        ROW_NUMBER() OVER (PARTITION BY ua.no_fail, mq.kod_tgsn ORDER BY mq.tgsn_semasa_id) AS rn
    FROM MAIN_QUERY mq
    LEFT JOIN umm_aplikasi ua ON mq.aplikasi_id = ua.aplikasi_id
    WHERE mq.kod_tgsn IN ('PPBKRPDPJPM', 'PPBKRSDPJPM', 'PPBKRCDPJPM') 
),
VAR_MODUL_PENGGUNA AS (
  SELECT DISTINCT p.nama_pengguna, m.kod AS modul_kod
  FROM pcp_capaian_pengguna cp
  JOIN pcp_pengguna p ON cp.pengguna_id = p.pengguna_id
  JOIN pcp_peranan_modul pm ON cp.peranan_modul_id = pm.peranan_modul_id
  JOIN ind_modul m ON pm.modul_id = m.modul_id
  WHERE p.nama_pengguna IN (var_nama_pengguna) 
    AND m.kod IN ('PNT', 'UAM')
),

VAR_BELUM_TUKAR_GANTI AS (
 SELECT unnest(ARRAY['HMSC', 'HMSTP', 'PRBB', 'OPRBB', 'HDHD', 'HMPV', 'HMV','HMVB','SSHM','SSSC','SW','SA','CRHMB','CSHMB','BETUL','PACT','PKH','PMKMH','PFT','REM','REMITAN'])
),
FINAL_QUERY_V1 AS (
	SELECT * FROM MAIN_QUERY AS DEFAULT_MAIN_PNT
	WHERE EXISTS (
	    SELECT 1
	    FROM VAR_MODUL_PENGGUNA mp
	    WHERE mp.nama_pengguna = DEFAULT_MAIN_PNT.nama_pengguna
	      OR DEFAULT_MAIN_PNT.modul IN ('PNT', 'UAM')
	  )
	AND DEFAULT_MAIN_PNT.kod_tgsn NOT IN ('KD', 'STRKD')
		AND NOT (
		  DEFAULT_MAIN_PNT.modul = 'CON'
		  AND DEFAULT_MAIN_PNT.kod_tgsn IN ('CSK', 'JSK')
		)
	UNION ALL
	SELECT * FROM MAIN_QUERY AS DEFAULT_MAIN
	WHERE DEFAULT_MAIN.KOD_TGSN NOT IN ('KD', 'STRKD')
	AND NOT (
	    DEFAULT_MAIN.MODUL = 'CON' AND 
	    (DEFAULT_MAIN.KOD_TGSN = 'CSK' OR DEFAULT_MAIN.KOD_TGSN = 'JSK')
	)
	AND DEFAULT_MAIN.MODUL NOT IN ('PNT', 'UAM')
	AND NOT (
	    DEFAULT_MAIN.kod_tgsn IN ('KD', 'STRKD')
	    OR (DEFAULT_MAIN.NAMA_PENGGUNA IS NOT NULL AND DEFAULT_MAIN.NAMA_PENGGUNA <> var_nama_pengguna)
	)
	AND NOT (
	    DEFAULT_MAIN.KOD_TGSN = 'PTBUT'
	    AND DEFAULT_MAIN.URUSAN_KOD IN ('PMQFT', 'PMQTFT')
	)

),

FIANL_QUERY_MERGE as (
	select * FROM FINAL_QUERY_V1 as FN_Q1
	WHERE NOT EXISTS (
		SELECT 1
   		FROM VAR_FILTER_TUGASAN_KOD_SET 
		 WHERE
	      (
	        stgsn_kod = 'PTB'
	        AND FN_Q1.KOD_TGSN LIKE '%' || stgsn_kod || '%'
	      )
			OR (
		    stgsn_kod <> 'PTB'
			  AND FN_Q1.KOD_TGSN = stgsn_kod
			)
	)

 	UNION ALL
	SELECT * from (

		SELECT DISTINCT ON (FN_Q1_v2.KOD_TGSN) FN_Q1_v2.*
		FROM FINAL_QUERY_V1 as FN_Q1_v2
		WHERE EXISTS (
			 SELECT 1
      		FROM VAR_FILTER_TUGASAN_KOD_SET
			where (
					UPPER(FN_Q1_v2.STATUS_PROSES) <> 'GANTUNG'

					AND (
			          (stgsn_kod = 'PTB' AND FN_Q1_v2.KOD_TGSN LIKE '%' || stgsn_kod || '%')
			          OR (stgsn_kod = 'SJR' AND FN_Q1_v2.KOD_TGSN LIKE '%' || stgsn_kod || '%')
			          OR (stgsn_kod = 'CTK_JR' AND FN_Q1_v2.KOD_TGSN LIKE '%' || stgsn_kod || '%')
			          OR (stgsn_kod = 'PJR' AND FN_Q1_v2.KOD_TGSN LIKE '%' || stgsn_kod || '%')
			          OR (
			            stgsn_kod NOT IN ('PTB', 'SJR', 'CTK_JR', 'PJR')
			            AND FN_Q1_v2.KOD_TGSN = stgsn_kod
			          )
			        )
			) order by FN_Q1_v2.KOD_TGSN, FN_Q1_v2.tgsn_semasa_id desc
		) limit 1 
	)

),
VAR_USER_PERANAN AS (
  SELECT LOWER(mdl.kod) AS modul, LOWER(sak.kod) AS peranan
  FROM pcp_capaian_pengguna cp
  JOIN pcp_pengguna pg ON cp.pengguna_id = pg.pengguna_id
  JOIN pcp_peranan_modul pm ON cp.peranan_modul_id = pm.peranan_modul_id
  JOIN ind_modul mdl ON pm.modul_id = mdl.modul_id
  JOIN rjk_senarai_ahli_kumpulan sak ON pm.peranan_id = sak.senarai_ahli_kumpulan_id
  WHERE pg.nama_pengguna = var_nama_pengguna
),
FINAL_QUERY AS (
  SELECT * 
  FROM FIANL_QUERY_MERGE AS DEFAULT_MAIN
  WHERE 1=1


 AND (
    -- Ambil jika bukan PTB dan nama_pengguna tidak kosong
    (
      DEFAULT_MAIN.kod_tgsn NOT ILIKE '%PTB%'
      AND COALESCE(TRIM(DEFAULT_MAIN.nama_pengguna), '') <> ''
    )
    -- Atau: jika PTB / nama kosong, validasi modul dan peranan terhadap VAR_USER_PERANAN
    OR EXISTS (
      SELECT 1
      FROM VAR_USER_PERANAN u
      WHERE LOWER(u.modul) = LOWER(DEFAULT_MAIN.modul)
        AND EXISTS (
          SELECT 1
          FROM unnest(string_to_array(LOWER(DEFAULT_MAIN.peranan), '-')) AS p(peranan)
          WHERE p.peranan = u.peranan
        )
        AND (
          DEFAULT_MAIN.kod_tgsn ILIKE '%PTB%'
          OR COALESCE(TRIM(DEFAULT_MAIN.nama_pengguna), '') = ''
        )
    )
  
    )
    AND NOT (
      DEFAULT_MAIN.id_rujukan_smartbox IS NOT NULL
      AND DEFAULT_MAIN.id_rujukan_smartbox <> ''
      AND DEFAULT_MAIN.kod_tgsn IN ('ISHSB', 'KDSB')
    )
),

URUSAN_MODUL_PARENT_CTE AS (
  SELECT 
    A.APLIKASI_ID as APP_ID_CTE,
    M.KOD AS URUSAN_MODUL_PARENT
  FROM UMM_APLIKASI A
  LEFT JOIN IND_URSN U ON A.URSN_ID = U.URSN_ID
  LEFT JOIN IND_MODUL M ON U.MODUL_ID = M.MODUL_ID
),

FINAL_RESULT AS (
	SELECT * ,
	CASE 
	  WHEN EXISTS (
	    SELECT 1
	    FROM UMM_PERTANYAAN p
	    JOIN RJK_SENARAI_AHLI_KUMPULAN k ON p.STATUS_ID = k.SENARAI_AHLI_KUMPULAN_ID
	    JOIN UMM_APLIKASI a ON p.APLIKASI_ID = a.APLIKASI_ID
	    JOIN IND_URSN u ON a.URSN_ID = u.URSN_ID
	    WHERE p.A_TGSN_ID = FQ.APP_A_TGSN_ID
	      AND k.KOD != 'SELESAI'
	      AND u.TEMPOH_KUIRI ~ '^[0-9]+$'
	      AND DATE_PART('day', CURRENT_DATE - p.CREATED_DATE) > u.TEMPOH_KUIRI::INT
	  )
	  THEN ' (Pertanyaan) - Telah Melebihi Tempoh Kuiri'
	
	  WHEN EXISTS (
	    SELECT 1
	    FROM UMM_PERTANYAAN p
	    JOIN RJK_SENARAI_AHLI_KUMPULAN k ON p.STATUS_ID = k.SENARAI_AHLI_KUMPULAN_ID
	    WHERE p.A_TGSN_ID = FQ.APP_A_TGSN_ID
	      AND k.KOD != 'SELESAI'
	  )
	  THEN ' (Pertanyaan)'
	
	  ELSE NULL
	END AS pertanyaan_keterangan,


	--	color and flag
	CASE 
	    WHEN (
	        CASE
	            WHEN FQ.MINIT_KPI IS NOT NULL 
	                 AND FQ.TRKH_PNRMAN IS NOT NULL 
	                 AND FQ.DHAS_1_TRKH_KPI IS NULL
	            THEN FQ.TRKH_PNRMAN + (FQ.MINIT_KPI || ' minutes')::INTERVAL
	            ELSE FQ.DHAS_1_TRKH_KPI
	        END
	    ) IS NOT NULL 
	    AND (
	        CASE
	            WHEN FQ.MINIT_KPI IS NOT NULL 
	                 AND FQ.TRKH_PNRMAN IS NOT NULL 
	                 AND FQ.DHAS_1_TRKH_KPI IS NULL
	            THEN FQ.TRKH_PNRMAN + (FQ.MINIT_KPI || ' minutes')::INTERVAL
	            ELSE FQ.DHAS_1_TRKH_KPI
	        END
	    ) < CURRENT_DATE
	THEN 'TUNGGAK'
	ELSE NULL
	END AS STATUS,
	CASE 
	    WHEN (
	        CASE
	            WHEN FQ.MINIT_KPI IS NOT NULL 
	                 AND FQ.TRKH_PNRMAN IS NOT NULL 
	                 AND FQ.TRKH_KPI IS NULL
	            THEN FQ.TRKH_PNRMAN + (FQ.MINIT_KPI || ' minutes')::INTERVAL
	            ELSE FQ.DHAS_1_TRKH_KPI
	        END
	    ) IS NOT NULL 
	    AND (
	        CASE
	            WHEN FQ.MINIT_KPI IS NOT NULL 
	                 AND FQ.TRKH_PNRMAN IS NOT NULL 
	                 AND FQ.TRKH_KPI IS NULL
	            THEN FQ.TRKH_PNRMAN + (FQ.MINIT_KPI || ' minutes')::INTERVAL
	            ELSE FQ.DHAS_1_TRKH_KPI
	        END
	    ) < CURRENT_DATE
	THEN 'red' -- warna merah sebagai contoh
	ELSE NULL
	END AS COLOR,


	CASE
	    WHEN NOT FQ.SHOW_KPI THEN 'Hijau'
	    WHEN FQ.TARIKH_DAN_MASA_LUPUT_STRING IS NULL OR FQ.TARIKH_DAN_MASA_LUPUT_STRING = '-' THEN 'Hijau'
	    WHEN FQ.TRKH_TETAP IS NULL THEN
	        CASE
	            WHEN TO_DATE(FQ.TARIKH_DAN_MASA_LUPUT_STRING, 'DD/MM/YYYY') >= CURRENT_DATE THEN 'Hijau'
	            ELSE 'Merah'
	        END
	    WHEN TO_DATE(FQ.TARIKH_DAN_MASA_LUPUT_STRING, 'DD/MM/YYYY') <= FQ.TRKH_TETAP::DATE THEN 'Hijau'
	    ELSE 'Merah'
	END AS FLAG_STATUS,

	--end color and flag

CASE
  WHEN FQ.KOD_TGSN = 'ISH' THEN TRUE
  WHEN FQ.MODUL = 'KKS' THEN TRUE
  WHEN FQ.MODUL = 'PNT' AND URUSAN_MODUL_PARENT = 'KKS' THEN TRUE
  WHEN EXISTS (
    SELECT 1
    FROM UNNEST(STRING_TO_ARRAY(FQ.URUSAN_KOD_DASHBOARD, '<BR />')) AS URSN
    WHERE URSN IN (SELECT * FROM VAR_BELUM_TUKAR_GANTI)
  ) THEN TRUE
  WHEN EXISTS (
    SELECT 1
    FROM UNNEST(STRING_TO_ARRAY(FQ.URUSAN_KOD_DASHBOARD, '<BR />')) AS URSN
    WHERE URSN IS NOT NULL
      AND (
        URSN NOT IN (SELECT * FROM VAR_BELUM_TUKAR_GANTI)
        OR URSN IN (SELECT * FROM VAR_ALSAN_TUKARGANTI_KOD_SET_BATAL)
      )
or (
    (
      SELECT COUNT(*) FROM DFT_A_MOHON_HKMLK HM
      JOIN IND_MKLMT_HKMLK MH ON MH.mklmt_hkmlk_id = HM.ID_HKMLK
      JOIN rjk_senarai_ahli_kumpulan o ON o.senarai_ahli_kumpulan_id = MH.status_hkmlk_id
      WHERE HM.APLIKASI_ID = FQ.APLIKASI_ID AND o.kod = 'STAHMBT'
    ) = (
      SELECT COUNT(*) FROM DFT_A_MOHON_HKMLK HM
      WHERE HM.APLIKASI_ID = FQ.APLIKASI_ID
    )
    or NOT EXISTS (
      SELECT 1
      FROM DFT_A_MOHON_HKMLK HM
      JOIN IND_MKLMT_HKMLK MH ON MH.mklmt_hkmlk_id = HM.ID_HKMLK
      JOIN RJK_SENARAI_AHLI_KUMPULAN o ON o.senarai_ahli_kumpulan_id = MH.status_hkmlk_id
      WHERE HM.APLIKASI_ID = FQ.APLIKASI_ID
      AND o.kod = 'STAHDFT'
      AND EXISTS (
        SELECT 1 FROM IND_VERSI_DHD TG WHERE TG.hkmlk_id = HM.ID_HKMLK
      )
    )
  )
  )
  
  THEN TRUE
  ELSE FALSE
END AS IS_HAKMILIK_BELUM_TUKARGANTI,



CASE 
  WHEN FQ.TARIKH_DAN_MASA_LUPUT IS NULL THEN '-' 

  WHEN FQ.TARIKH_DAN_MASA_LUPUT <= NOW() THEN '0 Hari'

  WHEN DATE_PART('month', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 THEN
    TRIM(BOTH FROM CONCAT_WS(' ',
      CASE 
        WHEN DATE_PART('month', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('month', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Bulan' 
      END,
      CASE 
        WHEN DATE_PART('day', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('day', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Hari' 
      END,
      CASE 
        WHEN DATE_PART('hour', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('hour', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Jam' 
      END,
      CASE 
        WHEN DATE_PART('minute', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('minute', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Minit' 
      END
    ))

  ELSE
    TRIM(BOTH FROM CONCAT_WS(' ',
      CASE 
        WHEN DATE_PART('day', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('day', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Hari' 
      END,
      CASE 
        WHEN DATE_PART('hour', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('hour', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Jam' 
      END,
      CASE 
        WHEN DATE_PART('minute', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW())) > 0 
          THEN FLOOR(DATE_PART('minute', age(FQ.TARIKH_DAN_MASA_LUPUT, NOW()))) || ' Minit' 
      END
    ))
END AS BAKI_MASA





	
FROM FINAL_QUERY AS FQ 
LEFT JOIN URUSAN_MODUL_PARENT_CTE UMP ON UMP.APP_ID_CTE = FQ.APP_ID
where UPPER(FQ.STATUS_TUGASAN) <> 'SELESAI'
--	WHERE 1=1
--	AND NOT (
--		FQ.MODUL = 'PFIKM'   
--		OR FQ.ID_TGSN IN (SELECT ID_TGSN_PELUPUSAN_PENGGUNA_FILTER FROM VAR_PELUPUSAN_TUGASAN_FILTERED)	
--  	)
--AND NOT (FQ.modul = 'UAM' AND FQ.URUSAN_KOD = 'BIO')


),



RANGKAIAN_MERGERED AS (
    SELECT 
    MAX(fd.TGSN_SEMASA_ID)::BIGINT AS ID,
    MAX(fd.TRKH_PNRMAN) AS TRKH_PEN,
    MAX(fd.TARIKH_PENERIMAAN_STRING) AS TARIKH_PENERIMAAN_STRING,
    MAX(fd.TARIKH_DAN_MASA_LUPUT_STRING) AS TARIKH_DAN_MASA_LUPUT_STRING,
    STRING_AGG(fd.ID_HKMLK, '<br />') AS no_hakmilik,
    ra.RANGKAIAN_ID::TEXT AS rangkaian_id_merged,
    fd.kod_tgsn::TEXT,
    STRING_AGG(fd.ID_PERMOHONAN_DASHBOARD ::TEXT, '<br />') AS id_permohonan,
    STRING_AGG(fd.URUSAN_KOD_DASHBOARD ::TEXT, '<br />') AS urusan,
    MAX(fd.NO_FAIL_PEMOHON) AS NO_FAIL_PEMOHON,
    STRING_AGG(fd.NO_RESIT_DASHBOARD :: TEXT, '<br />') AS no_resit,
	MAX(fd.TGSN_PERIHAL) as tugas,
    MAX(fd.NAMA_PEMOHON) AS NAMA_PEMOHON,
    MAX(fd.NAMA_PEJABAT_PENDEK) AS PEJABAT,
    MAX(fd.ID_PENGHANTARAN) AS ID_PENYAMPAIAN,
	MAX(fd.APP_A_TGSN_ID ) as id_APP_A_TGSN,
	MAX(fd.APLIKASI_ID),
	MAX(fd.pertanyaan_keterangan) AS pertanyaan_keterangan,
	MAX(fd.TARIKH_SIASATAN_STRING) as TARIKH_SIASATAN_STRING,
	MAX(fd.STATUS) as ROW_STATUS,
	MAX(fd.COLOR) as ROW_COLOR,
	MAX(fd.FLAG_STATUS) as FLAG_STATUS,
	(MAX(CASE WHEN fd.IS_HAKMILIK_BELUM_TUKARGANTI THEN 1 ELSE 0 END) = 1),
	MAX(fd.BAKI_MASA) as BAKI_MASA,
	MAX(fd.NO_HAKMILIK_BARU) as NO_HAKMILIK_BARU,
MAX(fd.MODUL) as MODUL

    FROM FINAL_RESULT fd
    JOIN UMM_APLIKASI ra ON fd.APLIKASI_ID = ra.APLIKASI_ID
    WHERE ra.RANGKAIAN_ID IS NOT NULL AND fd.kod_tgsn <> 'IMH'
    GROUP BY ra.RANGKAIAN_ID, fd.kod_tgsn
  ),

  REMAINING_ROW AS (
    SELECT 
    fd.TGSN_SEMASA_ID::BIGINT AS ID,
    fd.TRKH_PNRMAN AS TRKH_PEN,
    fd.TARIKH_PENERIMAAN_STRING,
    fd.TARIKH_DAN_MASA_LUPUT_STRING,
    fd.ID_HKMLK AS no_hakmilik,
      NULL::TEXT AS rangkaian_id_merged,
    fd.kod_tgsn::TEXT,
    fd.ID_PERMOHONAN_DASHBOARD AS id_permohonan,
    fd.URUSAN_KOD_DASHBOARD AS urusan,
    fd.NO_FAIL_PEMOHON AS NO_FAIL_PEMOHON,
    fd.NO_RESIT_DASHBOARD AS no_resit,
	fd.TGSN_PERIHAL as tugas,
    fd.NAMA_PEMOHON AS NAMA_PEMOHON,
    fd.NAMA_PEJABAT_PENDEK AS PEJABAT,
    fd.ID_PENGHANTARAN AS ID_PENYAMPAIAN,
	fd.APP_A_TGSN_ID as id_APP_A_TGSN,
	fd.APLIKASI_ID,
	fd.pertanyaan_keterangan,
	fd.TARIKH_SIASATAN_STRING as TARIKH_SIASATAN_STRING,
	fd.STATUS as ROW_STATUS,
	fd.COLOR as ROW_COLOR,
	fd.FLAG_STATUS as FLAG_STATUS, 
	fd.IS_HAKMILIK_BELUM_TUKARGANTI,
	fd.BAKI_MASA as BAKI_MASA, 
	fd.NO_HAKMILIK_BARU as NO_HAKMILIK_BARU,
fd.MODUL as MODUL
    FROM FINAL_RESULT fd
    LEFT JOIN UMM_APLIKASI ra ON fd.APLIKASI_ID = ra.APLIKASI_ID
--    testing
--	WHERE ra.RANGKAIAN_ID IS NULL OR fd.kod_tgsn = 'IMH'
  ),

--  FINAL_V2 AS (
--    SELECT * FROM RANGKAIAN_MERGERED
--    UNION ALL
--    SELECT * FROM REMAINING_ROW
--  ),

FINAL_V2 AS (
  SELECT DISTINCT ON (merged.id) merged.*
  FROM (
    SELECT * FROM RANGKAIAN_MERGERED
    UNION ALL
    SELECT * FROM REMAINING_ROW
  ) merged
  ORDER BY merged.id, merged.trkh_pen DESC -- pilih row terbaru per id
),

FINAL_OUTPUT AS (

 	SELECT 
        'Tugasan' AS title, COUNT(*) AS total
    FROM 
        FINAL_V2 V2
    WHERE 
        UPPER(V2.STATUS_TUGASAN) IN ('BARU','DALAM TINDAKAN')
	UNION ALL 
    SELECT 
        'Baru' AS title, COUNT(*) AS total
    FROM 
        FINAL_V2 V2
    WHERE 
        UPPER(V2.STATUS_TUGASAN) = 'BARU'

    UNION ALL

    SELECT 
        'Dalam Tindakan' AS title, COUNT(*) AS total
    FROM 
        FINAL_V2 V2
    WHERE 
        UPPER(V2.STATUS_TUGASAN) = 'DALAM TINDAKAN'

	UNION ALL

    SELECT 'Selesai' AS title, COUNT(*) AS total
	FROM UMM_A_TGSN A_APP1 
	INNER JOIN UMM_APLIKASI APP_1 ON A_APP1.APLIKASI_ID=APP_1.APLIKASI_ID 
	INNER JOIN UMM_APLIKASI APP_2 ON A_APP1.APLIKASI_ID=APP_2.APLIKASI_ID 
	INNER JOIN IND_URSN URSN_1 ON APP_2.URSN_ID=URSN_1.URSN_ID 
	INNER JOIN IND_MODUL MOD_1 ON URSN_1.MODUL_ID=MOD_1.MODUL_ID 
	CROSS JOIN PCP_PENGGUNA CP_PEN 
	WHERE A_APP1.PENGGUNA_SEMASA_ID=CP_PEN.PENGGUNA_ID 
	AND (A_APP1.PENGGUNA_SEMASA_ID IS NOT NULL) AND (CP_PEN.NAMA_PENGGUNA=var_nama_pengguna)
	AND (A_APP1.STATUS_TUGASAN IS NOT NULL) AND UPPER(A_APP1.STATUS_TUGASAN)='SELESAI'
),

FINAL_OUTPUT_V2 AS (
	SELECT * FROM FINAL_OUTPUT 
	UNION ALL
	SELECT 
		'Jumlah Tugasan' AS title,
		(SELECT FO.total FROM FINAL_OUTPUT FO WHERE UPPER(FO.title) = 'TUGASAN') + 
		(SELECT FO.total FROM FINAL_OUTPUT FO WHERE UPPER(FO.title) = 'SELESAI') AS total
)


SELECT * FROM FINAL_OUTPUT_V2 FO_V2
WHERE UPPER(FO_V2.title) <> 'TUGASAN';

	
END;
$function$
;

-- DROP FUNCTION et_main_uat.instr(varchar, varchar, int4, int4);

CREATE OR REPLACE FUNCTION et_main_uat.instr(p_str character varying, p_substr character varying, p_start integer, p_occurrence integer)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE STRICT
AS $function$
  DECLARE
    v_str   VARCHAR DEFAULT p_str;
    v_pos0  INT DEFAULT 0;
    v_pos   INT DEFAULT 0;
    v_found INT DEFAULT p_occurrence;
  BEGIN
    IF p_start >= 1 THEN
      v_str = SUBSTR(p_str, p_start);
      v_pos0 = p_start;
    END IF;
 
    WHILE 1=1 LOOP
	-- Find the next occurrence
	v_pos = POSITION(p_substr IN v_str);
 
	-- Nothing found
	IF v_pos IS NULL OR v_pos = 0 THEN
	  RETURN v_pos;
	END IF;
 
	-- The required occurrence found
	IF v_found = 1 THEN
	  EXIT;
	END IF;
 
	-- Prepare to find another one occurrence
	v_found := v_found - 1;
        v_pos0 := v_pos0 + v_pos;
	v_str := SUBSTR(v_str, v_pos);
    END LOOP;
 
    RETURN v_pos0 + v_pos;
  END;
  $function$
;

-- DROP FUNCTION et_main_uat.is_json_valid(text);

CREATE OR REPLACE FUNCTION et_main_uat.is_json_valid(p_json_text text)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
DECLARE
  json_data jsonb;
BEGIN
  -- Try to cast the input string to jsonb
  BEGIN
    json_data := p_json_text::jsonb;
  EXCEPTION
    WHEN others THEN
      -- If an exception occurs, the string is not valid JSON
      RETURN FALSE;
  END;

  -- If the casting is successful, return true
  RETURN TRUE;
END;
$function$
;

-- DROP FUNCTION et_main_uat."json_exists"(sys."clob", text);

CREATE OR REPLACE FUNCTION et_main_uat."json_exists"(json_data clob, key text)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
begin
  	
  key = replace(key, '$.','');	
  RETURN CAST(json_data AS JSONB) ? key;
END;
$function$
;

-- DROP FUNCTION et_main_uat."json_exists"(jsonb, text);

CREATE OR REPLACE FUNCTION et_main_uat."json_exists"(json_data jsonb, key text)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
begin
  	
  key = replace(key, '$.','');	
  RETURN json_data ? key;
END;
$function$
;

-- DROP FUNCTION et_main_uat.json_exists_numeric(text, text);

CREATE OR REPLACE FUNCTION et_main_uat.json_exists_numeric(json_text text, key_name text)
 RETURNS numeric
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF json_text IS NULL OR json_text = '' OR json_text = '{}' OR json_text = 'null' OR LENGTH(TRIM(json_text)) = 0 THEN
    RETURN 0;
  END IF;
  BEGIN
    RETURN COALESCE((json_text::JSON ->> key_name)::NUMERIC, 0);
  EXCEPTION WHEN OTHERS THEN
    RETURN 0;
  END;
END;
$function$
;

-- DROP FUNCTION et_main_uat."json_value"(jsonb, text);

CREATE OR REPLACE FUNCTION et_main_uat."json_value"(json_data jsonb, key text)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
begin
  	
  key = replace(key, '$.','');	
  RETURN json_data->>key;
END;
$function$
;

-- DROP FUNCTION et_main_uat."json_value"(sys."clob", text);

CREATE OR REPLACE FUNCTION et_main_uat."json_value"(json_data clob, key text)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
begin
  	
  key = replace(key, '$.','');	
  RETURN json_data::jsonb->>key;
EXCEPTION
    WHEN others THEN
      -- If an exception occurs, return NULL or handle it as needed
      RETURN NULL; -- You can return a default value or handle the exception differently 
END;
$function$
;

-- DROP PROCEDURE et_main_uat.migrate_borang2_by_hakmilikid(varchar);

CREATE OR REPLACE PROCEDURE et_main_uat.migrate_borang2_by_hakmilikid(IN arg_hakmilik_id character varying)
 SECURITY DEFINER
AS $procedure$
	/* constants and variables */
	destination CONSTANT VARCHAR2(100) := 'et_main';
	migrationTime CONSTANT TIMESTAMP(6) := sysdate;
	username CONSTANT VARCHAR2(100) := 'MIGRATOR_S';
	migrationScript CONSTANT VARCHAR2(100) := 'STORED_PROC';
	msgNotifyUser VARCHAR2(4000);

	/* hardcoded variables */
	bandarTiada NUMBER(19,0);
	jenisPecahBahagi NUMBER(19,0);
	formulaUnitSyer NUMBER(19,0);
	negeriTiada NUMBER(19,0);
	unitLuasaTiada NUMBER(19,0);
	
	B2ASAS ET_DMSA.BORANG2_ASAS%ROWTYPE;
	
	/* exceptions */
	tiadaStrataInduk EXCEPTION;
	noNoPetak EXCEPTION;
	noNoBangunan EXCEPTION;
	noNoTingkat EXCEPTION;
	landedStrataWNoTingkat EXCEPTION;
	landedStrataWNoBgnn EXCEPTION;
	blokSmntaraWNoBgnn EXCEPTION;
	noIndeksDetail EXCEPTION;
	borang2NotFound EXCEPTION;
	exceptionNotifyUser EXCEPTION;
  versiIsNotZero EXCEPTION;
--------------------------------------------------------------------------------	
	/* functions (start) */
	FUNCTION findStrataIndukIdByIdHakmilik(idHakmilik IN  VARCHAR2) 
	RETURN NUMBER IS
		indukId NUMBER(19,0);
	BEGIN
		SELECT HKMLK_ID INTO indukId
		FROM IND_HKMLK WHERE ID_HKMLK = idHakmilik;
		RETURN indukId;
	EXCEPTION
		WHEN OTHERS THEN
			RAISE tiadaStrataInduk;
			RETURN NULL;
	END;
--------------------------------------------------------------------------------		
	FUNCTION findBgnIdByNamaAndMklmtStrId(namaBgn IN VARCHAR2, mStrataId IN NUMBER) 
	RETURN NUMBER IS
		bgnnId NUMBER(19,0);
	BEGIN
		SELECT b.BANGUNAN_ID INTO bgnnId
		FROM STR_I_BANGUNAN b WHERE b.NAMA LIKE namaBgn and b.MKLMT_STRATA_ID = mStrataId;
		RETURN bgnnId;
	EXCEPTION
		WHEN OTHERS THEN
			DBMS_OUTPUT.put_line('ERROR findBgnIdByNamaAndMklmtStrId('|| namaBgn || ', '
			|| mStrataId||')');
			RETURN NULL;
	END;
--------------------------------------------------------------------------------		
	FUNCTION findMenaraIdByBangunanId(bgnnId IN NUMBER) 
	RETURN NUMBER IS
		menaraId NUMBER(19,0);
	BEGIN
		SELECT m.MENARA_ID INTO menaraId
		FROM STR_I_MENARA m WHERE m.NAMA LIKE 'NA' and m.BANGUNAN_ID = bgnnId;
		RETURN menaraId;
	EXCEPTION
		WHEN OTHERS THEN
			DBMS_OUTPUT.put_line('ERROR findMenaraIdByBangunanId('|| bgnnId||')');
		RETURN NULL;
	END;
--------------------------------------------------------------------------------		
	FUNCTION findTingIdByNamaAndBgnId(namaTing IN  VARCHAR2, bgnnId IN NUMBER) 
	RETURN NUMBER IS
		tingId NUMBER(19,0);
	BEGIN
		SELECT t.TINGKAT_ID INTO tingId FROM STR_I_TINGKAT t
		JOIN STR_I_MENARA m ON (t.MENARA_ID = m.MENARA_ID)
		JOIN STR_I_BANGUNAN b ON (m.BANGUNAN_ID = b.BANGUNAN_ID)
		WHERE t.NAMA LIKE namaTing AND b.BANGUNAN_ID = bgnnId;
		RETURN tingId;
	EXCEPTION
		WHEN OTHERS THEN
			DBMS_OUTPUT.put_line('ERROR findTingIdByNamaAndBgnId('|| namaTing || ', '
			|| bgnnId||')');
		RETURN NULL;
	END;
--------------------------------------------------------------------------------		
	FUNCTION returnSpaceIfNull(field IN  VARCHAR2) 
	RETURN VARCHAR2 IS
		tempVariable VARCHAR2(200);
	BEGIN
		tempVariable := trim(field);
		IF tempVariable IS NULL THEN
			tempVariable := ' ';
		END IF;
		RETURN tempVariable;
	END;
--------------------------------------------------------------------------------		
	FUNCTION getSakIdBySakKod(sakKod IN  VARCHAR2) 
	RETURN NUMBER IS
		sakId NUMBER(19, 0);
	BEGIN
		SELECT SENARAI_AHLI_KUMPULAN_ID INTO sakId
		FROM RJK_SENARAI_AHLI_KUMPULAN WHERE KOD = sakKod;
		RETURN sakId;
	END;
	
	FUNCTION getDmsaSakKodByDmsaSakId(sakId IN NUMBER, blockDescription IN VARCHAR2) 
	RETURN VARCHAR2 IS
		sakKod VARCHAR2(120);
	BEGIN
		SELECT KOD INTO sakKod
		FROM et_dmsa.RJK_SENARAI_AHLI_KUMPULAN WHERE SENARAI_AHLI_KUMPULAN_ID = sakId;
		RETURN sakKod;
	EXCEPTION
		WHEN OTHERS THEN
			DBMS_OUTPUT.put_line('ERROR getDmsaSakKodByDmsaSakId('||sakId||')'|| blockDescription||' '||SQLERRM);
			RETURN NULL;
	END;
--------------------------------------------------------------------------------		
	FUNCTION getSakIdByDmsaSakKod(sakKod IN VARCHAR2, blockDescription IN VARCHAR2,skkod IN VARCHAR2) 
	RETURN NUMBER IS
		sakId NUMBER(19, 0);
	BEGIN
		SELECT SENARAI_AHLI_KUMPULAN_ID INTO sakId
		FROM RJK_SENARAI_AHLI_KUMPULAN WHERE STRATA_KOD = sakKod and senarai_kumpulan_id = (select senarai_kumpulan_id from rjk_senarai_kumpulan where kod = skkod);
		RETURN sakId;
	EXCEPTION
		WHEN OTHERS THEN
			DBMS_OUTPUT.put_line('ERROR getSakIdByDmsaSakKod('||sakKod||')'||blockDescription||' '||SQLERRM);
			RETURN NULL;
	END;
--------------------------------------------------------------------------------		
	FUNCTION getSakIdByDmsaSakId(dmsaSakId IN NUMBER, blockDescription IN VARCHAR2,skkod IN VARCHAR2)
	RETURN NUMBER IS
		sakId NUMBER(19,0);
		dmsaSakKod VARCHAR2(120);
	BEGIN
		dmsaSakKod := getDmsaSakKodByDmsaSakId(dmsaSakId, blockDescription);
		sakId := getSakIdByDmsaSakKod(dmsaSakKod, blockDescription,skkod);
		RETURN sakId;
	END;
--------------------------------------------------------------------------------		
	PROCEDURE findStrataIndeksVersiByHkmlkId(hkmlkId IN NUMBER, indeksVersiId OUT NUMBER, indeksId OUT NUMBER, noVersiB2 OUT NUMBER) IS
	BEGIN
		SELECT STRATA_IDX_VERSI_ID, STRATA_IDX_ID, NO_VERSI INTO indeksVersiId, indeksId, noVersiB2
		FROM ind_strata_IDX_VERSI WHERE HKMLK_ID = hkmlkId
    AND FLAG_AKTIF = 'Y';
	EXCEPTION
		WHEN OTHERS THEN
			DBMS_OUTPUT.put_line('ERROR findStrataIndeksVersiByHkmlkId('||hkmlkId||') '||SQLERRM);
	END;
--------------------------------------------------------------------------------		
	FUNCTION findMklmtStrataByHkmlkId(idHakmilik IN VARCHAR2)
	RETURN NUMBER IS
		maklumatStrataId NUMBER(19,0);
	BEGIN
		SELECT MKLMT_STRATA_ID INTO maklumatStrataId
		FROM STR_I_MKLMT_STRATA WHERE ID_HKMLK = idHakmilik;
    --HAKMILIK = idHakmilik;
		RETURN maklumatStrataId;
	EXCEPTION
		WHEN OTHERS THEN
			DBMS_OUTPUT.put_line('ERROR findMklmtStrataByHkmlkId('||idHakmilik||') '||SQLERRM);
			RETURN NULL;
	END;
--------------------------------------------------------------------------------	
	FUNCTION findMcByMklmtStrataId(mklmtStrataId IN NUMBER)
	RETURN NUMBER IS
		mcId NUMBER(19,0);
	BEGIN
		SELECT MC_ID INTO mcId
		FROM STR_I_MC WHERE MKLMT_STRATA_ID = mklmtStrataId;
		RETURN mcId;
	EXCEPTION
		WHEN OTHERS THEN
			DBMS_OUTPUT.put_line('ERROR findMcByHkmlkId('||mklmtStrataId||') '||SQLERRM);
			RETURN NULL;
	END;
	/* functions (end) */
--------------------------------------------------------------------------------		
BEGIN
	/* block to find borang 2 asas */
	BEGIN
		SELECT * INTO B2ASAS FROM et_dmsa.BORANG2_ASAS WHERE HAKMILIK_ID = arg_hakmilik_id;
	EXCEPTION
		WHEN OTHERS THEN
			RAISE borang2NotFound;
	/* end block to find borang 2 asas */
	END;
	
	/* initialize hardcoded variables */
	bandarTiada := getSakIdBySakKod('2002');
	jenisPecahBahagi := getSakIdBySakKod('STR_JPB_BGNN_DAN_TNH');
	formulaUnitSyer := getSakIdBySakKod('STR_FUS_STANDARD');
	negeriTiada := getSakIdBySakKod('17');
	unitLuasaTiada := getSakIdBySakKod('UNIKELMP');
	
	DECLARE
		errMsgBorang2 VARCHAR2(250);
		idHakmilik VARCHAR2(160);
		hakmilikId NUMBER(19,0);
		indeksId NUMBER(19,0);
		indeksVersiId NUMBER(19,0);
		maklumatStrataId NUMBER(19,0);
		noRujukanPelanLama ET_DMSA.MAKLUMAT_SIFUS.NO_RUJUKAN_PELAN_BANGUNAN%TYPE;
		noVersiB2 NUMBER;
		
	/* start b2 block*/
	BEGIN
		/* find existing maklumat induk block */
		BEGIN
			idHakmilik := B2ASAS.HAKMILIK_ID;
			hakmilikId := findStrataIndukIdByIdHakmilik(idHakmilik);
			
			findStrataIndeksVersiByHkmlkId(hakmilikId, indeksVersiId, indeksId, noVersiB2);
      			
			IF noVersiB2 > 0 THEN
				RAISE versiIsNotZero;
			END IF;
      
		EXCEPTION
			WHEN tiadaStrataInduk THEN
				errMsgBorang2 := 'Tiada Strata Induk B2ASAS ID HAKMLK:' || idHakmilik || ' ' || 'B2ASAS ID:' || B2ASAS.BORANG2_ASAS_ID;
				msgNotifyUser :=  msgNotifyUser || ' ***** Tiada strata induk (tiada id hakmilik ini dalam SPTB). Sila pasti bandar pekan mukim / jenis hakmilik / no hakmilik betul.';
				GOTO skipB2;
				
      WHEN versiIsNotZero THEN
				errMsgBorang2 := 'ind_strata_IDX_VERSI IdxVersi versi is not zero B2ASAS:' || B2ASAS.BORANG2_ASAS_ID || ' ID_HAKMILIK:'
								|| idHakmilik || ' HKMLK_ID:' || hakmilikId || ' noVersi:' || noVersiB2;
				msgNotifyUser := msgNotifyUser || ' ***** Versi Borang 2 ini bukan 0. Sila rujuk migration team. ';
				GOTO skipB2;  
        
			WHEN OTHERS THEN
				errMsgBorang2 := 'Error in finding maklumat induk block B2ASAS ID:'|| B2ASAS.BORANG2_ASAS_ID||' '||SQLERRM;
				msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgBorang2;
				GOTO skipB2;
		/* end find existing maklumat induk block */
		END;
		
		DECLARE
			noBukuDaftar ET_DMSA.BORANG2_ASAS.NO_BUKU_DAFTAR_STRATA%TYPE;
			alamatMc1 ET_DMSA.BORANG2_ASAS.ALAMAT1_MC%TYPE;
			poskodMc et_dmsa.BORANG2_ASAS.POSKOD_MC%TYPE;
			bandarMcId NUMBER(19,0);
			bandarLainMc ET_DMSA.RJK_SENARAI_AHLI_KUMPULAN.NAMA%TYPE;
			negeriMcId NUMBER(19,0);
			bandarPDokId NUMBER(19,0);
			bandarLainPDok ET_DMSA.RJK_SENARAI_AHLI_KUMPULAN.NAMA%TYPE;
			negeriPDokId NUMBER(19,0);
			noRujukanFails VARCHAR2(500);
		/* block for maklumat asas */
		BEGIN
			DECLARE
				CURSOR C_RUJ_FAIL IS 
					SELECT NO_RUJUKAN_FAIL FROM et_dmsa.NO_RUJUKAN_FAIL WHERE NORJKFAIL_BRG2A_ID = B2ASAS.BORANG2_ASAS_ID;
				noRujukanFail ET_DMSA.NO_RUJUKAN_FAIL.NO_RUJUKAN_FAIL%TYPE;
			/* block to construct no rujukan fail */
			BEGIN
				FOR RUJUKAN_FAILS IN C_RUJ_FAIL LOOP
					noRujukanFail := TRIM(RUJUKAN_FAILS.NO_RUJUKAN_FAIL);
					IF noRujukanFail IS NOT NULL THEN
						noRujukanFails := noRujukanFails || noRujukanFail || ',';
					END IF;
				END LOOP;
				noRujukanFails := TRIM(TRAILING ',' FROM noRujukanFails);
			EXCEPTION
				WHEN OTHERS THEN
					DBMS_OUTPUT.put_line('ERROR CONSTRUCTING NO RUJUKAN FAIL:' || noRujukanFails || SQLERRM);
					
					msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || 'ERROR CONSTRUCTING NO RUJUKAN FAIL NO RUJUKAN FAIL:' || noRujukanFails || SQLERRM ;
			/* end block to construct no rujukan fail */
			END;
		
			DECLARE
				bandarMcNama ET_DMSA.RJK_SENARAI_AHLI_KUMPULAN.NAMA%TYPE;
				bandarMcKod ET_DMSA.RJK_SENARAI_AHLI_KUMPULAN.KOD%TYPE;
				bandarPDokNama ET_DMSA.RJK_SENARAI_AHLI_KUMPULAN.NAMA%TYPE;
				bandarPDokKod ET_DMSA.RJK_SENARAI_AHLI_KUMPULAN.KOD%TYPE;
			/* ind_strata_IDX */
			BEGIN
				noBukuDaftar := B2ASAS.NO_BUKU_DAFTAR_STRATA;
				alamatMc1 := returnSpaceIfNull(B2ASAS.ALAMAT1_MC);
				poskodMc := returnSpaceIfNull(B2ASAS.POSKOD_MC);
				negeriPDokId := getSakIdByDmsaSakId(B2ASAS.NEGERI_ID_PENYAMPAIAN_DOK, 'B2ASAS.NEGERI_ID_PENYAMPAIAN_DOK','NEGERI');
				
				negeriMcId := getSakIdByDmsaSakId(B2ASAS.NEGERI_ID_MC, 'B2ASAS.NEGERI_ID_MC','NEGERI');
				IF negeriMcId IS NULL THEN
					negeriMcId := negeriTiada;
				END IF;
				
				IF B2ASAS.BANDAR_ID_MC IS NOT NULL THEN 
					SELECT KOD, NAMA INTO bandarMcKod, bandarMcNama
					FROM et_dmsa.RJK_SENARAI_AHLI_KUMPULAN WHERE SENARAI_AHLI_KUMPULAN_ID = B2ASAS.BANDAR_ID_MC;
				END IF;
				
				IF bandarMcKod IS NOT NULL THEN 
					bandarMcId := getSakIdByDmsaSakKod(bandarMcKod, 'BORANG2.BANDAR_ID_MC','BANDAR');
				END IF;
					
				IF bandarMcId IS NULL THEN
					bandarLainMc := bandarMcNama;
					bandarMcId := bandarTiada;
				END IF;
				
				IF B2ASAS.BANDAR_ID_PENYAMPAIAN_DOK IS NOT NULL THEN 
					SELECT KOD, NAMA INTO bandarPDokKod, bandarPDokNama
					FROM et_dmsa.RJK_SENARAI_AHLI_KUMPULAN WHERE SENARAI_AHLI_KUMPULAN_ID = B2ASAS.BANDAR_ID_PENYAMPAIAN_DOK;
				END IF;
				
				IF bandarPDokKod IS NOT NULL THEN 
					bandarPDokId := getSakIdByDmsaSakKod(bandarPDokKod, 'BORANG2.BANDAR_ID_PENYAMPAIAN_DOK','BANDAR');
				END IF;
					
				IF bandarPDokId IS NULL AND bandarMcKod IS NOT NULL THEN
					bandarLainPDok := bandarPDokNama;
					bandarPDokId := bandarTiada;
				END IF;
				
				IF indeksId IS NULL THEN
					INSERT INTO ind_strata_IDX(STRATA_IDX_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
											VERSION, NO_DAFTAR, JUMLAH_SYER, NAMA_MC, ALAMAT_DAFTAR1,
											ALAMAT_DAFTAR2, ALAMAT_DAFTAR3, ALAMAT_DAFTAR4, POSKOD_DAFTAR, BANDAR_DAFTAR_ID,
											BANDAR_DAFTAR_LAIN, NEGERI_DAFTAR_ID, --ALAMAT, ALAMAT2, ALAMAT3,
											--ALAMAT4, POSKOD, BANDAR_ID, BANDAR_LAIN, NEGERI_ID, 
											NO_SKIM, NO_RUJUKAN_FAIL, JUMLAH_FOLIO_PELAN)
						VALUES(SEQ_STRATA_IDX.NEXTVAL, username, sysdate, username, sysdate,
								0, noBukuDaftar, B2ASAS.JUMLAH_UNIT_SYER, B2ASAS.NAMA_MC, alamatMc1,
								B2ASAS.ALAMAT2_MC, B2ASAS.ALAMAT3_MC, B2ASAS.ALAMAT4_MC, poskodMc, bandarMcId,
								bandarLainMc, negeriMcId, --B2ASAS.ALAMAT1_PENYAMPAIAN_DOK, B2ASAS.ALAMAT2_PENYAMPAIAN_DOK, B2ASAS.ALAMAT3_PENYAMPAIAN_DOK,
								--B2ASAS.ALAMAT4_PENYAMPAIAN_DOK, B2ASAS.POSKOD_PENYAMPAIAN_DOK, bandarPDokId, bandarLainPDok, negeriPDokId,
								TRIM(B2ASAS.NO_SKIM), noRujukanFails, B2ASAS.JUMLAH_FOLIO_PELAN);
					indeksId := SEQ_STRATA_IDX.CURRVAL;
          
          INSERT INTO ind_strata_IDX_PENYAMPAIAN(STRATA_IDX_PENYAMPAIAN_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
                      VERSION, STRATA_IDX_ID, NAMA, ALAMAT, ALAMAT2, ALAMAT3,
											ALAMAT4, POSKOD, BANDAR_ID, BANDAR_LAIN, NEGERI_ID)
						VALUES(SEQ_STRATA_IDX_PENYAMPAIAN.NEXTVAL, username, sysdate, username, sysdate,
								0, indeksId, null, B2ASAS.ALAMAT1_PENYAMPAIAN_DOK, B2ASAS.ALAMAT2_PENYAMPAIAN_DOK, B2ASAS.ALAMAT3_PENYAMPAIAN_DOK,
								B2ASAS.ALAMAT4_PENYAMPAIAN_DOK, B2ASAS.POSKOD_PENYAMPAIAN_DOK, bandarPDokId, bandarLainPDok, negeriPDokId);
          
				ELSE
					UPDATE ind_strata_IDX SET NO_DAFTAR = noBukuDaftar, JUMLAH_SYER = B2ASAS.JUMLAH_UNIT_SYER, NAMA_MC = B2ASAS.NAMA_MC, ALAMAT_DAFTAR1 = alamatMc1,
					ALAMAT_DAFTAR2 = B2ASAS.ALAMAT2_MC, ALAMAT_DAFTAR3 = B2ASAS.ALAMAT3_MC, ALAMAT_DAFTAR4 = B2ASAS.ALAMAT4_MC, POSKOD_DAFTAR = poskodMc,
					BANDAR_DAFTAR_ID = bandarMcId, BANDAR_DAFTAR_LAIN = bandarLainMc, NEGERI_DAFTAR_ID = negeriMcId, --ALAMAT = B2ASAS.ALAMAT1_PENYAMPAIAN_DOK,
					--ALAMAT2 = B2ASAS.ALAMAT2_PENYAMPAIAN_DOK, ALAMAT3 = B2ASAS.ALAMAT3_PENYAMPAIAN_DOK, ALAMAT4 = B2ASAS.ALAMAT4_PENYAMPAIAN_DOK,
					--POSKOD = B2ASAS.POSKOD_PENYAMPAIAN_DOK, BANDAR_ID = bandarPDokId, BANDAR_LAIN = bandarLainPDok, NEGERI_ID = negeriPDokId,
					NO_SKIM = TRIM(B2ASAS.NO_SKIM), NO_RUJUKAN_FAIL = noRujukanFails, JUMLAH_FOLIO_PELAN = B2ASAS.JUMLAH_FOLIO_PELAN
					WHERE STRATA_IDX_ID = indeksId;
          
          UPDATE ind_strata_IDX_PENYAMPAIAN SET 
					ALAMAT = B2ASAS.ALAMAT1_PENYAMPAIAN_DOK, ALAMAT2 = B2ASAS.ALAMAT2_PENYAMPAIAN_DOK, 
					ALAMAT3 = B2ASAS.ALAMAT3_PENYAMPAIAN_DOK, ALAMAT4 = B2ASAS.ALAMAT4_PENYAMPAIAN_DOK,
					POSKOD = B2ASAS.POSKOD_PENYAMPAIAN_DOK, BANDAR_ID = bandarPDokId, BANDAR_LAIN = bandarLainPDok, NEGERI_ID = negeriPDokId
					WHERE STRATA_IDX_ID = indeksId;
          
				END IF;
				
			EXCEPTION
				WHEN OTHERS THEN 
					errMsgBorang2 := 'ind_strata_IDX B2ASAS ID:' || B2ASAS.BORANG2_ASAS_ID || ' ' || SQLERRM;
					msgNotifyUser := msgNotifyUser || ' ***** Sila pasti No Pendaftaran Buku Strata diisi / Alamat tidak melebihi 80 characters dalam Maklumat Asas (DMSA) - ' || SQLERRM;
					GOTO skipB2;
			/* end ind_strata_IDX */
			END;
		
			/* ind_strata_IDX_VERSI */
			BEGIN
				IF indeksVersiId IS NULL THEN 
					INSERT INTO ind_strata_IDX_VERSI(STRATA_IDX_VERSI_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
													VERSION, STRATA_IDX_ID, NO_VERSI, HKMLK_ID)
					VALUES (SEQ_STRATA_IDX_VERSI.NEXTVAL, username, sysdate, username, sysdate,
							0, indeksId, 0, hakmilikId);
					indeksVersiId := SEQ_STRATA_IDX_VERSI.CURRVAL;
				ELSE
					UPDATE ind_strata_IDX_VERSI SET STRATA_IDX_ID = indeksId, NO_VERSI = 0, HKMLK_ID = hakmilikId
					WHERE STRATA_IDX_VERSI_ID = indeksVersiId;
				END IF;
			EXCEPTION
				WHEN OTHERS THEN 
					errMsgBorang2 := 'ind_strata_IDX_VERSI B2ASAS ID:' || B2ASAS.BORANG2_ASAS_ID || SQLERRM;
					msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgBorang2 ;
					GOTO skipB2;
			/* end ind_strata_IDX_VERSI */
			END;

			DECLARE
				errMsgMklmtStrata VARCHAR2(250);
				kiraanUnitSyer VARCHAR2(255);
				maklumatSifus ET_DMSA.MAKLUMAT_SIFUS%ROWTYPE;
			/* block to insert maklumat strata */
			BEGIN
				/* retrieve maklumatSifus block by idHakmilik */
				BEGIN
					SELECT s.* INTO maklumatSifus FROM et_dmsa.MAKLUMAT_SIFUS s
					JOIN et_dmsa.IND_MAKLUMAT_HAKMILIK m ON (m.MAKLUMAT_HAKMILIK_ID = s.MKLMT_HAKMILIK_SIFUS_ID)
					WHERE m.HAKMILIK_ID = idHakmilik;
					
					noRujukanPelanLama := trim(maklumatSifus.NO_RUJUKAN_PELAN_BANGUNAN);
				EXCEPTION
					WHEN OTHERS THEN
						errMsgMklmtStrata := 'MAKLUMAT_SIFUS error retrieving for this idHakmilik:' || idHakmilik || ' B2ASAS ID:'
												|| B2ASAS.BORANG2_ASAS_ID || ' ' || SQLERRM;
						DBMS_OUTPUT.put_line(errMsgMklmtStrata);
				/* end retrieve maklumatSifus block by idHakmilik */
				END;
				
				IF maklumatSifus.MKLMT_SIFUS_ID IS NOT NULL THEN
					DECLARE
						jenisPmbgn ET_DMSA.FORMULA_UNIT_SYER.JENIS_PEMBANGUNAN%TYPE;
						bilPetak ET_DMSA.FORMULA_UNIT_SYER.BILANGAN_PETAK%TYPE;
						kiraan et_dmsa.FORMULA_UNIT_SYER.KIRAAN_UNIT_SYER%TYPE;
						CURSOR C_KIRAAN_US IS SELECT * FROM ET_DMSA.FORMULA_UNIT_SYER
							WHERE FUS_MKLMTSIFUS_ID = maklumatSifus.MKLMT_SIFUS_ID;
					/* construct kiraan unit syer block */
					BEGIN
						FOR KIRAAN_US IN C_KIRAAN_US LOOP
							jenisPmbgn := TRIM(KIRAAN_US.JENIS_PEMBANGUNAN);
							bilPetak := KIRAAN_US.BILANGAN_PETAK;
							kiraan := TRIM(SUBSTR(KIRAAN_US.KIRAAN_UNIT_SYER, 1, INSTR(KIRAAN_US.KIRAAN_UNIT_SYER, '=') - 1));
							
							IF jenisPmbgn IS NULL OR bilPetak IS NULL OR kiraan IS NULL THEN
								kiraanUnitSyer := NULL;
								EXIT;
							ELSE
								kiraanUnitSyer := kiraanUnitSyer || '@' || jenisPmbgn || ':' || bilPetak || ':' || kiraan || '||';
							END IF;
						END LOOP;
						DBMS_OUTPUT.put_line('Kiraan:' || kiraanUnitSyer);
					EXCEPTION
						WHEN OTHERS THEN
							errMsgMklmtStrata := 'Error in loop to construct formula unit syer. MAKLUMAT_SIFUS ID:' 
												|| maklumatSifus.MKLMT_SIFUS_ID || ' ' || SQLERRM;
							DBMS_OUTPUT.put_line(errMsgMklmtStrata);
					/* end construct kiraan unit syer block */
					END;
				END IF;
			
				/* STR_I_MAKLUMAT_STRATA */
				BEGIN
					maklumatStrataId := findMklmtStrataByHkmlkId(idHakmilik);
					IF maklumatStrataId IS NULL THEN
						INSERT INTO STR_I_MKLMT_STRATA(MKLMT_STRATA_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
													VERSION, NO_BUKU_DAFTAR, NO_CPSP, TRKH_CPSP, NAMA_PEMAJU,
													JNS_PEMBINAAN, JNS_KOS_RENDAH, JNS_PECAH_BAHAGI_ID, FORMULA_UNIT_SYER_ID, ID_HKMLK,--HAKMILIK,
													NO_SIRI_SIJIL_SIFUS, KIRAAN_UNIT_SYER, NAMA_SKIM, NO_RUJUKAN_FAIL, TRKH_KELULUSAN_SIFUS,
													NO_KELUARAN_SIFUS)
						VALUES(SEQ_MKLMT_STRATA.NEXTVAL, username, SYSDATE, username, SYSDATE,
								0, noBukuDaftar, '-', SYSDATE, '-',
								'-', 'N', jenisPecahBahagi, formulaUnitSyer, idHakmilik,
								maklumatSifus.NO_SIRI, kiraanUnitSyer, maklumatSifus.NAMA_SKIM, maklumatSifus.NO_RUJUKAN_FAIL, maklumatSifus.TARIKH_KELULUSAN,
								maklumatSifus.KELUARAN);
						maklumatStrataId := SEQ_MKLMT_STRATA.CURRVAL;
					ELSE
						UPDATE STR_I_MKLMT_STRATA SET NO_BUKU_DAFTAR = noBukuDaftar, NO_CPSP = '-', TRKH_CPSP = SYSDATE, NAMA_PEMAJU = '-',
						JNS_PEMBINAAN = '-', JNS_KOS_RENDAH = 'N', JNS_PECAH_BAHAGI_ID = jenisPecahBahagi, FORMULA_UNIT_SYER_ID = formulaUnitSyer,
						ID_HKMLK/*HAKMILIK*/ = idHakmilik, NO_SIRI_SIJIL_SIFUS = maklumatSifus.NO_SIRI, KIRAAN_UNIT_SYER = kiraanUnitSyer, NAMA_SKIM = maklumatSifus.NAMA_SKIM,
						NO_RUJUKAN_FAIL = maklumatSifus.NO_RUJUKAN_FAIL, TRKH_KELULUSAN_SIFUS = maklumatSifus.TARIKH_KELULUSAN, NO_KELUARAN_SIFUS = maklumatSifus.KELUARAN
						WHERE MKLMT_STRATA_ID = maklumatStrataId;
					END IF;
				EXCEPTION
					WHEN OTHERS THEN 
						errMsgMklmtStrata := 'STR_I_MAKLUMAT_STRATA B2ASAS ID:' || B2ASAS.BORANG2_ASAS_ID || SQLERRM;
						DBMS_OUTPUT.put_line(errMsgMklmtStrata);
				/* end STR_I_MAKLUMAT_STRATA */
				END;
			/* end block to insert maklumat strata */
			END;

			DECLARE
				errMsgStrMc VARCHAR2(250);
				mcId NUMBER(19,0);
			/* STR_I_MC */
			BEGIN
				mcId := findMcByMklmtStrataId(maklumatStrataId);
				IF mcId IS NULL THEN
					INSERT INTO STR_I_MC(MC_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
										VERSION, NAMA, ALAMAT_DAFTAR1, ALAMAT_DAFTAR2, ALAMAT_DAFTAR3,
										ALAMAT_DAFTAR4, POSKOD_DAFTAR, BANDAR_DAFTAR_ID, BANDAR_DAFTAR_LAIN, NEGERI_DAFTAR_ID,
										ALAMAT, ALAMAT2, ALAMAT3, ALAMAT4, 
										POSKOD, BANDAR_ID, BANDAR_LAIN, NEGERI_ID, MKLMT_STRATA_ID)
						VALUES(SEQ_MC.NEXTVAL, username, sysdate, username, sysdate,
							0, B2ASAS.NAMA_MC, alamatMc1, B2ASAS.ALAMAT2_MC, B2ASAS.ALAMAT3_MC, 
							B2ASAS.ALAMAT4_MC, poskodMc, bandarMcId, bandarLainMc, negeriMcId,
							B2ASAS.ALAMAT1_PENYAMPAIAN_DOK, B2ASAS.ALAMAT2_PENYAMPAIAN_DOK, B2ASAS.ALAMAT3_PENYAMPAIAN_DOK, B2ASAS.ALAMAT4_PENYAMPAIAN_DOK,
							B2ASAS.POSKOD_PENYAMPAIAN_DOK, bandarPDokId, bandarLainPDok, negeriPDokId, maklumatStrataId);
				ELSE
					UPDATE STR_I_MC SET NAMA = B2ASAS.NAMA_MC, ALAMAT_DAFTAR1 = alamatMc1, ALAMAT_DAFTAR2 = B2ASAS.ALAMAT2_MC, ALAMAT_DAFTAR3 = B2ASAS.ALAMAT3_MC,
					ALAMAT_DAFTAR4 = B2ASAS.ALAMAT4_MC, POSKOD_DAFTAR = poskodMc, BANDAR_DAFTAR_ID = bandarMcId, BANDAR_DAFTAR_LAIN = bandarLainMc, 
					NEGERI_DAFTAR_ID = negeriMcId, ALAMAT = B2ASAS.ALAMAT1_PENYAMPAIAN_DOK, ALAMAT2 = B2ASAS.ALAMAT2_PENYAMPAIAN_DOK, ALAMAT3 = B2ASAS.ALAMAT3_PENYAMPAIAN_DOK,
					ALAMAT4 = B2ASAS.ALAMAT4_PENYAMPAIAN_DOK, POSKOD = B2ASAS.POSKOD_PENYAMPAIAN_DOK, BANDAR_ID = bandarPDokId, BANDAR_LAIN = bandarLainPDok,
					NEGERI_ID = negeriPDokId, MKLMT_STRATA_ID = maklumatStrataId
					WHERE MC_ID = mcId;
				END IF;
				DBMS_OUTPUT.put_line('STR_I_MC inserted');
			EXCEPTION
				WHEN OTHERS THEN 
					errMsgStrMc := 'STR_I_MC B2ASAS ID:' || B2ASAS.BORANG2_ASAS_ID || SQLERRM;
					DBMS_OUTPUT.put_line(errMsgStrMc);
			/* end STR_I_MC */
			END;
		/* end block for maklumat asas */
		END;
		
		DECLARE
			errMsgDel VARCHAR2(250);
			byParent VARCHAR2(50);
			bangunanIds VARCHAR2(2000);
			tingkatIds VARCHAR2(2000);
			menaraIds VARCHAR2(2000);
			tingkatSmntaraIds VARCHAR2(3000);
			menaraSmntaraIds VARCHAR2(3000);
			CURSOR C_BGNN IS SELECT p.BANGUNAN_ID FROM STR_I_PTK p 
				WHERE p.MKLMT_STRATA_ID = maklumatStrataId AND p.BANGUNAN_ID IS NOT NULL GROUP BY p.BANGUNAN_ID;
			CURSOR C_TINGKT IS SELECT p.TINGKAT_ID FROM STR_I_PTK p 
				WHERE p.MKLMT_STRATA_ID = maklumatStrataId AND p.TINGKAT_ID IS NOT NULL GROUP BY p.TINGKAT_ID;
			CURSOR C_MENARA IS SELECT p.MENARA_ID FROM STR_I_PTK p 
				WHERE p.MKLMT_STRATA_ID = maklumatStrataId AND p.MENARA_ID IS NOT NULL GROUP BY p.MENARA_ID;
			CURSOR C_TING_MENARA IS SELECT b.TINGKAT_ID, b.MENARA_ID FROM STR_I_BLOK_SMTR b
				WHERE b.MKLMT_STRATA_ID = maklumatStrataId AND b.TINGKAT_ID IS NOT NULL;
		/* block to delete all child tables */
		BEGIN
			/* block to construct bangunanIds */
			BEGIN
				bangunanIds := NULL;
				FOR BGNNS IN C_BGNN LOOP
					bangunanIds := bangunanIds || BGNNS.BANGUNAN_ID || ',';
				END LOOP;
				bangunanIds := TRIM(TRAILING ',' FROM bangunanIds);
			EXCEPTION
				WHEN OTHERS THEN
					errMsgDel := 'ERROR CONSTRUCTING BGNN IDS in delete block.' || SQLERRM;
					DBMS_OUTPUT.put_line(errMsgDel);
			END;
			
			/* block to construct tingkatIds */
			BEGIN
				tingkatIds := NULL;
				FOR TINGKATS IN C_TINGKT LOOP
					tingkatIds := tingkatIds || TINGKATS.TINGKAT_ID || ',';
				END LOOP;
				tingkatIds := TRIM(TRAILING ',' FROM tingkatIds);
			EXCEPTION
				WHEN OTHERS THEN
				errMsgDel := 'ERROR CONSTRUCTING TINGKAT IDS in delete block.' || SQLERRM;
					DBMS_OUTPUT.put_line(errMsgDel);
			END;

			/* block to construct menaraIds */
			BEGIN
				menaraIds := NULL;
				FOR MENARAS IN C_MENARA LOOP
					menaraIds := menaraIds || MENARAS.MENARA_ID || ',';
				END LOOP;
				menaraIds := TRIM(TRAILING ',' FROM menaraIds);
			EXCEPTION
				WHEN OTHERS THEN
					errMsgDel := 'ERROR CONSTRUCTING MENARA SEMENTARA IDS in delete block.' || SQLERRM;
					DBMS_OUTPUT.put_line(errMsgDel);
			END;
			
			/* block to construct tingkatSmntaraIds and menaraSmntaraIds */
			BEGIN
				tingkatSmntaraIds := NULL;
				menaraSmntaraIds := NULL;
				FOR TING_MEN IN C_TING_MENARA LOOP
					tingkatSmntaraIds := tingkatSmntaraIds || TING_MEN.TINGKAT_ID || ',';
					menaraSmntaraIds := menaraSmntaraIds || TING_MEN.MENARA_ID || ',';
				END LOOP;
				tingkatSmntaraIds := TRIM(TRAILING ',' FROM tingkatSmntaraIds);
				menaraSmntaraIds := TRIM(TRAILING ',' FROM menaraSmntaraIds);
			EXCEPTION
				WHEN OTHERS THEN
					errMsgDel := 'ERROR CONSTRUCTING TINGKAT AND MENARA SMNTARA IDS in delete block.' || SQLERRM;
					DBMS_OUTPUT.put_line(errMsgDel);
			END;
			
			/* delete ind_strata_IDX_PETAK_AKSESORI */
			BEGIN
				DELETE FROM ind_strata_IDX_PTK_AKSESORI WHERE IDX_AKHIR_ID = indeksVersiId;
			EXCEPTION
				WHEN OTHERS THEN
					errMsgDel := 'DELETE ind_strata_IDX_PETAK_AKSESORI B2ASAS:' || B2ASAS.BORANG2_ASAS_ID || ' indeksVersiId:'
								|| indeksVersiId || ' ' || SQLERRM;
					DBMS_OUTPUT.put_line(errMsgDel);
					
					msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || 'DELETE ind_strata_IDX_PETAK_AKSESORI: ' || SQLERRM;
			END;
			
			/* delete ind_strata_IDX_TERPRNC */
			BEGIN
--				UPDATE ind_strata_PETAK_AKSESORI SET STRATA_INDEKS_TERPERINCI_ID = NULL WHERE STRATA_INDEKS_TERPERINCI_ID IN (
--					SELECT STR_IDX_TERPRNC_ID FROM ind_strata_IDX_TERPRNC WHERE IDX_AKHIR_ID = indeksVersiId);
				DELETE FROM ind_BTRN_strata_IDX WHERE IDX_AKHIR_ID = indeksVersiId;
			EXCEPTION
				WHEN OTHERS THEN
					errMsgDel := 'DELETE ind_strata_IDX_TERPRNC B2ASAS:' || B2ASAS.BORANG2_ASAS_ID || ' indeksVersiId:'
								|| indeksVersiId || ' ' || SQLERRM;
					DBMS_OUTPUT.put_line(errMsgDel);
					
					msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgDel;
			END;
			
			/* delete ind_strata_IDX_RINGKASAN */
			BEGIN
				DELETE FROM ind_strata_IDX_RINGKASAN WHERE IDX_AKHIR_ID = indeksVersiId;
			EXCEPTION
				WHEN OTHERS THEN
					errMsgDel := 'DELETE ind_strata_IDX_RINGKASAN B2ASAS:' || B2ASAS.BORANG2_ASAS_ID || ' indeksVersiId:'
								|| indeksVersiId || ' ' || SQLERRM;
					DBMS_OUTPUT.put_line(errMsgDel);
					
					msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgDel;
			END;
			
			/* delete STR_I_PTK_AKSESORI */
			BEGIN
				DELETE FROM STR_I_PTK_AKSESORI WHERE PTK_ID IN 
				(SELECT PTK_ID FROM STR_I_PTK WHERE MKLMT_STRATA_ID = maklumatStrataId);
			EXCEPTION
				WHEN OTHERS THEN
					errMsgDel := 'DELETE STR_I_PTK_AKSESORI B2ASAS:' || B2ASAS.BORANG2_ASAS_ID || ' maklumatStrataId:'
								|| maklumatStrataId || ' ' || SQLERRM;
					DBMS_OUTPUT.put_line(errMsgDel);
			END;
			
			/* delete STR_I_PETAK */
			BEGIN
				DELETE FROM STR_I_PTK WHERE MKLMT_STRATA_ID = maklumatStrataId;
			EXCEPTION
				WHEN OTHERS THEN
					errMsgDel := 'DELETE STR_I_PETAK B2ASAS:' || B2ASAS.BORANG2_ASAS_ID || ' maklumatStrataId:'
								|| maklumatStrataId || ' ' || SQLERRM;
					DBMS_OUTPUT.put_line(errMsgDel);
			END;

			/* delete STR_I_BLOK_SEMENTARA */
			BEGIN
				DELETE FROM STR_I_BLOK_SMTR WHERE MKLMT_STRATA_ID = maklumatStrataId;
			EXCEPTION
				WHEN OTHERS THEN
					errMsgDel := 'DELETE STR_I_BLOK_SEMENTARA B2ASAS:' || B2ASAS.BORANG2_ASAS_ID || ' maklumatStrataId:'
								|| maklumatStrataId || ' ' || SQLERRM;
					DBMS_OUTPUT.put_line(errMsgDel);
			END;
			
			/* delete STR_I_TINGKAT */
			BEGIN
				IF tingkatIds IS NOT NULL THEN
					byParent := 'by petak';
					EXECUTE IMMEDIATE 'DELETE FROM STR_I_TINGKAT WHERE TINGKAT_ID IN ('||tingkatIds||')';
				END IF;
				
				IF tingkatSmntaraIds IS NOT NULL THEN
					byParent := 'by blok sementara';
					EXECUTE IMMEDIATE 'DELETE FROM STR_I_TINGKAT WHERE TINGKAT_ID IN ('||tingkatSmntaraIds||')';
				END IF;
			EXCEPTION
				WHEN OTHERS THEN
					errMsgDel := 'DELETE ' || byParent || ' STR_I_TINGKAT B2ASAS:' || B2ASAS.BORANG2_ASAS_ID || ' maklumatStrataId:'
								|| maklumatStrataId || ' ' || SQLERRM;
					DBMS_OUTPUT.put_line(errMsgDel);
			END;

			/* delete STR_I_MENARA */
			BEGIN
				IF menaraIds IS NOT NULL THEN
					byParent := 'by petak';
					EXECUTE IMMEDIATE 'DELETE FROM STR_I_MENARA WHERE MENARA_ID IN('||menaraIds||')';
				END IF;
				
				IF menaraSmntaraIds IS NOT NULL THEN 
					byParent := 'by blok sementara';
					EXECUTE IMMEDIATE 'DELETE FROM STR_I_MENARA WHERE MENARA_ID IN('||menaraSmntaraIds||')';
				END IF;
			EXCEPTION
				WHEN OTHERS THEN
					errMsgDel := 'DELETE ' || byParent || ' STR_I_MENARA B2ASAS:' || B2ASAS.BORANG2_ASAS_ID || ' maklumatStrataId:'
								|| maklumatStrataId || ' ' || SQLERRM;
					DBMS_OUTPUT.put_line(errMsgDel);
			END;
			
			/* delete STR_I_BANGUNAN */
			BEGIN
				IF bangunanIds IS NOT NULL THEN
					EXECUTE IMMEDIATE 'DELETE FROM STR_I_BANGUNAN WHERE BANGUNAN_ID IN ('||bangunanIds||')';
				END IF;
			EXCEPTION
				WHEN OTHERS THEN
					errMsgDel := 'DELETE STR_I_BANGUNAN B2ASAS:' || B2ASAS.BORANG2_ASAS_ID || ' maklumatStrataId:'
								|| maklumatStrataId || ' ' || SQLERRM;
					DBMS_OUTPUT.put_line(errMsgDel);
			END;
			
			/* delete STR_I_RUJUKAN_PELAN_BANGUNAN */
			BEGIN
				DELETE FROM STR_I_RUJUKAN_PELAN_BANGUNAN WHERE MKLMT_STRATA_ID = maklumatStrataId;
			EXCEPTION
				WHEN OTHERS THEN
					errMsgDel := 'DELETE STR_I_RUJUKAN_PELAN_BANGUNAN B2ASAS:' || B2ASAS.BORANG2_ASAS_ID || ' maklumatStrataId:'
								|| maklumatStrataId || ' ' || SQLERRM;
					DBMS_OUTPUT.put_line(errMsgDel);
			/* end delete STR_I_RUJUKAN_PELAN_BANGUNAN */
			END;
			
			DBMS_OUTPUT.put_line('Delete block complete.');
			/* block to delete all child tables */
		END;
		
		IF noRujukanPelanLama IS NOT NULL THEN
			DECLARE
				errMsgRujukanPelan VARCHAR2(250);
			/* STR_I_RUJUKAN_PELAN_BANGUNAN */
			BEGIN
				INSERT INTO STR_I_RUJUKAN_PELAN_BANGUNAN(RUJUKAN_PELAN_BANGUNAN_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
														VERSION, NO_RUJUKAN, MKLMT_STRATA_ID, TRKH)
						VALUES(SEQ_RUJUKAN_PELAN_BANGUNAN.NEXTVAL, username, sysdate, username, sysdate,
								0, noRujukanPelanLama, maklumatStrataId, sysdate);
			EXCEPTION
				WHEN OTHERS THEN
					errMsgRujukanPelan := 'STR_I_RUJUKAN_PELAN_BANGUNAN noRujukanPelanLama:' || noRujukanPelanLama || ' B2ASAS ID:' 
											|| B2ASAS.BORANG2_ASAS_ID || ' ID_HAKMILIK:' || idHakmilik || ' ' ||SQLERRM;
					DBMS_OUTPUT.put_line(errMsgRujukanPelan);
			/* end STR_I_RUJUKAN_PELAN_BANGUNAN */
			END;
		END IF;
		
		DECLARE
			CURSOR C_B2IDX IS 
				SELECT * FROM ET_DMSA.BORANG2_INDEKS_HEADER
				WHERE BORANG2_ASAS_ID = B2ASAS.BORANG2_ASAS_ID ORDER BY BORANG2_INDEKS_HEADER_ID;
		/* indeks block */
		BEGIN
			/* indeks header loop */
			FOR B2IH IN C_B2IDX LOOP
				/* indeks header block */
				DECLARE
					errMsgIndeks VARCHAR2(250);
					noBangunan et_dmsa.BORANG2_INDEKS_HEADER.NO_BANGUNAN%TYPE;
					noPelan et_dmsa.BORANG2_INDEKS_HEADER.FOLIO_PELAN%TYPE;
					noTingkat et_dmsa.BORANG2_INDEKS_HEADER.NO_TINGKAT%TYPE;
					countDetail NUMBER;

					CURSOR C_B2IDX_DET IS 
						SELECT * FROM et_dmsa.BORANG2_INDEKS_DETAIL
						WHERE BORANG2_INDEKS_HEADER_ID = B2IH.BORANG2_INDEKS_HEADER_ID ORDER BY BORANG2_INDEKS_DETAIL_ID;
				BEGIN
					countDetail := 0;
					noBangunan := replace(trim(upper(B2IH.NO_BANGUNAN)), '	');
					noTingkat := replace(trim(upper(B2IH.NO_TINGKAT)), '	');
					noPelan := replace(trim(B2IH.FOLIO_PELAN), '	');
					
					IF (upper(noBangunan) LIKE '%TIADA%' AND upper(noTingkat) LIKE '%TIADA%') THEN
						noBangunan := null;
						noTingkat := null;
					END IF;
					
					/* indeks detail loop */
					FOR B2ID IN C_B2IDX_DET LOOP
						countDetail := countDetail + 1;
						
						DECLARE
							errMsgIndeksDetail VARCHAR2(250);
							isBlokSementara BOOLEAN := FALSE;
							isLandedStrata BOOLEAN := FALSE;
							noPetak et_dmsa.BORANG2_INDEKS_DETAIL.PETAK%TYPE;
							unitLuasPetak NUMBER(19,0);
							luasPetak et_dmsa.BORANG2_INDEKS_DETAIL.LUAS_PETAK%TYPE;
              kegunaanKod VARCHAR2(255);
              kegunaanId NUMBER(19,0);
              catatan VARCHAR2(255);
						/* indeks detail block */
						BEGIN
   
              IF B2ID.KEGUNAAN IS NOT NULL THEN
                SELECT KOD INTO kegunaanKod 
                FROM et_dmsa.RJK_MAKSUD_BORANG2 WHERE MAKSUD_BORANG2_ID = B2ID.KEGUNAAN;
                
                kegunaanId := getSakIdByDmsaSakKod(kegunaanKod, 'B2ID.KEGUNAAN','SUB_KGUNAAN_TNH_KC');
                
                SELECT NAMA INTO catatan
                FROM RJK_SENARAI_AHLI_KUMPULAN WHERE SENARAI_AHLI_KUMPULAN_ID = kegunaanId;
                
              ELSE 
                kegunaanId := NULL;
                catatan := NULL;
              END IF;
              
							unitLuasPetak := getSakIdByDmsaSakId(B2ID.UNIT_LUAS, 'B2ID.UNIT_LUAS','UNIT_LUAS');
							luasPetak := B2ID.LUAS_PETAK;
							IF luasPetak IS NULL THEN
								luasPetak := 0;
							END IF;
							
							noPetak := replace(trim(upper(B2ID.PETAK)), '	');
							
							IF noPetak LIKE 'L%' OR noPetak LIKE 'l%' OR noPetak LIKE 'pl%' OR
							noPetak LIKE 'PL%' OR noPetak LIKE 'pL%' OR noPetak LIKE 'Pl%' THEN
								isLandedStrata := TRUE;
							ELSIF noPetak LIKE 'P%' OR noPetak LIKE 'p%' THEN
								isBlokSementara := TRUE;
							END IF;
							DBMS_OUTPUT.put_line('isLandedStrata:' || CASE WHEN isLandedStrata THEN 'Y' ELSE 'N'END
							|| ' isBlokSementara:' || CASE WHEN isBlokSementara THEN 'Y' ELSE 'N' END
							|| ' noBangunan:' || noBangunan || ',noTingkat:' || noTingkat || ',noPetak:' || noPetak);
							
							DECLARE
								hakmilikIdBorang4 NUMBER(19,0);
								indeksTerperinciId NUMBER(19,0);
                versiDhdBorang4 NUMBER(19,0);
							/* block to insert ind_strata_IDX_TERPRNC, update IND_MKLMT_HKMLK */
							BEGIN
								DECLARE
									errMsgFindBorang4 VARCHAR2(250);
								/* block to find IND_HKMLK borang 4 based on noBangunan, noTingkat, noPetak */
								BEGIN
									IF noBangunan IS NULL AND noTingkat IS NULL THEN
--									SELECT HKMLK_ID INTO hakmilikIdBorang4 FROM IND_HKMLK WHERE NO_BANGUNAN IS NULL
--										AND NO_TINGKAT IS NULL AND NO_PETAK = noPetak AND STRATA_INDUK_ID = hakmilikId;
                    
                    SELECT a.HKMLK_ID, b.VERSI_DHD INTO hakmilikIdBorang4, versiDhdBorang4
                    FROM IND_HKMLK a, IND_VERSI_DHD b WHERE 
                    a.HKMLK_ID = b.HKMLK_ID AND a.NO_BANGUNAN IS NULL
										AND a.NO_TINGKAT IS NULL AND a.NO_PTK = noPetak AND a.STRATA_INDUK_ID = hakmilikId
                    AND b.FLAG_AKTIF = 'Y';
                    
									ELSIF noTingkat IS NULL AND noPetak IS NULL THEN
--										SELECT HKMLK_ID INTO hakmilikIdBorang4 FROM IND_HKMLK WHERE NO_BANGUNAN = noBangunan
--										AND NO_TINGKAT IS NULL AND NO_PETAK IS NULL AND STRATA_INDUK_ID = hakmilikId;
                    
                    SELECT a.HKMLK_ID, b.VERSI_DHD INTO hakmilikIdBorang4, versiDhdBorang4
                    FROM IND_HKMLK a, IND_VERSI_DHD b WHERE 
                    a.HKMLK_ID = b.HKMLK_ID AND a.NO_BANGUNAN = noBangunan
                    AND a.NO_TINGKAT IS NULL AND a.NO_PTK IS NULL AND a.STRATA_INDUK_ID = hakmilikId
                    AND b.FLAG_AKTIF = 'Y';
                    
                  ELSE 
--										SELECT HKMLK_ID INTO hakmilikIdBorang4 FROM IND_HKMLK WHERE NO_BANGUNAN = noBangunan
--										AND NO_TINGKAT = noTingkat AND NO_PETAK = noPetak AND STRATA_INDUK_ID = hakmilikId;
                    
                    SELECT a.HKMLK_ID, b.VERSI_DHD INTO hakmilikIdBorang4, versiDhdBorang4
                    FROM IND_HKMLK a, IND_VERSI_DHD b WHERE 
                    a.HKMLK_ID = b.HKMLK_ID AND a.NO_BANGUNAN = noBangunan
                    AND a.NO_TINGKAT = noTingkat AND a.NO_PTK = noPetak AND a.STRATA_INDUK_ID = hakmilikId
                    AND b.FLAG_AKTIF = 'Y';
                    
									END IF;
								EXCEPTION
									WHEN OTHERS THEN
										errMsgFindBorang4 := 'Error finding hakmilik borang 4 for where column values:' ||
										'NO_BANGUNAN=' || noBangunan || ' NO_TINGKAT=' || noTingkat || ' NO_PETAK=' || noPetak || ' STRATA_INDUK_ID='
										|| hakmilikId || ' ' || SQLERRM;
										DBMS_OUTPUT.put_line(errMsgFindBorang4);
								/* end block to find IND_HKMLK borang 4 based on noBangunan, noTingkat, noPetak */
								END;
								
								DECLARE
									errMsgIndeksTprnc VARCHAR2(250);
									noBangunan_idx et_dmsa.BORANG2_INDEKS_HEADER.NO_BANGUNAN%TYPE;
									noPetak_idx et_dmsa.BORANG2_INDEKS_DETAIL.PETAK%TYPE;
--									kegunaanPetak NUMBER(19,0);
								/* insert ind_strata_IDX_TERPRNC */
								BEGIN
--									kegunaanPetak := getSakIdByDmsaSakId(B2ID.KEGUNAAN, 'B2ID.KEGUNAAN','SUB_KGUNAAN_TNH_KC');
								
									IF isBlokSementara THEN
										noBangunan_idx := noPetak;
										noPetak_idx := NULL;
									ELSE
										noBangunan_idx := noBangunan;
										noPetak_idx := noPetak;
									END IF;
									
									INSERT INTO ind_BTRN_strata_IDX(BTRN_STRATA_IDX_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
																	VERSION, NO_BANGUNAN, NO_TINGKAT, NO_PELAN, NO_PTK,
																	HKMLK_ID, IDX_MULA, IDX_AKHIR_ID, UNIT_SYER, NO_MUKA_SRT,
																	LUAS, UNIT_LUAS_ID, KEGUNAAN_ID, CATATAN)
										VALUES (SEQ_BTRN_STRATA_IDX.NEXTVAL, username, sysdate, username, sysdate,
												0, noBangunan_idx, noTingkat, noPelan, noPetak_idx,
												hakmilikIdBorang4, indeksVersiId, indeksVersiId, B2ID.UNIT_SYER, ' ',
												B2ID.LUAS_PETAK, unitLuasPetak, kegunaanId, catatan);
									indeksTerperinciId := SEQ_BTRN_STRATA_IDX.CURRVAL;
									DBMS_OUTPUT.put_line('complete ind_strata_IDX_TERPRNC noBangunan_idx:' || noBangunan_idx || ' noPetak_idx:' || noPetak_idx);
								EXCEPTION
									WHEN OTHERS THEN
										errMsgIndeksTprnc := 'ind_strata_IDX_TERPRNC noBangunan_idx:' || noBangunan_idx || ',noTingkat:'|| noTingkat 
															|| ',noPetak_idx:' || noPetak_idx ||' B2ASAS ID:' || B2ASAS.BORANG2_ASAS_ID || ' B2IHEADER ID:' 
															|| B2IH.BORANG2_INDEKS_HEADER_ID || ' ' ||SQLERRM;
										DBMS_OUTPUT.put_line(errMsgIndeksTprnc);
										
										msgNotifyUser := msgNotifyUser || ' ***** No bangunan / no tingkat / no petak melebihi 5 characters dalam Indeks Secara Detail (DMSA). ' || SQLERRM;
								/* end insert ind_strata_IDX_TERPRNC */
								END;
								
								IF  versiDhdBorang4 = 0 AND hakmilikIdBorang4 IS NOT NULL THEN 
									DECLARE
										errMsgUpdateMklmtHkmlk VARCHAR2(250);
									/* block to update IND_MKLMT_HKMLK */
									BEGIN
										UPDATE IND_MKLMT_HKMLK SET LUAS = B2ID.LUAS_PETAK, UNIT_LUAS_ID = unitLuasPetak
										WHERE MKLMT_HKMLK_ID = (SELECT MKLMT_HKMLK_ID FROM IND_VERSI_DHD WHERE HKMLK_ID = hakmilikIdBorang4);
									EXCEPTION
										WHEN OTHERS THEN
											errMsgUpdateMklmtHkmlk := 'Error update IND_MKLMT_HKMLK where HKMLK_ID(borang4)=' || hakmilikIdBorang4 
																	|| 'INDEKS_TERPERINCI_ID='|| indeksTerperinciId || ' ' ||SQLERRM;
											DBMS_OUTPUT.put_line(errMsgUpdateMklmtHkmlk);
									/* end block to update IND_MKLMT_HKMLK */
									END;
								END IF;
							/* end block to insert ind_strata_IDX_TERPRNC, update IND_MKLMT_HKMLK */
							END;
							
							IF isBlokSementara THEN
								DECLARE
									tableName VARCHAR2(50);
									errMsgBlokSmntara VARCHAR2(250);
									menaraId NUMBER(19,0);
									tingkatId NUMBER(19,0);
									namaMenara VARCHAR2(10);
								/* STR_I_BLOK_SEMENTARA */
								BEGIN
									IF noBangunan IS NOT NULL THEN
										RAISE blokSmntaraWNoBgnn;
									END IF;
									
									tingkatId := NULL;
									menaraId := NULL;
									IF noTingkat IS NOT NULL THEN
										SELECT CASE WHEN COUNT(*) > 0 THEN '|' ELSE 'NA' END INTO namaMenara 
										FROM STR_I_BLOK_SMTR WHERE FLAG_PTK_TNH = 'N' AND MKLMT_STRATA_ID = maklumatStrataId 
										AND TINGKAT_ID IS NOT NULL AND NAMA LIKE noPetak;
										
										tableName := 'STR_I_MENARA';
										INSERT INTO STR_I_MENARA(MENARA_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
																VERSION, NAMA)
											VALUES(SEQ_MENARA.NEXTVAL, username, SYSDATE, username, SYSDATE,
													0, namaMenara);
										menaraId := SEQ_MENARA.CURRVAL;
										
										tableName := 'STR_I_TINGKAT';
										INSERT INTO STR_I_TINGKAT(TINGKAT_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
																	VERSION, NAMA, NO_TINGKAT, MENARA_ID)
											VALUES(SEQ_TINGKAT.NEXTVAL, username, SYSDATE, username, SYSDATE,
													0, noTingkat, 0, menaraId);
										tingkatId := SEQ_TINGKAT.CURRVAL;
									END IF;
									
									tableName := 'STR_I_BLOK_SEMENTARA';
									INSERT INTO STR_I_BLOK_SMTR(BLOK_SMTR_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
																		VERSION, NAMA, BIL_PTK, JNS_PEMBANGUNAN, IND_PERMOHONAN_PPHSYB,
																		JUMLAH_DEPOSIT, TRKH_JANGKA_SIAP, UNIT_SYER_MUKTAMAD, UNIT_SYER_SISTEM, UNIT_SYER,
																		MKLMT_STRATA_ID, TINGKAT_ID, MENARA_ID, JUMLAH_PTK_AKSESORI, LUAS,
                                    JUMLAH_LUAS, LUAS_PTK_AKSESORI, KEGUNAAN_ID)
											VALUES(SEQ_BLOK_SMTR.NEXTVAL, username, SYSDATE, username, SYSDATE,
											0, noPetak, 0, 'NA', 'N', 
											0, NULL, B2ID.UNIT_SYER, B2ID.UNIT_SYER, B2ID.UNIT_SYER,
											maklumatStrataId, tingkatId, menaraId, 0, B2ID.LUAS_PETAK,
                      0, 0, kegunaanId);
									DBMS_OUTPUT.put_line('blok sementara complete tingkatId:' || tingkatId || ' menaraId:' || menaraId);
								EXCEPTION
									WHEN blokSmntaraWNoBgnn THEN
										errMsgBlokSmntara := 'isBlokSementara:Y noBangunan IS NOT NULL(noBangunan:'||noBangunan||',noTingkat:'||noTingkat
															||',noPetak:'||noPetak||') B2ASAS ID:' || B2ASAS.BORANG2_ASAS_ID || ' B2IHEADER ID:' 
															|| B2IH.BORANG2_INDEKS_HEADER_ID;
										DBMS_OUTPUT.put_line(errMsgBlokSmntara);
										
									WHEN OTHERS THEN
										errMsgBlokSmntara := tableName || ' isBlokSementara:Y B2ASAS ID:' || B2ASAS.BORANG2_ASAS_ID || ' B2IHEADER ID:' ||
														B2IH.BORANG2_INDEKS_HEADER_ID || SQLERRM;
										DBMS_OUTPUT.put_line(errMsgBlokSmntara);
								/* end STR_I_BLOK_SEMENTARA */
								END;
								CONTINUE;
							END IF;
							
							IF isLandedStrata THEN
								DECLARE
								tableName VARCHAR2(50);
								errMsgLanded VARCHAR2(250);
								/* STR_I_PETAK for landed strata*/
								BEGIN
									IF noBangunan IS NOT NULL THEN
										RAISE landedStrataWNoBgnn;
									END IF;
									IF noTingkat IS NOT NULL THEN
										RAISE landedStrataWNoTingkat;
									END IF;
									
									IF noPetak LIKE 'P%' OR noPetak LIKE 'p%' THEN
										tableName := 'STR_I_BLOK_SEMENTARA';
										INSERT INTO STR_I_BLOK_SMTR(BLOK_SMTR_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
																		VERSION, NAMA, BIL_PTK, JNS_PEMBANGUNAN, IND_PERMOHONAN_PPHSYB,
																		JUMLAH_DEPOSIT, TRKH_JANGKA_SIAP, UNIT_SYER_MUKTAMAD, UNIT_SYER_SISTEM, UNIT_SYER,
																		MKLMT_STRATA_ID, FLAG_PTK_TNH, JUMLAH_PTK_AKSESORI, LUAS,
                                    JUMLAH_LUAS, LUAS_PTK_AKSESORI, KEGUNAAN_ID)
											VALUES(SEQ_BLOK_SMTR.NEXTVAL, username, SYSDATE, username, SYSDATE,
											0, noPetak, 0, 'NA', 'N', 
											0, sysdate,  B2ID.UNIT_SYER, B2ID.UNIT_SYER, B2ID.UNIT_SYER,
											maklumatStrataId, 'Y', 0, B2ID.LUAS_PETAK,
                      0, 0, kegunaanId);
										DBMS_OUTPUT.put_line('landed petak sementara complete.');
									ELSE 
										tableName := 'STR_I_PETAK';
										INSERT INTO STR_I_PTK(PTK_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
																VERSION, NAMA, UNIT_SYER, UNIT_SYER_MUKTAMAD, UNIT_SYER_SISTEM,
																NO_PTK, JNS_KEGUNAAN, JNS_PEMBANGUNAN, LUAS, MKLMT_STRATA_ID,
																BANGUNAN_ID, MENARA_ID, TINGKAT_ID, FLAG_PTK_TNH, LUAS_SETIAP_TINGKAT,
																AX08, JADUAL_PTK, KEGUNAAN_ID)
											VALUES(SEQ_PTK.NEXTVAL, username, SYSDATE, username, SYSDATE,
													0, noPetak, B2ID.UNIT_SYER, B2ID.UNIT_SYER, B2ID.UNIT_SYER,
													0, 'NA', 'NA', luasPetak, maklumatStrataId,
													NULL, NULL, NULL, 'Y', 0,
													0, 0, kegunaanId);
										DBMS_OUTPUT.put_line('landed petak complete.');
									END IF;
								EXCEPTION
									WHEN landedStrataWNoBgnn THEN
										errMsgLanded := 'isLandedStrata:Y noBangunan IS NOT NULL(noBangunan:'||noBangunan||',noTingkat:'
														||noTingkat||',noPetak:'||noPetak||')B2ASAS ID:' || B2ASAS.BORANG2_ASAS_ID 
														||' B2IHEADER ID:'|| B2IH.BORANG2_INDEKS_HEADER_ID;
										DBMS_OUTPUT.put_line(errMsgLanded);
										
									WHEN landedStrataWNoTingkat THEN
										errMsgLanded := 'isLandedStrata:Y noTingkat IS NOT NULL(noBangunan:'||noBangunan||',noTingkat:'
														||noTingkat||',noPetak:'||noPetak||')B2ASAS ID:' || B2ASAS.BORANG2_ASAS_ID 
														|| ' B2IHEADER ID:' || B2IH.BORANG2_INDEKS_HEADER_ID;
										DBMS_OUTPUT.put_line(errMsgLanded);
										
									WHEN OTHERS THEN
										errMsgLanded := tableName || ' isLandedStrata:Y B2ASAS ID:' || B2ASAS.BORANG2_ASAS_ID 
														|| ' B2IHEADER ID:' || B2IH.BORANG2_INDEKS_HEADER_ID || SQLERRM;
										DBMS_OUTPUT.put_line(errMsgLanded);
								/* end STR_I_PETAK for landed strata */
								END;
								CONTINUE;
							END IF;
							
							DECLARE
								errMsgBgnTingPetak VARCHAR2(250);
								tableName VARCHAR2(50);
								bangunanId NUMBER(19,0);
								menaraId NUMBER(19,0);
								tingkatId NUMBER(19,0);
							/* block for non landed strata and non blok sementara */
							BEGIN
								IF noBangunan IS NULL THEN
									raise noNoBangunan;
								END IF;
								IF noTingkat IS NULL THEN
									raise noNoTingkat;
								END IF;
								IF noPetak IS NULL THEN
									raise noNoPetak;
								END IF;
								bangunanId := findBgnIdByNamaAndMklmtStrId(noBangunan, maklumatStrataId);
								menaraId := findMenaraIdByBangunanId(bangunanId);
								tingkatId := findTingIdByNamaAndBgnId(noTingkat, bangunanId);
								
								IF bangunanId IS NULL THEN
									tableName := 'STR_I_BANGUNAN';
									INSERT INTO STR_I_BANGUNAN(BANGUNAN_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
																VERSION, NAMA, JUMLAH_BLOK_SMTR, JUMLAH_SYER, FLAG_MENARA, 
																FLAG_BLOK_SMTR, MKLMT_STRATA_ID)
										VALUES(SEQ_BANGUNAN.NEXTVAL, username, SYSDATE, username, SYSDATE,
												0, noBangunan, 0, 0, 'Y',
												'N', maklumatStrataId);
									bangunanId := SEQ_BANGUNAN.CURRVAL;
									
									tableName := 'STR_I_MENARA';
									INSERT INTO STR_I_MENARA(MENARA_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
															VERSION, NAMA, BANGUNAN_ID)
										VALUES(SEQ_MENARA.NEXTVAL, username, SYSDATE, username, SYSDATE,
												0, 'NA', bangunanId);
									menaraId := SEQ_MENARA.CURRVAL;
								END IF;
								
								IF tingkatId IS NULL THEN
									tableName := 'STR_I_TINGKAT';
									INSERT INTO STR_I_TINGKAT(TINGKAT_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
															VERSION, NAMA, NO_TINGKAT, MENARA_ID)
										VALUES(SEQ_TINGKAT.NEXTVAL, username, SYSDATE, username, SYSDATE,
												0, noTingkat, 0, menaraId);
									tingkatId := SEQ_TINGKAT.CURRVAL;
								END IF;
								DBMS_OUTPUT.put_line('bangunanId:'||bangunanId||' tingkatId:'||tingkatId|| ' menaraId:' || menaraId 
								||' maklumatStrataId:'||maklumatStrataId);

								tableName := 'STR_I_PETAK';
								INSERT INTO STR_I_PTK(PTK_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
														VERSION, NAMA, UNIT_SYER, UNIT_SYER_MUKTAMAD, UNIT_SYER_SISTEM,
														NO_PTK, JNS_KEGUNAAN, JNS_PEMBANGUNAN, LUAS, MKLMT_STRATA_ID,
														BANGUNAN_ID, MENARA_ID, TINGKAT_ID, LUAS_SETIAP_TINGKAT, AXF1XF2,
														JADUAL_PTK, KEGUNAAN_ID)
									VALUES(SEQ_PTK.NEXTVAL, username, SYSDATE, username, SYSDATE,
											0, noPetak, B2ID.UNIT_SYER, B2ID.UNIT_SYER, B2ID.UNIT_SYER,
											0, 'NA', 'NA', luasPetak, maklumatStrataId,
											bangunanId, menaraId, tingkatId, 0, 0,
											0, kegunaanId);
								DBMS_OUTPUT.put_line('normal petak complete for petak ' || noPetak );
							EXCEPTION
								WHEN noNoPetak THEN
									errMsgBgnTingPetak := 'isLandedStrata:N isBlokSementara:N NoPetak IS NULL(noBangunan:'||noBangunan
														||',noTingkat:'||noTingkat||',noPetak:'||noPetak||') B2ASAS ID:'
														|| B2ASAS.BORANG2_ASAS_ID || ' B2IHEADER ID:'|| B2IH.BORANG2_INDEKS_HEADER_ID;
									DBMS_OUTPUT.put_line(errMsgBgnTingPetak);
								
								WHEN noNoBangunan THEN
									errMsgBgnTingPetak := 'isLandedStrata:N isBlokSementara:N NoBangunan IS NULL(noBangunan:'||noBangunan
														||',noTingkat:'||noTingkat||',noPetak:'||noPetak||') B2ASAS ID:'
														|| B2ASAS.BORANG2_ASAS_ID || ' B2IHEADER ID:'|| B2IH.BORANG2_INDEKS_HEADER_ID;
									DBMS_OUTPUT.put_line(errMsgBgnTingPetak);
								
								WHEN noNoTingkat THEN
									errMsgBgnTingPetak := 'isLandedStrata:N isBlokSementara:N NoTingkat IS NULL(noBangunan:'||noBangunan
														||',noTingkat:'||noTingkat||',noPetak:'||noPetak||') B2ASAS ID:'
														|| B2ASAS.BORANG2_ASAS_ID || ' B2IHEADER ID:'|| B2IH.BORANG2_INDEKS_HEADER_ID;
									DBMS_OUTPUT.put_line(errMsgBgnTingPetak);
									
								WHEN OTHERS THEN
									errMsgBgnTingPetak := tableName || ' isLandedStrata:N isBlokSementara:N B2ASAS ID:'
														|| B2ASAS.BORANG2_ASAS_ID || ' B2IHEADER ID:'|| B2IH.BORANG2_INDEKS_HEADER_ID || SQLERRM;
									DBMS_OUTPUT.put_line(errMsgBgnTingPetak);
							/* end block for non landed strata and non blok sementara */
							END;
						/* end indeks detail block */
						END;
					/* end indeks detail loop */
					END LOOP;
					
					IF countDetail = 0 THEN
						raise noIndeksDetail;
					END IF;
					DBMS_OUTPUT.put_line(' ');
					
				EXCEPTION
					WHEN noIndeksDetail THEN
						errMsgIndeks := 'There are 0 Indeks_Detail B2ASAS ID:' || B2ASAS.BORANG2_ASAS_ID || ' B2IHEADER ID:' ||
						B2IH.BORANG2_INDEKS_HEADER_ID || ' noBangunan:' || noBangunan || ' noTingkat:' || noTingkat || ' noFolioPelan:' ||
						noPelan || ' jumlahSyer:' || B2IH.JUMLAH_SYER;
						DBMS_OUTPUT.put_line(errMsgIndeks);
					
					WHEN OTHERS THEN
						errMsgIndeks := 'ERROR IN INDEKS HEADER LOOP B2ASAS ID:' || B2ASAS.BORANG2_ASAS_ID || ' B2IHEADER ID:' ||
						B2IH.BORANG2_INDEKS_HEADER_ID || SQLERRM;
						DBMS_OUTPUT.put_line(errMsgIndeks);
				/* end indeks header block */
				END;
			/* end indeks header loop */
			END LOOP;
		/* end indeks block */
		END;
		
		DECLARE
			CURSOR C_B2RINGKASAN IS 
				SELECT * FROM et_dmsa.BORANG2_RINGKASAN_HEADER WHERE BORANG2_ASAS_ID = B2ASAS.BORANG2_ASAS_ID;
		/* ringkasan block */
		BEGIN
			/* ringkasan header loop */
			FOR B2RH IN C_B2RINGKASAN LOOP
				DECLARE
					CURSOR C_B2RINGKASAN_DET IS 
						SELECT * FROM et_dmsa.BORANG2_RINGKASAN_DETAIL WHERE BORANG2_RINGKASAN_HEADER_ID = B2RH.BORANG2_RINGKASAN_HEADER_ID;
						
					noPetak et_dmsa.BORANG2_RINGKASAN_HEADER.NO_PETAK%TYPE;
					maksud et_dmsa.RJK_MAKSUD_BORANG2.NAMA%TYPE;
					jenisStrataId NUMBER(19,0);
				/* ringkasan detail block */
				BEGIN
					noPetak := replace(trim(B2RH.NO_PETAK), '	');
					jenisStrataId := getSakIdByDmsaSakId(B2RH.KATEGORI_BANGUNAN, 'B2RH.KATEGORI_BANGUNAN','JNS_STRATA');
					
					IF B2RH.MAKSUD_ID IS NOT NULL THEN
						SELECT NAMA INTO maksud 
						FROM et_dmsa.RJK_MAKSUD_BORANG2 WHERE MAKSUD_BORANG2_ID = B2RH.MAKSUD_ID;
					ELSE 
						maksud := NULL;
					END IF;
					
					/* ringkasan detail loop */
					FOR B2RD IN C_B2RINGKASAN_DET LOOP
						DECLARE
							errMsgRingkasan VARCHAR2(250);
						/* ind_strata_IDX_RINGKASAN */
						BEGIN
							INSERT INTO ind_strata_IDX_RINGKASAN(STRATA_IDX_RINGKASAN_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
															VERSION, MAKSUD, NAMA, NO_PTK, UNIT_SYER,
															JNS_STRATA_ID, IDX_AKHIR_ID, IDX_MULA)
								VALUES(SEQ_STRATA_IDX_RINGKASAN.NEXTVAL, username, sysdate, username, sysdate,
										0, maksud, trim(B2RD.SENARAI_PETAK_BLOK), noPetak, B2RH.UNIT_SYER,
										jenisStrataId, indeksVersiId, indeksVersiId);
							DBMS_OUTPUT.put_line('ind_strata_IDX_RINGKASAN inserted');
						EXCEPTION
							WHEN OTHERS THEN
								errMsgRingkasan := 'ind_strata_IDX_RINGKASAN noPetak:'|| noPetak ||' kategoriBangunan:' || B2RH.KATEGORI_BANGUNAN 
													||' B2ASAS ID:' || B2ASAS.BORANG2_ASAS_ID ||' B2RHEADER ID:' || B2RH.BORANG2_RINGKASAN_HEADER_ID 
													|| ' ' || SQLERRM;
								DBMS_OUTPUT.put_line(errMsgRingkasan);
								
								msgNotifyUser := msgNotifyUser || ' ***** Sila pasti Kategori / Senarai Petak / No Petak / Unit Syer diisi dalam Ringkasan Kandungan (DMSA). ' || SQLERRM;
						/* ind_strata_IDX_RINGKASAN */
						END;
					/* end ringkasan detail loop */
					END LOOP;
				/* end ringkasan detail block */
				END;
			/* end ringkasan header loop */
			END LOOP;
		/* end ringkasan block */
		END;
		
		DECLARE
			CURSOR C_B2PETAKS IS 
				SELECT * FROM et_dmsa.BORANG2_PETAK_AKSESORI WHERE BORANG2_ASAS_ID = B2ASAS.BORANG2_ASAS_ID AND PETAK_AKSESORI IS NOT NULL
				ORDER BY BORANG2_PETAK_AKSESORI_ID;
		/* petak aksesori block */
		BEGIN
			/* loop for petak aksesori */
			FOR B2PA IN C_B2PETAKS LOOP
				DECLARE
					errMsgPetakAks VARCHAR2(250);
					noBangunan VARCHAR2(50);
					noTingkat VARCHAR2(50);
					noPetak VARCHAR2(50);
					part1 VARCHAR2(50);
					part2 VARCHAR2(50);
					part3 VARCHAR2(50);
					petakBersangkutan et_dmsa.BORANG2_PETAK_AKSESORI.PETAK_YANG_BERSANGKUTAN%TYPE;
--					countPetak NUMBER;
--					petakId NUMBER(19,0);
					indeksTerperinciId NUMBER(19,0);
					unitLuasPetakAksesori NUMBER(19,0);
					luasPetakAksesori NUMBER(16,4);
				
				BEGIN
					unitLuasPetakAksesori := getSakIdByDmsaSakId(B2PA.UNIT_LUAS, 'B2PA.UNIT_LUAS','UNIT_LUAS');
					luasPetakAksesori := B2PA.LUAS_PETAK;
					IF luasPetakAksesori IS NULL THEN
						luasPetakAksesori := 0;
					END IF;

					petakBersangkutan := REPLACE(TRIM(B2PA.PETAK_YANG_BERSANGKUTAN), '	');
					IF INSTR(petakBersangkutan, '/') = 0 THEN
						part1 := petakBersangkutan;
						petakBersangkutan := NULL;
					ELSE 
						part1 := TRIM(SUBSTR(petakBersangkutan, 1, INSTR(petakBersangkutan,'/') - 1));
						petakBersangkutan := TRIM(SUBSTR(petakBersangkutan, INSTR(petakBersangkutan,'/') + 1, LENGTH(petakBersangkutan)));
					END IF;
					IF INSTR(petakBersangkutan, '/') = 0 THEN
						part2 := petakBersangkutan;
						petakBersangkutan := NULL;
					ELSE 
						part2 := SUBSTR(petakBersangkutan, 1, INSTR(petakBersangkutan,'/') - 1);
						petakBersangkutan := TRIM(SUBSTR(petakBersangkutan, INSTR(petakBersangkutan,'/') + 1, LENGTH(petakBersangkutan)));
					END IF;
					part3 := petakBersangkutan;
					
					IF part1 IS NULL THEN
						noPetak := NULL;
						noTingkat := NULL;
						noBangunan := NULL;
					ELSIF part2 IS NULL THEN
						noPetak := part1;
						noTingkat := NULL;
						noBangunan := NULL;
					ELSIF part3 IS NULL THEN
						noPetak := part2;
						noTingkat := part1;
						noBangunan := NULL;
					ELSE
						noPetak := part3;
						noTingkat := part2;
						noBangunan := part1;
					END IF;
					DBMS_OUTPUT.put_line('Original Petak Bersangkutan:' || B2PA.PETAK_YANG_BERSANGKUTAN || ' to ' || noBangunan || ','
					|| noTingkat || ',' || noPetak);
					
					/* ind_strata_IDX_PETAK_AKSESORI*/
					DECLARE
						lokasiPetakAksesori et_main.IND_STRata_IDX_PTK_AKSESORI.LOKASI%TYPE;
						lokasiBangunan et_dmsa.BORANG2_PETAK_AKSESORI.LOKASI_NO_BANGUNAN%TYPE;
						lokasiTingkat et_dmsa.BORANG2_PETAK_AKSESORI.LOKASI_NO_TINGKAT%TYPE;
						lokasiPetak et_dmsa.BORANG2_PETAK_AKSESORI.LOKASI_NO_PETAK%TYPE;
--						tujuanPetakAksesori NUMBER(19,0);
					BEGIN
--						tujuanPetakAksesori := getSakIdByDmsaSakId(B2PA.TUJUAN, 'B2PA.TUJUAN','SUB_KGUNAAN_TNH_KC');
					
						lokasiBangunan := TRIM(B2PA.LOKASI_NO_BANGUNAN);
						lokasiTingkat := TRIM(B2PA.LOKASI_NO_TINGKAT);
						lokasiPetak := TRIM(B2PA.LOKASI_NO_PETAK);
					
						IF lokasiBangunan IS NOT NULL THEN
							lokasiPetakAksesori := lokasiBangunan;
						END IF;
						IF lokasiTingkat IS NOT NULL THEN
							lokasiPetakAksesori := lokasiPetakAksesori || '/' || lokasiTingkat;
						END IF;
						IF lokasiPetak IS NOT NULL THEN
							lokasiPetakAksesori := lokasiPetakAksesori || '/' || lokasiPetak;
						END IF;
						DBMS_OUTPUT.put_line(lokasiPetakAksesori);
						
						DBMS_OUTPUT.put_line('DEBUGGING PTAK AKSESORI');
						
						BEGIN
							IF noBangunan IS NULL AND noTingkat IS NULL THEN
								SELECT BTRN_STRATA_IDX_ID INTO indeksTerperinciId FROM ind_BTRN_strata_IDX 
								WHERE NO_BANGUNAN IS NULL AND NO_TINGKAT IS NULL AND NO_PTK = noPetak  AND IDX_AKHIR_ID = indeksVersiId;
								
								DBMS_OUTPUT.put_line('DEBUGGING PTAK AKSESORI option 1');
								
							ELSIF noTingkat IS NULL AND noPetak IS NULL THEN
								SELECT BTRN_STRATA_IDX_ID INTO indeksTerperinciId FROM ind_BTRN_strata_IDX 
								WHERE NO_BANGUNAN  = noBangunan AND NO_TINGKAT IS NULL AND NO_PTK IS NULL AND IDX_AKHIR_ID = indeksVersiId;
								DBMS_OUTPUT.put_line('DEBUGGING PTAK AKSESORI option 12');
							ELSE
								SELECT BTRN_STRATA_IDX_ID INTO indeksTerperinciId FROM ind_BTRN_strata_IDX 
								WHERE NO_BANGUNAN = noBangunan AND NO_TINGKAT = noTingkat AND NO_PTK = noPetak  AND IDX_AKHIR_ID = indeksVersiId;
								DBMS_OUTPUT.put_line('DEBUGGING PTAK AKSESORI option 3');
							END IF;
						EXCEPTION
							WHEN OTHERS THEN
								errMsgPetakAks := 'ind_strata_IDX_PETAK_AKSESORI B2ASAS ID:' || B2ASAS.BORANG2_ASAS_ID || ' petakAksesori: ' || B2PA.PETAK_AKSESORI || ' ' 
													|| ' petakBersangkutan: ' || B2PA.PETAK_YANG_BERSANGKUTAN || ' indeksVersiId:' || indeksVersiId 
													|| ' ' || SQLERRM;
								DBMS_OUTPUT.put_line(errMsgPetakAks);
						END;
						
						DBMS_OUTPUT.put_line('nilai indeksTerperinciId:' || indeksTerperinciId || ' berdasaarkan id :' || B2PA.borang2_petak_aksesori_id);
						
					
						INSERT INTO ind_strata_IDX_PTK_AKSESORI(STRATA_IDX_PTK_AKSESORI_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
														VERSION, NAMA, LOKASI,
														IDX_MULA, IDX_AKHIR_ID, BTRN_STRATA_IDX_ID,
														LUAS, UNIT_LUAS_ID)
						VALUES (SEQ_STRATA_IDX_PTK_AKSESORI.NEXTVAL, username, sysdate, username, sysdate,
								0, trim(B2PA.PETAK_AKSESORI), lokasiPetakAksesori,
								indeksVersiId, indeksVersiId, indeksTerperinciId,
								B2PA.LUAS_PETAK, unitLuasPetakAksesori);
						DBMS_OUTPUT.put_line('ind_strata_IDX_PETAK_AKSESORI inserted');
						
						IF indeksTerperinciId IS NOT NULL THEN
							DECLARE
								errMsgFindBorang4 VARCHAR2(250);
								hakmilikIdBorang4 NUMBER(19,0);
                versiDhdBorang4 NUMBER(19,0);
							/* block to find IND_HKMLK borang 4 based on indeksTerperinciId*/
							BEGIN
								SELECT HKMLK_ID INTO hakmilikIdBorang4 FROM ind_BTRN_strata_IDX WHERE BTRN_STRATA_IDX_ID = indeksTerperinciId;
                
                SELECT b.VERSI_DHD INTO versiDhdBorang4
                FROM IND_HKMLK a, IND_VERSI_DHD b 
                WHERE a.HKMLK_ID = b.HKMLK_ID 
                AND a.HKMLK_ID = hakmilikIdBorang4
                AND b.FLAG_AKTIF = 'Y';
                	
								IF versiDhdBorang4 = 0 AND hakmilikIdBorang4 IS NOT NULL THEN 
									DECLARE
										errMsgUpdateStrPetakAksesori VARCHAR2(250);
									/* block to update ind_strata_PETAK_AKSESORI */
									BEGIN
										UPDATE ind_strata_PTK_AKSESORI SET LUAS = B2PA.LUAS_PETAK, UNIT_LUAS_ID = unitLuasPetakAksesori
										WHERE HKMLK_ID = hakmilikIdBorang4 AND NAMA = trim(B2PA.PETAK_AKSESORI);
									EXCEPTION
										WHEN OTHERS THEN
											errMsgUpdateStrPetakAksesori := 'Error update ind_strata_PETAK_AKSESORI where HKMLK_ID(borang4)=' || hakmilikIdBorang4 
																	|| 'INDEKS_TERPERINCI_ID='|| indeksTerperinciId || ' ' ||SQLERRM;
											DBMS_OUTPUT.put_line(errMsgUpdateStrPetakAksesori);
									/* end block to update ind_strata_PETAK_AKSESORI */
									END;
								END IF;
							
							EXCEPTION
								WHEN OTHERS THEN
									errMsgFindBorang4 := 'Error finding hakmilik borang 4 for ind_strata_IDX_PETAK_AKSESORI where STR_IDX_TERPRNC_ID = ' || indeksTerperinciId || ' ' || SQLERRM;
									DBMS_OUTPUT.put_line(errMsgFindBorang4);
							/* end block to find IND_HKMLK borang 4 based on noBangunan, noTingkat, noPetak */
							END;
						END IF;
					EXCEPTION
						WHEN OTHERS THEN
							errMsgPetakAks := 'ind_strata_IDX_PETAK_AKSESORI B2ASAS ID:' || B2ASAS.BORANG2_ASAS_ID || ' petakAksesori: ' || B2PA.PETAK_AKSESORI || ' ' 
												|| ' petakBersangkutan: ' || B2PA.PETAK_YANG_BERSANGKUTAN || ' '|| SQLERRM;
							DBMS_OUTPUT.put_line(errMsgPetakAks);
							
							msgNotifyUser := msgNotifyUser || ' ***** ' || errMsgPetakAks;
					/* end insert ind_strata_IDX_PETAK_AKSESORI */
					END;
					
					/* STR_I_PTK_AKSESORI*/
					DECLARE
						petakId NUMBER(19,0);
					BEGIN
						IF noPetak LIKE 'L%' OR noPetak LIKE 'l%' THEN
							SELECT p.PTK_ID INTO petakId FROM STR_I_PTK p
							WHERE p.MKLMT_STRATA_ID = maklumatStrataId AND p.NAMA = noPetak;
						ELSIF noPetak LIKE 'P%' OR noPetak LIKE 'p%' THEN
							UPDATE STR_I_BLOK_SMTR SET JUMLAH_PTK_AKSESORI = JUMLAH_PTK_AKSESORI + 1
							WHERE NAMA LIKE noPetak AND MKLMT_STRATA_ID = maklumatStrataId;
						ELSE 
							SELECT p.PTK_ID  INTO petakId FROM STR_I_PTK p
							JOIN STR_I_TINGKAT t ON (p.TINGKAT_ID = t.TINGKAT_ID)
							JOIN STR_I_MENARA m ON (t.MENARA_ID = m.MENARA_ID)
							JOIN STR_I_BANGUNAN b ON (m.BANGUNAN_ID = b.BANGUNAN_ID)
							WHERE p.MKLMT_STRATA_ID = maklumatStrataId AND p.NAMA = noPetak AND b.NAMA = noBangunan AND t.NAMA = noTingkat;
						END IF;

						IF petakId IS NOT NULL THEN
							INSERT INTO STR_I_PTK_AKSESORI(PTK_AKSESORI_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
															VERSION, NAMA, LUAS_PTK, UNIT_LUAS_PTK_ID, JNS_KEGUNAAN,
															PTK_ID, UNIT_SYER_MUKTAMAD, BXF3, F3, JADUAL_PTK)
							VALUES (SEQ_PTK_AKSESORI.NEXTVAL, username, SYSDATE, username, SYSDATE,
									0, trim(B2PA.PETAK_AKSESORI), luasPetakAksesori, unitLuasaTiada, 'NA',
									petakId, 0, 0, 0, 0);
							DBMS_OUTPUT.put_line('STR_I_PTK_AKSESORI inserted');
						END IF;
					EXCEPTION
						WHEN TOO_MANY_ROWS THEN
							errMsgPetakAks := 'STR_I_PTK_AKSESORI B2ASAS ID:' || B2ASAS.BORANG2_ASAS_ID ||' MORE THAN 1 MATCH IN STR_I_PETAK(petakBersangkutan:' 
												|| B2PA.PETAK_YANG_BERSANGKUTAN || ',noBangunan:' || noBangunan || ',noTingkat:' || noTingkat 
												|| ',noPetak:' || noPetak || ',mStrataId:' || maklumatStrataId;
							DBMS_OUTPUT.put_line(errMsgPetakAks);

						WHEN NO_DATA_FOUND THEN
							errMsgPetakAks := 'STR_I_PTK_AKSESORI B2ASAS ID:' || B2ASAS.BORANG2_ASAS_ID ||' NO MATCH IN STR_I_PETAK(petakBersangkutan:' 
												|| B2PA.PETAK_YANG_BERSANGKUTAN || ',noBangunan:' || noBangunan || ',noTingkat:' || noTingkat 
												|| ',noPetak:' || noPetak || ',mStrataId:' || maklumatStrataId;
							DBMS_OUTPUT.put_line(errMsgPetakAks);
							
						WHEN OTHERS THEN
							errMsgPetakAks := 'STR_I_PTK_AKSESORI B2ASAS ID:' || B2ASAS.BORANG2_ASAS_ID || ' ' || SQLERRM;
							DBMS_OUTPUT.put_line(errMsgPetakAks);
					/* end STR_I_PTK_AKSESORI */
					END;
				EXCEPTION
					WHEN OTHERS THEN
						errMsgPetakAks := 'BORANG2_PETAK_AKSESORI B2ASAS ID:' || B2ASAS.BORANG2_ASAS_ID || ' petakAksesori: ' || B2PA.PETAK_AKSESORI || ' ' 
											|| ' petakBersangkutan: ' || B2PA.PETAK_YANG_BERSANGKUTAN || ' '|| SQLERRM;
						DBMS_OUTPUT.put_line(errMsgPetakAks);
				END;
			/* end loop for petak aksesori */
			END LOOP;
		/* end petak aksesori block */
		END;
		
		DECLARE
			CURSOR C_STR_PETAK_AKS IS 
				SELECT p.PTK_ID FROM STR_I_PTK p LEFT JOIN STR_I_PTK_AKSESORI pa ON (p.PTK_ID = pa.PTK_ID)
				WHERE p.MKLMT_STRATA_ID = maklumatStrataId GROUP BY p.PTK_ID HAVING COUNT(pa.PTK_AKSESORI_ID) = 0;
		/* insert petak aksesori for petak without petak aksesori */
		BEGIN
			/* petak id loop */
			FOR PTK_ID IN C_STR_PETAK_AKS LOOP
				DECLARE
					errMsgUpdate VARCHAR2(250);
				/* block to insert petak aksesori */
				BEGIN
					INSERT INTO STR_I_PTK_AKSESORI(PTK_AKSESORI_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
													VERSION, NAMA, LUAS_PTK, UNIT_LUAS_PTK_ID, JNS_KEGUNAAN,
													PTK_ID, UNIT_SYER_MUKTAMAD, BXF3, F3, JADUAL_PTK)
						VALUES (SEQ_PTK_AKSESORI.NEXTVAL, username, SYSDATE, username, SYSDATE,
								0, 'NA', 0, unitLuasaTiada, 'NA',
								PTK_ID.PTK_ID, 0, 0, 0, 0);
				EXCEPTION
					WHEN OTHERS THEN
					errMsgUpdate := 'STR_I_PTK_AKSESORI error inserting petak aksesori for petakId:'|| PTK_ID.PTK_ID
									||' MAKLUMAT_STRATA_ID:' || maklumatStrataId || SQLERRM;
					DBMS_OUTPUT.put_line(errMsgUpdate);
				/* end block to insert petak aksesori */
				END;
			/* end petak id loop */
			END LOOP;
		/* end insert petak aksesori for petak without petak aksesori */
		END;
		
		DECLARE
			CURSOR C_STR_BGNN IS 
				SELECT BANGUNAN_ID FROM STR_I_BANGUNAN WHERE MKLMT_STRATA_ID = maklumatStrataId;
		/* update total unit syer block */
		BEGIN
			/* bangunan id loop */
			FOR BGN_ID IN C_STR_BGNN LOOP
				DECLARE
					errMsgUpdate VARCHAR2(250);
					noOfPetak NUMBER;
				/* update STR_I_BANGUNAN */
				BEGIN
					SELECT COUNT(*) INTO noOfPetak
					FROM STR_I_PTK WHERE BANGUNAN_ID = BGN_ID.BANGUNAN_ID;
					DBMS_OUTPUT.put_line('noOfPetak:' || noOfPetak || ' for STR_I_BANGUNAN ID:' || BGN_ID.BANGUNAN_ID);
					
					IF noOfPetak = 0 THEN
						CONTINUE;
					END IF;
					
					UPDATE STR_I_BANGUNAN SET JUMLAH_SYER = (SELECT SUM(UNIT_SYER) FROM STR_I_PTK WHERE BANGUNAN_ID = BGN_ID.BANGUNAN_ID)
					WHERE BANGUNAN_ID = BGN_ID.BANGUNAN_ID;
					DBMS_OUTPUT.put_line('TotalUnitSyer updated');
				EXCEPTION
					WHEN OTHERS THEN
					errMsgUpdate := 'STR_I_BANGUNAN error updating total unit syer MAKLUMAT_STRATA_ID:' 
									|| maklumatStrataId || ' STR_I_BANGUNAN ID:'|| BGN_ID.BANGUNAN_ID || SQLERRM;
					DBMS_OUTPUT.put_line(errMsgUpdate);
				/* end update STR_I_BANGUNAN */
				END;
			/* end bangunan id loop */
			END LOOP;
		/* end update total unit syer block */
		END;
		
		<<skipB2>>
		IF errMsgBorang2 IS NOT NULL THEN
			DBMS_OUTPUT.put_line(errMsgBorang2);
		END IF;
		
	/* end b2 block*/
	END;

	COMMIT;
	
	IF msgNotifyUser IS NOT NULL THEN
		raise exceptionNotifyUser;
	END IF;

EXCEPTION
	WHEN exceptionNotifyUser THEN
		RAISE_APPLICATION_ERROR(-20001, 'Masalah migration Borang 2 untuk idHakmilik ' || arg_hakmilik_id || ' : . ' || msgNotifyUser
			|| ' Sila rujuk support team jika masih ada masalah selepas pembetulan di DMSA.' );
	WHEN borang2NotFound THEN
		RAISE_APPLICATION_ERROR(-20001, 'No Borang 2 with this idHakmilik:' || arg_hakmilik_id || ' is found.');
	WHEN OTHERS THEN
		NULL;
		DBMS_OUTPUT.put_line('ERROR IN OUTER BLOCK: ' || SQLERRM);
END
$procedure$
 LANGUAGE edbspl
;

-- DROP PROCEDURE et_main_uat.migrate_borang4_by_hakmilikid(varchar);

CREATE OR REPLACE PROCEDURE et_main_uat.migrate_borang4_by_hakmilikid(IN arg_hakmilik_id character varying)
 SECURITY DEFINER
AS $procedure$

	
	loccode varchar2(4000) := '';
    v_LogLevel varchar2(1000) := 'Debug';

	/* constants and variables */
	destination CONSTANT VARCHAR2(100) := 'et_main';
	username CONSTANT VARCHAR2(80) := 'MIGRATOR_S';
	migrationTime CONSTANT TIMESTAMP(6) := sysdate;
	migrationScript CONSTANT VARCHAR2(20) := 'CALL_PROCEDURE';
	errMsg VARCHAR2(250);
	msgNotifyUser VARCHAR2(4000);
  	errMsg2 VARCHAR2(1000);  

	/* hardcoded variables */
	statusTanahDaftarId NUMBER(19,0);
	jenisPengenalanTiada NUMBER(19,0);
	jenisPbTiada NUMBER(19,0);
	jenisPbMc NUMBER(19,0);
	negeriTiada NUMBER(19,0);
	bandarTiada NUMBER(19,0);
	jenisPelanLain NUMBER(19,0);
	jenisPelanPetak NUMBER(19,0);
	jenisPelanPetakAksesori NUMBER(19,0);
	unitLuasaTiada NUMBER(19,0);
	pejabatId NUMBER(19,0);
	caraBayaranTiada NUMBER(19,0);
	medanIdIndPelan NUMBER(19,0);
  jenisPetakId NUMBER(19,0);
  seq NUMBER;
  idHakmilikStrataInduk IND_HKMLK.ID_HKMLK%TYPE;
  versiDhdId NUMBER(19,0);
  pejabatKod VARCHAR2(2);

	B4ASAS ET_DMSA.BORANG4_ASAS%ROWTYPE;

	TYPE BORANG4_INDUK_REF IS TABLE OF NUMBER INDEX BY VARCHAR2(19);

	/* exceptions */
	tiadaStrataInduk EXCEPTION;
	tiadaNoHakmilik EXCEPTION;
	tiadaNoPetak EXCEPTION;
	tiadaNoBangunan EXCEPTION;
	tiadaNoTingkat EXCEPTION;
	noBorang2Match EXCEPTION;
	tiadaMaklumatHakmilik EXCEPTION;
	tooManyMaklumatHakmilik EXCEPTION;
	tiadaJenisBorang4 EXCEPTION;
	tiadaNoBlokSementara EXCEPTION;
	petaksAksIsNull EXCEPTION;
	versiIsNotZero EXCEPTION;
	noBorang4Match EXCEPTION;
	appMoreThanOne EXCEPTION;
	exceptionNotifyUser EXCEPTION;

    --bugfixes
    noah1 number;
    noah2 number;
    noah3 number;
    noah4 number;

    --pcp
    n_nota_id number;
    found number;
    msgerrpcp varchar2(2000);

    foundDokPenentusahan number;
    aDokPenentusahanId number;

--------------------------------------------------------------------------------		
	/* functions (start) */
	FUNCTION findStrataIndukIdByIdHakmilik(idHakmilik IN  VARCHAR2) 
	RETURN NUMBER IS
		indukId NUMBER(19,0);
	BEGIN
	
		ET_MAIN.PR_TKR_LOG('findStrataIndukIdByIdHakmilik','I',arg_hakmilik_id,null,null,'ID HM:' || idHakmilik);
	
		SELECT HKMLK_ID INTO indukId
		FROM IND_HKMLK WHERE ID_HKMLK = idHakmilik;
		RETURN indukId;
	EXCEPTION
		WHEN OTHERS THEN
			RAISE tiadaStrataInduk;
			RETURN NULL;
	END;
--------------------------------------------------------------------------------		
	PROCEDURE findHakmilikEtanah(idHakmilik IN VARCHAR2, hmId OUT NUMBER, mHmId OUT NUMBER, dhdVId OUT NUMBER, versiNo OUT NUMBER) IS
	BEGIN
		SELECT v.VERSI_DHD_ID, v.HKMLK_ID, v.MKLMT_HKMLK_ID, v.VERSI_DHD 
		INTO dhdVId, hmId, mHmId, versiNo
		FROM IND_VERSI_DHD v JOIN IND_HKMLK h ON (v.HKMLK_ID = h.HKMLK_ID)
		WHERE v.FLAG_AKTIF = 'Y' AND upper(h.ID_HKMLK) = upper(idHakmilik);
	EXCEPTION
		WHEN NO_DATA_FOUND THEN
            ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'ERR findHakmilikEtanah(' || idHakmilik || ') ' || SQLERRM);
			hmId := NULL;
			mHmId := NULL;
			dhdVId := NULL;
	END;
--------------------------------------------------------------------------------		
  FUNCTION findBorang2NoVersi(strataIndukId IN NUMBER) 
	RETURN NUMBER IS
		versiNoB2 NUMBER(19,0);
	BEGIN
		SELECT NO_VERSI INTO versiNoB2
		FROM IND_STRATA_IDX_VERSI WHERE HKMLK_ID = strataIndukId
    AND FLAG_AKTIF = 'Y';
		RETURN versiNoB2;
	EXCEPTION
		WHEN OTHERS THEN
            ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'ERROR findBorang2NoVersi(' || strataIndukId || ')');
			RETURN NULL;
	END;
--------------------------------------------------------------------------------	 
	FUNCTION findSIndeksVIdByIdSIndukId(strataIndukId IN NUMBER) 
	RETURN NUMBER IS
		versiId NUMBER(19,0);
	BEGIN
		SELECT max(STRATA_IDX_VERSI_ID) INTO versiId
		FROM IND_STRATA_IDX_VERSI WHERE HKMLK_ID = strataIndukId;
		RETURN versiId;
	EXCEPTION
		WHEN OTHERS THEN
            ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'ERROR findSIndeksVIdByIdSIndukId(' || strataIndukId || ')');
			RETURN NULL;
	END;
--------------------------------------------------------------------------------		
	FUNCTION returnSpaceIfNull(field IN  VARCHAR2) 
	RETURN VARCHAR2 IS
		tempVariable VARCHAR2(4000);
	BEGIN
		tempVariable := trim(field);
		IF tempVariable IS NULL THEN
			tempVariable := ' ';
		END IF;
		RETURN tempVariable;
	END;
--------------------------------------------------------------------------------		
	FUNCTION getSakIdBySakKod(sakKod IN  VARCHAR2) 
	RETURN NUMBER IS
		sakId NUMBER(19, 0);
	BEGIN
		SELECT SENARAI_AHLI_KUMPULAN_ID INTO sakId
		FROM RJK_SENARAI_AHLI_KUMPULAN WHERE KOD = sakKod;
		RETURN sakId;
	END;
--------------------------------------------------------------------------------		
	FUNCTION getDmsaSakKodByDmsaSakId(sakId IN  NUMBER, blockDescription IN VARCHAR2) 
	RETURN VARCHAR2 IS
		sakKod VARCHAR2(120);
	BEGIN
		SELECT KOD INTO sakKod
		FROM ET_DMSA.RJK_SENARAI_AHLI_KUMPULAN WHERE SENARAI_AHLI_KUMPULAN_ID = sakId ;
		RETURN sakKod;
	EXCEPTION
		WHEN OTHERS THEN
			ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'ERROR getDmsaSakKodByDmsaSakId('||sakId||')'|| blockDescription||' '||SQLERRM);
			RETURN NULL;
	END;
--------------------------------------------------------------------------------		
	FUNCTION getSakIdByDmsaSakKod(sakKod IN  VARCHAR2, blockDescription IN VARCHAR2, sk in VARCHAR2) 
	RETURN NUMBER IS
		sakId NUMBER(19, 0);
	BEGIN
		SELECT SENARAI_AHLI_KUMPULAN_ID INTO sakId
		FROM RJK_SENARAI_AHLI_KUMPULAN WHERE STRATA_KOD = sakKod and senarai_kumpulan_id = (select senarai_kumpulan_id from rjk_senarai_kumpulan where kod = sk);-- and senarai_kumpulan_id = 213;
		RETURN sakId;
	EXCEPTION
		WHEN OTHERS THEN
			ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'ERROR getSakIdByDmsaSakKod('||sakKod||')'||blockDescription||' '||SQLERRM);
			RETURN NULL;
	END;
--------------------------------------------------------------------------------		
	FUNCTION getSakIdByDmsaSakId(dmsaSakId IN NUMBER, blockDescription IN VARCHAR2, sk in VARCHAR2)
	RETURN NUMBER IS
		sakId NUMBER(19,0);
		dmsaSakKod VARCHAR2(120);
	BEGIN
		dmsaSakKod := getDmsaSakKodByDmsaSakId(dmsaSakId, blockDescription);
		sakId := getSakIdByDmsaSakKod(dmsaSakKod, blockDescription,sk);
		RETURN sakId;
	END;
--------------------------------------------------------------------------------		
	FUNCTION getSeksyenIdByDmsaSeksyenId(dmsaSeksyenId IN NUMBER, etanahBpmId IN NUMBER)
	RETURN NUMBER IS
		seksyenKod ET_DMSA.IND_SEKSYEN.KOD%TYPE;
		seksyenId NUMBER(19,0);
	BEGIN
		SELECT KOD INTO seksyenKod FROM ET_DMSA.IND_SEKSYEN WHERE SEKSYEN_ID = dmsaSeksyenId;
		SELECT SEKSYEN_ID INTO seksyenId FROM IND_SEKSYEN WHERE KOD = seksyenKod AND BANDAR_PEKAN_MUKIM_ID = etanahBpmId;
		RETURN seksyenId;
	EXCEPTION
		WHEN OTHERS THEN
			ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'ERROR getSeksyenIdByDmsaSeksyenId('||dmsaSeksyenId||')'||SQLERRM);
			RETURN NULL;
	END;
--------------------------------------------------------------------------------		
	FUNCTION getBorang2ByIdHakmilik(idHakmilikInduk IN VARCHAR2)
	RETURN ET_DMSA.BORANG2_ASAS%ROWTYPE IS
		borang2 ET_DMSA.BORANG2_ASAS%ROWTYPE;
	BEGIN
		SELECT * INTO borang2 FROM ET_DMSA.BORANG2_ASAS WHERE HAKMILIK_ID = idHakmilikInduk;
		RETURN borang2;
	EXCEPTION
		WHEN OTHERS THEN
			RAISE noBorang2Match;
			RETURN NULL;
	END;
--------------------------------------------------------------------------------		
	FUNCTION getMklmtHkmlkByStrataIndukId(strataIndukId IN NUMBER)
	RETURN IND_MKLMT_HKMLK%ROWTYPE IS
		maklumatHakmilikId NUMBER(19,0);
		maklumatHakmilik IND_MKLMT_HKMLK%ROWTYPE;
	BEGIN
		SELECT MKLMT_HKMLK_ID INTO maklumatHakmilikId 
		FROM IND_VERSI_DHD WHERE HKMLK_ID = strataIndukId AND FLAG_AKTIF = 'Y';

		SELECT * INTO maklumatHakmilik FROM IND_MKLMT_HKMLK
		WHERE MKLMT_HKMLK_ID = maklumatHakmilikId;
		RETURN maklumatHakmilik;
	EXCEPTION
		WHEN TOO_MANY_ROWS THEN
			RAISE tooManyMaklumatHakmilik;
			RETURN NULL;
		WHEN OTHERS THEN
			RAISE tiadaMaklumatHakmilik;
			RETURN NULL;
	END;
--------------------------------------------------------------------------------
    PROCEDURE LOG(msg varchar2, enabled boolean) is
    BEGIN
        IF v_LogLevel = 'Debug' AND enabled = true then
            ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,msg);
        end if;
    END;
	/* functions (end) */
--------------------------------------------------------------------------------	
BEGIN
	-- block to find b4asas  
	
	raise debug 'STARTING....';
	ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'sEBELUM CARI');

	
    BEGIN
      SELECT * INTO B4ASAS 
      FROM ET_DMSA.BORANG4_ASAS
      WHERE BORANG4_ASAS_ID = (
                SELECT BORANG4_ASAS_ID FROM ET_DMSA.VIEW_B4ASAS_IDHAKMILIK WHERE ID_HAKMILIK = UPPER(arg_hakmilik_id));  

    EXCEPTION WHEN OTHERS THEN
      RAISE noBorang4Match;
    /* end block to find b4asas */
    END;

	ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'SELEPAS CARI done');

	statusTanahDaftarId := getSakIdBySakKod('STAHDFT');
	jenisPbTiada := getSakIdBySakKod('JNNULL');
	jenisPbMc := getSakIdBySakKod('JENMC');
	jenisPengenalanTiada := getSakIdBySakKod('JENNULL');
	negeriTiada := getSakIdBySakKod('00');
	bandarTiada := getSakIdBySakKod('2002');
	jenisPelanLain := getSakIdBySakKod('JENIS_PELAN_LAIN-LAIN');
	jenisPelanPetak := getSakIdBySakKod('JENIS_PELAN_PETAK');
	jenisPelanPetakAksesori := getSakIdBySakKod('JENIS_PELAN_PETAK_AKSESORI');
	unitLuasaTiada := getSakIdBySakKod('UNIKELMP');
	caraBayaranTiada := getSakIdBySakKod('CABNULL');
	medanIdIndPelan := getSakIdBySakKod('IND_PELAN');

    --  SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Pengarah Tanah dan Galian Negeri Perak';

	DECLARE
		errMsgBorang4 VARCHAR2(250);
		idHakmilik IND_HKMLK.ID_HKMLK%TYPE;
		hakmilikId NUMBER(19,0);
		maklumatHakmilikId NUMBER(19, 0);
		jenisHakmilikId NUMBER(19,0);
		strataIndukId NUMBER(19, 0);
		indeksVersiIndukId NUMBER(19,0);
        noVersiIndukId NUMBER(19,0);
		indeksTerperinciId NUMBER(19,0);
		bpmId NUMBER(19,0);
		noPetak ET_DMSA.BORANG4_ASAS.NO_PETAK%TYPE;
		noTing ET_DMSA.BORANG4_ASAS.NO_TINGKAT%TYPE;
		noBgnn ET_DMSA.BORANG4_ASAS.NO_BANGUNAN%TYPE;
		noHakmilik ET_DMSA.BORANG4_ASAS.NO_HAKMILIK%TYPE;
        daerahKod VARCHAR2(2);

		bpmKod ET_DMSA.IND_BANDAR_PEKAN_MUKIM.KOD%TYPE;
		jenisHakmilikKod ET_DMSA.RJK_SENARAI_AHLI_KUMPULAN.KOD%TYPE;
		jenisBorangKod ET_DMSA.RJK_SENARAI_AHLI_KUMPULAN.KOD%TYPE;

		pemilik_tbl BORANG4_INDUK_REF;
		kumpulanPb_tbl BORANG4_INDUK_REF;
		urusan_tbl BORANG4_INDUK_REF;
		appHakmilik_tbl BORANG4_INDUK_REF;

		listOfIdPengenalan VARCHAR2(2000);
	
    /* start b4 asas loop */
	BEGIN

		DECLARE
			versiNo NUMBER;
		/* IND_HKMLK */
		BEGIN
		
			loccode := 'beforekod';
		
			SELECT KOD INTO daerahKod
			FROM ET_DMSA.IND_DAERAH WHERE DAERAH_ID = B4ASAS.DAERAH_ID;    
			
			loccode := 'afterkod';

			SELECT KOD INTO bpmKod
			FROM ET_DMSA.IND_BANDAR_PEKAN_MUKIM WHERE BANDAR_PEKAN_MUKIM_ID = B4ASAS.BANDAR_PEKAN_MUKIM_ID;
			
			loccode := 'bpmkod';
			

			SELECT BANDAR_PEKAN_MUKIM_ID INTO bpmId
			FROM IND_BANDAR_PEKAN_MUKIM WHERE KOD = bpmKod AND DAERAH_ID = B4ASAS.DAERAH_ID;
			loccode := 'bpm';

			jenisHakmilikKod := getDmsaSakKodByDmsaSakId(B4ASAS.JENIS_HAKMILIK, 'B4ASAS.JENIS_HAKMILIK');
			
			loccode := 'jkod of ' || B4ASAS.JENIS_HAKMILIK;
			
			SELECT JNS_HKMLK_ID INTO jenisHakmilikId
			FROM RJK_JNS_HKMLK WHERE KOD = jenisHakmilikKod;
			
			loccode := 'jhm';

			noHakmilik := replace(trim(B4ASAS.NO_HAKMILIK), '	');
			noPetak := replace(trim(upper(B4ASAS.NO_PETAK)), '	');
			noTing := replace(trim(upper(B4ASAS.NO_TINGKAT)), '	');
			noBgnn := replace(trim(upper(B4ASAS.NO_BANGUNAN)), '	');

            /* 08/10/18 Azrilisam
            -- PTG
            IF pejabatKod = '00' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Pengarah Tanah dan Galian Negeri Perak';
            -- Tapah
            ELSIF pejabatKod = '01' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Batang Padang';  
            -- Manjung
            ELSIF pejabatKod = '02' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Manjung';  
            -- Batu Gajah
            ELSIF pejabatKod = '03' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Kinta'; 
            -- Kerian
            ELSIF pejabatKod = '04' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Kerian';   
            -- Kuala Kangsar
            ELSIF pejabatKod = '05' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Kuala Kangsar';    
            -- Taiping
            ELSIF pejabatKod = '06' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Larut Matang dan Selama, Taiping';  
            -- Hilir Perak
            ELSIF pejabatKod = '07' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Hilir Perak';  
            -- Gerik
            ELSIF pejabatKod = '08' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Hulu Perak, Gerik';  
            -- Selama
            ELSIF pejabatKod = '09' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Selama'; 
            -- Perak Tengah
            ELSIF pejabatKod = '10' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Perak Tengah, Seri Iskandar'; 
            -- Muallim
            ELSIF pejabatKod = '11' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Muallim';   
            -- Ipoh
            ELSIF pejabatKod = '12' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Daerah Kecil Ipoh';  
            -- Kampar
            ELSIF pejabatKod = '13' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Kampar';   
            -- Sungai Siput
            ELSIF pejabatKod = '14' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Sungai Siput';   
            -- Lenggong
            ELSIF pejabatKod = '15' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Lenggong';  
            -- Pengkalan Hulu
            ELSIF pejabatKod = '16' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Pengkalan Hulu'; 
            -- Kampung Gajah
            ELSIF pejabatKod = '17' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Kampung Gajah';   
            -- Bagan Datuk
            ELSIF pejabatKod = '18' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Bagan Datuk';  
            ELSE
            pejabatId := NULL;
            END IF;      
                */
            
			IF noHakmilik IS NULL THEN
				RAISE tiadaNoHakmilik;
			END IF;

			noHakmilik := CASE WHEN LENGTH(noHakmilik) < 8 THEN lpad(noHakmilik, 8, '0') ELSE noHakmilik END;
			--idHakmilik := B4ASAS.NEGERI_ID || '00' || bpmKod || jenisHakmilikKod || noHakmilik;
			idHakmilik := '11' || daerahKod || bpmKod || jenisHakmilikKod || noHakmilik;      
			strataIndukId := findStrataIndukIdByIdHakmilik(idHakmilik);
			indeksVersiIndukId := findSIndeksVIdByIdSIndukId(strataIndukId);
            noVersiIndukId := findBorang2NoVersi(strataIndukId);
			idHakmilikStrataInduk := idHakmilik;

            --find out pejabat id and pejabat kod for aplikasi
            IF (    jenisHakmilikKod = 'GRN' 
                  OR jenisHakmilikKod = 'PN'
                  OR jenisHakmilikKod = 'HSD') THEN 
                        pejabatKod := '00';
                        SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE KOD = '00';
                        ELSE --GM PM HSM         
                        SELECT PEJABAT_ID INTO pejabatId FROM IND_BANDAR_PEKAN_MUKIM WHERE BANDAR_PEKAN_MUKIM_ID = bpmId;
                        SELECT KOD INTO pejabatKod FROM IND_PEJABAT WHERE PEJABAT_ID = pejabatId;
            END IF;
            --

			jenisBorangKod := getDmsaSakKodByDmsaSakId(B4ASAS.JENIS_BORANG, 'B4ASAS.JENIS_BORANG');
			
			loccode := 'jenisBorangKod:' || B4ASAS.JENIS_BORANG;
			
			IF jenisBorangKod LIKE 'JNS_DOK_B4A' THEN
				IF noBgnn IS NULL THEN
					RAISE tiadaNoBlokSementara;
				ELSE 
                    idHakmilik := idHakmilik || '/' || noBgnn;
                    --	idHakmilik := idHakmilik || CASE WHEN LENGTH(noBgnn) < 5 THEN lpad(noBgnn, 5, '0') ELSE noBgnn END;

                    IF(upper(noBgnn) LIKE 'PL%') THEN
						jenisPetakId := getSakIdBySakKod('JNSSTRBPT'); --Blok Sementara Petak Tanah
					ELSE
						jenisPetakId := getSakIdBySakKod('JNSSTRBLS'); --Blok Sementara
					END IF;
				END IF;

			ELSIF jenisBorangKod LIKE 'JNS_DOK_B4' THEN
				IF noPetak IS NULL THEN
					RAISE tiadaNoPetak;
				END IF;
				IF (noBgnn IS NULL AND noTing IS NOT NULL) THEN
					RAISE tiadaNoBangunan;
				ELSIF (noTing IS NULL AND noBgnn IS NOT NULL) THEN
					RAISE tiadaNoTingkat;
				END IF;

				IF (upper(noBgnn) LIKE '%TIADA%' AND upper(noTing) LIKE '%TIADA%') THEN
					noBgnn := null;
					noTing := null;
				END IF;

				IF(noBgnn IS NULL AND noTing IS NULL) THEN
                    idHakmilik := idHakmilik || '/' || noPetak;
                    --	idHakmilik := idHakmilik || CASE WHEN LENGTH(noPetak) < 5 THEN lpad(noPetak, 5, '0') ELSE noPetak END;
                    jenisPetakId := getSakIdBySakKod('JNSSTRPTT'); --Petak Tanah
				ELSE
                    --					idHakmilik := idHakmilik 
                    --								|| CASE WHEN LENGTH(noBgnn) < 5 THEN lpad(noBgnn, 5, '0') ELSE noBgnn END
                    --								|| CASE WHEN LENGTH(noTing) < 5 THEN lpad(noTing, 5, '0') ELSE noTing END
                    --								|| CASE WHEN LENGTH(noPetak) < 5 THEN lpad(noPetak, 5, '0') ELSE noPetak END;
                    idHakmilik := idHakmilik || '/' || noBgnn || '/' || noTing || '/' || noPetak;
                    jenisPetakId := getSakIdBySakKod('JNSSTRPTK'); --Petak
				END IF;
			ELSE 
				RAISE tiadaJenisBorang4;
			END IF;
            
			findHakmilikEtanah(idHakmilik, hakmilikId, maklumatHakmilikId, versiDhdId, versiNo);

			IF versiNo > 0 THEN
				RAISE versiIsNotZero;
			END IF;

			IF hakmilikId IS NOT NULL THEN
				UPDATE IND_HKMLK 
                SET 
                    LAST_MODIFIED_BY = username, LAST_MODIFIED_DATE = sysdate, VERSION = 0, ID_HKMLK = idHakmilik,
					BANDAR_PEKAN_MUKIM_ID = bpmId, STRATA_INDUK_ID = strataIndukId, NO_BANGUNAN = noBgnn, NO_TINGKAT = noTing,
					NO_PTK = noPetak, JNS_HKMLK_ID = jenisHakmilikId, FLAG_TUKARGANTI = 'Y'
				WHERE HKMLK_ID = hakmilikId;

                --Feature #62541
                UPDATE IND_HKMLK_PELBAGAI 
                SET 
                    JNS_PTK_ID = jenisPetakId 
                WHERE 
                    HKMLK_PELBAGAI_ID = (SELECT HKMLK_PELBAGAI_ID FROM IND_HKMLK WHERE HKMLK_ID = hakmilikId AND HKMLK_PELBAGAI_ID IS NOT NULL);

			ELSE
				INSERT INTO IND_HKMLK ( HKMLK_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
										VERSION, ID_HKMLK, NO_HKMLK, BANDAR_PEKAN_MUKIM_ID, STRATA_INDUK_ID,
										NO_BANGUNAN, NO_TINGKAT, NO_PTK, JNS_HKMLK_ID, FLAG_TUKARGANTI)
					VALUES ( SEQ_HKMLK.NEXTVAL, username, SYSDATE, username, SYSDATE, 
							0, idHakmilik, noHakmilik, bpmId, strataIndukId, 
							noBgnn, noTing, noPetak, jenisHakmilikId, 'Y');
				hakmilikId := SEQ_HKMLK.CURRVAL;
			END IF;

		EXCEPTION 
			WHEN tiadaStrataInduk THEN
				errMsgBorang4 := 'IND_HKMLK B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' Tiada Strata Induk ' || idHakmilik;
				msgNotifyUser := msgNotifyUser || ' ***** Tidak dapat strata induk untuk Borang 4 ini. Sila pasti bandar pekan mukim / jenis hakmilik / no hakmilik betul. ';
				GOTO skipB4;
			WHEN tiadaNoHakmilik THEN
				errMsgBorang4 := 'IND_HKMLK B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' Tiada No. Hakmilik';
				msgNotifyUser := msgNotifyUser || ' ***** Sila isi no hakmilik untuk Borang 4 ini. ';
				GOTO skipB4;
			WHEN tiadaNoPetak THEN
				errMsgBorang4 := 'IND_HKMLK B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' Tiada No. Petak';
				msgNotifyUser := msgNotifyUser || ' ***** Sila isi no petak untuk Borang 4 ini. ';
				GOTO skipB4;
			WHEN tiadaNoTingkat THEN
				errMsgBorang4 := 'IND_HKMLK B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' Tiada No. Tingkat';
				msgNotifyUser := msgNotifyUser || ' ***** Sila isi no tingkat untuk Borang 4 ini. ';
				GOTO skipB4;
			WHEN tiadaNoBangunan THEN
				errMsgBorang4 := 'IND_HKMLK B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' Tiada No. Bangunan';
				msgNotifyUser := msgNotifyUser || ' ***** Sila isi no bangunan untuk Borang 4 ini. ';
				GOTO skipB4;
			WHEN tiadaJenisBorang4 THEN
				errMsgBorang4 := 'IND_HKMLK B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || 'Tiada jenis borang 4';
				msgNotifyUser := msgNotifyUser || ' ***** Tidak dapat jenis borang untuk Borang 4 ini. Sila rujuk migration team. ' || ':LOCCODE:' || loccode;
				GOTO skipB4;
			WHEN tiadaNoBlokSementara THEN
				errMsgBorang4 := 'IND_HKMLK B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' Tiada No. Blok Sementara';
				msgNotifyUser := msgNotifyUser || ' ***** Sila isi no blok sementara untuk Borang 4A ini. ';
				GOTO skipB4;
			WHEN versiIsNotZero THEN
				errMsgBorang4 := 'IND_HKMLK DhdVersi versi is not zero B4ASAS:' || B4ASAS.BORANG4_ASAS_ID || ' ID_HAKMILIK:'
								|| idHakmilik || ' HKMLK_ID:' || hakmilikId || ' versiDhdId:' || versiDhdId
								|| ' versiNo:' || versiNo;
				msgNotifyUser := msgNotifyUser || ' ***** Versi Borang 4 ini bukan 0. Sila rujuk migration team. ';
				GOTO skipB4;
			WHEN OTHERS THEN
				errMsgBorang4 := 'IND_HKMLK B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' ' || SQLERRM || ':LOCCODE:' || loccode; 
				msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgBorang4;
				GOTO skipB4;
		/* end IND_HKMLK */
		END;
		ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'IND_HKMLK done');

		DECLARE
			strataIndukMH IND_MKLMT_HKMLK%ROWTYPE;
			strataIndukMHId NUMBER(19,0);
			noLot ET_DMSA.BORANG4_ASAS.NO_LOT%TYPE;
			jenisPeganganId NUMBER(19,0);
			jenisTanahId NUMBER(19,0);
			seksyenId IND_SEKSYEN.SEKSYEN_ID%TYPE;
			unitNoLotId NUMBER(19,0);
            kodSyrtNyt IND_SYRT_NYATA.KOD%TYPE;

		
		BEGIN
 
			strataIndukMH := getMklmtHkmlkByStrataIndukId(strataIndukId);

            noLot := trim(strataIndukMH.NO_LOT);
			IF noLot IS NOT NULL THEN
				noLot := lpad(noLot, 7, '0');
			END IF;

			SELECT JNS_TNH_ID INTO jenisTanahId 
			FROM IND_BANDAR_PEKAN_MUKIM WHERE BANDAR_PEKAN_MUKIM_ID = bpmId;

            --changed to get no lot from strata induk 11/8
            --changed to get taraf milik id, unit lot id, seksyen id, tempoh pajakan and tarikh luput from strata induk 14/8

            IF maklumatHakmilikId IS NOT NULL THEN 
				UPDATE IND_MKLMT_HKMLK SET LAST_MODIFIED_BY = username, LAST_MODIFIED_DATE = sysdate, VERSION = 0, --FLAG_TERKINI = 'Y',
					KADAR_CUKAI = strataIndukMH.KADAR_CUKAI, NO_LOT = noLot,
					TEMPOH_PAJAKAN = strataIndukMH.TEMPOH_PAJAKAN, TRKH_LUPUT = strataIndukMH.TRKH_LUPUT, TRKH_DAFTAR = B4ASAS.TARIKH_DAFTAR_HAKMILIK_STRATA,
					UNIT_SYER = B4ASAS.UNIT_SYER_BAGI_PETAK, STATUS_HKMLK_ID = statusTanahDaftarId, UNIT_LOT_ID = strataIndukMH.UNIT_LOT_ID,
					SEKSYEN_ID = strataIndukMH.SEKSYEN_ID, UNIT_KADAR_CUKAI_ID = strataIndukMH.UNIT_KADAR_CUKAI_ID, SYRT_NYATA_ID = strataIndukMH.SYRT_NYATA_ID,
					SKTN_KPTGN_ID = strataIndukMH.SKTN_KPTGN_ID, TARAF_MILIK_ID = strataIndukMH.TARAF_MILIK_ID, 
					JNS_TNH_ID = jenisTanahId, KAT_ID = strataIndukMH.KAT_ID, LUAS = 0, UNIT_LUAS_ID = unitLuasaTiada, 
					LOKASI = strataIndukMH.LOKASI--, JENIS_PETAK_ID = jenisPetakId
				WHERE MKLMT_HKMLK_ID = maklumatHakmilikId;
			ELSE
				INSERT INTO IND_MKLMT_HKMLK( MKLMT_HKMLK_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE, 
											VERSION, /*FLAG_TERKINI,*/ KADAR_CUKAI, NO_LOT,
											TEMPOH_PAJAKAN, TRKH_LUPUT, TRKH_DAFTAR,
											UNIT_SYER, STATUS_HKMLK_ID, UNIT_LOT_ID, SEKSYEN_ID,
											UNIT_KADAR_CUKAI_ID, SYRT_NYATA_ID, SKTN_KPTGN_ID, 
											TARAF_MILIK_ID, JNS_TNH_ID, KAT_ID, LUAS, UNIT_LUAS_ID, LOKASI)--, JENIS_PETAK_ID)
					VALUES (SEQ_MKLMT_HKMLK.NEXTVAL, username, SYSDATE, username, SYSDATE,
							0, /*'Y',*/ strataIndukMH.KADAR_CUKAI, noLot, 
							strataIndukMH.TEMPOH_PAJAKAN, strataIndukMH.TRKH_LUPUT, B4ASAS.TARIKH_DAFTAR_HAKMILIK_STRATA,
							B4ASAS.UNIT_SYER_BAGI_PETAK, statusTanahDaftarId, strataIndukMH.UNIT_LOT_ID, strataIndukMH.SEKSYEN_ID,
							strataIndukMH.UNIT_KADAR_CUKAI_ID, strataIndukMH.SYRT_NYATA_ID, strataIndukMH.SKTN_KPTGN_ID,
							strataIndukMH.TARAF_MILIK_ID, jenisTanahId, strataIndukMH.KAT_ID, 0, unitLuasaTiada, strataIndukMH.LOKASI);--, jenisPetakId);
				maklumatHakmilikId := SEQ_MKLMT_HKMLK.CURRVAL;
			END IF;			

		

            --#60567 SYARAT NYATA BERCAMPUR PADA SKIM
            IF idHakmilikStrataInduk = '080302PN00404588' THEN
                ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'SYARAT NYATA BERCAMPUR PADA SKIM');   
                BEGIN
                    SELECT KOD_SYRT_NYT into kodSyrtNyt FROM TKR_HKMLK_STR_SYRT_NYT_BCMPR WHERE ID_HAKMILIK = idHakmilik;
            
                    IF kodSyrtNyt IS NOT NULL THEN      
                        UPDATE IND_MKLMT_HKMLK 
                        SET 
                            SYRT_NYATA_ID = (SELECT SYRT_NYATA_ID FROM IND_SYRT_NYATA WHERE KOD = kodSyrtNyt)
                        WHERE MKLMT_HKMLK_ID = maklumatHakmilikId;
                    END IF;
                EXCEPTION
                    WHEN OTHERS THEN
                        ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'Bukan syarat nyata bercampur' || ' ' || SQLERRM);
                END;
            END IF;
            --end #60567 SYARAT NYATA BERCAMPUR PADA SKIM

			ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'IND_MKLMT_HKMLK done');

		EXCEPTION
			WHEN tiadaMaklumatHakmilik THEN
				errMsgBorang4 := 'IND_MKLMT_HKMLK ERROR getMklmtHkmlkByStrataIndukId:' || strataIndukId
									|| 'B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' ' || SQLERRM; 
				msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgBorang4;
				GOTO skipB4;
			WHEN tooManyMaklumatHakmilik THEN
				errMsgBorang4 := 'IND_MKLMT_HKMLK TOO_MANY_ROWS getMklmtHkmlkByStrataIndukId:' || strataIndukId
									|| 'B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' ' || SQLERRM; 
				msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgBorang4;
				GOTO skipB4;
			WHEN OTHERS THEN
				errMsgBorang4 := 'IND_MKLMT_HKMLK B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' ' || SQLERRM; 
				msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgBorang4;
				GOTO skipB4;
		/* end IND_MKLMT_HKMLK */
		END;

		/* IND_VERSI_DHD */
		BEGIN
			IF versiDhdId IS NOT NULL THEN
				UPDATE IND_VERSI_DHD SET LAST_MODIFIED_BY = username, LAST_MODIFIED_DATE = sysdate, VERSION = 0, FLAG_AKTIF = 'Y', 
				VERSI_DHD = 0, VERSI_DHK = 0, MKLMT_HKMLK_ID = maklumatHakmilikId, HKMLK_ID = hakmilikId,
        TRKH_DHD = B4ASAS.TARIKH_DAFTAR_HAKMILIK_STRATA, TRKH_DHK = B4ASAS.TARIKH_DAFTAR_HAKMILIK_STRATA 
				WHERE VERSI_DHD_ID = versiDhdId;
			ELSE 
				INSERT INTO IND_VERSI_DHD( VERSI_DHD_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE, 
										VERSION, FLAG_AKTIF, VERSI_DHD, VERSI_DHK, MKLMT_HKMLK_ID, TRKH_DHD, TRKH_DHK, 
										HKMLK_ID )
					VALUES ( SEQ_VERSI_DHD.NEXTVAL, username, SYSDATE, username, SYSDATE,
							0,'Y', 0, 0, maklumatHakmilikId, B4ASAS.TARIKH_DAFTAR_HAKMILIK_STRATA, B4ASAS.TARIKH_DAFTAR_HAKMILIK_STRATA,
							hakmilikId );
				versiDhdId := SEQ_VERSI_DHD.CURRVAL;
			END IF;

			ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'IND_VERSI_DHD done');
		EXCEPTION
			WHEN OTHERS THEN
				errMsgBorang4 := 'IND_VERSI_DHD B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' ' || SQLERRM; 
				msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgBorang4;
				GOTO skipB4;
		/* end IND_VERSI_DHD */
		END;

		IF indeksVersiIndukId IS NOT NULL THEN
			DECLARE
				errMsgUpdateIndex VARCHAR2(250);
				luasPetak NUMBER(16,4);
				unitLuasPetak NUMBER(19,0);
			/* block to update BORANG2 IND_STR_IDX_TPRNC */
			BEGIN        
          IF noBgnn IS NULL AND noTing IS NULL  THEN
            SELECT BTRN_STRATA_IDX_ID INTO indeksTerperinciId FROM IND_BTRN_STRATA_IDX 
            WHERE NO_BANGUNAN IS NULL AND NO_TINGKAT IS NULL AND NO_PTK = noPetak AND IDX_AKHIR_ID = indeksVersiIndukId;
          ELSIF noTing IS NULL AND noPetak IS NULL  THEN
            SELECT BTRN_STRATA_IDX_ID INTO indeksTerperinciId FROM IND_BTRN_STRATA_IDX 
            WHERE NO_BANGUNAN = noBgnn AND NO_TINGKAT IS NULL AND NO_PTK IS NULL AND IDX_AKHIR_ID = indeksVersiIndukId;
          ELSE
            SELECT BTRN_STRATA_IDX_ID INTO indeksTerperinciId FROM IND_BTRN_STRATA_IDX 
            WHERE NO_BANGUNAN = noBgnn AND NO_TINGKAT = noTing AND NO_PTK = noPetak AND IDX_AKHIR_ID = indeksVersiIndukId;
          END IF;

          UPDATE IND_BTRN_STRATA_IDX SET HKMLK_ID = hakmilikId WHERE BTRN_STRATA_IDX_ID = indeksTerperinciId;

 --         IF noVersiIndukId = 0 THEN --avoid to update if B2 already tukarganti
          /* block to update IND_MKLMT_HKMLK FOR LUAS PETAK */
            BEGIN			
              SELECT LUAS, UNIT_LUAS_ID INTO luasPetak, unitLuasPetak FROM IND_BTRN_STRATA_IDX WHERE HKMLK_ID = hakmilikId;

              UPDATE IND_MKLMT_HKMLK SET LUAS = luasPetak, UNIT_LUAS_ID = unitLuasPetak WHERE MKLMT_HKMLK_ID = maklumatHakmilikId;
            EXCEPTION
              WHEN OTHERS THEN
                errMsgUpdateIndex := 'IND_MKLMT_HKMLK fail to get luas petak untuk HKMLK_ID ' || hakmilikId
                          || 'B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' ' || 
                          ' indeksVersiIndukId:' || indeksVersiIndukId || ' noBgnn:' || noBgnn
                          || ' noTing:' || noTing || ' noPetak:' || noPetak || ' ' || SQLERRM; 
                ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgUpdateIndex);
          /* end block to update IND_MKLMT_HKMLK FOR LUAS PETAK */
          END;
--				END IF;
			EXCEPTION
				WHEN NO_DATA_FOUND THEN
					errMsgUpdateIndex := 'IND_STR_IDX_TERPRNC indeks terperinci not found B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID 
										|| ' indeksVersiIndukId:' || indeksVersiIndukId || ' noBgnn:' || noBgnn
										|| ' noTing:' || noTing || ' noPetak:' || noPetak;
					ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgUpdateIndex);

				WHEN OTHERS THEN
					errMsgUpdateIndex := 'IND_STR_IDX_TERPRNC UPDATE error B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID 
										|| ' indeksVersiIndukId:' || indeksVersiIndukId || ' indeksTerperinciId:' || indeksTerperinciId 
										|| SQLERRM;
					ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgUpdateIndex);
			/* end block to update BORANG2 IND_STR_IDX_TERPRNC  */
			END;
		ELSE
			ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'update IND_STR_IDX_TERPRNC with hakmilikid skipped as indeksVersiIndukId is NULL');
		END IF;

		DECLARE 
			errMsgDelete VARCHAR2(250);
			warisIds VARCHAR2(2000);
			pbIds VARCHAR2(2000);
		/* block to delete all child data*/
		BEGIN
			DECLARE
				CURSOR C_DEL_PB IS SELECT pb.PIHAK_BKPTG_ID FROM IND_PIHAK_BKPTG pb WHERE pb.VERSI_AKHIR_ID = versiDhdId  and pb.created_by = 'MIGRATOR_S';
				CURSOR C_DEL_WARIS IS SELECT k.WARIS_ID FROM IND_KUMPLN_PIHK_BKPTG k
									JOIN IND_PIHAK_BKPTG pb ON (pb.PIHAK_BKPTG_ID = k.PIHAK_BKPTG_ID)
									WHERE pb.VERSI_AKHIR_ID = versiDhdId  and pb.created_by = 'MIGRATOR_S';
				CURSOR C_CUR_APP IS SELECT ap.ID_PENGENALAN FROM UMM_APLIKASI ap
									JOIN UMM_A_HKMLK ah ON (ap.APLIKASI_ID = ah.APLIKASI_ID)
									WHERE UPPER(ah.ID_HKMLK) = UPPER(idHakmilik)  and ah.created_by = 'MIGRATOR_S';

			/* block to retrieve all similar data */
			BEGIN

				/* block to construct warisIds */
				BEGIN
					FOR W IN C_DEL_WARIS loop
						--if(trim(W.WARIS_ID is not null)) then
							warisIds := warisIds || W.WARIS_ID || ',';
						--end if;
						warisIds := replace (warisIds,',,',',');
					END LOOP;
					warisIds := TRIM(TRAILING ',' FROM warisIds);
					warisIds = REGEXP_REPLACE(warisIds, '^,+', '');
				EXCEPTION
					WHEN OTHERS THEN
						warisIds := NULL;
						errMsgDelete := 'Error construct warisIds B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' versiDhdId:'
										|| versiDhdId || ' ' || SQLERRM;
						ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgDelete);

						msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgDelete;
				/* end block to construct warisIds */
				END;

				/* block to construct pbIds */
				BEGIN
					FOR PB IN C_DEL_PB LOOP
						pbIds := pbIds || PB.PIHAK_BKPTG_ID || ',';
					END LOOP;
					pbIds := TRIM(TRAILING ',' FROM pbIds);
				EXCEPTION
					WHEN OTHERS THEN
						pbIds := NULL;
						errMsgDelete := 'Error construct pbIds B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' versiDhdId:'
										|| versiDhdId || ' ' || SQLERRM;
						ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgDelete);

						msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgDelete;
				/* end block to construct pbIds */
				END;

				/* block to construct listOfIdPengenalan */
				BEGIN
					FOR APP IN C_CUR_APP LOOP
						listOfIdPengenalan := listOfIdPengenalan || '''' || APP.ID_PENGENALAN|| '''' || ',';
					END LOOP;
					listOfIdPengenalan := TRIM(TRAILING ',' FROM listOfIdPengenalan);
				EXCEPTION
					WHEN OTHERS THEN
						listOfIdPengenalan := NULL;
						errMsgDelete := 'Error construct listOfIdPengenalan B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' versiDhdId:'
										|| versiDhdId || ' ' || SQLERRM;
						ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgDelete);

						msgNotifyUser := msgNotifyUser || ' *****  Sila rujuk migration team - ' || errMsgDelete;
				/* end block to construct listOfIdPengenalan */
				END;
			/* end block to retrieve all similar data */
			END;

			/* delete DFT_A_SERAHAN_TERLIBAT */
			BEGIN
				DELETE FROM DFT_A_SERAHAN_TERLIBAT WHERE A_HKMLK_ID IN (SELECT A_HKMLK_ID FROM UMM_A_HKMLK WHERE UPPER(ID_HKMLK) = UPPER(idHakmilik)  and created_by = 'MIGRATOR_S');
			EXCEPTION
				WHEN OTHERS THEN
					errMsgDelete := 'delete DFT_A_SERAHAN_TERLIBAT B4ASAS ID:' ||  B4ASAS.BORANG4_ASAS_ID || ' versiDhdId:' 
									|| versiDhdId || SQLERRM;
					ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgDelete);

					msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgDelete;
			/* end delete DFT_A_SERAHAN_TERLIBAT */
			END;

			/* delete UMM_A_PIHAK_BKPTG */
			BEGIN
				DELETE FROM UMM_A_PIHAK_BKPTG WHERE A_HKMLK_ID IN (SELECT A_HKMLK_ID FROM UMM_A_HKMLK WHERE UPPER(ID_HKMLK) = UPPER(idHakmilik))  and created_by = 'MIGRATOR_S';
			EXCEPTION
				WHEN OTHERS THEN
					errMsgDelete := 'delete UMM_A_PIHAK_BKPTG B4ASAS ID:' ||  B4ASAS.BORANG4_ASAS_ID || ' versiDhdId:' 
									|| versiDhdId || SQLERRM;
					ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgDelete);

					msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgDelete;
			/* end delete UMM_A_PIHAK_BKPTG */
			END;

			/* delete UMM_A_HKMLK */
			BEGIN
				DELETE FROM UMM_A_HKMLK 
                WHERE   
                        UPPER(ID_HKMLK) = UPPER(idHakmilik) and 
                        JNS_TNH_ISMEN_ID is null and 
                        created_by = 'MIGRATOR_S'; --avoid delete two appHakmilik for ismen
			EXCEPTION
				WHEN OTHERS THEN
					errMsgDelete := 'delete UMM_A_HKMLK B4ASAS ID:' ||  B4ASAS.BORANG4_ASAS_ID || ' versiDhdId:' 
									|| versiDhdId || SQLERRM;
					ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgDelete);

					msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgDelete;
			/* end delete UMM_A_HKMLK */
			END;

            /** delete for dok penentusahan */
			BEGIN
				DELETE FROM DFT_A_BTRN_DOK_PENNTSHN WHERE UPPER(ID_HKMLK) = UPPER(idHakmilik);

			EXCEPTION
				WHEN OTHERS THEN
					errMsgDelete := 'delete DFT_A_BTRN_DOK_PENNTSHN B4ASAS ID:' ||  B4ASAS.BORANG4_ASAS_ID || ' versiDhdId:' 
									|| versiDhdId || SQLERRM;
					ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgDelete);

					msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgDelete;
			/* end delete UMM_A_HKMLK */
			END;

			IF pbIds IS NOT NULL THEN
				/* delete IND_KUMPLN_PIHK_BKPTG */
				BEGIN
					EXECUTE IMMEDIATE 'DELETE FROM IND_KUMPLN_PIHK_BKPTG WHERE PIHAK_BKPTG_ID IN ('|| pbIds ||')';
				EXCEPTION
					WHEN OTHERS THEN
						errMsgDelete := 'delete IND_KUMPLN_PIHK_BKPTG B4ASAS ID:' ||  B4ASAS.BORANG4_ASAS_ID || ' versiDhdId:' 
										|| versiDhdId || SQLERRM;
						ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgDelete);

						msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgDelete;
				/* end delete IND_KUMPLN_PIHK_BKPTG */
				END;
			END IF;

			IF warisIds IS NOT NULL THEN
				/* delete IND_WARIS */
				BEGIN
					EXECUTE IMMEDIATE 'DELETE FROM IND_WARIS WHERE WARIS_ID IN ('|| warisIds ||')';
				EXCEPTION
					WHEN OTHERS THEN
						errMsgDelete := 'delete IND_WARIS B4ASAS ID:' ||  B4ASAS.BORANG4_ASAS_ID || ' versiDhdId:'
										|| versiDhdId || 'using warisId :' || warisIds || ' |' || SQLERRM;
						ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgDelete);

						msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgDelete;
				/* end delete IND_WARIS */
				END;
			END IF;

			IF pbIds IS NOT NULL THEN
				/* delete IND_PIHAK_BKPTG */
				BEGIN
					EXECUTE IMMEDIATE 'DELETE FROM IND_PIHAK_BKPTG WHERE PIHAK_BKPTG_ID IN ('|| pbIds ||')';
				EXCEPTION
					WHEN OTHERS THEN
						errMsgDelete := 'delete IND_PIHAK_BKPTG B4ASAS ID:' ||  B4ASAS.BORANG4_ASAS_ID || ' versiDhdId:' 
										|| versiDhdId || SQLERRM;
						ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgDelete);

						msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgDelete;
				/* end delete IND_PIHAK_BKPTG */
				END;
			END IF;

			/* delete IND_XML_REKOD_URUSAN */
			/* 08/10/18 Azrilisam
            BEGIN
				DELETE FROM IND_XML_REKOD_URUSAN WHERE REKOD_URSN_ID IN (SELECT REKOD_URSN_ID FROM IND_REKOD_URSN WHERE VERSI_AKHIR_ID = versiDhdId);				
			EXCEPTION
					WHEN OTHERS THEN
						errMsgDelete := 'delete IND_XML_REKOD_URUSAN B4ASAS ID:' ||  B4ASAS.BORANG4_ASAS_ID || ' versiDhdId:' 
										|| versiDhdId || SQLERRM;
						ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK',errMsgDelete);

						msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgDelete;
			END;
			*/
			/* delete IND_REKOD_URSN */
			BEGIN
				DELETE FROM IND_REKOD_URSN WHERE VERSI_AKHIR_ID = versiDhdId  and created_by = 'MIGRATOR_S';
			EXCEPTION
					WHEN OTHERS THEN
						errMsgDelete := 'delete IND_REKOD_URSN B4ASAS ID:' ||  B4ASAS.BORANG4_ASAS_ID || ' versiDhdId:' 
										|| versiDhdId || SQLERRM;
						ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgDelete);

						msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgDelete;
			END;

			/* delete SKG_DOK */
			BEGIN
				DELETE FROM SKG_DOK WHERE MEDAN_ID = medanIdIndPelan AND MEDAN_PK_ID IN (SELECT PELAN_ID FROM IND_PELAN WHERE VERSI_AKHIR_ID = versiDhdId  and created_by = 'MIGRATOR_S');
			EXCEPTION
				WHEN OTHERS THEN
					errMsgDelete := 'delete SKG_DOK B4ASAS ID:' ||  B4ASAS.BORANG4_ASAS_ID || ' versiDhdId:' 
									|| versiDhdId || SQLERRM;
					ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgDelete);

					msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgDelete;
			/* end delete IND_PELAN */
			END;

			/* delete IND_STR_PTK_AKSESORI */
			BEGIN
				DELETE FROM IND_STRATA_PTK_AKSESORI WHERE VERSI_AKHIR_ID = versiDhdId  and created_by = 'MIGRATOR_S';
			EXCEPTION
				WHEN OTHERS THEN
					errMsgDelete := 'delete IND_STR_PTK_AKSESORI B4ASAS ID:' ||  B4ASAS.BORANG4_ASAS_ID || ' versiDhdId:' 
									|| versiDhdId || SQLERRM;
					ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgDelete);

					msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgDelete;
			/* end delete IND_STR_PTK_AKSESORI */
			END;

			/* delete IND_PELAN */
			BEGIN
				DELETE FROM IND_PELAN WHERE VERSI_AKHIR_ID = versiDhdId  and created_by = 'MIGRATOR_S';
			EXCEPTION
				WHEN OTHERS THEN
					errMsgDelete := 'delete IND_PELAN B4ASAS ID:' ||  B4ASAS.BORANG4_ASAS_ID || ' versiDhdId:' 
									|| versiDhdId || SQLERRM;
					ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgDelete);

					msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgDelete;
			/* end delete IND_PELAN */
			END;

		/* end block to delete all child data*/
		END;

		DECLARE
			borang2 ET_DMSA.BORANG2_ASAS%ROWTYPE;
			namaMc IND_PIHAK_BKPTG.NAMA%TYPE;
			alamatMc1 IND_PIHAK_BKPTG.ALAMAT_DAFTAR1%TYPE;
			poskodMc IND_PIHAK_BKPTG.POSKOD_DAFTAR%TYPE;
			bandarMcId NUMBER(19,0);
			bandarLainMc IND_PIHAK_BKPTG.BANDAR_DAFTAR_LAIN%TYPE;
			negeriMcId NUMBER(19,0);
			bandarPDokId NUMBER(19,0);
			negeriPDokId NUMBER(19,0);
			bandarLainPDok IND_PIHAK_BKPTG.BANDAR_DAFTAR_LAIN%TYPE;--IND_PIHAK_BKPTG.BANDAR_LAIN%TYPE;
		/* block IND_PIHAK_BKPTG for MC, IND_STR_IDX, IND_STR_IDX_VERSI */
		BEGIN

			/* IND_PIHAK_BKPTG for MC */
			DECLARE
				errMsgPbMc VARCHAR2(250);
				bandarMcKod ET_DMSA.RJK_SENARAI_AHLI_KUMPULAN.KOD%TYPE;
				bandarMcNama ET_DMSA.RJK_SENARAI_AHLI_KUMPULAN.NAMA%TYPE;
				bandarPDokKod ET_DMSA.RJK_SENARAI_AHLI_KUMPULAN.KOD%TYPE;
				bandarPDokNama ET_DMSA.RJK_SENARAI_AHLI_KUMPULAN.NAMA%TYPE;
			BEGIN

				borang2 := getBorang2ByIdHakmilik(idHakmilikStrataInduk);
				namaMc := returnSpaceIfNull(borang2.NAMA_MC);
				alamatMc1 := returnSpaceIfNull(borang2.ALAMAT1_MC);
				poskodMc := returnSpaceIfNull(borang2.POSKOD_MC);
				
				loccode := 'PYM1';

				
				IF borang2.NEGERI_ID_PENYAMPAIAN_DOK IS NOT NULL THEN 
				
					negeriPDokId := getSakIdByDmsaSakId(borang2.NEGERI_ID_PENYAMPAIAN_DOK,'BORANG2.NEGERI_ID_PENYAMPAIAN_DOK','NEGERI');
				ELSE
					negeriPDokId := NULL;
				END IF;
				
				loccode := 'PYM2';

				IF borang2.BANDAR_ID_MC IS NOT NULL THEN
					SELECT KOD, NAMA INTO bandarMcKod, bandarMcNama
					FROM ET_DMSA.RJK_SENARAI_AHLI_KUMPULAN WHERE SENARAI_AHLI_KUMPULAN_ID = borang2.BANDAR_ID_MC;
				ELSE 
					bandarMcNama := NULL;
					bandarMcKod := NULL;
				END IF;
				
				
				loccode := 'PYM3';

				IF bandarMcKod IS NOT NULL THEN 
					bandarMcId := getSakIdByDmsaSakKod(bandarMcKod, 'BORANG2.BANDAR_ID_MC','BANDAR');
				END IF;
				
				
				loccode := 'PYM4';

				IF bandarMcId IS NULL THEN
					bandarLainMc := bandarMcNama;
					bandarMcId := bandarTiada;
				END IF;

				IF borang2.NEGERI_ID_MC IS NOT NULL THEN 
					negeriMcId := getSakIdByDmsaSakId(borang2.NEGERI_ID_MC, 'BORANG2.NEGERI_ID_MC','NEGERI');
				ELSE
					negeriMcId := negeriTiada;
				END IF;
				
				
				loccode := 'PYM5' || borang2.NEGERI_ID_MC;

				IF borang2.BANDAR_ID_PENYAMPAIAN_DOK IS NOT NULL THEN
					SELECT KOD, NAMA INTO bandarPDokKod, bandarPDokNama
					FROM ET_DMSA.RJK_SENARAI_AHLI_KUMPULAN WHERE SENARAI_AHLI_KUMPULAN_ID = borang2.BANDAR_ID_PENYAMPAIAN_DOK;
				ELSE 
					bandarPDokNama := NULL;
					bandarPDokKod := NULL;
				END IF;
				
				
				loccode := 'PYM6';

				IF bandarPDokKod IS NOT NULL THEN 
					bandarPDokId := getSakIdByDmsaSakKod(bandarPDokKod, 'BORANG2.BANDAR_ID_PENYAMPAIAN_DOK','BANDAR');
				END IF;

				IF bandarPDokId IS NULL AND bandarPDokKod IS NOT NULL THEN
					bandarLainPDok := bandarPDokNama;
					bandarPDokId := bandarTiada;
				ELSE
					bandarLainPDok := NULL;
					bandarPDokId := NULL;
				END IF;
				
				
				loccode := 'PYM7' || borang2.NEGERI_ID_MC;

				INSERT INTO IND_PIHAK_BKPTG( PIHAK_BKPTG_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
											VERSION, NAMA, ALAMAT_DAFTAR1, ALAMAT_DAFTAR2, ALAMAT_DAFTAR3, 
											ALAMAT_DAFTAR4, POSKOD_DAFTAR, BANDAR_DAFTAR_ID, BANDAR_DAFTAR_LAIN, NEGERI_DAFTAR_ID,
											/*
                      ALAMAT, ALAMAT2, ALAMAT3, ALAMAT4, POSKOD,
											BANDAR_ID, BANDAR_LAIN, NEGERI_ID,*/
                      JNS_PIHAK_BKPTG_ID, JNS_NO_ID,
											NO_KP, VERSI_MULA, VERSI_AKHIR_ID, FLAG_KUATKUASA)--, HKMLK_ID)
					VALUES(SEQ_PIHAK_BKPTG.NEXTVAL, username, sysdate, username, sysdate,
							0, namaMc, alamatMc1, borang2.ALAMAT2_MC, borang2.ALAMAT3_MC,
							borang2.ALAMAT4_MC, poskodMc, bandarMcId, bandarLainMc, negeriMcId,
							/*
              borang2.ALAMAT1_PENYAMPAIAN_DOK, borang2.ALAMAT2_PENYAMPAIAN_DOK, borang2.ALAMAT3_PENYAMPAIAN_DOK, 
							borang2.ALAMAT4_PENYAMPAIAN_DOK, borang2.POSKOD_PENYAMPAIAN_DOK,
							bandarPDokId, bandarLainPDok, negeriPDokId,*/
              jenisPbMc, jenisPengenalanTiada,
							' ', versiDhdId, versiDhdId, 'Y');--, hakmilikId);
				
				
				loccode := 'PYM8';
				
			EXCEPTION
				WHEN noBorang2Match THEN
					errMsgPbMc := 'IND_PIHK_BKPTG FOR PB MC NO MATCHING B2 FOR THIS HAKMILIK:' ||idHakmilikStrataInduk|| ' '
									||'B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID;
					ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgPbMc);

					msgNotifyUser := msgNotifyUser || ' ***** Tidak dapat maklumat MC dari Borang 2. Sila pasti Borang 2 telah wujud/migrasi.';

				WHEN OTHERS THEN
					errMsgPbMc := 'IND_PIHK_BKPTG FOR PB MC B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || SQLERRM;
					ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgPbMc);

					msgNotifyUser := msgNotifyUser || ' ***** Sila pasti nama MC diisi / alamat MC tidak melebihi 80 characters. ' || SQLERRM || ':' || loccode ;
			/* end IND_PIHAK_BKPTG for MC */
			END;
		/* end block IND_PIHAK_BKPTG for MC, IND_STR_IDX, IND_STR_IDX_VERSI */
		END;
        
        /* C_B4PEMILIK - ET_DMSA.BORANG4_SENARAI_PEMILIK */
		DECLARE
			CURSOR C_B4PEMILIK IS 
				SELECT * FROM ET_DMSA.BORANG4_SENARAI_PEMILIK b4p 
				WHERE b4p.BORANG4_ASAS_ID = B4ASAS.BORANG4_ASAS_ID;
		BEGIN

			/* loop to record all noKumpulan used along with no of pb using each noKumpulan */
			FOR B4PEMILIK IN C_B4PEMILIK LOOP
				IF B4PEMILIK.KUMPULAN_PIHAK_BKPTGN IS NOT NULL THEN

					DECLARE
						kumpulanPb NUMBER;
					BEGIN
						kumpulanPb := kumpulanPb_tbl(B4PEMILIK.KUMPULAN_PIHAK_BKPTGN);
						IF kumpulanPb IS NOT NULL THEN
							kumpulanPb_tbl(B4PEMILIK.KUMPULAN_PIHAK_BKPTGN) := kumpulanPb + 1;
						ELSE
							kumpulanPb_tbl(B4PEMILIK.KUMPULAN_PIHAK_BKPTGN) := 1;
						END IF;
					EXCEPTION
						WHEN NO_DATA_FOUND THEN
							kumpulanPb_tbl(B4PEMILIK.KUMPULAN_PIHAK_BKPTGN) := 1;
							ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'insert into kumpulanPb_tbl('|| B4PEMILIK.KUMPULAN_PIHAK_BKPTGN ||')');
							CONTINUE;
						WHEN OTHERS THEN
							ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'ERROR INITIALIZING kumpulanPb_tbl'||SQLERRM);
							EXIT;
					END;

				END IF;
			END LOOP;

			/* loop to start insert pemilik from b4 senarai pemilik */
			FOR B4PEMILIK IN C_B4PEMILIK LOOP
                                
				DECLARE
					CURSOR C_B4PEMILIK_WARIS IS 
						SELECT * FROM ET_DMSA.BORANG4_PEMILIK_WARIS b4w 
						WHERE b4w.BORANG4_SENARAI_PEMILIK_ID = B4PEMILIK.BORANG4_SENARAI_PEMILIK_ID;

					errMsgPemilik VARCHAR2(4000);
					pbIndukId NUMBER(19,0);
					tableName VARCHAR2(100);

					alamatDaftar1 IND_PIHAK_BKPTG.ALAMAT_DAFTAR1%TYPE;
					bandarDaftarKod ET_DMSA.RJK_SENARAI_AHLI_KUMPULAN.KOD%TYPE;
					bandarDaftarNama ET_DMSA.RJK_SENARAI_AHLI_KUMPULAN.NAMA%TYPE;
					bandarDaftarId NUMBER(19,0);
					bandarDaftarLain IND_PIHAK_BKPTG.BANDAR_DAFTAR_LAIN%TYPE;
					negeriDaftarId NUMBER(19,0);
					poskodDaftar IND_PIHAK_BKPTG.POSKOD_DAFTAR%TYPE;
					jenisNoId NUMBER(19,0);
					noKp IND_PIHAK_BKPTG.NO_KP%TYPE;
					jenisNoKpLamaId NUMBER(19,0);
					warganegaraId NUMBER(19,0);
					jenisPbId NUMBER(19,0);

					warisCount NUMBER(19,0);
					noKumpulan NUMBER;
					groupIdExisted VARCHAR2(2);

					aplikasiIdForPb NUMBER(19,0);

				/* IND_PIHAK_BKPTG */
				BEGIN
					warisCount := 0;
					alamatDaftar1 := returnSpaceIfNull(B4PEMILIK.ALAMAT1);
					poskodDaftar := returnSpaceIfNull(B4PEMILIK.POSKOD);
					noKp := returnSpaceIfNull(B4PEMILIK.NO_PENGENALAN);

					IF B4PEMILIK.BANDAR_ID IS NOT NULL THEN
						SELECT KOD, NAMA INTO bandarDaftarKod, bandarDaftarNama
						FROM ET_DMSA.RJK_SENARAI_AHLI_KUMPULAN WHERE SENARAI_AHLI_KUMPULAN_ID = B4PEMILIK.BANDAR_ID;
					ELSE 
						bandarDaftarNama := NULL;
						bandarDaftarKod := NULL;
					END IF;
					
					loccode := 'before BANDAR';

					IF bandarDaftarKod IS NOT NULL THEN 
						bandarDaftarId := getSakIdByDmsaSakKod(bandarDaftarKod, 'B4PEMILIK.BANDAR_ID','BANDAR');
					END IF;

					IF bandarDaftarId IS NULL THEN
						bandarDaftarLain := bandarDaftarNama;
						bandarDaftarId := bandarTiada;
					END IF;
					
					loccode := 'before NEGERI';

					IF B4PEMILIK.NEGERI_ID IS NOT NULL THEN 
						negeriDaftarId := getSakIdByDmsaSakId(B4PEMILIK.NEGERI_ID, 'B4PEMILIK.NEGERI_ID','NEGERI');
					ELSE
						negeriDaftarId := negeriTiada;
					END IF;
					
					
					loccode := 'before JENIS_NOP';

					IF B4PEMILIK.JENIS_NO_PENGENALAN IS NOT NULL THEN
						jenisNoId := getSakIdByDmsaSakId(B4PEMILIK.JENIS_NO_PENGENALAN, 'B4PEMILIK.JENIS_NO_PENGENALAN','JENIS_NOP');
					ELSE 
						jenisNoId := jenisPengenalanTiada;
					END IF;
					
					
					
					loccode := 'before WARGANEGARA';

					IF B4PEMILIK.WARGANEGARA_ID IS NOT NULL THEN
						warganegaraId := getSakIdByDmsaSakId(B4PEMILIK.WARGANEGARA_ID, 'B4PEMILIK.WARGANEGARA_ID','WARGANEGARA');
					ELSE 
						warganegaraId := NULL;
					END IF;
					
					loccode := 'before JENIS_NOP 2';

					IF B4PEMILIK.JENIS_NO_PENGENALAN2 IS NOT NULL THEN
						jenisNoKpLamaId := getSakIdByDmsaSakId(B4PEMILIK.JENIS_NO_PENGENALAN2, 'B4PEMILIK.JENIS_NO_PENGENALAN2','JENIS_NOP');
					ELSE
						jenisNoKpLamaId := NULL;
					END IF;
					
					loccode := 'before JEN_PHKBKPTGN';

					IF B4PEMILIK.JENIS_PIHAK_BKPTGN IS NOT NULL THEN
						jenisPbId := getSakIdByDmsaSakId(B4PEMILIK.JENIS_PIHAK_BKPTGN, 'B4PEMILIK.JENIS_PIHAK_BKPTGN','JEN_PHKBKPTGN');
					ELSE 
						jenisPbId := jenisPbTiada;
					END IF;
					
					loccode := 'AFTER JEN_PHKBKPTGN';

					/* find the aplikasi id for the pemilik*/
					DECLARE
						noOfAplikasiForPb NUMBER(19,0);
						noOfAppHakmilik NUMBER(19,0);
						jenisUrusanKod RJK_SENARAI_AHLI_KUMPULAN.KOD%TYPE;
						kategoriHakmilikNama RJK_SENARAI_AHLI_KUMPULAN.NAMA%TYPE;
						urusanId NUMBER(19,0);
						kodUrusan IND_URSN.KOD%TYPE;
						idPengenalanForPb UMM_APLIKASI.ID_PENGENALAN%TYPE;
						mh IND_MKLMT_HKMLK%ROWTYPE;
						actionSearch VARCHAR2(150);

						yrhtb varchar2(5);
					BEGIN
						noOfAplikasiForPb := 0;
						noOfAppHakmilik := 0;
					
					
						loccode := 'before testing B4PEMILIK.NO_SERAHAN IS NOT NULL THEN';

						IF B4PEMILIK.NO_SERAHAN IS NOT NULL THEN
						
								IF(trim(B4PEMILIK.NO_SERAHAN) = '00000') then
									
					
									loccode := 'enter trim(B4PEMILIK.NO_SERAHAN) = 00000';
									jenisUrusanKod := 'SC';
									
									urusanId := 464;
									kodUrusan := 'PP';

									select yr into yrhtb from (
										select 
										right(ps.id_pengenalan,5) yr
										from 
										ind_hkmlk hm ,
										ind_hkmlk hs , ind_versi_dhd ds , ind_rekod_ursn rs , umm_aplikasi  ps , ind_ursn us
										where 
										
										hm.strata_induk_id = hs.hkmlk_id and ds.hkmlk_id = hs.hkmlk_id and ds.versi_dhd_id = rs.versi_akhir_id (+) 
										and rs.aplikasi_id = ps.aplikasi_id(+) and ps.ursn_id = us.ursn_id(+)
										and (us.kod = 'HTB' )
										and hm.id_hkmlk = arg_hakmilik_id
										
										union 
										select null yr from dual
										) limit 1
										;
									
									idPengenalanForPb := pejabatKod || jenisUrusanKod || yrhtb;
									
									B4PEMILIK.TARIKH_SERAHAN := TO_DATE('1900-01-01', 'YYYY-MM-DD');
								
								else
								
									loccode := 'enter trim(B4PEMILIK.NO_SERAHAN) <> 00000';
									
									SELECT KOD  INTO jenisUrusanKod 
									FROM RJK_JNS_URSN
									WHERE JNS_URSN_ID = (SELECT JNS_URSN_ID 
														FROM IND_URSN 
														WHERE KOD = (SELECT KOD 
																	 FROM ET_DMSA.RJK_SENARAI_AHLI_KUMPULAN 
																	 WHERE SENARAI_AHLI_KUMPULAN_ID = B4PEMILIK.JENIS_URUSAN ));
								
									SELECT URSN_ID, KOD INTO urusanId, kodUrusan FROM IND_URSN 
									WHERE KOD = (SELECT KOD FROM ET_DMSA.RJK_SENARAI_AHLI_KUMPULAN WHERE SENARAI_AHLI_KUMPULAN_ID = B4PEMILIK.JENIS_URUSAN);

								
									--idPengenalanForPb := kategoriHakmilikNama || jenisUrusanKod || replace(replace(trim(B4PEMILIK.NO_SERAHAN), ' ', ''), chr(9)) ;
									idPengenalanForPb := pejabatKod || jenisUrusanKod || replace(replace(trim(B4PEMILIK.NO_SERAHAN), ' ', ''), chr(9)) ;

	
								end if;
							
								loccode := 'SELECT NAMA INTO kategoriHakmilikNama ';

								SELECT NAMA INTO kategoriHakmilikNama 
                                            FROM RJK_SENARAI_AHLI_KUMPULAN 
                                            WHERE STRATA_KOD = (SELECT KOD 
                                                                FROM ET_DMSA.RJK_SENARAI_AHLI_KUMPULAN 
                                                                WHERE SENARAI_AHLI_KUMPULAN_ID = B4ASAS.KATEGORI_HAKMILIK);
																
								actionSearch := 'Search total aplikasi based on id pengenalan ';
								
								SELECT COUNT(APLIKASI_ID) into noOfAplikasiForPb FROM UMM_APLIKASI WHERE ID_PENGENALAN = idPengenalanForPb;
							
								loccode := 'SELECT COUNT(APLIKASI_ID) ';

								IF (noOfAplikasiForPb < 1) then
									loccode := 'noOfAplikasiForPb < 1';
									INSERT INTO UMM_APLIKASI(APLIKASI_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
														VERSION, FLAG_PERTANYAAN, TRKH_TAMAT, STATUS_KEPUTUSAN, STATUS_PROSES,
														PEJABAT_ID, ID_PENGENALAN, NO_FOLIO, NO_JILID, TRKH_SERAHAN,
														URSN_ID, NO_RUJUKAN_FAIL)
												VALUES(SEQ_APLIKASI.NEXTVAL, username, sysdate, username, sysdate,
														0, 'N', B4PEMILIK.TARIKH_SERAHAN, 'Daftar', 'Tamat',
														pejabatId, idPengenalanForPb, B4PEMILIK.NO_FOLIO, B4PEMILIK.NO_JILID, B4PEMILIK.TARIKH_SERAHAN,
														urusanId, null) RETURNING APLIKASI_ID INTO aplikasiIdForPb;										
								else
									loccode := 'noOfAplikasiForPb >= 1';
									actionSearch := 'Search aplikasi based on existing id pengenalan ';
									SELECT APLIKASI_ID INTO aplikasiIdForPb FROM UMM_APLIKASI WHERE ID_PENGENALAN = idPengenalanForPb;

                                    UPDATE UMM_APLIKASI 
                                        SET 
                                            LAST_MODIFIED_BY = username, 
                                            LAST_MODIFIED_DATE = sysdate, 
                                            TRKH_SERAHAN = B4PEMILIK.TARIKH_SERAHAN, 
                                            NO_FOLIO = B4PEMILIK.NO_FOLIO, 
                                            NO_JILID = B4PEMILIK.NO_JILID
                                        WHERE APLIKASI_ID = aplikasiIdForPb AND CREATED_BY='MIGRATOR_S';
								END IF;

								actionSearch := 'Search total app hakmilik based on aplikasi id and id hakmilik ';
								SELECT COUNT(A_HKMLK_ID) into noOfAppHakmilik FROM UMM_A_HKMLK WHERE APLIKASI_ID = aplikasiIdForPb AND ID_HKMLK = idHakmilik;
								loccode := 'SELECT COUNT(A_HKMLK_ID)';
								IF (noOfAppHakmilik < 1) then
									loccode := 'noOfAppHakmilik < 1';
									actionSearch := 'Search maklumat hakmilik ';
									SELECT * INTO mh FROM IND_MKLMT_HKMLK WHERE MKLMT_HKMLK_ID = maklumatHakmilikId;
									INSERT INTO MIG_LOG3(id_hakmilik,message,log_time)values(idHakmilik,'insert 1',sysdate);			
									INSERT INTO UMM_A_HKMLK (A_HKMLK_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
															VERSION, ID_HKMLK, APLIKASI_ID, JNS_HKMLK_ID, STATUS_HKMLK_ID,
															JNS_TNH_ID, KAT_ID, TARAF_MILIK_ID, SEKSYEN_ID, UNIT_LOT_ID,
															UNIT_LUAS_ID, UNIT_KADAR_CUKAI_ID, UNIT_SYER, KADAR_CUKAI, LUAS,
															NO_BANGUNAN, NO_TINGKAT, NO_PTK, NO_LOT, TEMPOH_PAJAKAN,
															TRKH_DAFTAR, TRKH_LUPUT, SKTN_KPTGN_ID, SYRT_NYATA_ID, LOKASI)
											VALUES(SEQ_A_HKMLK.NEXTVAL, username, SYSDATE, username, SYSDATE,
													'0', idHakmilik, aplikasiIdForPb, jenisHakmilikId, mh.STATUS_HKMLK_ID,
													mh.JNS_TNH_ID, mh.KAT_ID, mh.TARAF_MILIK_ID, mh.SEKSYEN_ID, mh.UNIT_LOT_ID,
													mh.UNIT_LUAS_ID, mh.UNIT_KADAR_CUKAI_ID, mh.UNIT_SYER, mh.KADAR_CUKAI, mh.LUAS,
													noBgnn, noTing, noPetak, mh.NO_LOT, mh.TEMPOH_PAJAKAN,
													mh.TRKH_DAFTAR, mh.TRKH_LUPUT, mh.SKTN_KPTGN_ID, mh.SYRT_NYATA_ID, mh.LOKASI);

								
							END IF;
						END IF;
					EXCEPTION
						WHEN appMoreThanOne THEN
							errMsgPemilik := 'APLIKASI - IND_PIHAK_BKPTG | MORE THAN ONE APP FOR SENARAI PEMILIK B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' B4PEMILIK ID:' ||
								B4PEMILIK.BORANG4_SENARAI_PEMILIK_ID || ' ' || SQLERRM || ':lcc:' || loccode; 
							ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgPemilik);

							msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team. ' || errMsgPemilik;

						WHEN OTHERS THEN
							errMsgPemilik := 'APLIKASI - IND_PIHAK_BKPTG FOR SENARAI PEMILIK (' || actionSearch || ') B4ASAS ID:' || 
								B4ASAS.BORANG4_ASAS_ID || ' B4PEMILIK ID:' || B4PEMILIK.BORANG4_SENARAI_PEMILIK_ID || ' ' || SQLERRM || ':lcc:' || loccode;  
							ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgPemilik);

							msgNotifyUser := msgNotifyUser || ' ***** Sila pasti no / masa dan tarikh serahan diisi untuk pemilik jika perlu. ' || errMsgPemilik;	
					END;
					ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'induk pb - aplikasi done');
					/* end find the aplikasi id for pemilik*/
				
					--loccode := 'before INSERT INTO IND_PIHAK_BKPTG' || B4PEMILIK.BORANG4_SENARAI_PEMILIK_ID || ':bandarDaftarLain:' || length(bandarDaftarLain)
								
				    --loccode := 'before INSERT INTO IND_PIHAK_BKPTG' ;
					loccode := 'before INSERT INTO IND_PIHAK_BKPTG' ||   ':B4PEMILIK.bandarDaftarLain:' || bandarDaftarLain;
					--log.info("alamatDaftar1:" || alamatDaftar1);
				
					loccode := ' 9' || aplikasiIdForPb;
				/**, B4PEMILIK.ALAMAT4,
								B4PEMILIK.NAMA, jenisPbId, noKp, poskodDaftar, bandarDaftarId,
								jenisNoId, negeriDaftarId, B4PEMILIK.ADALAH_KUATKUASA, versiDhdId, versiDhdId,
								B4PEMILIK.SYER_PEMBILANG, B4PEMILIK.SYER_PENYEBUT, warganegaraId, B4PEMILIK.NO_PENGENALAN2, jenisNoKpLamaId,
								0, username, sysdate, username, sysdate, bandarDaftarLain,
								aplikasiIdForPb)  
					**/
					
					INSERT INTO IND_PIHAK_BKPTG( PIHAK_BKPTG_ID, ALAMAT_DAFTAR1, ALAMAT_DAFTAR2, ALAMAT_DAFTAR3, ALAMAT_DAFTAR4,
								NAMA, JNS_PIHAK_BKPTG_ID, NO_KP, POSKOD_DAFTAR, BANDAR_DAFTAR_ID,
								JNS_NO_ID, NEGERI_DAFTAR_ID, FLAG_KUATKUASA, VERSI_MULA, VERSI_AKHIR_ID,
								SYER_PEMBILANG, SYER_PENYEBUT, WARGANEGARA_ID, NO_KP_LAMA, JNS_NO_KP_LAMA_ID,
								VERSION, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE, BANDAR_DAFTAR_LAIN,
								APLIKASI_ID)--, HKMLK_ID)
						VALUES ( SEQ_PIHAK_BKPTG.NEXTVAL, substr(alamatDaftar1,1,254), B4PEMILIK.ALAMAT2, B4PEMILIK.ALAMAT3, B4PEMILIK.ALAMAT4,
								B4PEMILIK.NAMA, jenisPbId, noKp, poskodDaftar, bandarDaftarId,
								jenisNoId, negeriDaftarId, B4PEMILIK.ADALAH_KUATKUASA, versiDhdId, versiDhdId,
								B4PEMILIK.SYER_PEMBILANG, B4PEMILIK.SYER_PENYEBUT, warganegaraId, B4PEMILIK.NO_PENGENALAN2, jenisNoKpLamaId,
								0, username, sysdate, username, sysdate, bandarDaftarLain,
								aplikasiIdForPb); --, hakmilikId); 
					
					/**INSERT INTO IND_PIHAK_BKPTG( PIHAK_BKPTG_ID, ALAMAT_DAFTAR1, ALAMAT_DAFTAR2, ALAMAT_DAFTAR3, ALAMAT_DAFTAR4,
								NAMA, JNS_PIHAK_BKPTG_ID, NO_KP, POSKOD_DAFTAR, BANDAR_DAFTAR_ID,
								JNS_NO_ID, NEGERI_DAFTAR_ID, FLAG_KUATKUASA, VERSI_MULA, VERSI_AKHIR_ID,
								SYER_PEMBILANG, SYER_PENYEBUT, WARGANEGARA_ID, NO_KP_LAMA, JNS_NO_KP_LAMA_ID,
								VERSION, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE, BANDAR_DAFTAR_LAIN,
								APLIKASI_ID) 
							
						VALUES ( SEQ_PIHAK_BKPTG.NEXTVAL, '-', ' -', '-', '-',
								'xB4PEMILIK.NAMA', 625, 'noKp', '12345', 10,
								10, 10, 'Y', 1, 1,
								1, 1, 10, '123', 10,
								0, 'username', current_timestamp, 'username', current_timestamp, 'bandarDaftarLain',
								aplikasiIdForPb); --, hakmilikId);**/
								
							
					--raise Debug 'PB: ' || B4PEMILIK.BORANG4_SENARAI_PEMILIK_ID;
					
					loccode := 'before pemilik_tbl ' ;
								
					pemilik_tbl(B4PEMILIK.BORANG4_SENARAI_PEMILIK_ID) := SEQ_PIHAK_BKPTG.CURRVAL;
				
					loccode := 'after pemilik_tbl';
					pbIndukId := SEQ_PIHAK_BKPTG.CURRVAL;
					loccode := 'AFTER INSERT INTO IND_PIHAK_BKPTG';

					SELECT COUNT(*) INTO warisCount FROM ET_DMSA.BORANG4_PEMILIK_WARIS b4w 
					WHERE b4w.BORANG4_SENARAI_PEMILIK_ID = B4PEMILIK.BORANG4_SENARAI_PEMILIK_ID;

					noKumpulan := B4PEMILIK.KUMPULAN_PIHAK_BKPTGN;
					ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'warisCount' || warisCount || ' noKumpulan' || noKumpulan);
					loccode := 'IF warisCount > 0 AND noKumpulan IS NULL THEN';
					
					IF warisCount > 0 AND noKumpulan IS NULL THEN
						groupIdExisted := 'Y';
						noKumpulan := 1;
						/* loop find unused no kumpulan by incrementing index */
						WHILE groupIdExisted = 'Y' LOOP
							DECLARE
								noOfPbPerKumpulan NUMBER;
							BEGIN
								noOfPbPerKumpulan := kumpulanPb_tbl(noKumpulan);
								IF noOfPbPerKumpulan IS NOT NULL THEN
									noKumpulan := noKumpulan + 1;
								END IF;
							EXCEPTION
								WHEN NO_DATA_FOUND THEN
									groupIdExisted := 'N';
									kumpulanPb_tbl(noKumpulan) := 1;
								WHEN OTHERS THEN
									ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'ERROR GENERATING NEW NO KUMPULAN');
									EXIT;
							END;
						/* end loop find unused no kumpulan by incrementing index */
						END LOOP;
					END IF;

					/* insert into IND_KUMPLN_PIHK_BKPTG if there is no waris at all and no kumpulan is not null*/
					IF noKumpulan IS NOT NULL AND warisCount = 0 THEN
						DECLARE
							errorMsgKumpPb VARCHAR2(250);
						BEGIN
							INSERT INTO IND_KUMPLN_PIHK_BKPTG(KUMPLN_PIHK_BKPTG_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
																VERSION, PIHAK_BKPTG_ID, GROUP_ID)
								VALUES (SEQ_KUMPLN_PIHK_BKPTG.NEXTVAL, username, sysdate, username, sysdate,
										0,  pbIndukId, noKumpulan);

              				UPDATE IND_PIHAK_BKPTG SET ID_KUMPULAN = noKumpulan where PIHAK_BKPTG_ID = pbIndukId;

						EXCEPTION
							WHEN OTHERS THEN
								errorMsgKumpPb := 'IND_KUMPLN_PIHK_BKPTG B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' B4PEMILIK ID:' ||
												B4PEMILIK.BORANG4_SENARAI_PEMILIK_ID || ' ' || SQLERRM;
								ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errorMsgKumpPb);

								msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errorMsgKumpPb;
						END;
					END IF;
					
					/** using maklumat tambahan **/
					loccode := 'using maklumat tambahan';

					if warisCount>0 then
						update ind_pihak_bkptg
							set
							id_kumpulan = noKumpulan,
							 mklmt_tmbhn = 
							(
								WITH numbered_waris AS (
								    SELECT 
								        to_char(ROW_NUMBER() OVER (ORDER BY no_pengenalan)) AS id,
								        w.no_pengenalan,
								        se.kod,
								        w.nama
								    FROM et_dmsa.borang4_pemilik_waris  w , et_dmsa.rjk_senarai_ahli_kumpulan sk , rjk_senarai_ahli_kumpulan se
									where w.jenis_no_pengenalan = sk.senarai_ahli_kumpulan_id(+) AND se.strata_kod = sk.kod AND
									 w.borang4_senarai_pemilik_id = B4PEMILIK.BORANG4_SENARAI_PEMILIK_ID
								)
								SELECT JSON_OBJECT(
								    'warisList' VALUE (
								        SELECT JSON_ARRAYAGG(
								            JSON_OBJECT(
								                'id' VALUE id,
								                'noPengenalan' VALUE no_pengenalan,
								                'jenisNombor' VALUE kod,
								                'nama' VALUE nama
								            )
								        )
								        FROM numbered_waris
								    )
								) AS json_result
								
							)
						where  PIHAK_BKPTG_ID = pbIndukId;
					end if;
				
				
					loccode := 'after maklumat tambahan';


					/* start waris loop */
					FOR B4WARIS IN C_B4PEMILIK_WARIS LOOP

						DECLARE
							errMsgWaris VARCHAR2(250);
							tableName VARCHAR2(250);
							warisId NUMBER(19,0);
							jenisPengenalanId NUMBER(19,0);
							noPengenalan IND_WARIS.NO_KP%TYPE;
						/* IND_WARIS, IND_KUMPLN_PIHK_BKPTG */
						BEGIN
							IF B4WARIS.JENIS_NO_PENGENALAN IS NOT NULL THEN 
								jenisPengenalanId := getSakIdByDmsaSakId(B4WARIS.JENIS_NO_PENGENALAN, 'B4WARIS.JENIS_NO_PENGENALAN','JENIS_NOP');
							ELSE 
								jenisPengenalanId := jenisPengenalanTiada;
							END IF;

							noPengenalan := returnSpaceIfNull(B4WARIS.NO_PENGENALAN);
							tableName := 'IND_WARIS';
							INSERT INTO IND_WARIS(WARIS_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
													VERSION, NAMA, NO_KP, JNS_NO_KP_ID)
								VALUES (SEQ_WARIS.NEXTVAL, username, sysdate, username, sysdate,
										0, B4WARIS.NAMA, noPengenalan, jenisPengenalanId);
							warisId := SEQ_WARIS.CURRVAL;

							tableName := 'IND_KUMPLN_PIHK_BKPTG';
							INSERT INTO IND_KUMPLN_PIHK_BKPTG(KUMPLN_PIHK_BKPTG_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
																VERSION, GROUP_ID, PIHAK_BKPTG_ID, WARIS_ID)
								VALUES (SEQ_KUMPLN_PIHK_BKPTG.NEXTVAL, username, sysdate, username, sysdate,
								0, noKumpulan, pbIndukId, warisId);
							ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'nama waris:' || B4WARIS.NAMA || ' noKumpulan:' || noKumpulan);

						EXCEPTION
							WHEN OTHERS THEN
								errMsgWaris := tableName ||' B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' B4PEMILIK ID:' ||
									B4PEMILIK.BORANG4_SENARAI_PEMILIK_ID || ' ' || SQLERRM;
								ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgWaris);

								msgNotifyUser := msgNotifyUser || ' ***** Sila pasti nama waris diisi (DMSA) - ' || errMsgWaris;
						/* end IND_WARIS, IND_KUMPLN_PIHK_BKPTG */
						END;
					/* end loop waris */
					END LOOP;

				EXCEPTION
					WHEN OTHERS THEN
						errMsgPemilik := 'IND_PIHAK_BKPTG FOR SENARAI PEMILIK B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' B4PEMILIK ID:' ||
									B4PEMILIK.BORANG4_SENARAI_PEMILIK_ID || ' ' || SQLERRM; 
						ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgPemilik);

						msgNotifyUser := msgNotifyUser || ' ***** Sila pasti nama pemilik diisi (DMSA) - ' || errMsgPemilik;
						CONTINUE;
				END;
			/* end loop to start insert pemilik from b4 senarai pemilik */
			END LOOP;
		/* end IND_PIHAK_BKPTG */
		END;
		ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'All senarai pemilik done');

		loccode := 'C_B4_NO_PELAN';
		DECLARE
			CURSOR C_B4_NO_PELAN IS 
				SELECT * FROM ET_DMSA.BORANG4_NO_PELAN
				WHERE BORANG4_ASAS_ID = B4ASAS.BORANG4_ASAS_ID AND NO_PELAN IS NOT NULL;
		/* IND_PELAN */
		BEGIN
			FOR B4NP IN C_B4_NO_PELAN LOOP

				DECLARE
					noPelan VARCHAR2(200);
					errMsgNoPelan VARCHAR2(250);
					pelanId NUMBER(19,0);
					idDokumen VARCHAR2(255);
					errMsgIdDokumen VARCHAR2(250);

					bilSkgDok number(19,0);
				BEGIN
					noPelan := returnSpaceIfNull(B4NP.NO_PELAN);

					INSERT INTO IND_PELAN(PELAN_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
										VERSION, HKMLK_ID, JNS_PELAN_ID, NO_PELAN, VERSI_AKHIR_ID,
										VERSI_MULA)
							VALUES(SEQ_PELAN.NEXTVAL, username, sysdate, username, sysdate,
									0, hakmilikId, jenisPelanPetak, noPelan, versiDhdId, versiDhdId) RETURNING PELAN_ID INTO pelanId;
--					pelanId := SEQ_PELAN.CURRVAL;

					BEGIN

						SELECT count(*)  into bilSkgDok 
						FROM ET_DMS.DOKUMEN 
						WHERE REPLACE(NAMA_DOKUMEN, ' ','') = REPLACE(TRIM(idHakmilik) || '_' || noPelan, ' ','')
						AND DOKUMEN_ID = (SELECT MAX(DOKUMEN_ID) FROM ET_DMS.DOKUMEN 
						WHERE REPLACE(NAMA_DOKUMEN, ' ','') = REPLACE(TRIM(idHakmilik) || '_' || noPelan, ' ',''));
	
	SELECT ID_DOKUMEN into idDokumen FROM ET_DMS.DOKUMEN 
								WHERE REPLACE(NAMA_DOKUMEN, ' ','') = REPLACE(TRIM(idHakmilik) || '_' || noPelan, ' ','')
								AND DOKUMEN_ID = (SELECT MAX(DOKUMEN_ID) FROM ET_DMS.DOKUMEN 
															WHERE REPLACE(NAMA_DOKUMEN, ' ','') = REPLACE(TRIM(idHakmilik) || '_' || noPelan, ' ',''));

						--if(bilSkgDok > 0 ) then
								
					
						--else
						--	idDokumen := NULL;

						--end if;
					
				
						INSERT INTO SKG_DOK(DOK_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
										VERSION, MEDAN_ID, MEDAN_PK_ID, VERSI_DOK, FLAG_AKTIF, FLAG_DRAF,
										ID_DOK, JNS_FAIL, NAMA_FAIL, CATATAN)
						VALUES(SEQ_DOK.NEXTVAL, username, sysdate, username, sysdate,
								0, medanIdIndPelan, pelanId, 1, 'Y', 'N', 
								idDokumen, 'image/tiff', trim(idHakmilik) || '_' || noPelan, null);					
					EXCEPTION
						WHEN OTHERS THEN
						errMsgIdDokumen := 'SKG_DOK - IND_PELAN B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' B4NPELAN ID:' ||
											B4NP.BORANG4_NO_PELAN_ID || ' ' || SQLERRM; 
						ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgIdDokumen);
					END;								
				EXCEPTION
					WHEN OTHERS THEN
					errMsgNoPelan := 'IND_PELAN B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' B4NPELAN ID:' ||
								B4NP.BORANG4_NO_PELAN_ID || ' ' || SQLERRM; 
					ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgNoPelan);

					msgNotifyUser := msgNotifyUser || ' ***** Masalah migrasi senarai pelan - ' || errMsgNoPelan;
				END;
			END LOOP;
		/* end IND_PELAN */
		END;
		ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'All pelan done');
	
	
		loccode := 'C_B4_PETAK_AKS';

--		ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'indeksVersiIndukId :' || indeksVersiIndukId);
--		IF indeksVersiIndukId IS NOT NULL THEN 
			DECLARE
				CURSOR C_B4_PETAK_AKS IS 
					SELECT * FROM ET_DMSA.BORANG4_PETAK_AKSESORI
					WHERE BORANG4_ASAS_ID = B4ASAS.BORANG4_ASAS_ID AND PETAK_AKSESORI IS NOT NULL;
			/* outer block for petak aksesori */
			BEGIN
				/* loop for petak aksesori */
				FOR B4PA IN C_B4_PETAK_AKS LOOP

					DECLARE
--						lokasiPetakAksesori IND_STR_PETAK_AKSESORI.LOKASI%TYPE;
					/* inner block for petak aksesori */
					BEGIN

						DECLARE
							errMsgFindLokasi VARCHAR2(250);
							noPetakPAks ET_DMSA.BORANG4_PETAK_AKSESORI.PETAK_AKSESORI%TYPE;
--							lokasiBangunan ET_DMSA.BORANG2_PETAK_AKSESORI.LOKASI_NO_BANGUNAN%TYPE;
--							lokasiTingkat ET_DMSA.BORANG2_PETAK_AKSESORI.LOKASI_NO_TINGKAT%TYPE;
--							lokasiPetak ET_DMSA.BORANG2_PETAK_AKSESORI.LOKASI_NO_PETAK%TYPE;
						/* blok to find lokasi from Borang 2 */
						BEGIN
							noPetakPAks := REPLACE(TRIM(B4PA.PETAK_AKSESORI), '	');
--							lokasiPetakAksesori := NULL;
							IF noPetakPAks IS NULL THEN
								raise petaksAksIsNull;
							END IF;

--							SELECT p.LOKASI_NO_BANGUNAN, p.LOKASI_NO_TINGKAT, p.LOKASI_NO_PETAK
--							INTO lokasiBangunan, lokasiTingkat, lokasiPetak FROM ET_DMSA.BORANG2_PETAK_AKSESORI p
--							JOIN ET_DMSA.BORANG2_ASAS b2a ON (p.BORANG2_ASAS_ID = b2a.BORANG2_ASAS_ID)
--							WHERE TRIM(p.PETAK_AKSESORI) LIKE noPetakPAks AND b2a.HAKMILIK_ID = idHakmilikStrataInduk;

--							IF lokasiBangunan IS NOT NULL THEN
--								lokasiPetakAksesori := lokasiBangunan || '/';
--							END IF;
--							IF lokasiTingkat IS NOT NULL THEN
--								lokasiPetakAksesori := lokasiPetakAksesori || lokasiTingkat;
--							END IF;
--							IF lokasiPetak IS NOT NULL THEN
--								lokasiPetakAksesori := lokasiPetakAksesori || '/' || lokasiPetak;
--							END IF;
--							ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,lokasiPetakAksesori);
						EXCEPTION
--							WHEN NO_DATA_FOUND THEN
--								errMsgFindLokasi := 'ERROR FINDING LOKASI No match petak aksesori. noPetakPAks:' || noPetakPAks ||' B4ASAS ID:' 
--													|| B4ASAS.BORANG4_ASAS_ID || ' B4PETAKAKS ID:' || B4PA.BORANG4_PETAK_AKSESORI_ID;
--								ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgFindLokasi);

--							WHEN TOO_MANY_ROWS THEN
--								errMsgFindLokasi := 'ERROR FINDING LOKASI Too many match petak aksesori. noPetakPAks:' || noPetakPAks ||' B4ASAS ID:' 
--													|| B4ASAS.BORANG4_ASAS_ID || ' B4PETAKAKS ID:' || B4PA.BORANG4_PETAK_AKSESORI_ID;
--								ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgFindLokasi);

							WHEN petaksAksIsNull THEN
								errMsgFindLokasi := 'ERROR No Petak Aksesori is NULL. noPetakPAks:' || noPetakPAks ||' B4ASAS ID:' 
													|| B4ASAS.BORANG4_ASAS_ID || ' B4PETAKAKS ID:' || B4PA.BORANG4_PETAK_AKSESORI_ID;
								ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgFindLokasi);

								msgNotifyUser := msgNotifyUser || ' ***** ' || errMsgFindLokasi;

							WHEN OTHERS THEN
								errMsgFindLokasi := 'ERROR FINDING LOKASI. noPetakPAks:' || noPetakPAks ||' B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || 
													' B4PETAKAKS ID:' || B4PA.BORANG4_PETAK_AKSESORI_ID || ' ' || SQLERRM; 
								ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgFindLokasi);

								msgNotifyUser := msgNotifyUser || ' ***** ' || errMsgFindLokasi;	
						/* end blok to find lokasi from Borang 2 */
						END;

						DECLARE
							errMsgPetakAksesori VARCHAR(4250);
							namaPetakAksesori IND_STRATA_PTK_AKSESORI.NAMA%TYPE;
							noPelanForPetakAksesori ET_DMSA.BORANG4_PETAK_AKSESORI.NO_PELAN%TYPE;
							noPelanForIndPelan ET_DMSA.BORANG4_PETAK_AKSESORI.NO_PELAN%TYPE;
							PelanIDForPetakAksesori ET_DMSA.BORANG4_PETAK_AKSESORI.NO_PELAN%TYPE;
							noOfSamePelan NUMBER;
							pelanId NUMBER(19,0);
							idDokumen VARCHAR2(255);
							luasPetakAksesori NUMBER(16,4);
							unitLuasPetakAksesori NUMBER(19,0);

						/* IND_STR_PETAK_AKSESORI */
						BEGIN
								namaPetakAksesori := returnSpaceIfNull(B4PA.PETAK_AKSESORI);
								noPelanForPetakAksesori := TRIM(B4PA.NO_PELAN);

             /*Check if there is more than one PA(B) using instr function to check pipeline*/

      if noPelanForPetakAksesori is not null then              

            IF Instr(noPelanForPetakAksesorI, '|') = 0 THEN
              /*If no then use the existing code without changes*/ 

                      noPelanForIndPelan := TRIM(B4PA.NO_PELAN);

                          --IF noPelanForIndPelan IS NOT NULL THEN  -- Share Start
                        SELECT COUNT(PELAN_ID) into noOfSamePelan FROM IND_PELAN WHERE NO_PELAN = noPelanForIndPelan AND VERSI_AKHIR_ID = versiDhdId;

                          IF noOfSamePelan < 1 THEN
                          INSERT INTO IND_PELAN(PELAN_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
                                    VERSION, HKMLK_ID, JNS_PELAN_ID, NO_PELAN, VERSI_AKHIR_ID, VERSI_MULA)
                            VALUES(SEQ_PELAN.NEXTVAL, username, sysdate, username, sysdate,
                                0, hakmilikId, jenisPelanPetakAksesori, noPelanForIndPelan, versiDhdId, versiDhdId) 
                                RETURNING PELAN_ID INTO pelanId;

                          BEGIN
                            SELECT ID_DOKUMEN into idDokumen FROM ET_DMS.DOKUMEN 
                              WHERE REPLACE(NAMA_DOKUMEN, ' ','') = REPLACE(TRIM(idHakmilik) || '_' || noPelanForIndPelan, ' ','')
                              AND DOKUMEN_ID = (SELECT MAX(DOKUMEN_ID) FROM ET_DMS.DOKUMEN WHERE REPLACE(NAMA_DOKUMEN, ' ','') = REPLACE(TRIM(idHakmilik) || '_' || noPelanForPetakAksesori, ' ',''));

                            INSERT INTO SKG_DOK(DOK_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
                                    VERSION, MEDAN_ID, MEDAN_PK_ID, VERSI_DOK, FLAG_AKTIF, FLAG_DRAF,
                                    ID_DOK, JNS_FAIL, NAMA_FAIL, CATATAN)
                            VALUES(SEQ_DOK.NEXTVAL, username, sysdate, username, sysdate,
                                0, medanIdIndPelan, pelanId, 1, 'Y', 'N', 
                                idDokumen, 'image/tiff', trim(idHakmilik) || '_' || noPelanForIndPelan, null);					
                          EXCEPTION
                            WHEN OTHERS THEN
                            errMsgPetakAksesori := '1SKG_DOK - IND_PELAN - IND_STR_PETAK_AKSESORI B4ASAS ID:' || 
                                      B4ASAS.BORANG4_ASAS_ID || ' B4PA.NO_PELAN:' || B4PA.NO_PELAN || ' ' || SQLERRM; 
                            ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgPetakAksesori);
                          END;
                        ELSE
                          SELECT PELAN_ID into pelanId FROM IND_PELAN WHERE NO_PELAN = noPelanForIndPelan AND VERSI_AKHIR_ID = versiDhdId;
                        END IF;
                        PelanIDForPetakAksesori :=pelanId;
                  --END IF; -- Share end 

                else

                    for rec in (SELECT distinct regexp_substr(noPelanForPetakAksesori,'[^|]+', 1, level)  no_pelan                    
                    from dual 
                    connect by regexp_substr(noPelanForPetakAksesori, '[^|]+', 1, level) is not NULL)  loop

                    DECLARE 
                    v_no_pelan varchar2(50);

                    BEGIN 
                    noPelanForIndPelan := trim(rec.no_pelan);
                    ---use the existing code without changes and passing no pelan 
                      IF length(noPelanForIndPelan) > 0  THEN  -- Share Start
                          SELECT COUNT(PELAN_ID) into noOfSamePelan FROM IND_PELAN WHERE NO_PELAN = noPelanForIndPelan AND VERSI_AKHIR_ID = versiDhdId;

                          IF noOfSamePelan < 1 THEN
                            INSERT INTO IND_PELAN(PELAN_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
                                      VERSION, HKMLK_ID, JNS_PELAN_ID, NO_PELAN, VERSI_AKHIR_ID, VERSI_MULA)
                              VALUES(SEQ_PELAN.NEXTVAL, username, sysdate, username, sysdate,
                                  0, hakmilikId, jenisPelanPetakAksesori, noPelanForIndPelan, versiDhdId, versiDhdId) 
                                  RETURNING PELAN_ID INTO pelanId;

                            BEGIN

                              SELECT ID_DOKUMEN into idDokumen FROM ET_DMS.DOKUMEN 
                                WHERE REPLACE(NAMA_DOKUMEN, ' ','') = REPLACE(TRIM(idHakmilik) || '_' || noPelanForIndPelan, ' ','')
                                AND DOKUMEN_ID = (SELECT MAX(DOKUMEN_ID) FROM ET_DMS.DOKUMEN WHERE REPLACE(NAMA_DOKUMEN, ' ','') = REPLACE(TRIM(idHakmilik) || '_' || noPelanForIndPelan, ' ',''));

                              INSERT INTO SKG_DOK(DOK_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
                                      VERSION, MEDAN_ID, MEDAN_PK_ID, VERSI_DOK, FLAG_AKTIF, FLAG_DRAF,
                                      ID_DOK, JNS_FAIL, NAMA_FAIL, CATATAN)
                              VALUES(SEQ_DOK.NEXTVAL, username, sysdate, username, sysdate,
                                  0, medanIdIndPelan, pelanId, 1, 'Y', 'N', 
                                  idDokumen, 'image/tiff', trim(idHakmilik) || '_' || noPelanForIndPelan, null);					
                            EXCEPTION
                              WHEN OTHERS THEN
                              errMsgPetakAksesori := '2SKG_DOK - IND_PELAN - IND_STR_PETAK_AKSESORI B4ASAS ID:' || 
                                        B4ASAS.BORANG4_ASAS_ID || ' B4PA.NO_PELAN:' || B4PA.NO_PELAN || ' ' || SQLERRM; 
                              ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgPetakAksesori);
                            END;
                          ELSE
                            SELECT PELAN_ID into pelanId FROM IND_PELAN WHERE NO_PELAN = noPelanForIndPelan AND VERSI_AKHIR_ID = versiDhdId;
                          END IF;
                        END IF; -- Share end 

                    END;
                     PelanIDForPetakAksesori :=pelanId;
                    end loop;
                    noPelanForPetakAksesori := REPLACE (noPelanForPetakAksesori, '|' , '||');
                    --pelanId
                end if;
        end if;   
							--avoid to update if B2 already tukarganti
	--						IF noVersiIndukId = 0 AND indeksTerperinciId IS NOT NULL THEN 
            IF indeksTerperinciId IS NOT NULL THEN 
								BEGIN
                                /**
									SELECT LUAS, UNIT_LUAS_ID into luasPetakAksesori, unitLuasPetakAksesori FROM IND_STRATA_PTK_AKSESORI a
										WHERE a.STRATA_IDX_TPRNC_ID = indeksTerperinciId AND a.NAMA = namaPetakAksesori;	
                                        
                                        **/
                                        
                                
									SELECT LUAS, UNIT_LUAS_ID into luasPetakAksesori, unitLuasPetakAksesori FROM IND_STRATA_IDX_PTK_AKSESORI a
										WHERE a.btrn_strata_idx_id = indeksTerperinciId AND a.NAMA = namaPetakAksesori;	        
                                        
								EXCEPTION
									WHEN OTHERS THEN
									errMsgPetakAksesori := 'Fail to get luas petak aksesori for petak:' || 
														namaPetakAksesori || ' STRATA_INDEKS_TERPERINCI_ID:' || indeksTerperinciId || ' ' || SQLERRM; 
									ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgPetakAksesori);
								END;
							END IF;

--							INSERT INTO IND_STR_PTK_AKSESORI(STR_PETAK_AKSESORI_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
--																VERSION, HKMLK_ID, VERSI_AKHIR, VERSI_MULA, NAMA,
--																LOKASI, IDX_AKHIR_ID, IDX_MULA, STRATA_INDEKS_TERPERINCI_ID)
--									VALUES (SEQ_STR_PETAK_AKSESORI.NEXTVAL, username, sysdate, username, sysdate,
--											0, hakmilikId, versiDhdId, versiDhdId, nama, 
--											lokasiPetakAksesori, indeksVersiIndukId, indeksVersiIndukId, indeksTerperinciId);
							INSERT INTO IND_STRATA_PTK_AKSESORI(STRATA_PTK_AKSESORI_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
																VERSION, HKMLK_ID, VERSI_AKHIR_ID, VERSI_MULA, NAMA, PELAN_ID, LUAS, UNIT_LUAS_ID, NO_PELAN)
									VALUES (SEQ_STRATA_PTK_AKSESORI.NEXTVAL, username, sysdate, username, sysdate,
											0, hakmilikId, versiDhdId, versiDhdId, namaPetakAksesori, PelanIDForPetakAksesori, luasPetakAksesori, unitLuasPetakAksesori, noPelanForPetakAksesori);

						EXCEPTION
							WHEN OTHERS THEN
								errMsgPetakAksesori := 'IND_STR_PETAK_AKSESORI B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' B4PETAKAKS ID:' ||
											B4PA.BORANG4_PETAK_AKSESORI_ID || ' ' || SQLERRM; 
								ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgPetakAksesori);

								msgNotifyUser := msgNotifyUser || ' ***** Masalah migrasi senarai petak aksesori - ' || errMsgPetakAksesori ;
						/* end IND_STR_PETAK_AKSESORI */
						END;

					/* end inner block for petak aksesori */
					END;
				/* end loop for petak aksesori */
				END LOOP;
			/* end outer block for petak aksesori */
			END;
			ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'petak aksesori block done');
--		ELSE 
--			ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'petak aksesori skipped as indeksVersiIndukId is NULL');
--		END IF;

		loccode := 'C_B4_URUSAN';
		DECLARE
			CURSOR C_B4_URUSAN IS 
				SELECT * FROM ET_DMSA.BORANG4_SENARAI_URUSAN
				WHERE BORANG4_ASAS_ID = B4ASAS.BORANG4_ASAS_ID;

			tiadaNoSerahan EXCEPTION;

			idPengenalan UMM_APLIKASI.ID_PENGENALAN%TYPE;
			aplikasiId NUMBER(19,0);
			urusanId NUMBER(19,0);
			appHakmilikId NUMBER(19,0);
			jenisUrusanKod RJK_SENARAI_AHLI_KUMPULAN.KOD%TYPE;
			kodUrusan IND_URSN.KOD%TYPE;
			existingAplikasi BOOLEAN;
			runningNumberNoSerahan NUMBER(19,0);
			currentYear NUMBER(19,0);
		/* start B4 urusan block */
		BEGIN
			/* loop to insert all urusan and construct urusan_tbl*/
			FOR B4URUSAN IN C_B4_URUSAN LOOP
				existingAplikasi := FALSE;

				DECLARE
					errMsgAplikasi VARCHAR2(250);
					kategoriHakmilikNama RJK_SENARAI_AHLI_KUMPULAN.NAMA%TYPE;
					noOfAplikasi NUMBER;
				/* UMM_APLIKASI */
				BEGIN
                
                    ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','D',arg_hakmilik_id,null,null,'BEFORE jenisUrusanKod :' || B4ASAS.BORANG4_ASAS_ID );
                    
					SELECT KOD INTO jenisUrusanKod FROM RJK_JNS_URSN
					WHERE JNS_URSN_ID = (SELECT JNS_URSN_ID FROM IND_URSN 
					WHERE KOD = (SELECT KOD FROM ET_DMSA.RJK_SENARAI_AHLI_KUMPULAN WHERE SENARAI_AHLI_KUMPULAN_ID = B4URUSAN.JENIS_URUSAN ));
                    
                    ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','D',arg_hakmilik_id,null,null,'BEFORE kategoriHakmilikNama :' || B4ASAS.BORANG4_ASAS_ID );

					SELECT NAMA INTO kategoriHakmilikNama FROM RJK_SENARAI_AHLI_KUMPULAN 
					WHERE STRATA_KOD = (SELECT KOD FROM ET_DMSA.RJK_SENARAI_AHLI_KUMPULAN WHERE SENARAI_AHLI_KUMPULAN_ID = B4ASAS.KATEGORI_HAKMILIK);
                    
                    ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','D',arg_hakmilik_id,null,null,'BEFORE urusanId :' || B4ASAS.BORANG4_ASAS_ID );

					SELECT URSN_ID, KOD INTO urusanId, kodUrusan FROM IND_URSN 
					WHERE KOD = (SELECT KOD FROM ET_DMSA.RJK_SENARAI_AHLI_KUMPULAN WHERE SENARAI_AHLI_KUMPULAN_ID = B4URUSAN.JENIS_URUSAN);
                    
                    ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','D',arg_hakmilik_id,null,null,'AFTER urusanId :' || B4ASAS.BORANG4_ASAS_ID );

--					IF B4URUSAN.NO_SERAHAN IS NULL THEN
--						RAISE tiadaNoSerahan;
--					END IF;
--					idPengenalan := kategoriHakmilikNama || jenisUrusanKod || B4URUSAN.NO_SERAHAN;

					IF B4URUSAN.NO_SERAHAN IS NULL THEN
						IF kodUrusan IN ('PHKK', 'PHKS') THEN
							--Generate no serahan based on running number
							UPDATE SIS_NO_TURUTAN SET LAST_MODIFIED_BY = username, LAST_MODIFIED_DATE = sysdate, NO_TURUTAN = 
								(SELECT NO_TURUTAN + 1 FROM SIS_NO_TURUTAN WHERE KOD = 'NO_SERAHAN')
								WHERE KOD = 'NO_SERAHAN' RETURNING NO_TURUTAN INTO runningNumberNoSerahan;

							SELECT TO_CHAR(SYSDATE, 'YYYY') INTO currentYear FROM dual;

							--idPengenalan := kategoriHakmilikNama || jenisUrusanKod || runningNumberNoSerahan || 'ET/' || currentYear;
                            idPengenalan := pejabatKod || jenisUrusanKod || runningNumberNoSerahan || 'ET/' || currentYear;
						ELSE
							RAISE tiadaNoSerahan;
						END IF;
					ELSE 						
						--idPengenalan := kategoriHakmilikNama || jenisUrusanKod || replace(replace(trim(B4URUSAN.NO_SERAHAN), ' ', ''), chr(9));
                        idPengenalan := pejabatKod || jenisUrusanKod || replace(replace(trim(B4URUSAN.NO_SERAHAN), ' ', ''), chr(9));
                    END IF;
                    
                    ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','D',arg_hakmilik_id,null,null,'BEFORE noOfAplikasi :' || B4ASAS.BORANG4_ASAS_ID );

					SELECT COUNT(APLIKASI_ID) INTO noOfAplikasi FROM UMM_APLIKASI WHERE ID_PENGENALAN = idPengenalan;
                    
                    ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','D',arg_hakmilik_id,null,null,'AFTER noOfAplikasi :' || B4ASAS.BORANG4_ASAS_ID );

					IF noOfAplikasi < 1 THEN
						existingAplikasi := FALSE;
						INSERT INTO UMM_APLIKASI(APLIKASI_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
										VERSION, FLAG_PERTANYAAN, TRKH_TAMAT, STATUS_KEPUTUSAN, STATUS_PROSES,
										PEJABAT_ID, ID_PENGENALAN, NO_FOLIO, NO_JILID, TRKH_SERAHAN,
										URSN_ID, NO_RUJUKAN_FAIL)
								VALUES(SEQ_APLIKASI.NEXTVAL, username, sysdate, username, sysdate,
										0, 'N', B4URUSAN.TARIKH_SERAHAN, 'Daftar', 'Tamat',
										pejabatId, idPengenalan, B4URUSAN.NO_FOLIO, B4URUSAN.NO_JILID, B4URUSAN.TARIKH_SERAHAN,
										urusanId, B4URUSAN.NO_RUJUKAN_FAIL);
						aplikasiId := SEQ_APLIKASI.CURRVAL;
						urusan_tbl(B4URUSAN.BORANG4_SENARAI_URUSAN_ID) := aplikasiId;
					ELSE
						existingAplikasi := TRUE;
                        
                        ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','D',arg_hakmilik_id,null,null,'BEFORE aplikasiId :' || B4ASAS.BORANG4_ASAS_ID );
                        
						SELECT APLIKASI_ID INTO aplikasiId FROM UMM_APLIKASI WHERE ID_PENGENALAN = idPengenalan;
                        
                        ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','D',arg_hakmilik_id,null,null,'AFTER aplikasiId :' || B4ASAS.BORANG4_ASAS_ID );

						UPDATE UMM_APLIKASI SET LAST_MODIFIED_BY = username, LAST_MODIFIED_DATE = sysdate, 
							NO_FOLIO = B4URUSAN.NO_FOLIO, NO_JILID = B4URUSAN.NO_JILID, TRKH_SERAHAN = B4URUSAN.TARIKH_SERAHAN, 
							URSN_ID = urusanId, NO_RUJUKAN_FAIL = B4URUSAN.NO_RUJUKAN_FAIL
							WHERE APLIKASI_ID = aplikasiId and created_by = 'MIGRATOR_S'; --to avoid update landed title 

                        urusan_tbl(B4URUSAN.BORANG4_SENARAI_URUSAN_ID) := aplikasiId;
					END IF;

				EXCEPTION
					WHEN tiadaNoSerahan THEN
						errMsgAplikasi := 'UMM_APLIKASI TIADA NO SERAHAN  B4ASAS ID:'|| B4ASAS.BORANG4_ASAS_ID || ' B4URUSAN ID:' ||
									B4URUSAN.BORANG4_SENARAI_URUSAN_ID;
						ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgAplikasi);

						msgNotifyUser := msgNotifyUser || ' ***** Sila isi no / tarikh dan masa serahan di Senarai Urusan (DMSA) - ' || errMsgAplikasi;
						CONTINUE;

					WHEN OTHERS THEN
						errMsgAplikasi := 'UMM_APLIKASI B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' B4URUSAN ID:' ||
									B4URUSAN.BORANG4_SENARAI_URUSAN_ID || ' ' || SQLERRM; 
						ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgAplikasi);

						msgNotifyUser := msgNotifyUser || ' ***** Masalah migrasi senarai urusan - ' || errMsgAplikasi;
						CONTINUE;
				/* end UMM_APLIKASI */
				END;
				ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'urusan - aplikasi done');

				DECLARE
					errMsgRekodUrusan VARCHAR2(250);
				/* IND_REKOD_URUSAN */
				BEGIN
					INSERT INTO IND_REKOD_URSN ( REKOD_URSN_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
									VERSION, --NO_SERAHAN, TARIKH_SERAHAN, NO_JILID, NO_FOLIO,
									--NO_RUJUKAN_FAIL, PAJAKAN_DARI, PAJAKAN_HINGGA, 
                  FLAG_KUATKUASA, --URSN_ID,
									VERSI_MULA, VERSI_AKHIR_ID, APLIKASI_ID)--, HKMLK_ID )
							VALUES( SEQ_REKOD_URSN.NEXTVAL, username, SYSDATE, username, SYSDATE, 
									'0', --idPengenalan, B4URUSAN.TARIKH_SERAHAN, B4URUSAN.NO_JILID, B4URUSAN.NO_FOLIO,
									--B4URUSAN.NO_RUJUKAN_FAIL, B4URUSAN.TARIKH_MULA_PAJAKAN, B4URUSAN.TARIKH_TAMAT_PAJAKAN, 
                  'Y', --urusanId, 
									versiDhdId, versiDhdId, aplikasiId);--, hakmilikId);
				EXCEPTION
					WHEN OTHERS THEN
						errMsgRekodUrusan := 'IND_REKOD_URUSAN B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' B4URUSAN ID:' ||
									B4URUSAN.BORANG4_SENARAI_URUSAN_ID || ' ' || SQLERRM; 
						ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgRekodUrusan);

						msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgRekodUrusan;
				/* end IND_REKOD_URUSAN */
				END;
				ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'urusan - rekod urusan done');

				DECLARE
					errMsgAppHakmilik VARCHAR2(250);
					mh IND_MKLMT_HKMLK%ROWTYPE;
				/* UMM_A_HKMLK */
				BEGIN
					SELECT * INTO mh
					FROM IND_MKLMT_HKMLK WHERE MKLMT_HKMLK_ID = maklumatHakmilikId;

          INSERT INTO MIG_LOG3(id_hakmilik,message,log_time)values(idHakmilik,'insert 2',sysdate);	

                    select count(*) into noah1 from umm_a_hkmlk where id_hkmlk=idHakmilik and aplikasi_ID=aplikasiId;
                    if(noah1 = 0) then

                        INSERT INTO UMM_A_HKMLK (A_HKMLK_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
                                                VERSION, ID_HKMLK, APLIKASI_ID, JNS_HKMLK_ID, STATUS_HKMLK_ID,
                                                JNS_TNH_ID, KAT_ID, TARAF_MILIK_ID, SEKSYEN_ID, UNIT_LOT_ID,
                                                UNIT_LUAS_ID, UNIT_KADAR_CUKAI_ID, UNIT_SYER, KADAR_CUKAI, LUAS,
                                                NO_BANGUNAN, NO_TINGKAT, NO_PTK, NO_LOT, TEMPOH_PAJAKAN,
                                                TRKH_DAFTAR, TRKH_LUPUT, SKTN_KPTGN_ID, SYRT_NYATA_ID, LOKASI)
                                VALUES(SEQ_A_HKMLK.NEXTVAL, username, SYSDATE, username, SYSDATE,
                                        '0', idHakmilik, aplikasiId, jenisHakmilikId, mh.STATUS_HKMLK_ID,
                                        mh.JNS_TNH_ID, mh.KAT_ID, mh.TARAF_MILIK_ID, mh.SEKSYEN_ID, mh.UNIT_LOT_ID,
                                        mh.UNIT_LUAS_ID, mh.UNIT_KADAR_CUKAI_ID, mh.UNIT_SYER, mh.KADAR_CUKAI, mh.LUAS,
                                        noBgnn, noTing, noPetak, mh.NO_LOT, mh.TEMPOH_PAJAKAN,
                                        mh.TRKH_DAFTAR, mh.TRKH_LUPUT, mh.SKTN_KPTGN_ID, mh.SYRT_NYATA_ID, mh.LOKASI);
                        appHakmilikId := SEQ_A_HKMLK.CURRVAL;

                        INSERT INTO MIG_LOG3(id_hakmilik,message,log_time)values(idHakmilik,'inserted umm_a_hkmlk',sysdate);

                        /** Try insert Dokumen Penentusahan here **/
                            begin
                                select a_dok_penntshn_id into aDokPenentusahanId from dft_a_dok_penntshn where aplikasi_id=aplikasiId;
                            exception
                                when NO_DATA_FOUND then
                                    aDokPenentusahanId := seq_a_dok_penntshn.nextval;
                                    insert into dft_a_dok_penntshn 
                                    (a_dok_penntshn_id,crEateD_by,crEated_date,last_modified_by,last_modified_date,version,aplikasi_Id,a_tgsn_id,flag_kuatkuasa,no_versi,serahan_terlibat)
                                        values
                                        (aDokPenentusahanId,'MIGRATOR_S',SYSDATE,'MIGRATOR_S',SYSDATE,0,aplikasiId,NULL,'N',NULL,NULL);
                                    INSERT INTO MIG_LOG3(id_hakmilik,message,log_time)values(idHakmilik,'inserted dft_a_dok_penntshn',sysdate);

                            end;

                            select count(*) into foundDokPenentusahan from dft_a_dok_penntshn where aplikasi_id=aplikasiId;

                            INSERT INTO DFT_A_BTRN_DOK_PENNTSHN (A_BTRN_DOK_PENNTSHN_ID,crEateD_by,crEated_date,last_modified_by,last_modified_date,version,a_dok_penntshn_id,id_hkmlk)
                            values
                            (seq_a_btrn_dok_penntshn.nextval,'MIGRATOR_S',SYSDATE,'MIGRATOR_S',SYSDATE,0,aDokPenentusahanId,idHakmilik);

                            INSERT INTO MIG_LOG3(id_hakmilik,message,log_time)values(idHakmilik,'inserted DFT_A_BTRN_DOK_PENNTSHN',sysdate);

                            IF kodUrusan = 'PCP' THEN

                                INSERT INTO MIG_LOG3(id_hakmilik,message,log_time)values(idHakmilik,'Attemping insert rekod PCP for ' || idHakmilik ,sysdate);

                                BEGIN
                                    begin
                                        select a_nota_id into n_nota_id from dft_a_nota where aplikasi_id = aplikasiId; 
                                    exception
                                        when no_data_found then

                                        INSERT INTO DFT_A_NOTA(A_NOTA_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE, VERSION, 
                                                    NO_WARTA, TRKH_WARTA, APLIKASI_ID,TRKH_KUATKUASA )
                                        VALUES(SEQ_A_NOTA.NEXTVAL, username, SYSDATE, username, SYSDATE, 0, B4URUSAN.NO_WARTA, B4URUSAN.TARIKH_WARTA,
                                                aplikasiId,B4URUSAN.TARIKH_KUATKUASA);

                                        INSERT INTO MIG_LOG3(id_hakmilik,message,log_time)values(idHakmilik,'inserted DFT_A_NOTA',sysdate);

                                        select a_nota_id into n_nota_id from dft_a_nota where aplikasi_id = aplikasiId; 

                                    end;

                                    select count(*) into found from DFT_A_BTRN_NOTA where a_nota_id = n_nota_id and ID_HKMLK= idHakmilik;

                                    if found = 0 then 

                                        INSERT INTO MIG_LOG3(id_hakmilik,message,log_time)values(idHakmilik,'Found Butiran PCP for ' || idHakmilik ,sysdate);

                                        INSERT INTO DFT_A_BTRN_NOTA  (A_BTRN_NOTA_ID,CREATED_BY,CREATED_DATE,LAST_MODIFIED_BY,LAST_MODIFIED_DATE,VERSION,CUKAI_BARU,a_NOTA_ID,ID_HKMLK) 
                                        values
                                        (seq_a_btrn_nota.nextval,'MIGRATOR_S',SYSDATE,'MIGRATOR_S',SYSDATE,0, B4URUSAN.TEMPOh_TAHUN, n_nota_id, idHakmilik);

                                        INSERT INTO MIG_LOG3(id_hakmilik,message,log_time)values(idHakmilik,'inserted DFT_A_BTRN_NOTA',sysdate);

                                    end if;
                                exception
                                    when others then
                                        msgerrpcp := 'Failed insert for ' || idHakmilik || ' ' || SQLERRM ;
                                        INSERT INTO MIG_LOG3(id_hakmilik,message,log_time)values(idHakmilik,msgerrpcp,sysdate);

                                END;

                            END IF;

                    else
                       select A_HKMLK_ID into appHakmilikId from umm_a_hkmlk where id_hkmlk=idHakmilik and aplikasi_ID=aplikasiId;
                    end if;
					appHakmilik_tbl(aplikasiId) := appHakmilikId;
				EXCEPTION
					WHEN OTHERS THEN
						errMsgAppHakmilik := 'UMM_A_HKMLK B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' B4URUSAN ID:' ||
								B4URUSAN.BORANG4_SENARAI_URUSAN_ID || ' ' || SQLERRM; 
						ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgAppHakmilik);

						msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgAppHakmilik;

                        INSERT INTO MIG_LOG3(id_hakmilik,message,log_time)values(idHakmilik,errMsgAppHakmilik,sysdate);

				/* end UMM_A_HKMLK */
				END;
				ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'urusan - appHakmilik done');

				DECLARE
					CURSOR C_B4_URUSAN_PEMILIK IS  
						SELECT * FROM ET_DMSA.BORANG4_URUSAN_PEMILIK
						WHERE BORANG4_SENARAI_URUSAN_ID = B4URUSAN.BORANG4_SENARAI_URUSAN_ID;

					pbIndukId NUMBER(19,0);
					pbInduk IND_PIHAK_BKPTG%ROWTYPE;
				/* UMM_A_PIHAK_BKPTG */
				BEGIN
					/* loop for urusan pemilik */
					FOR B4URUSAN_PEMILIK IN C_B4_URUSAN_PEMILIK LOOP

						DECLARE
							errMsgUrusanPemilik VARCHAR2(250);
						BEGIN
							pbIndukId := pemilik_tbl(B4URUSAN_PEMILIK.BORANG4_SENARAI_PEMILIK_ID);
							SELECT * INTO pbInduk
							FROM IND_PIHAK_BKPTG WHERE PIHAK_BKPTG_ID = pbIndukId;

							INSERT INTO UMM_A_PIHAK_BKPTG( A_PIHAK_BKPTG_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
															VERSION, ALAMAT_DAFTAR1, ALAMAT_DAFTAR2, ALAMAT_DAFTAR3, ALAMAT_DAFTAR4,
															NAMA, JNS_PIHAK_BKPTG_ID, NO_KP, POSKOD_DAFTAR, BANDAR_DAFTAR_ID, BANDAR_DAFTAR_LAIN, 
															NEGERI_DAFTAR_ID, FLAG_KUATKUASA, SYER_PEMBILANG, SYER_PENYEBUT, WARGANEGARA_ID,
															NO_KP_LAMA, JNS_NO_KP_LAMA_ID, JNS_NO_ID, A_HKMLK_ID, PIHAK_BKPTG_ID)
									VALUES (SEQ_A_PIHAK_BKPTG.NEXTVAL, username, sysdate, username, sysdate,
											0, pbInduk.ALAMAT_DAFTAR1, pbInduk.ALAMAT_DAFTAR2, pbInduk.ALAMAT_DAFTAR3, pbInduk.ALAMAT_DAFTAR4,
											pbInduk.NAMA, pbInduk.JNS_PIHAK_BKPTG_ID, pbInduk.NO_KP, pbInduk.POSKOD_DAFTAR, pbInduk.BANDAR_DAFTAR_ID, pbInduk.BANDAR_DAFTAR_LAIN,
											pbInduk.NEGERI_DAFTAR_ID, pbInduk.FLAG_KUATKUASA, pbInduk.SYER_PEMBILANG, pbInduk.SYER_PENYEBUT, pbInduk.WARGANEGARA_ID, 
											pbInduk.NO_KP_LAMA, pbInduk.JNS_NO_KP_LAMA_ID, pbInduk.JNS_NO_ID, appHakmilikId, pbIndukId);
							EXCEPTION
								WHEN OTHERS THEN
									errMsgUrusanPemilik := 'UMM_A_PIHAK_BKPTG B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' B4URUSAN ID:' ||
															B4URUSAN.BORANG4_SENARAI_URUSAN_ID || ' ' || SQLERRM; 
									ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgUrusanPemilik);

									msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgUrusanPemilik;
						END;
					/* end loop for urusan pemilik */
					END LOOP;
				/* end UMM_A_PIHAK_BKPTG */
				END;
				ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'urusan - urusan pemilik done');

				DECLARE 
					CURSOR C_B4_URUSAN_PB IS  
						SELECT * FROM ET_DMSA.BORANG4_URSN_PIHAK_BKPTGN
						WHERE BORANG4_SENARAI_URUSAN_ID = B4URUSAN.BORANG4_SENARAI_URUSAN_ID;

					pbIndukId NUMBER(19,0);
				/* to insert IND_PIHAK_BKPTG and then UMM_A_PIHAK_BKPTG for urusan pb */
				BEGIN
					/* start loop urusan pb */
					FOR B4URUSAN_PB IN C_B4_URUSAN_PB LOOP

						DECLARE
							namaPb IND_PIHAK_BKPTG.NAMA%TYPE;
							errMsgUrusanPb VARCHAR2(250);
							alamatDaftar1 IND_PIHAK_BKPTG.ALAMAT_DAFTAR1%TYPE;
							bandarDaftarKod ET_DMSA.RJK_SENARAI_AHLI_KUMPULAN.KOD%TYPE;
							bandarDaftarNama ET_DMSA.RJK_SENARAI_AHLI_KUMPULAN.NAMA%TYPE;
							bandarDaftarId NUMBER(19,0);
							bandarDaftarLain IND_PIHAK_BKPTG.BANDAR_DAFTAR_LAIN%TYPE;
							negeriDaftarId NUMBER(19,0);
							poskodDaftar IND_PIHAK_BKPTG.POSKOD_DAFTAR%TYPE;
							jenisNoId NUMBER(19,0);
							noKp IND_PIHAK_BKPTG.NO_KP%TYPE;
							warganegaraId NUMBER(19,0);
							jenisPbId NUMBER(19,0);
						/* IND_PIHAK_BKPTG */
						BEGIN
							alamatDaftar1 := returnSpaceIfNull(B4URUSAN_PB.ALAMAT1);
							poskodDaftar := returnSpaceIfNull(B4URUSAN_PB.POSKOD);
							noKp := returnSpaceIfNull(B4URUSAN_PB.NO_PENGENALAN);
							namaPb := returnSpaceIfNull(B4URUSAN_PB.NAMA);

							IF B4URUSAN_PB.BANDAR_ID IS NOT NULL THEN
								SELECT KOD, NAMA INTO bandarDaftarKod, bandarDaftarNama
								FROM ET_DMSA.RJK_SENARAI_AHLI_KUMPULAN WHERE SENARAI_AHLI_KUMPULAN_ID = B4URUSAN_PB.BANDAR_ID;
							ELSE 
								bandarDaftarNama := NULL;
								bandarDaftarKod := NULL;
							END IF;
							
							loccode := 'BANDAR:' || bandarDaftarKod;

							IF bandarDaftarKod IS NOT NULL THEN 
								bandarDaftarId := getSakIdByDmsaSakKod(bandarDaftarKod, 'B4URUSAN_PB.BANDAR_ID','BANDAR');
							END IF;

							IF bandarDaftarId IS NULL THEN
								bandarDaftarLain := bandarDaftarNama;
								bandarDaftarId := bandarTiada;
							END IF;
							
							loccode := 'NEGERI:' || B4URUSAN_PB.NEGERI_ID;

							IF B4URUSAN_PB.NEGERI_ID IS NOT NULL THEN 
								negeriDaftarId := getSakIdByDmsaSakId(B4URUSAN_PB.NEGERI_ID, 'B4URUSAN_PB.NEGERI_ID','NEGERI');
							ELSE
								negeriDaftarId := negeriTiada;
							END IF;
							
							loccode := 'JENIS_NOP:' || B4URUSAN_PB.JENIS_NO_PENGENALAN;

							IF B4URUSAN_PB.JENIS_NO_PENGENALAN IS NOT NULL THEN
								jenisNoId := getSakIdByDmsaSakId(B4URUSAN_PB.JENIS_NO_PENGENALAN, 'B4URUSAN_PB.JENIS_NO_PENGENALAN','JENIS_NOP');
							ELSE 
								jenisNoId := jenisPengenalanTiada;
							END IF;
							
							
							loccode := 'WARGANEGARA:' || B4URUSAN_PB.WARGANEGARA_ID;

							IF B4URUSAN_PB.WARGANEGARA_ID IS NOT NULL THEN
								warganegaraId := getSakIdByDmsaSakId(B4URUSAN_PB.WARGANEGARA_ID, 'B4URUSAN_PB.WARGANEGARA_ID','WARGANEGARA');
							ELSE 
								warganegaraId := NULL;
							END IF;
							
							
							loccode := 'JEN_PHKBKPTGN:' || B4URUSAN_PB.JENIS_PIHAK_BKPTGN;

							IF B4URUSAN_PB.JENIS_PIHAK_BKPTGN IS NOT NULL THEN
								jenisPbId := getSakIdByDmsaSakId(B4URUSAN_PB.JENIS_PIHAK_BKPTGN, 'B4URUSAN_PB.JENIS_PIHAK_BKPTGN','JEN_PHKBKPTGN');
							ELSE 
								jenisPbId := jenisPbTiada;
							END IF;
							
							
							loccode := 'BEFORE INSERT PB:';

							INSERT INTO IND_PIHAK_BKPTG(PIHAK_BKPTG_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
														NAMA, JNS_PIHAK_BKPTG_ID, JNS_NO_ID, NO_KP, WARGANEGARA_ID,
														VERSION, VERSI_MULA, VERSI_AKHIR_ID, FLAG_KUATKUASA, APLIKASI_ID,
														ALAMAT_DAFTAR1, ALAMAT_DAFTAR2, ALAMAT_DAFTAR3, ALAMAT_DAFTAR4, POSKOD_DAFTAR,
														BANDAR_DAFTAR_ID, NEGERI_DAFTAR_ID, BANDAR_DAFTAR_LAIN)--, HKMLK_ID)
								VALUES(SEQ_PIHAK_BKPTG.NEXTVAL, username, sysdate, username, sysdate,
										namaPb, jenisPbId, jenisNoId, noKp, warganegaraId,
										0, versiDhdId, versiDhdId, 'Y', aplikasiId,
										alamatDaftar1, B4URUSAN_PB.ALAMAT2, B4URUSAN_PB.ALAMAT3, B4URUSAN_PB.ALAMAT4, poskodDaftar,
										bandarDaftarId, negeriDaftarId, bandarDaftarLain);--, hakmilikId);
							pbIndukId := SEQ_PIHAK_BKPTG.CURRVAL;
						EXCEPTION
							WHEN OTHERS THEN
								errMsgUrusanPb := 'IND_PIHAK_BKPTG FOR URUSAN PB B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' B4URUSAN ID:' ||
											B4URUSAN.BORANG4_SENARAI_URUSAN_ID || ' ' || SQLERRM || ':LCC:' || loccode; 
								ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgUrusanPb);

								msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgUrusanPb;
								CONTINUE;
						/* end IND_PIHAK_BKPTG */
						END;

						DECLARE
						errMsgUrusanPbApp VARCHAR2(250);
						pbInduk IND_PIHAK_BKPTG%ROWTYPE;
						/* UMM_A_PIHAK_BKPTG */
						BEGIN
							SELECT * INTO pbInduk
							FROM IND_PIHAK_BKPTG WHERE PIHAK_BKPTG_ID = pbIndukId;

							INSERT INTO UMM_A_PIHAK_BKPTG( A_PIHAK_BKPTG_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
															VERSION, ALAMAT_DAFTAR1, ALAMAT_DAFTAR2, ALAMAT_DAFTAR3, ALAMAT_DAFTAR4,
															NAMA, JNS_PIHAK_BKPTG_ID, NO_KP, POSKOD_DAFTAR, BANDAR_DAFTAR_ID, BANDAR_DAFTAR_LAIN, 
															NEGERI_DAFTAR_ID, FLAG_KUATKUASA, FLAG_BARU, WARGANEGARA_ID, JNS_NO_ID,
															A_HKMLK_ID, PIHAK_BKPTG_ID)
									VALUES (SEQ_A_PIHAK_BKPTG.NEXTVAL, username, sysdate, username, sysdate,
											0, pbInduk.ALAMAT_DAFTAR1, pbInduk.ALAMAT_DAFTAR2, pbInduk.ALAMAT_DAFTAR3, pbInduk.ALAMAT_DAFTAR4,
											pbInduk.NAMA, pbInduk.JNS_PIHAK_BKPTG_ID, pbInduk.NO_KP, pbInduk.POSKOD_DAFTAR, pbInduk.BANDAR_DAFTAR_ID, pbInduk.BANDAR_DAFTAR_LAIN,
											pbInduk.NEGERI_DAFTAR_ID, pbInduk.FLAG_KUATKUASA, 'Y', pbInduk.WARGANEGARA_ID, pbInduk.JNS_NO_ID,
											appHakmilikId, pbIndukId);
						EXCEPTION
							WHEN OTHERS THEN
								errMsgUrusanPbApp := 'UMM_A_PIHAK_BKPTG B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' B4URUSAN ID:' ||
											B4URUSAN.BORANG4_SENARAI_URUSAN_ID || ' ' || SQLERRM; 
								ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgUrusanPbApp);

								msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgUrusanPbApp;
						/* end UMM_A_PIHAK_BKPTG */
						END;

					/* end loop urusan pb */
					END LOOP;
				/* end IND_PIHAK_BKPTG and then UMM_A_PIHAK_BKPTG for urusan pb */
				END;
				ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'urusan - urusan pb done');

				IF existingAplikasi = FALSE THEN
					DECLARE
						errMsgTransactional VARCHAR2(250);
						suratCaraId NUMBER(19,0);
						pajakanId NUMBER(19,0);
						unitLuasPajakanId NUMBER(19,0);
						tableName VARCHAR2(100);
            jenisNoIdPenerima NUMBER(19,0);
            jenisPenyampaianId NUMBER(19,0);
            jenisTanahIsmenTanggung NUMBER(19,0);
            jenisTanahIsmenKuasai NUMBER(19,0);
            mklmt IND_MKLMT_HKMLK%ROWTYPE;
            hkmlk IND_HKMLK%ROWTYPE;
					/* Transactional Tables */
					BEGIN

                    INSERT INTO MIG_LOG3(id_hakmilik,message,log_time)values(idHakmilik,'Analyzing jenis urusan' || jenisUrusanKod || ' aplikasi ' || aplikasiId,sysdate);

						IF jenisUrusanKod = 'SC' THEN
							/* DFT_A_SURATCARA */
							tableName := 'DFT_A_SURATCARA';
							INSERT INTO DFT_A_SRTCARA(A_SRTCARA_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
                                          VERSION, APLIKASI_ID, CARA_BAYARAN_ID, TUJUAN_ID, HARI, 
                                          BULAN, TAHUN, TRKH_KUATKUASA, TRKH_LUPUT)
                                   VALUES(SEQ_A_SRTCARA.NEXTVAL, username, SYSDATE, username, SYSDATE,
                                          0, aplikasiId, caraBayaranTiada, NULL,  B4URUSAN.TEMPOH_HARI, 
                                          B4URUSAN.TEMPOH_BULAN, B4URUSAN.TEMPOH_TAHUN, B4URUSAN.TARIKH_KUATKUASA, B4URUSAN.TARIKH_LUPUT);
							suratCaraId := SEQ_A_SRTCARA.CURRVAL;

								--IF kodUrusan IN ('GD') THEN
									/* DFT_A_GADAIAN */
                  /* 08/10/18 Azrilisam
									tableName := 'DFT_A_GADAIAN';
									INSERT INTO DFT_A_GADAIAN( A_GADAIAN_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
																VERSION, CARA_BAYARAN_ID, A_SURATCARA_ID)
									VALUES(SEQ_A_GADAIAN.NEXTVAL, username, SYSDATE, username, SYSDATE, 0, caraBayaranTiada, suratCaraId);
                  */

                IF kodUrusan IN ('IS') THEN
                  /* DFT_A_ISMEN */   
                  /* 08/10/18 Azrilisam
                  tableName := 'DFT_A_ISMEN';
                  INSERT INTO DFT_A_ISMEN( A_ISMEN_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
																VERSION, TUJUAN_ID, HARI, BULAN, TAHUN,
                                TARIKH_KUATKUASA, TARIKH_LUPUT, A_SURATCARA_ID)
									VALUES(SEQ_A_ISMEN.NEXTVAL, username, SYSDATE, username, SYSDATE, 
                            0, null, B4URUSAN.TEMPOH_HARI, B4URUSAN.TEMPOH_BULAN, B4URUSAN.TEMPOH_TAHUN,
                            B4URUSAN.TARIKH_KUATKUASA, B4URUSAN.TARIKH_LUPUT, suratCaraId);
                  */           

                  jenisTanahIsmenTanggung := getSakIdBySakKod('JTI_TANGGUNG');
                  jenisTanahIsmenKuasai := getSakIdBySakKod('JTI_KUASAI');

                  IF B4URUSAN.ID_HAKMILIK_TANGGUNG IS NOT NULL THEN
                    IF idHakmilik = trim(B4URUSAN.ID_HAKMILIK_TANGGUNG) THEN
                      UPDATE UMM_A_HKMLK SET JNS_TNH_ISMEN_ID = jenisTanahIsmenTanggung 
                      WHERE APLIKASI_ID = aplikasiId AND ID_HKMLK = idHakmilik AND CREATED_BY = 'MIGRATOR_S'; 
                    ELSE  
                      SELECT mh.* into mklmt FROM IND_MKLMT_HKMLK mh
                      JOIN IND_VERSI_DHD vd ON vd.MKLMT_HKMLK_ID =  mh.MKLMT_HKMLK_ID
                      JOIN IND_HKMLK hkmlk ON hkmlk.HKMLK_ID = vd.HKMLK_ID
                      WHERE hkmlk.ID_HKMLK = trim(B4URUSAN.ID_HAKMILIK_TANGGUNG);

                      SELECT * into hkmlk FROM IND_HKMLK hkmlk
                      WHERE hkmlk.ID_HKMLK = trim(B4URUSAN.ID_HAKMILIK_TANGGUNG);

                      INSERT INTO MIG_LOG3(id_hakmilik,message,log_time)values(trim(B4URUSAN.ID_HAKMILIK_TANGGUNG),'insert 3',sysdate);	

                      select count(*) into noah2 from umm_a_hkmlk where id_hkmlk=trim(B4URUSAN.ID_HAKMILIK_TANGGUNG) and aplikasi_ID=aplikasiId;
                      if(noah2 = 0) then

                          INSERT INTO UMM_A_HKMLK (A_HKMLK_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
                                      VERSION, ID_HKMLK, APLIKASI_ID, JNS_HKMLK_ID, STATUS_HKMLK_ID,
                                      JNS_TNH_ID, KAT_ID, TARAF_MILIK_ID, SEKSYEN_ID, UNIT_LOT_ID,
                                      UNIT_LUAS_ID, UNIT_KADAR_CUKAI_ID, UNIT_SYER, KADAR_CUKAI, LUAS,
                                      NO_BANGUNAN, NO_TINGKAT, NO_PTK, NO_LOT, TEMPOH_PAJAKAN,
                                      TRKH_DAFTAR, TRKH_LUPUT, SKTN_KPTGN_ID, SYRT_NYATA_ID, LOKASI,
                                      JNS_TNH_ISMEN_ID)
                              VALUES(SEQ_A_HKMLK.NEXTVAL, username, SYSDATE, username, SYSDATE,
                                  '0', trim(B4URUSAN.ID_HAKMILIK_TANGGUNG), aplikasiId, hkmlk.JNS_HKMLK_ID, mklmt.STATUS_HKMLK_ID,
                                  mklmt.JNS_TNH_ID, mklmt.KAT_ID, mklmt.TARAF_MILIK_ID, mklmt.SEKSYEN_ID, mklmt.UNIT_LOT_ID,
                                  mklmt.UNIT_LUAS_ID, mklmt.UNIT_KADAR_CUKAI_ID, mklmt.UNIT_SYER, mklmt.KADAR_CUKAI, mklmt.LUAS,
                                  hkmlk.NO_BANGUNAN, hkmlk.NO_TINGKAT, hkmlk.NO_PTK, mklmt.NO_LOT, mklmt.TEMPOH_PAJAKAN,
                                  mklmt.TRKH_DAFTAR, mklmt.TRKH_LUPUT, mklmt.SKTN_KPTGN_ID, mklmt.SYRT_NYATA_ID, mklmt.LOKASI,
                                  jenisTanahIsmenTanggung);
                        end if;
                    END IF;
                  END IF;

                  IF B4URUSAN.ID_HAKMILIK_KUASAI IS NOT NULL THEN
                    IF idHakmilik = trim(B4URUSAN.ID_HAKMILIK_KUASAI) THEN
                      UPDATE UMM_A_HKMLK SET JNS_TNH_ISMEN_ID = jenisTanahIsmenKuasai 
                      WHERE APLIKASI_ID = aplikasiId AND ID_HKMLK = idHakmilik AND CREATED_BY = 'MIGRATOR_S';
                    ELSE
                      SELECT mh.* into mklmt FROM IND_MKLMT_HKMLK mh
                      JOIN IND_VERSI_DHD vd ON vd.MKLMT_HKMLK_ID =  mh.MKLMT_HKMLK_ID
                      JOIN IND_HKMLK hkmlk ON hkmlk.HKMLK_ID = vd.HKMLK_ID
                      WHERE hkmlk.ID_HKMLK = trim(B4URUSAN.ID_HAKMILIK_KUASAI);

                      SELECT * into hkmlk FROM IND_HKMLK hkmlk
                      WHERE hkmlk.ID_HKMLK = trim(B4URUSAN.ID_HAKMILIK_KUASAI);

                      INSERT INTO MIG_LOG3(id_hakmilik,message,log_time)values(trim(B4URUSAN.ID_HAKMILIK_KUASAI),'insert 4',sysdate);	

                      select count(*) into noah3 from umm_a_hkmlk where id_hkmlk=trim(B4URUSAN.ID_HAKMILIK_KUASAI) and aplikasi_ID=aplikasiId;
                      if(noah3 = 0) then
                          INSERT INTO UMM_A_HKMLK (A_HKMLK_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
                                      VERSION, ID_HKMLK, APLIKASI_ID, JNS_HKMLK_ID, STATUS_HKMLK_ID,
                                      JNS_TNH_ID, KAT_ID, TARAF_MILIK_ID, SEKSYEN_ID, UNIT_LOT_ID,
                                      UNIT_LUAS_ID, UNIT_KADAR_CUKAI_ID, UNIT_SYER, KADAR_CUKAI, LUAS,
                                      NO_BANGUNAN, NO_TINGKAT, NO_PTK, NO_LOT, TEMPOH_PAJAKAN,
                                      TRKH_DAFTAR, TRKH_LUPUT, SKTN_KPTGN_ID, SYRT_NYATA_ID, LOKASI,
                                      JNS_TNH_ISMEN_ID)
                              VALUES(SEQ_A_HKMLK.NEXTVAL, username, SYSDATE, username, SYSDATE,
                                  '0', trim(B4URUSAN.ID_HAKMILIK_KUASAI), aplikasiId, hkmlk.JNS_HKMLK_ID, mklmt.STATUS_HKMLK_ID,
                                  mklmt.JNS_TNH_ID, mklmt.KAT_ID, mklmt.TARAF_MILIK_ID, mklmt.SEKSYEN_ID, mklmt.UNIT_LOT_ID,
                                  mklmt.UNIT_LUAS_ID, mklmt.UNIT_KADAR_CUKAI_ID, mklmt.UNIT_SYER, mklmt.KADAR_CUKAI, mklmt.LUAS,
                                  hkmlk.NO_BANGUNAN, hkmlk.NO_TINGKAT, hkmlk.NO_PTK, mklmt.NO_LOT, mklmt.TEMPOH_PAJAKAN,
                                  mklmt.TRKH_DAFTAR, mklmt.TRKH_LUPUT, mklmt.SKTN_KPTGN_ID, mklmt.SYRT_NYATA_ID, mklmt.LOKASI,
                                  jenisTanahIsmenKuasai);
                        end if;
                    END IF;
                  END IF;

								ELSIF kodUrusan IN ('PJT', 'PJBT', 'PJKT', 'PJKBT') THEN
									/* DFT_A_PAJAKAN */
                  /* 08/10/18 Azrilisam
									tableName := 'DFT_A_PAJAKAN';
									INSERT INTO DFT_A_PAJAKAN(A_PAJAKAN_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
																VERSION, DARI, HINGGA, 
																TAHUN,BULAN, HARI, A_SURATCARA_ID)
										VALUES( SEQ_A_PAJAKAN.NEXTVAL, username, SYSDATE, username, SYSDATE, 0,
												B4URUSAN.TARIKH_MULA_PAJAKAN, B4URUSAN.TARIKH_TAMAT_PAJAKAN, 
												B4URUSAN.TEMPOH_TAHUN, B4URUSAN.TEMPOH_BULAN, B4URUSAN.TEMPOH_HARI, suratCaraId);
									pajakanId := SEQ_A_PAJAKAN.CURRVAL;
									*/                

									IF kodUrusan IN ('PJBT', 'PJKBT') THEN
                    NULL;
										/* DFT_A_PAJAKAN_TERPRNC */
                    /* 08/10/18 Azrilisam
										tableName := 'DFT_A_PAJAKAN_TERPRNC';
										unitLuasPajakanId := getSakIdByDmsaSakKod(B4URUSAN.UNIT_LUAS_PAJAKAN, 'B4URUSAN.UNIT_LUAS_PAJAKAN');
										INSERT INTO DFT_A_PAJAKAN_TERPRNC(A_PAJAKAN_TERPRNC_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
																			VERSION, LUAS1, UNIT_ID, PAJAKAN_ID, ID_HAKMILIK)
											VALUES(SEQ_A_PAJAKAN_TERPRNC.NEXTVAL, username, SYSDATE, username, SYSDATE,
													0, B4URUSAN.LUAS_PAJAKAN, unitLuasPajakanId, pajakanId, idHakmilik);
                    */

										tableName := 'DFT_A_BTRN_SRTCARA';
										unitLuasPajakanId := getSakIdByDmsaSakKod(B4URUSAN.UNIT_LUAS_PAJAKAN, 'B4URUSAN.UNIT_LUAS_PAJAKAN','UNIT_LUAS');
										INSERT INTO DFT_A_BTRN_SRTCARA(A_BTRN_SRTCARA_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
																			VERSION, LUAS1, UNIT_ID, A_SRTCARA_ID, ID_HKMLK)
											VALUES(SEQ_A_BTRN_SRTCARA.NEXTVAL, username, SYSDATE, username, SYSDATE,
                             0, B4URUSAN.LUAS_PAJAKAN, unitLuasPajakanId, suratCaraId, idHakmilik);

									END IF;
								END IF;

						ELSIF jenisUrusanKod = 'B' THEN
							/* DFT_A_BORANG */
							tableName := 'DFT_A_BORANG';
							INSERT INTO DFT_A_BORANG( A_BORANG_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
														VERSION, APLIKASI_ID, TAHUN, BULAN, HARI,
														NO_PRNTH, TRKH_MAHKAMAH, TRKH_KUATKUASA, CATATAN,
                            NAMA_MAHKAMAH, SEBAB_PRNTH)
							VALUES(SEQ_A_BORANG.NEXTVAL, username, SYSDATE, username, SYSDATE,
									0, aplikasiId, B4URUSAN.TEMPOH_TAHUN, B4URUSAN.TEMPOH_BULAN, B4URUSAN.TEMPOH_HARI,
									B4URUSAN.NO_PERINTAH, B4URUSAN.TARIKH_PERINTAH, B4URUSAN.TARIKH_KUATKUASA, B4URUSAN.CATATAN,
                  B4URUSAN.NAMA_MAHKAMAH, B4URUSAN.SEBAB_PERINTAH);

              IF kodUrusan = 'KVSPC' THEN
										/* DFT_A_NOTIS */
                    IF B4URUSAN.PENERIMA_JENIS_NO_ID IS NOT NULL THEN
                      jenisNoIdPenerima := getSakIdByDmsaSakId(B4URUSAN.PENERIMA_JENIS_NO_ID, 'B4URUSAN.PENERIMA_JENIS_NO_ID','JENIS_NOP');
                    END IF;

                    IF B4URUSAN.JENIS_PENYAMPAIAN_KOD IS NOT NULL THEN
                      jenisPenyampaianId := getSakIdBySakKod(B4URUSAN.JENIS_PENYAMPAIAN_KOD);
                    END IF;

										tableName := 'DFT_A_NOTIS';
										INSERT INTO DFT_A_NOTIS(A_NOTIS_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
																			VERSION, APLIKASI_ID, PNRM, NO_PENGENALAN, JNS_NO_ID, 
                                      TRKH_TERIMA, JNS_PENYAMPAIAN_ID)
											VALUES(SEQ_A_NOTIS.NEXTVAL, username, SYSDATE, username, SYSDATE,
													0, aplikasiId, B4URUSAN.PENERIMA_NAMA, B4URUSAN.PENERIMA_NO_PENGENALAN, jenisNoIdPenerima,
                          B4URUSAN.TARIKH_TERIMA, jenisPenyampaianId);
              END IF;

						ELSIF jenisUrusanKod = 'N' THEN
							/* DFT_A_NOTA */

                            begin
                                        select a_nota_id into n_nota_id from dft_a_nota where aplikasi_id = aplikasiId; 
                                    exception
                                        when no_data_found then

                                        tableName := 'DFT_A_NOTA';
                                        INSERT INTO DFT_A_NOTA(A_NOTA_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE, VERSION, 
                                                    NO_WARTA, TRKH_WARTA, APLIKASI_ID,TRKH_KUATKUASA )
                                        VALUES(SEQ_A_NOTA.NEXTVAL, username, SYSDATE, username, SYSDATE, 0, B4URUSAN.NO_WARTA, B4URUSAN.TARIKH_WARTA,
                                                aplikasiId,B4URUSAN.TARIKH_KUATKUASA);

                                        INSERT INTO MIG_LOG3(id_hakmilik,message,log_time)values(idHakmilik,'inserted DFT_A_NOTA',sysdate);

                            END;

						END IF;

					EXCEPTION
						WHEN OTHERS THEN
							errMsgTransactional := tableName ||' B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' B4URUSAN ID:' ||
										B4URUSAN.BORANG4_SENARAI_URUSAN_ID || ' ' || SQLERRM; 
							ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgTransactional);

							msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgTransactional;
					/* end Transactional Tables */
					END;
					ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'urusan - transactional tables done');
				ELSE -- Do not update SPTB data so query with condition created_by = 'MIGRATOR_S'
					DECLARE
						errMsgTransactional VARCHAR2(250);
						unitLuasPajakanId NUMBER(19,0);
            jenisTanahIsmenTanggung NUMBER(19,0);
            jenisTanahIsmenKuasai NUMBER(19,0);
					BEGIN
						UPDATE DFT_A_SRTCARA SET LAST_MODIFIED_BY = username, LAST_MODIFIED_DATE = SYSDATE
							WHERE APLIKASI_ID = aplikasiId AND CREATED_BY = 'MIGRATOR_S';
            /* 08/10/18 Azrilisam							
						UPDATE DFT_A_GADAIAN SET LAST_MODIFIED_BY = username, LAST_MODIFIED_DATE = SYSDATE
							WHERE A_SURATCARA_ID = (SELECT A_SURATCARA_ID FROM DFT_A_SURATCARA WHERE APLIKASI_ID = aplikasiId AND CREATED_BY = 'MIGRATOR_S');

						UPDATE DFT_A_PAJAKAN SET LAST_MODIFIED_BY = username, LAST_MODIFIED_DATE = SYSDATE, 
							DARI = B4URUSAN.TARIKH_MULA_PAJAKAN, HINGGA = B4URUSAN.TARIKH_TAMAT_PAJAKAN, 
							TAHUN = B4URUSAN.TEMPOH_TAHUN, BULAN = B4URUSAN.TEMPOH_BULAN, HARI = B4URUSAN.TEMPOH_HARI
							WHERE A_SURATCARA_ID = (SELECT A_SURATCARA_ID FROM DFT_A_SURATCARA WHERE APLIKASI_ID = aplikasiId AND CREATED_BY = 'MIGRATOR_S');
            */
			
			loccode := 'PRE UNIT_LUAS:' || B4URUSAN.UNIT_LUAS_PAJAKAN;

			if B4URUSAN.UNIT_LUAS_PAJAKAN is not null then
				unitLuasPajakanId := getSakIdByDmsaSakKod(B4URUSAN.UNIT_LUAS_PAJAKAN, 'B4URUSAN.UNIT_LUAS_PAJAKAN','UNIT_LUAS');
			else			
				unitLuasPajakanId := NULL;
			end if;
			
			loccode := 'POST UNIT_LUAS:' || B4URUSAN.UNIT_LUAS_PAJAKAN;
            /* 08/10/18 Azrilisam
						UPDATE DFT_A_PAJAKAN_TERPRNC SET LAST_MODIFIED_BY = username, LAST_MODIFIED_DATE = SYSDATE,
							LUAS1 = B4URUSAN.LUAS_PAJAKAN, UNIT_ID = unitLuasPajakanId
							WHERE PAJAKAN_ID = (SELECT A_PAJAKAN_ID FROM DFT_A_PAJAKAN p 
								JOIN DFT_A_SURATCARA sc ON (p.A_SURATCARA_ID = sc.A_SURATCARA_ID)
								WHERE sc.APLIKASI_ID = aplikasiId AND sc.CREATED_BY = 'MIGRATOR_S');
            */

						UPDATE DFT_A_BORANG SET LAST_MODIFIED_BY = username, LAST_MODIFIED_DATE = SYSDATE,
							TAHUN = B4URUSAN.TEMPOH_TAHUN, BULAN = B4URUSAN.TEMPOH_BULAN, HARI = B4URUSAN.TEMPOH_HARI, NO_PRNTH = B4URUSAN.NO_PERINTAH, 
							TRKH_MAHKAMAH = B4URUSAN.TARIKH_PERINTAH, TRKH_KUATKUASA = B4URUSAN.TARIKH_KUATKUASA, CATATAN = B4URUSAN.CATATAN,
              NAMA_MAHKAMAH = B4URUSAN.NAMA_MAHKAMAH, SEBAB_PRNTH = B4URUSAN.SEBAB_PERINTAH
							WHERE APLIKASI_ID = aplikasiId AND CREATED_BY = 'MIGRATOR_S';

						UPDATE DFT_A_NOTA SET LAST_MODIFIED_BY = username, LAST_MODIFIED_DATE = SYSDATE,  
							NO_WARTA = B4URUSAN.NO_WARTA, TRKH_WARTA = B4URUSAN.TARIKH_WARTA
							WHERE APLIKASI_ID = aplikasiId AND CREATED_BY = 'MIGRATOR_S';

            IF kodUrusan IN ('IS') THEN
              /* 08/10/18 Azrilisam
              UPDATE DFT_A_ISMEN SET LAST_MODIFIED_BY = username, LAST_MODIFIED_DATE = SYSDATE,
                HARI = B4URUSAN.TEMPOH_HARI, BULAN = B4URUSAN.TEMPOH_BULAN, TAHUN = B4URUSAN.TEMPOH_TAHUN,
                TARIKH_KUATKUASA = B4URUSAN.TARIKH_KUATKUASA, TARIKH_LUPUT = B4URUSAN.TARIKH_LUPUT 
                WHERE A_SURATCARA_ID = (SELECT A_SURATCARA_ID FROM DFT_A_SURATCARA WHERE APLIKASI_ID = aplikasiId AND CREATED_BY = 'MIGRATOR_S');
              */

              jenisTanahIsmenTanggung := getSakIdBySakKod('JTI_TANGGUNG');
              jenisTanahIsmenKuasai := getSakIdBySakKod('JTI_KUASAI');

              IF B4URUSAN.ID_HAKMILIK_TANGGUNG IS NOT NULL THEN
                IF idHakmilik = trim(B4URUSAN.ID_HAKMILIK_TANGGUNG) THEN
                  UPDATE UMM_A_HKMLK SET JNS_TNH_ISMEN_ID = jenisTanahIsmenTanggung 
                  WHERE APLIKASI_ID = aplikasiId AND ID_HKMLK = idHakmilik AND CREATED_BY = 'MIGRATOR_S'; 
                END IF;
              END IF;

              IF B4URUSAN.ID_HAKMILIK_KUASAI IS NOT NULL THEN
                IF idHakmilik = trim(B4URUSAN.ID_HAKMILIK_KUASAI) THEN
                  UPDATE UMM_A_HKMLK SET JNS_TNH_ISMEN_ID = jenisTanahIsmenKuasai 
                  WHERE APLIKASI_ID = aplikasiId AND ID_HKMLK = idHakmilik AND CREATED_BY = 'MIGRATOR_S';
                END IF;
              END IF;
            END IF;

					EXCEPTION
						WHEN OTHERS THEN
							errMsgTransactional := 'UPDATE TABLES DFT_A_XXX B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' B4URUSAN ID:' ||
										B4URUSAN.BORANG4_SENARAI_URUSAN_ID || ' ' || SQLERRM || ':LCC:' || loccode; 
							ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgTransactional);

							msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgTransactional;
					/* end Transactional Tables */
					END;
					ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'urusan - update transactional tables done');
				END IF;

			/* end loop to insert all urusan and construct urusan_tbl*/
			END LOOP;

			/* start loop to insert urusan terlibat*/
			FOR B4URUSAN IN C_B4_URUSAN LOOP
				DECLARE
					errMsgUrusanTerlibat VARCHAR2(250);

					CURSOR C_B4_URUSAN_TERLIBAT IS  
						SELECT * FROM ET_DMSA.BORANG4_URUSAN_TERLIBAT
						WHERE URUSAN = B4URUSAN.BORANG4_SENARAI_URUSAN_ID;
				BEGIN
					/* inner urusan terlibat loop */
					FOR U_TERLIBAT IN C_B4_URUSAN_TERLIBAT LOOP

						DECLARE
              aplikasiSemasa NUMBER(19,0);
							aplikasiTerlibat NUMBER(19,0);
							appHakmilikTerlibat NUMBER(19,0);
						/* DFT_A_SERHN_TERLBT */
						BEGIN
              aplikasiTerlibat := urusan_tbl(U_TERLIBAT.URUSAN_TERLIBAT);           
							aplikasiSemasa := urusan_tbl(U_TERLIBAT.URUSAN);
							appHakmilikTerlibat := appHakmilik_tbl(aplikasiSemasa);

							INSERT INTO DFT_A_SERAHAN_TERLIBAT(A_SERAHAN_TERLIBAT_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
															VERSION, APLIKASI_ID, A_HKMLK_ID, KEUTAMAAN)
								VALUES(SEQ_A_SERAHAN_TERLIBAT.NEXTVAL, username, sysdate, username, sysdate,
										0, aplikasiTerlibat, appHakmilikTerlibat, U_TERLIBAT.KEUTAMAAN);
						EXCEPTION
							WHEN OTHERS THEN
								errMsgUrusanTerlibat := 'DFT_A_SERHN_TERLBT B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' B4URUSAN ID:' ||
														B4URUSAN.BORANG4_SENARAI_URUSAN_ID || ' ' || SQLERRM; 
								ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgUrusanTerlibat);							

								msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgUrusanTerlibat;
						/* end DFT_A_SERHN_TERLBT */
						END;
					/* end inner urusan terlibat loop */
					END LOOP;
				END;
			/* end loop to insert urusan terlibat*/
			END LOOP;
		/* end B4 urusan block */
		END;

		IF listOfIdPengenalan IS NOT NULL THEN
			ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'deleted aplikasi start');
			DECLARE
				v_query	VARCHAR2 (2000);

				TYPE refcur_type IS REF CURSOR;
				C_APP_DEL	refcur_type;		
				APP_DEL	NUMBER(19,0);

--				CURSOR C_APP_DEL IS SELECT ap.APLIKASI_ID FROM UMM_APLIKASI ap
--					JOIN IND_REKOD_URSN u ON (u.APLIKASI_ID = ap.APLIKASI_ID)
--					LEFT JOIN UMM_A_HKMLK ah ON (ap.APLIKASI_ID = ah.APLIKASI_ID) 
--					WHERE ah.A_HKMLK_ID IS NULL AND u.VERSI_AKHIR = versiDhdId GROUP BY ap.APLIKASI_ID;

			/* block to delete unused aplikasi child tables and aplikasi itself (case when urusan has been deleted in DMSA) */
			BEGIN
				/* start delete Aplikasi loop */			
				v_query := 'SELECT APLIKASI_ID FROM
					(
						SELECT ap.ID_PENGENALAN, ap.APLIKASI_ID FROM UMM_APLIKASI ap
						LEFT JOIN UMM_A_HKMLK ah ON (ap.APLIKASI_ID = ah.APLIKASI_ID) 
						WHERE ID_PENGENALAN IN (' || listOfIdPengenalan || ')
					)
					WHERE ID_PENGENALAN NOT IN (
						SELECT ap1.ID_PENGENALAN FROM UMM_APLIKASI ap1
						LEFT JOIN UMM_A_HKMLK ah1 ON (ap1.APLIKASI_ID = ah1.APLIKASI_ID) 
						WHERE ah1.ID_HKMLK = ''' || idHakmilik || ''')';

				OPEN C_APP_DEL FOR v_query;

--				FOR APP_DEL IN C_APP_DEL LOOP
				LOOP
					FETCH C_APP_DEL INTO APP_DEL;

					EXIT WHEN C_APP_DEL%NOTFOUND;

					DECLARE
						errMsgDelApp VARCHAR2(250);
						noOfOtherAppHkmlk NUMBER;
						tableName VARCHAR2(100);
					/* block to delete Aplikasi and transactional tables */
					BEGIN
						SELECT COUNT(A_HKMLK_ID) INTO noOfOtherAppHkmlk FROM UMM_A_HKMLK 
						WHERE APLIKASI_ID = APP_DEL AND ID_HKMLK NOT LIKE idHakmilik;

						IF noOfOtherAppHkmlk = 0 THEN
							tableName := 'DFT_A_NOTA';

							--DELETE FROM DFT_A_BTRN_NOTA WHERE APLIKASI_ID = APP_DEL AND CREATED_BY = 'MIGRATOR_S';

							DELETE FROM DFT_A_NOTA WHERE APLIKASI_ID = APP_DEL AND CREATED_BY = 'MIGRATOR_S';

							tableName := 'DFT_A_BORANG';
							DELETE FROM DFT_A_BORANG WHERE APLIKASI_ID = APP_DEL AND CREATED_BY = 'MIGRATOR_S';
							/* 08/10/18 Azrilisam
							tableName := 'DFT_A_PAJAKAN_TERPRNC';
							DELETE FROM DFT_A_PAJAKAN_TERPRNC t WHERE t.PAJAKAN_ID IN (
								SELECT p.A_PAJAKAN_ID FROM DFT_A_PAJAKAN p 
								JOIN DFT_A_SURATCARA sc ON (p.A_SURATCARA_ID = sc.A_SURATCARA_ID)
								WHERE sc.APLIKASI_ID = APP_DEL) AND CREATED_BY = 'MIGRATOR_S';

							tableName := 'DFT_A_PAJAKAN';
							DELETE FROM DFT_A_PAJAKAN WHERE A_SURATCARA_ID IN (
								SELECT A_SURATCARA_ID FROM DFT_A_SURATCARA WHERE APLIKASI_ID = APP_DEL)
								AND CREATED_BY = 'MIGRATOR_S';

							DELETE FROM DFT_A_GADAIAN WHERE A_SURATCARA_ID IN (
								SELECT A_SURATCARA_ID FROM DFT_A_SURATCARA WHERE APLIKASI_ID = APP_DEL)
								AND CREATED_BY = 'MIGRATOR_S';
              */
              tableName := 'DFT_A_BTRN_SRTCARA';
              DELETE FROM DFT_A_BTRN_SRTCARA WHERE A_BTRN_SRTCARA_ID IN (
              SELECT A_BTRN_SRTCARA_ID FROM DFT_A_BTRN_SRTCARA P JOIN DFT_A_SRTCARA SC ON (P.A_SRTCARA_ID = SC.A_SRTCARA_ID) 
              WHERE SC.APLIKASI_ID = APP_DEL) AND CREATED_BY = 'MIGRATOR_S';

							tableName := 'DFT_A_SURATCARA';
							DELETE FROM DFT_A_SRTCARA WHERE APLIKASI_ID = APP_DEL AND CREATED_BY = 'MIGRATOR_S';

							tableName := 'UMM_APLIKASI';
              DELETE FROM RPT_KPI_APLIKASI WHERE APLIKASI_ID = APP_DEL;

							DELETE FROM UMM_APLIKASI WHERE APLIKASI_ID = APP_DEL AND CREATED_BY = 'MIGRATOR_S';

							ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'deleted aplikasi done : ' || APP_DEL);
						END IF;
					EXCEPTION
						WHEN OTHERS THEN
							errMsgDelApp := tableName || ' ERROR DELETING (UNUSED) APLIKASI | APLIKASI_ID:' || APP_DEL || ' ' || SQLERRM;
              ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgDelApp);

							msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgDelApp;
					/* end block to delete Aplikasi and transactional tables */
					END;
				/* end delete Aplikasi loop */
				END LOOP;
			/* block to delete unused aplikasi child tables and aplikasi itself */
			END;
		END IF;

		ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','I',arg_hakmilik_id,null,null,'All urusan done');

		<<skipB4>>
		IF errMsgBorang4 IS NOT NULL THEN
			ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgBorang4);
		END IF;
	/* end b4 asas loop */
	END;

	--COMMIT;

	IF msgNotifyUser IS NOT NULL THEN
		raise exceptionNotifyUser;
	END IF;
--------------------------------------------------------------------------------	
  FOR C IN (SELECT  A.STRATA_PTK_AKSESORI_ID, C.LUAS_PETAK LUAS, F.UNIT_LUAS_ID
            FROM    IND_STRATA_PTK_AKSESORI A, IND_HKMLK B, ET_DMSA.BORANG2_PETAK_AKSESORI C, IND_HKMLK D,
                    ET_DMSA.BORANG2_ASAS E,
                   (SELECT  X.SENARAI_AHLI_KUMPULAN_ID SAK_ID, Y.SENARAI_AHLI_KUMPULAN_ID UNIT_LUAS_ID
                    FROM    ET_DMSA.RJK_SENARAI_AHLI_KUMPULAN X, RJK_SENARAI_AHLI_KUMPULAN Y
                    WHERE   X.KOD = Y.STRATA_KOD) F        
            WHERE   A.LUAS IS NULL AND A.HKMLK_ID = B.HKMLK_ID AND A.NAMA = TRIM(C.PETAK_AKSESORI)
                    AND B.STRATA_INDUK_ID = D.HKMLK_ID AND D.ID_HKMLK = E.HAKMILIK_ID AND C.BORANG2_ASAS_ID = E.BORANG2_ASAS_ID
                    AND C.UNIT_LUAS = F.SAK_ID AND C.LUAS_PETAK IS NOT NULL AND B.ID_HKMLK = arg_hakmilik_id) LOOP
  UPDATE IND_STRATA_PTK_AKSESORI SET LUAS = C.LUAS, UNIT_LUAS_ID = C.UNIT_LUAS_ID WHERE STRATA_PTK_AKSESORI_ID = C.STRATA_PTK_AKSESORI_ID;
  END LOOP;
  --COMMIT;
--------------------------------------------------------------------------------	
  FOR rec in (SELECT hkmlk_id FROM ind_hkmlk 
              WHERE strata_induk_id IS NOT NULL AND hkmlk_pelbagai_id IS NULL and id_hkmlk = arg_hakmilik_id) LOOP
  seq := seq_hkmlk_pelbagai.nextval;

  INSERT INTO ind_hkmlk_pelbagai(hkmlk_pelbagai_id,created_by,created_date,last_modified_by,last_modified_date,version,
                                 flag_terkini,flag_silap,flag_gantung,flag_endos_cukai_ptk,flag_kuota_bumi,
                                 JNS_PTK_ID) 
                         VALUES (seq,'MIGRATOR_S',SYSDATE,'MIGRATOR_S',sysdate,'0','N','N','N','N','N',
                                  jenisPetakId);       
  UPDATE ind_hkmlk SET hkmlk_pelbagai_id=seq WHERE hkmlk_id = rec.hkmlk_id;
  END LOOP;
  --COMMIT; 
-------------------------------------------------------------------------------------------------------------------------	 

  --Feature #63181 Ursn KRM from master title
  IF (idHakmilikStrataInduk = '080202GRN00154840' OR idHakmilikStrataInduk = '080501PN00386355') THEN
    DECLARE
      errMsgRekodUrusan VARCHAR2(250);
      aplikasiId IND_REKOD_URSN.APLIKASI_ID%TYPE;
      kandunganBaru IND_REKOD_URSN.KANDUNGAN_BARU%TYPE;
      tdknDiambil IND_REKOD_URSN.TDKN_DIAMBIL%TYPE;
    /* IND_REKOD_URUSAN */
    BEGIN
      select c.aplikasi_id, c.kandungan_baru, c.tdkn_diambil into aplikasiId, kandunganBaru, tdknDiambil 
      from ind_hkmlk a, ind_versi_dhd b, ind_rekod_ursn c, umm_aplikasi d
      where a.id_hkmlk = idHakmilikStrataInduk
      and a.hkmlk_id = b.hkmlk_id
      and b.flag_aktif = 'Y' 
      and b.versi_dhd_id = c.versi_akhir_id
      and c.flag_kuatkuasa = 'Y'
      and c.aplikasi_id = d.aplikasi_id
      and d.ursn_id = (select ursn_id from ind_ursn where kod = 'KRM');

      INSERT INTO IND_REKOD_URSN (REKOD_URSN_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
              VERSION, FLAG_KUATKUASA, VERSI_MULA, VERSI_AKHIR_ID, APLIKASI_ID, VERSI_SBLM_ID, KANDUNGAN_BARU, TDKN_DIAMBIL)
      VALUES( SEQ_REKOD_URSN.NEXTVAL, username, SYSDATE, username, SYSDATE, 
        '0', 'Y', versiDhdId, versiDhdId, aplikasiId, null, kandunganBaru, tdknDiambil);

      ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','I',arg_hakmilik_id,null,null,'urusan - rekod urusan KRM done based on master title');
    END;

  END IF;
  --dbms_output.putline('Done for ' || arg_hakmilik_id);
  --COMMIT;
----------------------------------------------------------------------------------------------------------------------------

EXCEPTION

	WHEN exceptionNotifyUser THEN
    /* 09/10/18 Azrilisam
		RAISE_APPLICATION_ERROR(-20001, 'Masalah migration Borang 4 untuk idHakmilik ' || arg_hakmilik_id || ' : . ' || msgNotifyUser
			|| ' Sila rujuk support team jika masih ada masalah selepas pembetulan di DMSA.' );
    */ 
    INSERT INTO DMSA_ERR_LOG (LOG_ID, BORANG, HAKMILIK_ID, ORA_ERR, CREATED_DATE) 
                      VALUES (SEQ_DMSA_ERR.NEXTVAL, 4, arg_hakmilik_id, 'Masalah migration Borang 4 untuk idHakmilik ' || arg_hakmilik_id || ' : . ' || msgNotifyUser
                              || ' Sila rujuk support team jika masih ada masalah selepas pembetulan di DMSA.', SYSDATE);
	--COMMIT;  

	WHEN noBorang4Match THEN
    /* 09/10/18 Azrilisam  
		RAISE_APPLICATION_ERROR(-20001, 'No Borang 4 with this idHakmilik:' || arg_hakmilik_id || ' is found.');
    */  
    INSERT INTO DMSA_ERR_LOG (LOG_ID, BORANG, HAKMILIK_ID, ORA_ERR, CREATED_DATE) 
                      VALUES (SEQ_DMSA_ERR.NEXTVAL, 4, arg_hakmilik_id, 'No Borang 4 with this idHakmilik:' || arg_hakmilik_id || ' is found.', SYSDATE);
		--COMMIT;     

	WHEN OTHERS THEN
		NULL;
    /* 09/10/18 Azrilisam    
		ET_MAIN.PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','ERROR IN OUTER BLOCK: ' || SQLERRM);
    */
	
    errMsg2 := loccode || ' || ' || SQLERRM; 
   --RAISE NOTICE 'An error occurred: %', loccode || ' || ' || SQLERRM;
        --RAISE;
    INSERT INTO DMSA_ERR_LOG (LOG_ID, BORANG, HAKMILIK_ID, ORA_ERR, CREATED_DATE) 
                      VALUES (SEQ_DMSA_ERR.NEXTVAL, 4, arg_hakmilik_id, 'ERROR IN OUTER BLOCK: ' || errMsg2, SYSDATE); 
    --COMMIT;  


END
$procedure$
 LANGUAGE edbspl
;

-- DROP PROCEDURE et_main_uat.migrate_borang4_by_hakmilikid_staged(varchar);

CREATE OR REPLACE PROCEDURE et_main_uat.migrate_borang4_by_hakmilikid_staged(IN arg_hakmilik_id character varying)
 SECURITY DEFINER
AS $procedure$
	
	loccode varchar2(100) := '';
    v_LogLevel varchar2(1000) := 'Debug';

	/* constants and variables */
	destination CONSTANT VARCHAR2(100) := 'et_main';
	username CONSTANT VARCHAR2(100) := 'MIGRATOR_S';
	migrationTime CONSTANT TIMESTAMP(6) := sysdate;
	migrationScript CONSTANT VARCHAR2(20) := 'CALL_PROCEDURE';
	errMsg VARCHAR2(250);
	msgNotifyUser VARCHAR2(4000);
  	errMsg2 VARCHAR2(1000);  

	/* hardcoded variables */
	statusTanahDaftarId NUMBER(19,0);
	jenisPengenalanTiada NUMBER(19,0);
	jenisPbTiada NUMBER(19,0);
	jenisPbMc NUMBER(19,0);
	negeriTiada NUMBER(19,0);
	bandarTiada NUMBER(19,0);
	jenisPelanLain NUMBER(19,0);
	jenisPelanPetak NUMBER(19,0);
	jenisPelanPetakAksesori NUMBER(19,0);
	unitLuasaTiada NUMBER(19,0);
	pejabatId NUMBER(19,0);
	caraBayaranTiada NUMBER(19,0);
	medanIdIndPelan NUMBER(19,0);
  jenisPetakId NUMBER(19,0);
  seq NUMBER;
  idHakmilikStrataInduk IND_HKMLK.ID_HKMLK%TYPE;
  versiDhdId NUMBER(19,0);
  pejabatKod VARCHAR2(2);

	B4ASAS ET_DMSA.BORANG4_ASAS%ROWTYPE;

	TYPE BORANG4_INDUK_REF IS TABLE OF NUMBER INDEX BY VARCHAR2(19);

	/* exceptions */
	tiadaStrataInduk EXCEPTION;
	tiadaNoHakmilik EXCEPTION;
	tiadaNoPetak EXCEPTION;
	tiadaNoBangunan EXCEPTION;
	tiadaNoTingkat EXCEPTION;
	noBorang2Match EXCEPTION;
	tiadaMaklumatHakmilik EXCEPTION;
	tooManyMaklumatHakmilik EXCEPTION;
	tiadaJenisBorang4 EXCEPTION;
	tiadaNoBlokSementara EXCEPTION;
	petaksAksIsNull EXCEPTION;
	versiIsNotZero EXCEPTION;
	noBorang4Match EXCEPTION;
	appMoreThanOne EXCEPTION;
	exceptionNotifyUser EXCEPTION;

    --bugfixes
    noah1 number;
    noah2 number;
    noah3 number;
    noah4 number;

    --pcp
    n_nota_id number;
    found number;
    msgerrpcp varchar2(2000);

    foundDokPenentusahan number;
    aDokPenentusahanId number;

--------------------------------------------------------------------------------		
	/* functions (start) */
	FUNCTION findStrataIndukIdByIdHakmilik(idHakmilik IN  VARCHAR2) 
	RETURN NUMBER IS
		indukId NUMBER(19,0);
	BEGIN
	
		PR_TKR_LOG('findStrataIndukIdByIdHakmilik','I',arg_hakmilik_id,null,null,'ID HM:' || idHakmilik);
	
		SELECT HKMLK_ID INTO indukId
		FROM IND_HKMLK WHERE ID_HKMLK = idHakmilik;
		RETURN indukId;
	EXCEPTION
		WHEN OTHERS THEN
			RAISE tiadaStrataInduk;
			RETURN NULL;
	END;
--------------------------------------------------------------------------------		
	PROCEDURE findHakmilikEtanah(idHakmilik IN VARCHAR2, hmId OUT NUMBER, mHmId OUT NUMBER, dhdVId OUT NUMBER, versiNo OUT NUMBER) IS
	BEGIN
		SELECT v.VERSI_DHD_ID, v.HKMLK_ID, v.MKLMT_HKMLK_ID, v.VERSI_DHD 
		INTO dhdVId, hmId, mHmId, versiNo
		FROM IND_VERSI_DHD v JOIN IND_HKMLK h ON (v.HKMLK_ID = h.HKMLK_ID)
		WHERE v.FLAG_AKTIF = 'Y' AND upper(h.ID_HKMLK) = upper(idHakmilik);
	EXCEPTION
		WHEN NO_DATA_FOUND THEN
            PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'ERR findHakmilikEtanah(' || idHakmilik || ') ' || SQLERRM);
			hmId := NULL;
			mHmId := NULL;
			dhdVId := NULL;
	END;
--------------------------------------------------------------------------------		
  FUNCTION findBorang2NoVersi(strataIndukId IN NUMBER) 
	RETURN NUMBER IS
		versiNoB2 NUMBER(19,0);
	BEGIN
		SELECT NO_VERSI INTO versiNoB2
		FROM IND_STRATA_IDX_VERSI WHERE HKMLK_ID = strataIndukId
    AND FLAG_AKTIF = 'Y';
		RETURN versiNoB2;
	EXCEPTION
		WHEN OTHERS THEN
            PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'ERROR findBorang2NoVersi(' || strataIndukId || ')');
			RETURN NULL;
	END;
--------------------------------------------------------------------------------	 
	FUNCTION findSIndeksVIdByIdSIndukId(strataIndukId IN NUMBER) 
	RETURN NUMBER IS
		versiId NUMBER(19,0);
	BEGIN
		SELECT max(STRATA_IDX_VERSI_ID) INTO versiId
		FROM IND_STRATA_IDX_VERSI WHERE HKMLK_ID = strataIndukId;
		RETURN versiId;
	EXCEPTION
		WHEN OTHERS THEN
            PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'ERROR findSIndeksVIdByIdSIndukId(' || strataIndukId || ')');
			RETURN NULL;
	END;
--------------------------------------------------------------------------------		
	FUNCTION returnSpaceIfNull(field IN  VARCHAR2) 
	RETURN VARCHAR2 IS
		tempVariable VARCHAR2(200);
	BEGIN
		tempVariable := trim(field);
		IF tempVariable IS NULL THEN
			tempVariable := ' ';
		END IF;
		RETURN tempVariable;
	END;
--------------------------------------------------------------------------------		
	FUNCTION getSakIdBySakKod(sakKod IN  VARCHAR2) 
	RETURN NUMBER IS
		sakId NUMBER(19, 0);
	BEGIN
		SELECT SENARAI_AHLI_KUMPULAN_ID INTO sakId
		FROM RJK_SENARAI_AHLI_KUMPULAN WHERE KOD = sakKod;
		RETURN sakId;
	END;
--------------------------------------------------------------------------------		
	FUNCTION getDmsaSakKodByDmsaSakId(sakId IN  NUMBER, blockDescription IN VARCHAR2) 
	RETURN VARCHAR2 IS
		sakKod VARCHAR2(120);
	BEGIN
		SELECT KOD INTO sakKod
		FROM ET_DMSA.RJK_SENARAI_AHLI_KUMPULAN WHERE SENARAI_AHLI_KUMPULAN_ID = sakId ;
		RETURN sakKod;
	EXCEPTION
		WHEN OTHERS THEN
			PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'ERROR getDmsaSakKodByDmsaSakId('||sakId||')'|| blockDescription||' '||SQLERRM);
			RETURN NULL;
	END;
--------------------------------------------------------------------------------		
	FUNCTION getSakIdByDmsaSakKod(sakKod IN  VARCHAR2, blockDescription IN VARCHAR2, sk in VARCHAR2) 
	RETURN NUMBER IS
		sakId NUMBER(19, 0);
	BEGIN
		SELECT SENARAI_AHLI_KUMPULAN_ID INTO sakId
		FROM RJK_SENARAI_AHLI_KUMPULAN WHERE STRATA_KOD = sakKod and senarai_kumpulan_id = (select senarai_kumpulan_id from rjk_senarai_kumpulan where kod = sk);-- and senarai_kumpulan_id = 213;
		RETURN sakId;
	EXCEPTION
		WHEN OTHERS THEN
			PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'ERROR getSakIdByDmsaSakKod('||sakKod||')'||blockDescription||' '||SQLERRM);
			RETURN NULL;
	END;
--------------------------------------------------------------------------------		
	FUNCTION getSakIdByDmsaSakId(dmsaSakId IN NUMBER, blockDescription IN VARCHAR2, sk in VARCHAR2)
	RETURN NUMBER IS
		sakId NUMBER(19,0);
		dmsaSakKod VARCHAR2(120);
	BEGIN
		dmsaSakKod := getDmsaSakKodByDmsaSakId(dmsaSakId, blockDescription);
		sakId := getSakIdByDmsaSakKod(dmsaSakKod, blockDescription,sk);
		RETURN sakId;
	END;
--------------------------------------------------------------------------------		
	FUNCTION getSeksyenIdByDmsaSeksyenId(dmsaSeksyenId IN NUMBER, etanahBpmId IN NUMBER)
	RETURN NUMBER IS
		seksyenKod ET_DMSA.IND_SEKSYEN.KOD%TYPE;
		seksyenId NUMBER(19,0);
	BEGIN
		SELECT KOD INTO seksyenKod FROM ET_DMSA.IND_SEKSYEN WHERE SEKSYEN_ID = dmsaSeksyenId;
		SELECT SEKSYEN_ID INTO seksyenId FROM IND_SEKSYEN WHERE KOD = seksyenKod AND BANDAR_PEKAN_MUKIM_ID = etanahBpmId;
		RETURN seksyenId;
	EXCEPTION
		WHEN OTHERS THEN
			PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'ERROR getSeksyenIdByDmsaSeksyenId('||dmsaSeksyenId||')'||SQLERRM);
			RETURN NULL;
	END;
--------------------------------------------------------------------------------		
	FUNCTION getBorang2ByIdHakmilik(idHakmilikInduk IN VARCHAR2)
	RETURN ET_DMSA.BORANG2_ASAS%ROWTYPE IS
		borang2 ET_DMSA.BORANG2_ASAS%ROWTYPE;
	BEGIN
		SELECT * INTO borang2 FROM ET_DMSA.BORANG2_ASAS WHERE HAKMILIK_ID = idHakmilikInduk;
		RETURN borang2;
	EXCEPTION
		WHEN OTHERS THEN
			RAISE noBorang2Match;
			RETURN NULL;
	END;
--------------------------------------------------------------------------------		
	FUNCTION getMklmtHkmlkByStrataIndukId(strataIndukId IN NUMBER)
	RETURN IND_MKLMT_HKMLK%ROWTYPE IS
		maklumatHakmilikId NUMBER(19,0);
		maklumatHakmilik IND_MKLMT_HKMLK%ROWTYPE;
	BEGIN
		SELECT MKLMT_HKMLK_ID INTO maklumatHakmilikId 
		FROM IND_VERSI_DHD WHERE HKMLK_ID = strataIndukId AND FLAG_AKTIF = 'Y';

		SELECT * INTO maklumatHakmilik FROM IND_MKLMT_HKMLK
		WHERE MKLMT_HKMLK_ID = maklumatHakmilikId;
		RETURN maklumatHakmilik;
	EXCEPTION
		WHEN TOO_MANY_ROWS THEN
			RAISE tooManyMaklumatHakmilik;
			RETURN NULL;
		WHEN OTHERS THEN
			RAISE tiadaMaklumatHakmilik;
			RETURN NULL;
	END;
--------------------------------------------------------------------------------
    PROCEDURE LOG(msg varchar2, enabled boolean) is
    BEGIN
        IF v_LogLevel = 'Debug' AND enabled = true then
            PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,msg);
        end if;
    END;
	/* functions (end) */
--------------------------------------------------------------------------------	
BEGIN
	-- block to find b4asas  
    BEGIN
      SELECT * INTO B4ASAS 
      FROM ET_DMSA.BORANG4_ASAS
      WHERE BORANG4_ASAS_ID = (
                SELECT BORANG4_ASAS_ID FROM ET_DMSA.VIEW_B4ASAS_IDHAKMILIK WHERE ID_HAKMILIK = UPPER(arg_hakmilik_id));  

    EXCEPTION WHEN OTHERS THEN
      RAISE noBorang4Match;
    /* end block to find b4asas */
    END;

	statusTanahDaftarId := getSakIdBySakKod('STAHDFT');
	jenisPbTiada := getSakIdBySakKod('JNNULL');
	jenisPbMc := getSakIdBySakKod('JENMC');
	jenisPengenalanTiada := getSakIdBySakKod('JENNULL');
	negeriTiada := getSakIdBySakKod('00');
	bandarTiada := getSakIdBySakKod('2002');
	jenisPelanLain := getSakIdBySakKod('JENIS_PELAN_LAIN-LAIN');
	jenisPelanPetak := getSakIdBySakKod('JENIS_PELAN_PETAK');
	jenisPelanPetakAksesori := getSakIdBySakKod('JENIS_PELAN_PETAK_AKSESORI');
	unitLuasaTiada := getSakIdBySakKod('UNIKELMP');
	caraBayaranTiada := getSakIdBySakKod('CABNULL');
	medanIdIndPelan := getSakIdBySakKod('IND_PELAN');

    --  SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Pengarah Tanah dan Galian Negeri Perak';

	DECLARE
		errMsgBorang4 VARCHAR2(250);
		idHakmilik IND_HKMLK.ID_HKMLK%TYPE;
		hakmilikId NUMBER(19,0);
		maklumatHakmilikId NUMBER(19, 0);
		jenisHakmilikId NUMBER(19,0);
		strataIndukId NUMBER(19, 0);
		indeksVersiIndukId NUMBER(19,0);
        noVersiIndukId NUMBER(19,0);
		indeksTerperinciId NUMBER(19,0);
		bpmId NUMBER(19,0);
		noPetak ET_DMSA.BORANG4_ASAS.NO_PETAK%TYPE;
		noTing ET_DMSA.BORANG4_ASAS.NO_TINGKAT%TYPE;
		noBgnn ET_DMSA.BORANG4_ASAS.NO_BANGUNAN%TYPE;
		noHakmilik ET_DMSA.BORANG4_ASAS.NO_HAKMILIK%TYPE;
        daerahKod VARCHAR2(2);

		bpmKod ET_DMSA.IND_BANDAR_PEKAN_MUKIM.KOD%TYPE;
		jenisHakmilikKod ET_DMSA.RJK_SENARAI_AHLI_KUMPULAN.KOD%TYPE;
		jenisBorangKod ET_DMSA.RJK_SENARAI_AHLI_KUMPULAN.KOD%TYPE;

		pemilik_tbl BORANG4_INDUK_REF;
		kumpulanPb_tbl BORANG4_INDUK_REF;
		urusan_tbl BORANG4_INDUK_REF;
		appHakmilik_tbl BORANG4_INDUK_REF;

		listOfIdPengenalan VARCHAR2(2000);
	
    /* start b4 asas loop */
	BEGIN

		DECLARE
			versiNo NUMBER;
		/* IND_HKMLK */
		BEGIN
		
			loccode := 'beforekod';
		
			SELECT KOD INTO daerahKod
			FROM ET_DMSA.IND_DAERAH WHERE DAERAH_ID = B4ASAS.DAERAH_ID;    
			
			loccode := 'afterkod';

			SELECT KOD INTO bpmKod
			FROM ET_DMSA.IND_BANDAR_PEKAN_MUKIM WHERE BANDAR_PEKAN_MUKIM_ID = B4ASAS.BANDAR_PEKAN_MUKIM_ID;
			
			loccode := 'bpmkod';
			

			SELECT BANDAR_PEKAN_MUKIM_ID INTO bpmId
			FROM IND_BANDAR_PEKAN_MUKIM WHERE KOD = bpmKod AND DAERAH_ID = B4ASAS.DAERAH_ID;
			loccode := 'bpm';

			jenisHakmilikKod := getDmsaSakKodByDmsaSakId(B4ASAS.JENIS_HAKMILIK, 'B4ASAS.JENIS_HAKMILIK');
			
			loccode := 'jkod of ' || B4ASAS.JENIS_HAKMILIK;
			
			SELECT JNS_HKMLK_ID INTO jenisHakmilikId
			FROM RJK_JNS_HKMLK WHERE KOD = jenisHakmilikKod;
			
			loccode := 'jhm';

			noHakmilik := replace(trim(B4ASAS.NO_HAKMILIK), '	');
			noPetak := replace(trim(upper(B4ASAS.NO_PETAK)), '	');
			noTing := replace(trim(upper(B4ASAS.NO_TINGKAT)), '	');
			noBgnn := replace(trim(upper(B4ASAS.NO_BANGUNAN)), '	');

            /* 08/10/18 Azrilisam
            -- PTG
            IF pejabatKod = '00' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Pengarah Tanah dan Galian Negeri Perak';
            -- Tapah
            ELSIF pejabatKod = '01' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Batang Padang';  
            -- Manjung
            ELSIF pejabatKod = '02' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Manjung';  
            -- Batu Gajah
            ELSIF pejabatKod = '03' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Kinta'; 
            -- Kerian
            ELSIF pejabatKod = '04' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Kerian';   
            -- Kuala Kangsar
            ELSIF pejabatKod = '05' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Kuala Kangsar';    
            -- Taiping
            ELSIF pejabatKod = '06' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Larut Matang dan Selama, Taiping';  
            -- Hilir Perak
            ELSIF pejabatKod = '07' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Hilir Perak';  
            -- Gerik
            ELSIF pejabatKod = '08' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Hulu Perak, Gerik';  
            -- Selama
            ELSIF pejabatKod = '09' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Selama'; 
            -- Perak Tengah
            ELSIF pejabatKod = '10' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Perak Tengah, Seri Iskandar'; 
            -- Muallim
            ELSIF pejabatKod = '11' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Muallim';   
            -- Ipoh
            ELSIF pejabatKod = '12' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Daerah Kecil Ipoh';  
            -- Kampar
            ELSIF pejabatKod = '13' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Kampar';   
            -- Sungai Siput
            ELSIF pejabatKod = '14' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Sungai Siput';   
            -- Lenggong
            ELSIF pejabatKod = '15' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Lenggong';  
            -- Pengkalan Hulu
            ELSIF pejabatKod = '16' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Pengkalan Hulu'; 
            -- Kampung Gajah
            ELSIF pejabatKod = '17' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Kampung Gajah';   
            -- Bagan Datuk
            ELSIF pejabatKod = '18' THEN
            SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE NAMA = 'Pejabat Daerah dan Tanah Bagan Datuk';  
            ELSE
            pejabatId := NULL;
            END IF;      
                */
            
			IF noHakmilik IS NULL THEN
				RAISE tiadaNoHakmilik;
			END IF;

			noHakmilik := CASE WHEN LENGTH(noHakmilik) < 8 THEN lpad(noHakmilik, 8, '0') ELSE noHakmilik END;
			--idHakmilik := B4ASAS.NEGERI_ID || '00' || bpmKod || jenisHakmilikKod || noHakmilik;
			idHakmilik := '11' || daerahKod || bpmKod || jenisHakmilikKod || noHakmilik;      
			strataIndukId := findStrataIndukIdByIdHakmilik(idHakmilik);
			indeksVersiIndukId := findSIndeksVIdByIdSIndukId(strataIndukId);
            noVersiIndukId := findBorang2NoVersi(strataIndukId);
			idHakmilikStrataInduk := idHakmilik;

            --find out pejabat id and pejabat kod for aplikasi
            IF (    jenisHakmilikKod = 'GRN' 
                  OR jenisHakmilikKod = 'PN'
                  OR jenisHakmilikKod = 'HSD') THEN 
                        pejabatKod := '00';
                        SELECT PEJABAT_ID INTO pejabatId FROM IND_PEJABAT WHERE KOD = '00';
                        ELSE --GM PM HSM         
                        SELECT PEJABAT_ID INTO pejabatId FROM IND_BANDAR_PEKAN_MUKIM WHERE BANDAR_PEKAN_MUKIM_ID = bpmId;
                        SELECT KOD INTO pejabatKod FROM IND_PEJABAT WHERE PEJABAT_ID = pejabatId;
            END IF;
            --

			jenisBorangKod := getDmsaSakKodByDmsaSakId(B4ASAS.JENIS_BORANG, 'B4ASAS.JENIS_BORANG');
			
			loccode := 'jenisBorangKod:' || B4ASAS.JENIS_BORANG;
			
			IF jenisBorangKod LIKE 'JNS_DOK_B4A' THEN
				IF noBgnn IS NULL THEN
					RAISE tiadaNoBlokSementara;
				ELSE 
                    idHakmilik := idHakmilik || '/' || noBgnn;
                    --	idHakmilik := idHakmilik || CASE WHEN LENGTH(noBgnn) < 5 THEN lpad(noBgnn, 5, '0') ELSE noBgnn END;

                    IF(upper(noBgnn) LIKE 'PL%') THEN
						jenisPetakId := getSakIdBySakKod('JNSSTRBPT'); --Blok Sementara Petak Tanah
					ELSE
						jenisPetakId := getSakIdBySakKod('JNSSTRBLS'); --Blok Sementara
					END IF;
				END IF;

			ELSIF jenisBorangKod LIKE 'JNS_DOK_B4' THEN
				IF noPetak IS NULL THEN
					RAISE tiadaNoPetak;
				END IF;
				IF (noBgnn IS NULL AND noTing IS NOT NULL) THEN
					RAISE tiadaNoBangunan;
				ELSIF (noTing IS NULL AND noBgnn IS NOT NULL) THEN
					RAISE tiadaNoTingkat;
				END IF;

				IF (upper(noBgnn) LIKE '%TIADA%' AND upper(noTing) LIKE '%TIADA%') THEN
					noBgnn := null;
					noTing := null;
				END IF;

				IF(noBgnn IS NULL AND noTing IS NULL) THEN
                    idHakmilik := idHakmilik || '/' || noPetak;
                    --	idHakmilik := idHakmilik || CASE WHEN LENGTH(noPetak) < 5 THEN lpad(noPetak, 5, '0') ELSE noPetak END;
                    jenisPetakId := getSakIdBySakKod('JNSSTRPTT'); --Petak Tanah
				ELSE
                    --					idHakmilik := idHakmilik 
                    --								|| CASE WHEN LENGTH(noBgnn) < 5 THEN lpad(noBgnn, 5, '0') ELSE noBgnn END
                    --								|| CASE WHEN LENGTH(noTing) < 5 THEN lpad(noTing, 5, '0') ELSE noTing END
                    --								|| CASE WHEN LENGTH(noPetak) < 5 THEN lpad(noPetak, 5, '0') ELSE noPetak END;
                    idHakmilik := idHakmilik || '/' || noBgnn || '/' || noTing || '/' || noPetak;
                    jenisPetakId := getSakIdBySakKod('JNSSTRPTK'); --Petak
				END IF;
			ELSE 
				RAISE tiadaJenisBorang4;
			END IF;
            
			findHakmilikEtanah(idHakmilik, hakmilikId, maklumatHakmilikId, versiDhdId, versiNo);

			IF versiNo > 0 THEN
				RAISE versiIsNotZero;
			END IF;

			IF hakmilikId IS NOT NULL THEN
				UPDATE IND_HKMLK 
                SET 
                    LAST_MODIFIED_BY = username, LAST_MODIFIED_DATE = sysdate, VERSION = 0, ID_HKMLK = idHakmilik,
					BANDAR_PEKAN_MUKIM_ID = bpmId, STRATA_INDUK_ID = strataIndukId, NO_BANGUNAN = noBgnn, NO_TINGKAT = noTing,
					NO_PTK = noPetak, JNS_HKMLK_ID = jenisHakmilikId, FLAG_TUKARGANTI = 'Y'
				WHERE HKMLK_ID = hakmilikId;

                --Feature #62541
                UPDATE IND_HKMLK_PELBAGAI 
                SET 
                    JNS_PTK_ID = jenisPetakId 
                WHERE 
                    HKMLK_PELBAGAI_ID = (SELECT HKMLK_PELBAGAI_ID FROM IND_HKMLK WHERE HKMLK_ID = hakmilikId AND HKMLK_PELBAGAI_ID IS NOT NULL);

			ELSE
				INSERT INTO IND_HKMLK ( HKMLK_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE,
										VERSION, ID_HKMLK, NO_HKMLK, BANDAR_PEKAN_MUKIM_ID, STRATA_INDUK_ID,
										NO_BANGUNAN, NO_TINGKAT, NO_PTK, JNS_HKMLK_ID, FLAG_TUKARGANTI)
					VALUES ( SEQ_HKMLK.NEXTVAL, username, SYSDATE, username, SYSDATE, 
							0, idHakmilik, noHakmilik, bpmId, strataIndukId, 
							noBgnn, noTing, noPetak, jenisHakmilikId, 'Y');
				hakmilikId := SEQ_HKMLK.CURRVAL;
			END IF;

		EXCEPTION 
			WHEN tiadaStrataInduk THEN
				errMsgBorang4 := 'IND_HKMLK B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' Tiada Strata Induk ' || idHakmilik;
				msgNotifyUser := msgNotifyUser || ' ***** Tidak dapat strata induk untuk Borang 4 ini. Sila pasti bandar pekan mukim / jenis hakmilik / no hakmilik betul. ';
				GOTO skipB4;
			WHEN tiadaNoHakmilik THEN
				errMsgBorang4 := 'IND_HKMLK B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' Tiada No. Hakmilik';
				msgNotifyUser := msgNotifyUser || ' ***** Sila isi no hakmilik untuk Borang 4 ini. ';
				GOTO skipB4;
			WHEN tiadaNoPetak THEN
				errMsgBorang4 := 'IND_HKMLK B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' Tiada No. Petak';
				msgNotifyUser := msgNotifyUser || ' ***** Sila isi no petak untuk Borang 4 ini. ';
				GOTO skipB4;
			WHEN tiadaNoTingkat THEN
				errMsgBorang4 := 'IND_HKMLK B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' Tiada No. Tingkat';
				msgNotifyUser := msgNotifyUser || ' ***** Sila isi no tingkat untuk Borang 4 ini. ';
				GOTO skipB4;
			WHEN tiadaNoBangunan THEN
				errMsgBorang4 := 'IND_HKMLK B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' Tiada No. Bangunan';
				msgNotifyUser := msgNotifyUser || ' ***** Sila isi no bangunan untuk Borang 4 ini. ';
				GOTO skipB4;
			WHEN tiadaJenisBorang4 THEN
				errMsgBorang4 := 'IND_HKMLK B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || 'Tiada jenis borang 4';
				msgNotifyUser := msgNotifyUser || ' ***** Tidak dapat jenis borang untuk Borang 4 ini. Sila rujuk migration team. ' || ':LOCCODE:' || loccode;
				GOTO skipB4;
			WHEN tiadaNoBlokSementara THEN
				errMsgBorang4 := 'IND_HKMLK B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' Tiada No. Blok Sementara';
				msgNotifyUser := msgNotifyUser || ' ***** Sila isi no blok sementara untuk Borang 4A ini. ';
				GOTO skipB4;
			WHEN versiIsNotZero THEN
				errMsgBorang4 := 'IND_HKMLK DhdVersi versi is not zero B4ASAS:' || B4ASAS.BORANG4_ASAS_ID || ' ID_HAKMILIK:'
								|| idHakmilik || ' HKMLK_ID:' || hakmilikId || ' versiDhdId:' || versiDhdId
								|| ' versiNo:' || versiNo;
				msgNotifyUser := msgNotifyUser || ' ***** Versi Borang 4 ini bukan 0. Sila rujuk migration team. ';
				GOTO skipB4;
			WHEN OTHERS THEN
				errMsgBorang4 := 'IND_HKMLK B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' ' || SQLERRM || ':LOCCODE:' || loccode; 
				msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgBorang4;
				GOTO skipB4;
		/* end IND_HKMLK */
		END;
		PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'IND_HKMLK done');

		DECLARE
			strataIndukMH IND_MKLMT_HKMLK%ROWTYPE;
			strataIndukMHId NUMBER(19,0);
			noLot ET_DMSA.BORANG4_ASAS.NO_LOT%TYPE;
			jenisPeganganId NUMBER(19,0);
			jenisTanahId NUMBER(19,0);
			seksyenId IND_SEKSYEN.SEKSYEN_ID%TYPE;
			unitNoLotId NUMBER(19,0);
            kodSyrtNyt IND_SYRT_NYATA.KOD%TYPE;

		
		BEGIN
 
			strataIndukMH := getMklmtHkmlkByStrataIndukId(strataIndukId);

            noLot := trim(strataIndukMH.NO_LOT);
			IF noLot IS NOT NULL THEN
				noLot := lpad(noLot, 7, '0');
			END IF;

			SELECT JNS_TNH_ID INTO jenisTanahId 
			FROM IND_BANDAR_PEKAN_MUKIM WHERE BANDAR_PEKAN_MUKIM_ID = bpmId;

            --changed to get no lot from strata induk 11/8
            --changed to get taraf milik id, unit lot id, seksyen id, tempoh pajakan and tarikh luput from strata induk 14/8

            IF maklumatHakmilikId IS NOT NULL THEN 
				UPDATE IND_MKLMT_HKMLK SET LAST_MODIFIED_BY = username, LAST_MODIFIED_DATE = sysdate, VERSION = 0, --FLAG_TERKINI = 'Y',
					KADAR_CUKAI = strataIndukMH.KADAR_CUKAI, NO_LOT = noLot,
					TEMPOH_PAJAKAN = strataIndukMH.TEMPOH_PAJAKAN, TRKH_LUPUT = strataIndukMH.TRKH_LUPUT, TRKH_DAFTAR = B4ASAS.TARIKH_DAFTAR_HAKMILIK_STRATA,
					UNIT_SYER = B4ASAS.UNIT_SYER_BAGI_PETAK, STATUS_HKMLK_ID = statusTanahDaftarId, UNIT_LOT_ID = strataIndukMH.UNIT_LOT_ID,
					SEKSYEN_ID = strataIndukMH.SEKSYEN_ID, UNIT_KADAR_CUKAI_ID = strataIndukMH.UNIT_KADAR_CUKAI_ID, SYRT_NYATA_ID = strataIndukMH.SYRT_NYATA_ID,
					SKTN_KPTGN_ID = strataIndukMH.SKTN_KPTGN_ID, TARAF_MILIK_ID = strataIndukMH.TARAF_MILIK_ID, 
					JNS_TNH_ID = jenisTanahId, KAT_ID = strataIndukMH.KAT_ID, LUAS = 0, UNIT_LUAS_ID = unitLuasaTiada, 
					LOKASI = strataIndukMH.LOKASI--, JENIS_PETAK_ID = jenisPetakId
				WHERE MKLMT_HKMLK_ID = maklumatHakmilikId;
			ELSE
				INSERT INTO IND_MKLMT_HKMLK( MKLMT_HKMLK_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE, 
											VERSION, /*FLAG_TERKINI,*/ KADAR_CUKAI, NO_LOT,
											TEMPOH_PAJAKAN, TRKH_LUPUT, TRKH_DAFTAR,
											UNIT_SYER, STATUS_HKMLK_ID, UNIT_LOT_ID, SEKSYEN_ID,
											UNIT_KADAR_CUKAI_ID, SYRT_NYATA_ID, SKTN_KPTGN_ID, 
											TARAF_MILIK_ID, JNS_TNH_ID, KAT_ID, LUAS, UNIT_LUAS_ID, LOKASI)--, JENIS_PETAK_ID)
					VALUES (SEQ_MKLMT_HKMLK.NEXTVAL, username, SYSDATE, username, SYSDATE,
							0, /*'Y',*/ strataIndukMH.KADAR_CUKAI, noLot, 
							strataIndukMH.TEMPOH_PAJAKAN, strataIndukMH.TRKH_LUPUT, B4ASAS.TARIKH_DAFTAR_HAKMILIK_STRATA,
							B4ASAS.UNIT_SYER_BAGI_PETAK, statusTanahDaftarId, strataIndukMH.UNIT_LOT_ID, strataIndukMH.SEKSYEN_ID,
							strataIndukMH.UNIT_KADAR_CUKAI_ID, strataIndukMH.SYRT_NYATA_ID, strataIndukMH.SKTN_KPTGN_ID,
							strataIndukMH.TARAF_MILIK_ID, jenisTanahId, strataIndukMH.KAT_ID, 0, unitLuasaTiada, strataIndukMH.LOKASI);--, jenisPetakId);
				maklumatHakmilikId := SEQ_MKLMT_HKMLK.CURRVAL;
			END IF;			

            --#60567 SYARAT NYATA BERCAMPUR PADA SKIM
            IF idHakmilikStrataInduk = '080302PN00404588' THEN
                PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'SYARAT NYATA BERCAMPUR PADA SKIM');   
                BEGIN
                    SELECT KOD_SYRT_NYT into kodSyrtNyt FROM TKR_HKMLK_STR_SYRT_NYT_BCMPR WHERE ID_HAKMILIK = idHakmilik;
            
                    IF kodSyrtNyt IS NOT NULL THEN      
                        UPDATE IND_MKLMT_HKMLK 
                        SET 
                            SYRT_NYATA_ID = (SELECT SYRT_NYATA_ID FROM IND_SYRT_NYATA WHERE KOD = kodSyrtNyt)
                        WHERE MKLMT_HKMLK_ID = maklumatHakmilikId;
                    END IF;
                EXCEPTION
                    WHEN OTHERS THEN
                        PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'Bukan syarat nyata bercampur' || ' ' || SQLERRM);
                END;
            END IF;
            --end #60567 SYARAT NYATA BERCAMPUR PADA SKIM

			PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'IND_MKLMT_HKMLK done');

		EXCEPTION
			WHEN tiadaMaklumatHakmilik THEN
				errMsgBorang4 := 'IND_MKLMT_HKMLK ERROR getMklmtHkmlkByStrataIndukId:' || strataIndukId
									|| 'B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' ' || SQLERRM; 
				msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgBorang4;
				GOTO skipB4;
			WHEN tooManyMaklumatHakmilik THEN
				errMsgBorang4 := 'IND_MKLMT_HKMLK TOO_MANY_ROWS getMklmtHkmlkByStrataIndukId:' || strataIndukId
									|| 'B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' ' || SQLERRM; 
				msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgBorang4;
				GOTO skipB4;
			WHEN OTHERS THEN
				errMsgBorang4 := 'IND_MKLMT_HKMLK B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' ' || SQLERRM; 
				msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgBorang4;
				GOTO skipB4;
		/* end IND_MKLMT_HKMLK */
		END;

		/* IND_VERSI_DHD */
		BEGIN
			IF versiDhdId IS NOT NULL THEN
				UPDATE IND_VERSI_DHD SET LAST_MODIFIED_BY = username, LAST_MODIFIED_DATE = sysdate, VERSION = 0, FLAG_AKTIF = 'Y', 
				VERSI_DHD = 0, VERSI_DHK = 0, MKLMT_HKMLK_ID = maklumatHakmilikId, HKMLK_ID = hakmilikId,
        TRKH_DHD = B4ASAS.TARIKH_DAFTAR_HAKMILIK_STRATA, TRKH_DHK = B4ASAS.TARIKH_DAFTAR_HAKMILIK_STRATA 
				WHERE VERSI_DHD_ID = versiDhdId;
			ELSE 
				INSERT INTO IND_VERSI_DHD( VERSI_DHD_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, LAST_MODIFIED_DATE, 
										VERSION, FLAG_AKTIF, VERSI_DHD, VERSI_DHK, MKLMT_HKMLK_ID, TRKH_DHD, TRKH_DHK, 
										HKMLK_ID )
					VALUES ( SEQ_VERSI_DHD.NEXTVAL, username, SYSDATE, username, SYSDATE,
							0,'Y', 0, 0, maklumatHakmilikId, B4ASAS.TARIKH_DAFTAR_HAKMILIK_STRATA, B4ASAS.TARIKH_DAFTAR_HAKMILIK_STRATA,
							hakmilikId );
				versiDhdId := SEQ_VERSI_DHD.CURRVAL;
			END IF;

			PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'IND_VERSI_DHD done');
		EXCEPTION
			WHEN OTHERS THEN
				errMsgBorang4 := 'IND_VERSI_DHD B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' ' || SQLERRM; 
				msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgBorang4;
				GOTO skipB4;
		/* end IND_VERSI_DHD */
		END;

		IF indeksVersiIndukId IS NOT NULL THEN
			DECLARE
				errMsgUpdateIndex VARCHAR2(250);
				luasPetak NUMBER(16,4);
				unitLuasPetak NUMBER(19,0);
			/* block to update BORANG2 IND_STR_IDX_TPRNC */
			BEGIN        
          IF noBgnn IS NULL AND noTing IS NULL  THEN
            SELECT BTRN_STRATA_IDX_ID INTO indeksTerperinciId FROM IND_BTRN_STRATA_IDX 
            WHERE NO_BANGUNAN IS NULL AND NO_TINGKAT IS NULL AND NO_PTK = noPetak AND IDX_AKHIR_ID = indeksVersiIndukId;
          ELSIF noTing IS NULL AND noPetak IS NULL  THEN
            SELECT BTRN_STRATA_IDX_ID INTO indeksTerperinciId FROM IND_BTRN_STRATA_IDX 
            WHERE NO_BANGUNAN = noBgnn AND NO_TINGKAT IS NULL AND NO_PTK IS NULL AND IDX_AKHIR_ID = indeksVersiIndukId;
          ELSE
            SELECT BTRN_STRATA_IDX_ID INTO indeksTerperinciId FROM IND_BTRN_STRATA_IDX 
            WHERE NO_BANGUNAN = noBgnn AND NO_TINGKAT = noTing AND NO_PTK = noPetak AND IDX_AKHIR_ID = indeksVersiIndukId;
          END IF;

          UPDATE IND_BTRN_STRATA_IDX SET HKMLK_ID = hakmilikId WHERE BTRN_STRATA_IDX_ID = indeksTerperinciId;

 --         IF noVersiIndukId = 0 THEN --avoid to update if B2 already tukarganti
          /* block to update IND_MKLMT_HKMLK FOR LUAS PETAK */
            BEGIN			
              SELECT LUAS, UNIT_LUAS_ID INTO luasPetak, unitLuasPetak FROM IND_BTRN_STRATA_IDX WHERE HKMLK_ID = hakmilikId;

              UPDATE IND_MKLMT_HKMLK SET LUAS = luasPetak, UNIT_LUAS_ID = unitLuasPetak WHERE MKLMT_HKMLK_ID = maklumatHakmilikId;
            EXCEPTION
              WHEN OTHERS THEN
                errMsgUpdateIndex := 'IND_MKLMT_HKMLK fail to get luas petak untuk HKMLK_ID ' || hakmilikId
                          || 'B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' ' || 
                          ' indeksVersiIndukId:' || indeksVersiIndukId || ' noBgnn:' || noBgnn
                          || ' noTing:' || noTing || ' noPetak:' || noPetak || ' ' || SQLERRM; 
                PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgUpdateIndex);
          /* end block to update IND_MKLMT_HKMLK FOR LUAS PETAK */
          END;
--				END IF;
			EXCEPTION
				WHEN NO_DATA_FOUND THEN
					errMsgUpdateIndex := 'IND_STR_IDX_TERPRNC indeks terperinci not found B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID 
										|| ' indeksVersiIndukId:' || indeksVersiIndukId || ' noBgnn:' || noBgnn
										|| ' noTing:' || noTing || ' noPetak:' || noPetak;
					PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgUpdateIndex);

				WHEN OTHERS THEN
					errMsgUpdateIndex := 'IND_STR_IDX_TERPRNC UPDATE error B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID 
										|| ' indeksVersiIndukId:' || indeksVersiIndukId || ' indeksTerperinciId:' || indeksTerperinciId 
										|| SQLERRM;
					PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgUpdateIndex);
			/* end block to update BORANG2 IND_STR_IDX_TERPRNC  */
			END;
		ELSE
			PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,'update IND_STR_IDX_TERPRNC with hakmilikid skipped as indeksVersiIndukId is NULL');
		END IF;

		DECLARE 
			errMsgDelete VARCHAR2(250);
			warisIds VARCHAR2(2000);
			pbIds VARCHAR2(2000);
		/* block to delete all child data*/
		BEGIN
			DECLARE
				CURSOR C_DEL_PB IS SELECT pb.PIHAK_BKPTG_ID FROM IND_PIHAK_BKPTG pb WHERE pb.VERSI_AKHIR_ID = versiDhdId  and pb.created_by = 'MIGRATOR_S';
				CURSOR C_DEL_WARIS IS SELECT k.WARIS_ID FROM IND_KUMPLN_PIHK_BKPTG k
									JOIN IND_PIHAK_BKPTG pb ON (pb.PIHAK_BKPTG_ID = k.PIHAK_BKPTG_ID)
									WHERE pb.VERSI_AKHIR_ID = versiDhdId  and pb.created_by = 'MIGRATOR_S';
				CURSOR C_CUR_APP IS SELECT ap.ID_PENGENALAN FROM UMM_APLIKASI ap
									JOIN UMM_A_HKMLK ah ON (ap.APLIKASI_ID = ah.APLIKASI_ID)
									WHERE UPPER(ah.ID_HKMLK) = UPPER(idHakmilik)  and ah.created_by = 'MIGRATOR_S';

			/* block to retrieve all similar data */
			BEGIN

				/* block to construct warisIds */
				BEGIN
					FOR W IN C_DEL_WARIS LOOP
						warisIds := warisIds || W.WARIS_ID || ',';
					END LOOP;
					warisIds := TRIM(TRAILING ',' FROM warisIds);
				EXCEPTION
					WHEN OTHERS THEN
						warisIds := NULL;
						errMsgDelete := 'Error construct warisIds B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' versiDhdId:'
										|| versiDhdId || ' ' || SQLERRM;
						PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgDelete);

						msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgDelete;
				/* end block to construct warisIds */
				END;

				/* block to construct pbIds */
				BEGIN
					FOR PB IN C_DEL_PB LOOP
						pbIds := pbIds || PB.PIHAK_BKPTG_ID || ',';
					END LOOP;
					pbIds := TRIM(TRAILING ',' FROM pbIds);
				EXCEPTION
					WHEN OTHERS THEN
						pbIds := NULL;
						errMsgDelete := 'Error construct pbIds B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' versiDhdId:'
										|| versiDhdId || ' ' || SQLERRM;
						PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgDelete);

						msgNotifyUser := msgNotifyUser || ' ***** Sila rujuk migration team - ' || errMsgDelete;
				/* end block to construct pbIds */
				END;

				/* block to construct listOfIdPengenalan */
				BEGIN
					FOR APP IN C_CUR_APP LOOP
						listOfIdPengenalan := listOfIdPengenalan || '''' || APP.ID_PENGENALAN|| '''' || ',';
					END LOOP;
					listOfIdPengenalan := TRIM(TRAILING ',' FROM listOfIdPengenalan);
				EXCEPTION
					WHEN OTHERS THEN
						listOfIdPengenalan := NULL;
						errMsgDelete := 'Error construct listOfIdPengenalan B4ASAS ID:' || B4ASAS.BORANG4_ASAS_ID || ' versiDhdId:'
										|| versiDhdId || ' ' || SQLERRM;
						PR_TKR_LOG('MIGRATE_BORANG4_BY_ID_HAKMILIK','E',arg_hakmilik_id,null,null,errMsgDelete);

						msgNotifyUser := msgNotifyUser || ' *****  Sila rujuk migration team - ' || errMsgDelete;
				/* end block to construct listOfIdPengenalan */
				END;
			/* end block to retrieve all similar data */
			END;

			/* delete DFT_A_SERAHAN_TERLIBAT */
