-- DROP PROCEDURE et_main_uat.pr_tkr_delete_hkmlk(varchar);

CREATE OR REPLACE PROCEDURE et_main_uat.pr_tkr_delete_hkmlk(IN arg_id_hkmlk character varying)
 SECURITY DEFINER
AS $procedure$
declare
	hm_hkmlk_id number(19,0);
	--arg_id_hkmlk varchar2(100);
begin
	--arg_id_hkmlk := '110440PN00012797/M1-A/7/1';
	select hkmlk_id into hm_hkmlk_id from ind_hkmlk where id_hkmlk = arg_id_hkmlk;

	delete from tkr_hakmilik_tukarganti where hkmlk_id = hm_hkmlk_id;
	delete from ind_versi_dhd where hkmlk_id = hm_hkmlk_id;
	delete from ind_strata_ptk_aksesori where hkmlk_id = hm_hkmlk_id;
	delete from ind_pelan where hkmlk_id = hm_hkmlk_id;
	delete from ind_hkmlk where hkmlk_id = hm_hkmlk_id;

end
$procedure$
 LANGUAGE edbspl
;

