CREATE OR REPLACE PROCEDURE et_main_uat.pr_tkr_log(IN refname character varying, IN loglevel character varying, IN v_ref2 character varying, IN v_ref3 character varying, IN v_ref4 character varying, IN v_message character varying)
 SECURITY DEFINER
