-- DROP PROCEDURE et_main_uat.pr_tmp_dc_live(int4);

CREATE OR REPLACE PROCEDURE et_main_uat.pr_tmp_dc_live(IN param integer)
 SECURITY DEFINER
AS $procedure$ 
BEGIN
  -- remove existing catatan
    if param = 0 or param = 1 then  
        update ind_hkmlk_pelbagai t
        set maklumat_tambahan = null

        where hkmlk_pelbagai_id in
        (
        select hkmlk_pelbagai_id from ind_hkmlk where id_hkmlk in (select id_hkmlk from tkr_tmp_dc_live)
        ); 
    end if;
  -- update with latest catatan
  if param = 1 or param = 2 then 
  for rec in (select distinct d.id_hkmlk,h.hkmlk_id,d.isu_no,h.hkmlk_pelbagai_id, c.keterangan from tkr_dc_kod c, tkr_tmp_dc_live d, ind_hkmlk h, ind_hkmlk_pelbagai p where c.id = d.isu_no and d.id_hkmlk = h.id_hkmlk and h.hkmlk_pelbagai_id = p.hkmlk_pelbagai_id
) loop

        update ind_hkmlk_pelbagai t
        set maklumat_tambahan = 
        '{"pembetulanList":[' ||
        ( case when maklumat_tambahan is null then
            '{"catatan":"' || rec.keterangan ||'","status":"N","kod":' || rec.isu_no || '}'
          else
            replace(replace(maklumat_tambahan,'{"pembetulanList":[',''),']}','') || ',{"catatan":"' || rec.keterangan ||'","status":"N","kod":' || rec.isu_no || '}'
          end
        ) 
        || ']}'

        where hkmlk_pelbagai_id = rec.hkmlk_pelbagai_id;

  end loop;
  end if;
END PR_TMP_DC_LIVE$procedure$
 LANGUAGE edbspl
;

-- DROP PROCEDURE et_main_uat.pr_tmp_fix_aplikasi_dmsa_pp(varchar);

CREATE OR REPLACE PROCEDURE et_main_uat.pr_tmp_fix_aplikasi_dmsa_pp(IN arg_hakmilik_id character varying)
 SECURITY DEFINER
AS $procedure$	
	loccode varchar2(100) := '';

	cntAplikasi number(19,0);

	aplikasiIdForPb number(19,0);
	
	cursor sub is 
			select * from (
		select 
			pb.aplikasi_id pb_aplikasi_id,
			pb.pihak_bkptg_id pb_pihak_bkptg_id,
			ap.created_date,
			ur.ursn_id,
			ap.trkh_serahan,
			ap.pejabat_id,
			dh.versi_dhd_id,
			ap.aplikasi_id ap_aplikasi_id,
			ap.id_pengenalan ap_id_pengenalan, 
			hm.hkmlk_id hm_hkmlk_id ,hm.id_hkmlk hm_id_hkmlk, hs.id_hkmlk hs_id_hkmlk, hs.hkmlk_id hs_hkmlk_id,
			ps.id_pengenalan ps_id_pengenalan, us.kod , substr(ap.id_pengenalan,1,4),right(ps.id_pengenalan,5),
			substr(ap.id_pengenalan,1,2) || 'SC' || right(ps.id_pengenalan,5) new_id_pengenalan 
			from 
			et_main.ind_hkmlk hm , et_main.ind_versi_dhd dh , et_main.ind_pihak_bkptg pb , et_main.umm_aplikasi ap , et_main.ind_ursn ur,
			et_main.ind_hkmlk hs , et_main.ind_versi_dhd ds , et_main.ind_rekod_ursn rs , et_main.umm_aplikasi  ps , et_main.ind_ursn us
			where 
			hm.strata_induk_id is not null and dh.hkmlk_id = hm.hkmlk_id and dh.versi_dhd_id = pb.versi_akhir_id 
			and ap.aplikasi_id = pb.aplikasi_id
			and ap.ursn_id = ur.ursn_id and ur.kod='PP'
			and hm.strata_induk_id = hs.hkmlk_id and ds.hkmlk_id = hs.hkmlk_id and ds.versi_dhd_id = rs.versi_akhir_id (+) 
			and rs.aplikasi_id = ps.aplikasi_id(+) and ps.ursn_id = us.ursn_id(+)	
			and (us.kod IN  ('HTB')   ) and ap.id_pengenalan like '%SC/%') where ap_id_pengenalan <> new_id_pengenalan
			
			;
		
BEGIN
	for rec in sub loop

		aplikasiIdForPb := null;

		-- check if aplikasi exist
		select aplikasi_id into aplikasiIdForPb from (
		select aplikasi_id from et_main.umm_aplikasi where id_pengenalan = rec.new_id_pengenalan
		union
		select null from dual ) limit 1
		;
			if aplikasiIdForPb is null then
				INSERT INTO UMM_APLIKASI(APLIKASI_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, 
				LAST_MODIFIED_DATE,VERSION, FLAG_PERTANYAAN, TRKH_TAMAT, STATUS_KEPUTUSAN, STATUS_PROSES,
				PEJABAT_ID, ID_PENGENALAN, NO_FOLIO, NO_JILID, TRKH_SERAHAN,URSN_ID, NO_RUJUKAN_FAIL)
				VALUES(
				SEQ_APLIKASI.NEXTVAL, 'MIGRATOR_S_PP', sysdate, 'MIGRATOR_S_PP', sysdate,
				0, 'N', rec.trkh_serahan, 'Daftar', 'Tamat',
				rec.pejabat_id, rec.new_id_pengenalan, null, null, rec.trkh_serahan,
				rec.ursn_id, null) RETURNING APLIKASI_ID INTO aplikasiIdForPb;

				dbms_output('Created Aplikasi ' || aplikasiIdForPb || ' for ' || rec.new_id_pengenalan);
				
			end if;

			-- add into new umm_a_hkmlk
			if aplikasiIdForPb is not null then

				--update et_main.ind_pihak_bkptg set aplikasi_id = aplikasiIdForPb where pihak_bkptg_id = rec.pb_pihak_bkptg_id;
			
				-- update et_main.umm_a_hkmlk set aplikasi_id = aplikasiIdForPb where aplikasi_id = rec.ap_aplikasi_id AND id_hkmlk = rec.hm_id_hkmlk;
				
			end if;

	
	end loop;
END
$procedure$
 LANGUAGE edbspl
;

-- DROP PROCEDURE et_main_uat.pr_tmp_fix_aplikasi_dmsa_pp();

CREATE OR REPLACE PROCEDURE et_main_uat.pr_tmp_fix_aplikasi_dmsa_pp()
 SECURITY DEFINER
AS $procedure$	
	loccode varchar2(100) := '';

	cntAplikasi number(19,0);

	aplikasiIdForPb number(19,0);
	
	cursor sub is 
			select * from (
		select 
			pb.aplikasi_id pb_aplikasi_id,
			pb.pihak_bkptg_id pb_pihak_bkptg_id,
			ap.created_date,
			ur.ursn_id,
			ap.trkh_serahan,
			ap.pejabat_id,
			dh.versi_dhd_id,
			ap.aplikasi_id ap_aplikasi_id,
			ap.id_pengenalan ap_id_pengenalan, 
			hm.hkmlk_id hm_hkmlk_id ,hm.id_hkmlk hm_id_hkmlk, hs.id_hkmlk hs_id_hkmlk, hs.hkmlk_id hs_hkmlk_id,
			ps.id_pengenalan ps_id_pengenalan, us.kod , substr(ap.id_pengenalan,1,4),right(ps.id_pengenalan,5),
			substr(ap.id_pengenalan,1,2) || 'SC' || right(ps.id_pengenalan,5) new_id_pengenalan 
			from 
			et_main.ind_hkmlk hm , et_main.ind_versi_dhd dh , et_main.ind_pihak_bkptg pb , et_main.umm_aplikasi ap , et_main.ind_ursn ur,
			et_main.ind_hkmlk hs , et_main.ind_versi_dhd ds , et_main.ind_rekod_ursn rs , et_main.umm_aplikasi  ps , et_main.ind_ursn us
			where 
			hm.strata_induk_id is not null and dh.hkmlk_id = hm.hkmlk_id and dh.versi_dhd_id = pb.versi_akhir_id 
			and ap.aplikasi_id = pb.aplikasi_id
			and ap.ursn_id = ur.ursn_id and ur.kod='PP'
			and hm.strata_induk_id = hs.hkmlk_id and ds.hkmlk_id = hs.hkmlk_id and ds.versi_dhd_id = rs.versi_akhir_id (+) 
			and rs.aplikasi_id = ps.aplikasi_id(+) and ps.ursn_id = us.ursn_id(+)	
			and (us.kod IN  ('HTB')   ) and ap.id_pengenalan like '%SC/%') where ap_id_pengenalan <> new_id_pengenalan
			
			;
		
BEGIN
	for rec in sub loop

		aplikasiIdForPb := null;

		-- check if aplikasi exist
		select aplikasi_id into aplikasiIdForPb from (
		select aplikasi_id from et_main.umm_aplikasi where id_pengenalan = rec.new_id_pengenalan
		union
		select null from dual ) limit 1
		;
			if aplikasiIdForPb is null then
				INSERT INTO UMM_APLIKASI(APLIKASI_ID, CREATED_BY, CREATED_DATE, LAST_MODIFIED_BY, 
				LAST_MODIFIED_DATE,VERSION, FLAG_PERTANYAAN, TRKH_TAMAT, STATUS_KEPUTUSAN, STATUS_PROSES,
				PEJABAT_ID, ID_PENGENALAN, NO_FOLIO, NO_JILID, TRKH_SERAHAN,URSN_ID, NO_RUJUKAN_FAIL)
				VALUES(
				SEQ_APLIKASI.NEXTVAL, 'MIGRATOR_S_PP', sysdate, 'MIGRATOR_S_PP', sysdate,
				0, 'N', rec.trkh_serahan, 'Daftar', 'Tamat',
				rec.pejabat_id, rec.new_id_pengenalan, null, null, rec.trkh_serahan,
				rec.ursn_id, null) RETURNING APLIKASI_ID INTO aplikasiIdForPb;

				dbms_output.put_line('Created Aplikasi ' || aplikasiIdForPb || ' for ' || rec.new_id_pengenalan);
				
			end if;

			-- add into new umm_a_hkmlk
			if aplikasiIdForPb is not null then

				update et_main.ind_pihak_bkptg set aplikasi_id = aplikasiIdForPb 
				where pihak_bkptg_id = rec.pb_pihak_bkptg_id;

				dbms_output.put_line('Update ind_pihak_bkptg  |' || aplikasiIdForPb || ' for ' || rec.pb_pihak_bkptg_id);

			
				 update et_main.umm_a_hkmlk set aplikasi_id = aplikasiIdForPb 
				 where aplikasi_id = rec.ap_aplikasi_id AND id_hkmlk = rec.hm_id_hkmlk;

				 dbms_output.put_line('Update umm_a_hkmlk  |' || aplikasiIdForPb || ' for ' || rec.hm_id_hkmlk);

				
			end if;

	
	end loop;
END
$procedure$
 LANGUAGE edbspl
;

-- DROP PROCEDURE et_main_uat.pr_trk_notify_update(varchar, varchar, varchar);

CREATE OR REPLACE PROCEDURE et_main_uat.pr_trk_notify_update(IN p_id_hkmlk character varying, IN p_ulasan character varying, IN p_jenis_fail character varying)
 SECURITY DEFINER
AS $procedure$
  /*Variables*/
  v_id_hkmlk varchar2(100);
  v_hkmlk_id number;
  v_tugasan_tukarganti_id number;
  v_tugasan_sm_id number;
  v_hakmilik_tukarganti_id number;
  v_hakmilik_tukarganti_checker varchar2(200);
  v_status varchar2(20);
  v_kod_tugasan varchar2(20);
  v_flag_agihan_kumpulan varchar2(2);

  n_buku_hakmilik_id number;
  n_hakmilik_tukarganti_id number;

  n_status varchar2(20);

  /* constants and variables */
  createdBy         CONSTANT VARCHAR2(100)  := 'MIGRATOR_DELTA';
  migrationTime     CONSTANT TIMESTAMP(6)  := sysdate;
  destination       CONSTANT VARCHAR2(100) := 'et_main_mig';
  errMsgUpdateIndex VARCHAR2(250);
BEGIN

    select
        ht. hakmilik_tukarganti_id, ht. buku_hakmilik_id , ht.status
            into
        n_hakmilik_tukarganti_id, n_buku_hakmilik_id ,n_status
    from tkr_hakmilik_tukarganti ht, tkr_buku_hakmilik bh
    where ht.buku_hakmilik_id = bh.buku_hakmilik_id
    and bh.jenis_fail = p_jenis_fail and ht.hkmlk_id = (select hkmlk_id from ind_hkmlk where id_hkmlk=p_id_hkmlk);

   -- Reassign pengguna based on latest setting from pengurusan JOPA
   IF (n_status = 'STRK') then
       UPDATE TKR_HAKMILIK_TUKARGANTI
        SET
            (PEMBANTU_TADBIR, PENDAFTAR)
             =
             (SELECT pembantu_tadbir,pendaftar from tkr_buku_hakmilik where buku_hakmilik_id = n_buku_hakmilik_id)
       where hakmilik_tukarganti_id = n_hakmilik_tukarganti_id;
    end if;

  SELECT ih.HKMLK_ID,
    ih.ID_HKMLK,
    tht.HAKMILIK_TUKARGANTI_ID,
    MAX(ttt.tugasan_tukarganti_id),
    tht.CHECKER
  INTO v_hkmlk_id,
    v_id_hkmlk,
    v_hakmilik_tukarganti_id,
    v_tugasan_tukarganti_id,
    v_hakmilik_tukarganti_checker
  FROM IND_HKMLK ih,
    TKR_HAKMILIK_TUKARGANTI tht,
    (SELECT * FROM TKR_TUGASAN_TUKARGANTI
    WHERE KOD_TUGASAN NOT IN ('CBH1','CBH2') AND NAMA_PENGGUNA <> 'MIGRATOR_DELTA') ttt
  WHERE ih.HKMLK_ID              = tht.HKMLK_ID
  AND tht.HAKMILIK_TUKARGANTI_ID = ttt.HAKMILIK_TUKARGANTI_ID(+)
  AND ih.ID_HKMLK             = p_id_hkmlk
  AND tht.BUKU_HAKMILIK_ID     IN
    (SELECT BUKU_HAKMILIK_ID FROM TKR_BUKU_HAKMILIK WHERE JENIS_FAIL = p_jenis_fail)
  GROUP BY ih.HKMLK_ID,
    ih.ID_HKMLK,
    tht.HAKMILIK_TUKARGANTI_ID, tht.CHECKER;
  --DBMS_OUTPUT.PUT_LINE('Proses delta ID hakmilik: ' || p_id_hkmlk);

  --Update TRKH_DATA = current system date, ADALAH_PERUBAHAN_DATA=Y (if the status value is not null) , Status Hakmik=SDSC, Status =SM (if the value is not null) in TKR_HAKMILIK_TUKARGANTI  for the hakmilik
  UPDATE TKR_HAKMILIK_TUKARGANTI
  SET ADALAH_PERUBAHAN_DATA = DECODE(STATUS,NULL,ADALAH_PERUBAHAN_DATA,'Y'),
    STATUS                  = DECODE(STATUS,NULL,NULL,'SM'),
    TRKH_DATA               = SYSDATE,
    STATUS_HAKMILIK         = 'SDSC',
    PRIORITY                = 5,
    LAST_MODIFIED_BY		    = createdBy,
    LAST_MODIFIED_DATE		  = sysdate,
    FLAG_SKIP_PT            = 'N',
    BILANGAN_MIGRASI        = DECODE(STATUS,'STRK',BILANGAN_MIGRASI+1,BILANGAN_MIGRASI)
  WHERE HKMLK_ID            = v_hkmlk_id
  AND BUKU_HAKMILIK_ID     IN
    (SELECT BUKU_HAKMILIK_ID FROM TKR_BUKU_HAKMILIK WHERE JENIS_FAIL = p_jenis_fail);
  ----DBMS_OUTPUT.PUT_LINE('Number of record(s) updated in TKR_HAKMILIK_TUKARGANTI : ' || SQL%ROWCOUNT);

  --if there is any record tugasan in TKR_TUGASAN_TUKARGANTI for the hakmilik
  IF v_tugasan_tukarganti_id IS NOT NULL THEN
    ----DBMS_OUTPUT.PUT_LINE('Tugasan tugarkanti ID : ' || v_tugasan_tukarganti_id);
    --check the status of LAST tugasan (TKR_TUGASAN_TUKARGANTI.Status)
    SELECT DECODE(STATUS,NULL,'J',STATUS),
      kod_tugasan, ADALAH_AGIHAN_KUMPULAN
    INTO v_status,
      v_kod_tugasan, v_flag_agihan_kumpulan
    FROM TKR_TUGASAN_TUKARGANTI
    WHERE tugasan_tukarganti_id = v_tugasan_tukarganti_id;
    ----DBMS_OUTPUT.PUT_LINE('Last Status : ' || V_STATUS||' Last Kod Tugasan : '||V_kod_tugasan);


    --check tugasan_tukarganti_id where kod tugasan = SM and exclude delta SM
    SELECT MAX(tugasan_tukarganti_id)
    INTO v_tugasan_sm_id
    FROM TKR_TUGASAN_TUKARGANTI
    WHERE HAKMILIK_TUKARGANTI_ID = v_hakmilik_tukarganti_id
    AND kod_tugasan              ='SM'
    AND NAMA_PENGGUNA <> 'MIGRATOR_DELTA'; --avoid kes SM, dummy tugsana SM with bigger id
    ----DBMS_OUTPUT.PUT_LINE('Tugasan_Tugarkanti_ID where Kod_Tugasan is SM : ' || v_tugasan_sm_id);

    --If not selesai and tugasan not in (SM,BTLH) then
    IF v_status != 'S' AND v_kod_tugasan NOT IN ('SM','BTLH') THEN
      ----DBMS_OUTPUT.PUT_LINE('Tugasan tugarkanti ID : ' || v_tugasan_tukarganti_id);

      --Update status =P in TKR_TUGASAN_TUKARGANTI and TRKH_TAMAT to current system date
      UPDATE TKR_TUGASAN_TUKARGANTI
      SET STATUS                   = 'P',
          TRKH_TAMAT               = sysdate,
          LAST_MODIFIED_BY		     = createdBy,
          LAST_MODIFIED_DATE		   = sysdate
      WHERE tugasan_tukarganti_id  = v_tugasan_tukarganti_id;
      ----DBMS_OUTPUT.PUT_LINE('Number of record(s) updated Status to P and trkh_tamat to sysdate: ' || SQL%ROWCOUNT);

      --Add new rekod into TKR_TUGASAN_TUKARGANTI (tugasan=SM and pengguna= previous last pengguna with tugasan SM, tarikh terima =sysdate)
      --for dummy tugasan with ulasan
      INSERT
      INTO TKR_TUGASAN_TUKARGANTI
        (
          TUGASAN_TUKARGANTI_ID,
          CREATED_BY,
          CREATED_DATE,
          LAST_MODIFIED_BY,
          LAST_MODIFIED_DATE,
          VERSION,
          ADALAH_AGIHAN_KUMPULAN,
          ADALAH_LENGKAP,
          CATATAN_1,
          CATATAN_2,
          CATATAN_3,
          KOD_TUGASAN,
          NAMA_PENGGUNA,
          TRKH_TAMAT,
          TRKH_TERIMA,
          BUKU_HAKMILIK_ID,
          HAKMILIK_TUKARGANTI_ID,
          CATATAN_4,
          CATATAN_5,
          ADALAH_CETAK_DHDK,
          ULASAN,
          TUGASAN_TUKARGANTI_SEBELUM_ID,
          STATUS,
          STATUS_KIV,
          TRKH_SEMAKAN,
          JNS_MSLH
        )
      SELECT SEQ_TUGASAN_TUKARGANTI.NEXTVAL,
        createdBy CREATED_BY,
        sysdate CREATED_DATE,
        createdBy LAST_MODIFIED_BY,
        sysdate LAST_MODIFIED_DATE,
        0 VERSION,
        'Y' ADALAH_AGIHAN_KUMPULAN,
        NULL ADALAH_LENGKAP,
        NULL CATATAN_1,
        NULL CATATAN_2,
        p_ulasan CATATAN_3, --ulasan for delta
        KOD_TUGASAN,
        createdBy NAMA_PENGGUNA, --user as delta
        SYSDATE TRKH_TAMAT,
        SYSDATE TRKH_TERIMA,
        BUKU_HAKMILIK_ID,
        HAKMILIK_TUKARGANTI_ID,
        NULL CATATAN_4,
        NULL CATATAN_5,
        ADALAH_CETAK_DHDK,
        NULL ULASAN,
        NULL TUGASAN_TUKARGANTI_SEBELUM_ID,
        'S' STATUS, --selesai
        STATUS_KIV,
        SYSDATE TRKH_SEMAKAN,
        JNS_MSLH
      FROM TKR_TUGASAN_TUKARGANTI
      WHERE TUGASAN_TUKARGANTI_ID = v_tugasan_sm_id;

      INSERT
      INTO TKR_TUGASAN_TUKARGANTI
        (
          TUGASAN_TUKARGANTI_ID,
          CREATED_BY,
          CREATED_DATE,
          LAST_MODIFIED_BY,
          LAST_MODIFIED_DATE,
          VERSION,
          ADALAH_AGIHAN_KUMPULAN,
          ADALAH_LENGKAP,
          CATATAN_1,
          CATATAN_2,
          CATATAN_3,
          KOD_TUGASAN,
          NAMA_PENGGUNA,
          TRKH_TAMAT,
          TRKH_TERIMA,
          BUKU_HAKMILIK_ID,
          HAKMILIK_TUKARGANTI_ID,
          CATATAN_4,
          CATATAN_5,
          ADALAH_CETAK_DHDK,
          ULASAN,
          TUGASAN_TUKARGANTI_SEBELUM_ID,
          STATUS,
          STATUS_KIV,
          TRKH_SEMAKAN,
          JNS_MSLH
        )
      SELECT SEQ_TUGASAN_TUKARGANTI.NEXTVAL,
        createdBy CREATED_BY,
        sysdate CREATED_DATE,
        createdBy LAST_MODIFIED_BY,
        sysdate LAST_MODIFIED_DATE,
        0 VERSION,
        'Y' ADALAH_AGIHAN_KUMPULAN,
        NULL ADALAH_LENGKAP,
        NULL CATATAN_1,
        NULL CATATAN_2,
        NULL CATATAN_3,
        KOD_TUGASAN,
        v_hakmilik_tukarganti_checker NAMA_PENGGUNA,
        NULL TRKH_TAMAT,
        SYSDATE TRKH_TERIMA,
        BUKU_HAKMILIK_ID,
        HAKMILIK_TUKARGANTI_ID,
        NULL CATATAN_4,
        NULL CATATAN_5,
        ADALAH_CETAK_DHDK,
        NULL ULASAN,
        NULL TUGASAN_TUKARGANTI_SEBELUM_ID,
        'J' STATUS, --Jalan
        STATUS_KIV,
        NULL TRKH_SEMAKAN,
        NULL JNS_MSLH
      FROM TKR_TUGASAN_TUKARGANTI
      WHERE TUGASAN_TUKARGANTI_ID = v_tugasan_sm_id;
      ----DBMS_OUTPUT.PUT_LINE('Number of row inserted ' || SQL%ROWCOUNT);
      --DBMS_OUTPUT.PUT_LINE('Proses delta id hakmilik berjaya.');


    ELSIf V_STATUS != 'S' AND V_kod_tugasan = 'SM' THEN --If not selesai and tugasan = (SM) then
      ----DBMS_OUTPUT.PUT_LINE('Tugasan tugarkanti ID for Status NOT Selesai with kod tugasan SM : ' || v_tugasan_tukarganti_id);

      --for dummy tugasan with ulasan
      INSERT
      INTO TKR_TUGASAN_TUKARGANTI
        (
          TUGASAN_TUKARGANTI_ID,
          CREATED_BY,
          CREATED_DATE,
          LAST_MODIFIED_BY,
          LAST_MODIFIED_DATE,
          VERSION,
          ADALAH_AGIHAN_KUMPULAN,
          ADALAH_LENGKAP,
          CATATAN_1,
          CATATAN_2,
          CATATAN_3,
          KOD_TUGASAN,
          NAMA_PENGGUNA,
          TRKH_TAMAT,
          TRKH_TERIMA,
          BUKU_HAKMILIK_ID,
          HAKMILIK_TUKARGANTI_ID,
          CATATAN_4,
          CATATAN_5,
          ADALAH_CETAK_DHDK,
          ULASAN,
          TUGASAN_TUKARGANTI_SEBELUM_ID,
          STATUS,
          STATUS_KIV,
          TRKH_SEMAKAN,
          JNS_MSLH
        )
      SELECT SEQ_TUGASAN_TUKARGANTI.NEXTVAL,
        createdBy CREATED_BY,
        sysdate CREATED_DATE,
        createdBy LAST_MODIFIED_BY,
        sysdate LAST_MODIFIED_DATE,
        0 VERSION,
        'Y' ADALAH_AGIHAN_KUMPULAN,
        NULL ADALAH_LENGKAP,
        NULL CATATAN_1,
        NULL CATATAN_2,
        p_ulasan CATATAN_3, --ulasan for delta
        KOD_TUGASAN,
        createdBy NAMA_PENGGUNA, --user as delta
        SYSDATE TRKH_TAMAT,
        SYSDATE TRKH_TERIMA,
        BUKU_HAKMILIK_ID,
        HAKMILIK_TUKARGANTI_ID,
        NULL CATATAN_4,
        NULL CATATAN_5,
        ADALAH_CETAK_DHDK,
        NULL ULASAN,
        NULL TUGASAN_TUKARGANTI_SEBELUM_ID,
        'S' STATUS, --selesai
        STATUS_KIV,
        SYSDATE TRKH_SEMAKAN,
        JNS_MSLH
      FROM TKR_TUGASAN_TUKARGANTI
      WHERE TUGASAN_TUKARGANTI_ID = v_tugasan_sm_id;

      --Update ADALAH_LENGKAP to null in TKR_TUGASAN_TUKARGANTI
      UPDATE TKR_TUGASAN_TUKARGANTI
      SET ADALAH_LENGKAP        = NULL,
          LAST_MODIFIED_BY		  = createdBy,
          LAST_MODIFIED_DATE	  = sysdate
      WHERE TUGASAN_TUKARGANTI_ID = v_tugasan_tukarganti_id;
      ----DBMS_OUTPUT.PUT_LINE('Number of record(s) set adalah lengkap to NULL' ||' : '|| SQL%ROWCOUNT);
      --DBMS_OUTPUT.PUT_LINE('Proses delta id hakmilik berjaya.');


    ELSIf V_STATUS = 'S' THEN --If selesai
      ----DBMS_OUTPUT.PUT_LINE('Tugasan tugarkanti ID for Status Selesai : ' || v_tugasan_tukarganti_id);
      --Add new rekod into TKR_TUGASAN_TUKARGANTI (tugasan=SM and pengguna= previous last pengguna with tugasan SM, tarikh terima =sysdate)
      --for dummy tugasan with ulasan
      INSERT INTO TKR_TUGASAN_TUKARGANTI
        (
          TUGASAN_TUKARGANTI_ID,
          CREATED_BY,
          CREATED_DATE,
          LAST_MODIFIED_BY,
          LAST_MODIFIED_DATE,
          VERSION,
          ADALAH_AGIHAN_KUMPULAN,
          ADALAH_LENGKAP,
          CATATAN_1,
          CATATAN_2,
          CATATAN_3,
          KOD_TUGASAN,
          NAMA_PENGGUNA,
          TRKH_TAMAT,
          TRKH_TERIMA,
          BUKU_HAKMILIK_ID,
          HAKMILIK_TUKARGANTI_ID,
          CATATAN_4,
          CATATAN_5,
          ADALAH_CETAK_DHDK,
          ULASAN,
          TUGASAN_TUKARGANTI_SEBELUM_ID,
          STATUS,
          STATUS_KIV,
          TRKH_SEMAKAN,
          JNS_MSLH
        )
      SELECT SEQ_TUGASAN_TUKARGANTI.NEXTVAL,
        createdBy CREATED_BY,
        sysdate CREATED_DATE,
        createdBy LAST_MODIFIED_BY,
        sysdate LAST_MODIFIED_DATE,
        0 VERSION,
        'Y' ADALAH_AGIHAN_KUMPULAN,
        NULL ADALAH_LENGKAP,
        NULL CATATAN_1,
        NULL CATATAN_2,
        p_ulasan CATATAN_3, --ulasan for delta
        KOD_TUGASAN,
        createdBy NAMA_PENGGUNA, --user as delta
        SYSDATE TRKH_TAMAT,
        SYSDATE TRKH_TERIMA,
        BUKU_HAKMILIK_ID,
        HAKMILIK_TUKARGANTI_ID,
        NULL CATATAN_4,
        NULL CATATAN_5,
        NULL ADALAH_CETAK_DHDK,
        NULL ULASAN,
        NULL TUGASAN_TUKARGANTI_SEBELUM_ID,
        'S' STATUS, -- Selesai
        STATUS_KIV,
        SYSDATE TRKH_SEMAKAN,
        JNS_MSLH
      FROM TKR_TUGASAN_TUKARGANTI
      WHERE TUGASAN_TUKARGANTI_ID = v_tugasan_sm_id;

      --for current tugasan
      INSERT INTO TKR_TUGASAN_TUKARGANTI
        (
          TUGASAN_TUKARGANTI_ID,
          CREATED_BY,
          CREATED_DATE,
          LAST_MODIFIED_BY,
          LAST_MODIFIED_DATE,
          VERSION,
          ADALAH_AGIHAN_KUMPULAN,
          ADALAH_LENGKAP,
          CATATAN_1,
          CATATAN_2,
          CATATAN_3,
          KOD_TUGASAN,
          NAMA_PENGGUNA,
          TRKH_TAMAT,
          TRKH_TERIMA,
          BUKU_HAKMILIK_ID,
          HAKMILIK_TUKARGANTI_ID,
          CATATAN_4,
          CATATAN_5,
          ADALAH_CETAK_DHDK,
          ULASAN,
          TUGASAN_TUKARGANTI_SEBELUM_ID,
          STATUS,
          STATUS_KIV,
          TRKH_SEMAKAN,
          JNS_MSLH
        )
      SELECT SEQ_TUGASAN_TUKARGANTI.NEXTVAL,
        createdBy CREATED_BY,
        sysdate CREATED_DATE,
        createdBy LAST_MODIFIED_BY,
        sysdate LAST_MODIFIED_DATE,
        0 VERSION,
        'Y' ADALAH_AGIHAN_KUMPULAN,
        NULL ADALAH_LENGKAP,
        NULL CATATAN_1,
        NULL CATATAN_2,
        NULL CATATAN_3,
        KOD_TUGASAN,
        v_hakmilik_tukarganti_checker NAMA_PENGGUNA,
        NULL TRKH_TAMAT,
        SYSDATE TRKH_TERIMA,
        BUKU_HAKMILIK_ID,
        HAKMILIK_TUKARGANTI_ID,
        NULL CATATAN_4,
        NULL CATATAN_5,
        NULL ADALAH_CETAK_DHDK,
        NULL ULASAN,
        NULL TUGASAN_TUKARGANTI_SEBELUM_ID,
        'J' STATUS,
        STATUS_KIV,
        NULL TRKH_SEMAKAN,
        NULL JNS_MSLH
      FROM TKR_TUGASAN_TUKARGANTI
      WHERE TUGASAN_TUKARGANTI_ID = v_tugasan_sm_id;
      ----DBMS_OUTPUT.PUT_LINE('Number of row inserted ' || SQL%ROWCOUNT);
      --DBMS_OUTPUT.PUT_LINE('Proses delta id hakmilik berjaya.');
    ELSE
      NULL; --DO NOTHING
    END IF;
  END IF;
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    NULL;
    --DBMS_OUTPUT.PUT_LINE('Proses delta id hakmilik gagal. NO_DATA_FOUND ERROR FOR ID_HAKMILIK : '||p_id_hkmlk );
  WHEN TOO_MANY_ROWS THEN
    NULL;
    --DBMS_OUTPUT.PUT_LINE('Proses delta id hakmilik gagal. TOO_MANY_ROWS ERROR FOR ID_HAKMILIK : '||p_id_hkmlk);
  WHEN OTHERS THEN
    NULL;
    --DBMS_OUTPUT.PUT_LINE('Proses delta id hakmilik gagal. Exception Error : '|| SQLERRM);
END$procedure$
 LANGUAGE edbspl
;

-- DROP PROCEDURE et_main_uat.proc_insert_missing_tgsn_pejabat(varchar);

CREATE OR REPLACE PROCEDURE et_main_uat.proc_insert_missing_tgsn_pejabat(IN p_kod_ursn character varying)
 SECURITY INVOKER
AS $procedure$
DECLARE
  rows_affected INTEGER;
BEGIN
 INSERT INTO IND_PEJABAT_TGSN
          SELECT SEQ_PEJABAT_TGSN.NEXTVAL PEJABAT_TGSN_ID,
          'INSERT_PROC' CREATED_BY,
          sysdate CREATED_DATE,
          'INSERT_PROC' LAST_MODIFIED_BY,
          sysdate LAST_MODIFIED_DATE,
          0 VERSION,
          (SELECT PEJABAT_URSN_id FROM IND_PEJABAT_URSN pu 
          WHERE pu.ursn_id = t.ursn_id and pu.pejabat_id =p.pejabat_id ) PEJABAT_URSN_ID,
          TGSN_ID,
          0 MINIT_KPI,
          NULL KOMPONEN_BISNES_ID,
          NULL JNS_PEJABAT_BERTGS_ID,
          NULL  
     FROM IND_TGSN t, IND_PEJABAT p
          WHERE TGSN_ID IN (
          SELECT TGSN_ID FROM IND_TGSN
          WHERE URSN_ID = (SELECT URSN_ID FROM IND_URSN WHERE KOD = p_kod_ursn)
          MINUS
          SELECT TGSN_ID FROM IND_PEJABAT_TGSN)
          AND p.created_by ='MIGRATOR_L';
         
     GET DIAGNOSTICS rows_affected = ROW_COUNT;
  	 RAISE NOTICE '% record inserted', rows_affected;
END;
$procedure$
 LANGUAGE plpgsql
;

-- DROP PROCEDURE et_main_uat.proc_insert_tgsn_pejabat(varchar, varchar);

CREATE OR REPLACE PROCEDURE et_main_uat.proc_insert_tgsn_pejabat(IN p_kod_pejabat_as_source character varying, IN p_kod_ursn character varying)
 SECURITY INVOKER
AS $procedure$
DECLARE
  v_count number;
  v_count_tgsn_pejabat_source number;
  pejabatUrsnId number(19,0);
  kod_pejabat_dest_rec record;
BEGIN

  FOR kod_pejabat_dest_rec IN
  ( 
    SELECT PEJABAT_ID, NAMA FROM IND_PEJABAT WHERE KOD <> p_kod_pejabat_as_source
  ) 
  LOOP
  
    RAISE NOTICE 'Start creating master data for pejabat %', kod_pejabat_dest_rec.nama;  
  
    --ind_pejabat_ursn
    SELECT count(*) into v_count FROM IND_PEJABAT_URSN
    WHERE PEJABAT_ID = kod_pejabat_dest_rec.pejabat_id 
    AND URSN_ID = (SELECT URSN_ID FROM IND_URSN WHERE KOD = p_kod_ursn);
  
    IF v_count > 0 THEN
      RAISE NOTICE 'No action: IND_PEJABAT_URSN DATA FOUND for pejabat %', kod_pejabat_dest_rec.nama;    
    ELSE
      INSERT INTO IND_PEJABAT_URSN
       SELECT SEQ_PEJABAT_URSN.NEXTVAL PEJABAT_URSN_ID,
          'INSERT_PROC' CREATED_BY,
          sysdate CREATED_DATE,
          'INSERT_PROC' LAST_MODIFIED_BY,
          sysdate LAST_MODIFIED_DATE,
          0 VERSION,
          kod_pejabat_dest_rec.pejabat_id PEJABAT_ID,
          (select ursn_id from ind_ursn where kod = p_kod_ursn) URSN_ID,
          NAMA_KOMPOSIT_BPM,
          NAMA_SERVIS_BPM,
          MINIT_KPI, 
          FLOWABLE_PROCESS_DEF_KEY,
          FLAG_FLOWABLE
        FROM IND_PEJABAT_URSN
        WHERE PEJABAT_ID = (SELECT PEJABAT_ID FROM IND_PEJABAT WHERE KOD = p_kod_pejabat_as_source) 
        AND URSN_ID = (SELECT URSN_ID FROM IND_URSN WHERE KOD = p_kod_ursn);
    END IF;
  
    --ind_pejabat_tgsn
    SELECT PEJABAT_URSN_ID into pejabatUrsnId FROM IND_PEJABAT_URSN
    WHERE PEJABAT_ID = kod_pejabat_dest_rec.pejabat_id 
    AND URSN_ID = (SELECT URSN_ID FROM IND_URSN WHERE KOD = p_kod_ursn);
    
    SELECT count(*) into v_count FROM IND_PEJABAT_TGSN
    WHERE PEJABAT_URSN_ID = pejabatUrsnId;

    SELECT count(*) into v_count_tgsn_pejabat_source FROM IND_PEJABAT_TGSN
    WHERE PEJABAT_URSN_ID = (
        SELECT PEJABAT_URSN_ID
        FROM IND_PEJABAT_URSN
        WHERE PEJABAT_ID = (SELECT PEJABAT_ID FROM IND_PEJABAT WHERE KOD = p_kod_pejabat_as_source) 
        AND URSN_ID = (SELECT URSN_ID FROM IND_URSN WHERE KOD = p_kod_ursn)
    );
  
    IF v_count > 0 THEN
      IF v_count != v_count_tgsn_pejabat_source THEN --copy extra/new tugasan from source pejabat into all other pejabat
        INSERT INTO IND_PEJABAT_TGSN
          SELECT SEQ_PEJABAT_TGSN.NEXTVAL PEJABAT_TGSN_ID,
          'INSERT_PROC' CREATED_BY,
          sysdate CREATED_DATE,
          'INSERT_PROC' LAST_MODIFIED_BY,
          sysdate LAST_MODIFIED_DATE,
          0 VERSION,
          pejabatUrsnId PEJABAT_URSN_ID,
          TGSN_ID,
          MINIT_KPI,
          KOMPONEN_BISNES_ID,
          JNS_PEJABAT_BERTGS_ID,
          NULL
          FROM IND_PEJABAT_TGSN
          WHERE PEJABAT_URSN_ID = (SELECT PEJABAT_URSN_ID FROM IND_PEJABAT_URSN WHERE
          PEJABAT_ID = (SELECT PEJABAT_ID FROM IND_PEJABAT WHERE KOD = p_kod_pejabat_as_source) AND 
          URSN_ID = (SELECT URSN_ID FROM IND_URSN WHERE KOD = p_kod_ursn))
          AND TGSN_ID NOT IN (
            SELECT TGSN_ID
            FROM IND_PEJABAT_TGSN
            WHERE PEJABAT_URSN_ID = (SELECT PEJABAT_URSN_ID FROM IND_PEJABAT_URSN WHERE
            PEJABAT_ID = kod_pejabat_dest_rec.pejabat_id  AND 
            URSN_ID = (SELECT URSN_ID FROM IND_URSN WHERE KOD = p_kod_ursn))
          );
        RAISE NOTICE 'Extra tugasan inserted for pejabat %', kod_pejabat_dest_rec.nama;
      ELSE 
        RAISE NOTICE 'No Action: IND_PEJABAT_TGSN DATA FOUND for pejabat %', kod_pejabat_dest_rec.nama;    
      END IF;
    ELSE
      INSERT INTO IND_PEJABAT_TGSN
       SELECT SEQ_PEJABAT_TGSN.NEXTVAL PEJABAT_TGSN_ID,
          'INSERT_PROC' CREATED_BY,
          sysdate CREATED_DATE,
          'INSERT_PROC' LAST_MODIFIED_BY,
          sysdate LAST_MODIFIED_DATE,
          0 VERSION,
          pejabatUrsnId PEJABAT_URSN_ID,
          TGSN_ID,
          MINIT_KPI,
          KOMPONEN_BISNES_ID,
          JNS_PEJABAT_BERTGS_ID,
          NULL
        FROM IND_PEJABAT_TGSN
        WHERE PEJABAT_URSN_ID = (SELECT PEJABAT_URSN_ID FROM IND_PEJABAT_URSN WHERE
        PEJABAT_ID = (SELECT PEJABAT_ID FROM IND_PEJABAT WHERE KOD = p_kod_pejabat_as_source) AND 
        URSN_ID = (SELECT URSN_ID FROM IND_URSN WHERE KOD = p_kod_ursn));
        
      RAISE NOTICE 'All tugasan inserted for pejabat %', kod_pejabat_dest_rec.nama;
    END IF;
    
    RAISE NOTICE  'End creating master data for pejabat %', kod_pejabat_dest_rec.nama;  
    RAISE NOTICE  ' ';
  
  END LOOP;
  
EXCEPTION
  WHEN OTHERS THEN
    RAISE NOTICE 'ERROR: %', SQLERRM;
END ;
$procedure$
 LANGUAGE plpgsql
;

-- DROP FUNCTION et_main_uat.rat_to_real(et_main_uat.rational_type);

CREATE OR REPLACE FUNCTION et_main_uat.rat_to_real(input_rat rational_type)
 RETURNS real
 LANGUAGE plpgsql
AS $function$
BEGIN
    RETURN input_rat.numerator::REAL / input_rat.denominator::REAL;
END;
$function$
;

-- DROP FUNCTION et_main_uat.rational_type_normalize(inout et_main_uat.rational_type);

CREATE OR REPLACE FUNCTION et_main_uat.rational_type_normalize(INOUT rt rational_type)
 RETURNS rational_type
 LANGUAGE plpgsql
AS $function$
DECLARE
  divisor INTEGER := gcd(rt.numerator, rt.denominator);
BEGIN
  -- the normalize procedure simplifies a fraction.
  -- for example, 6/8 = 3/4
  rt.numerator := rt.numerator / divisor;
  rt.denominator := rt.denominator / divisor;
END;
$function$
;

-- DROP FUNCTION et_main_uat.rational_type_rat_to_real(et_main_uat.rational_type);

CREATE OR REPLACE FUNCTION et_main_uat.rational_type_rat_to_real(rt rational_type)
 RETURNS real
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- the rat-to-real function converts a rational number to a real number.
  -- for example, 6/8 = 0.75
  RETURN rt.numerator::REAL / rt.denominator;
END;
$function$
;

