-- DROP FUNCTION et_main_uat.shufflenochar(varchar);

CREATE OR REPLACE FUNCTION et_main_uat.shufflenochar(no_kp character varying)
 RETURNS character varying
 LANGUAGE plpgsql
AS $function$
DECLARE
    result_str VARCHAR(4000) := '';
    current_char CHAR(1);
    current_num INT;
BEGIN
    FOR i IN 1..LENGTH(no_kp) LOOP
        current_char := SUBSTRING(no_kp FROM i FOR 1);

        IF current_char ~  '[0-9]' THEN
            current_num := CAST(current_char AS INT);
            -- increase by 2 and modulo 10
            current_num := (current_num + 2) % 10;
            result_str := result_str || current_num::VARCHAR;
        ELSE
            -- if not a digit, append the character as is
            result_str := result_str || current_char;
        END IF;
    END LOOP;

    RETURN result_str;

    EXCEPTION
        WHEN OTHERS THEN
            RETURN no_kp;
END;
$function$
;

-- DROP PROCEDURE et_main_uat.sp_populate_rpt_hls15_init();

CREATE OR REPLACE PROCEDURE et_main_uat.sp_populate_rpt_hls15_init()
 SECURITY INVOKER
AS $procedure$
DECLARE
    rec RECORD;
BEGIN

    for crdt_year in 2019..2026 loop 

            INSERT INTO rpt_hsl15_fakta (
            kod_usia, kod_jt, tahun_pa, tarikh, tahun_bil, sh_kod, mh_trkh_batal, seq, seq_jt, 
            perihal, nama_jt, id_hkmlk, nama_pembayar, pj_hm, ct, tct, dd, td, ta, tta, jumlah, kelebihan, 
            kekurangan, remitan_tunggakan, grn_ct, grn_tct, grn_dd, grn_td, grn_ta, grn_tta, grn_ttl, 
            gm_ct, gm_tct, gm_dd, gm_td, gm_ta, gm_tta, gm_ttl, pn_ct, pn_tct, pn_dd, pn_td, pn_ta, pn_tta, pn_ttl, 
            pm_ct, pm_tct, pm_dd, pm_td, pm_ta, pm_tta, pm_ttl, hsd_ct, hsd_tct, hsd_dd, hsd_td, hsd_ta, hsd_tta, hsd_ttl, 
            hsm_ct, hsm_tct, hsm_dd, hsm_td, hsm_ta, hsm_tta, hsm_ttl
        )
        SELECT
        RT.KOD_USIA as KOD_USIA,
        RT.KOD_JT as KOD_JT, 
        TT.tahun_pa ,
        TT.TARIKH,
        AC.tahun_bil ,
        AC.SH_KOD ,
        AC.MH_TRKH_BATAL,
        RT.SEQ::INTEGER AS SEQ,
        RT.SEQ_JT::INTEGER AS SEQ_JT,
        RT.PERIHAL AS PERIHAL,
        RT.NAMA_JT AS NAMA_JT,
        AC.ID_HKMLK AS ID_HKMLK,
        AC.NAMA_PEMBAYAR AS NAMA_PEMBAYAR,
        AC.PJ_HM AS PJ_HM, 
        CASE WHEN AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.CT, 0 ) ELSE 0 END AS CT,
        CASE WHEN AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TCT, 0 ) ELSE 0 END AS TCT,
        CASE WHEN AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.DD, 0 ) ELSE 0 END AS DD,
        CASE WHEN AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TD, 0 ) ELSE 0 END AS TD,
        CASE WHEN AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TA, 0 ) ELSE 0 END AS TA,
        CASE WHEN AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TTA, 0 ) ELSE 0 END AS TTA,
        CASE WHEN AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.JUMLAH, 0 ) ELSE 0 END AS JUMLAH,
        CASE WHEN ( AC.STATUS_BYRN_BIL = 'SBB_KREDIT' OR ( AC.STATUS_BYRN_BIL = 'SBB_JELAS' AND TT.JUMLAH <0 )) AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.JUMLAH, 0 ) ELSE 0 END AS KELEBIHAN,
        CASE WHEN AC.STATUS_BYRN_BIL = 'SBB_BK' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.JUMLAH, 0 ) ELSE 0 END AS KEKURANGAN,
        CASE WHEN AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( AC.REMITAN_TUNGGAKAN, 0 ) ELSE 0 END AS REMITAN_TUNGGAKAN,
        CASE WHEN AC.JNS_HM = 'GRN' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.CT, 0 ) ELSE 0 END AS GRN_CT,
        CASE WHEN AC.JNS_HM = 'GRN' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TCT, 0 ) ELSE 0 END AS GRN_TCT,
        CASE WHEN AC.JNS_HM = 'GRN' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.DD, 0 ) ELSE 0 END AS GRN_DD,
        CASE WHEN AC.JNS_HM = 'GRN' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TD, 0 ) ELSE 0 END AS GRN_TD,
        CASE WHEN AC.JNS_HM = 'GRN' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TA, 0 ) ELSE 0 END AS GRN_TA,
        CASE WHEN AC.JNS_HM = 'GRN' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TTA, 0 ) ELSE 0 END AS GRN_TTA,
        CASE WHEN AC.JNS_HM = 'GRN' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.JUMLAH, 0 ) ELSE 0 END AS GRN_TTL,
        CASE WHEN AC.JNS_HM = 'GM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.CT, 0 ) ELSE 0 END AS GM_CT,
        CASE WHEN AC.JNS_HM = 'GM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TCT, 0 ) ELSE 0 END AS GM_TCT,
        CASE WHEN AC.JNS_HM = 'GM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.DD, 0 ) ELSE 0 END AS GM_DD,
        CASE WHEN AC.JNS_HM = 'GM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TD, 0 ) ELSE 0 END AS GM_TD,
        CASE WHEN AC.JNS_HM = 'GM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TA, 0 ) ELSE 0 END AS GM_TA,
        CASE WHEN AC.JNS_HM = 'GM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TTA, 0 ) ELSE 0 END AS GM_TTA,
        CASE WHEN AC.JNS_HM = 'GM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.JUMLAH, 0 ) ELSE 0 END AS GM_TTL,
        CASE WHEN AC.JNS_HM = 'PN' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.CT, 0 ) ELSE 0 END AS PN_CT,
        CASE WHEN AC.JNS_HM = 'PN' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TCT, 0 ) ELSE 0 END AS PN_TCT,
        CASE WHEN AC.JNS_HM = 'PN' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.DD, 0 ) ELSE 0 END AS PN_DD,
        CASE WHEN AC.JNS_HM = 'PN' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TD, 0 ) ELSE 0 END AS PN_TD,
        CASE WHEN AC.JNS_HM = 'PN' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TA, 0 ) ELSE 0 END AS PN_TA,
        CASE WHEN AC.JNS_HM = 'PN' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TTA, 0 ) ELSE 0 END AS PN_TTA,
        CASE WHEN AC.JNS_HM = 'PN' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.JUMLAH, 0 ) ELSE 0 END AS PN_TTL,
        CASE WHEN AC.JNS_HM = 'PM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.CT, 0 ) ELSE 0 END AS PM_CT,
        CASE WHEN AC.JNS_HM = 'PM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TCT, 0 ) ELSE 0 END AS PM_TCT,
        CASE WHEN AC.JNS_HM = 'PM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.DD, 0 ) ELSE 0 END AS PM_DD,
        CASE WHEN AC.JNS_HM = 'PM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TD, 0 ) ELSE 0 END AS PM_TD,
        CASE WHEN AC.JNS_HM = 'PM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TA, 0 ) ELSE 0 END AS PM_TA,
        CASE WHEN AC.JNS_HM = 'PM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TTA, 0 ) ELSE 0 END AS PM_TTA,
        CASE WHEN AC.JNS_HM = 'PM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.JUMLAH, 0 ) ELSE 0 END AS PM_TTL,
        CASE WHEN AC.JNS_HM = 'HSD' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.CT, 0 ) ELSE 0 END AS HSD_CT,
        CASE WHEN AC.JNS_HM = 'HSD' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TCT, 0 ) ELSE 0 END AS HSD_TCT,
        CASE WHEN AC.JNS_HM = 'HSD' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.DD, 0 ) ELSE 0 END AS HSD_DD,
        CASE WHEN AC.JNS_HM = 'HSD' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TD, 0 ) ELSE 0 END AS HSD_TD,
        CASE WHEN AC.JNS_HM = 'HSD' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TA, 0 ) ELSE 0 END AS HSD_TA,
        CASE WHEN AC.JNS_HM = 'HSD' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TTA, 0 ) ELSE 0 END AS HSD_TTA,
        CASE WHEN AC.JNS_HM = 'HSD' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.JUMLAH, 0 ) ELSE 0 END AS HSD_TTL,
        CASE WHEN AC.JNS_HM = 'HSM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.CT, 0 ) ELSE 0 END AS HSM_CT,
        CASE WHEN AC.JNS_HM = 'HSM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TCT, 0 ) ELSE 0 END AS HSM_TCT,
        CASE WHEN AC.JNS_HM = 'HSM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.DD, 0 ) ELSE 0 END AS HSM_DD,
        CASE WHEN AC.JNS_HM = 'HSM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TD, 0 ) ELSE 0 END AS HSM_TD,
        CASE WHEN AC.JNS_HM = 'HSM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TA, 0 ) ELSE 0 END AS HSM_TA,
        CASE WHEN AC.JNS_HM = 'HSM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TTA, 0 ) ELSE 0 END AS HSM_TTA,
        CASE WHEN AC.JNS_HM = 'HSM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.JUMLAH, 0 ) ELSE 0 END AS HSM_TTL
        FROM MV_AKAUN_CUKAI_DTL_1 AC
        JOIN MV_PENYATA_AKAUN_SUMMARY_1 TT ON TT.NO_AKAUN = AC.NO_AKAUN
        JOIN MV_SAK_DTL RT ON RT.SEQ = AC.KOD_TT
        WHERE AC.tahun_bil = crdt_year
          and TT.tahun_pa = crdt_year;

        commit;    

    end loop;    

END;
$procedure$
 LANGUAGE plpgsql
;

-- DROP PROCEDURE et_main_uat.sp_populate_rpt_hls15_init2();

CREATE OR REPLACE PROCEDURE et_main_uat.sp_populate_rpt_hls15_init2()
 SECURITY INVOKER
AS $procedure$
DECLARE
    rec RECORD;
BEGIN

    for crdt_year in 2019..2026 loop 

            INSERT INTO rpt_hsl15_fakta (
            kod_usia, kod_jt, tahun_pa, tarikh, tahun_bil, sh_kod, mh_trkh_batal, seq, seq_jt, 
            perihal, nama_jt, id_hkmlk, nama_pembayar, pj_hm, ct, tct, dd, td, ta, tta, jumlah, kelebihan, 
            kekurangan, remitan_tunggakan, grn_ct, grn_tct, grn_dd, grn_td, grn_ta, grn_tta, grn_ttl, 
            gm_ct, gm_tct, gm_dd, gm_td, gm_ta, gm_tta, gm_ttl, pn_ct, pn_tct, pn_dd, pn_td, pn_ta, pn_tta, pn_ttl, 
            pm_ct, pm_tct, pm_dd, pm_td, pm_ta, pm_tta, pm_ttl, hsd_ct, hsd_tct, hsd_dd, hsd_td, hsd_ta, hsd_tta, hsd_ttl, 
            hsm_ct, hsm_tct, hsm_dd, hsm_td, hsm_ta, hsm_tta, hsm_ttl
        )
        SELECT
        RT.KOD_USIA as KOD_USIA,
        RT.KOD_JT as KOD_JT, 
        TT.tahun_pa ,
        TT.TARIKH,
        AC.tahun_bil ,
        AC.SH_KOD ,
        AC.MH_TRKH_BATAL,
        RT.SEQ::INTEGER AS SEQ,
        RT.SEQ_JT::INTEGER AS SEQ_JT,
        RT.PERIHAL AS PERIHAL,
        RT.NAMA_JT AS NAMA_JT,
        AC.ID_HKMLK AS ID_HKMLK,
        AC.NAMA_PEMBAYAR AS NAMA_PEMBAYAR,
        AC.PJ_HM AS PJ_HM, 
        CASE WHEN AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.CT, 0 ) ELSE 0 END AS CT,
        CASE WHEN AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TCT, 0 ) ELSE 0 END AS TCT,
        CASE WHEN AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.DD, 0 ) ELSE 0 END AS DD,
        CASE WHEN AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TD, 0 ) ELSE 0 END AS TD,
        CASE WHEN AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TA, 0 ) ELSE 0 END AS TA,
        CASE WHEN AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TTA, 0 ) ELSE 0 END AS TTA,
        CASE WHEN AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.JUMLAH, 0 ) ELSE 0 END AS JUMLAH,
        CASE WHEN ( AC.STATUS_BYRN_BIL = 'SBB_KREDIT' OR ( AC.STATUS_BYRN_BIL = 'SBB_JELAS' AND TT.JUMLAH <0 )) AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.JUMLAH, 0 ) ELSE 0 END AS KELEBIHAN,
        CASE WHEN AC.STATUS_BYRN_BIL = 'SBB_BK' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.JUMLAH, 0 ) ELSE 0 END AS KEKURANGAN,
        CASE WHEN AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( AC.REMITAN_TUNGGAKAN, 0 ) ELSE 0 END AS REMITAN_TUNGGAKAN,
        CASE WHEN AC.JNS_HM = 'GRN' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.CT, 0 ) ELSE 0 END AS GRN_CT,
        CASE WHEN AC.JNS_HM = 'GRN' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TCT, 0 ) ELSE 0 END AS GRN_TCT,
        CASE WHEN AC.JNS_HM = 'GRN' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.DD, 0 ) ELSE 0 END AS GRN_DD,
        CASE WHEN AC.JNS_HM = 'GRN' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TD, 0 ) ELSE 0 END AS GRN_TD,
        CASE WHEN AC.JNS_HM = 'GRN' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TA, 0 ) ELSE 0 END AS GRN_TA,
        CASE WHEN AC.JNS_HM = 'GRN' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TTA, 0 ) ELSE 0 END AS GRN_TTA,
        CASE WHEN AC.JNS_HM = 'GRN' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.JUMLAH, 0 ) ELSE 0 END AS GRN_TTL,
        CASE WHEN AC.JNS_HM = 'GM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.CT, 0 ) ELSE 0 END AS GM_CT,
        CASE WHEN AC.JNS_HM = 'GM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TCT, 0 ) ELSE 0 END AS GM_TCT,
        CASE WHEN AC.JNS_HM = 'GM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.DD, 0 ) ELSE 0 END AS GM_DD,
        CASE WHEN AC.JNS_HM = 'GM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TD, 0 ) ELSE 0 END AS GM_TD,
        CASE WHEN AC.JNS_HM = 'GM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TA, 0 ) ELSE 0 END AS GM_TA,
        CASE WHEN AC.JNS_HM = 'GM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TTA, 0 ) ELSE 0 END AS GM_TTA,
        CASE WHEN AC.JNS_HM = 'GM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.JUMLAH, 0 ) ELSE 0 END AS GM_TTL,
        CASE WHEN AC.JNS_HM = 'PN' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.CT, 0 ) ELSE 0 END AS PN_CT,
        CASE WHEN AC.JNS_HM = 'PN' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TCT, 0 ) ELSE 0 END AS PN_TCT,
        CASE WHEN AC.JNS_HM = 'PN' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.DD, 0 ) ELSE 0 END AS PN_DD,
        CASE WHEN AC.JNS_HM = 'PN' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TD, 0 ) ELSE 0 END AS PN_TD,
        CASE WHEN AC.JNS_HM = 'PN' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TA, 0 ) ELSE 0 END AS PN_TA,
        CASE WHEN AC.JNS_HM = 'PN' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TTA, 0 ) ELSE 0 END AS PN_TTA,
        CASE WHEN AC.JNS_HM = 'PN' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.JUMLAH, 0 ) ELSE 0 END AS PN_TTL,
        CASE WHEN AC.JNS_HM = 'PM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.CT, 0 ) ELSE 0 END AS PM_CT,
        CASE WHEN AC.JNS_HM = 'PM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TCT, 0 ) ELSE 0 END AS PM_TCT,
        CASE WHEN AC.JNS_HM = 'PM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.DD, 0 ) ELSE 0 END AS PM_DD,
        CASE WHEN AC.JNS_HM = 'PM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TD, 0 ) ELSE 0 END AS PM_TD,
        CASE WHEN AC.JNS_HM = 'PM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TA, 0 ) ELSE 0 END AS PM_TA,
        CASE WHEN AC.JNS_HM = 'PM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TTA, 0 ) ELSE 0 END AS PM_TTA,
        CASE WHEN AC.JNS_HM = 'PM' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.JUMLAH, 0 ) ELSE 0 END AS PM_TTL,
        CASE WHEN AC.JNS_HM = 'HSD' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.CT, 0 ) ELSE 0 END AS HSD_CT,
        CASE WHEN AC.JNS_HM = 'HSD' AND AC.STATUS_BYRN_BIL NOT IN ( 'SBB_KERAJAAN','SBB_CTTPJ' ) THEN COALESCE ( TT.TCT, 0 ) ELSE 0 END AS HSD_TCT,
