-- DROP FUNCTION et_main_uat.squirrel_get_error_offset(varchar);

CREATE OR REPLACE FUNCTION et_main_uat.squirrel_get_error_offset(query_text character varying)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
    l_status INTEGER;
BEGIN
    BEGIN
        -- Execute the query dynamically
        EXECUTE query_text;
    EXCEPTION
        WHEN OTHERS THEN
            -- Use RAISE EXCEPTION to capture error position
            RAISE EXCEPTION 'Error occurred at position %', pg_exception_detail();
    END;

    -- Return -1 if no exception occurs
    RETURN -1;
END;
$function$
;

-- DROP FUNCTION et_main_uat.susun_sekatan(varchar, varchar);

CREATE OR REPLACE FUNCTION et_main_uat.susun_sekatan(in_kod character varying, in_caw character varying)
 RETURNS character varying
 LANGUAGE edbspl
 SECURITY DEFINER
AS $function$
    xkod    varchar2(10)     :=  (in_kod);
    xcaw    varchar2(2)      :=  (in_caw);
    perihal varchar2(3000);
begin
select  (select  perihal from et_main.sptb_kod_sekatan where to_number(baris) = '1' and kod = xkod and pej = xcaw)||chr(10)||' '||
