-- DROP FUNCTION et_main_uat.total_dashboard_penyampaian_notis_by_pengguna(text, numeric, text, text);

CREATE OR REPLACE FUNCTION et_main_uat.total_dashboard_penyampaian_notis_by_pengguna(var_nama_pengguna text DEFAULT NULL::text, var_pejabat_id numeric DEFAULT NULL::numeric, var_filter_colum text DEFAULT NULL::text, var_filter_val text DEFAULT NULL::text)
 RETURNS TABLE(total bigint)
 LANGUAGE plpgsql
AS $function$
BEGIN
  RETURN QUERY

with MAIN_Q as (SELECT 
    DHAS_1.TGSN_SEMASA_ID::BIGINT AS ID,
    HNTR_1.ID_PENGHANTARAN AS PENGHANTARAN_ID,
    DHAS_1.TGSN_PERIHAL AS TUGASAN_PERIHAL,
    DHAS_1.NAMA_PENGGUNA AS NAMA_PENGGUNA,
    DHAS_1.TRKH_PNRMAN AS TRKH_PNRMAN,
    DHAS_1.TRKH_KPI AS TRKH_KPI,
    APP_TGSN_1.TRKH_MULA AS TARIKH_MULA,
    APP_TGSN_1.TRKH_TETAP AS TARIKH_TAMAT,
    APP_TGSN_1.TEMPOH_KPI AS TEMPOH_PERINGATAN_KPI,
    
    CASE 
        WHEN HNTR_1.ID_PENGHANTARAN LIKE 'PNL%' 
             AND SP_1.KOD = 'JENIS_PENYAMPAIAN_T'
             THEN APP_1.MKLMT_TMBHN::jsonb ->> 'idPengenalanInduk'
        ELSE APP_1.ID_PENGENALAN
    END AS ID_PERMOHONAN,
    
    ALMT_1.NAMA_PNRM AS NAMA_PENERIMA,
    
    TRIM(
	    COALESCE(ALMT_1.ALAMAT,'') || ' ' ||
	    COALESCE(ALMT_1.ALAMAT2,'') || ' ' ||
	    COALESCE(ALMT_1.ALAMAT3,'') || ' ' ||
	    COALESCE(ALMT_1.ALAMAT4,'') || ' ' ||
	    COALESCE(ALMT_1.POSKOD,'') || ' ' ||
	    CASE WHEN MDL_1.KOD='BANDAR_LAIN' THEN MAX(ALMT_1.BANDAR_LAIN) ELSE MAX(MDL_1.NAMA) END || ' ' ||
	    MAX(NEGERI.NAMA)
	) AS ALAMAT_PENERIMA,
	
	TRIM(
	    COALESCE(PEJABAT.ALAMAT,'') || ' ' ||
	    COALESCE(PEJABAT.ALAMAT2,'') || ' ' ||
	    COALESCE(PEJABAT.ALAMAT3,'') || ' ' ||
	    COALESCE(PEJABAT.ALAMAT4,'') || ' ' ||
	    COALESCE(PEJABAT.POSKOD,'') || ' ' ||
	    CASE WHEN MDL_1.KOD='BANDAR_LAIN' THEN PEJABAT.BANDAR_LAIN ELSE MDL_1.NAMA END || ' ' ||
	    NEGERI.NAMA
	) AS ALAMAT_PEJABAT_PENERIMA,
	ALMT_1.jns_alamat AS JENIS_ALAMAT,
	CASE 
        WHEN DHAS_1.NAMA_PENGGUNA IS NULL OR DHAS_1.NAMA_PENGGUNA = var_nama_pengguna THEN 1
        ELSE 0
    END AS SHOW_LINK,
    CASE 
        WHEN DHAS_1.PERANAN = '-PN-' THEN 1
        ELSE 0
    END AS ENABLE_AGIH,
	HNTR_1.FLAG_SEGERA AS SEGERA_FLAG,
	CASE WHEN DHAS_1.TGSN_PERIHAL LIKE '%Pembetulan%' THEN 1 ELSE 0 END AS PEMBETULAN_FLAG,
    CASE 
	    WHEN SP_1.KOD = 'JENIS_PENYAMPAIAN_T' THEN 1
	    ELSE 0
	END AS TAMPAL_FLAG,
	COALESCE(MDL_1.NAMA, '-') AS MODUL_NAME,
	ARRAY_AGG(
    CASE 
        WHEN ALMT_1.jns_alamat = 'TH'
            THEN 'Di atas tanah ' || COALESCE(ALMT_1.alamat,'')
        WHEN ALMT_1.jns_alamat = 'PT'
            THEN 'Di papan kenyataan ' || COALESCE(ALMT_1.nama_pnrm,'')
        WHEN ALMT_1.jns_alamat = 'PP'
            THEN 'Di papan kenyataan Pejabat Penghulu'
        WHEN ALMT_1.jns_alamat = 'TA'
            THEN 'Di papan kenyataan Tempat Awam'
        ELSE '-'
    END
) AS LOKASI_TAMPAL_LIST

	
FROM UMM_TGSN_SEMASA DHAS_1
LEFT JOIN UMM_A_TGSN APP_TGSN_1 
    ON DHAS_1.A_TGSN_ID = APP_TGSN_1.A_TGSN_ID
LEFT JOIN UMM_APLIKASI APP_1 
    ON DHAS_1.APLIKASI_ID = APP_1.APLIKASI_ID
LEFT JOIN UMM_HANTARAN_NOTIS HNTR_1 
    ON DHAS_1.HANTARAN_NOTIS_ID = HNTR_1.HANTARAN_NOTIS_ID
LEFT JOIN IND_MODUL MDL_1 
    ON HNTR_1.UNIT_ID = MDL_1.MODUL_ID
LEFT JOIN UMM_BTRN_HANTARAN_NOTIS BHNTR_1
    ON HNTR_1.HANTARAN_NOTIS_ID = BHNTR_1.HANTARAN_NOTIS_ID
LEFT JOIN RJK_SENARAI_AHLI_KUMPULAN SP_1
    ON BHNTR_1.jns_penyampaian_id = SP_1.senarai_ahli_kumpulan_id
LEFT JOIN UMM_ALAMAT_PNRM_NOTIS ALMT_1
    ON BHNTR_1.alamat_pnrm_notis_id = ALMT_1.alamat_pnrm_notis_id
LEFT JOIN RJK_SENARAI_AHLI_KUMPULAN NEGERI
    ON ALMT_1.NEGERI_ID = NEGERI.SENARAI_AHLI_KUMPULAN_ID
LEFT JOIN IND_PEJABAT PEJABAT
    ON ALMT_1.PEJABAT_ID = PEJABAT.PEJABAT_ID
WHERE DHAS_1.HANTARAN_NOTIS_ID IS NOT NULL
AND (DHAS_1.NAMA_PENGGUNA = var_nama_pengguna OR DHAS_1.NAMA_PENGGUNA IS NULL)
AND (var_pejabat_id IS NULL OR DHAS_1.PEJABAT_ID = var_pejabat_id)
AND DHAS_1.PERANAN LIKE '%-PN-%'
GROUP BY 
    DHAS_1.TGSN_SEMASA_ID,
    HNTR_1.ID_PENGHANTARAN,
    DHAS_1.TGSN_PERIHAL,
    DHAS_1.NAMA_PENGGUNA,
    DHAS_1.TRKH_PNRMAN,
    DHAS_1.TRKH_KPI,
    APP_TGSN_1.TRKH_MULA,
    APP_TGSN_1.TRKH_TETAP,
    APP_TGSN_1.TEMPOH_KPI,
    APP_1.ID_PENGENALAN,
    APP_1.MKLMT_TMBHN,
    ALMT_1.NAMA_PNRM,
    ALMT_1.ALAMAT,
    ALMT_1.ALAMAT2,
    ALMT_1.ALAMAT3,
    ALMT_1.ALAMAT4,
    ALMT_1.POSKOD,
    ALMT_1.jns_alamat,
    PEJABAT.ALAMAT,
    PEJABAT.ALAMAT2,
    PEJABAT.ALAMAT3,
    PEJABAT.ALAMAT4,
    PEJABAT.POSKOD,
    PEJABAT.BANDAR_LAIN,
    MDL_1.KOD,
    MDL_1.NAMA,
    NEGERI.NAMA,
    DHAS_1.PERANAN,
    HNTR_1.FLAG_SEGERA,
    SP_1.KOD
  
),

FINAL_QUE AS (
select
    Q_.ID,
    Q_.PENGHANTARAN_ID::TEXT as PENGHANTARAN_ID,
    Q_.TUGASAN_PERIHAL::TEXT as TUGASAN_PERIHAL,
    Q_.NAMA_PENGGUNA::TEXT as NAMA_PENGGUNA,
    Q_.TRKH_PNRMAN as TRKH_PNRMAN,
    Q_.TRKH_KPI as TRKH_KPI,
 	Q_.TARIKH_MULA,
 	Q_.TARIKH_TAMAT,
	Q_.ID_PERMOHONAN::TEXT as ID_PERMOHONAN,
	Q_.NAMA_PENERIMA :: TEXT as NAMA_PENERIMA, 
	Q_.ALAMAT_PENERIMA::TEXT AS ALAMAT_PENERIMA,
	Q_.SHOW_LINK::number as SHOW_LINK,
	Q_.TAMPAL_FLAG::number as TAMPAL_FLAG,
	Q_.MODUL_NAME::TEXT as MODUL_NAME,
	Q_.LOKASI_TAMPAL_LIST as LOKASI_TAMPAL_LIST,

	split_part(Q_.NAMA_PENGGUNA, '@', 1) AS DISPLAY_NAMA_PENGGUNA,
split_part(Q_.NAMA_PENGGUNA, '@', 1) || E'\n' || Q_.ALAMAT_PENERIMA AS MAKLUMAT_PENERIMA ,
--COALESCE(Q_.TRKH_KPI, CURRENT_DATE) AS TARIKH_SUSUNAN,
CASE
            WHEN Q_.TRKH_KPI IS NULL THEN 'Hijau'
            ELSE
                CASE
                    WHEN Q_.TARIKH_TAMAT IS NULL THEN
                        CASE
                            WHEN Q_.TEMPOH_PERINGATAN_KPI IS NOT NULL THEN
                                CASE
                                    WHEN Q_.TRKH_KPI > Q_.TARIKH_MULA + (Q_.TEMPOH_PERINGATAN_KPI || ' minutes')::interval
                                         AND NOW() >= Q_.TARIKH_MULA + (Q_.TEMPOH_PERINGATAN_KPI || ' minutes')::interval
                                         AND NOW() < Q_.TRKH_KPI
                                         THEN 'Kuning'
                                    WHEN NOW() > Q_.TRKH_KPI THEN 'Merah'
                                    WHEN NOW() < Q_.TRKH_KPI THEN 'Hijau'
                                    ELSE 'Merah'
                                END
                            ELSE
                                CASE
                                    WHEN NOW() < Q_.TRKH_KPI THEN 'Hijau'
                                    ELSE 'Merah'
                                END
                        END
                    ELSE
                        CASE
                            WHEN Q_.TRKH_KPI < Q_.TARIKH_TAMAT THEN 'Hijau'
                            ELSE 'Merah'
                        END
                END
       END AS FLAG
--
--CASE 
--	WHEN Q_.TRKH_KPI IS NOT NULL THEN
--            'Notis Penting hantar sebelum ' || TO_CHAR(Q_.TRKH_KPI, 'DD/MM/YYYY')
--        ELSE 'Sila tentukan tarikh aktiviti'
--    END AS SEGERA_TOOLTIP
from MAIN_Q Q_



)

SELECT COUNT(*) FROM FINAL_QUE

WHERE
  (var_filter_colum IS NULL OR var_filter_val IS NULL OR (
  (var_filter_colum = 'MODUL_NAME' AND MODUL_NAME ILIKE '%' || var_filter_val || '%') or 
(var_filter_colum = 'PENGHANTARAN_ID' AND PENGHANTARAN_ID ILIKE '%' || var_filter_val || '%') or
(var_filter_colum = 'ID_PERMOHONAN' AND ID_PERMOHONAN ILIKE '%' || var_filter_val || '%') or
(var_filter_colum = 'TRKH_PNRMAN' AND TRKH_PNRMAN ILIKE '%' || var_filter_val || '%') or
(var_filter_colum = 'MAKLUMAT_PENERIMA' AND MAKLUMAT_PENERIMA ILIKE '%' || var_filter_val || '%') or
(var_filter_colum = 'NAMA_PENGGUNA' AND NAMA_PENGGUNA ILIKE '%' || var_filter_val || '%') or
(var_filter_colum = 'TUGASAN_PERIHAL' AND TUGASAN_PERIHAL ILIKE '%' || var_filter_val || '%') or
(var_filter_colum = 'FLAG' AND FLAG ILIKE '%' || var_filter_val || '%')

 ))
;
END;
$function$
;

-- DROP FUNCTION et_main_uat.urusan_kod(int4);

CREATE OR REPLACE FUNCTION et_main_uat.urusan_kod(id integer)
 RETURNS character varying
 LANGUAGE plpgsql
AS $function$
DECLARE
    n_kod VARCHAR(100);
BEGIN
    SELECT kod INTO n_kod FROM ind_ursn WHERE ursn_id = id;
    RETURN n_kod;

    EXCEPTION
        WHEN OTHERS THEN
            RETURN NULL;
END;
$function$
;

-- DROP FUNCTION et_main_uat.urusan_nama(int4);

CREATE OR REPLACE FUNCTION et_main_uat.urusan_nama(id integer)
 RETURNS character varying
 LANGUAGE plpgsql
AS $function$
DECLARE
    n_nama VARCHAR(100);
BEGIN
    SELECT nama INTO n_nama FROM ind_ursn WHERE ursn_id = id;
    RETURN n_nama;

    EXCEPTION
        WHEN OTHERS THEN
            RETURN NULL;
END;
$function$
;